INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (694, '宝山大通桥', '大通桥是一座单孔石拱桥。桥面中部(拱顶上)高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆，每侧有8根望柱，7段石栏板，端望柱与河岸上的石栏杆相连接。桥面宽4.50米，桥面长18.00米，全长40.00米。侧墙是用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长4.90米。拱碹是半圆形纵联分段并列式结构，由6道纵联石和7段拱碹石构成，碹脸外边有双线拱眉石，拱眉凸出于碹脸，拱眉与侧墙取平。跨径8.50米。碹脸上方两边的侧墙上各有一个勾头石，桥孔两边的侧墙上各有一根桥联柱，上顶有勾头石。', '', 9, NULL, NULL, '', 8, 1, 8, 1, '上海市宝山区车墩镇南门村，跨官绍塘上', '石材（料石）', 50, 51, '2026-04-28 23:07:53', '2026-04-28 23:36:16');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (695, '宝山三里桥', '桥塊和桥面上铺砌青石板，桥面中(拱顶上)高起为平面，两端是阶梯式坡道，两侧原有石栏杆，今已无存，桥面宽3.50米，桥长20.00米。侧墙用青石板砌筑。上顶有单层仰天石。桥台与石板砌筑的河岸为一体。拱碹是半圆形纵联分段并列式结构，无拱眉，跨径8.50米。', '', 9, NULL, NULL, '', 8, 1, 10, 1, '上海市宝山区车墩镇华阳街', '青石板', 50, 52, '2026-04-28 23:07:53', '2026-04-28 23:36:16');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (696, '登龙桥', '登龙桥是一座单孔石拱桥。桥面中部(拱顶上)为平面，两端是阶梯式坡道，南北两坡各有13级台阶，两侧有节间式石栏杆。桥面宽5.90米，桥长13.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形。拱碹是半圆形纵联分段并列式结构，拱眉凸出于碹脸，又凸出于侧墙。跨径5.70米，矢高3米。', '', 9, NULL, NULL, '', 10, 1, 10, 1, '上海市嘉定区练祁河上', '石材（料石）', 50, 53, '2026-04-28 23:07:53', '2026-04-28 23:36:16');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (697, '高义桥', '桥面中部(拱顶上)高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆，每侧有4根望柱，3块石栏板，两块抱鼓石。无地伏，桥栏杆置于仰天石上。桥面宽约4.00米，桥长26.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长4.00米。拱碹是半圆形纵联分段并列式结构，碹脸外边有拱眉石，拱眉凸出于碹脸，拱眉与侧墙取平。碹脸上方两边的侧墙上各有一个勾头石，桥孔两侧(桥台上)的侧墙上各有一根桥联柱，上顶有勾头石。东西两侧的桥柱上刻有对联，东侧的上联是“长虹彩射金沙塔”，下联是“半月潮连合浦门”；西侧的上联是“西城万户稻梁入”，下联是“东望千艘吉贝来”。', '', 9, NULL, NULL, '', 7, 1, 7, 1, '上海市嘉定区西门外，跨于街河上', '石材（料石）', 50, 54, '2026-04-28 23:07:53', '2026-04-28 23:36:16');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (698, '天恩桥', '桥面中部(中孔上)高起为平面，两端是阶梯式坡道。两侧有节间式石栏杆，每侧有望柱4根，栏板3段石栏板，两端各有一块抱鼓石。无地伏，桥栏杆置于单层仰天石上。桥面宽3.50米，桥长46.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，桥台下部前面和两侧皆有小出台，前墙长约3.50米。桥墩两端与拱脚齐平，桥墩厚85厘米，桥墩长3.50米。拱碹是半圆形纵联分段并列式结构，中孔拱碹由8道纵联石和9段拱碹石构成，边孔拱碹由6道纵联石和7段拱碹石构成，碹脸外边有拱眉石，拱眉凸出于碹脸，又凸出于侧墙。中孔跨径11.52米，边孔跨径5.50米。中孔碹脸上方两边的侧墙上各有一个勾头石，三孔之间(桥墩上)的侧墙上各有一根桥联柱，边孔外边的侧墙上各有一根桥联柱，上顶皆有勾头石。桥联柱上皆有对联。', '', 9, NULL, NULL, '', 7, 1, 10, 1, '上海市嘉定区南翔镇横沥河上', '石材（料石、石栏板、仰天石、拱碹石）', 50, 55, '2026-04-28 23:07:53', '2026-04-28 23:36:16');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (699, '寿带桥', '寿带桥是一座单孔石拱桥。桥面大致是平面，两侧有节间式石栏杆。桥面宽3.50米，桥长22.75米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长约3.50米。拱碹是半圆形纵联分段并列式结构，碹脸、拱眉与侧墙平。跨径7.50米。', '', 9, NULL, NULL, '', 10, 1, 10, 1, '上海市金山区', '石材（料石）', 50, 56, '2026-04-28 23:07:53', '2026-04-28 23:36:16');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (700, '蒲汇塘桥', '今存蒲汇塘桥是一座3孔石拱桥。桥面中部(中孔上)高起为平面，两端是阶梯式坡道，南北各有20级台阶，两侧有节间式石栏杆，每侧有8根望柱，7块石栏板，两块抱鼓石。无地伏，桥栏杆置于仰天石上。桥面宽5.45米，桥长29.00米。侧墙是用条形石板砌筑，上面有双层仰天石。桥台是凹字形，前墙长5.50米，端墙较长，前面和两侧下部皆有小出台。桥墩两端为方形，四周下部有出台，桥墩厚85厘米，桥墩长5.50米。拱碹是半圆形纵联分段并列式结构，中孔由6道纵联石和7段拱碹石构成，边孔由4道纵联石和5段拱碹石构成，碹脸外边皆有拱眉石，拱眉凸出于碹脸，拱眉稍凸出于侧墙。中孔跨径11.25米，边孔跨径6.50米。中孔拱碹上方两边的侧墙上各有一个勾头石。三孔拱碹之间(桥墩上)的侧墙上各有一根桥联柱，上端有勾头石。', '', 9, NULL, NULL, '', 8, 1, 10, 1, '上海市闵行区七宝镇', '石材', 50, 57, '2026-04-28 23:07:53', '2026-04-28 23:36:16');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (701, '普济桥', '桥面中部(中孔上)高起为平面，两端为阶梯式坡道，北端坡道26级踏步，南端坡道30级踏步。两侧有节间式石栏杆，每侧有望柱4根，栏板3段，两端各有一块抱鼓石。无地伏，桥栏杆置于仰天石上。桥面宽4.05米，桥梁全长38.69米。侧墙用条形石板砌筑，上面有单层仰天石组成的金边线。桥台是凹字形，前面和两侧下部有出台，前墙长4.10米。桥墩的两端与拱脚齐平，四周有出台，桥墩厚85厘米，桥墩长约4.00米。拱碹是纵联分段并列式结构，碹脸外边有拱眉石，拱眉凸出于碹脸，拱眉与侧墙取平。中孔跨径9.16米，矢高4.37米，南边孔跨径5.31米，矢高2.60米，北边孔跨径5.29米，矢高2.54米。各孔碹脸上部两边的侧墙上各有一个勾头石，两个桥墩上(各孔之间)和边孔的外边侧墙上各有一根桥联柱，柱顶上有勾头石。', '', 9, NULL, NULL, '', 10, 1, 10, 1, '上海市青浦区金泽镇', '石材（条形石板）', 50, 58, '2026-04-28 23:07:53', '2026-04-28 23:36:16');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (702, '如意桥', '如意桥是一座单孔石拱桥。桥面中部(拱顶上)高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆，无地伏，桥栏杆置于仰天石上。桥面宽3.40米，桥长20.80米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形。拱碹是半圆形纵联分段并列式结构，拱眉凸出于碹脸，又凸出于侧墙。跨径9.80米。碹脸上方两侧各有一个勾头石，桥孔两边的侧墙上有桥联柱，上顶有勾头石。', '', 9, NULL, NULL, '', 8, 1, 8, 1, '上海市青浦区金泽镇', '石材', 50, 59, '2026-04-28 23:07:53', '2026-04-28 23:36:16');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (703, '天王阁桥', '桥面中部(中孔上)高起为平面，两端是阶梯式坡道。两侧有节间式石栏杆，每侧有10根望柱，9块石栏板，两块抱鼓石。无地伏，桥栏杆置于仰天石上。桥面宽4.50米，桥长30.00米。侧墙用条形石板砌筑，上面有双层仰天石。桥台是凹字形，前墙长4.50米。端墙较长，前面和两侧下部皆有小出台。桥墩两端为方形，桥墩厚85厘米，桥墩长4.50米，四周下部有出台。拱碹是半圆形纵联分段并列式结构，中孔由6道纵联石和7段拱碹石构成，边孔由4道纵联石和5段拱碹石构成，碹脸外边皆有拱眉石，拱眉凸出于碹脸，拱眉稍凸出于侧墙。中孔跨径11.30米，边孔跨径5.50米。中孔拱碹上方两边的侧墙上各有一个勾头石。三孔拱碹之间(桥墩上)的侧墙上各有一根桥联柱，上端有勾头石。', '', 9, NULL, NULL, '', 8, 1, 8, 1, '上海市青浦区金泽镇', '石材', 50, 60, '2026-04-28 23:07:53', '2026-04-28 23:36:16');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (704, '万安桥', '桥面略显弧形，两侧有节间式石栏杆，桥面宽2.60米，桥长29米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长2.60米。拱碹是半圆形纵联分段并列式结构，碹脸外边有拱眉，拱眉凸出于碹脸，拱眉稍凸出于侧墙。跨径9.80米。', '', 9, NULL, NULL, '', 8, 2, 10, 1, '青浦区金泽镇', '石材', 50, 61, '2026-04-28 23:07:53', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (705, '紫石桥', '桥塊和桥面上铺砌紫色砂岩石板，桥面中部(拱碹上)是圆弧形，两端是较为平缓的阶梯式坡道，南段坡道是20级踏步，北段坡道是21级踏步。两侧有砖石桥栏杆，上面有石帽，无地伏，砖栏杆砌筑在仰天石上。桥面宽2.75米，桥长26.70米。侧墙用料石砌筑，上顶有双层仰天石，上层仰天石的外立面是平面，下层托石的外立面是圆弧形。桥台是凹字形，前面和两侧有出台，前墙长2.80米。拱碹是圆弧形分段并列式结构，碹脸外边有拱眉石，拱眉凸出于碹脸，拱眉与侧墙平。跨径10.50米。碹脸上部两边的侧墙上各有一个勾头石，勾头石的上面(仰天石下面)各有一个石雕龙头。', '', 9, NULL, NULL, '', 8, 1, 8, 1, '上海市青浦区金泽镇颐浩寺前', '紫色花岗石、紫色砂岩石板、砖石', 50, 62, '2026-04-28 23:07:53', '2026-04-28 23:36:16');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (706, '青浦放生桥', '桥面(中孔上)高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆，每侧有10根望柱，9段石栏板，两块抱鼓石。无地伏，桥栏杆置于仰天石上。桥面宽5.80米，桥梁全长70.80米。侧墙用料石砌筑，上面有单层仰天石组成的金边线，桥台为凹字形，前墙长5.80米。前面和两侧下部有出台，端墙的外端与石砌河岸连砌。桥墩上游端与拱脚齐平，下游端伸出较长，两侧和下游端有出台(宽出拱脚)，桥墩厚80厘米，桥墩长约7.80米。拱碹是半圆形纵联分段并列式结构，中三孔的拱碹由8道纵联石和9段拱碹石构成，次边孔由6道纵联石和7段拱碹石构成，边孔由4道纵联石和5段拱碹石构成，碹脸外边有双线拱眉石，拱眉凸出于碹脸，又凸出于侧墙。中孔跨径13.00米，次边孔跨径10.00米，边孔跨径7.00米。中孔碹脸上方两边的侧墙上各有一个勾头石，各孔碹脸之间(桥墩上)和边孔外边的侧墙上各有一根桥联柱，上顶有一勾头石。', '', 9, NULL, NULL, '', 8, 1, 7, 1, '上海市青浦区朱家角镇漕港河上', '石材（料石、仰天石、拱碹石等）', 50, 63, '2026-04-28 23:07:53', '2026-04-28 23:36:16');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (707, '泰安桥（何家桥）', '泰安桥是一座单孔石拱桥。桥堍在河岸上，两侧是建筑。桥面中部(拱顶上)高起为平面，两端是阶梯坡道。两侧有节间式石栏杆，每侧有6根望柱，5块石栏板(两面皆有雕刻花饰)，栏杆两段与民房连接。无地伏，桥栏杆置于仰天石上。桥面宽4.00米，净宽3.20米，桥长26.20米。侧墙用料石砌筑，上顶有单层仰天石。桥台的前墙与石砌河岸为一体。拱碹是半圆框形纵联式结构，碹脸外缘錾出拱眉线，拱眉与侧墙取平。跨径8.60米，矢高4.35米。', '', 9, NULL, NULL, '', 8, 1, 8, 1, '上海市青浦区朱家角镇圆津禅院门前', '石材（料石）', 50, 64, '2026-04-28 23:07:53', '2026-04-28 23:36:16');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (708, '松江大仓桥', '15. 松江大仓桥 大仓桥原名永丰桥，位于上海市松江区，跨松江市河上，南北走 向。明天启六年(1626年)建。 大仓桥是一座5孔薄拱薄墩轻型石拱桥。桥面中部(中孔上)高起 为平面，两端是很长的阶梯式坡道，两侧有节间式石栏杆，桥面宽5.00 米，净宽3.90米，桥长54.00米。 侧墙用料石砌筑，上面有单层仰天石组成的金边线。桥台为凹字 形，前墙长5.40米，端墙很长，其端部与石砌河岸相连接。桥墩两端 是方形，桥墩厚95厘米，桥墩长约5.40米。拱碹为纵联分段并列式结 构，碹脸外边有拱眉，拱眉凸出于碹脸，又凸出于侧墙。跨径数据 暂缺。 五孔碹脸上方两边的侧墙上各有一个勾头石，各孔拱碹之间(桥墩 上)和边孔外边的侧墙上各有一根桥联柱，上端有勾头石。', '', 9, NULL, NULL, '', 10, 1, 10, 1, '', NULL, 50, 65, '2026-04-28 23:07:53', '2026-04-28 23:07:53');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (709, '云间第一桥', '桥面中部(中孔拱顶上)为平面，两端是阶梯式坡道，两侧有节间式石栏杆。桥面宽4.50米，桥长41.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长约5.00米。桥墩两端是方形，桥墩厚95厘米，桥墩长5.00米。拱碹是半圆形纵联分段并列式结构，有拱眉。拱眉凸出于碹脸，又凸出于侧墙。中孔跨径12.00米，边孔跨径9.00米。', '', 9, NULL, NULL, '', 8, 1, 8, 1, '上海市松江区松江镇中山路，跨古浦塘上', '石材（料石）', 50, 66, '2026-04-28 23:07:53', '2026-04-28 23:36:16');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (710, '金山济渡桥', '济渡桥又名七星桥，桥北头立有“济渡桥”碑。桥面是花岗岩石板梁，每孔4块石板梁，无栏杆。桥面宽4.00米，桥长43.60米。桥台的前墙是用5块条形石板并排竖立在石板基台上，上顶有石板盖梁，后面有凹字形构造。桥墩的构造形式和桥台的前墙相同。中孔跨径7.00米，边孔跨径6.00米。', '', 9, NULL, NULL, '', 8, 2, 8, 1, '金山区漕泾镇', '花岗岩石板', 50, 67, '2026-04-28 23:07:53', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (711, '迎祥桥', '迎祥桥是一座5孔石板梁桥。桥面每孔5块石板梁，无栏杆，桥面宽2.41米，桥长34.25米。桥台是凹字形，前墙是4根方形石柱，上顶横架一根石帽梁。桥墩是4根或5根方形石柱，上顶横架一根石帽梁。跨径6.00米。', '', 9, NULL, NULL, '', 6, 2, 6, 1, '青浦区金泽镇', '石材', 50, 68, '2026-04-28 23:07:53', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (712, '望仙桥', '望仙桥是一座双孔石板梁桥。桥面每孔4块花岗岩石板梁，无栏杆，桥面宽2.75米，桥面长10.00米，全长16.00米。桥台是凹字形，前墙长3.30米。桥墩两端是方形，桥墩厚80厘米，桥墩长4.30米。跨径4.60米。', '', 9, NULL, NULL, '', 10, 2, 10, 1, '上海市松江区方塔园内', '花岗岩', 50, 69, '2026-04-28 23:07:53', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (713, '青龙桥', '今存青龙桥是一座3孔石拱桥。桥面中部(中孔上)高起为平面，两端(边孔上和桥塊上)为坡面。桥上无栏杆，两侧各有一道边牙石。桥面宽7.65米，净宽6.66米，桥长56.50米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长7.65米。桥墩上游端是尖形，下游端是方形，拱碹均为圆弧形纵联石结构，有拱眉，碹脸，拱眉与侧墙取平。中孔跨径11.70米，边孔跨径9.30米。', '', 25, NULL, NULL, '', 8, 1, 8, 1, '楚雄彝族自治州楚雄市', '料石', 50, 51, '2026-04-28 23:07:53', '2026-04-28 23:36:16');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (714, '禄丰星宿桥', '星宿桥是一座7孔石拱桥。桥塊和桥面上铺砌条形石板，全桥为平面，两侧有节间式石栏杆，桥面宽9.80米，桥面长96.50米，全长119.99米。侧墙用红砂岩石板砌筑，上顶有双层仰天石。桥台是燕翅形。桥墩两端是尖形，桥墩厚4.30米，桥墩长18.00米。拱碹是半圆形纵联式结构，龙门上有石雕龙头，碹脸外边有拱眉，拱眉凸出于碹脸，凸出于侧墙。跨径均为11.30米。', '', 25, NULL, NULL, '', 8, 1, 8, 1, '楚雄彝族自治州禄丰县西门外，跨禄衣河(又称星宿江)上', '条形石板、红砂岩石板', 50, 52, '2026-04-28 23:07:53', '2026-04-28 23:36:16');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (715, '南华灵官桥（瑞应桥）', '灵官桥是一座3孔石拱桥。在两个桥墩上各有一个小孔洞。桥面呈弧形，无栏杆，桥面宽7.00米，桥长51.50米。侧墙用料石砌筑，上顶有单层仰天石。桥台是燕翅形，前墙长8.20米。桥墩两端是尖形，拱碹是半圆形纵联式结构，碹脸外边有拱眉，拱眉与侧墙平。中孔跨径8.80米，边孔跨径8.50米。', '', 25, NULL, NULL, '', 7, 1, 7, 1, '楚雄彝族自治州南华县灵官村', '料石', 50, 53, '2026-04-28 23:07:53', '2026-04-28 23:36:16');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (716, '南薰桥', '桥面为平面，桥面全宽5.20米，净宽4.00米，桥长17.00米。桥上建砖木阁和亭。侧墙用块石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长5.50米。拱碹是半圆形纵联式结构，碹脸龙门上有龙头，碹脸外有拱眉石，拱眉凸出于碹脸，拱眉与侧墙取平。跨径11.00米。', '', 25, NULL, NULL, '', 8, 1, 8, 1, '大理白族自治州宾川县钟良溪上', '石材、木材、砖', 50, 54, '2026-04-28 23:07:53', '2026-04-28 23:36:16');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (717, '剑川玉津桥', '玉津桥是一座单孔石拱桥。桥塊和桥面上铺砌条形石板，桥面呈圆弧形，两侧有节间式石栏杆，栏杆端部各有一只石雕“娃娃鱼”。桥面宽5.00米，桥长35.40米。侧墙用料石砌筑。上顶有单层仰天石。桥台是燕翅形。拱碹是半圆形纵联式结构，上游龙门上有石雕鳌头，下游龙门上有石雕鳌尾，无拱眉。跨径12.00米。', '', 25, NULL, NULL, '', 8, 1, 8, 1, '大理白族自治州剑川县沙溪镇', '条形石板、料石', 50, 55, '2026-04-28 23:07:53', '2026-04-28 23:36:16');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (718, '大理观音寺桥', '观音寺桥是一座单孔石梁桥和两个单孔石拱桥连接而成的3孔石桥。石梁桥居中，两端各一孔石拱桥，统称观音寺桥。桥上建一座二层楼阁。石梁桥的桥面宽3.00米，桥面长8.00米。石梁桥的桥墩两端是方形，桥墩长3.00米。石拱桥的桥面宽3.00米，桥长均为8.00米。桥台是凹字形，前墙长4.00米。', '', 25, NULL, NULL, '', 8, 1, 8, 1, '大理白族自治州大理市观音寺院内，跨于水塘上', '石材', 50, 56, '2026-04-28 23:07:53', '2026-04-28 23:36:16');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (719, '见龙桥', '今存见龙桥是一座5孔石拱桥。由一座3孔主桥和两座单孔辅桥组成，主桥的桥面呈穹隆形，两侧有节间式石栏杆。桥面宽均为4.80米，桥长48.00米。桥面中部建桥亭。侧墙用条形石板砌筑，上顶有单层仰天石组成的金边线。桥台又是桥墩，拱碹是三心圆弧形纵联式结构，碹脸外边有拱眉，拱眉与侧墙平。中孔跨径6.35米，次边孔跨径5.80米，边孔的跨径是5.20米。南桥台是燕翅形，北桥台是凹字形。南端第一桥墩(利用原桥台改建而成)又厚又大，两端为尖形，其余二桥墩两端均为尖形。辅桥外端各有一段引道(石堤),南北引道总长67.00米，全桥总长(包括引道)115.00米。', '', 25, NULL, NULL, '', 8, 1, 8, 1, '红河哈尼族彝族自治州建水县西庄镇，跨泸江上', '石材（条形石板、仰天石）', 50, 57, '2026-04-28 23:07:53', '2026-04-28 23:36:16');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (720, '建水双龙桥', '今存双龙桥是一座17孔石拱桥。中间有楼阁及其台座，台座东西长20.00米，南北宽15.00米。台座下面有一个大桥孔，拱碹是半圆形纵联分段并列式结构，碹脸外边有拱眉石，拱眉凸出于碹脸，拱眉与侧墙平。楼阁台座将全桥分为两段，楼阁以西有6孔，楼阁以东有10孔，东西两段桥的结构与形式相同，桥堍和桥面上铺砌青石板，全桥是平面，两侧有青石砌成的宇墙式栏杆。桥面宽均为3.50米，西段桥长48.00米，东段桥长80.00米，台座长20.00米，桥梁全长148.00米。侧墙用料石砌筑，上顶有双层仰天石。西桥台是燕翅形，前墙长约3.50米。东桥台是凹字形，前墙长3.50米。桥墩上游端均为尖形，下游端均为方形，拱碹均系半圆形纵联式结构，碹脸外边有拱眉石，拱眉凸出于碹脸，拱眉与侧墙平。跨径6.50米。', '', 25, NULL, NULL, '', 8, 1, 8, 1, '红河哈尼族彝族自治州建水县张家营村，跨泸江河与榻冲河之交汇处', '青石板、料石', 50, 58, '2026-04-28 23:07:53', '2026-04-28 23:36:16');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (721, '天缘桥', '天缘桥是一座3孔石拱桥。桥塊和桥面上铺砌条形石板为平面，两侧有宇墙式石栏杆，无地伏，桥栏杆置于仰天石上。南端有一对石狮子，北端有一对石象。桥面宽7.20米，桥长43.00米。中孔上建一座重檐八角攒尖顶亭阁。桥梁两端各有一段用石板铺砌的引道，引道分别向东西弯曲，全桥形成 “S” 形。桥梁全长(包括引道)121.00米。侧墙用料石砌筑，上顶有双层仰天石。桥台是带燕翅形。桥墩上游端是尖形，下游端是方形，拱碹是半圆框形纵联式结构，无拱眉，碹脸后退于侧墙。跨径均为17.30米。', '', 25, NULL, NULL, '', 8, 1, 8, 1, '红河哈尼族彝族自治州建水县城东十里，跨泸江河上', '条形石板、料石', 50, 59, '2026-04-28 23:07:53', '2026-04-28 23:36:16');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (722, '德泽桥', '德泽桥是一座6孔石拱桥。桥面大致为平面，无栏杆，桥面宽7.00 米，桥长110.00米。 侧墙用料石砌筑，上顶有单层仰天石。桥台是燕翅形。桥墩两端是 尖形，桥墩厚2.50米，桥墩长9.70米。拱碹是圆弧形分段并列式结 构，碹脸外边有拱眉，拱眉凸出于碹脸，拱眉与侧墙平。跨径均为 18.50米。', '', 25, NULL, NULL, '', 8, 1, 8, 1, '曲靖市沾益县，跨牛栏江上', '料石', 50, 60, '2026-04-28 23:07:53', '2026-04-28 23:36:16');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (723, '沾益九龙桥', '九龙桥是一座9孔石拱桥。桥塊和桥面上铺砌条形石板，全桥桥面略显弧形，两侧有石板栏杆。桥面宽6.50米，桥长80.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是燕翅形。桥墩上游端是尖形，下游端是方形，桥墩厚2.20米，桥墩长8.60米。拱碹是半圆形纵联式结构，无拱眉。中孔跨径12.00米，其跨径分别为8.00米、9.00米、10.00米、11.00米、11.00米、10.00米、9.00米、8.00米。', '', 25, NULL, NULL, '', 8, 1, 8, 1, '曲靖市沾益县', '条形石板、料石', 50, 61, '2026-04-28 23:07:53', '2026-04-28 23:36:16');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (724, '廊坊桥', '廊坊桥是一座7孔等跨径石拱桥。桥面上铺砌条形石板，两侧有石板栏杆。桥面宽6.00米，桥长95.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是燕翅形，前墙长6.60米。桥墩两端是尖形，拱碹是半圆形纵联式结构，无拱眉，跨径均为10.40米。', '', 25, NULL, NULL, '', 8, 1, 8, 1, '曲靖市沾益县德泽乡', '条形石板、料石', 50, 62, '2026-04-28 23:07:53', '2026-04-28 23:36:16');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (725, '沾益太平桥', '太平桥是一座3孔石拱桥。两侧有节间式石栏杆。桥面宽6.00米，桥梁全长40.00米。侧墙用块石砌筑，上顶有单层仰天石。桥台是燕翅形，前墙长7.00米。桥墩两端是尖形，桥墩厚1.85米，桥墩长8.60米。拱碹是半圆形纵联式结构，有拱眉，拱眉凸出于碹脸，又凸出于侧墙。中孔跨径7.00米，边孔跨径6.20米。', '', 25, NULL, NULL, '', 7, 1, 7, 1, '曲靖市沾益县东门外，跨于南盘江上', '石材', 50, 63, '2026-04-28 23:07:53', '2026-04-28 23:36:16');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (726, '田房桥', '田房桥是一座3孔等跨径石拱桥。全桥桥面为平面，两侧有石栏杆。桥面宽3.50米，桥长33.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台建在山脚岩石上。桥墩两端是方形。拱碹是半圆形纵联式结构，无拱眉。跨径6.00米。', '', 25, NULL, NULL, '', 10, 1, 10, 1, '文山壮族苗族自治州广南县八宝镇田房村，跨山涧水沟上', '石材（料石）', 50, 64, '2026-04-28 23:07:53', '2026-04-28 23:36:16');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (727, '金锁桥', '金锁桥是一座单孔石拱桥。桥面宽8.00米，桥长31.00米。侧墙用块石砌筑，上顶有单层仰天石。桥台是燕翅形，前墙长9.00米。拱碹是三心圆弧形纵联式结构，碹脸外无拱眉，碹脸与侧墙取平。跨径17.00米。', '', 25, NULL, NULL, '', 8, 1, 8, 1, '玉溪市华宁县洗澡塘河上', '块石', 50, 65, '2026-04-28 23:07:53', '2026-04-28 23:36:16');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (728, '丽江黑龙潭桥', '今存黑龙潭桥是一座5孔石拱桥。桥塊和桥面上铺砌青石板，桥面呈穹隆形，两侧有节间式石栏杆，每侧有望柱20根，栏板19块，抱鼓石两块。桥面宽6.50米，桥长46.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，端墙外有八字石砌墙。桥墩两端是圆形，拱碹是半圆形纵联式结构，有拱眉，拱眉凸出于碹脸，拱眉与侧墙平。跨径均为7.60米。', '', 25, NULL, NULL, '', 10, 1, 10, 1, '丽江市', '青石板（桥塊和桥面）、料石（侧墙）', 50, 66, '2026-04-28 23:07:53', '2026-04-28 23:36:16');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (729, '大理观音堂桥', '观音堂桥是一座3孔石墩台悬臂式木梁桥。上部结构，桥面是25根圆木纵梁，纵梁两端下面各有3层圆木悬臂梁，悬臂梁之间疏铺方木横梁。纵梁上面横顺铺双层木桥面板。桥面宽12.00米，桥长19.40米。桥上建木结构廊。桥台是凹字形，端墙后部有燕翅墙，用条形石板砌筑，前墙长13.20米，端墙长4.00米。桥墩是用条形石板砌筑，桥墩两端是尖形，桥墩厚1.50米，桥墩长13.50米。跨径均为3.50米。', '', 25, NULL, NULL, '', 8, 2, 8, 1, '大理白族自治州大理市，在观音寺桥南', '圆木、方木、条形石板', 50, 67, '2026-04-28 23:07:53', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (730, '云龙彩凤桥', '桥面宽4.70米，桥长33.30米。桥上建木结构廊。桥台建在山脚岩石上，形状不规则。跨径27.00米。', '', 25, NULL, NULL, '', 8, 2, 8, 1, '大理白族自治州云龙县白石乡顺荡村，跨批江上', '木', 50, 68, '2026-04-28 23:07:53', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (731, '云龙通京桥', '通京桥是一座单跨石墩台撑架式木梁桥。上部结构的上面有6道圆木纵梁，纵梁的底面挂有5根圆木横梁。横梁的下面有6根圆木辅梁，辅梁的两端各与一对圆木斜撑对接，斜撑木的下端落在经过加工的基岩上。桥面宽4.00米，桥长40.00米。净跨径29.00米。桥上建木结构廊。', '', 25, NULL, NULL, '', 8, 2, 8, 1, '云南省大理白族自治州云龙县长新乡包罗村，跨于澜沧江支流批江上', '石、圆木', 50, 69, '2026-04-28 23:07:53', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (732, '永胜金龙桥', '上部结构是9道圆木纵梁，上面铺木桥面板。桥面宽4.50米，桥长49.00米。桥上建木结构廊。每道纵梁下面中部各挂1根圆木辅梁，辅梁两端各挂1根圆木横梁，在横梁的外侧各有9根圆木斜撑，斜撑的下端置于山脚岩石上。跨径27.00米。', '', 25, NULL, NULL, '', 10, 2, 10, 1, '丽江市永胜县金沙江龙开口电站上游', '木材（圆木纵梁、木桥面板、木结构廊、圆木辅梁、圆木横梁、圆木斜撑）', 50, 70, '2026-04-28 23:07:53', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (733, '凤庆青龙桥', '青龙桥是一座单孔撑架式木梁桥。桥面宽4.50米，桥长25.00米。跨径21.00米。', '', 25, NULL, NULL, '', 8, 2, 8, 1, '临沧市凤庆县城东北，跨丽江上', '木', 50, 71, '2026-04-28 23:07:53', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (734, '永定桥', '永定桥原名“天虹桥”。上部结构是每孔15根圆木纵梁，上面铺双层木桥面板，桥面宽7.35米，桥梁全长74.00米。桥上建砖木结构廊。桥台是凹字形，用石板砌筑。桥墩也是用石板砌筑，两端是方形，桥墩厚1.25米，桥墩长8.50米。跨径6.00—6.50米。', '', 25, NULL, NULL, '', 7, 2, 7, 1, '凉山彝族自治州会理县', '石板（桥台、桥墩）、圆木（纵梁）、木（桥面板）、砖木（廊）', 50, 72, '2026-04-28 23:07:53', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (735, '赤峰普渡桥', '普渡桥是一座3孔石拱桥。桥面是弧形，无栏杆，桥面宽数据暂缺，桥长69.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是燕翅形。桥墩上游端是尖形，下游端是方形，桥墩厚1.40米，桥墩长9.65米。拱碹是半圆形纵联式结构，无拱眉。中孔跨径16.00米，西边孔跨径6.00米，东边孔跨径9.00米。', '', 5, NULL, NULL, '', 8, 1, 8, 1, '赤峰市克什克腾旗，跨西拉木伦河上', '料石', 50, 51, '2026-04-28 23:07:53', '2026-04-28 23:36:16');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (736, '安顺桥', '安顺桥是一座3孔石拱桥。桥塊和桥面上铺砌青石板，桥面中部高起为平面，边孔上桥面较低，也是平面，两段平桥面之间有阶梯连接。桥面宽6.00米，桥长81.00米。桥上建双层楼阁式长廊。侧墙用料石砌筑，上顶有双层仰天石。桥台是燕翅形。桥墩两端是尖形，桥墩上各有一个小孔洞。拱碹是圆弧形，无拱眉。中孔跨径20.00米，边孔跨径15.00米。', '', 23, NULL, NULL, '', 8, 1, 8, 1, '成都市府河与南河交汇处', '青石板、料石', 50, 51, '2026-04-28 23:07:53', '2026-04-28 23:36:16');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (737, '九眼桥', '九眼桥原名“宏济桥”，又名“镇江桥”。桥面略显弧形，两侧有石栏杆，桥面宽7.20米，桥长120.00米，侧墙是用料石砌筑，上顶有单层仰天石。桥台是燕翅形，桥墩两端是尖形，跨径由北向南依次是6.50米、7.30米、8.00米、8.75米、9.40米、8.75米、8.00米、7.25米、6.55米。1988年在九眼桥西侧新建一座混凝土大桥，1992年将九眼桥拆除。', '', 23, NULL, NULL, '', 8, 1, 8, 1, '成都市锦江区跨锦江上', '石材、料石', 50, 52, '2026-04-28 23:07:53', '2026-04-28 23:36:16');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (738, '毗河桥', '全桥是平面，两侧有石栏杆，桥面宽 8.40米，桥长91.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是燕翅形，前墙长9.00 米。桥墩上游端是尖形，下游端是方形，拱碹是半圆形纵联式结构，有拱眉，碹脸、拱眉与侧墙平。跨径均为9.00米。', '', 23, NULL, NULL, '', 8, 1, 8, 1, '成都市新都区，跨毗河上', '料石', 50, 53, '2026-04-28 23:07:53', '2026-04-28 23:36:16');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (739, '成都七里桥', '桥面大致为平面。桥面宽10.50米，桥长112.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是燕翅形。桥墩上游端是尖形，下游端是方形，桥墩厚1.45米，桥墩长13.00米。拱碹是半圆形纵联式结构，有拱眉，碹脸、拱眉与侧墙平。跨径均为15.00米。', '', 23, NULL, NULL, '', 8, 1, 8, 1, '成都市', '料石', 50, 54, '2026-04-28 23:07:53', '2026-04-28 23:36:16');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (740, '万里桥（俗称“老南门大桥”）', '桥面宽15.00米，桥长85.00米。侧墙用条形石板砌筑，上顶有双层仰天石。桥台是燕翅形。桥墩两端是尖形，桥墩厚2.00米，桥墩长17.50米。拱碹是半圆形纵联式结构，无拱眉。跨径均为8.50米。1988年维修期间在河床中发现秦汉时期的砖砌和石砌构筑物，石板上有成排的圆孔及数排木桩。', '', 23, NULL, NULL, '', 8, 1, 8, 1, '四川省成都市老城南门外跨锦江上', '青石板（桥堍和桥面）、条形石板（侧墙）、砖、木（秦汉时期）', 50, 55, '2026-04-28 23:07:53', '2026-04-28 23:36:16');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (741, '望仙桥', '望仙桥原是一座5孔石拱桥。桥塊和桥面上铺砌青石板，两侧有节间式石栏杆。桥面宽20.00米，桥长110.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是燕翅形，桥墩两端是尖形，桥墩厚1.30米，桥墩长22.90米。拱碹是半圆形纵联式结构，碹脸外边有拱眉，拱眉凸出于碹脸，拱眉与侧墙平。跨径均为19.50米。', '', 23, NULL, NULL, '', 8, 1, 8, 1, '成都市青羊横街，跨清水河上', '青石板、料石', 50, 56, '2026-04-28 23:07:53', '2026-04-28 23:36:16');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (742, '崇州永利桥', '永利桥是一座3孔砖石拱桥。桥面为穹隆形，两侧有节间式石栏杆，桥面宽7.50米，桥长44.10米。侧墙用料石砌筑，上顶有单层仰天石。桥台是燕翅形，桥墩两端是尖形，中孔拱碹是卵形纵联式结构，边孔拱碹是半圆形纵联式结构，无拱眉。中孔跨径15.00米，边孔跨径13.60米。', '', 23, NULL, NULL, '', 8, 1, 10, 1, '崇州市元通镇', '砖材、石材（料石）', 50, 57, '2026-04-28 23:07:53', '2026-04-28 23:36:16');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (743, '德昌大高桥', '大高桥是一座单孔石拱桥。桥塊和桥面上铺砌不规则石板，两侧有石栏杆，宽4.00米，桥长14.40米。侧墙用料石砌筑，上顶有单层仰天石。桥台是燕翅形，前墙长约5.00米。拱碹是半圆形纵联式结构，无拱眉。跨径3.00米。', '', 23, NULL, NULL, '', 8, 1, 8, 1, '凉山彝族自治州德昌县', '石板、料石', 50, 58, '2026-04-28 23:07:53', '2026-04-28 23:36:16');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (744, '德昌会仙桥', '会仙桥是一座单孔石拱桥。桥塊和桥面上铺砌不规则石板，无栏杆，桥面宽4.50米，桥长10.80米。侧墙用料石砌筑，上顶有单层仰天石。桥台是燕翅形，前墙长约5.50米。拱碹是半圆形纵联式结构，无拱眉。跨径8.00米。', '', 23, NULL, NULL, '', 8, 1, 8, 1, '凉山彝族自治州德昌县', '石板、料石', 50, 59, '2026-04-28 23:07:53', '2026-04-28 23:36:16');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (745, '观音桥', '观音桥是一座单孔石拱桥。无栏杆，桥面宽3.45米，桥长 22.74米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长3.50米。拱碹半圆形纵联式结构，无拱眉。跨径4.45米。', '', 23, NULL, NULL, '', 8, 1, 8, 1, '泸州市泸县毗卢镇白鹤村，跨于马溪河上', '料石', 50, 60, '2026-04-28 23:07:53', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (746, '福寿桥', '福寿桥是一座3孔石拱桥。桥塊和桥面上铺砌石板，两侧有石板栏杆，栏板厚30厘米，栏板高82厘米。桥面宽5.80米，桥长41.90米。侧墙用料石砌筑，上顶有双层仰天石。桥台是燕翅形，前墙长约7.00米。桥墩下部是船形，上部构造较薄，厚约60厘米，桥墩长8.40米，桥墩外端上有石雕龙头。拱碹是半圆形纵联式结构，碹脸外边有拱眉石，拱眉凸出于碹脸，拱眉与侧墙平。跨径11.50米。', '', 23, NULL, NULL, '', 10, 1, 10, 1, '泸州市泸县百和镇高洞社区，跨大鹿溪上', '石材（料石、石板）', 50, 61, '2026-04-28 23:07:53', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (747, '黄泥沱小桥', '黄泥沱小桥是一座单孔石拱桥。桥面微呈弧形，无栏杆。桥面宽 2.65米，桥长12.4米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长约 3.00米。拱碹是半圆形纵联式结构，龙门上有石雕龙头，碹脸外边有拱眉，拱眉凸出于碹脸，拱眉与侧墙平。拱跨4.80米。', '', 23, NULL, NULL, '', 8, 1, 8, 1, '泸州市泸县福集镇赵岩村，跨无名溪上', '料石', 50, 62, '2026-04-28 23:07:53', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (748, '泸县惠济桥', '今存惠济桥是一座9孔等跨径石拱桥。桥塊和桥面铺砌条形石板，两侧有石砌“品”字形花饰栏杆。桥面宽7.90米，桥长105.60米。侧墙用料石砌筑，上顶有双层仰天石。桥台是凹字形，前墙长9.00米，桥墩两端是方形，桥墩厚1.25米，桥墩长9.00米。拱碹是半圆形纵联式结构，碹脸外边有拱眉石，拱眉凸出于碹脸，拱眉与侧墙平。跨径均约为10.00米。', '', 23, NULL, NULL, '', 8, 1, 7, 1, '泸州市泸县福集镇跨濑溪河上', '条形石板、料石', 50, 63, '2026-04-28 23:07:53', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (749, '泸县水笛滩大桥', '今存水笛滩大桥是一座14孔等跨径石拱桥。桥面是平面，两侧有石栏杆和地伏石。桥面宽5.70米，桥梁全长36.40米。侧墙用料石砌筑，上顶有单层仰天石组成的金边线。桥台是凹字形，前墙长6.00米。桥墩两端是方形，拱碹是半圆形纵联式结构，无拱眉，第五孔和第八孔龙门上有石雕龙头，碹脸与侧墙平。跨径6.50米。2001年维修，改为水泥桥面，桥面宽5.70米，桥面长36.40米。', '', 23, NULL, NULL, '', 10, 1, 10, 1, '泸州市泸县云龙镇战旗村与石洞顺江村交界处，跨龙溪河上', '石材（料石、仰天石、地伏石）、水泥（2001年维修后桥面）', 50, 64, '2026-04-28 23:07:53', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (750, '王家桥', '王家桥是一座单孔石拱桥。桥塊和桥面上铺砌条形石板，两侧有矮式石板栏杆，桥面宽4.30米，桥长35.55米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长5.00米。拱碹是半圆形纵联式结构，上游面龙门上有石雕龙头，下游面龙门上有石雕龙尾。拱眉凸出于碹脸，拱眉与侧墙平，跨径7.20米。', '', 23, NULL, NULL, '', 8, 1, 10, 1, '泸州市泸县喻寺镇赵南村，跨濑溪河大湾河段支流上', '石材（条形石板、料石）', 50, 65, '2026-04-28 23:07:53', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (751, '永济桥', '永济桥是一座3孔石拱桥。桥面上铺砌条形石板，无栏杆。桥面宽4.25米，桥长18.8米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长4.30米，端墙外有燕翅墙。桥墩的两端是八字形，桥墩厚1.10米，桥墩长6.05米。拱碹是半圆形纵联式结构，碹脸外边有拱眉石，拱眉凸出于碹脸，碹脸与侧墙平。跨径均为6.00米。', '', 23, NULL, NULL, '', 8, 1, 8, 1, '泸州市泸县兆雅镇永和村，跨于永济溪上', '条形石板、料石', 50, 66, '2026-04-28 23:07:53', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (752, '永嘉桥', '永嘉桥是一座5孔石拱桥。桥塊和桥面上铺砌条形石板，两侧有条石护栏，护栏高0.8米，宽0.4米。桥面宽7.13米，桥长50.12米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长约8.00米，端墙外有燕翅墙。桥墩的两端是八字形，桥墩1.10米，桥墩长8.90米。拱碹是半圆形纵联式结构，龙门上有石雕龙头，碹脸外边有拱眉石，拱眉凸出于碹脸，拱眉与侧墙平。跨径均为6.60米。', '', 23, NULL, NULL, '', 8, 1, 2, 1, '泸州市泸县嘉明镇秀水社区，跨于九曲河上', '石材（条形石板、条石、料石）', 50, 67, '2026-04-28 23:07:53', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (753, '泸县皂角滩桥', '皂角滩桥是一座5孔石拱桥。桥面两侧有石板栏杆，桥面宽5.30米，桥长约56.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是燕翅形，前墙长约6.00米。桥墩两端是尖形，拱碹是半圆形纵联式结构，上游面龙门上原有大小龙头各一，如今只在第一孔龙门尚存一小龙头，碹脸外边有拱眉，拱眉凸出于碹脸，拱眉与侧墙平。跨径有大有小，2.70—11.20米。', '', 23, NULL, NULL, '', 8, 1, 10, 1, '泸州市泸县百和镇楼方嘴村，跨大鹿溪上', '石材（料石、石板）', 50, 68, '2026-04-28 23:07:53', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (754, '太平桥', '太平桥是一座单孔石拱桥。桥面高出两岸很多，桥面顶部为弧形，两端是阶梯式坡道，两侧有节间式石栏杆。桥面宽7.50米，桥长52.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，端墙的后部与石砌河岸相连。拱碹是半圆形纵联式结构，碹脸外边有拱眉，拱眉凸出于碹脸，又凸出于侧墙。跨径32.00米。', '', 23, NULL, NULL, '', 10, 2, 10, 1, '泸州市泸县喻寺镇古桥村', '石材', 50, 69, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (755, '天仙桥', '天仙桥是一座9孔石拱桥。桥面大致为平面。侧墙用料石砌筑，上顶有单层仰天石。桥台是燕翅形。桥墩上游端是尖形，下游端是方形。拱碹是半圆形纵联式结构，有拱眉，碹脸、拱眉与侧墙平。跨径数据暂缺。', '', 23, NULL, NULL, '', 10, 1, 10, 1, '绵阳市梓潼县', '石材（料石）', 50, 70, '2026-04-28 23:07:53', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (756, '达州彩虹桥', '彩虹桥原名“高拱桥”，清同治七年(1868年)建，命名“万元桥”。石桥立面呈单驼峰式，桥面的顶面是微弧形面，两侧有平直石板栏杆，长6.00米，净宽9.00米。两端是阶梯式弧形坡面，各有76级台阶，两侧有石板栏杆。桥面全宽10.30米，净宽9.00米，桥长45.00米。侧墙用条形石板砌筑，上顶有单层仰天石。桥台是在山脚下岩石上开凿成平台。拱碹是半圆形分段并列式结构，碹脸外边有拱眉，拱眉凸出于碹脸，拱眉与侧墙平。跨径37.60米。', '', 23, NULL, NULL, '', 8, 1, 10, 1, '四川省达州市达川区大风乡，跨明月江上', '石材（条形石板）', 50, 71, '2026-04-28 23:07:53', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (757, '广安平桥', '平桥是一座5孔等跨径石拱桥。桥面两侧有石栏杆，栏杆两端各有一只石狮子。桥面宽6.60米，桥长76.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是燕翅形，桥墩两端是尖形，拱碹是半圆形纵联式结构，有拱眉，跨径8.60米。', '', 23, NULL, NULL, '', 8, 1, 8, 1, '广安市，跨于西溪河汇入渠江入口处', '料石', 50, 72, '2026-04-28 23:07:53', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (758, '广安五福桥', '五福桥又名“板桥”。原系石墩台木梁桥，桥上有廊。清嘉庆十一年改建为石拱桥，宽三丈，长六丈。两侧有石栏杆，栏板上刻五个“福”字。现为一座5孔等跨径石拱桥。桥堍和桥面上铺砌条形石板，两侧有节间式石栏杆，栏杆两端有石狮子。桥面宽7.50米，桥长79.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是燕翅形，桥墩两端是尖形，拱碹是半圆形纵联式结构，有拱眉，拱眉凸出于碹脸，拱眉与侧墙平。跨径9.80米。', '', 23, NULL, NULL, '', 8, 1, 10, 1, '广安市罗渡溪上', '石材（条形石板、料石）', 50, 73, '2026-04-28 23:07:53', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (759, '广安中桥', '中桥是一座5孔石拱桥。桥面大致为平面，两侧有节间式石栏杆，北面栏板上刻“致中桥”,南面栏板上刻“皇图巩固”。桥面宽8.20米，桥长88.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是燕翅形。桥墩两端是尖形，拱碹是半圆形纵联式结构，无拱眉，跨径11.00米。', '', 23, NULL, NULL, '', 8, 1, 8, 1, '广安市', '料石', 50, 74, '2026-04-28 23:07:53', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (760, '西溪桥', '其总平面图形呈“乙”字形，全桥大致分为三段，桥面每孔5—6块石板梁，无栏杆，桥面宽4.50—5.30米，桥长122.00米。桥台是凹字形，桥墩两端是方形，跨径3.20—5.00米。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '成都市广安区', '石板', 50, 75, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (761, '板栗树桥', '板栗树桥是一座10孔石板梁桥，桥面每孔两块石板梁，桥石板厚0.33米，桥面宽1.04米，桥长28.70米。无桥台，边孔石板梁搭在山脚岩石上。桥墩由单条石垒砌，两端是八字形，桥墩厚0.40米，桥墩长2.00米。跨径2.87米。桥墩上现存3尊龙形圆雕，雕刻手法细腻，形态栩栩如生。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县百和镇楼方嘴村，跨无名溪上', '石材', 50, 76, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (762, '对夹滩桥', '对夹滩桥是一座8孔石板梁桥。桥面每孔2块石板梁，石板厚0.37米，桥面宽1.75米，桥长24.30米。桥台是燕翅形，桥墩由单条石垒砌。跨径3.01米。由东南向西北第三、第六孔有龙首圆雕，龇嘴状，其雕刻手法简洁粗犷。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县百和镇东岳村，跨于鹿溪河对夹滩河段', '石材', 50, 77, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (763, '福水桥', '福水桥是一座3孔石板梁桥。桥面每孔2块石板梁，桥面宽1.08米，桥长7.01米。桥台是燕翅形，北台前墙长1.98米，南台前墙长2.90米。桥墩厚0.35米，北墩长2.28米，南墩长2.41米。跨径(北—南)2.31米、2.37米、2.33米。两桥墩上各有龙形圆雕一尊，共两尊。龙口微张，龙尾呈弧状圆台形，其雕刻手法简约生动。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县百和镇朱巷村，跨于福水溪上', '石材', 50, 78, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (764, '泸县观音桥', '观音桥是一座4孔石板梁桥，桥面每孔2块石板梁(石板厚0.36 米),桥面宽1.03米，桥长7.79米。 桥台是燕翅形，前墙长无标注。桥墩厚0.38米，北墩长2.03米， 中墩长2.34米，南墩长2.35米。跨径(北—南)1.98米、1.98米、 1.97米、1.86米。 三桥墩上各有龙形圆雕一尊，共三尊，保存完整。龙首直口龇牙， 露舌，龙尾呈圆台状。雕刻线条流畅，形象生动。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县嘉明镇狮子村，跨无名溪上', '石材', 50, 79, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (765, '两河口桥', '两河口桥原是一座3孔石板梁桥。石板梁厚0.28米，桥面宽1.14米，桥长8.25米。桥台是燕翅形。桥墩是单条石垒砌，桥墩厚0.40米，桥墩长2.00米。跨径2.75米。桥墩上游端有石雕龙头。20世纪70年代，当地村民在古桥上建3孔石拱桥，成为桥上桥。', '', 23, NULL, NULL, '', 10, 1, 10, 1, '泸州市泸县百和镇排楼村，跨两河口小溪与大鹿溪交汇处', '石材', 50, 80, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (766, '泸永桥', '泸永桥是一座5孔石板梁桥。桥面每孔两块石板梁，桥石板厚0.45米，桥面宽2.00米，桥长12.00米。两端是八字形，桥墩厚0.40米，桥墩长2.60米。跨径2.40米。中间两桥墩上雕刻龙形，每孔桥面分别用三块石板并列铺成，雕刻粗犷简约却不失生动。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县百和镇蒋坝村，跨无名溪上', '石材', 50, 81, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (767, '双寿桥', '双寿桥是一座9孔石板梁桥。桥面每孔2块石板梁，石板厚0.50 米，桥面宽1.20米，桥长24.40米。 桥台是燕翅形，桥墩是单条石。跨径2.71米。 由东向西第三、六墩上游端有石雕龙头。下游端有石雕龙尾。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县百和镇东岳村，跨无名溪上', '石材', 50, 82, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (768, '万寿桥', '万寿桥是一座3孔石板梁桥。桥面每孔1块石板梁，桥石板厚0.25米，桥面宽1.04米，桥长8.96米。无桥台，边孔石板梁搭在山脚岩石上。桥墩由单条石垒砌，两端是八字形，桥墩厚0.40米，桥墩长2.00米。跨径2.98米。由西北向东南第二墩有龙形圆雕，龙雕直口龇牙，凸目、凸鼻。雕刻精细、生动、古朴，保存完整。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县百和镇檀木村，跨无名溪上', '石材', 50, 83, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (769, '小桥子桥', '小桥子桥是一座3孔石板梁桥。桥面每孔两块石板梁，桥石板厚 0.35米，桥面宽5.00米，桥长12.00米。无桥台，边孔石板梁搭在山脚岩石上。桥墩由单条石垒砌，两端是八字形，桥墩厚0.40米，桥墩长6.00米。跨径4.0米。桥墩上游端有石雕龙头，下游端有石雕龙尾。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县百和镇四合村，跨无名溪上', '石材', 50, 84, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (770, '泸县潮河桥', '潮河桥是一座5孔石板梁桥。桥面每孔1块石板梁，石板梁厚0.50米，桥面宽1.60米，桥长14.42米。桥台是燕翅形，桥墩由单条石垒砌。跨径2.88米。从东南向西北第二、第三墩上游端有龙头，下游端有龙尾。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县潮河镇潮河村，跨潮河上', '石材', 50, 85, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (771, '付河沟龙桥', '付河沟龙桥是一座5孔石板梁桥。桥面每孔1块石板梁，石板梁厚0.32米，桥面宽0.90米，桥长18.30米。桥台燕翅无存。桥墩由单条石垒砌。跨径2.70米。桥墩上游端有石雕龙头，下游端有石雕龙尾。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县潮河镇朱家坪村，在水田中', '石材', 50, 86, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (772, '梁山上双龙桥', '梁山上双龙桥是一座3孔石板梁桥。桥面每孔1块石板梁，石板梁厚0.32米，桥面宽0.80米，桥长5.57米。桥台是燕翅形，桥墩由单条石垒砌。跨径1.85米。由西南向东北第一个桥墩有石雕龙头，局部损坏。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县潮河镇龙江村，跨无名溪上', '石材', 50, 87, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (773, '龙凤桥', '今存龙凤桥是一座3孔石板梁桥，桥面每孔3块石板梁，桥面宽 1.17米，桥长6.25米。 桥台与石砌河岸为一体。桥墩两端是方形，桥墩厚0.43米，桥墩 长2.10米。跨径由北向南依次是2.10米、2.10米、2.05米。 两个桥墩上分别有石雕龙头，龇牙，凸目，凸额，尖耳，鹿角 形角。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县潮河镇王庄村', '石材', 50, 88, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (774, '泸县明团山桥', '桥面每孔一块石板梁，石板厚0.48米，无栏杆。桥面宽1.24米，桥长14.40米，高1.8米。桥台是石板砌筑的不规则形。桥墩两端有方形和尖形两种形式，厚度与长度不等。跨径1.34—2.43米。东北第二、第三墩的上游端有石雕龙头，龙头龇牙含珠，龙身、龙尾呈“S”形，雕刻精细，造型生动。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县潮河镇天堂坝村，跨无名溪上', '石质', 50, 89, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (775, '五谷寺观音桥', '五谷寺观音桥是一座3孔石板梁桥。桥面每孔1块石板梁，石板梁厚0.50米。桥面宽1.00米，桥长10.00米。桥台燕翅无存，桥墩由单条石垒砌。跨径3.33米。桥墩上雕刻两龙，尾部损毁严重。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸县潮河镇五谷寺村，跨无名溪上', '石', 50, 90, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (776, '江安桥', '江安桥是一座7孔石板梁桥。桥面每孔1块石板梁，石板厚0.40米，石板梁长由东向西依次是2.30米、2.55米、2.71米、2.64米、2.45米、2.43米、2.68米，石板梁之间有0.25米的缝隙。桥面宽1.30米，桥长19.14米。东桥台即石板砌筑的河岸，西桥台是石板砌筑的不规则形。桥墩两端有方形，有八字形，桥墩厚0.50—0.55米，桥墩长2.41—2.71米。跨径由东向西依次是2.55米、2.80米、2.96米、2.89米、2.70米、2.68米、2.68米。桥墩上有石雕龙头。桥东有《重修江安桥记》石碑，刻有“大清同治六年”等字样。', '', 23, NULL, NULL, '', 8, 2, 10, 1, '泸州市泸县得胜镇仁和村', '石材', 50, 91, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (777, '可字桥', '可字桥是一座7孔石板梁桥。桥面每孔两块石板梁，石板厚0.38米，桥面宽2.26米，桥长14.35米。无桥台，石板梁搭在山坡岩石上。桥墩两端是方形，桥墩厚0.50米，桥墩长2.30米。跨径2.05米。原有4个石雕龙头，今尚存1个。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县得胜镇贯顶山村，跨无名溪上', '石材', 50, 92, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (778, '栏湾桥', '栏湾桥是一座5孔石板梁桥，桥面每孔两块石板梁，石板厚0.46 厘米，桥面宽1.36米，桥长13.64米。 无正规桥台。桥墩两端是方形，桥墩厚0.50米，桥墩长2.04米。 跨径由北向南依次是2.73米、2.72米、2.79米、2.72米、2.68米。 桥中部两个桥墩分别雕刻有圆雕龙头，龙口微启，露舌龇牙，鼻、 目凸出，雕刻手法细腻，细条流畅。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县得胜镇白象村', '石材', 50, 93, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (779, '龙阴沟桥', '龙阴沟桥是一座5孔石板梁桥，桥面每孔两块石板梁，桥面宽1.34米，桥长10.40米。桥两端无桥台，石板梁直接搭在溪岸岩石上。桥墩厚0.39米。跨径2.18—2.25米。桥中部两个桥墩分别雕刻有圆雕龙，龙首斜口圆吻、凸额，龙尾为平面盘曲状浮雕。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县得胜镇龙阴沟村，跨无名溪上', '石材', 50, 94, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (780, '毛狗寺桥', '毛狗寺桥是一座4孔石板梁桥。桥面每孔两块石板梁，石板厚0.36米，桥面宽1.50米，桥长10.03米。桥台是燕翅形。桥墩两端是方形，桥墩厚0.40米，桥墩长2.50米。跨径2.57米。桥墩雕龙头，现残存，仅见影像。龙头长0.75米，宽0.55米。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县得胜镇顺民村，跨无名溪上', '石材', 50, 95, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (781, '五子凼桥', '五子凼桥是一座4孔石板梁桥。桥面每孔是两块石板梁，桥面宽 1.13米，桥长8.85米。无桥台石板梁直接搭在山脚岩石上。桥墩两端有方形，有尖形，有长有短。跨径2.21米。两侧桥墩上分别雕刻有圆雕龙头，齿此嘴露牙，形态像鳄鱼，其整体保存较好。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县得胜镇龙阴沟村，跨马溪河支流崔洞溪上', '石材', 50, 96, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (782, '泸县仙济桥', '仙济桥是一座5孔石板梁桥。桥面每孔2块石板梁，石板梁厚0.31米。桥面宽1.40米，桥长9.32米。桥台石砌为方形。桥墩两端是尖形，桥墩厚0.40米。跨径2.32—2.35米。桥墩两端有雕龙，雕刻手法简约而不失生动。', '', 23, NULL, NULL, '', 8, 2, 10, 1, '四川省泸州市泸县得胜镇仁和村，跨濑溪河支流蒲溪上', '石材', 50, 97, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (783, '血水河桥', '血水河桥是一座5孔石板梁桥。桥面每孔4块石板梁，无栏杆。桥面宽2.70米，桥长9.04米。无桥台，石板梁直接搭在山坡上。桥墩两端是方形，有长有短，有薄有厚，桥墩长2.70米。跨径1.85米。原有4尊龙雕，现仅存1尊，龙吻呈弧形长突，很有特点。南端桥板部分已倒塌。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县得胜镇龙阴沟村，跨无名河上', '石材', 50, 98, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (784, '泸县半边滩桥', '半边滩桥是一座石拱和石梁结构相连的31孔石桥。北段8孔是石板梁，第九、十两孔是石拱，南段21孔是石板梁。全桥桥面宽为1.95米，桥梁全长78.40米。两端的桥台是燕翅形。石拱桥的跨径一大一小，大孔的拱碹是大半部圆弧形，小孔的拱碹是半圆形。桥台与石梁桥的中间桥台共，作用为桥墩，桥墩由单条石垒砌，两端是方形。跨径2.52米。', '', 23, NULL, NULL, '', 8, 1, 8, 1, '四川省泸州市泸县方洞镇新联村，跨于濑溪河半边滩河段上', '石材', 50, 99, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (785, '龙灯桥', '龙灯桥是一座3孔石板梁桥。桥面每孔3块石板梁，桥面宽1.41米，桥长7.15米。桥台带燕翅形，前墙长2.44米。桥墩的两端是方形，桥墩厚0.40米，长3.10米。跨径(东北—西南)是1.98米、2.32米、1.90米。两桥墩上各有一尊龙形圆雕。龙雕身披龙鳞，呈“S”形昂首上扬，张口含珠，龙尾纵向卷曲上翘，龙尾、龙首高出桥面0.2—0.4米。其雕刻手法粗犷大方，线条遒劲，甚有气势。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县方洞镇三界村，跨于龙灯桥小溪上', '石材', 50, 100, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (786, '土地坑桥', '土地坑桥是一座3孔石板梁桥。桥面每孔3块石板梁，石板梁厚0.32米，桥面宽1.06米，桥长5.56米。东北无桥台，石板梁搭在山脚岩石上。西北桥台是方形。桥墩由单条石垒砌。跨径1.85米。桥墩上游端有石雕龙头。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县方洞镇屈湾村，跨无名溪上', '石材', 50, 101, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (787, '泸县杨河坝观音桥', '观音桥是一座3孔石板梁桥，桥面每孔3块石板梁，石板梁厚0.32米。桥面宽1.16米，桥长6.78米。桥台是燕翅形，桥墩由单条石垒砌。跨径2.26米。桥墩上游端有石雕龙头，下游端有石雕龙尾。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '四川省泸州市泸县方洞镇庆丰村，跨无名溪上', '石材', 50, 102, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (788, '泸县旧桥', '旧桥是一座4孔石板梁桥。桥面每孔两块石板梁，无栏杆。桥面宽1.24米，桥面长10.65米。桥台是燕翅形，前墙长2.10米。桥墩两端是方形，桥墩厚0.33—0.55米，桥墩长2.94米。跨径(西北—东南)2.60米、2.63米、2.66米、2.76米。第二、第四桥墩的上游端有石雕龙头。龙嘴、龙眼、龙耳、龙须等凸出。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县福集镇神龙村', '石材', 50, 103, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (789, '苦桥子桥', '苦桥子桥是一座石拱桥和石板梁桥对接而成的 5 孔石桥。北第二孔 (现为第一孔) 是石拱桥 (2011 年改造成原来的石板梁桥)，其余 4 孔是石梁桥。拱桥的桥面是弧形阶梯式 (拱碹石的上面做成台阶)，无栏杆。桥面宽 1.50 米，桥面长 18.40 米。拱碹是圆弧形纵联式结构。跨径 3.76 米。石板梁桥的桥面每孔两块石板梁，无栏杆。桥面宽 1.50 米，桥面长 18.40 米。桥台建在河坡岩石上，桥墩两端是方形，桥墩厚 0.33—0.65 米，桥墩长 2.43—3.35 米。北一、二孔跨径 3.84 米，第三至五孔的跨径是 4.84 米、3.86 米、2.10 米。第二、第三个桥墩都有石雕龙头。', '', 23, NULL, NULL, '', 10, 1, 10, 1, '泸州市泸县福集镇石鸭滩村，跨苦桥子溪 (又名小桥溪) 上', '石材', 50, 104, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (790, '石鸭滩桥', '石鸭滩桥是一座35孔石板梁桥。桥面每孔2—5块石板梁，石板梁厚0.46米，桥面宽1.20—2.56米，桥长101.50米。桥台是燕翅形。桥墩两端是尖形，桥墩厚0.40米，桥墩长2.00米。跨径2.28—2.56米。由西南向东北第十四墩、第二十二墩上游端上有石雕龙头、鸭头、象头。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县福集镇石鸭滩村，跨濑溪河上', '石材', 50, 105, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (791, '水口寺桥', '水口寺桥是一座5孔石板梁桥。桥面每孔2块石板梁，石板梁厚 0.50米，桥面宽1.00米，桥长14.42米。桥台石砌为方形。桥墩两端是尖形，桥墩0.52—0.60米。跨径 2.13—2.43米。第二桥墩上游端有石雕龙头，局部损坏。', '', 23, NULL, NULL, '', 8, 2, 10, 1, '泸州市泸县福集镇螺蛳山村，跨濑溪河支流小鹿溪上', '石材', 50, 106, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (792, '铁山洞桥', '铁山洞桥是一座4孔石板梁桥。桥面每孔两块梁，石板厚0.42米。桥面宽1.75米，桥长14.00米。桥台两侧有燕翅墙。桥墩两端是尖形，桥墩厚0.45米，桥墩长1.80米。跨径2.25—2.45米。桥墩上游端有石雕龙头，下游端是石雕龙尾。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县福集镇螺蛳山村，跨无名小河上', '石材', 50, 107, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (793, '泸县万寿桥', '今存文昌宫万寿桥是一座5孔石板梁桥。桥面每孔两块石板梁，桥面宽1.68米，桥长14.40米。桥台用石板砌筑成方形。桥墩两端是方形，桥墩厚0.35米，桥墩长1.70米。跨径2.32—2.44米。中间两桥墩上有石雕龙头，两个龙身呈“S”形，有昂首冲天之势。桥南约40米有修桥碑记，高2.00米、宽0.78米，厚0.25米，但由于风雨侵蚀，字迹剥落，不能辨认。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县毗卢镇罗汉坝村，跨马溪河支流的无名小溪上', '石材', 50, 108, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (794, '鱼目滩桥', '鱼目滩桥是一座16孔石板梁桥。第八孔跨径较大，桥面高起，两端有踏步梯道与相邻桥面连接，桥面每孔是两块石板梁，石板厚0.40米。桥面宽1.53米，桥长47.7米。桥台两侧有燕翅墙。桥墩两端是方形，桥墩厚0.35米，桥墩长1.60米。跨径2.22—2.38米。由东北向西南第七墩、第九墩各有龙首圆雕一尊，共2尊。龙首长吻弧口，龇牙露舌，凸鼻。雕刻手法简洁，线条流畅，不失生动。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县福集镇鱼目村，跨九曲河上', '石材', 50, 109, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (795, '保寿桥（又名“观音桥”）', '保寿桥是一座3孔石板梁桥。桥面每孔两块石板梁，石板梁厚22厘米，桥面宽78厘米，桥长5.67米。桥台是燕翅形，前墙长1.33米。桥墩两端是方形和八字形，桥墩厚0.30米，北墩长1.68米，南墩长1.56米。跨径(北—南)1.89米、2.08米、1.70米。桥墩上游端有石雕龙头，下游端有石雕龙尾，局部残损。', '县保', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县海潮镇陈湾村', '石材', 50, 110, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (796, '泸县观音山双龙桥', '双龙桥又名新桥。是一座3孔石板梁桥。桥面每孔2块石板梁，石板梁厚0.38米，桥面宽1.30米，桥长7.86米。桥台燕翅无存。桥墩由单条石垒砌，桥墩两端是方形。跨径2.62米。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县海潮镇徐场村，跨无名溪上', '石材', 50, 111, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (797, '泸县桂花坝桥', '桂花坝桥是一座3孔石板梁桥。桥面每孔1块石板梁，石板梁厚0.28米，桥面宽0.96米，桥长7.10米。桥台是燕翅形，前墙长1.55米。桥墩两端是方形，桥墩厚0.30米，长1.91米。跨径(东北西南)是2.20米、2.70米、2.20米。桥墩上游端有石雕龙头，局部残损，下游端有石雕龙尾，严重损坏。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县海潮镇尖山村', '石材', 50, 112, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (798, '龙岩星桥', '龙岩星桥是一座4孔石板梁桥。桥面每孔2块石板梁，石板梁厚0.50米，桥面宽1.31米，桥长15.28米。桥台是简易不规则的。桥墩两端是方形，桥墩厚0.53—0.68米，桥墩长1.74—2.51米。跨径(北—南)是3.10米、4.52米、4.89米、2.77米。由西北向东南第二、第三桥墩上游端有石雕龙头，龙头长0.97米，宽0.53—0.68米，高0.64米。', '', 23, NULL, NULL, '', 8, 2, 10, 1, '泸州市泸县海潮镇陈湾村，跨于黑龙溪上', '石材', 50, 113, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (799, '如此桥（观音桥）', '如此桥是一座3孔石板梁桥。桥面每孔2块石板梁，石板梁厚0.42米，桥面宽2.10米，桥长8.40米。东南桥台燕翅无存，西北桥台是燕翅形。桥墩由单条石垒砌。跨径2.80米。桥墩上游端有石雕龙头，下游端有石雕龙尾。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县海潮镇尖山村，跨沱江支流彭溪上', '石材', 50, 114, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (800, '泸县星桥', '星桥是一座3孔石板梁桥，桥面每孔2块石板梁，石板梁厚0.33米，桥面宽0.91米，桥长6.87米。桥台燕翅无存，桥墩由单条石垒砌。跨径2.29米。桥墩上游端有石雕龙头，下游端的石雕龙尾损坏。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县海潮镇陈湾村，跨星桥溪上', '石材', 50, 115, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (801, '一人桥', '一人桥是一座3孔石板梁桥。桥面每孔1块石板梁，石板梁厚0.40米，桥面宽1.00米，桥长9.90米。北桥台是燕翅形，南桥台燕翅毁坏。桥墩由单条石垒砌。跨径3.30米。两桥墩有圆雕龙，龙首、龙尾上昂，高出桥面。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '四川省泸州市泸县海潮镇龙塘村，跨无名溪上', '石材', 50, 116, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (802, '泸县余坝桥', '桥面宽1.58米，桥长8.84米。桥台是燕翅形，前墙长2.68米。桥墩两端是方形，桥墩厚0.47米，长3.20米。跨径(北—南)2.63米、3.51米、2.70米。两个桥墩上各有圆雕龙一尊，龙雕局部残损。龙头长1.13米，宽0.45米，龙吻卷曲状，造型独特；龙尾呈“Z”形缠绕状。两个桥墩之间的桥板迎水侧面正中刻三纹鱼等图案。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸县', NULL, 50, 117, '2026-04-28 23:07:53', '2026-04-28 23:17:40');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (803, '鸿雁桥', '现存鸿雁桥是一座16孔石板梁桥。桥面每孔两块石板梁，石板厚0.47米，桥面宽1.37米，桥长43.73米。桥台燕翅形，前墙长3.80米。桥墩两端是方形，桥墩厚0.50米，桥墩长3.36米。跨径(石板梁长)由北向南依次是2.30米、2.13米、2.30米、2.40米、4.50米、2.70米、2.40米、2.40米、2.35米、2.35米、2.38米、2.40米、2.37米、2.34米、2.42米、2.34米(全长43.73米)。从西北向东南第四、第十一桥墩分别雕刻有圆雕龙，第七桥墩仅存圆雕鸭尾造型。龙雕局部残损。龙头上昂，张口含珠，凸目，凸额；龙身呈“S”形，刻有云纹；龙尾呈缠绕状。圆雕鸭尾呈“V”形，浅浮雕花纹图案。其雕刻手法细腻生动，甚有气势。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县嘉明镇罗桥村，跨于九曲河上', '石材', 50, 118, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (804, '黄桷树桥', '今存黄桷树桥是一座3孔石板梁桥。桥面每孔一块石板梁，石板厚0.23米，无栏杆。桥面宽1.50米，桥面长13.50米。桥台带燕翅形，桥墩两端是方形。跨径3.35—4.40米。雕有两条龙。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县嘉明镇双河口村跨无名溪上', '石材', 50, 119, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (805, '泸县金龙桥', '金龙桥是一座4孔石板梁桥。桥面每孔2块石板梁，石板梁厚0.30米，桥面宽1.00米，桥长7.86米。桥台是燕翅形，前墙长1.79米。桥墩两端是方形，桥墩厚0.36—0.40米，桥墩长2.20米。跨径由北向南依次是1.85米、1.99米、1.93米、2.09米。由西南向东北第一、第二桥墩有石雕龙头。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县嘉明镇团山堡村', '石材', 50, 120, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (806, '梁桥', '梁桥是一座石拱和石梁混合结构桥。中孔是石拱结构，两端各有4孔石板梁结构。石板梁桥的桥面每孔均为两块石板梁，石板厚0.30米。桥面宽1.73米，桥长27.21米。桥台是燕翅形，桥墩由单条石垒砌。各孔跨径3.02米。', '', 23, NULL, NULL, '', 8, 1, 8, 1, '泸州市泸县嘉明镇石燕村，跨于九曲河上', '石材', 50, 121, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (807, '锅厂头桥', '锅厂头桥是一座4孔石板梁桥。桥面每孔2块石板梁，石板厚0.36米，桥面宽1.52米，桥长9.59米。无桥台，桥墩由单条石垒砌。跨径2.39米。桥墩上游端有石雕龙头，下游端有石雕龙尾。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县立石镇玉龙社区，跨无名溪上', '石材', 50, 122, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (808, '横江高桥', '横江高桥是一座5孔石板梁桥。桥面每孔2块石板梁，石板梁厚0.36米，石板梁之间留有0.15米缝隙。桥面宽1.50米，桥长14.10米。桥台是燕翅形。桥墩用单条石板砌筑，两端是方形。跨径2.82米。中间二墩上游端有石雕龙头，下游端有石雕龙尾。', '', 23, NULL, NULL, '', 8, 2, 10, 1, '泸州市泸县牛滩镇横江村，跨无名溪上', '石材', 50, 123, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (809, '王坝新桥', '王坝新桥是一座7孔石板梁桥。桥面每孔2块石板梁，石板梁厚 0.40米，桥面宽1.80米，桥面长17.50米。 桥台是燕翅形，桥墩两端是方形。跨径均为2.50米。 桥墩上游端现存4个龙头。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县牛滩镇王坝村，跨王坝河上', '石', 50, 124, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (810, '泸县月亮山双龙桥', '双龙桥是一座3孔石板梁桥。桥面每孔2块石板梁，石板梁厚0.33米，桥面宽1.23米，桥长6.57米。东北桥台燕翅毁坏，西南桥台是燕翅形。桥墩单条石垒砌。跨径2.19米。桥墩上游端各有一石雕龙首，下游端各有一石雕龙尾。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县牛滩镇红旗村，跨无名溪上', '石材', 50, 125, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (811, '蜘蛛桥', '蜘蛛桥是一座3孔石板梁桥。桥面每孔2块石板梁，桥面宽1.29米，桥长10.86米。桥台是燕翅形，桥墩由单条石垒砌。跨径3.62米。桥墩上游端有石雕龙头，下游端有石雕龙尾。', '', 23, NULL, NULL, '', 8, 2, 10, 1, '泸州市泸县牛滩镇红旗村，跨濑溪河支流无名小溪上', '石材', 50, 126, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (812, '奔青山金花桥', '金花桥是一座3孔石板梁桥。桥面每孔1块石板梁，石板梁厚0.28米，桥面宽1.18米，桥长8.06米。无桥台，石板梁搭在山脚岩石上。桥墩用单条石板砌筑。跨径2.68米。两个桥墩分别浅浮雕龙头，龙头为浅口、上唇微翘，凸鼻、线刻眼睛，造型简单。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县毗卢镇坳丘村，跨无名河上', '石材', 50, 127, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (813, '高阁桥', '高阁桥是一座3孔石板梁桥。桥面每孔2块石板梁(石板梁厚25 厘米),桥面宽1.00米，桥长6.60米。 桥台是燕翅形，北桥台前墙长1.00米(同桥面宽),无南桥台，石 板梁搭在山脚岩石上。桥墩两端是尖形，桥墩厚0.40米，长1.87米。 跨径(东—西)2.20米、2.30米、2.10米。 两个桥墩上分别雕有圆雕龙头，龙头局部残损，线刻龙耳，浮雕龙 角似牛角，雕刻手法简单粗犷。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县毗卢镇坳丘村，跨马溪河上', '石材', 50, 128, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (814, '杨湾桥', '杨湾桥是一座6孔石板梁桥。桥面每孔2块石板梁，石板梁厚0.36米。桥面宽1.33米，桥长9.09米。无桥台，边孔石板梁搭在山脚岩石上。桥墩两端是八字形，桥墩厚0.45米，桥墩长2.00米。跨径(北—南)2.70米、1.29米、1.29米、1.29米、1.32米、1.22米。由东南向西北第二、第三、第四个桥墩分别雕有圆雕龙头，龙头齿此牙，凸鼻、凸目，局部残损，雕刻手法粗犷。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县毗卢镇陈家河村，跨马溪河支流(无名)上', '石材', 50, 129, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (815, '水渚桥', '今存水渚桥是一座3孔石板梁桥。桥面每孔一块石板梁，无栏杆。桥面宽0.60米，桥长6.16米。桥台带燕翅形，前墙长1.00米，桥墩两端是方形，桥墩厚0.30—0.40米，桥墩长2.35—2.42米。跨径2.13—2.15米。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县奇峰镇阳高村', '石材', 50, 130, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (816, '铁垆滩桥', '铁垆滩桥是一座13孔石板梁桥。桥面每孔两块石板梁，桥面宽1.36米，桥长28.52米。桥台是燕翅形。桥墩两端是方形，桥墩厚45厘米，桥墩长2.40米。跨径2.19米。由东北向西南第四、第五、第六、第七、第八墩各有龙形圆雕一尊，共5尊。龙首短吻斜口，口微张露牙舌，凸鼻。龙尾或纵向卷曲，或平面盘状。其雕刻手法粗犷简洁。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县奇峰镇长林村，跨铁石溪上', '石材', 50, 131, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (817, '泸县新桥', '新桥是一座7孔石板梁桥。桥面每孔两块石板梁，石板厚0.33米，桥面宽1.00米，桥长14.06米。无桥台，边孔石板梁搭在山脚岩石上。桥墩两端是八字形。跨径2.00米。由北向南第三、第四墩分别有一尊龙首圆雕，共两尊。龙首雕刻线条圆润流畅，龙头高鼻凸目浮于水面，生动传神。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县奇峰镇长林村，跨马溪河支流铁石溪上', '石材', 50, 132, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (818, '和尚山高桥', '和尚山高桥原名“高桥”,曾名“福星桥”,位于泸州市泸县石桥镇秦家坝村，跨于马溪河上，东北西南走向，建于清代。和尚山高桥是一座5孔石板梁桥。桥面每孔两块石板梁，桥面宽1.36米，桥长32.12米。桥台是燕翅形，前墙长2.11米。桥墩两端是方形，桥墩厚0.40—0.42米，桥墩长2.32米。跨径(东—西)2.40米、2.40米、2.48米、2.61米、2.61米、2.62米。桥墩上分别圆雕狮、龙、象等吉祥兽物，兽头面向河流上游。雕刻物线条流畅，形象生动，技艺精湛。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县石桥镇秦家坝村，跨于马溪河上', '石材', 50, 133, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (819, '河坝头双龙桥', '河坝头双龙桥是一座5孔石板梁桥。桥面每孔1块石板梁(石板梁厚0.37米),桥面宽1.32米，桥长12.20米。桥台是燕翅形。桥墩用单条石板砌筑，两端是方形。跨径2.44米。中间两个桥墩上游端有石雕龙头，皆有残损。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县石桥镇秦家坝村，跨无名小溪上', '石材', 50, 134, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (820, '会元桥', '会元桥是一座6孔石板梁桥。桥面每孔4块石板梁，桥面宽4.50米，桥长25.00米。桥台是凹字形，前墙长4.50米。桥墩两端是方形，桥墩厚0.70—0.85米，桥墩长5.00—5.50米。跨径均为3.15米。20世纪90年代，改建3孔桥面为混凝土板梁。', '', 23, NULL, NULL, '', 10, 2, 10, 1, '泸州市泸县石桥镇黄荆湾村', '石材、混凝土', 50, 135, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (821, '桥底下桥', '桥底下桥是一座6孔石板梁桥。桥面每孔2块石板梁，桥面宽1.56米，桥长13.42米。西北第一孔桥面高出其他桥面0.45米。桥台是燕翅形。桥墩用单条石板砌筑，两端是方形。跨径2.33米。西北至东南第二、第三、第四桥墩均圆雕龙头，张口露舌，小巧精致。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县石桥镇永定村，跨于马溪河上游', '石材', 50, 136, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (822, '鼎新桥', '鼎新桥是一座7孔石板梁桥。桥面每孔1块石板梁，石板梁厚63厘米，桥面宽1.26米，桥长21.42米。桥台是燕翅形，桥墩由单条石垒砌。跨径3.06米。东北向西南第三、第四、第五孔东侧桥板侧面，分别浮雕丝缠书卷、丝缠宝剑、丝缠如意。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县太伏镇照南山村，跨鼎新桥小溪上', '石材', 50, 137, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (823, '济康桥', '济康桥是一座6孔石板梁桥。桥面每孔2块石板梁，石板梁厚0.50米，桥面宽1.20米，桥长13.00米。桥台是燕翅形，桥墩由单条石垒砌。跨径2.16米。中央桥墩上有圆雕龙。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县太伏镇林桥村，跨无名溪上', '石材', 50, 138, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (824, '李子桥', '李子桥是一座3孔石板梁桥。桥面每孔1块石板梁，石板梁厚0.50米，桥面宽1.32米，桥长7.86米。无桥台，边孔石板梁搭在山脚岩石上。桥墩由单条石垒砌，跨径2.62米。桥墩上游端有石雕龙头，下游端有石雕龙尾。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县太伏镇林桥村，跨无名溪上', '石材', 50, 139, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (825, '母猪桥', '母猪桥是一座6孔石板梁桥。桥面每孔1块石板梁，石板梁厚0.50米，桥面宽0.97米，桥长15.16米。无桥台。桥墩两端是方形，桥墩厚0.35—0.39米，长1.61—2.06米。跨径(东—西)是1.01米、1.97米、3.03米、3.00米、3.03米、3.03米。由东南向西北第三、第四墩上各有龙首圆雕一尊，共两尊。龙首弧吻凸目，口微启，其雕刻手法简洁生动。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县太伏镇林桥村，跨于母猪溪上', '石材', 50, 140, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (826, '桥墩河桥', '桥面每孔1块石板梁，桥面宽1.43米，桥长13.58米。南桥台是燕翅形，北端无桥台，石板梁搭在山脚岩石上。桥墩用单条石垒砌，跨径(南—北)2.84米、2.80米、2.40米、2.19米、1.95米、1.4米。从南向北第一、第二、第三墩上游端有石雕龙头。第二、第三墩下游端有石雕龙尾。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县太伏镇渔湾村，跨无名小溪上', '石材', 50, 141, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (827, '泸县狮子桥', '狮子桥是一座8孔石板梁桥，桥面每孔3块石板梁，桥面宽1.22米，桥长16.24米。东南桥台燕翅毁坏，西北桥台是燕翅形。桥墩由单条石垒砌，跨径2.03米。从东南至西北第二、第三墩各有龙形圆雕一尊，雕刻手法简洁生动。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县太伏镇渔湾村，跨长江支流大岸溪上', '石材', 50, 142, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (828, '堰坎桥', '堰坎桥是一座9孔石板梁桥。桥面每孔2块石板梁，石板厚0.35米，石板宽0.65米，石板梁长2.00—2.15米。桥面宽1.30米，桥长18.74米。西南端无桥台，东北桥台残存燕翅形，桥墩由单条石垒砌。跨径2.08米。龙形雕刻手法古朴生动。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县太伏镇玉溪村，跨无名溪上', '石材', 50, 143, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (829, '泸县玉带桥', '玉带桥是一座4孔石板梁桥。桥面每孔2块石板梁，桥面宽0.87米，桥长7.87米。东北桥台是燕翅形，西南桥台毁坏，桥墩形状不明。跨径1.96米。3个桥墩上分别有龙形圆雕各一尊，尾部呈缠绕状。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县太伏镇伏龙村，跨玉带河小溪上', '石材', 50, 144, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (830, '龙脑桥', '龙脑桥是一座13孔石板梁桥。桥堍上各并排铺砌两块石板，桥面每孔2块石板梁，石板宽0.95米，厚0.60米，长3.60米。桥上无栏杆，桥面宽1.90米，桥面长46.80米，全长54.00米。桥台是凹字形，前墙长约3.00米。两端是尖形，桥墩厚3.10米，桥墩长5.00米。跨径2.96—3.01米。北起第三至第十墩上游(东)端上面有石雕兽头，下游(西)端的上面有石雕兽尾。中间8个桥墩分别圆雕龙、麒麟、青狮、大象4种吉祥兽物，石雕动物的脊背凹槽上安置桥面石板。桥的一侧露出动物头部，一侧露出尾部。这些雕刻各不相同，有的嘴衔绶带，有的脚踏绣球，有的足踩玉圭。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '四川省泸州市泸县县城玉蟾街道北部龙华村，跨九曲河上', '石材', 50, 145, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (831, '代桥', '代桥是一座3孔石板梁桥。桥面每孔两块石板梁，石板梁厚0.30米，桥面宽1.14米，桥长8.70米。无桥台石板梁搭在山脚岩石上。桥墩用单条石垒砌，两端是方形。跨径2.90米。桥墩上游端有石雕龙头，下游端有石雕龙尾(局部残损)。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县玄滩镇石鹅沟村，跨无名溪上', '石材', 50, 146, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (832, '纺线桥', '今存纺线桥是一座9孔石板梁桥。桥面每孔两块石板梁，石板厚0.40米，桥面宽2.09米，桥长23.10米。桥两端均无桥台，石板梁直接搭在河岸岩石上。桥墩两端是方形，桥墩厚0.60米，桥墩长2.10米。跨径2.33—2.43米。桥中部的6个桥墩各有一尊圆雕龙，龙头短吻上翘，平目凸额，雕刻手法简单、粗犷，龙雕残损、风化严重。', '', 23, NULL, NULL, '', 7, 2, 7, 1, '泸州市泸县玄滩镇老油房村，跨濑溪河上', '石材', 50, 147, '2026-04-28 23:07:53', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (833, '济众桥', '济众桥是一座9孔石板梁桥。桥面每孔2块石板梁，石板梁厚0.30米，桥面宽1.30米，桥长26.25米。桥台两侧有不对称雁翅墙。桥墩两端是方形。由东南向西北第二桥墩上游端有石雕龙头，局部损坏。下游端有石雕龙尾。桥台石砌为方形。桥墩厚0.48—0.52米。跨径2.33—2.45米。', '', 23, NULL, NULL, '', 8, 2, 10, 1, '泸州市泸县玄滩镇老油房村，跨马溪河上', '石材', 50, 148, '2026-04-28 23:07:54', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (834, '泸县牛岩坡新桥', '新桥是一座9孔石板梁桥。桥面每孔2块石板梁，石板梁厚0.30米，桥面宽1.25米，桥长22.30米。桥台两侧有雁翅墙。桥墩上游端是尖形，下游端是方形。桥台石砌为方形。桥墩两端是尖形，桥墩厚0.48—0.50米，跨径1.89—2.12米。由北向南第三、第五桥墩上游端有石雕龙头，龙头损坏。', '', 23, NULL, NULL, '', 8, 2, 10, 1, '泸州市泸县玄滩镇涂丰村，跨龙溪河上', '石材', 50, 149, '2026-04-28 23:07:54', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (835, '泰和桥', '泰和桥是一座14孔石板梁桥。每孔两块石板梁，桥面宽1.58米，桥长35.20米。桥台是燕翅形，前墙长2.20米。桥墩用条形石垒砌，两端是方形。跨径2.51米。桥墩的上游端有石雕龙头，有部分残损。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县玄滩镇中心村，跨于马溪河上', '石材（条形石、石板梁）、混凝土（北第二、第三两孔桥面）', 50, 150, '2026-04-28 23:07:54', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (836, '众缘桥', '众缘桥是一座3孔石板梁桥。桥面每孔2块石板梁，石板梁厚0.38米，桥面宽1.70米，桥长8.50米。无桥台，石板梁搭在山脚岩石上。桥墩用单条石板砌筑，两端是方形。跨径2.83米。桥墩上游端有石雕龙头，张口含珠(残损)。', '', 23, NULL, NULL, '', 8, 2, 10, 1, '泸州市泸县玄滩镇海罗村，跨无名溪上', '石材', 50, 151, '2026-04-28 23:07:54', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (837, '岸滩桥', '岸滩桥是一座26孔石板梁桥。桥面每孔2块石板梁，石板梁厚0.30米，桥面宽1.25米，桥长67.32米。桥台是燕翅形，桥墩由单条石垒砌。跨径2.58米。桥墩原有龙雕，现已损毁。为方便于桥下船只通行，后人将东北面桥墩增高成现状。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县喻寺镇兴隆村，跨濑溪河上', '石材', 50, 152, '2026-04-28 23:07:54', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (838, '谭石桥', '谭石桥是一座28孔石板梁桥。桥面原系每孔2块石板梁，历次重修，形成每孔2、3、4块石板梁，桥面宽1.77 — 2.30 米，桥长 100.00米。桥台燕翅无存。桥墩由单条石垒砌。跨径3.57米。20世纪90年代，将西南端2孔桥面升高，改石板梁为混凝土板梁。', '', 23, NULL, NULL, '', 10, 2, 10, 1, '泸州市泸县喻寺镇新桥村跨濑溪河上', '石材、混凝土', 50, 153, '2026-04-28 23:07:54', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (839, '泸县牺牛山桥', '黄桷桥是一座3孔石板梁桥。桥面每孔2块石板梁，石板厚0.33米，桥面宽95米，桥长8.09米。西北桥台为燕翅形，东南无桥台，边孔石板梁搭在山脚岩石上。桥墩单条石垒砌，两端是八字形，桥墩厚40厘米，桥墩长2.50米。两个桥墩分别有圆雕瑞兽，两瑞兽扭头相望，造型生动，兽雕局部保存较完整。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸县', '石材', 50, 154, '2026-04-28 23:07:54', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (840, '翘墩桥', '翘墩桥是一座3孔石板梁桥，桥面每孔2块石板梁，桥面宽1.03米，桥长5.90米。桥台是燕翅形。桥墩单条石垒砌，两端是八字形，桥墩厚0.40米，桥墩长1.60米，跨径1.97米。两个桥墩上分别有圆雕龙，龙雕局部残损。龙头向上游，龙口微张露牙，龙尾呈平面浅浮雕盘卷状。桥台残存。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县云锦镇斑竹林村，跨龙溪河支流云锦溪上', '石材', 50, 155, '2026-04-28 23:07:54', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (841, '泸县天堂嘴双龙桥', '双龙桥是一座3孔石板梁桥。桥面每孔2块石板梁，石板梁厚0.30 米。桥面宽2.50米，桥长8.00米。 桥台是燕翅形，桥墩由单条石垒砌，跨径2.66米。 桥墩上游端有石雕龙头，龙头长0.8米，宽0.4米。下游端有石雕龙尾，龙尾长0.4米，宽0.35米。', '', 23, NULL, NULL, '', 8, 2, 10, 1, '泸州市泸县云锦镇花园村，跨无名溪上', '石材', 50, 156, '2026-04-28 23:07:54', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (842, '乌棒桥', '乌棒桥是一座双孔石板梁桥。桥面每孔2块石板梁，石板梁厚0.50米，桥面宽0.88米，桥长4.08米。无桥台，桥墩两端是方形，桥墩厚分别为0.32米和0.35米，桥墩长约1.00米。跨径1.52米。桥墩上有圆雕龙，龙雕残损。原桥东北约6米田角处有1通桥碑，现已成为当地居民熊廷华住宅的墙基石，碑宽0.32米、厚0.4米、高1.47米。', '', 23, NULL, NULL, '', 8, 2, 10, 1, '泸州市泸县云锦镇翻身村，跨无名溪上', '石材', 50, 157, '2026-04-28 23:07:54', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (843, '砖嘴屋基双龙桥', '桥面每孔两块石板梁，桥面宽 1.00 米，桥长 11.68 米。桥台是燕翅形。桥墩用单条石垒砌，桥墩厚 0.40 米，桥墩长 2.00 米。跨径 2.92 米。由西向东第一、第三个桥墩分别有圆雕龙头，龙头龇牙露舌，憨态可掬。原桥板与龙雕位于同一平面，为便于行人通过，当地居民于 1968 年将桥板升高到现有高度。', '', 23, NULL, NULL, '', 10, 2, 10, 1, '泸州市泸县云锦镇稻子村，跨龙溪河支流(无名)上', '石材', 50, 158, '2026-04-28 23:07:54', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (844, '子母桥', '子母桥是一座4孔石板梁桥。桥面每孔两块石板梁，石板厚0.40米，桥面宽1.64米，桥长10.05米。无桥台，两端的石板梁分别搭在溪岸石滩上。桥墩单条石垒砌，两端是八字形，桥墩厚0.40米，桥墩长2.50米。跨径2.62米。西北向东南第二、第三个桥墩分别有圆雕龙，龙雕局部残损，龙吻凸出，雕刻大气。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '四川省泸州市泸县云锦镇冯石村，跨长江支流大河上', '石材', 50, 159, '2026-04-28 23:07:54', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (845, '金罡桥', '金罡桥是一座5孔石板梁桥。桥面每孔两块石板梁(石板厚0.39米)，桥面宽1.46米，桥长13.28米。桥台是燕翅形，前墙长2.04米，桥墩厚0.35—0.51米，长2.50米。跨径(石梁长和石梁之间的缝隙0.25米)由北向南依次是2.40米、2.37米、2.37米、2.40米、2.37米。桥面形制较其他泸县龙桥不同，桥板安置于“工”字形桥墩上。桥中部的两个桥墩分别雕刻有圆雕龙，龙头短吻、粗鼻、凸目；龙身刻云纹；龙尾呈缠绕卷曲状。从东向西第二个桥墩龙头张口露齿，第三个桥墩龙头张口含珠。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县云龙镇朱梅滩村，跨于龙溪河的支流上', '石材', 50, 160, '2026-04-28 23:07:54', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (846, '梨园桥', '桥面每孔两块石板梁(石板厚0.32米)，桥面宽1.14米，桥长11.95米。桥台属于不规则形。桥墩的两端是方形，桥墩厚0.32—0.35米，长1.66—2.43米。跨径(东—西)是2.38米、2.38米、2.40米、2.38米、2.41米。桥中部的两个桥墩分别雕刻有圆雕龙，龙头长吻弧口，龇牙露舌，凸鼻，龙尾为浅浮雕平面盘状，雕刻技法较细腻。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县云龙镇茅坝村', '石材', 50, 161, '2026-04-28 23:07:54', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (847, '龙洞桥', '龙洞桥是一座5孔石板梁桥，桥面每孔两块石板梁(石板厚0.33 米),桥面宽1.63米，桥长10.11米。桥台带燕翅形，前墙长2.23米。桥墩两端是方形，桥墩厚0.38 米，长3.23—3.34米。跨径(东—西)是2.00米、2.05米、2.02米、 2.04米、2.00米。4个桥墩上各有一尊圆雕龙头。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县云龙镇姜河坎溪', '石材', 50, 162, '2026-04-28 23:07:54', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (848, '漏孔滩桥', '漏孔滩桥是一座7孔石板梁桥。桥面每孔1块石板梁，石板厚0.35米，桥面宽1.10米，桥长16.76米。桥两端无桥台，石板梁直接搭在溪岸岩石上。桥墩两端是方形，桥墩厚50厘米，桥墩长1.10米。跨径2.39米。由东北向西南第四、第五个桥墩上分别雕刻有龙头，龙头雕刻弧口微翘，凸目，雕刻技法较简单。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县云龙镇英雄村，跨漏孔滩小溪上', '石材', 50, 163, '2026-04-28 23:07:54', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (849, '泸县三元桥', '三元桥是一座7孔石板梁桥。桥面每孔是单块石板梁，无栏杆。桥面宽1.00米，桥长11.83米。桥台是凹字形，东起第一、第二、第五桥墩的两端是方形，第三、第四桥墩的两端是圆形，上游端有石雕龙头，下游端是龙尾。跨径1.30—1.80米。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县云龙镇云丰村，跨无名小溪上', '石材', 50, 164, '2026-04-28 23:07:54', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (850, '狮洞子桥', '狮洞子桥是一座4孔石板梁桥。桥面每孔2块石板梁，石板厚0.30米，桥面宽1.30米，桥长6.60米。桥台两侧有燕翅墙，不对称。桥墩两端是方形，桥墩厚0.45米，桥墩长1.30米。跨径1.65米。桥中部的桥墩雕刻有圆雕龙，龙头长0.6米，宽0.25米；龙尾长0.28米，宽0.25米。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县云龙镇大水河村，跨无名小溪上', '石材', 50, 165, '2026-04-28 23:07:54', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (851, '顺对子桥', '今存顺对子桥是一座11孔石板梁桥。桥面每孔4块石板梁，桥板厚0.40米。无栏杆，桥面宽1.98米，桥长39.00米。桥台是凹字形，桥墩两端是尖形。跨径2.80米。中4墩的上游端有石雕龙头，下游端有石雕龙尾。龙头上昂，口内含珠，凸目凸鼻，龙吻短平，角卷曲，高于桥面板0.04—0.25米。龙尾有的卷曲，有的上翘。第六孔桥板东侧楷书阴刻“龙藏蛟伏”字样，字间有浅浮雕宝剑一把。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '四川省泸州市泸县云龙镇吉林村，跨龙溪河上', '石材', 50, 166, '2026-04-28 23:07:54', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (852, '天堂桥', '天堂桥是一座5孔石板梁桥。桥面每孔两块石板梁，石板厚0.30米，桥面宽1.29—1.60米，桥长12.42米。桥台两侧有燕翅墙。桥墩两端是方形。跨径2.48米。从南向北的第一、第二、第三桥墩各有龙形雕刻，其中第一、第二桥墩龙头已毁，龙尾完整，呈“S”形上翘状，第三个桥墩龙头口微张，凸目、凸额，龙形雕刻细腻，龙尾已毁。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县云龙镇葛藤湾村，跨滩子河小溪上', '石材', 50, 167, '2026-04-28 23:07:54', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (853, '土地桥', '土地桥是一座3孔石板梁桥。桥面每孔2块石板梁，石板厚0.30米，桥面宽1.10米，桥长6.50米。桥台是雁翅型。桥墩两端是方形，有长有短。跨径2.16米。桥面含龙雕宽2.15米。桥墩分别有一尊龙雕，龙头龙尾残存。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县云龙镇伏耳村跨无名溪上', '石材', 50, 168, '2026-04-28 23:07:54', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (854, '泸县瓦坝大桥', '桥面宽0.94米，桥长6.75米。桥台是燕翅形。桥墩两端是八字形。跨径2.25米。两个桥墩上分别有圆雕龙，龙头、龙尾高于桥板0.25米，两龙头局部残损。龙头呈“S”形上昂，张口露牙，龙须飘逸；龙身刻云纹，龙爪呈奋然划动姿势，龙尾呈翘卷镂空状。此桥由于所跨河溪窄小，河床浅，每逢汛期便被淹没，不能通行。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸县', NULL, 50, 169, '2026-04-28 23:07:54', '2026-04-28 23:17:41');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (855, '泸县永济桥（锣鼓滩大桥）', '永济桥是一座13孔石板梁桥。桥面每孔3块石板梁，石板梁厚0.45米。桥面宽1.88米，桥长42.57米。东北桥台燕翅无存，西南桥台是燕翅形。桥墩上游端尖形，下游端方形。桥墩厚0.50—0.53米，桥墩长2.00—3.00米。跨径2.1—2.21米。由东北向西南第四、第六、第七、第九桥墩上游端有石雕龙头，下游端有石雕龙尾。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县镇战旗村，跨于龙溪河上', '石材', 50, 170, '2026-04-28 23:07:54', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (856, '白思桥', '白思桥是一座8孔石板梁桥。桥面每孔2块石板梁，桥面宽1.18米，桥长22.89米。桥台是“一”字形，前墙长(同桥面宽)1.18米。桥墩两端是方形，桥墩厚0.50米，桥墩长分别是2.39、2.49、2.28米。跨径(北—南)是3.40米、2.66米、2.64米、2.65米、2.63米、2.68米、2.58米、3.65米。由南向北第三、第四、第五墩分别有圆雕狮、龙、象各一尊。狮雕口衔绶带，龙雕张口含珠，象雕贴身藏鼻，造型生动。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县兆雅镇石龙村，跨猫儿河小溪上', '石材', 50, 171, '2026-04-28 23:07:54', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (857, '泸县双龙桥', '双龙桥是一座4孔石板梁桥。桥面每孔两块石板梁，桥面宽1.10米，桥长11.20米。无桥台，边孔石板梁搭在山脚岩石上。桥墩用单条石垒砌，两端是方形，桥墩厚0.40米，桥墩长1.60米。跨径2.80米。北第一、第二墩东侧各有圆雕龙首一尊。龙雕弧吻凸鼻，龇牙咧嘴，粗犷而生动。', '', 23, NULL, NULL, '', 8, 2, 8, 1, '泸州市泸县兆雅镇石龙村，在水田中', '石材', 50, 172, '2026-04-28 23:07:54', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (858, '萧河桥', '萧河桥是一座单孔石拱桥。桥面上横铺条形石板，桥面略显圆弧形。桥栏杆无存，地伏和仰天石犹存。桥面全宽4.30米，净宽3.00米，桥长10.50米。侧墙是用青石板砌筑，上顶有单层仰天石。桥台两侧有燕翅墙，前墙长5.50米。拱碹是半圆形纵联式结构，碹脸外边有拱眉石，碹脸、拱眉与侧墙平。跨径3.00米。', '', 2, NULL, NULL, '', 10, 1, 10, 1, '天津市宝坻区', '条形石板、青石板', 50, 51, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (859, '果香峪桥', '果香峪桥是一座单孔石拱桥。桥面上横铺条形花岗岩石板，桥面略显圆弧形。两侧有节间式石栏杆，望柱与栏板高度相同，两端有抱鼓石。桥面宽7.00米，桥长9.50米。侧墙是用青石板砌筑，上顶有单层仰天石。桥台两侧有燕翅墙，前墙长8.20米。拱碹是尖形(拱顶是小圆弧形)纵联式结构，无拱眉，跨径5.30米。', '', 2, NULL, NULL, '', 8, 1, 8, 1, '天津市蓟州区', '花岗岩石板（桥面）、青石板（侧墙）', 50, 52, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (860, '蓟州水关桥', '水关桥是一座5孔石拱桥。桥面上铺砌花岗岩石板，桥面略显圆弧形，无栏杆。桥面宽6.40米，桥长20.00米。翼墙和侧墙是用花岗岩石板砌筑，上面有单层仰天石。桥台两侧有燕翅墙。桥墩两端是尖形，桥墩厚数据暂缺，桥墩长数据暂缺。拱碹是半圆形纵联式结构，中孔碹脸龙门上有石雕龙头，碹脸外边有拱眉石，拱眉凸出于碹脸，拱眉与侧墙齐平。跨径6.60米。', '', 2, NULL, NULL, '', 10, 1, 10, 1, '天津市蓟州区黄崖长城南面', '花岗岩石板', 50, 53, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (861, '迎客松桥', '迎客松桥是一座3孔石拱桥。桥面上铺砌花岗岩石板，桥面略显圆弧形，无栏杆，无地伏。桥面宽3.00米，桥长9.00米。翼墙和侧墙是用花岗岩石板砌筑，上面有较厚的青石仰天石(略高出桥面)。桥台两侧有燕翅墙，前墙长4.20米。桥墩两端是尖形。拱碹是半圆形纵联式结构，中孔碹脸龙门上有石雕龙头，碹脸外边有拱眉石，拱眉凸出于碹脸，拱眉与侧墙齐平。中孔跨径6.30米，边孔跨径5.40米。', '', 2, NULL, NULL, '', 8, 1, 8, 1, '天津市蓟州区', '花岗岩石板、青石', 50, 54, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (862, '九华山迎仙桥', '迎仙桥是一座单孔石拱桥，桥上有节间式石栏杆，望柱为方形柱头，栏板为实体板，地伏和仰天石均为矩形断面。桥面宽7.00米，桥长15.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是燕翅形，前墙长约8.20米。拱碹是半圆形纵联分段并列式结构，碹脸外有拱眉石，拱眉与侧墙取平。跨径7.60米。', '', 12, NULL, NULL, '', 8, 1, 8, 1, '池州市青阳县九华山大门口', '石材（料石）', 50, 51, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (863, '广惠桥', '广惠桥古名“宏济桥”。现存桥是一座3孔石拱桥，桥面为正圆弧形，两侧有节间式石栏杆，望柱置于地伏上，栏板是两条横板式。桥面宽6.30米，桥长36.00米。侧墙用料石砌筑，上顶有单层仰天石组成的金边线。桥台两侧有燕翅墙，前墙长约7.50米。桥墩两端均为尖形，拱碹是半圆形纵联石结构，无拱眉，碹脸后退于侧墙。中孔跨径8.00米，边孔跨径6.50米。', '', 12, NULL, NULL, '', 7, 1, 10, 1, '滁州市区四牌楼街和古楼街交接处', '石材（料石）', 50, 52, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (864, '薛老桥', '薛老桥是一座单孔石拱桥，桥堍和桥面上铺砌青石板，桥面略显弧形，原无栏杆。桥面宽4.50米，桥长6.00米。侧墙用乱石砌筑，上顶有一层平牙石。桥台是凹字形，前墙长4.50米。拱碹是半圆形纵联式结构，碹脸外边有拱眉，拱眉、碹脸与侧墙取平。跨径3.50米。1990年添建有节间式石栏杆，每侧有望柱3根，栏板2块，抱鼓石2块，更换边牙石为地伏。', '', 12, NULL, NULL, '', 10, 1, 10, 1, '滁州琅琊山中醉翁亭前', '青石板、乱石', 50, 53, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (865, '长虹桥', '长虹桥是一座11孔石拱桥。桥面大致为平面，桥栏杆大部分已损坏，地伏和仰天石的断面均为矩形，桥面宽7.20米，桥长147.00米。侧墙用块石砌筑，上顶有单层仰天石。桥台是燕翅形。桥墩上游端是尖形，下游端是方形。拱碹是半圆形纵联式结构，有拱眉，碹脸、拱眉与侧墙平。最大跨径11.00米。', '', 12, NULL, NULL, '', 7, 1, 10, 1, '黄山市徽州区西溪南镇', '石材、块石', 50, 54, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (866, '麟凤桥', '麟凤桥是一座5孔石拱桥，桥塊和桥面上铺砌红砂岩石板，桥面呈圆弧形，两侧有节间式石栏杆，每侧34根望柱，33块栏板，2块抱鼓石。桥面宽7.65米，桥长91.90米。侧墙用料石砌筑，上顶有单层仰天石组成的金边线。桥台是带燕翅形，前墙长8.80米。桥墩上游端是尖形，下游端是方形，拱碹是半圆纵联式结构，碹脸外边有拱眉石，拱眉凸出于碹脸，拱眉与侧墙平。跨径均为14.50米。', '', 12, NULL, NULL, '', 8, 1, 8, 1, '黄山市黄山区仙源镇东门外，跨麻川河上', '红砂岩石板（桥塊和桥面）、料石（侧墙）', 50, 55, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (867, '祁门平政桥', '现存平政桥是一座5孔石拱桥。桥堍和桥面上铺砌砂岩石板，桥面是正圆弧形竖曲线，两侧有节间式石栏杆，下面有砂岩地伏。桥面宽7.00米，桥长79.40米。侧墙用料石砌筑，上顶有单层仰天石组成的金边线。桥台是凹字形，前墙长7.00米。桥墩两端是方形(与拱脚齐),桥墩厚2.00米，桥墩长7.00米。拱碹是半圆形纵联式结构，碹脸外边有拱眉石，拱眉凸出于碹脸，又凸出于侧墙。中孔跨径15.00米，次边孔跨径13.05米，边孔跨径10.50米。', '', 12, NULL, NULL, '', 8, 1, 10, 1, '安徽省黄山市祁门县阊江河上', '砂岩石板、料石', 50, 56, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (868, '仁济桥', '仁济桥是一座5孔石拱桥。其结构形式与平政桥相同，桥堍和桥面上铺砌砂岩石板，桥面中部(中三孔上)高起为平面，两端(边孔上和桥堍上)是缓坡面。两侧有节间式石栏杆，下面有地伏石。桥面宽 7.00米，桥长79.40米。侧墙用条形石板砌筑，上面有单层仰天石组成的金边线。桥台是凹字形，前墙长约7.00米。桥墩两端均为方形，桥墩厚1.50米，桥墩长约7.00米。拱碹是半圆形镶边纵联式结构，碹脸外边有拱眉石，拱眉凸出于碹脸，又凸出于侧墙。中三孔跨径均为15.00米，边孔跨径均为 10.50米。', '', 12, NULL, NULL, '', 8, 1, 10, 1, '黄山市祁门县祁门乡，跨阊江河上，在平政桥下游 250米', '砂岩石板（桥堍和桥面）、条形石板（侧墙）', 50, 57, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (869, '北岸桥', '北岸桥是一座5孔石拱桥。桥上建有砖木结构廊，南端门额是“乡贤星”,北端门额是“谦庵旧址”。桥面宽4.70米，桥长33.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台建在山脚下，两侧有燕翅墙，前墙长5.90米。桥墩两端是尖形，拱碹是半圆形纵联式结构，碹脸外边有拱眉石，碹脸、拱眉与侧墙齐平。跨径均为5.50米。', '', 12, NULL, NULL, '', 8, 1, 8, 1, '黄山市歙县北岸镇，跨棉溪河上', '石材、砖木', 50, 58, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (870, '高阳桥', '全桥为平面，桥面宽6.00米，桥长19.00米。桥上建砖木结构屋。侧墙用料石砌筑，上顶有单层仰天石。桥台是燕翅形。桥墩上游端是尖形，下游端是方形。跨径6.20米。', '', 12, NULL, NULL, '', 10, 1, 10, 1, '安徽省黄山市歙县', '石材（料石）、砖木', 50, 59, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (871, '太平桥', '今存太平桥是一座16孔厚拱厚墩重型石拱桥。桥面大致是平面，两侧有节间式石栏杆，地伏为矩形断面。桥面宽7.10米，桥长267.60米。侧墙用料石砌筑，上顶有单层仰天石(矩形断面)组成的金边线。桥台两侧有燕翅墙，桥墩较厚，上游端为尖形，下游端为方形，桥墩下部四周有出台(宽约20厘米)，拱碹为半圆形纵联式结构，无拱眉，碹脸与侧墙取平。跨径均为13.50米。', '', 12, NULL, NULL, '', 7, 1, 7, 1, '黄山市歙县城西门外，跨池河上', '石材（料石）', 50, 60, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (872, '万年桥', '万年桥是一座9孔石拱桥。桥塊和桥面上铺砌花岗岩石板，桥面呈穹隆形，两侧有节间式石栏杆，无地伏，桥栏杆置于双层仰天石上。桥面宽6.70米，桥长153.00米。翼墙和侧墙用花岗岩石板砌筑，上顶有双层青石仰天石组成的金边线。桥台为凹字形，前墙长6.70米，端墙外有石砌燕翅墙。桥墩为梭形，底部四周皆有出台(宽约30厘米)，桥墩厚1.30米，桥墩长7.30米。拱碹是半圆形纵联式结构，碹脸外缘錾出拱眉线，拱眉凸出于侧墙。跨径均为14.00米。桥东端旧有一座石牌坊，北面石匾上刻“北钥云龙”，南面石匾上刻“道岸津梁”。', '', 12, NULL, NULL, '', 8, 1, 8, 1, '安徽省黄山市歙县城北门外北关村，跨扬之河上', '花岗岩石板、青石', 50, 61, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (873, '紫阳桥（寿民桥）', '紫阳桥是一座9孔石拱桥。桥面东高西低，呈斜坡式平面。桥台和桥墩上顶的高程是东桥台最高，向西逐渐减小。桥堍和桥面上铺砌红砂岩石板，两侧有节间式石栏杆，地伏是矩形断面。桥面宽10.00米，桥长140.00米。侧墙用料石砌筑，上顶有单层仰天石组成的金边线。桥台建在山脚岩石上，两侧有燕翅墙，燕翅墙很高，前墙长11.20米。桥墩两端是尖形，分水尖上顶在仰天石下面，拱碹均系半圆形纵联式结构，东孔的跨径最大，是12.40米，其他各孔跨径均为11.00米。', '', 12, NULL, NULL, '', 8, 1, 8, 1, '安徽省黄山市歙县城东南渔梁坝下紫阳村（跨练江上）', '红砂岩石板、料石', 50, 62, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (874, '登封桥', '登封桥是一座9孔等跨径石拱桥。桥面宽7.50米，桥长180.00米。桥塊和桥面上用条形石板铺砌，桥面大致为平面，两侧有宇墙式砖砌桥栏杆，上顶有青石墙帽，无地伏，桥栏杆置于仰天石上。侧墙用青石板砌筑，上顶有单层青石仰天石组成的金边线。桥台在河岸上，桥墩两端均为方形，四周有出台(宽出拱脚约30厘米),拱碹是半圆形纵联式结构，拱眉凸出于碹脸，拱眉与侧墙平。跨径均为16.00米。', '', 12, NULL, NULL, '', 8, 1, 8, 1, '安徽省黄山市休宁县齐云山北麓，跨横江上，桥北接皖赣公路，桥南接齐云山登山道', '条形石板、青石、砖', 50, 63, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (875, '镇海桥', '现存镇海桥是一座7孔石拱桥。桥面大致为平面，桥栏杆残存约半数。桥长130.00米。侧墙用块石砌筑，上顶有单层仰天石。桥台是凹字形，端墙外有燕翅墙。桥墩两端与拱脚齐平，拱碹为半圆形纵联式结构，碹脸、拱眉与侧墙取平。跨径均为13.00米。', '', 12, NULL, NULL, '', 8, 1, 8, 1, '黄山市屯溪区', '块石', 50, 64, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (876, '六安道桥', '桥面略显圆弧形，桥上无栏杆，桥面宽3.80米，桥长10.00米。侧墙用料石砌筑，上顶有单层较厚的仰天石。桥台是燕翅形，前墙长约5.00米。拱碹用不规则石料砌筑，属于半圆形纵联式结构，碹脸外边有拱眉石，拱眉与侧墙平。跨径5.50米。', '', 12, NULL, NULL, '', 8, 1, 10, 1, '安徽省六安市，跨沟渠(排水沟)上', '石料（料石、不规则石料）', 50, 65, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (877, '叶家桥', '桥面中部(中孔上)高起，两端是坡道。两侧有节间式青石栏杆，每侧有望柱12根，栏板11块，抱鼓石2块。桥面宽8.00米，桥长54.50米。侧墙用料石砌筑，上顶有双层仰天石组成的金边线。桥台两端有燕翅墙，前墙长9.20米。桥墩上游端是尖形，下游端是方形，拱碹是半圆形镶边纵联式结构，碹脸外边有拱眉石，拱眉凸出于碹脸，又凸出于侧墙。中孔跨径8.00米，次边孔跨径7.00米，边孔跨径6.00米。东面各孔拱碹以上两边的侧墙上各有一对石雕龙头，西面对应位置上各有一对龙尾。', '', 12, NULL, NULL, '', 10, 1, 10, 1, '马鞍山市当涂县丹阳镇跨丹阳河上', '青石、料石', 50, 66, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (878, '宿州三环桥', '三环桥是一座3孔石拱桥。桥面是圆弧形，无栏杆。桥面宽4.00 米，桥长24.50米。 侧墙用料石砌筑，上顶有单层仰天石。桥台是燕翅形，前墙长约 5.20米。桥墩上游端是尖形，下游端是方形，中孔跨径4.50米。', '', 12, NULL, NULL, '', 7, 1, 7, 1, '宿州市埇桥区，跨望洲河上', '料石', 50, 67, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (879, '众善桥', '众善桥是一座5孔等跨径石拱桥。桥塊和桥面上铺砌青石板，全桥为平面，原有桥栏杆被更换，桥面宽数据暂缺，桥长37.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是燕翅形。桥墩上游端是尖形，下游端是方形，跨径均为5.50米。', '', 12, NULL, NULL, '', 8, 1, 8, 1, '宿州市泗县，跨石梁河上', '青石板、料石', 50, 68, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (880, '钱家桥', '钱家桥是一座3孔石拱桥。桥塊和桥面纵向铺砌花岗岩条形石板，桥面呈圆弧形。两侧有节间式栏杆，栏板上雕刻狮子、飞蝶、龙、花卉等图案。桥面宽5.00米，桥梁全长31.50米。侧墙用花岗岩条形石板砌筑，上顶有双层仰天石组成的金边线。桥台两侧有燕翅墙，前墙长6.20米。桥墩两端是尖形。拱碹是半圆框形纵联式结构，碹脸外边有拱眉石，拱眉凸出于碹脸，拱眉与侧墙齐平。中孔跨径10.00米，边孔跨径7.00米。', '', 12, NULL, NULL, '', 10, 1, 10, 1, '铜陵市枞阳县', '花岗岩条形石板', 50, 69, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (881, '绩溪来苏桥', '今存来苏桥是一座5孔石板梁桥。桥面略显弧形，两侧有节间式石栏杆，望柱与栏板齐平。桥面宽4.00米，桥长40.00米。侧墙用料石砌筑，上顶有单层仰天石组成的金边线。桥台两侧有较高的燕翅墙，前墙长5.20米。桥墩两端均为尖形，端部较高，尖端的立面，上面长于下面，桥墩厚数据暂缺，桥墩长数据暂缺。拱碹是半圆形纵联式结构，无拱眉。跨径均为4.45米。', '', 12, NULL, NULL, '', 10, 1, 10, 1, '宣城市绩溪县', '石材（料石）', 50, 70, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (882, '杨川桥', '杨川桥是一座单孔石拱桥。桥面略显圆弧形，无栏杆，桥面宽数据暂缺，桥长数据暂缺。侧墙用垮石砌筑，上顶有单层较厚的仰天石。桥台是燕翅形。拱碹用不规则石料砌筑，属于半圆形纵联式结构，碹脸外边有拱眉石，拱眉与侧墙平。跨径9.00米。', '', 12, NULL, NULL, '', 8, 1, 10, 1, '宣城市绩溪县云川村，跨龙溪河的支流云川上', '垮石、不规则石料', 50, 71, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (883, '中王桥', '中王桥是一座5孔石拱桥。桥上无栏杆，桥面宽6.00米，桥长 74.00米。 侧墙用块石砌筑，上顶有单层仰天石。桥台是燕翅形，前墙长7.20 米。桥墩上游端是尖形，下游端是方形，拱碹是半圆框形纵联式结构， 碹脸外边有拱眉，拱眉凸出于碹脸，又凸出于侧墙。中孔跨径10.00 米，次边孔跨径9.00米，边孔跨径8.00米。', '', 12, NULL, NULL, '', 8, 1, 10, 1, '宣城市绩溪县', '块石', 50, 72, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (884, '乐成桥', '乐成桥是一座11孔石拱桥。桥面略显圆弧形，两侧有节间式石栏杆，桥面宽6.20米，桥长156.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是燕翅形。桥墩上游端是尖形，下游端是方形，桥孔净跨度尺寸不一，最大跨径11.50米，最小跨径6.50米。', '', 12, NULL, NULL, '', 8, 1, 8, 1, '宣城市旌德县三溪镇三溪村，跨三溪河上', '石材（料石）', 50, 73, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (885, '旌德三溪桥（又名南河桥）', '桥面宽7.00米，桥面长149.00米，桥梁全长156.00米。侧墙用条形石板砌筑，上顶有双层仰天石组成的金边线，桥台为凹字形，前墙长7.00米。两侧有块石砌筑的护岸墙。桥墩两端是方形，拱碹是半圆框形纵联式结构，每孔由8道纵联石和9块碹脸石构成，框内砌筑拱碹石。中孔龙门上有石雕龙头，各孔碹脸外边皆有拱眉石，拱眉凸出于碹脸，拱眉与侧墙取平。中孔跨径11.60米，边孔跨径9.60米。', '', 12, NULL, NULL, '', 8, 1, 8, 1, '宣城市旌德县三溪镇', '青石板（桥堍和桥面）、条形石板（侧墙）、块石（护岸墙）', 50, 74, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (886, '飞鲤桥', '桥面中部高起为平面，两端是阶梯式坡道。两侧有石栏杆，地伏是矩形断面。桥面宽5.50米，桥长25.00米。侧墙用料石砌筑，上顶有单层仰天石，上半部是垂直平面，下半部是斜面。桥台是凹字形，前墙长约5.50米。桥墩两端是方形，桥墩厚1.50米，桥墩长5.50米。拱碹是半圆形纵联分段并列式结构，碹脸外有拱眉石。中孔跨径4.70米，边孔跨径4.20米。', '', 12, NULL, NULL, '', 8, 1, 8, 1, '宣城市郎溪县', '石材（料石）', 50, 75, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (887, '河沥溪桥', '今存河沥溪桥是一座9孔石拱桥。全桥(桥塊和桥面)为平面，桥栏杆无存，地伏亦无存。桥面宽7.00米，桥长148.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台的前墙建在石板砌筑的河岸上。桥墩的下部两端均为圆形，周圈宽出拱脚，桥墩上部(与拱脚同宽)的两端是尖形，拱碹是半圆形框形纵联式结构，碹脸外边有拱眉石，拱眉凸出于碹脸，又凸出于侧墙。跨径5.50—13.80米。', '', 12, NULL, NULL, '', 8, 1, 8, 1, '宁国市', '石材（料石、石板）', 50, 76, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (888, '项家河桥（原名陈仙桥）', '桥塊上铺砌条形石板，桥面是石板梁，无栏杆。桥面宽2.14米，桥梁全长(包括引道)57.50米。桥台是凹字形。桥墩两端是方形，桥墩厚0.90米，桥墩长2.50米。跨径3.50—5.00米。', '', 12, NULL, NULL, '', 8, 2, 10, 1, '桐城市项家河村', '石板', 50, 77, '2026-04-28 23:07:54', '2026-04-28 23:36:26');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (889, '紫来桥', '紫来桥又名“桐溪桥”，又称“秋瓦石桥”。今存桥梁由一座单孔石拱桥和4孔悬臂式石板梁桥对接而成。东端的石拱桥桥面为平面，西端有阶梯式坡道与石板梁桥面相连，两侧设有节间式石栏杆，桥面宽4.50米。其桥台为凹字形，前墙长约5.00米，拱碹为半圆形纵联式结构，无拱眉，跨径7.80米。西端的石板梁桥桥面为石板梁，两端下面各有一层悬臂式石板，桥面宽4.50米，桥梁全长48.00米。桥台亦为凹字形，桥墩两端为方形，厚3.30米，长6.50米，跨径均为6.70米。', '', 12, NULL, NULL, '', 8, 1, 8, 1, '桐城市跨龙眠河上', '石材', 50, 78, '2026-04-28 23:07:54', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (890, '锁山桥', '桥面每孔5块花岗岩石板梁，桥面宽2.20米，桥长17.60米。桥台是凹字形，前墙长2.55米，桥墩两端是方形，上顶有两层单悬臂石板。桥墩厚90厘米，上顶有两层双悬臂石板，桥墩长2.55米。跨径均为5.00米。', '', 12, NULL, NULL, '', 10, 2, 10, 1, '广德市四合乡水塘下村', '花岗岩', 50, 79, '2026-04-28 23:07:54', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (891, '绩溪南山桥', '南山桥是一座3孔石板梁桥，桥塊上满铺石板，桥面每孔由7块石板梁组成。两侧有节间式石栏杆，每侧有6根望柱，有5块石栏板，每块栏板下面垫两块方形石块，无地伏，望柱立于石板梁上。桥面宽2.00米，桥长15.00米。桥台两侧有燕翅墙，前墙长约3.0米。桥墩两端均为尖形，桥墩厚0.90米，桥墩长2.55米。中孔跨径4.10米，边孔跨径3.70米。', '', 12, NULL, NULL, '', 8, 2, 8, 1, '宣城市绩溪县', '石板', 50, 80, '2026-04-28 23:07:54', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (892, '永济桥', '桥面略显弧形，两侧有节间式青石栏杆，每侧有望柱16根，栏板15块，两端是抱鼓石。望柱上有狮子、猴子，栏板为实体板，两面皆有雕刻花饰。没有连续的地伏石，望柱下面有一块方形石板，栏板的两端搭在石板上，栏板下面有缝隙，可以排除雨水。桥面宽6.25米，桥面长42.50米，全长55.00米。侧墙是用青石板砌筑，上顶有双层仰天石组成的金边线。桥台是凹字形，前墙长7.50米。拱碹是半圆形纵联式结构，碹脸龙门上有龙头，碹脸外边有拱眉石，拱眉凸出于碹脸，又凸出于侧墙。跨径16.50米。', '', 15, NULL, NULL, '', 7, 1, 7, 1, '济南市平阴县浪溪河上', '青石料', 50, 51, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (893, '济宁卞桥（双月桥）', '今存卞桥是一座3孔石拱桥。桥塊和桥面上铺砌石板面层，桥面略显圆弧形。两侧有节间式石栏杆，每侧有望柱12根，栏板11块，栏杆两端各有一只蹲踞在须弥座上的大石狮子，两侧的狮子面相对，在端望柱内侧各有一块小型抱鼓石。望柱的柱头是方形莲捧头平顶式，栏板是寻杖下镂空式，板面上雕刻人物、花卉、禽兽等浮雕。地伏是矩形断面。桥面宽6.00米，桥梁全长24.00米。桥梁两端各有35.00米长的引道。翼墙和侧墙是用条形石板砌筑，上面是由双层仰天石组成的金边线。桥台是燕翅形，前墙长7.20米。桥墩很厚，下部为梭形(两端为尖形),上部两端为方形，桥墩厚3.00米，桥墩长10.50米。拱碹是马蹄形框形纵联式结构，每孔由三道纵联石(龙门碹石)和4段碹脸石构成框形结构，框内是纵联拱碹石，拱脚处拱碹厚50厘米，拱顶处拱碹厚40厘米，碹脸外边有拱眉石，拱眉凸出于碹脸，拱眉与侧墙取平。各孔的拱顶上(金边线下),两面各有一个伸出约60厘米的石雕龙头。中孔跨径4.50米，边孔跨径3.50米。', '', 15, NULL, NULL, '', 7, 1, 7, 1, '山东省济宁市泗水县城东泉林镇卞桥村东，跨泗水河上', '石材（石板、条形石板）', 50, 52, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (894, '济宁泗河桥', '泗河桥是一座7孔石拱桥。桥面上铺砌条形石板为平面，桥面宽8.65米，桥长72.00米。侧墙是用料石砌筑，上顶有单层仰天石。桥台是燕翅形，前墙长约9.90米。桥墩上游端是尖形，下游端是方形。拱碹是半圆形纵联式结构，碹脸外边有拱眉石，拱眉凸出于碹脸，拱眉与侧墙齐平。跨径7.00—8.00米不等。各孔碹脸上部两侧各有一个石雕兽头，各孔碹脸下部之间各有一个石雕兽头。', '', 15, NULL, NULL, '', 9, 1, 10, 1, '济宁市兖州市城南五里处跨泗河上', '条形石板、料石', 50, 53, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (895, '蒙阴迎仙桥', '迎仙桥是一座3孔石拱桥。桥塊和桥面铺砌条形石板，全桥为平面，两侧有节间式石栏杆，望柱为方形柱头，栏板为实体板，无地伏，桥栏杆置于仰天石上。桥面宽5.35米，桥长30.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台两侧有石砌燕翅墙，前墙长6.50米。桥墩两端为尖形，周围宽出拱脚约15厘米，上部的尖端高出拱脚许多。中孔的拱碹是尖形(实际上拱顶是小圆形)镶边纵联式结构，龙门碹是纵联石，两边各有两段碹脸石，碹脸外边有拱眉石，拱眉与侧墙平。边孔的拱碹是卵形(拱顶的圆弧较长，拱形近似三心圆弧形)框形纵联式结构，均由4道纵联式和5块碹脸石构成，碹脸外边有拱眉石，拱眉与侧墙平。中孔跨径7.20米，边孔跨径6.60米。在两个桥墩以上的侧墙上(仰天石以下)各有一个石雕龙头。', '', 15, NULL, NULL, '', 8, 1, 8, 1, '临沂市蒙阴县北楼村', '条形石板、料石', 50, 54, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (896, '小卞桥', '小卞桥是一座3孔石拱桥。桥塊和桥面上铺砌石板面层，桥面大致为平面。两侧有节间式石栏杆，每侧有望柱12根，栏板11块，栏杆两端各有一只石狮子。桥面宽3.90米，桥长16.30米。翼墙和侧墙用条形石板砌筑，上面有单层仰天石组成的金边线。桥台两侧有燕翅墙，前墙长4.10米。桥墩较厚，两端是尖形，桥墩厚1.80米，桥墩长5.90米。跨径均为3.00米。', '', 15, NULL, NULL, '', 8, 1, 8, 1, '临沂市平邑县卞桥镇东卞桥村东南', '石材', 50, 55, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (897, '河阳桥', '河阳桥是一座3孔石拱桥。桥面为弧形，铺砌条形石板，两侧有节间式石栏杆，每侧有望柱8根，栏板7块，抱鼓石2块。桥面宽6.50米，桥长18.00米。侧墙用块石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长7.00米。桥墩两端是方形，桥墩厚约1.00米。拱碹是半圆形纵联式结构，无拱眉。中孔跨径4.80米，边孔跨径3.60米。', '', 15, NULL, NULL, '', 8, 1, 8, 1, '临沂市沂南县大庄镇河阳北村，跨沂河支流玉交沟上', '石材（条形石板、块石）', 50, 56, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (898, '信量桥', '信量桥是一座11孔等跨径石拱桥。桥塊和桥面上铺砌条形石板，全桥大致是平面，两侧有节间式石栏杆。桥面全宽4.60米，净宽3.50米，桥面长40.00米，桥全长57.70米。侧墙用料石砌筑，上顶有单层仰天石。桥台属燕翅形，前墙长5.80米。桥墩两端为尖形。拱碹是类似三心圆弧形纵联式结构，拱圈厚40厘米，龙门上各有一只石雕龙头，碹脸外边镶有拱眉石。跨径均为4.20米。', '', 15, NULL, NULL, '', 10, 1, 10, 1, '临沂市沂南县辛集乡苗家曲村，跨潮沽河上', '条形石板、料石', 50, 57, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (899, '青州万年桥', '万年桥是一座7孔等跨径石拱桥。桥塊和桥面上铺砌花岗岩石板，桥面大致为平面。两侧有节间式青石栏杆，两端有抱鼓石，无通长地伏，望柱安装在一块长方形石板上，栏板的两端搭在方形石板上，栏板下面有空隙，可以排泄雨水。栏板上雕有“二十四孝图”“松鹤同春”“张良圯上遇黄石公”。望柱头上雕宝瓶、狮子。桥面宽9.40米，桥长86.70米。侧墙用青石板砌筑，上顶有双层仰天石。桥台是凹字形，端墙后部有燕翅墙，前墙长10.30米。桥墩两端是尖形。拱碹是半圆形纵联式结构，碹脸外边有拱眉石，拱眉凸出于碹脸，拱眉与侧墙平。跨径均为5.30米。', '', 15, NULL, NULL, '', 8, 1, 8, 1, '青州市城北门外，跨南阳河上', '花岗岩石板（桥堍和桥面）、青石（栏杆、侧墙）', 50, 58, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (900, '兴隆桥', '兴隆桥是一座单孔石拱桥。桥面中部(拱顶上)高起为平面，两端是阶梯式坡道。两侧有节间式石栏杆。桥面宽2.00米，桥长5.50米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形。拱碹是半圆形纵联分段并列式结构，有拱眉，拱眉凸出于碹脸，拱眉与侧墙平。跨径3.85米。', '', 15, NULL, NULL, '', 8, 1, 8, 1, '滕州市', '石材（料石）', 50, 59, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (901, '枣庄罗锅桥', '罗锅桥是一座单孔石拱桥。桥塊和桥面上铺砌青石板，桥面隆起较高，桥上是坡道，无栏杆。桥面宽6.00米，桥长30.00米。侧墙用青石板砌筑，上顶有单层青石仰天石。桥台是凹字形，拱碹是半圆形纵联式结构，无拱眉，跨径7.00米。', '', 15, NULL, NULL, '', 10, 1, 10, 1, '枣庄市薛城区邹坞镇中陈郝村，跨于流经中陈郝村的薛河支流蟠龙河上', '青石板', 50, 60, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (902, '红梅寺桥', '今存红梅寺桥是一座单孔石拱桥。桥面上铺砌花岗岩石板，桥面略显圆弧形。两侧有节间式青石栏杆，下面有青石地伏。桥面宽6.50米。桥长14.50米。侧墙是用料石砌筑，上面有双层仰天石组成的金边线。桥台两侧有燕翅墙，前墙长7.70米。拱碹是纵联式结构，无拱眉，碹脸与侧墙平，西面碹脸上部两边的侧墙上各有一只石雕龙头，东面的对应位置上各有一个龙尾。跨径7.00米。', '', 4, NULL, NULL, '', 10, 1, 10, 1, '长治市红梅寺南面，跨山间排水沟上', '花岗岩石板、青石、料石', 50, 51, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (903, '襄垣通济桥', '桥面铺砌条形石板，桥面为平面。两侧有节间式石栏杆。下面有青石地伏。桥面宽6.40米，桥长11.70米。侧墙用料石砌筑，上面有单层青石仰天石组成的金边线。桥台有燕翅墙，前墙长7.60米。拱碹是半圆形纵联式结构，碹脸外边镶有拱眉石，拱眉凸出于碹脸，拱眉与侧墙平。跨径6.45米，矢高3.20米。', '', 4, NULL, NULL, '', 8, 1, 8, 1, '长治市襄垣县', '条形石板、青石、料石', 50, 52, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (904, '永安桥（桥上桥）', '永安桥又名“桥上桥”，石桥上下重叠。上层桥的桥堍和桥面上铺砌青石板，两侧有砖砌桥栏杆。桥面宽6.20米，桥梁全长50.00米。侧墙用青砖砌筑，上顶有单层青石仰天石。桥台是凹字形，端墙与侧墙为整体。拱碹是半圆形纵联式结构，碹脸用青砖砌筑，无拱眉。下层桥大部分被埋没，仅外露局部碹脸。', '', 4, NULL, NULL, '', 8, 1, 10, 1, '山西省长治市襄垣县侯堡镇桥上村西', '沙石（下层桥镶面）、青石料（上层桥砌筑）、青砖（上层桥镶面、侧墙、碹脸、桥栏杆）、青石板（桥面）、青石（仰天石）', 50, 53, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (905, '永惠桥', '永惠桥是一座单孔石拱桥。桥面铺砌青石板，桥面略显圆弧形。两侧有节间式石栏杆。下面有青石地伏。桥面宽7.50米，桥长28.50米。侧墙用料石砌筑，上面有单层青石仰天石组成的金边线。桥台有燕翅墙，前墙长9.00米。拱碹是半圆形纵联式结构，碹脸外边镶有拱眉石，拱眉凸出于碹脸，拱眉与侧墙平。跨径12.80米。', '', 4, NULL, NULL, '', 10, 1, 10, 1, '长治市襄垣县城北门外，跨甘水河上', '青石板、青石、料石', 50, 54, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (906, '景德桥', '景德桥原名“沁阳桥”，俗称“西大桥”。桥面宽5.90米，桥长33.00米。侧墙用料石砌筑，上面有双层仰天石组成的金边线。桥台是凹字形，端墙的外端有燕翅墙。拱碹为圆弧形并列式结构，由25道拱碹石构成，碹脸外边有拱眉石，拱眉凸出于碹脸，又凸出于侧墙。跨径21.00米。拱碹上面两端各有一个小跨径孔，拱碹是半圆形纵联式结构，碹脸龙门上有石雕龙头。碹脸外边有拱眉石，拱眉凸出于碹脸，又凸出于侧墙。内侧拱脚建在大拱碹上，外拱脚建在桥台上。跨径是3.10米。', '', 4, NULL, NULL, '', 8, 1, 8, 1, '山西省晋城市城西门外跨沁水河上', '料石', 50, 55, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (907, '迎旭桥', '桥上无栏杆，亦无地伏。桥面宽4.90米，桥长18.60米。侧墙用条石砌筑，上顶有单层仰天石，其断面为矩形。桥台利用山脚岩壁开凿而成。端墙外端有燕翅墙。拱碹是圆弧形并列式结构，共有17道拱碹石，碹脸上雕有花饰，龙门上有龙头，碹脸外镶有拱眉石。拱眉凸出于碹脸，又凸出于侧墙。跨径16.50米。', '', 4, NULL, NULL, '', 8, 1, 8, 1, '晋城市大箕乡大箕村，跨大箕河上', '石材（条石、拱碹石）', 50, 56, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (908, '永固桥', '永固桥是一座单孔石拱桥。桥面上铺砌条形石板，桥面略显圆弧形。两侧有节间式青石栏杆，下面有青石地伏。桥面宽6.55米，桥长14.00米。侧墙用料石砌筑，上面有单层仰天石组成的金边线。桥台两侧有燕翅墙，前墙长7.80米。拱碹是半圆形纵联式结构，拱厚30厘米，碹脸外边有拱眉石，拱眉凸出于碹脸，拱眉与侧墙平。跨径7.15米。上游面拱碹的两边侧墙上各有一个龙头，下游面拱碹的两边侧墙上各有一个龙尾。', '', 4, NULL, NULL, '', 8, 1, 8, 1, '晋城市跨丹河上', '条形石板、青石、料石', 50, 57, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (909, '泽州周村桥', '周村桥是一座单孔石拱桥。桥面略显弧形，两侧有节间式石栏杆。桥面宽5.50米，桥长19.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形。拱碹是圆弧形并列式结构，碹脸、拱眉与侧墙平。跨径8.30米。桥台上各有一个小跨径孔，拱碹是半圆形，无拱眉。跨径90厘米。', '', 4, NULL, NULL, '', 10, 1, 10, 1, '晋城市泽州县周村镇', '料石', 50, 58, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (910, '平遥惠济桥', '惠济桥是一座9孔等跨径石拱桥。桥塊和桥面上铺砌条形石板，两侧有节间式石栏杆，桥面宽7.40米，桥长80.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长7.50米。桥墩两端与拱脚齐平，桥墩长7.50米。拱碹是半圆形纵联式结构，有拱眉，拱眉凸出于碹脸，拱眉与侧墙平。', '', 4, NULL, NULL, '', 8, 1, 8, 1, '山西省晋中市平遥县', '条形石板、料石', 50, 59, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (911, '高河桥', '今存高河桥是一座5孔石拱桥。桥面上铺砌不规则石板。两侧的栏杆无存，青石地伏犹存。桥面宽9.80米，桥长68.30米。侧墙用乱石砌筑，上面有单层矩形断面的仰天石。桥台两侧有燕翅墙，前墙长11.00米。桥墩上游端是尖形，下游端是方形。拱碹是半圆纵联式结构，碹脸与侧墙取平。跨径由北向南依次是8.50米、9.20米、10.00米、9.20米、8.60米。', '', 4, NULL, NULL, '', 7, 1, 10, 1, '临汾市', '石材（不规则石板、青石、乱石）', 50, 60, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (912, '霍州安济桥', '安济桥是一座3孔石拱桥。桥塊和桥面上铺砌条形石板，桥面略显圆弧形。两侧有节间式石栏杆，下面有青石地伏，桥面宽6.70米，桥长45.00米。桥塊翼墙和侧墙用料石砌筑，上顶有单层仰天石组成的金边线。桥台两侧有燕翅墙，桥墩上游端是尖形，下游端是方形。拱碹是半圆形，上半部是纵联式结构，龙门上各有一个龙头，无拱眉，碹脸与侧墙平。下半部分是一段并列式结构，碹脸外面有拱眉。中孔跨径5.00米，边孔跨径4.20米。', '', 4, NULL, NULL, '', 8, 1, 8, 1, '山西省霍州市跨南涧河上', '条形石板、青石、料石', 50, 61, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (913, '交里桥', '交里桥是一座7孔石拱桥。桥堍和桥面上铺砌条形石板，桥面大致为平面。两侧有节间式石栏杆，无地伏，桥栏杆置于仰天石上。桥面宽7.70米，桥长141.00米。桥堍翼墙和侧墙用料石砌筑，上顶有单层仰天石组成的金边线。桥台是燕翅形，桥墩上游端是尖形，下游端是方形。拱碹是半圆形纵联式结构，碹脸外边有拱眉石，拱眉凸出于碹脸，拱眉与侧墙取平。跨径均为8.00米。', '', 4, NULL, NULL, '', 8, 1, 8, 1, '山西省临汾市曲沃县浍河上', '条形石板、料石', 50, 62, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (914, '通惠桥', '通惠桥（又名京安桥）是一座5孔石拱桥。桥面上铺砌花岗岩石板，桥面大致为平面。两侧有节间式青石栏杆，下面有青石地伏。桥面宽7.00米，桥长62.00米。翼墙和侧墙是用条形石板砌筑，上面有单层仰天石。桥台两侧有燕翅墙，前墙长7.80米。桥墩两端是尖形。拱碹是半圆形纵联式结构，碹脸外边有拱眉，拱眉凸出于碹脸，跨径均为7.40米。', '', 4, NULL, NULL, '', 10, 1, 10, 1, '临汾市襄汾县古城镇北街与京安村之间豁都峪涧河上', '花岗岩石板、青石、条形石板', 50, 63, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (915, '广义桥', '广义桥是一座单孔石拱桥。桥面铺砌条形石板，桥面为平面。两侧有节间式石栏杆，每侧有22根望柱，栏板21块，栏杆端部有抱鼓石，望柱的柱头有雕兽，也有圆球形，石件多有残缺损。下面有青石地伏。桥面宽6.75米，桥长24.40米。侧墙用料石砌筑，上面有单层青石仰天石组成的金边线。桥台有燕翅墙，前墙长8.00米。拱碹是半圆形纵联式结构，碹脸外边镶有拱眉石，拱眉凸出于碹脸，拱眉与侧墙平。跨径14.00米。', '', 4, NULL, NULL, '', 10, 1, 10, 1, '山西省朔州市右玉县', '条形石板、青石、料石', 50, 64, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (916, '平丰桥', '今存平丰桥是一座单孔砖石混合结构拱桥。桥塊和桥面上铺砌青石板，桥面大致是平面。两侧有节间式青石栏杆，下面有青石地伏。桥面宽7.00米，桥长50.00米。侧墙的下部用料石砌筑，上部用砖材砌筑，上面有单层青石仰天石组成的金边线。桥台有燕翅墙，前墙长8.20米。拱碹是半圆形，主拱圈用砖材砌筑，两端是石碹脸，无拱眉，碹脸与侧墙取平。跨径5.00米。', '', 4, NULL, NULL, '', 8, 1, 8, 1, '朔州市右玉县，跨二道沟上', '青石板（桥塊、桥面、栏杆、地伏、仰天石）、料石（侧墙下部）、砖材（侧墙上部、主拱圈）', 50, 65, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (917, '太原豫让桥', '豫让桥是一座单孔石拱桥。桥面上铺砌青石板，桥栏杆无存，青石地伏尚存。桥面宽5.20米，桥面长9.20米。侧墙是用青石板砌筑，上顶有单层仰天石。桥台被埋没，桥孔大部分被埋没，拱碹可能是半圆形纵联式结构，无拱眉。跨径6.50米。', '', 4, NULL, NULL, '', 8, 1, 8, 1, '太原市赤桥村，在晋祠以东，跨晋水北河上', '青石板', 50, 66, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (918, '原平普济桥', '普济桥是一座单孔类似敞肩式石拱桥。桥塊和桥面上铺砌青石，桥面纵断呈正圆弧形竖曲线，两侧有节间式石栏杆，望柱是平顶方形柱头，栏板是实体板，下面有矩形断面的地伏石。桥面宽8.00米，净宽6.70米，桥面长24.20米，全长30.00米。侧墙用条形石板砌筑，上面有单层仰天石组成的金边线。桥台是凹字形，前墙长8.00米。端墙很长，其外端有燕翅墙。拱碹是圆弧框形纵联式结构，碹脸龙门上有石雕龙头。碹脸上雕刻花饰图案，碹脸外边有拱眉石，拱眉凸出于碹脸，又凸出于侧墙。跨径20.00米。拱碹上面两端各有两个小跨径孔，拱碹均为半圆形纵联式结构，碹脸龙门上有石雕龙头。碹脸外边有拱眉石，拱眉凸出于碹脸，又凸出于侧墙。内侧的小孔建在大拱碹上，外侧小孔建在大拱碹两端，其内拱脚建在大拱碹上，外拱脚建在桥台上。内侧小孔的跨径是1.80米，外侧小孔的跨径是3.20米。桥梁的南北两端各有一段铺砌青石板的路堤，南堤长28.5米，北堤长34.5米。', '', 4, NULL, NULL, '', 8, 1, 8, 1, '原平市城北嶂阳镇南门外跨护镇河上', '青石（桥塊、桥面、路堤）、条形石板（侧墙）', 50, 67, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (919, '鱼沼飞桥', '鱼沼飞桥是一座平面为十字形4孔石板梁桥，中间是一个方形桥中墩，长和宽均为6.00米。桥中墩东西两边的桥通称为正桥，桥中墩南北两侧的桥通称为翼桥。正桥是一座双孔石梁桥。桥面大致为平面，桥面宽6.00米，全长19.60米。桥台即水池的边岸。跨径均为3米。翼桥均系单孔石梁桥，桥面有明显纵坡(内端高于外端),桥面宽均为3.80米，桥长各为6.00米(南北全长19.50米)。桥台即水池的边岸。全桥的石板梁上铺墁方砖面层，全桥两侧有汉白玉节间式石栏杆。', '', 4, NULL, NULL, '', 5, 2, 10, 1, '太原市晋祠圣母殿内，跨于殿前的水池上', '石板梁、方砖、汉白玉', 50, 68, '2026-04-28 23:07:54', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (920, '安贞桥', '安贞桥是一座单孔石拱桥。桥面上铺砌条形石板，两侧有石板栏杆。桥面宽3.80米，桥长33.60米。侧墙用料石砌筑。上顶有单层仰天石。桥台建在山脚岩石上，形状不规则。拱碹是半圆形纵联式结构，有拱眉，拱眉、碹脸与侧墙平。跨径27.00米。', '', 19, NULL, NULL, '', 10, 1, 10, 1, '广东省河源市紫金县黄塘镇拱桥村', '石材（条形石板、料石）', 50, 51, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (921, '博罗通济桥', '通济桥是一座双孔石拱桥。桥塊和桥面上铺砌条形石板，两侧有节间式石栏杆，桥面宽6.00米，桥长27.50米，侧墙用料石砌筑，上顶有单层仰天石。桥台是燕翅形。桥墩两端是尖形。拱碹是半圆形纵联式结构，中孔龙门上有石雕龙头，有拱眉，拱眉凸出于碹脸，拱眉与侧墙平。跨径均为17.80米。', '', 19, NULL, NULL, '', 8, 1, 8, 1, '惠州市博罗县，跨松源河上', '条形石板、料石', 50, 52, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (922, '见龙桥', '见龙桥是一座单孔石拱桥。桥面为平面，两端桥塊是阶梯式坡道。全桥无栏杆。桥面宽4.20米，桥长21.00米。侧墙用花岗岩石板砌筑，上顶有单层仰天石。桥台是凹字形，拱碹是半圆形纵联式结构，无拱眉，碹脸与侧墙平。跨径6.50米。', '', 19, NULL, NULL, '', 10, 2, 10, 1, '江门市新会区', '石板、块石', 50, 53, '2026-04-28 23:07:54', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (923, '步天桥', '步天桥是一座3孔厚拱厚墩重型石拱桥。全桥为平面，两侧有节间式石栏杆，望柱均为方形柱头，栏板是实体板，无地伏，桥栏杆置于仰天石上。桥面宽6.20米，桥长66.50米。侧墙用花岗岩石板砌筑，上顶有单层仰天石。桥台前墙与石板砌筑的河岸相连。桥墩上游端是尖形，下游端是方形，拱碹是半圆形纵联式结构，无拱眉，碹脸与侧墙平。跨径9.20米。', '', 19, NULL, NULL, '', 10, 1, 10, 1, '江门市新会区', '花岗岩', 50, 54, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (924, '惠济桥', '惠济桥是一座3孔石拱桥。桥面中部(中孔上)高起为平面，两端是阶梯式坡道。两侧有节间式石栏杆。桥面宽3.00米，桥长26.00米。侧墙使用料石砌筑，上顶有单层仰天石。桥台平面是凹字形，桥台立面是梯形，前墙上顶长5.50米，底部长7.00米，端墙后部有燕翅墙。桥墩两端是尖形，拱碹是半圆形纵联式结构，有拱眉，拱眉凸出于碹脸，拱眉与侧墙平。中孔跨径7.00米，边孔跨径6.00米。', '', 19, NULL, NULL, '', 8, 1, 10, 1, '鹤山市沙坪镇玉桥村，跨沙坪河上', '料石', 50, 55, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (925, '砥柱桥', '砥柱桥是一座4孔石拱桥。南二孔上的桥面高起为平面，北二孔上的桥面较低，也是平面，两段桥面之间有坡道相连，南北两桥塊上面均为坡道。全桥两侧有石板栏杆。桥面宽3.00米，桥长83.50米。侧墙用块石砌筑，上顶有单层仰天石。桥台建在山脚岩石上。桥墩用块石砌筑，平面形状不规则。南二孔拱碹是半圆形纵联式结构，北二孔拱碹是圆弧形纵联式结构，无拱眉。跨径均为12.50米。', '', 19, NULL, NULL, '', 8, 1, 10, 1, '梅州市梅县区姚尧镇显朝村，跨山涧水沟上', '块石、石板', 50, 56, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (926, '接龙桥', '接龙桥是一座8孔厚拱厚墩重型石拱桥。桥塊和桥面上为平面，用137块青石板铺砌，两侧有节间式石栏杆。桥面宽3.60米，桥长60.28米。侧墙用料石砌筑，上顶有单层仰天石。桥台是带燕翅形，桥墩两端是尖形，拱碹为半圆形纵联式结构，碹脸外边有拱眉石，拱眉凸出于碹脸，又凸出于侧墙。跨径均为7.00米。', '', 19, NULL, NULL, '', 8, 1, 10, 1, '南雄市田边水村', '青石板、料石', 50, 57, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (927, '龙津桥', '现存龙津桥是一座双孔石拱桥。桥面为平面，桥塊上是阶梯式坡道，两侧有节间式石栏杆，每侧有14根望柱(桥面上10根，桥塊上各2根),栏板13块(桥面上9块，桥塊上各2块),抱鼓石2块。无地伏，桥栏杆置于仰天石上。桥面宽4.00米，桥长55.00米。侧墙用花岗岩石板砌筑，上顶有单层仰天石。桥台是凹字形，端墙很长。桥墩很厚，上游端为尖形，下游端是方形。拱碹是半圆形纵联式结构，碹脸外边有拱眉石，拱眉凸出于碹脸，拱眉与侧墙取平。跨径5.20米。', '', 19, NULL, NULL, '', 8, 1, 8, 1, '广州市石楼镇大岭村', '花岗岩石板', 50, 58, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (928, '洋溪桥', '桥面中部(拱顶上)高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆。桥面宽2.58米，桥塊端宽2.90米，桥长12.20米。侧墙用料石砌筑，上顶有双层仰天石。桥台是凹字形，下部的前面和两边有出台，前墙长3.00米。拱碹是半圆形纵联分段并列式结构，碹脸外边有拱眉石，拱眉与侧墙平。跨径均为4.90米，桥台间距离4.00米。', '', 19, NULL, NULL, '', 8, 1, 10, 1, '河源市龙川县老隆镇', '料石', 50, 59, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (929, '甜济桥', '甜济桥是一座单孔石拱桥。桥面中部为平面，两端是阶梯式坡道，两侧有节间式石栏杆，桥面宽3.00米，桥长21.20米。侧墙用料石砌筑，上顶有单层仰天石。桥台建在山脚岩石上。拱碹是半圆形纵联式结构，有拱眉，拱眉凸出于碹脸，拱眉与侧墙平。跨径12.20米。', '', 19, NULL, NULL, '', 8, 1, 10, 1, '梅州市梅县区，跨西枝江上游的泔溪河上', '料石', 50, 60, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (930, '聚奎桥', '聚奎桥是一座单孔石拱桥。全桥为平面。两侧有块石砌筑的桥栏杆。桥面宽5.50米，桥长68.00米。侧墙用块石砌筑，上顶有单层仰天石。桥台建在山脚岩石上。拱碹是圆形纵联分段并列式结构，有拱眉，拱眉凸出于碹脸，又凸出于侧墙。跨径47.60米。', '', 19, NULL, NULL, '', 10, 1, 10, 1, '梅州市梅县区松源镇桥背村', '块石', 50, 61, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (931, '天成桥', '天成桥是一座单孔石拱桥。桥面中部高起为平面，两侧有石板栏杆，两端是坡道，坡道上无栏杆。桥面宽5.50米，桥长54.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台建在山脚岩石上，不规则。拱碹是半圆形纵联式结构，有拱眉，拱眉凸出于碹脸，拱眉与侧墙平。跨径47.60米。', '', 19, NULL, NULL, '', 10, 1, 10, 1, '梅州市梅县区松源镇宝坑村', '石材（料石）', 50, 62, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (932, '丰顺普济桥', '普济桥是一座7孔石拱桥。桥面大致为平面，两侧有节间式石栏杆。桥面宽3.00米，桥长92.00米。侧墙用料石砌筑。上顶有单层仰天石。桥台是燕翅形。桥墩上游端是尖形，下游端是方形，桥墩厚2.20米，桥墩长4.50米。拱碹是半圆形纵联式结构，有拱眉，碹脸、拱眉与侧墙平。跨径均为11.50米。', '', 19, NULL, NULL, '', 8, 1, 10, 1, '梅州市丰顺县丰良镇', '料石', 50, 63, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (933, '永兴桥', '永兴桥是一座3孔石拱桥。桥面中部(中孔上)高起为平面，边孔上及桥堍上是缓坡面，两侧有节间式石栏杆，每侧有望柱20根，栏板19块，地伏为矩形断面。桥栏杆两端与河岸上的石栏杆相连。桥面宽3.40米，桥长50米。侧墙用花岗岩石板砌筑，上顶有单层矩形断面的仰天石。桥台是凹字形，也用花岗岩石板砌筑，前墙长约3.70米。桥墩也用花岗岩石板砌筑，两端是方形，拱碹是半圆形纵联式结构，碹脸外边有拱眉石，拱眉凸出于碹脸，拱眉与侧墙平。中孔跨径16.00米，边孔跨径15.00米。', '', 19, NULL, NULL, '', 8, 1, 8, 1, '深圳市沙井镇新桥村', '花岗岩石板', 50, 64, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (934, '广济桥', '桥面宽5.00米，桥梁全长517.95米。桥台是凹字形，端墙很短，两边与石板砌筑的河岸相连。桥墩很厚又长，桥墩两端的立面是多面形(平面为多边折线形)。桥墩厚6.00—13.00米，桥墩长22.00—25.00米。跨径11.10—14.10米。历史上曾因河道中间水流湍急未能合龙而以舟代之，桥分两段，每段各12孔。', '', 19, NULL, NULL, '', 7, 2, 5, 1, '潮州市湘安区潮州镇跨韩江上', '花岗岩石板梁、石板', 50, 65, '2026-04-28 23:07:54', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (935, '渡头江桥', '渡头江桥是一座23孔石板梁桥。桥面每孔是两块条形石板，无栏杆，桥面宽1.80米，桥长89.60米。桥台建在河岸基岩上，桥墩用3层石板垒砌而成，桥墩厚80—90厘米，桥墩长2.80米。跨径3.00—4.00米。', '', 19, NULL, NULL, '', 8, 2, 8, 1, '桂林市兴安县跨湘江上', '石板', 50, 66, '2026-04-28 23:07:54', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (936, '三步江桥', '今存三步江桥是一座3孔石板梁桥。桥面每孔是2块花岗岩石板梁，桥上无栏杆，桥面宽1.10米，桥长12.00米。桥台是凹字形，前墙长2.00米，桥墩是两块方形石柱，立于石板基础上，上顶有一块石板帽梁。桥墩厚0.90—1.00米，桥墩长2.00米。跨径3.50—4.00米。', '', 19, NULL, NULL, '', 10, 2, 10, 1, '钦州市灵山县', '花岗岩', 50, 67, '2026-04-28 23:07:54', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (937, '竹行桥', '桥面是花岗岩石板梁，每孔4块石板梁，全桥为平面，桥上无栏杆，桥面宽2.26米，桥长19.00米。桥台两侧有燕翅墙，桥墩两端为尖形，中2孔跨径4.66米，边孔跨径4.25米。', '', 19, NULL, NULL, '', 8, 2, 10, 1, '钦州市灵山县灵城镇', '花岗岩石板', 50, 68, '2026-04-28 23:07:54', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (938, '鹤泉桥', '鹤泉桥是一座15孔石拱桥(实际上属于涵洞)。桥塊和桥面上铺砌石板，全桥为平面，两侧有矮石板栏杆。桥面宽1.50米，桥长60.00米。侧墙用块石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长2.00米。桥墩两端是方形，桥墩厚1.20米，桥墩长2.00米。拱碹是半圆形纵联式结构，无拱眉，跨径均为2.60米。', '', 20, NULL, NULL, '', 8, 1, 8, 1, '靖西市新靖镇鹤泉村', '石板、块石', 50, 51, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (939, '观音桥', '观音桥是一座单孔石拱桥。桥上无栏杆。桥面宽5.10米，桥长8.50米。侧墙用块石砌筑，上顶有单层仰天石。桥台是凹字型，拱碹是半圆形纵联式结构，无拱眉，跨径5.00米。', '', 20, NULL, NULL, '', 8, 1, 8, 1, '桂林市通湖路馆驿巷天盛小区内，跨安泰河上', '石材（块石）', 50, 52, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (940, '花桥', '今存花桥是一座4孔等跨径石拱桥。桥面为平面，两侧有节间式石栏杆，无地伏，桥栏杆置于仰天石上。桥面宽7.00米。桥梁全长135.00米。桥上建砖木结构廊。侧墙用青石板砌筑，上顶有单层仰天石。南桥台建在山脚岩石上。北端桥台是凹字形。桥墩两端与拱脚齐平，桥墩厚1.20米。拱碹为半圆形纵联式结构，拱碹较薄，无拱眉，碹脸与侧墙齐平。跨径均为26.00米。四个拱碹之间的侧墙上各有一个石雕龙头。', '', 20, NULL, NULL, '', 10, 1, 10, 1, '广西桂林市小东江和灵剑溪汇合处', '青石料、青石板、砖木', 50, 53, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (941, '富里桥', '富里桥是一座单孔石拱桥。桥面中部(拱顶上)高起为平面，两侧有板式石栏杆，两端是阶梯式坡道，无栏杆。桥面宽5.00米，桥长30.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长5.00米。拱碹是半圆形纵联分段并列式结构，碹脸外边有拱眉石，碹脸、拱眉与侧墙取平。跨径20.00米。', '', 20, NULL, NULL, '', 7, 1, 7, 1, '桂林市阳朔县，跨乌龟河上', '料石', 50, 54, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (942, '仙桂桥', '桥面略显弧形，无栏杆。桥面宽4.16 米，桥长25.80米。侧墙用块石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长4.60 米。拱碹是半圆形并列式结构，有拱眉，跨径5.50米。', '', 20, NULL, NULL, '', 5, 1, 10, 1, '桂林市阳朔县白沙镇旧县村', '块石', 50, 55, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (943, '阳朔遇龙桥', '桥面略显弧形，桥上无栏杆，亦无地伏。桥面宽5.00米，桥长60.00米。侧墙用料石砌筑，上顶有双层仰天石，上下两层均为矩形断面。桥台是凹字形，前面和两侧下部皆有出台，前墙长5.00米。拱碹是半圆形纵联分段并列式结构，无拱眉，碹脸与侧墙平。跨径18.00米。', '', 20, NULL, NULL, '', 7, 1, 7, 1, '桂林市阳朔县', '料石', 50, 56, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (944, '益寿桥', '益寿桥是一座3孔石拱桥。桥面略显弧形，无栏杆，桥面宽4.65米，桥长38.20米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长4.65米。桥墩两端是方形，桥墩厚1.20米，桥墩长5.05米。拱碹是半圆形纵联式结构，碹脸外边有拱眉，碹脸、拱眉与侧墙平。中孔跨径12.30米，边孔跨径11.50米。', '', 20, NULL, NULL, '', 7, 1, 7, 1, '河池市东兰县九曲河上', '料石', 50, 57, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (945, '五桂桥', '五桂桥是一座3孔石拱桥。桥面中部(3孔拱上)高起为平面，两侧有石板栏杆，两端是阶梯式坡道，两端各有23级台阶，无栏杆。桥面宽5.50米，桥长44.50米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长5.50米。桥墩两端是方形，桥墩厚1.00米，桥墩长6.00米。拱碹是半圆形纵联式结构，无拱眉，跨径均为12.00米。', '', 20, NULL, NULL, '', 10, 1, 10, 1, '贺州市八步区沙田镇马峰村', '石材（料石、石板）', 50, 58, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (946, '青龙回澜桥', '桥面是平面，桥面宽4.70米，桥长26.70米。桥上建有木结构廊，桥头建2层式亭。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形。桥墩两端是方形，拱碹是半圆形纵联式结构，无拱眉。跨径均为6.00米。', '', 20, NULL, NULL, '', 7, 1, 7, 1, '贺州市富川县油沐乡沐笼村，跨黄沙河上', '料石、木材', 50, 59, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (947, '忻城思练桥', '思练桥是一座双孔石拱桥。桥面为平面，两端的桥塊为坡面，全部铺砌青石板。桥上无栏杆，地伏和仰天石犹存，其断面均为矩形。桥面宽3.30米，桥长36.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台为凹字形，前墙长3.30米。桥墩两端是方形，拱碹为半圆形纵联式结构，有拱眉，碹脸、拱眉与侧墙平。跨径均为6.00米。', '', 20, NULL, NULL, '', 10, 1, 10, 1, '来宾市忻城县', '青石板、料石', 50, 60, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (948, '三江永济桥', '永济桥是一座5孔石拱桥。桥塊和桥面上铺砌花岗岩石板，全桥大致为平面，两侧有节间式石栏杆，桥面宽4.00米，桥长96.00米。侧墙用花岗岩石板砌筑，上顶有单层仰天石。桥台上游端是尖形，下游端是方形。拱碹是半圆形纵联式结构，有拱眉，拱眉凸出于碹脸，拱眉与侧墙平。', '', 20, NULL, NULL, '', 8, 1, 10, 1, '柳州市三江侗族自治县林溪乡，跨澄江河上', '花岗岩石板', 50, 61, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (949, '接龙桥', '接龙桥是一座5孔石拱桥。桥塊和桥面上铺砌青石板，两侧有节间式石栏杆。桥面宽3.80米，桥长57.70米。侧墙用料石砌筑，上顶有单层仰天石。桥台是燕翅形，前墙长约5.00米。桥墩上游端是尖形，下游端是方形，跨径均为15.00米。', '', 20, NULL, NULL, '', 8, 1, 8, 1, '钦州市灵山县灵城镇', '青石板、料石', 50, 62, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (950, '云龙桥', '云龙桥是一座3孔等跨径石拱桥。桥面上铺砌条形石板，两侧有节间式石栏杆。桥面宽7.00米，桥长39.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，桥墩两端是方形，拱碹是半圆形纵联式结构，无拱眉，跨径均为11.00米。', '', 20, NULL, NULL, '', 8, 1, 8, 1, '玉林市大南路与沿江北路交叉口处，跨南流江上', '石材（条形石板、料石）', 50, 63, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (951, '三江程阳桥（又名“永济桥”“盘龙桥”）', '程阳桥是一座4孔等跨径石墩台悬臂式木梁桥。上部结构是双层圆木叠合纵梁，纵梁两端下面有3层圆木悬臂梁，悬臂梁之间有疏铺方木横系梁。纵梁上面铺木桥面板，木板上面铺墁砖面。桥面宽3.75米，桥长77.60米。桥上建砖木结构通廊，每个桥墩和桥台上建塔式亭。桥台是凹字形，用料石砌筑。桥墩也是用料石砌筑，两端为立三面形式。跨径均为12.50米。', '', 20, NULL, NULL, '', 8, 2, 8, 1, '柳州市三江侗族自治县古宜镇程阳村，跨林溪河上', '石墩台、圆木（纵梁、悬臂梁）、方木（横系梁）、木桥面板、砖面、料石（桥台、桥墩）', 50, 64, '2026-04-28 23:07:54', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (952, '北流登龙桥', '登龙桥是一座单孔撑架式木梁桥。纵梁上横铺木桥面板，上面铺墁青砖。桥面宽13.50米，桥长36.30米。桥上建砖木结构廊。桥台建在山脚岩石上。跨径10.00米。', '', 20, NULL, NULL, '', 7, 2, 7, 1, '北流市龙桥路', '木材、青砖', 50, 65, '2026-04-28 23:07:54', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (953, '本善桥', '桥面是正圆弧形，两侧有节间式石栏杆，每侧有6根望柱，5块栏板，两块抱鼓石。无地伏，桥栏杆安装在仰天石上。桥面宽3.00米，桥塊端宽3.75米，桥长30.18米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前面和两侧下部有小出台。拱碹是半圆形分段并列式结构(龙门碹是纵联石),由8段拱碹石构成，无拱眉，碹脸与侧墙平。跨径8.00米。', '', 10, NULL, NULL, '', 5, 1, 5, 1, '常州市金坛区清涪村，跨清涪河上', '石材', 50, 51, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (954, '惠济桥', '惠济桥是一座单孔石拱桥。桥面中部(拱顶上)高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆，无地伏，桥栏杆置于仰天石上。桥面宽6.20米，桥梁全长(包括引道)53.60米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长6.60米。拱碹是半圆形纵联分段并列式结构，有拱眉，拱眉凸出于碹脸，拱眉与侧墙平。跨径12.00米。碹脸上方两侧各有一个勾头石，桥孔两边的侧墙上有桥联柱，上顶有勾头石。东侧联为“帆影西来趁顺道牙樯绘出桑麻两岸，水光东去看横排雁齿汇成烟火千家”；西侧联为“城郭遥瞻二十里通津于兹砥拉，江湖旁引千百年利济永屯苞桑”。', '', 10, NULL, NULL, '', 8, 1, 8, 1, '江苏省常州市武进区京杭大运河上', '石材（料石）', 50, 52, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (955, '兴隆桥', '兴隆桥是一座单孔石拱桥。桥面中部（拱顶上）高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆，桥面宽3.15米，桥长19.10米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长3.50米。拱碹是半圆形纵联分段并列式结构，有拱眉，拱眉凸出于碹脸，拱眉与侧墙平。跨径6.50米。', '', 10, NULL, NULL, '', 8, 1, 8, 1, '无锡市梁溪区棉花巷，跨外环河上', '花岗岩石板、青石', 50, 53, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (956, '广济桥', '广济桥是一座3孔石拱桥。桥面中部(中孔拱顶上)高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆，桥面全宽6.20米，净宽4.90米，桥长48.25米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前面和两侧下部有小出台，前墙长6.80米。桥墩两端是方形，四周有小出台，桥墩厚1.00米，桥墩长6.80米。拱碹是半圆形纵联分段并列式结构，碹脸外边镶有拱眉石，拱眉凸出于碹脸，又凸出于侧墙。中孔跨径12.50米，边孔跨径9.50米。', '', 10, NULL, NULL, '', 7, 1, 10, 1, '常州市钟楼区西仓街', '料石', 50, 54, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (957, '板桥', '桥面中部(中孔上)高起为平面，两端是阶梯式坡道。两侧有节间式石栏杆，每侧有4根望柱和3段石栏板，两段各有一块抱鼓石。无地伏，桥栏杆置于仰天石上。桥面宽12.00米，桥长23.00米。侧墙用条形石板砌筑，上面有双层仰天石。桥台是凹字形，前墙长7.00米。端墙较长，前面和两侧下部皆有小出台。桥墩两端为方形，桥墩厚85厘米，桥墩长7.00米。四周下部有出台。拱碹是半圆形纵联分段并列式结构，碹脸外边皆有拱眉石，拱眉凸出于碹脸，拱眉梢凸出于侧墙。中孔跨径7.35米，边孔跨径5.50米。', '', 10, NULL, NULL, '', 8, 1, 8, 1, '南京市雨花台区板桥河上', '石材', 50, 55, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (958, '江夏桥', '今存江夏桥是一座3孔石拱桥。桥塊和桥面上铺砌条形石板，两侧有节间式石栏杆，每侧有望柱8根，栏板7块，抱鼓石两块。无地伏，桥栏杆置于仰天石上。桥面宽4.70米，桥长44.00米。侧墙用料石砌筑，上顶有单层青石仰天石组成的金边线。桥台是凹字形，前墙长4.70米，前面和两侧下部有小出台。桥墩两端与拱脚取齐，四周有出台，桥墩厚1.00米，桥墩长5.00米。拱碹是半圆形纵联分段并列式结构，碹脸外边有拱眉石，拱眉凸出于碹脸，又凸出于侧墙。中孔跨径10.00米，边孔跨径7.50米。', '', 10, NULL, NULL, '', 7, 1, 7, 1, '南京市高淳区古柏镇戴家城村', '条形石板、料石、青石', 50, 56, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (959, '漆桥', '桥面中部(中孔上)高起为平面，两端是较缓的坡道，桥面上铺砌条形石板，两侧有节间式石栏杆，每侧有望柱8根，栏板7块，抱鼓石两块。无地伏，桥栏杆置于仰天石上。桥面宽4.50米，桥长39.00米。侧墙用料石砌筑，上顶有单层青石仰天石组成的金边线。桥台是凹字形，前墙长4.50米，前面和两侧下部有出台。桥墩属于薄型，两端与拱脚取齐，四周有出台，桥墩厚1.00米，桥墩长4.80米。拱碹是半圆形纵联分段并列式结构，碹脸外边有拱眉石，拱眉凸出于碹脸，又凸出于侧墙。中孔跨径10.00米，边孔跨径7.00米。', '', 10, NULL, NULL, '', 10, 1, 10, 1, '南京市高淳区', '石材（条形石板、料石、青石）', 50, 57, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (960, '童男桥', '童男桥是一座单孔石拱桥。桥面中部(拱顶上)高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆，桥面宽4.00米，桥长15.30米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长4.50米。拱碹是半圆形纵联分段并列式结构，无拱眉，跨径5.00米。', '', 10, NULL, NULL, '', 8, 1, 8, 1, '南京市江宁区，跨大河上', '料石', 50, 58, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (961, '南京长乐桥', '长乐桥是一座3孔石拱桥。桥面中部(中孔拱顶上)高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆，桥面宽3.70米，桥长36.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长4.20米。桥墩两端是尖形，桥墩厚1.00米，桥墩长4.20米。拱碹是半圆形纵联分段并列式结构，无拱眉，中孔跨径8.00米，边孔跨径6.00米。中孔拱碹上部两边的侧墙上有一对勾头石。', '', 10, NULL, NULL, '', 8, 1, 8, 1, '南京市溧水区东屏镇长乐村，跨溧水河上', '料石', 50, 59, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (962, '蒲塘桥', '桥面中部(中孔上)为平面，两端是较缓的坡面，两侧有节间式石栏杆，望柱是方形柱头，栏板为实体板。地伏为矩形断面。桥面全宽6.90米，净宽5.70米，桥梁全长91.30米。侧墙用花岗岩砌筑，上顶有单层仰天石组成的金边线。桥台是凹字形，前墙长7.00米。端墙后部两侧有燕翅墙，前面和两侧下部皆有小出台。桥墩用条形石板砌筑，自下而上有收分，两端是方形，两端伸出桥外较长。拱碹是半圆形纵联分段并列式结构，中三孔由10道纵联石和11段拱碹石构成，边孔由6道纵联石和7段拱碹石构成，其余四孔由8道纵联石和9段拱碹石构成。碹脸外边有拱眉石，拱眉凸出于碹脸，拱眉与侧墙取平。中孔跨径10.60米，向两端逐孔减小，边孔跨径5.50米。', '', 10, NULL, NULL, '', 8, 1, 8, 1, '南京市溧水区蒲塘河上', '花岗岩（侧墙）、条形石板（桥墩）', 50, 60, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (963, '南京天生桥', '桥面经过整修而形成平面，无栏杆，桥面宽9.00米，桥面长34.00 米。桥台即山崖，跨径20.00米，桥孔净空35.00米。', '', 10, NULL, NULL, '', 7, 2, 7, 1, '南京市溧水区，跨胭脂河上', '天然石材', 50, 61, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (964, '大中桥', '大中桥是一座3孔砖石拱桥。桥面宽12.80米，桥长40.00米。侧墙用花岗岩石板砌筑，上面有单层青石仰天石。桥台是凹字形，前墙长12.80米。拱碹是半圆形纵联分段并列式结构，碹脸外边有拱眉石，眉石凸出于碹脸，又凸出于侧墙。中孔跨径12.00米，边孔跨径9.00米。', '', 10, NULL, NULL, '', 10, 1, 10, 1, '南京市秦淮区通济门内', '砖、花岗岩石板、青石', 50, 62, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (965, '九龙桥', '九龙桥是一座5孔石拱桥。桥堍和桥面上铺砌青石板，两侧有节间式石栏杆，桥面宽13.30米，净宽12.40米，桥面长51.00米，全长68.10米。侧墙用料石砌筑，上顶有单层仰天石。桥台是燕翅形，桥墩两端是尖形。拱碹是半圆形纵联分段并列式结构，无拱眉，中孔跨径7.40米，次边孔跨径7.10米，边孔跨径6.80米。', '', 10, NULL, NULL, '', 8, 1, 8, 1, '南京市秦淮区，近临通济门，跨外秦淮河上', '青石板（桥堍和桥面）、料石（侧墙）', 50, 63, '2026-04-28 23:07:54', '2026-04-28 23:36:17');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (966, '南京七瓮桥', '桥面宽14.20米，净宽13.00米，桥面长89.60米，全长99.70米。侧墙由料石砌筑，上顶有双层仰天石组成的金边线。桥台是凹字形，端墙后部有燕翅墙。桥墩上游端是尖形，下游端是方形，呈梭形(两端尖形)，墩长26.00米，两端皆伸出桥身外3.00米，上游端上面各有一只卧式石雕镇水兽(共6只)，兽头上仰。拱碹是半圆形纵联分段并列式结构，每块拱碹石长1.15米、宽0.50米、厚0.25米，共有242块拱碹石。中孔跨径12.00米，边孔跨径7.00米。中孔两边的侧墙上刻有“上方桥”三个大字。中孔碹石上刻有“清顺治六年重修”。碹脸龙门上各有一石雕龙头。各孔拱碹上边两侧各有一个勾头石。', '', 10, NULL, NULL, '', 10, 1, 10, 1, '南京市秦淮区光华门外七桥村', '石材（料石、拱碹石）', 50, 64, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (967, '玄津桥', '玄津桥是一座3孔石拱桥。桥塊和桥面上铺砌条形石板，桥面略呈圆弧形，两侧有节间式石栏杆，栏杆两端有一对石狮子。桥面宽19.10米，桥长41.60米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，端墙外有护岸石墙。桥墩两端是尖形。拱碹是半圆形纵联分段并列式结构，有拱眉，碹脸、拱眉与侧墙平。中孔跨径12.50米，边孔跨径9.50米。', '', 10, NULL, NULL, '', 8, 1, 8, 1, '南京市秦淮区中山东路上，跨古杨吴城的护城河上，在逸仙桥南边', '石材（条形石板、料石）', 50, 65, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (968, '程家桥（又名“二条桥”）', '桥面中部(拱顶上)高起为平面，两端是阶梯式坡道，北坡有36级台阶，南坡有31级台阶，两侧有节间式石栏杆，东面栏板上刻“南无阿弥陀佛”。桥面宽3.30米，桥长31.80米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，拱碹是半圆形纵联分段并列式结构，有拱眉，跨径14.50米，矢高7.20米。', '', 10, NULL, NULL, '', 8, 1, 10, 1, '江苏省常熟市虞山镇山前塘上（在头条桥以西一公里处）', '石材（料石）', 50, 66, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (969, '苏州觅渡桥', '该桥是一座单孔石拱桥，桥面中部略显正圆弧形，两端是阶梯式坡道，两侧有节间式石栏杆，无地伏，桥栏杆置于仰天石上。桥面宽4.80米，桥梁全长81.30米。侧墙用条形石板砌筑，上顶有单层仰天石组成的金边线。桥台是凹字形，端墙很长。拱碹是半圆形分段并列式结构，由7段拱碹石构成，碹脸外边有拱眉石，拱眉与侧墙平。跨径19.30米。碹脸两边的侧墙上各有一个勾头石。1958年改修全桥桥面为正圆弧形，桥面两头各有一段较长的反弧形路面，桥栏杆改建成砖砌宇墙式。', '', 10, NULL, NULL, '', 8, 1, 10, 1, '苏州市姑苏区葑门外，跨古运河上', '石材（条形石板、仰天石、拱碹石）、砖（宇墙）', 50, 67, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (970, '普济桥', '普济桥是一座3孔薄拱薄墩轻型石拱桥。桥面中部(中孔上)高起为平面，两端是阶梯式坡道，南坡有26级踏步，北坡有30级踏步。两侧有节间式石栏杆，每侧有4根望柱、3段栏板和两块抱鼓石。无地伏，桥栏杆置于仰天石上。桥面宽4.05米，桥长38.69米。侧墙用料石砌筑，上顶有单层仰天石组成的金边线。桥台是凹字形，前墙长4.10米。桥墩两端与拱脚齐平，桥墩厚70厘米，桥墩长4.10米。拱碹是半圆形纵联分段并列式结构，碹脸外边有拱眉石，拱眉凸出于碹脸，又凸出于侧墙。中孔跨径9.16米，矢高4.37米，南边孔跨径5.31米，矢高2.60米，北边孔跨径5.29米，矢高2.54米。', '', 10, NULL, NULL, '', 8, 1, 8, 1, '苏州市姑苏区山塘街，跨山塘河上', '料石、仰天石', 50, 68, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (971, '上津桥', '桥面中部(拱顶上)高起为平面，两端铺设条石踏步，南29级，北31级。两侧有节间式砖石栏杆，每侧有4根望柱，3段砖栏板，两端有抱鼓石。砖砌栏板上有青石帽(扶手)，中间栏板上镶有一块石匾，刻“上津桥”三个大字。无地伏，桥栏杆砌筑在仰天石上。桥面宽3.70米，桥长42.45米。侧墙用料石砌筑，上顶有单层仰天石。桥台的前墙与石砌河岸连砌为一体，拱碹是半圆形分段并列式结构，共7段拱碹石，碹脸外边有拱眉石，拱眉与侧墙平。跨径12.20米。', '', 10, NULL, NULL, '', 8, 1, 10, 1, '苏州市姑苏区阊门外枫桥路东头，跨阊门古运河上', '条石、砖、青石、料石', 50, 69, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (972, '寿星桥', '现存寿星桥是一座单孔石拱桥。桥面呈正圆弧形，两侧有板式石栏杆，无地伏，桥栏杆置于仰天石上。桥面宽4.00米，桥长18.00米。侧墙顶上有单层仰天石组成的金边线。桥台是凹字形，前面和两侧有出台。拱碹是半圆形纵联分段并列式结构，由6道纵联石和7段拱碹石构成，碹脸外边有拱眉石，拱眉凸出于碹脸，又凸出于侧墙。跨径4.70米，矢高约2.60米。碹脸上方两边的侧墙上各有一个勾头石。桥孔两边(桥台上)的侧墙上各有一根桥联柱，上顶有勾头石。', '', 10, NULL, NULL, '', 5, 1, 5, 1, '江苏省苏州市城东叶家弄', '石材', 50, 70, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (973, '苏州万年桥', '原有桥面中部(中孔上)高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆。今存桥面呈正圆弧竖曲线，桥塊上为缓坡反圆弧竖曲线，两侧有石柱石栏杆，桥面宽6.20米，桥长85.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形。桥墩两端是方形，桥墩厚98厘米，桥墩长6.60米。拱碹是半圆形纵联分段并列式结构，有拱眉，拱眉凸出于碹脸，又凸出于侧墙。中孔跨径16.00米，边孔跨径11.20米。', '', 10, NULL, NULL, '', 7, 1, 7, 1, '苏州市姑苏区胥门外，跨外城河上', '石材（料石）', 50, 71, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (974, '吴门桥', '桥面中部(拱顶上)高起为平面，两端是阶梯式坡道，南北坡道上各有50级踏步。桥面中部两侧有平直形砖栏杆，栏杆上镶有一块石匾，镌刻“吴门桥”。桥栏杆与砖砌侧墙为一体，两端的坡道上无栏杆。桥面宽4.80米，桥长66.30米。侧墙用砖材砌筑，上顶有单层仰天石组成的金边线。桥台是凹字形，桥台前墙的两角各立一根方形石柱，前墙近上游端有一根竖立的石柱(竖向有闸口槽),三根石柱之间砌筑石板。拱碹是半圆形纵联分段并列式结构，由10道纵联石和11段拱碹石构成，碹脸外边有拱眉石，眉石凸出于碹脸，又凸出于侧墙。跨径16.00米。碹脸上部两边的侧墙上各有一个勾头石，桥孔两边的侧墙上各有一根桥联柱，上顶有勾头石。', '', 10, NULL, NULL, '', 8, 1, 10, 1, '苏州市姑苏区盘门外，跨古运河上', '砖、石', 50, 72, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (975, '苏州彩云桥', '现存彩云桥是一座3孔薄拱薄墩轻型石拱桥。桥面中部(中孔上) 高起为平面，两端是阶梯式坡道。两侧有节间式石栏杆，每侧有望柱4 根，栏板3块，抱鼓石两块。无地伏，桥栏杆置于仰天石上。桥面宽 3.70米，桥长38.00米。 侧墙是用料石砌筑，上顶有单层仰天石组成的金边线。桥台是凹字 形，前墙长3.70米。前面和两侧下部皆有小出台。桥墩的两端与拱脚 取齐，四周有小出台，桥墩厚70厘米，桥墩长3.70米。拱碹均为半圆 形纵联分段并列式结构，中孔是8道纵联石和9段拱碹石，边孔是6道 纵联石和7段拱碹石，碹脸外边有拱眉石，拱眉凸出于碹脸，又凸出于 侧墙。中孔跨径8.50米，边孔跨径7.20米。 中孔碹脸上方两边的侧墙上各有一个勾头石，桥墩上的侧墙上各有 一根桥联柱，上顶有勾头石。', '', 10, NULL, NULL, '', 9, 1, 10, 1, '江苏省苏州市虎丘区横塘镇，原跨运河上，1992年迁建于胥江上', '石材（料石、仰天石、拱碹石）', 50, 73, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (976, '苏州枫桥', '桥面中部高起为平面，两端是阶梯式坡道。两侧有节间式石栏杆，每侧有6根望柱，5段栏板，两块抱鼓石。无地伏，桥栏杆置于仰天石上。桥面宽5.27米，净宽4.20米，桥长39.60米。侧墙用料石砌筑，上顶有单层仰天石组成的金边线。桥台是凹字形，前墙长5.30米。端墙与石砌河岸连砌为一体，前面和左右两面皆有出台。拱碹是半圆形纵联分段并列式结构，由8道纵联石和9段拱碹石构成，碹脸外边有拱眉石，拱眉凸出于碹脸，拱眉与侧墙平。跨径10.00米。碹脸上方两边的侧墙上各有一个勾头石，桥孔两边的侧墙上各有一根桥联柱，上顶有勾头石。', '', 10, NULL, NULL, '', 8, 1, 8, 1, '苏州市虎丘区寒山寺以北', '石材', 50, 74, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (977, '江村桥', '桥面中部高起为平面，两端是阶梯式坡道。两侧有节间式石栏杆，每侧有4根望柱，3段栏板，两块抱鼓石。桥面宽4.50米，桥长27.50米。侧墙用料石砌筑，上顶有单层仰天石组成的金边线。桥台是凹字形，前墙长4.50米，前面和两侧下部皆有出台。拱碹是半圆形纵联分段并列式结构，由8道纵联石和9段拱碹石构成，碹脸外缘錾出拱眉线，拱眉与侧墙平。跨径10.00米。碹脸上方两边的侧墙上各有一个勾头石，桥孔两边的侧墙上各有一根桥联柱，上顶有勾头石。', '', 10, NULL, NULL, '', 8, 1, 10, 1, '苏州市虎丘区寒山寺门前', '料石', 50, 75, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (978, '行春桥（又名九环洞桥）', '桥塊和桥面上铺砌条形石板，两侧有节间式青石栏杆，望柱为方形柱头，栏板为实体板，无地伏，桥栏杆置于仰天石上。桥面宽5.20米，桥长54.00米。侧墙用花岗岩石板砌筑，上顶有双层青石板组成的金边线，上层石板(仰天石)的外立面为平面，下层石板(托石)的立面呈弧形。桥台两侧有燕翅墙，前墙前面下部有出台，前墙长6.40米。桥墩上游端是尖形，下游端是方形，下部四周有出台，拱碹是半圆形纵联式结构，无拱眉，碹脸与侧墙取平。中孔跨径5.30米，边孔跨径3.50米。各孔拱碹之间(桥墩以上)的侧墙上各有一个龙头。', '', 10, NULL, NULL, '', 7, 1, 10, 1, '苏州市虎丘区石湖风景区', '条形石板、青石、花岗岩', 50, 76, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (979, '越城桥', '桥面铺砌花岗岩石板，中部高起为平面，两端为长坡道。两侧有节间式石栏杆，每侧有4根望柱，3段石栏板，两块抱鼓石。无地伏，桥栏杆置于仰天石上。桥面宽3.60米，桥长33.20米。侧墙用料石砌筑，上有单层仰天石。桥台是凹字形，前墙两端伸出形成方台，台宽约1.00米。拱碹是半圆形纵联分段并列式结构，由8道纵联石和9段拱碹石构成，碹脸外边有拱眉石，拱眉凸出于碹脸及侧墙。跨径9.50米，矢高4.80米。桥联柱上刻有对联。', '', 10, NULL, NULL, '', 8, 1, 8, 1, '苏州市虎丘区石湖风景区越城镇，石湖东岸边，跨于北越来溪上', '花岗岩石板、料石', 50, 77, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (980, '洪恩桥', '洪恩桥是一座单孔石拱桥。桥面中部(拱顶上)高起为平面，两端是阶梯式坡道。两侧有节间式石栏杆，每侧有望柱4根，栏板3段，两端是抱鼓石。无地伏，桥栏杆置于仰天石上。桥面宽3.25米，桥长13.31米。侧墙用花岗岩石板砌筑，上面有单层青石仰天石。桥台是凹字形，前面和两侧有出台，端墙两侧与河岸连砌为一体，桥塊在河岸上。拱碹是半圆形纵联分段并列式结构，碹脸外边有拱眉石，眉石凸出于碹脸，又凸出于侧墙。跨径5.60米。', '', 10, NULL, NULL, '', 10, 1, 10, 1, '苏州市吴江区跨街河上', '花岗岩、青石', 50, 78, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (981, '吉利桥', '吉利桥是一座单孔石拱桥。桥堍和桥面上铺砌花岗岩石板，桥面略显圆弧形。两侧有节间式石栏杆，每侧有6根望柱，5块栏板，2块抱鼓石。桥面宽2.40米，桥长13.00米。桥堍翼墙和桥身侧墙是用花岗岩石板砌筑，上面有单层青石仰天石。桥台是凹字形，前墙长2.80米。拱碹是圆弧形并列式结构，碹脸外边有拱眉石，拱眉凸出于碹脸，拱眉又凸出于侧墙。跨径5.00米。', '', 10, NULL, NULL, '', 8, 1, 8, 1, '苏州市吴江区同里镇，在太平桥和长庆桥之间', '花岗岩石板、青石', 50, 79, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (982, '道南桥', '道南桥是一座单孔石拱桥。桥面中部(拱顶上)高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆，桥面宽2.75米，桥长17.30米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形。拱碹是半圆形纵联分段并列式结构，有拱眉。跨径7.80米，矢高3.90米。', '', 10, NULL, NULL, '', 8, 1, 8, 1, '苏州市吴江区黎里镇老街下岸，跨市河支流南港河上', '石材', 50, 80, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (983, '东风桥', '东风桥是一座单孔石拱桥。桥面中部(拱顶上)高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆，每侧有4根望柱，3块栏板，两块抱鼓石。桥面宽4.20米，桥长18.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形。拱碹是半圆形纵联分段并列式结构，拱眉凸出于碹脸，又凸出于侧墙。跨径8.15米。碹脸上方两侧有一个勾头石。桥孔两边的侧墙上各有一根桥联柱，上顶有勾头石。', '', 10, NULL, NULL, '', 7, 1, 10, 1, '苏州市吴江区黎里镇，跨市河上', '石材（料石）', 50, 81, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (984, '青龙桥', '青龙桥原名“际恩桥”,俗称“相家桥”。桥面中部(拱顶上)高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆，桥面宽3.75米，桥长35.00米。桥台是凹字形。拱碹是半圆形纵联分段并列式结构，拱眉凸出于碹脸，拱眉又凸出于侧墙。跨径16.00米。', '', 10, NULL, NULL, '', 8, 1, 8, 1, '苏州市吴江区黎里镇', '石材', 50, 82, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (985, '广福桥', '广福桥是一座单孔石拱桥。桥面中部(拱顶上)高起为平面，两端是阶梯式坡道。两侧有节间式石栏杆，桥面宽2.34米，桥堍端宽2.64米，桥长17.40米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，拱碹是半圆形纵联分段并列式结构，有拱眉，跨径6.90米，矢高3.17米。', '', 10, NULL, NULL, '', 7, 1, 10, 1, '苏州市吴江区七都镇', '料石', 50, 83, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (986, '绍定桥', '绍定桥是一座单孔石拱桥。桥面中部(拱顶上)高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆，桥面宽4.25米，桥长18.50米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形。拱碹是半圆形纵联分段并列式结构，有拱眉，拱眉凸出于碹脸，拱眉与侧墙平。跨径8.60米。两面碹脸上方的侧墙上有一对勾头石。', '', 10, NULL, NULL, '', 8, 1, 8, 1, '苏州市吴江区七都镇东庙村', '石材（料石）', 50, 84, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (987, '带福桥', '带福桥原名“搭北桥”。桥面中部(中孔拱顶上)高起为平面，两侧有节间式石栏杆，桥面宽4.00米，桥长47.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形。桥墩两端是方形。拱碹是半圆形纵联分段并列式结构。有拱眉，中孔跨径19.00米，边孔跨径9.50米。', '', 10, NULL, NULL, '', 8, 1, 8, 1, '苏州市吴江区，跨盛泽东港上', '料石', 50, 85, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (988, '升明桥', '现存升明桥是一座3孔薄拱薄墩轻型石拱桥。桥面中部(中孔上) 高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆，每侧有望柱4 根，栏板3段，抱鼓石2块。无地伏，桥栏杆置于仰天石上。桥面宽25 米，桥塊端宽5.45米，桥长46.94米。 侧墙用料石砌筑，上面有单层仰天石。桥台是凹字形，前墙长6.90 米。桥墩两端是方形，拱脚四周有出台，桥墩厚1.00米，桥墩长6.90 米。拱碹为半圆形纵联分段并列式结构，碹脸外边镶有双线拱眉，拱眉 凸出于碹脸，又凸出于侧墙。中孔跨径10.70米，边孔跨径8.00米。每 孔碹脸上方两边的侧墙上各有一个勾头石，桥墩上和边孔外边(桥台以 上)的侧墙上各有一根桥联柱，上顶有勾头石。', '', 10, NULL, NULL, '', 8, 1, 8, 1, '苏州市吴江区盛泽镇，跨东白漾口上', '石材（料石）', 50, 86, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (989, '挹翠桥', '桥面中部(拱顶上)高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆，桥面宽3.50米，桥长14.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形。拱碹是半圆形纵联分段并列式结构，有拱眉，拱眉凸出于碹脸，拱眉与侧墙平。跨径6.50米。两面碹脸上方的侧墙上有一对勾头石，桥孔两侧(桥台端墙以上)的侧墙上各有根桥联柱，上顶有勾头石。', '', 10, NULL, NULL, '', 10, 1, 10, 1, '苏州市吴江区盛泽先蚕祠内，跨花园水池上', '料石', 50, 87, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (990, '双塔桥', '双塔桥是一座单孔石拱桥。桥面中部(拱顶上)高起为平面，两端是阶梯式坡道。两侧有节间式石栏杆，桥面宽4.50米，桥长48.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，桥墩两端是方形，拱碹是半圆形纵联分段并列式结构，有拱眉。跨径16.00米。', '', 10, NULL, NULL, '', 8, 1, 8, 1, '苏州市吴江区七都镇双塔村(原李家港村)，跨稽鱼漾上', '料石', 50, 88, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (991, '垂虹桥', '垂虹桥始建于北宋庆历八年(1048年)，最初为石墩台木梁桥，命名“利往桥”。元泰定二年(1325年)改建成72孔石拱桥，桥上中间建有砖木结构亭“垂虹”，两端各建“汇泽”与“砥定”亭。现存桥梁仅南端4孔为古代石拱桥，其余各孔均系20世纪50年代重建。原桥桥面宽5.45米，桥长54.50米。', '', 10, NULL, NULL, '', 6, 1, 10, 1, '苏州市吴江区松陵镇', '石材、木材、砖', 50, 89, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (992, '三里桥', '今存三里桥是一座单孔石拱桥。桥面中部(拱顶上)高起为平面，两端是阶梯式坡道，两侧有板式石栏杆，无地伏，桥栏杆置于仰天石上。桥面宽4.65米，桥塊外端宽5.38米。桥长52.40米。侧墙用料石砌筑，上顶有单层仰天石。桥体上部(桥面)较窄，下部(拱脚和桥台端墙下部)较宽。桥台是凹字形，前面和两侧皆有外出台，西桥台前墙长5.00米。东桥台的前面和两侧出台宽约60厘米，前墙长6.80米。拱碹是半圆形纵联分段并列式结构，由10道纵联石和11段拱碹石构成，碹脸外边有拱眉石，拱眉凸出于碹脸，又凸出于侧墙。跨径16.00米，矢高8.05米。碹脸上方两边的侧墙上各有一个勾头石，桥孔两边(桥台上)的侧墙上各有一根桥联柱，上顶有勾头石。', '', 10, NULL, NULL, '', 8, 1, 8, 1, '苏州市吴江区松陵镇北门外，跨于古京杭大运河上', '料石', 50, 90, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (993, '苏州亭子桥', '今存亭子桥是一座3孔薄拱薄墩轻型石拱桥。桥面中部(中空上) 高起为平面，两端是坡道，坡道的两侧有节间式石栏杆，每侧各有望柱 3根，栏板2块，抱鼓石一块。无地伏，桥栏杆置于仰天石上。桥面宽 7.00米，桥长98.00米。桥上中部建砖木结构亭子。 侧墙用料石砌筑，上顶有单层仰天石。桥台的前墙与石砌河岸连砌 为一体。桥墩的两端与拱脚齐平。拱碹是半圆形纵联分段并列式结构， 碹脸外镶有拱眉石，拱眉凸出于碹脸，又凸出于侧墙。跨径均为19.00 米。各孔碹脸的上方两边各有一个勾头石。', '', 10, NULL, NULL, '', 10, 1, 10, 1, '苏州市吴江区跨街河上', '石材（料石）、砖木', 50, 91, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (994, '长庆桥', '长庆桥是一座单孔石拱桥。桥面隆起较高，两侧有节间式石栏杆，每侧有4根望柱，3块栏板。桥面宽1.75米，两端的桥堍端宽2.50米，桥长11.54米。侧墙用料石砌筑，上顶用单层仰天石。桥台与石砌河岸为一体。拱碹是半圆形纵联分段并列式结构。跨径5.00米。龙门上刻“鲤鱼跳龙门”。南门桥孔两侧有桥联柱，西边的联柱上刻“共解囊金成利济，好留柱石待标题”,东边的联柱上刻“同治十二年桂月吉立”。', '', 10, NULL, NULL, '', 8, 1, 8, 1, '苏州市吴江区同里镇，在太平桥西边，在吉利桥东北方，跨东柳、裀礦两圩', '石材（料石、仰天石）', 50, 92, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (995, '富关桥（原名“庆荣桥”）', '富关桥是一座单孔石拱桥。桥面中部(拱顶上)高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆，桥面宽4.00米，桥长21.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形。拱碹是半圆形纵联分段并列式结构，有拱眉，拱眉凸出于碹脸，拱眉与侧墙平。跨径7.00米。', '', 10, NULL, NULL, '', 10, 1, 10, 1, '苏州市吴江区同里镇跨街河上', '石材（料石）', 50, 93, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (996, '普安桥', '普安桥是一座单孔石拱桥。桥面中部(拱顶上)高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆，桥面宽3.65米，桥长21.50米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形。拱碹是半圆形纵联分段并列式结构，有拱眉，拱眉凸出于碹脸，拱眉与侧墙平。跨径7.00米。', '', 10, NULL, NULL, '', 7, 1, 7, 1, '苏州市吴江区同里镇后港东溪上', '料石', 50, 94, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (997, '思本桥', '思本桥是一座单孔石拱桥。桥面顶部是圆弧形，两端是阶梯式坡道，两侧有石栏杆。桥面宽1.85米，桥长22.50米。侧墙用花岗岩石板砌筑，上顶有单层仰天石。桥台是凹字形。拱碹是半圆形纵联分段并列式结构，无拱眉。跨径9.00米。', '', 10, NULL, NULL, '', 5, 1, 10, 1, '苏州市吴江区同里镇潦浜村，跨市河上', '花岗岩', 50, 95, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (998, '宝带桥', '宝带桥是一座53孔薄拱薄墩轻型石拱桥。桥堍平面为梯形（喇叭形），桥堍和桥面上全部横向铺砌石板。桥面中部（第十四、十五、十六孔上）高起，两端为平面，桥上无栏杆。桥面宽4.10米，桥身长249.80米，北桥堍长23.40米，南桥堍长43.06米，南北桥堍端宽均为6.10米，桥梁全长316.80米。侧墙用条形石板砌筑，上顶有单层较厚的仰天石（边牙石）。桥台为凹字形，前墙长约4.50米，有燕翅墙。桥墩两端为方形，四周有出台，厚65厘米，长4.50米。拱碹为半圆形纵联分段并列式结构，碹脸外边镶有拱眉石。各孔跨径不等，北起第十五孔为6.90米，第十四和十六孔为6.00米，其余各孔净跨径为3.90米至4.10米。桥两端各有一对石狮子，北端有碑亭（内有乾隆题诗碑）及两座五层八面石塔（高4.00米，有佛龛佛像）。', '', 10, NULL, NULL, '', 8, 1, 8, 1, '江苏省苏州市澹台湖（县区西）', '石材（黎块石板、条形石板）', 50, 96, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (999, '东美桥', '东美桥是一座单孔石拱桥。桥面中部(拱顶上)高起为平面，两端是阶梯式坡道。两侧有节间式石栏杆，每侧有望柱4根，栏板3段，栏杆的两端与河岸上的栏杆对接。无地伏，桥栏杆置于仰天石上。桥面宽3.10米，桥长34.20米。侧墙用花岗岩石板砌筑，上面有单层青石仰天石。桥台是凹字形，前面和两侧有出台，端墙两侧与河岸连砌为一体，桥堍在河岸上。拱碹是半圆形纵联分段并列式结构，由6道纵联石和7段拱碹石构成，碹脸外边镶有拱眉石，拱眉凸出于碹脸，又凸出于侧墙。跨径7.30米。', '', 10, NULL, NULL, '', 10, 1, 10, 1, '苏州市吴中区甪直镇，跨街河上', '花岗岩、青石', 50, 97, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1000, '光福桥', '光福桥是一座单孔石梁桥。桥面中部(拱顶上)高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆，桥面宽2.34米，桥塊端宽3.35米，桥长16.10米。侧墙用花岗岩石板砌筑，上面有单层青石仰天石。桥台是凹字形，前面和两侧有出台，前墙长3.00米。拱碹是半圆形纵联分段并列式结构，碹脸外边镶有拱眉石，拱眉凸出于碹脸，又凸出于侧墙。跨径6.90米，矢高约3.37米。桥孔两侧的侧墙上各有一根桥联柱，上顶有勾头石。', '', 10, NULL, NULL, '', 7, 2, 10, 1, '苏州市吴中区', '花岗岩、青石', 50, 98, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1001, '下津桥', '桥面中部(拱顶上)高起为平面，两端是阶梯式坡道，各有33级踏步。两侧有节间式石栏杆，每侧有望柱4根，栏板3块，抱鼓石2块。中间栏板上镶有一块石匾，刻“下津桥”三个大字。无地伏，桥栏杆置于仰天石上。桥面宽5.20米，桥长58.00米。侧墙用条石砌筑，上顶有单层仰天石。桥台是凹字形，前面和两侧有出台，前墙长5.60米。拱碹是半圆形纵联分段并列式结构，碹脸外缘錾出拱眉线，拱眉凸出于碹脸，又凸出于侧墙。跨径10.00米。碹脸上方两边的侧墙上各有一个勾头石，拱碹两边(桥台上)的侧墙上各有一根桥联柱，上顶有勾头石。', '', 10, NULL, NULL, '', 7, 1, 7, 1, '苏州市吴中区甪直镇街东口', '石材（条石）', 50, 99, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1002, '五龙桥', '今存五龙桥是一座5孔薄拱薄墩轻型石拱桥。桥面中部(中孔上) 高起为平面，两端是阶梯式坡道。两侧有节间式石栏杆，每侧有望柱6 根，石栏板5段，两端有抱鼓石。无地伏，桥栏杆置于仰天石上。桥面宽6.50米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前面和两侧皆有出台。桥墩两端与拱脚齐平，下部四周有出台，桥墩厚1.05米，桥墩长6.90米。拱碹是半圆形纵联分段并列式结构，碹脸外边有拱眉石，拱眉凸出于碹脸，又凸出于侧墙。中孔跨径18.00米，次边孔跨径16.50米，边孔跨径15.00米。', '', 10, NULL, NULL, '', 10, 1, 10, 1, '苏州市吴中区', '石材（料石）', 50, 100, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1003, '正阳桥', '正阳桥是一座单孔石拱桥。跨街河上，桥面中部(拱顶上)高起为平面，两端是阶梯式坡道，各有33级踏步。桥面宽5.20米，桥长58.00米。桥台是凹字形，端墙很长，前面和两边有出台，前墙长5.60米。拱碹是半圆形纵联分段并列式结构，碹脸外边有拱眉石，拱眉凸出于碹脸，又凸出于侧墙。跨径10.00米。', '', 10, NULL, NULL, '', 7, 1, 7, 1, '苏州市吴中区甪直镇街河上', '花岗岩石板（桥堍翼墙和桥身侧墙）、青石（仰天石）', 50, 101, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1004, '富安桥', '富安桥是一座单孔石拱桥。桥面中部高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆，每侧有望柱6根，栏板5块，抱鼓石2块，无地伏，桥栏杆置于仰天石上。桥面宽3.80米，桥长17.40米。侧墙用料石砌筑，上顶有单层仰天石组成的金边线。桥台是凹字形，下部前面和两边有小出台。拱碹是半圆形纵联分段并列式结构，碹脸外边有拱眉石，拱眉凸出于碹脸，又凸出于侧墙。跨径6.60米。', '', 10, NULL, NULL, '', 10, 1, 10, 1, '昆山市周庄，跨街河上', '石材（料石）', 50, 102, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1005, '里和桥（又名南塘桥，俗称观音桥）', '里和桥是一座单孔石拱桥。桥面中部(拱顶上)高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆，桥面宽3.50米，桥长23.40米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，拱碹是半圆形纵联分段并列式结构，有拱眉，拱眉凸出于碹脸，拱眉与侧墙平。跨径9.00米。碹脸上方两侧有一对勾头石。在桥孔两边的侧墙上各有一根桥联柱，上顶有勾头石。', '', 10, NULL, NULL, '', 8, 1, 8, 1, '昆山市锦溪镇，跨南市河上', '石材（料石）', 50, 103, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1006, '普庆桥（俗称“俞家桥”）', '普庆桥是一座单孔石拱桥。桥面中部(拱顶上)高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆，桥面宽3.10米，桥长18.70米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，拱碹是半圆形纵联分段并列式结构，有拱眉，拱眉凸出于碹脸，拱眉与侧墙平。跨径6.60米。', '', 10, NULL, NULL, '', 8, 1, 8, 1, '昆山锦溪镇', '石材（料石）', 50, 104, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1007, '溥济桥（俗称“陈家桥”）', '溥济桥是一座单孔石拱桥。桥面呈圆弧形，两侧有节间式木栏杆，桥面宽2.95米，桥长15.40米。侧墙用料石砌筑，上顶有单层仰天石。桥台与石板砌筑的河岸为一体。拱碹是半圆形纵联分段并列式结构，无拱眉。跨径5.80米。', '', 10, NULL, NULL, '', 7, 1, 10, 1, '昆山市锦溪镇', '料石、石板、木材', 50, 105, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1008, '天水桥（俗称“观音桥”）', '天水桥是一座单孔石拱桥。桥面中部(拱顶上)高起为平面，两侧有节间式石栏杆，桥面宽3.30米，桥长17.40米。侧墙用料石砌筑，上顶有单层仰天石。桥台与石板砌筑的河岸为一体。拱碹是半圆形纵联分段并列式结构，有拱眉，拱眉凸出于碹脸，拱眉与侧墙平。跨径8.80米。', '', 10, NULL, NULL, '', 7, 1, 7, 1, '昆山市锦溪古镇', '石材（料石、石板）', 50, 106, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1009, '陶家桥', '现存陶家桥是一座单孔石拱桥。桥面中部高起为平面，两端是坡面 (中间是一条坡道，两边是梯道)。桥面中部建有一座四柱式瓦顶砖木结构亭。桥面宽5.80米，桥长28.40米。桥塊翼墙和桥身侧墙用花岗岩石板砌筑，上面有单层青石仰天石。桥台是凹字形，端墙很长，前墙长6.20米。拱碹是半圆形分段并列式结构，碹脸外有拱眉石，拱眉凸出于碹脸，拱眉与侧墙平。跨径7.80米。', '', 10, NULL, NULL, '', 8, 1, 8, 1, '昆山市千灯古镇', '花岗岩石板、青石、砖木', 50, 107, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1010, '通秀桥', '通秀桥是一座单孔石拱桥。桥面中部(拱顶上)为平面，两端是阶梯式坡道。桥面宽2.90米，桥长11.70米。侧墙用料石砌筑，上顶有单层仰天石组成的金边线。桥台是凹字形。拱碹是半圆形纵联分段并列式结构，碹脸外边有拱眉石，拱眉与侧墙平。跨径4.60米。', '', 10, NULL, NULL, '', 8, 1, 8, 1, '昆山市', '石材（料石、仰天石）', 50, 108, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1011, '太平桥', '桥面中部(拱顶上)高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆，每侧有望柱4根，栏板3块，抱鼓石两块。桥面宽2.50米，桥长13.20米。桥塊翼墙和桥身侧墙用料石砌筑，上面有单层青石仰天石。桥台的前墙与石板砌筑的河岸连砌为一体。拱碹是半圆形纵联分段并列式结构，由6道纵联石和7段拱碹石构成，碹脸外边有拱眉石，拱眉凸出于碹脸，拱眉与侧墙取平。跨径4.80米。', '', 10, NULL, NULL, '', 8, 2, 8, 1, '苏州市吴江区同里镇', '花岗岩', 50, 109, '2026-04-28 23:07:54', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1012, '永安桥', '永安桥是一座单孔石拱桥，与世德桥通称“周庄双桥”。桥面中部(拱顶上)高起为平面，两端是阶梯式坡道。两侧有节间式石栏杆，每侧有望柱4根，栏板3段，两端是抱鼓石。无地伏，桥栏杆置于仰天石上。桥面宽2.40米，桥长13.30米。侧墙用花岗岩石板砌筑，上面有单层青石仰天石。桥台是凹字形，前面和两侧有出台，前墙长2.80米。因为端墙很短，桥堍在河岸上。拱碹是半圆形纵联分段并列式结构，由6道纵联石和7段拱碹石构成，碹脸外边镶有拱眉石，拱眉凸出于碹脸，又凸出于侧墙。跨径3.50米。', '', 10, NULL, NULL, '', 10, 1, 10, 1, '昆山市周庄镇', '花岗岩（侧墙）、青石（仰天石）', 50, 110, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1013, '贞丰桥', '贞丰桥是一座单孔石拱桥。桥面中部高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆，每侧有望柱4根，栏板3块，抱鼓石2块，无地伏，桥栏杆置于仰天石上。桥面全宽3.60米，净宽2.80米，桥长12.20米。侧墙用料石砌筑，上顶有单层仰天石组成的金边线。桥台是凹字形，下部前面和两边有小出台。拱碹是半圆形纵联分段并列式结构，碹脸外边有拱眉石，拱眉凸出于碹脸，又凸出于侧墙。跨径4.40米。', '', 10, NULL, NULL, '', 8, 1, 8, 1, '昆山市周庄全福路，跨街河上', '石材（料石）', 50, 111, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1014, '皋桥（又名兴福桥）', '桥面是圆弧形，上面铺砌石板。两侧有节间式石栏杆，每侧有4根望柱，桥栏杆与河岸上的石栏杆对接。无地伏，桥栏杆置于仰天石上。桥面宽4.27米，桥长15.03米。侧墙用料石砌筑，上顶有双层仰天石组成的金边线。桥台是凹字形，前墙长4.90米，端墙的外端与石砌河岸为一体。拱碹是半圆形分段并列式结构(龙门碹是纵联石),由5道纵联石和6段拱碹石构成，无拱眉，碹脸与侧墙平。跨径9.90米。碹脸上方两边的侧墙上各有一个勾头石。', '', 10, NULL, NULL, '', 6, 1, 6, 1, '太仓市城内西门街，跨街河上', '石材（料石、石板）', 50, 112, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1015, '金鸡桥', '金鸡桥是一座单孔石拱桥。桥塊和桥面为弧形，铺砌青石板，中间有一块石板上雕有雄鸡高歌。桥上无栏杆，两边各有一道较厚的边牙石(相当于仰天石)。桥面宽2.37米，桥长11.70米。侧墙用料石砌筑，上顶有单层仰天石组成的金边线。桥台是凹字形，前墙长4.00米。拱碹是半圆形分段并列式结构，由5段拱碹石构成，每段拱碹石由3块或4块石件组成。碹脸外无拱眉石，碹脸与侧墙平。跨径5.10米。端墙以上的侧墙上，各有一根石柱，石柱的上面有石座，石座端面上雕荷叶图案。', '', 10, NULL, NULL, '', 6, 1, 10, 1, '太仓市城厢镇新丰村，跨朱里泾河上', '青石板、料石', 50, 113, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1016, '太仓井亭桥', '井亭桥是一座3孔石拱桥。桥面宽3.37米，桥长16.70米。中孔跨径5.80米。3孔券石都是5道，每道以四五块青石砌成。中孔北面券石中央有一组铭文，铭文碑上有荷叶浮雕相邻，下有莲花浮雕相托。因桥堍原有一座供过往行人休息的石亭而得名，此桥又名“众安桥”。', '', 10, NULL, NULL, '', 6, 1, 6, 1, '太仓市城厢镇新丰村', '青石', 50, 114, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1017, '太仓州桥', '州桥原名“安福桥”。桥面中部(中孔上)高起为平面，两端是阶梯式坡道。两侧有板式石栏杆。无地伏，桥栏杆置于仰天石上。桥面宽4.00米，净宽3.20米，桥长16.20米。侧墙用料石砌筑，上顶有双层仰天石组成的金边线。桥台是凹字形，前面和两边有小出台，前墙长4.40米。桥墩的两端与拱脚取齐，四周有小出台，桥墩厚1.00米，桥墩长4.40米。拱碹是半圆形纵联分段并列式结构，中孔拱碹由6道纵联石和7段拱碹石构成，边孔拱碹由4道纵联石和5段拱碹石构成，碹脸外边有拱眉石，拱眉凸出于碹脸，拱眉与侧墙取平。中孔跨径8.05米，北孔跨径6.20米。', '', 10, NULL, NULL, '', 6, 1, 10, 1, '江苏省太仓市城厢镇府南街南端，横跨致和塘', '石材（料石）', 50, 115, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1018, '周泾桥', '桥塊和桥面上铺砌青石板，桥面为圆弧形，两侧有石砌宇墙式栏杆，无地伏，桥栏杆置于仰天石上。桥面宽4.58米，桥长17.26米。侧墙用料石砌筑，上顶有双层仰天石组成的金边线。桥台是凹字形，前墙长5.20米，端墙很短，端墙与石砌河岸连砌为一体。桥墩两端与拱脚取齐，四周有小出台，桥墩厚70厘米，桥墩长4.90米。拱碹为半圆形纵联分段并列式结构，无拱眉，碹脸与侧墙取平。中孔跨径11.60米，边孔跨径7.60米。', '', 10, NULL, NULL, '', 6, 1, 10, 1, '太仓市城内东街，跨于致和塘上', '青石板、料石', 50, 116, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1019, '帆影桥', '帆影桥是一座单孔石拱桥。桥面中部(拱顶上)高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆，桥面宽3.55米，桥长36.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，拱碹是半圆形纵联分段并列式结构，有拱眉，拱眉凸出于碹脸，又凸出于侧墙。跨径8.00米。', '', 10, NULL, NULL, '', 10, 1, 10, 1, '无锡市鼋头渚公园内，在鼋头渚旁边', '石材（料石）', 50, 117, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1020, '梁塘桥', '桥面中部(拱顶上)高起为平面，两端是阶梯式坡道，南北两坡各有22级台阶。两侧原有节间式石栏杆，今尚存青石地伏，桥面宽3.00米。桥长21.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长3.40米。拱碹是半圆形纵联分段并列式结构，有拱眉，拱眉凸出于碹脸，又凸出于侧墙。跨径7.00米。碹脸上方两侧各有一个勾头石。在桥孔两边的侧墙上各有一根桥联柱，上顶有勾头石。', '', 10, NULL, NULL, '', 8, 1, 8, 1, '无锡市滨湖区扬名乡，跨街河上', '料石、青石', 50, 118, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1021, '巡塘桥', '巡塘桥是一座单孔石拱桥。桥面中部(拱顶上)高起为平面，两侧有石板栏杆，中间栏板下面的一块石板上镌刻着“重建古巡塘桥”六个大字。两端是阶梯式坡道，桥面宽2.80米，桥长17.20米。侧墙用块石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长3.20米。拱碹是圆弧形纵联式结构，有拱眉，拱眉凸出于碹脸，又凸出于侧墙。跨径5.00米。', '', 10, NULL, NULL, '', 8, 1, 8, 1, '无锡市滨湖区巡塘古镇，跨巡塘河上', '石材（块石、石板）', 50, 119, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1022, '扬名桥', '扬名桥是一座3孔薄拱薄墩轻型石拱桥。桥面中部(中孔上)高起为平面，两端是阶梯式坡道。两侧有节间式石栏杆，每侧有望柱4根，栏板3段，抱鼓石2块。桥面宽3.75米，桥长49.50米。侧墙用料石砌筑，上顶有单层青石仰天石组成的金边线。桥台是凹字形，前面和两侧下部有出台。桥墩两端与拱脚取齐，四周有出台，桥墩厚10.50米，桥墩长4.20米。拱碹是半圆形纵联分段并列式结构，均由6道纵联石和7段拱碹石构成，碹脸外边有拱眉石，拱眉凸出于碹脸，又凸出于侧墙。中孔跨径12.00米，边孔跨径10.00米。', '', 10, NULL, NULL, '', 8, 1, 10, 1, '无锡市滨湖区跨梁塘河上', '料石、青石', 50, 120, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1023, '陆墟桥', '陆墟桥是一座单孔石拱桥。桥面中部(拱顶上)高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆，桥面宽3.00米，桥长19.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长3.40米。拱碹是半圆形纵联分段并列式结构，有拱眉，拱眉凸出于碹脸，又凸出于侧墙。跨径7.00米。碹脸上方两侧各有一个勾头石。', '', 10, NULL, NULL, '', 5, 1, 5, 1, '无锡市惠山区陆区镇，跨街河上', '料石', 50, 121, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1024, '伯渎桥', '伯渎桥是一座单孔石拱桥，桥面中部(拱顶上)高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆，桥面宽3.00米，桥长30.00米。侧墙是用块石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长3.40米。拱碹是圆弧形纵联式结构，无拱眉。跨径20.00米。', '', 10, NULL, NULL, '', 8, 1, 8, 1, '无锡市梁溪区，跨伯渎河上，位于清名桥东南', '石材（块石）', 50, 122, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1025, '定胜桥', '定胜桥是一座单孔石拱桥。桥面中部(拱顶上)高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆，桥面宽3.60米，桥长26.00米。侧墙用石板砌筑，上顶有单层青石仰天石。桥台是凹字形，前墙长4.00米。拱碹是半圆形纵联分段并列式结构，有拱眉，拱眉凸出于碹脸，拱眉与侧墙平。跨径4.50米。', '', 10, NULL, NULL, '', 10, 1, 10, 1, '无锡市梁溪区定胜河上', '石板、青石', 50, 123, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1026, '跨塘桥', '桥面中部(拱顶上)高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆，桥面宽4.00米。桥长27.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长4.40米。拱碹是半圆形纵联分段并列式结构，有拱眉，拱眉錾出双层拱眉线，拱眉凸出于碹脸，又凸出于侧墙。跨径7.00米。碹脸上方两侧各有两个石雕龙头。在桥孔两边的侧墙上各有一根桥联柱，上顶有勾头石。', '', 10, NULL, NULL, '', 7, 1, 7, 1, '无锡市梁溪区南长街，跨塘河(古运河)上', '料石', 50, 124, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1027, '清名桥', '桥面中部高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆，每侧有望柱4根，栏板3块，抱鼓石两块。无地伏，桥栏杆置于仰天石上。桥面宽5.50米，桥长43.20米。侧墙用料石砌筑，上顶有单层仰天石组成的金边线。桥台是凹字形，前面和两侧有出台，前墙长5.80米。拱碹是半圆形纵联分段并列式结构，由8道纵联石和9段拱碹石构成，碹脸的外立面为凹字形(两边凸起),每道拱碹石的接缝上嵌有一块铁铜子。碹脸凸出于侧墙。跨径13.10米。', '', 10, NULL, NULL, '', 8, 1, 8, 1, '江苏省无锡市梁溪区南长街跨古运河上', '料石、石材', 50, 125, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1028, '承先桥', '承先桥又名“崇村桥”。桥面中部(拱顶上)高起为平面，两端是阶梯式坡道，两侧原有节间式石栏杆，今已无存。桥面宽3.80米，桥面长18.00米，全长34.00米，侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形。拱碹是半圆形纵联分段并列式结构，有拱眉，拱眉凸出于碹脸，拱眉与侧墙平。', '', 10, NULL, NULL, '', 8, 1, 8, 1, '无锡市锡山区与江阴市交界的崇村白荡窄口处', '石材（料石）', 50, 126, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1029, '大成桥', '大成桥是一座单孔石拱桥。桥面中部(拱顶上)高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆，桥面宽3.85米，桥长22.00米。桥台是凹字形。拱碹是半圆形纵联分段并列式结构，有拱眉，拱眉凸出于碹脸，又凸出于侧墙。跨径20.00米。', '', 10, NULL, NULL, '', 8, 1, 8, 1, '无锡市锡山区安镇大成村，跨宛山荡中的大堤上', '石材', 50, 127, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1030, '耕读桥', '耕读桥是一座单孔石拱桥。桥面中部(拱顶上)高起为平面，两端是阶梯式坡道，南北各有22级台阶，两侧有节间式石栏杆，桥面宽3.00米。桥长27.00米。侧墙用料石砌筑，上顶有单层较宽的仰天石，拱顶上面的仰天石上刻有“耕读桥”三个大字。桥台是凹字形，前墙长3.50米。拱碹是半圆形纵联分段并列式结构，有拱眉，拱眉錾出双层拱眉线，拱眉凸出于碹脸，又凸出于侧墙。跨径6.60米。两面碹脸上方两侧各有两个石雕龙头。桥孔两边的侧墙上各有一根桥联柱，上顶有勾头石。桥联柱上有对联。东面的上联是“沃壤植桑麻抱布贸丝人利涉”，下联是“佳名易耕读高车驷马管留题”。西面的上联是“南里岁丰穰风送稻花香匝地”，下联是“西溪波潋滟云沉米水如天”。', '', 10, NULL, NULL, '', 8, 1, 8, 1, '无锡市南门外耕读河上', '料石', 50, 128, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1031, '永济桥', '桥面中部(中孔上)高起为平面，两端是阶梯式坡道。两侧有板式石栏杆。无地伏，桥栏杆置于仰天石上。桥面宽4.55米，桥塊端宽6.60米，桥长50.18米。侧墙用料石砌筑，上顶有双层仰天石组成的金边线。桥台是凹字形，前面和两边有小出台，前墙长约5.00米，端墙很长，端部有八字燕翅墙。桥墩的两端与拱脚取齐，四周有小出台，桥墩厚70厘米，桥墩长约5.00米。拱碹是半圆形纵联分段并列式结构，中孔拱碹由10道纵联石和11段拱碹石构成，边孔拱碹由6道纵联石和7段拱碹石构成，碹脸外边有拱眉石，拱眉凸出于碹脸，拱眉与侧墙取平。中孔跨径12.40米，矢高约6.25米，边孔跨径5.70米，矢高约3.00米。', '', 10, NULL, NULL, '', 8, 1, 8, 1, '常熟市城南门外，跨元和塘上', '石材（料石、仰天石、纵联石、拱碹石、拱眉石）', 50, 129, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1032, '李家桥', '李家桥是一座单孔石拱桥。桥面中部(拱顶上)高起为平面，两端是阶梯式坡道。两侧有节间式石栏杆。桥面宽3.56米，桥长27.78米。侧墙用料石砌筑，上面有单层仰天石，桥台是凹字形，前墙长3.60米。拱碹是半圆形分段并列式结构，碹脸的龙门上有石雕龙头，碹脸外边有拱眉石，拱眉凸出于碹脸，拱眉凸出于侧墙。跨径7.60米。', '', 10, NULL, NULL, '', 8, 1, 8, 1, '常熟市李桥村', '石材（料石）', 50, 130, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1033, '常熟拂水桥', '拂水桥又名“福庆桥”,俗称“三条桥”。桥面中部(拱顶上)高起为平面，两端是阶梯式坡道，南北坡道各有27级台阶，两侧有节间式石栏杆。桥面宽3.00米，桥长30.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，拱碹是半圆形纵联分段并列式结构，有拱眉，跨径9.20米，矢高4.60米。', '', 10, NULL, NULL, '', 8, 1, 8, 1, '常熟市虞山镇，在二条桥以西一公里处，跨山前河上', '石材（料石）', 50, 131, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1034, '文学桥', '文学桥又称言子墓道桥。桥面中部高起为平面，两端是阶梯式坡道。两侧各有一道很矮的石板，无地伏。桥面3.00米，桥长21.00米。侧墙用料石砌筑，上面有单层仰天石。桥台是凹字形，前墙长3.00米。拱碹是半圆形纵联分段并列式结构，碹脸外边有拱眉石，拱眉凸出于碹脸，拱眉与侧墙平。跨径9.00米。桥孔两侧的桥联柱上有对联，南面的上联是“道接东山远”，下联是“源分墨井香”；北面的上联是“东南开道脉”，下联是“今古挹文澜”。', '', 10, NULL, NULL, '', 10, 1, 10, 1, '常熟市庐山镇东陵口言子墓前', '石材（料石）', 50, 132, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1035, '月河桥（紫薇桥）', '桥面中部高起为平面，两端是阶梯式坡道，两坡各设20级踏级，桥面全部铺砌五康石板，两侧各有矮式青石板栏杆，无地伏，桥栏杆置于侧墙上。桥面全宽3.61米，桥长17.37米。侧墙用料石砌筑，上面有单层仰天石。桥台是凹字形，前墙长3.60米。拱碹是分段并列式结构，由7段拱碹石构成，碹脸外边有拱眉石，拱眉凸出于碹脸，拱眉与侧墙平。跨径6.61米。拱碹上方两边的侧墙上各有一个勾头石。', '', 10, NULL, NULL, '', 10, 1, 10, 1, '江苏省常熟市梅李镇月河上', '五康石板、青石板、料石', 50, 133, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1036, '常熟甸桥（又名“头条桥”）', '甸桥是一座单孔石拱桥。桥面中部(拱顶上)高起为平面，两端是阶梯式坡道。两侧有节间式石栏杆，每侧有4根望柱，3段栏板，2块抱鼓石。桥面宽2.85米，桥长25.88米。桥堍翼墙和桥身侧墙用花岗岩石板砌筑，上面有单层青石仰天石。桥台是凹字形。拱碹是半圆形纵联石结构，碹脸外边有拱眉石，拱眉凸出于碹脸，拱眉与侧墙平。拱碹是半圆形纵联分段并列式结构，碹脸外边有拱眉石，拱眉凸出于碹脸，又凸出于侧墙。跨径9.44米。', '', 10, NULL, NULL, '', 8, 1, 8, 1, '常熟市虞山镇', '花岗岩石板（桥堍翼墙和桥身侧墙）、青石（仰天石）', 50, 134, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1037, '广嗣桥', '广嗣桥又名“退戌戊桥”，俗称联登桥。桥面中部(拱顶上)高起为平面，两端是阶梯式坡道，南坡道长10.40米，北坡道长12.40米。两侧有节间式石栏杆，每侧有望柱6根，栏板5块，抱鼓石2块。无地伏，桥栏杆置于仰天石上。桥面全宽4.20米，净宽3.28米，桥长21.25米。侧墙用花岗岩石板砌筑，上顶有单层青石仰天石组成的金边线，仰天石的外面与侧墙取平。桥台是凹字形，前墙长4.20米。前面和两侧皆有小出台。拱碹是半圆形纵联分段并列式结构，由8道纵联石和9段拱碹石构成，碹脸外有拱眉石，拱眉凸出于碹脸，又凸出于侧墙。跨径12.50米，矢高6.30米。碹脸上方两边的侧墙上各有一个勾头石，桥孔两边(桥台上)的侧墙上各有一根桥联柱，上顶有勾头石。桥联柱上刻有对联。', '', 10, NULL, NULL, '', 8, 1, 8, 1, '常熟市虞山镇小东门外，跨于莲墩浜上', '花岗岩（侧墙）、青石（仰天石）', 50, 135, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1038, '顺民桥', '顺民桥是一座单孔石拱桥。桥塊和桥面上铺砌花岗石，桥面中部 (拱顶上)高起为平面，两端是阶梯式坡道。两侧有节间式石栏杆，无地伏。桥面宽3.60米，桥长26.30米。桥塊翼墙和桥身侧墙是用花岗岩石板砌筑，上面有单层青石仰天石。桥台是凹字形，端墙很长，前面和两侧有出台。拱碹是半圆形分段并列式结构，碹脸外边有拱眉石，拱眉凸出于碹脸，又凸出于侧墙。跨径11.60米，矢高5.80米。碹脸上方两边的侧墙上各有一个勾头石，桥孔两边(桥台上)的侧墙上各有一根桥联柱，上顶有勾头石。', '', 10, NULL, NULL, '', 8, 1, 8, 1, '常熟市虞山镇北门外李桥村与张坝村交界处，跨福山塘上', '花岗石、青石', 50, 136, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1039, '常熟香花桥', '香花桥是一座单孔石拱桥。桥堍和桥面上铺砌花岗岩石板，桥面中部（拱顶上）高起为平面，两端是阶梯式坡道，各有踏步16级。两侧有节间式石栏杆，每侧有望柱4根，栏板3段，抱鼓石2块。无地伏，桥栏杆置于仰天石上。桥面宽3.25米，桥面长10.50米，桥长50.00米。桥堍翼墙和桥身侧墙是用花岗岩石板砌筑，上面有单层青石仰天石。桥台是凹字形，前面和左右两面皆有出台。拱碹是半圆形纵联分段并列式结构，碹脸外边有拱眉石，拱眉凸出于碹脸，又凸出于侧墙。跨径5.40米。碹脸上方两边的侧墙上各有一个勾头石。拱碹两边（桥台上）的侧墙上各有一根桥联柱，上顶有勾头石。桥联柱上有对联，东面的上联是“弓影腾空流通万壑”，下联是“花名独表香透重门”；西面的上联是“雁齿横排去烟出没”，下联是“虹腰高卧泉石奔腾”。', '', 10, NULL, NULL, '', 8, 1, 8, 1, '江苏省常熟市虞山寺山门前，跨拂水岩上', '花岗岩、青石', 50, 137, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1040, '常熟玉带桥', '玉带桥是一座7孔石拱桥。桥面呈正圆弧形，两侧有节间式石栏杆，桥面宽4.30米，桥长51.50米。侧墙使用料石砌筑，上顶有双层仰天石。桥台是凹字形，桥墩两端与拱脚齐平，桥墩长4.30米。拱碹是半圆形纵联式结构，有拱眉，拱眉凸出于碹脸，拱眉与侧墙平。各孔跨径依次是5.00米、5.50米、6.00米、6.50米、6.00米、5.50米、5.00米。', '', 10, NULL, NULL, '', 10, 1, 10, 1, '常熟市虞山公园内', '石材、料石', 50, 138, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1041, '云庆桥（又名“钓渚渡桥”“鸟嘴渡桥”）', '云庆桥是一座3孔石拱桥。桥面中部(中孔拱顶上)高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆，望柱上顶与栏板齐平，每侧有望柱8根，栏板7块，抱鼓石2块，无地伏，桥栏杆置于仰天石上。桥面全宽3.20米，净宽2.50米，桥长59.00米。侧墙用料石砌筑，上顶有单层仰天石组成的金边线。桥台是凹字形，前墙长2.90米。桥墩两端是方形，桥墩厚95厘米，桥墩长2.90米。拱碹是半圆形纵联分段并列式结构，碹脸外边有拱眉石，拱眉凸出于碹脸，又凸出于侧墙。中孔跨径8.00米，边孔跨径4.50米。各孔碹脸上方两边的侧墙上各有一个勾头石，桥墩上和边孔拱碹外边(桥台上)的侧墙上各有一根桥联柱，上顶皆有勾头石。', '', 10, NULL, NULL, '', 8, 1, 8, 1, '常熟市张桥镇卫浜村，跨运河次航道(羊尖塘)上', '料石', 50, 139, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1042, '万安桥', '桥面中部(中孔拱顶上)高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆，桥面宽5.50米，桥长57.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，桥墩两端是方形。拱碹是半圆形纵联分段并列式结构，有拱眉，拱眉凸出于碹脸，又凸出于侧墙。中孔跨径15.00米，边孔跨径12.00米。', '', 10, NULL, NULL, '', 5, 1, 10, 1, '江阴市跨夏港河上', '石材', 50, 140, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1043, '五云桥', '五云桥是一座单孔石拱桥。桥面中部(拱顶上)高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆，桥面宽4.60米，桥长21.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，拱碹是半圆形纵联分段并列式结构，有拱眉，拱眉凸出于碹脸，又凸出于侧墙。跨径18.50米。桥孔两侧的侧墙上有桥联柱，上顶有勾头石。南面上联是“桥卧长虹亿万姓咸歌利济”,下联是“江镇净练百千年常庆安澜”。北面上联是“建一邑之鸿规会其有拯”,下联是“乐四民之利济惠节无疆”。', '', 10, NULL, NULL, '', 8, 1, 8, 1, '江阴市城南门外，跨古锡澄运河上', '料石', 50, 141, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1044, '画溪桥', '画溪桥是一座3孔石拱桥。桥面中部(中孔拱顶上)高起为平面，两侧有节间式石栏杆，桥面4.00米，桥长33.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长4.00米，前面和两侧下部有小出台。拱碹是半圆形分段并列式结构(龙门碹是纵联石)，由8段拱碹石构成，无拱眉，碹脸与侧墙平。中孔跨径9.50米，边孔跨径8.60米。', '', 10, NULL, NULL, '', 8, 1, 8, 1, '宜兴市丁罗镇', '石材', 50, 142, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1045, '鲸塘桥', '桥面中部是平面，两端是阶梯式坡道，上下各有42级踏步。两侧有板式分节石栏杆，无地伏，桥栏杆置于仰天石上。桥面全宽5.46米，净宽4.50米，桥长44.20米。侧墙用料石砌筑，上顶有双层仰天石组成的金边线。桥台是凹字形，前墙长5.50米，前面和两侧下部有小出台。桥墩两端是方形，四周有小出台，桥墩厚1.00米，桥墩长5.90米。拱碹是半圆形纵联分段并列式结构，碹脸外边镶有拱眉石，拱眉凸出于碹脸，又凸出于侧墙。中孔跨径8.00米，边孔跨径7.70米。中孔碹脸上方两边的侧墙上各有一个勾头石，桥墩上和边孔外边的侧墙上各有一根桥联柱，上端有勾头石。桥联柱上有对联，东面的上联是“荷叶地钟灵料有才人题柱去”，下联是“鲸溪波效顺迎凤仙客泛槎回”；西面的上联是“左墨岭右烟峰积翠千寻排对岸”，下联是“南桃溪北濑水长虹一道跨中流”。', '', 10, NULL, NULL, '', 8, 1, 8, 1, '宜兴市鲸溪河上', '料石', 50, 143, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1046, '庆丰桥', '庆丰桥是一座单孔石拱桥。桥面中部(拱顶上)高起为平面。两端是阶梯式坡道，两侧有节间式石栏杆，桥面宽5.00米，净宽4.10米，桥塊端宽7.00米，桥面长25.00米，全长31.80米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形。拱碹是半圆形纵联分段并列式结构，有拱眉。跨径7.80米。', '', 10, NULL, NULL, '', 8, 1, 10, 1, '盐城市大丰区草堰乡丁溪村，跨丁溪夹河上', '料石', 50, 144, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1047, '扬州二十四桥', '今存二十四桥是一座单孔石拱桥。桥梁立面呈穹隆形，俗称“单驼峰式”,桥面中部(拱顶上)是圆弧形，两端是阶梯式坡道，各有12级踏步，桥堍的平面呈梯形，俗称喇叭形。两侧有节间式石栏杆，每侧有12根望柱，11块栏板，2块抱鼓石。桥面宽2.40米，桥长24.00米。桥堍翼墙和侧墙用料石砌筑，上面有双层仰天石组成的金边线。桥台是凹字形，端墙的外端有燕翅墙，前墙长3.00米。拱碹是近似三心圆弧形(俗称鸭蛋形)分段并列式结构，碹脸外边有拱眉石，拱眉凸出于碹脸，拱眉凸出于侧墙。跨径10.50米。', '', 10, NULL, NULL, '', 8, 1, 8, 1, '江苏省扬州市瘦西湖上', '料石', 50, 145, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1048, '扬州五亭桥', '五亭桥原名“莲花桥”，桥上建有五座木结构亭。全桥从外面看共有大小15孔（包括两个半跨孔），实际上是10孔。中间是一个大跨径孔，跨径7.00米，其拱碹是半圆形纵联分段并列式结构，由6道纵联石和7段拱碹石构成，碹脸外边镶有双线拱眉石。中孔两边为大型桥墩（台座），顶面顺河方向长19.00米，顺桥方向宽20.00米，四周有节间式石栏杆。台座下面顺河方向及顺桥方向各有一孔，跨径均为4.50米。大桥墩以外各有2孔，内侧孔为半幅。桥台呈凹字形，桥墩两端为方形。桥梁全长55.00米。', '', 10, NULL, NULL, '', 8, 1, 8, 1, '江苏省扬州市瘦西湖上', '石材、木材', 50, 146, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1049, '丁卯桥', '丁卯桥是一座单孔闸桥合一的石拱桥。桥面中部(拱顶上)为平面，两端是阶梯式坡道。两侧有节间式石栏杆，每侧有4根望柱，3段栏板，2块抱鼓石。桥面宽3.00米，桥长25.00米。桥塊翼墙和桥身侧墙是用花岗岩石板砌筑，上面有单层青石仰天石。桥台是凹字形，前墙的上游端伸出桥身以外为闸台。拱碹是半圆形纵联分段并列式结构，碹脸外边有拱眉石，拱眉凸出于碹脸，拱眉与侧墙取平。跨径9.44米。', '', 10, NULL, NULL, '', 8, 1, 10, 1, '镇江市丹徒区', '花岗岩石板、青石', 50, 147, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1050, '中和双桥', '中和双桥是一座单孔石板梁桥。桥面是5块石板梁，两侧有石板栏杆，桥面宽3.90米，桥长13.00米。桥台与石板砌筑的河岸为一体。跨径4.05米。', '', 10, NULL, NULL, '', 6, 2, 6, 1, '昆山市锦溪镇', '石板', 50, 148, '2026-04-28 23:07:54', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1051, '大陵桥', '大陵桥是一座单孔石梁桥。桥面是5块石板梁，两侧有石栏杆，桥面4.75米，桥长12.00米。桥台是凹字形。跨径6.50米。', '', 10, NULL, NULL, '', 8, 2, 8, 1, '苏州市吴江区黎里镇，跨市河上', '石材', 50, 149, '2026-04-28 23:07:54', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1052, '进登桥', '进登桥是一座单孔石板梁桥。桥面是花岗岩石板梁，两侧有石板栏杆，桥面宽4.75米，桥长12.00米。桥台是凹字形，用料石砌筑，前墙前面有4根方形石柱，上顶架设石帽梁。跨径6.50米。', '', 10, NULL, NULL, '', 8, 2, 8, 1, '苏州市吴江区黎里镇，跨市河上', '花岗岩、料石', 50, 150, '2026-04-28 23:07:54', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1053, '迎祥桥（又名“汝家桥”）', '迎祥桥是一座3孔石板梁桥。中孔桥面是平面，边孔桥面是坡面 (桥头低),两侧有石板栏杆，桥面宽4.50米，桥长12.00米。桥台与料石砌筑的河岸为一体。桥墩是4根方形石柱，上顶有石板帽梁。中孔跨径6.00米，边孔跨径2.50米。', '', 10, NULL, NULL, '', 8, 2, 10, 1, '苏州市吴江区黎里镇市河上', '石材（料石、石板）', 50, 151, '2026-04-28 23:07:54', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1054, '东庙桥', '桥面宽2.10米，桥长21.50米。桥台是凹字形，前墙是竖立设置的3块条形石板，上顶有石板盖梁，盖梁长2.50米。桥墩也是竖立设置的3块条形石板，中孔跨径4.60米，边孔跨径4.20米。', '', 10, NULL, NULL, '', 10, 2, 10, 1, '苏州市吴江区七都镇', '花岗岩石板', 50, 152, '2026-04-28 23:07:54', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1055, '泰安桥', '桥面宽2.40米，桥长20.00米。桥台是凹字形，前墙是竖立设置的3块条形石板，上顶有石板盖梁，盖梁长2.50米。桥墩也是竖立设置的3块条形石板，上顶有石板盖梁，盖梁长2.50米。中孔跨径5.00米，边孔跨径4.20米。', '', 10, NULL, NULL, '', 8, 2, 10, 1, '苏州市吴江区盛泽镇黄家溪村', '花岗岩', 50, 153, '2026-04-28 23:07:54', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1056, '中和桥', '中孔桥面是5块石板梁，为平面，两端是阶梯式坡道，下面各有一孔石拱，拱碹是半圆形纵联分段并列式结构，有双线拱眉，拱眉凸出于碹脸，又凸出于侧墙。桥上两侧有石板栏杆，无地伏，桥栏杆置于仰天石上，桥面宽2.65米，桥塊端宽3.05米，桥长18.50米。侧墙用料石砌筑，上顶有仰天石。桥台与石板砌筑的河岸为一体，桥墩两端是方形，桥墩厚约1.00米，桥墩长3.00米。中孔跨径5.50米，边孔跨径3.20米。', '', 10, NULL, NULL, '', 8, 1, 10, 1, '苏州市吴江区盛泽镇王家庄，跨市河上', '石材（石板梁、料石、石板）', 50, 154, '2026-04-28 23:07:54', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1057, '中元桥', '中孔桥面为平面，两边孔桥面为坡面，桥面是3块石板梁，两侧有石栏杆，桥面宽3.10米，桥长16.50米。桥台是凹字形。桥墩是4根方形石柱，上顶有石板横梁，横梁宽80厘米，长4.00米，中孔跨径5.00米，边孔跨径3.00米。', '', 10, NULL, NULL, '', 10, 2, 10, 1, '苏州市吴江区同里镇东埭村，跨洪字圩和冲字圩汇合处', '石材', 50, 155, '2026-04-28 23:07:54', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1058, '香花桥', '香花桥是一座3孔石板梁桥。中孔桥面为平面，边孔桥面为坡面，桥面每孔是3块石板梁，无栏杆，桥面宽2.09米，桥梁全长16.10米。桥台用石板砌筑，其平面为凹字形。桥墩是3根方形石柱，上顶有石板横梁，横梁宽80厘米，横梁长2.95米。中孔跨径4.66米，边孔跨径3.66米。', '', 10, NULL, NULL, '', 8, 2, 8, 1, '苏州市相城区黄埭镇老街西端，跨街河上', '石材', 50, 156, '2026-04-28 23:07:54', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1059, '金莲桥', '今存金莲桥是一座3孔石板梁桥。桥塊上铺砌花岗岩石板，桥面是花岗岩石板梁，每孔有4块石板梁。两侧有节间式石栏杆，每侧有6根望柱、5块栏板和2块抱鼓石。下面有矩形断面的地伏石。桥面宽3.04米，桥长10.70米。桥台是凹字形，桥墩两端是4根方形石柱，上顶架一根石板帽梁，帽梁宽80厘米，帽梁长4.60米。中孔跨径4.00米，边孔跨径2.70米。', '', 10, NULL, NULL, '', 10, 2, 10, 1, '无锡市梁溪区惠山寺前面', '花岗岩石板', 50, 157, '2026-04-28 23:07:54', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1060, '飞虹桥', '飞虹桥是一座单孔石板梁桥。桥面较高为平面，桥塊上是坡面，两侧有石栏杆。桥面宽6.20米，桥长22.00米。桥台是凹字形。跨径6.60米。', '', 10, NULL, NULL, '', 10, 2, 10, 1, '无锡市锡山区东亭街道祗陀寺前', '石材', 50, 158, '2026-04-28 23:07:54', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1061, '乐稼桥', '乐稼桥是一座3孔石板梁桥。桥面每孔3块石板梁，无栏杆，桥面宽3.30米，桥长20.90米。桥台是凹字形。桥墩是4根方形石柱，上顶架一根石板帽梁，帽梁宽80厘米，帽梁长4.00米。中孔跨径5.50米，边孔跨径3.50米。', '', 10, NULL, NULL, '', 10, 2, 10, 1, '无锡市锡山区鹅湖镇(原荡口镇)新桥村', '石材', 50, 159, '2026-04-28 23:07:54', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1062, '荆山桥', '今存荆山桥是一座159孔石拱与石梁混合桥，中间19孔是石拱桥，南段95孔是石板梁桥，北段45孔是石板梁桥。两侧有石栏杆，桥面宽7.00米，桥长1615米。另有资料记载为169孔，中间29孔是石拱桥，南段95孔是石板梁桥，北段45孔是石板梁桥。南北桥台和拱桥都是凹字形。桥墩两端全是方形，桥墩厚1.00米，桥墩长2.55米，石拱桥的拱碹是半圆形纵联式结构，无拱眉，跨径12.00米。石梁桥跨径5.50—6.50米。史料记载桥身原长362.5丈(1160米),顶宽1.9丈(6.10米)。', '', 10, NULL, NULL, '', 8, 1, 8, 1, '徐州市经济技术开发区', '石材', 50, 160, '2026-04-28 23:07:54', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1063, '黄洲桥', '现存桥是一座9孔等跨径石拱桥。全桥(桥塊和桥面)为平面，两侧有节间式石栏杆，桥面宽6.25米，桥长139.00米。侧墙用料石砌筑，上顶单层仰天石。桥台为凹字形，前面和两侧皆有出台，前墙长7.00米。桥墩的两端为方形，四周有出台，桥墩厚2.75米，桥墩长7.90米。拱碹是半圆形纵联式结构，碹脸外有拱眉石，碹脸、拱眉、侧墙三者取平。跨径均为14.50米。', '', 14, NULL, NULL, '', 8, 1, 10, 1, '抚州市崇仁县城内跨崇仁河上', '料石、石材', 50, 51, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1064, '南城万年桥', '今存桥是一座23孔厚拱厚墩重型石拱桥。桥面大致是平面，两侧有节间式石栏杆，桥面全宽6.30米，净宽5.80米，桥长411.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是燕翅形，前墙长约7.00米。桥墩上游端是尖形，下游端是方形，桥墩顶面厚3.40米，桥墩顶面长7.40米。拱碹是半圆形镶边纵联式结构，跨径13.40—15.00米(大部分是14.00米)。', '', 14, NULL, NULL, '', 8, 1, 8, 1, '抚州市南城县城东北歇羊渡，跨盱江上', '石料（料石）、混凝土', 50, 52, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1065, '万安古城桥', '古城桥是一座11孔石拱桥。桥堍和桥面上铺砌红砂岩石板，桥面大致为平面，两侧原有节间式石栏杆，损坏多处。地伏石完整存在。桥面宽6.40米，桥梁全长180.00米。侧墙用料石砌筑，上顶有单层仰天石组成的金边线。桥台两侧有燕翅墙，前墙长7.60米，桥墩上游端是尖形，下游端是方形，拱碹是半圆形纵联式结构，碹脸外边有拱眉石，碹脸、拱眉与侧墙齐平。河水较深，跨径未能测量，估计约14.00米。', '', 14, NULL, NULL, '', 8, 1, 8, 1, '吉安市万安县水南村跨横江上', '红砂岩石板、料石', 50, 53, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1066, '永丰恩江桥', '恩江桥由济川桥和平政桥连接而成，全桥共19孔，全长355.75米。平政桥跨于小恩江上，为10孔石拱桥，桥长168.00米，桥面宽5.40米，侧墙用青石板砌筑，桥墩两端为方形，拱碹为半圆形纵联式结构。济川桥跨大恩江上，为9孔石拱桥，桥长152.00米，桥面宽6.10米，桥墩上游端为尖形，下游端为方形，拱碹为半圆形纵联式结构。两桥相距35.75米，并非直线对接。', '', 14, NULL, NULL, '', 8, 1, 8, 1, '江西省吉安市永丰县，跨大恩江与小恩江', '青石板、石材、混凝土', 50, 54, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1067, '永新龙源口桥（久大桥）', '桥面高起为平面，桥堍均为阶梯式坡道，无栏杆，两侧各有一道边牙石。桥面宽4.95米，净宽4.30米，桥长23.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是燕翅形，前墙长约6.00米。拱碹是半圆形纵联分段并列式结构，由10道纵联石和11段拱碹石构成，碹脸外边有拱眉石，拱眉凸出于碹脸，又凸出于侧墙。跨径14.90米。', '', 14, NULL, NULL, '', 8, 1, 10, 1, '吉安市永新县龙源口村（七里溪岭下）', '石材（料石）', 50, 55, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1068, '庐山观音桥', '观音桥原名“栖贤桥”，又称“三峡桥”。桥面宽4.00米，桥长24.40米。桥塊和桥面上铺砌大块石板，两侧有节间式石栏杆和石地伏。侧墙用料石砌筑，上顶有单层仰天石。桥台是燕翅形，前墙长4.00米。拱碹是半圆形并列式结构，由7道拱碹石构成，拱碹石两端采取凹凸形榫接，无拱眉。跨径10.00米。', '', 14, NULL, NULL, '', 10, 1, 10, 1, '江西省庐山市白鹿镇栖贤谷（三峡涧）上', '石材（大块石板、料石、拱碹石）', 50, 56, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1069, '钟陵桥', '钟陵桥是一座3孔石拱桥。桥塊和桥面上铺砌红砂岩石板，桥略显圆弧形，桥栏杆无存，地伏尚存，地伏的断面是矩形。桥面宽5.45米，桥长25.90米。侧墙用料石砌筑，上顶有断面为矩形的仰天石。桥台是燕翅形，前墙长约7.00米。桥墩上游端是尖形，下游端是方形，桥墩厚1.50米，桥墩长7.00米。拱碹为半圆形纵联式结构，无拱眉，碹脸与侧墙取平。中孔跨径5.45米，边孔跨径4.00米。', '', 14, NULL, NULL, '', 8, 1, 8, 1, '南昌市进贤县钟陵河上', '红砂岩石板、料石', 50, 57, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1070, '铅山大义桥', '今存大义桥是一座7孔石拱桥。桥塊和桥面上铺砌石板面层，全桥为平面，两侧有节间式石栏杆，地伏是矩形断面。桥面宽6.50米，桥长110.00米。侧墙用石板砌筑，上顶有双层仰天石。桥台是凹字形，桥墩两端与拱脚取平，拱碹是半圆形纵联式结构，无拱眉，碹脸与侧墙平。跨径12.00米。', '', 14, NULL, NULL, '', 10, 1, 10, 1, '上饶市铅山县永平镇', '石板', 50, 58, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1071, '抚州文昌桥', '现存文昌桥是一座12孔石拱桥。桥面宽6.40米，桥长230.00米（2002年加宽后桥面宽11.00米，桥长255.40米）。桥塊和桥面上铺砌青石板，桥面大致是平面，两侧有石砌宇墙式栏杆，无地伏，桥栏杆砌筑在仰天石上。侧墙用条形石板砌筑，上面有单层仰天石组成的金边线。桥台两侧有燕翅墙。桥墩上游端是尖形，下游端是方形，桥墩厚1.50米，桥墩长7.90米。拱碹是半圆形纵联式结构，无拱眉，碹脸与侧墙平。跨径17.50米。', '', 14, NULL, NULL, '', 8, 1, 5, 1, '江西省抚州市区，跨汝水(今抚河)上', '青石板（桥面）、条形石板（侧墙）、混凝土（1958年更换栏杆）、沥青（1958年铺筑面层）', 50, 59, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1072, '步瀛桥', '步瀛桥是一座3孔石拱桥。全桥为平面，两侧有石板栏杆。桥面宽4.50米，桥长30.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是燕翅形。桥墩两端是尖形。拱碹是半圆形纵联式结构，跨径均为8.50米。', '', 14, NULL, NULL, '', 5, 1, 10, 1, '宜春市三阳镇上甘棠村', '料石、石板', 50, 60, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1073, '宜春长桥', '今存长桥是一座5孔石拱桥。桥面是弧形，桥栏杆无存，地伏石尚存。桥面宽5.50米，桥长63.00米。侧墙用石板砌筑，上顶有双层仰天石。桥台在河岸上，桥墩上游端为尖形，下游端是方形。拱碹是半圆形纵联式结构。中孔跨径10.00米，次边孔跨径9.50米，边孔跨径9.00米。', '', 14, NULL, NULL, '', 8, 1, 10, 1, '宜春市', '石材', 50, 61, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1074, '宜春升瀛桥（俗称“新桥”）', '升瀛桥是一座4孔石拱桥。东3孔跨仰溪河上，桥面长50.00米。西1孔跨支流上，桥面长6.00米，两段桥相隔约50.00米。全桥为平面，桥面宽6.00米，全桥长约100.00米。侧墙用块石砌筑，上顶有单层仰天石。桥台是燕翅形，桥墩两端是尖形，跨径17.50米。', '', 14, NULL, NULL, '', 8, 1, 10, 1, '宜春市温汤乡刘坊村，跨仰溪河与其支流上', '块石', 50, 62, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1075, '逢渠桥', '桥面为平面，桥塊为缓坡道，无栏杆。桥面宽4.70米，桥长11.40米。侧墙用块石砌筑，上顶有一层较高仰天石，而成边牙石。桥台被埋于河岸中，拱碹是半圆形纵联式结构，碹脸外有较厚的拱眉石，碹脸、拱眉与侧墙取平。跨径4.28米，矢高2.10米。碹脸上方有一块石匾，镌刻“逢渠桥”三个大字。桥孔两边的侧墙上各立有一个石雕护桥神像。', '', 14, NULL, NULL, '', 7, 1, 10, 1, '宜春市宜丰县洞山村', '石材（块石）', 50, 63, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1076, '永镇桥', '永镇桥是一座3孔石墩台悬臂式木梁桥。上部结构是双层杉圆木叠合纵梁，两层圆木纵梁之间有疏铺方木横系梁，纵梁两端下面有3层圆木悬臂梁，各层悬臂梁之间有疏铺方木横系梁。纵梁上面疏铺方木横梁，横梁上面铺木桥面板，桥面宽4.33米，桥长38.50米。桥上建楼式通廊，在长廊门额上书写正楷“永镇桥”三个大字。桥台用花岗岩条形石板砌筑，两侧与块石砌筑的弧形护墙相连。桥墩上游端是尖形，下游端是方形。跨径均为12.50米。', '', 14, NULL, NULL, '', 10, 2, 10, 1, '赣州市安远县新龙乡永镇村，跨甲江河上', '杉圆木、方木、木桥面板、花岗岩条形石板、块石', 50, 64, '2026-04-28 23:07:54', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1077, '婺源彩虹桥', '桥上建有11间通廊，中孔的廊上建有亭子。桥面净宽3.00米，桥长140.00米。桥上建砖木结构廊。桥台是凹字形，前墙长4.00米。桥墩很厚，两端方形，桥墩厚2.50米，桥墩长4.00米。跨径6.50米。', '', 14, NULL, NULL, '', 8, 2, 8, 1, '上饶市婺源县清华镇', '石（墩台）、木（桥面）、砖木（廊）', 50, 65, '2026-04-28 23:07:54', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1078, '思溪桥', '思溪桥是一座双孔石墩台木梁桥。上部结构是圆木纵梁，纵梁上面铺木桥面板，木板上铺墁砖面。桥面宽3.10米，桥长16.50米。桥上建砖木结构廊。桥台是燕翅形，用料石砌筑。桥墩也是料石砌筑，上游端是尖形，下游端是方形。跨径均为5.60米。', '', 14, NULL, NULL, '', 10, 2, 10, 1, '上饶市婺源县思溪桥村', '圆木（纵梁）、木（桥面板）、砖（桥面）、料石（桥台、桥墩）', 50, 66, '2026-04-28 23:07:54', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1079, '安国伍仁桥', '伍仁桥又名贵妃桥。今存伍仁桥是一座5孔石拱桥。桥塊和桥面上铺砌花岗岩石板，桥面纵断呈正圆弧形竖曲线，两侧有节间式青石栏杆，每侧有望柱24根，栏板23块，抱鼓石两块。望柱的柱头雕有狮子。下面有青石地伏。桥面宽5.70米，净宽5.00米，桥梁全长57.00米。翼墙和侧墙是用料石砌筑，上顶有双层仰天石组成的金边线。桥台是带燕翅形，前墙长7.00米。桥墩两端为尖形。拱碹是半圆形纵联式结构，碹脸外边有拱眉石，拱眉凸出于碹脸，拱眉与侧墙平。中孔跨径10.00米，次边孔跨径9.00米，边孔跨径8.00米。', '', 3, NULL, NULL, '', 7, 1, 7, 1, '安国市伍仁桥镇磁河上', '花岗岩石板、青石、料石', 50, 51, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1080, '保定方顺桥', '桥长16.60米，高5.30米，阔8.00米。中孔跨径13.30米，二边孔跨径3.30米。桥面上铺砌花岗岩石板，桥面是圆弧形竖曲线，两侧有节间式石栏杆。望柱的柱头是狮子，栏板为实体板，地伏是矩形断面，地伏后退于金边0.16米。侧墙是用条形石板砌筑，上顶有单层仰天石组成的金边线。桥台是凹字形，前墙长8.00米，桥台上各有一个小孔洞。拱碹是圆弧形纵联分段并列式结构，由12道纵联石和13段拱碹石构成，龙门上有石雕龙头。碹脸外边镶有拱眉石，拱眉凸出于碹脸，又凸出于侧墙。', '', 3, NULL, NULL, '', 8, 1, 2, 1, '保定市满城区方顺桥村，跨方顺河上', '花岗岩石板、条形石板', 50, 52, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1081, '绿野梯桥', '绿野梯桥是一座3孔石拱桥。桥面上铺砌花岗岩石板，桥面略显圆弧形，无栏杆，无地伏。桥面宽4.10米，桥长9.10米。桥塊翼墙和侧墙是用花岗岩石板砌筑，上面有较厚的青石仰天石 (略高出桥面)。桥台两侧有燕翅墙，前墙长5.30米。桥墩两端是尖形。拱碹是半圆形纵联式结构，中孔碹脸龙门上有石雕龙头，碹脸外边有拱眉石，拱眉凸出于碹脸，拱眉与侧墙齐平。中孔跨径3.00米，边孔跨径2.00米。', '', 3, NULL, NULL, '', 10, 1, 10, 1, '保定市莲池区', '花岗岩石板、青石', 50, 53, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1082, '下胡良桥', '下胡良桥是一座7孔石拱桥。桥塊和桥面上铺砌不规则形青石板，桥面呈穹隆形，两侧有节间式石栏杆，地伏是矩形断面。桥面宽9.14米，桥长69.00米。桥塊翼墙和侧墙是用料石砌筑，上顶有单层仰天石组成的金边线，桥台两侧有燕翅墙，前墙长10.00米。桥墩两端是尖形。拱碹是半圆形纵联式结构，中三孔龙门上有石雕龙头，碹脸外边有拱眉石，拱眉凸出于碹脸，拱眉与侧墙平。', '', 3, NULL, NULL, '', 7, 1, 7, 1, '涿州市城北东仙坡镇下胡良村，跨胡良河上', '青石板、料石', 50, 54, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1083, '涿州永济桥', '永济桥是一座9孔厚拱厚墩重型石拱桥。桥面全宽10.70米，净宽8.70米，桥长151.15米。桥面铺砌花岗岩石板，圆弧形，两侧有节间式石栏杆。翼墙和侧墙用花岗岩石砌筑，上顶有单层仰天石组成的金边线。桥台两侧有燕翅墙，前墙长约11.90米。桥墩上游端为尖形，下游端是方形，厚5.10米，长14.50米。拱碹是半圆形纵联式结构，碹脸外边有拱眉石。南引桥长271.50米，北引桥长约205.00米。桥梁全长(包括引桥)627.65米。乾隆帝曾赐名并题联，有“十八省通衢”之称。', '', 3, NULL, NULL, '', 8, 1, 8, 1, '河北省涿州市城北拒马河上', '花岗岩、石材', 50, 55, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1084, '登瀛桥（杜林桥）', '登瀛桥是一座3孔石拱桥。桥堍和桥面上铺砌花岗岩石板，桥面略显圆弧形。两侧有节间式石栏杆，无地伏石，望柱置于仰天石上，望柱上端雕刻狮子、麒麟、猴子。栏板为实体板，每块栏板下面有三块方形石块，两面雕刻有人物、走兽等图案。桥面宽7.80米，桥长66.00米。翼墙和侧墙用料石砌筑，上顶有单层仰天石组成的金边线。桥台是凹字形，端墙的外端有燕翅墙，前墙长9.00米。桥墩两端为尖形。拱碹是半圆框形纵联式结构，龙门碹上皆有石雕龙头，碹脸外面雕有花饰，碹脸外边有拱眉石，拱眉凸出于碹脸，又凸出于侧墙。跨径均为11.30米。两个桥墩上各有一个馒头形小孔洞，拱碹是半圆形纵联式结构，龙门上也有龙头，跨径均为1.80米。桥头有一通石碑和一对石狮子。', '', 3, NULL, NULL, '', 8, 1, 8, 1, '河北省沧州市沧县杜林镇，跨滹沱河故道上', '花岗岩石板（桥堍和桥面）、料石（翼墙和侧墙）', 50, 56, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1085, '献县单桥', '单桥是一座5孔石拱桥，在4个桥墩上各有一个小跨径孔，全桥共有大小9孔。桥面宽9.50米，桥梁全长96.00米。桥堍平面呈喇叭形，铺砌花岗岩石板，桥面有多条车辙沟。两侧有节间式石栏杆，每侧有望柱32根，栏板31块，抱鼓石两块。望柱柱头雕兽，柱身雕花。全桥62块栏板共雕刻72幅图像。栏板下面有空隙可泄雨水。翼墙和侧墙用条形石板砌筑。桥台两侧有燕翅墙，前墙长10.50米。拱碹为半圆形镶边纵联式结构，各孔均为9道碹脸石，龙门有石雕龙头，碹脸石接缝嵌有银锭铁，外边镶有拱眉石。南边孔跨径15.00米，北边孔跨径9.80米，小孔跨径1.80米。', '', 3, NULL, NULL, '', 7, 1, 10, 1, '河北省沧州市献县乐寿镇单桥村', '石材、花岗岩石板、条形石板、银锭铁', 50, 57, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1086, '弘济桥', '弘济桥是一座单孔敞肩式石拱桥。桥面宽6.82米，净宽6.00米，桥面长45.00米，全长48.90米。两侧有节间式石栏杆，每侧有望柱18根，栏板17块，抱鼓石两块。望柱柱头雕有狮子、猴子、桃形、石榴形；栏板雕有鹿、麒麟、花卉。桥台为凹字形，前墙长8.00米。拱碹为圆弧形并列式结构，主孔跨径31.88米，矢高6.02米。主孔拱碹两端各有两个小跨径孔，内二小孔跨径1.60米，外二小孔跨径2.00米。碹脸雕刻有龙头、龙、凤、飞马、花卉等图案。侧墙和翼墙用不规整石板砌筑，上顶有单层矩形断面仰天石。', '', 3, NULL, NULL, '', 7, 1, 7, 1, '邯郸市永年区广府镇跨滏阳河上', '青石板、石材', 50, 58, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1087, '邯郸学步桥', '桥名“学步桥”出自《庄子 · 秋水》篇。学步桥是一座3孔石拱桥，桥台和桥墩上各有一个小跨径孔，全桥是3大孔4小孔。桥塊和桥面铺砌花岗岩石板，全桥为平面，两侧有节间式石栏杆，每侧有望柱18根，栏板17块，抱鼓石两块。望柱的柱头上雕有形态各异的狮子，柱身两面雕有花饰，栏板为实体板，两面雕有人物、走兽等图案。桥面宽8.30米，桥长35.00米。桥塊翼墙和桥身侧墙采用规整的石板砌筑，上面有单层较厚仰天石组成的金边线。桥台是带燕翅形，前墙长9.50米。桥墩上游端是尖形，下游端是方形。拱碹是半圆形镶边纵联式结构，碹脸上雕有花饰，龙门上有石雕龙头，碹脸外边有拱眉石，拱眉凸出于碹脸，拱眉与侧墙平。大孔的跨径均为6.20米。', '', 3, NULL, NULL, '', 7, 1, 7, 1, '邯郸市沁河上', '石材、花岗岩石板', 50, 59, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1088, '衡水安济桥', '今存安济桥是一座7孔厚拱厚墩重型石拱桥。桥塊和桥面上铺砌青石板。桥面大致为平面，两侧有节间式石栏杆，每侧有望柱58根，柱上有形态各异的石狮，栏板57块。栏板是寻杖下镂空式，两端各有一只较大的石狮子，无地伏，桥栏杆置于仰天石上。桥梁全长116.00米。桥塊翼墙和侧墙是用料石砌筑，上顶有单层仰天石组成的金边线。桥台两侧有燕翅墙。桥墩上游端为尖形，下游端是方形，桥墩厚4.30米。拱碹是半圆框形纵联式结构，由14道纵联石和每面15块碹脸石组成框形结构，内部是纵联石，中三孔的龙门上各有一个石雕龙头，无拱眉，碹脸与侧墙平，各孔拱碹的龙门上皆有龙头。跨径皆10.00米。', '', 3, NULL, NULL, '', 8, 1, 8, 1, '河北省衡水市桃城区跨滏阳河上', '青石板、料石', 50, 60, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1089, '安固桥', '安固桥是一座单孔石拱桥。桥堍和桥面上铺砌青(石灰岩)石板，两侧有节间式石栏杆，每侧有6根望柱，5块栏板，两块抱鼓石。桥身段各有4根望柱，3块栏板，八字栏杆各有1根望柱，1块栏板，1块抱鼓石。桥面全宽6.90米，净宽6.00米，桥梁全长54.00米。侧墙是用青石板砌筑，上顶有单层仰天石。桥台两侧有燕翅墙，前墙长8.30米。拱碹是半圆形纵联式结构，碹脸外边有拱眉石，碹脸、拱眉与侧墙平。跨径8.50米。桥头有明清残碑，上半段大部分不知去向。', '', 3, NULL, NULL, '', 8, 1, 10, 1, '石家庄市高邑县方珊乡南邱村，跨新沟河上', '青(石灰岩)石板', 50, 61, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1090, '功德桥', '功德桥是一座单孔石拱桥。桥塊和桥面用青(石灰岩)石板铺砌，两侧有节间式石栏杆，每侧有4根望柱，3块栏板，两块抱鼓石。桥身段各有4根望柱，3块栏板，八字栏杆是一块抱鼓石。桥面全宽6.40米，净宽5.50米，桥面长21米，全长52.90米。侧墙是用青石板砌筑，上顶有单层仰天石。桥台两侧有燕翅墙，前墙长7.80米。拱碹是半圆形纵联式结构，碹脸外边有拱眉石，碹脸、拱眉与侧墙平。跨径8.60米。桥头有清代残碑一段，左上方有“大清道光二十八口□□□□”。', '', 3, NULL, NULL, '', 8, 1, 10, 1, '石家庄市高邑县方珊乡南邱村，跨新沟河上', '青(石灰岩)石板', 50, 62, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1091, '井陉苍岩山桥', '桥上建有一座两层式歇山顶楼阁，故又称“楼殿桥”。桥面两侧和两端(楼门两边)有节间式白石栏杆。桥面宽9.00米，桥面长15.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台在山崖上开凿而成。拱碹是圆弧形镶边纵联式结构，碹脸上雕有花饰，碹脸的龙门上石雕龙头，碹脸外边有两层拱眉石，内层拱眉的外面为平面，外层拱眉的外面是凹字形，拱眉与侧墙取平。跨径10.70米，矢高3.30米。桥身上部较窄，下部(拱脚处)较宽，下部比上部宽出40厘米。', '', 3, NULL, NULL, '', 10, 1, 10, 1, '河北省石家庄市井陉县苍岩山上，跨于山涧上', '石材（料石、白石）', 50, 63, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1092, '井陉垂虹桥（平顺桥）', '桥塊和桥面上铺砌青石板，桥面略显圆弧形，两侧有节间式石栏杆，每侧有望柱14根，栏板13块，抱鼓石两块。其中，桥身上有望柱12根，栏板11块，桥塊上八字栏杆各有望柱1根，栏板1块，抱鼓石1块。望柱的柱头上有大小狮子、石猴。栏板上雕刻鹤、犬、鹿、荷花图案。桥面宽6.00米，桥长32.00米。侧墙用料石砌筑，上顶有单层仰天石组成的金边线。桥台是带燕翅形，前墙长7.20米。桥墩上游端是尖形，下游端是方形，拱碹是半圆形纵联式结构，碹脸外边有拱眉石，拱眉凸出于碹脸，又凸出于侧墙。中孔跨径6.20米，边孔跨径5.40米。', '', 3, NULL, NULL, '', 8, 1, 8, 1, '石家庄市井陉县赵村店村南，跨于无名沟渠上', '青石板、料石', 50, 64, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1093, '井陉逸仙桥', '今存桥是一座12孔石拱桥。属于厚拱厚墩石拱桥，桥塊和桥面上铺砌不规则青石板，全桥大致为平面。两侧有节间式石栏杆，两端各有一段块石砌筑的宇墙式栏杆。桥面宽7.20米，桥长208.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台两侧有燕翅墙，前墙长8.40米。桥墩两端是圆形，桥墩端部的上面是圆锥体。拱碹均为半圆形纵联式结构，碹脸龙门上皆有石雕龙头，碹脸与侧墙齐平。跨径均为7.20米。', '', 3, NULL, NULL, '', 8, 1, 8, 1, '石家庄市井陉县城东征水镇，跨治河上', '青石板（桥塊和桥面）、料石（侧墙）、块石（宇墙式栏杆）', 50, 65, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1094, '清宁桥', '修复后的清明桥全长44.20米，宽5.08米。桥两边望柱共有36根，雕刻精美。桥面板下部分为原来的建筑，整个桥身由三个拱券组成，中孔跨径12.50米，边孔跨径5.06米。', '', 3, NULL, NULL, '', 4, 1, 4, 1, '石家庄市栾城区窦妪镇南北赵村之间，横跨液河故道上', '石', 50, 66, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1095, '永济桥', '永济桥是一座5孔石拱桥。桥堍和桥面上铺砌青石板，桥面略显圆弧形，两侧有节间式石栏杆，每侧有24根望柱，栏板23块，两块抱鼓石。望柱的柱头是桃形，栏板是实体板，两面皆有雕刻图案。无地伏，桥栏杆置于仰天石上。桥面宽6.30米，桥长70.00米。侧墙用料石砌筑，上顶有单层仰天石组成的金边线。桥台两侧有燕翅墙。桥墩两端是尖形。拱碹是半圆形纵联式结构，无拱眉。中孔跨径13.70米，边孔跨径12.10米。', '', 3, NULL, NULL, '', 7, 1, 7, 1, '石家庄市赵县城西，跨清水河上', '青石板（桥面及栏杆）、料石（侧墙）', 50, 67, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1096, '升仙桥', '升仙桥是一座单孔类似敞肩式石拱桥，桥面上铺砌青石板，中间略显圆弧形，两侧有节间式石栏杆，每侧原有望柱14根，栏板13块，抱鼓石两块。其中，桥身上有望柱12根，栏板11块，桥堍上八字栏杆各有望柱1根，栏板1块，抱鼓石1块。桥面宽6.00米，桥长15.30米。翼墙和侧墙用料石砌筑，上顶有单层仰天石组成的金边线。桥台是凹字形，前墙长12.00米。拱碹是圆弧形并列式结构，由20道拱碹石构成，碹脸龙门上有石雕龙头，碹脸外边镶有拱眉石，拱眉凸出于碹脸，拱眉与侧墙齐平。跨径11.30米。拱碹上面两端各有一个小跨径孔，拱碹的内拱脚建在主孔拱碹两端，外拱脚建在桥台上面增建的小台上。两个小孔的拱碹均系半圆形纵联式结构，由8道碹石构成，碹脸外边镶有拱眉石，碹脸的龙门上也有石雕龙头，跨径均为2.45米。', '', 3, NULL, NULL, '', 5, 1, 10, 1, '石家庄市行唐县旧县城西门外，跨护城河上', '青石板、料石', 50, 68, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1097, '赵县安济桥', '安济桥是一座单孔敞肩式石拱桥。桥面铺砌青石板，有车辙沟和“驴蹄印”。全桥纵断面呈正圆弧竖曲线，两侧原有节间式青石栏杆，望柱形式多样，有圆柱形和圆球形，栏板为实体板。桥面原宽9.00米，桥梁全长50.83米。侧墙用青石板砌筑，上顶有单层仰天石组成的金边线。桥台长方形，前墙长9.50米。拱碹是圆弧形并列式结构，原有28道拱碹石，尚存25道。拱碹厚1.03米，碹脸接缝有银锭铁，龙门有石雕龙头。跨径37.02米，矢高7.23米。拱碹上面两端各有两个小跨径孔，外二小孔跨径3.81米，内二小孔跨径2.85米。南端有关帝庙。', '', 3, NULL, NULL, '', 3, 1, 3, 1, '河北省石家庄市赵县城南大石桥村村北跨洨河上', '青石', 50, 69, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1098, '济美桥', '济美桥是一座4孔石拱桥。中墩上有一个小跨径孔。桥塊和桥面上铺砌青石板，桥面大致为平面，桥塊上是缓坡面。两侧有节间式青石栏杆，望柱的柱头为方形截锥体，栏杆下面无地伏，望柱直接置于金边(仰天石)上；栏板为实体板，每块栏板的下面两端垫一块方石墩，栏板上有雕刻花饰。桥面宽4.00米，桥长50.00米。侧墙用料石砌筑，上顶有单层仰天石组成的金边线，金边对侧墙外出檐约16厘米。桥台两侧有燕翅墙，前墙长5.20米。桥墩的两端是尖形。中二孔拱碹是圆弧形并列式结构，龙门上有石雕龙头，碹脸外边皆镶有拱眉石。两个边孔的拱碹是半圆形纵联式结构，龙门上有石雕龙头，碹脸外边皆镶有拱眉石。中墩上小孔的拱碹也是半圆形纵联式构造，龙门上有石雕龙头，碹脸外边皆镶有拱眉石。', '', 3, NULL, NULL, '', 7, 1, 7, 1, '石家庄市赵县宋村村东北，跨于液河上', '青石板、料石', 50, 70, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1099, '赵县沙河店桥', '桥面上铺砌青石板，中间略显圆弧形，两侧有节间式石栏杆，望柱和栏板的规格与形式参差不齐。桥面宽15.00米，桥长37.00米。翼墙和侧墙用不规则石板砌筑，上顶有单层仰天石。桥台是凹字形，前墙长16.20米。拱碹是圆弧形并列式构造，由16道拱碹石构成，碹脸龙门上有石雕龙头，碹脸外边镶有拱眉石，拱眉凸出于碹脸，拱眉与侧墙齐平。跨径7.50米。拱碹上面两端各有一个小跨径孔，小孔拱碹的内拱脚落在主孔拱碹两端，外拱脚落在桥台上，小孔内的净空即拱碹的矢高。小孔拱碹均系半圆形纵联式结构，由5道碹石构成，碹脸外边镶有拱眉石，碹脸的龙门上也有石雕龙头，跨径均为1.62米。', '', 3, NULL, NULL, '', 8, 1, 8, 1, '石家庄市赵县城南沙河店村，跨沙河上', '青石板、石材', 50, 71, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1100, '赵县永通桥', '永通桥是一座单孔敞肩石拱桥，其造型与安济桥相似。桥面上铺砌花岗岩石板，全桥略显弧形，两侧有节间式石栏杆，望柱是方形柱头，栏板是寻杖下镂空式，板面上有浮雕，每侧栏杆长32.70米。桥面宽6.34米，桥长32.00米。侧墙用料石砌筑，上顶有单层(断面为矩形)仰天石组成的金边线。桥台是凹字形，前墙长7.50米。拱碹是圆弧形并列式结构，由20道碹石构成，龙门碹上有石雕龙头，碹脸儿外缘镶有拱眉，拱眉凸出于碹脸，拱眉与侧墙取平。跨径26.00米，矢高5.34米。主拱碹上两端各有两个小孔洞，内侧小孔的拱碹是半圆形并列式结构，有七块碹脸石，碹脸外有拱眉，碹脸、拱眉与侧墙取平，跨径是1.80米。外侧小孔的拱碹是圆弧形并列式结构，有五块碹脸石，碹脸外有拱眉，碹脸、拱眉与侧墙取平，跨径3.00米。两个小拱碹的撞碹上雕有“河神”人头像。', '', 3, NULL, NULL, '', 7, 1, 7, 1, '石家庄市赵县西门外，跨清水河上', '花岗岩石板、料石、碹石', 50, 72, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1101, '正定太平桥', '太平桥是一座13孔石拱桥。桥塊和桥面上铺砌青石板，两侧有节间式石栏杆。桥面宽7.20米，桥长数据暂缺。侧墙用料石砌筑，上顶有单层仰天石。桥台燕翅形。桥墩上游端是尖形，下游端是方形。拱碹是半圆形纵联式结构，碹脸外边有拱眉石。', '', 3, NULL, NULL, '', 10, 1, 10, 1, '石家庄市正定县', '青石板（桥塊和桥面）、料石（侧墙）', 50, 73, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1102, '响水桥', '响水桥是一座3孔石拱桥。桥塊和桥面上铺砌条形石板，两侧有节间式青石栏杆，每侧有望柱10根，栏板9块，抱鼓石两块。望柱是平顶方形柱头。其中，桥身段有望柱8根，栏板7块，八字栏杆各有望柱1根，栏板1块，抱鼓石1块。桥面全宽5.70米，净宽4.80米，桥长15.60米。侧墙用料石砌筑，上顶有单层青石仰天石组成的金边线。桥台是燕翅形，燕翅墙长13.00米，前墙长6.50米。桥墩两端是尖形。拱碹是半圆形纵联式结构，中孔龙门上有石雕龙头，无拱眉，碹脸与侧墙平。中孔跨径3.70米，边孔跨径2.70米。桥下有石板海墁，海墁下游有五级跌水，每层落差40厘米，第一层宽4.00米，第二层宽4.00米，第三层宽2.00米，第四层宽3.00米，第五层又是一段海墁。', '', 3, NULL, NULL, '', 8, 1, 8, 1, '唐山市迁西县榛子镇，跨龙湾河上', '条形石板、青石、料石', 50, 74, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1103, '彩亭桥', '彩亭桥是一座3孔石拱桥。桥塊和桥面上顺桥铺砌5条青石板，两侧有节间式石栏杆，每侧有望柱12根，栏板11块，抱鼓石两块。其中，桥身段上有望柱8根，栏板7块，八字栏杆各有望柱2根，栏板2块，抱鼓石1块。望柱的柱头上有狮子、莲花瓣、桃形图案。地伏是矩形断面。桥面宽6.00米，桥长19.00米。侧墙用料石砌筑，上顶有单层青石仰天石组成的金边线。桥台两侧有燕翅墙，前墙长7.00米。桥墩两端的平面是梯形。拱碹是半圆形纵联式结构，龙门上皆有石雕龙头，龙头两侧各有3段碹脸石，无拱眉，碹脸与侧墙平。跨径4.50米。桥墩以上的侧墙上各有一个石雕龙头。', '', 3, NULL, NULL, '', 10, 1, 10, 1, '唐山市玉田县彩亭桥镇，跨古兰泉河上', '青石板、料石、青石', 50, 75, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1104, '临城紫金桥', '紫金桥俗称“双岔紫金桥”，是两座单孔石拱桥的统称，二桥相距约27米，其间有石堤。二桥的结构形式完全相同，桥堍和桥面上铺砌青石板，两侧有节间式青石栏杆，每侧有望柱10根，栏板9块，抱鼓石两块。下面有青石地伏。桥面宽均为6.20米，桥长均为27.00米。二桥(包括石堤)全长约81.00米。桥堍翼墙和侧墙用青石板砌筑，上顶有单层仰天石组成的金边线。桥台两侧有燕翅墙，前墙长7.40米。拱碹是半圆形纵联式结构，碹脸外边有拱眉石，拱眉凸出于碹脸，拱眉与侧墙齐平。跨径均为16米。', '', 3, NULL, NULL, '', 8, 1, 8, 1, '邢台市临城县竹壁村', '青石、青石板', 50, 76, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1105, '古町桥', '古町桥是一座单孔石拱桥。桥面上铺砌青石板，桥面呈圆弧形，两侧各有一道青石板栏杆，栏板高60厘米，下面有青石地伏，地伏高17厘米，宽28厘米。桥面宽6.60米，桥长21.00米。侧墙用花岗岩石板砌筑，上顶有单层仰天石。桥台是带燕翅形，拱碹是半圆形纵联式结构，碹脸外边有拱眉石，碹脸、拱眉与侧墙平。跨径6.60米。', '', 3, NULL, NULL, '', 10, 1, 10, 1, '邢台市宁晋县', '青石板、花岗岩石板', 50, 77, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1106, '邢台如意桥', '如意桥是一座单孔石拱桥。桥面中部(拱顶上)高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆，每侧有望柱6根，栏板5块，抱鼓石两块。桥面宽6.80米，桥长24.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形。拱碹是半圆形纵联式结构，有拱眉，拱眉、碹脸与侧墙平。跨径11.50米，矢高5.8米。', '', 3, NULL, NULL, '', 7, 1, 7, 1, '邢台市(原顺德府)邢台县良舍村', '料石', 50, 78, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1107, '遵化五音桥', '五音桥是一座7孔石拱桥。桥堍在河岸上，桥堍和桥面上铺砌青白石板，全桥桥面呈穹隆形。两侧有节间式白石栏杆，每侧有望柱64根，栏板63块，抱鼓石2块。其中，桥身上望柱48根(含角柱)，栏板47块，桥堍上的八字栏杆各有望柱8根，栏板8块，1块抱鼓石。地伏也是白石料，矩形断面。桥面宽10.40米，桥长110.60米。侧墙是用青白石石板砌筑，上顶有双层仰天石组成的金边线，侧墙、翼墙和仰天石均为白石料。桥台是凹字形，前墙长10.40米。桥墩两端为方形。拱碹是半圆形镶边纵联式结构，碹脸与侧墙齐平。中孔跨径16.00米。', '', 3, NULL, NULL, '', 8, 1, 8, 1, '河北省遵化市清孝陵(世祖爱新觉罗 · 福临——顺治)的御道上', '方解石（栏板）、青白石（桥面、侧墙）、白石（栏杆、地伏、翼墙、仰天石）', 50, 79, '2026-04-28 23:07:54', '2026-04-28 23:36:18');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1108, '承德水心榭桥', '水心榭桥是一座8孔石板梁桥。全桥为平面，桥面宽4.50米，桥长43.00米。中二孔上建一座砖木结构重檐亭，边墩上各有一座砖木结构重檐亭。桥台是凹字形，前墙长4.50米。桥墩两端是方形，两个边墩厚5.00米，中间的5个桥墩较薄，厚度均为2.00米。跨径均为3.00米。', '', 3, NULL, NULL, '', 8, 2, 8, 1, '承德避暑山庄，跨山庄湖水面上', '石板、砖木', 50, 80, '2026-04-28 23:07:54', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1109, '高邑广济桥（凤仙桥）', '广济桥原是一座5孔石板梁桥。今存中间3孔，两端桥塊和中三孔桥面外露，全桥用花岗岩石料砌筑，桥塊上横铺条形石板。桥面每孔是4块石板梁，石板梁长5.80米，无栏杆，桥面宽3.25米，桥面长17.50米，原桥全长36.50米。原有桥是燕翅形，现外露桥是原有桥墩，两侧增砌燕翅墙。桥墩两端是尖形。跨径均为5.00米。', '', 3, NULL, NULL, '', 8, 2, 8, 1, '石家庄市高邑县西北营乡东驿头村，跨悒河上', '花岗岩石料', 50, 81, '2026-04-28 23:07:54', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1110, '古贤桥', '古贤桥是一座3孔石拱桥。桥塊和桥面铺砌条形石板，全桥为平面，桥栏杆无存。桥面宽8.30米，桥身长31.00米，桥梁全长50.00米。翼墙和侧墙是用条形石板砌筑，上面有单层仰天石组成的金边线。桥台两侧有燕翅墙，前墙长9.50米。桥墩两端是尖形。中孔跨径8.00米，边孔跨径7.00米。', '', 16, NULL, NULL, '', 7, 1, 10, 1, '安阳市汤阴县', '条形石板', 50, 51, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1111, '云溪桥', '云溪桥是一座5孔石拱桥。桥塊和桥面铺砌条形石板，全桥为平面，桥栏杆无存，地伏石尚存。桥面宽12.00米，桥面长49.20米，全长60.00米。翼墙和侧墙是用条形石板砌筑，上面有单层仰天石组成的金边线。桥台两侧有燕翅墙，前墙长13.20米，燕翅墙上皆有镇水石兽。桥墩两端是尖形。拱碹是半圆形纵联式结构，碹脸外面雕有花饰，中孔龙门上有石雕“虎头”,无拱眉。跨径均为8.00米。', '', 16, NULL, NULL, '', 7, 1, 10, 1, '鹤壁市浚县云溪镇南门外，跨卫河(古代永济渠)上', '条形石板', 50, 52, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1112, '堰口桥', '堰口桥是一座单孔石拱桥。桥面宽5.00米，桥长20.00米。侧墙是用条形石板砌筑，上顶有单层仰天石。桥台两侧有燕翅墙，前墙长5.20米。拱碹是半圆形纵联式结构，龙门上有龙头。碹脸外边有拱眉，拱眉与侧墙平。跨径3.40米。', '', 16, NULL, NULL, '', 3, 1, 3, 1, '鹤壁市山城区石林乡', '条形石板', 50, 53, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1113, '临颍小商桥', '桥面全部铺青石板，桥面宽7.60米，净宽6.67米，桥梁全长20.87米（1958年修栏杆后桥长25.90米）。侧墙用料石砌筑，上面有双层仰天石组成的金边线。桥台两侧有燕翅墙，前墙长7.90米，桥台四角下部雕有金刚力士像，双肩扛拱，双手上托。拱碹是圆弧形并列式结构，由20道拱碹石并列构成，碹脸宽65厘米，外面雕有花饰，龙门上有石雕龙头。碹脸外边有双层拱眉石。跨径11.60米，矢高约2.20米。拱碹上面两端各一个小跨径孔，跨径2.13米，矢高约1.20米。', '', 16, NULL, NULL, '', 8, 1, 8, 1, '河南省漯河市临颍县城南小商河(颍河故道)上', '石材（青石板、料石）', 50, 54, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1114, '永和桥', '永和桥是一座3孔石拱桥。桥塊和桥面上铺砌石灰岩石板，桥面呈圆弧形，两侧有节间式青石栏杆，石件不全。望柱的柱头上有石狮子，栏板是实体板，无通长地伏石，望柱下面是一块方形青石板，栏板的两端搭在方形石板上。桥面宽6.80米，桥面长31.50米，桥梁全长39.50米。侧墙用青石板砌筑，上顶有单层青石仰天石组成的金边线。桥台是燕翅形，前墙长约8.00米。桥墩两端是尖形。拱碹均系半圆形镶边纵联式结构，中孔碹脸龙门上有石雕龙头，碹脸外面皆有雕刻的图案。碹脸外边有拱眉石，拱眉凸出于碹脸，拱眉与侧墙平。中孔跨径7.00米，边孔跨径4.50米。', '', 16, NULL, NULL, '', 10, 1, 10, 1, '河南省平顶山市叶县跨洹河故道上', '石灰岩、青石', 50, 55, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1115, '永济桥（万全桥）', '永济桥是一座9孔石拱桥。全桥用花岗岩石板砌筑，桥塊和桥面上铺砌花岗岩石板，桥面呈穹隆形。两侧有节间式用石板砌筑的栏杆，桥面宽10.00米，桥梁全长101.00米。侧墙用石板砌筑，上顶有单层仰天石。桥台燕翅形，前墙长8.20米，桥墩上游端(东侧)是尖形(分水尖)，高出桥墩许多，下游端是方形。拱碹是半圆形纵联分段并列式结构，无拱眉。跨径由北往南依次是6.00米、7.80米、9.80米、11.00米、12.00米、11.00米、9.90米、7.90米、6.08米。', '', 16, NULL, NULL, '', 7, 1, 8, 1, '河南省信阳光山县波陂河镇，跨波陂河上', '花岗岩石板', 50, 56, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1116, '郑州惠济桥', '惠济桥是一座3孔石拱桥。桥塊和桥面上铺砌条形石板，全桥为平面，两侧有节间式石栏杆，桥面宽5.00米，桥长41.00米。桥两端各建一座桥关楼。侧墙是用料石砌筑，上顶有单层仰天石。桥台是凹字形。桥墩两端是尖形。拱碹是半圆形纵联式结构，无拱眉。', '', 16, NULL, NULL, '', 10, 1, 10, 1, '郑州市惠济区惠济桥村，跨古代隋唐大运河故道上', '条形石板、料石', 50, 57, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1117, '沈丘泉河桥', '今存桥是一座9孔砖石混合结构拱桥。南北走向，因为河道中间有一个顺河长形小岛，将桥梁分隔成两段，南段为4孔，北段为5孔，在中间的小岛上有一个大桥墩。桥面大致为平面，两侧有节间式石栏杆，石件多有损坏，下面有矩形断面的地伏石。桥面宽4.80米，桥长95.00米。翼墙和侧墙的上部是用砖材砌筑，下部是用石板砌筑，上顶有单层仰天石组成的金边线。桥台为凹字形，前墙长9.00米，端墙很长。桥墩采用石圆柱式，北四孔柱直径是1.46米，南五孔柱径是1.50米。拱碹均系半圆形纵联式结构，碹脸外边有拱眉石，碹脸、拱眉与侧墙平。南四孔跨径均为4.20米，北五孔跨径均为4.40米。', '', 16, NULL, NULL, '', 8, 1, 8, 1, '周口市沈丘县', '砖材（主拱圈、翼墙和侧墙上部）、石材（拱圈两端石碹脸、石栏杆、地伏石、翼墙和侧墙下部石板、仰天石、石圆柱式桥墩）', 50, 58, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1118, '弘济桥', '桥面铺砌青石板，呈正圆弧形。两侧设有节间式石栏杆，每侧有18根望柱，柱头刻有狮子、猴、桃、石榴，配有17块栏板，板面刻有鹿、麒麟、武松打虎等图案。桥栏杆置于单层仰天石上，无地伏。桥面全宽7.90米，净宽6.50米，桥面长44.60米，全长55.00米。翼墙和侧墙用条形石板砌筑，顶端有单层仰天石组成的金边线。桥台呈凹字形，前墙长6.50米。拱碹为圆弧形并列式结构，由18道拱碹石构成，碹脸对接缝处有银锭铁。龙门及小孔龙门上均有石雕龙头，碹脸外侧有凸出的拱眉石。主跨径24.80米。拱碹上方两端各有两个小跨径孔，为半圆形纵联式结构，内侧小孔跨径1.75米，外侧小孔跨径2.73米。侧墙刻有二龙戏珠、飞凤、飞虎。', '', 16, NULL, NULL, '', 8, 1, 8, 1, '河南省驻马店市汝南县城北汝河上', '青石板、条形石板', 50, 59, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1119, '济民桥', '济民桥是一座5孔石拱桥。桥堍和桥面铺砌条形青石板，全桥为平面，两侧有节间式石栏杆，每侧望柱26根，栏板25块，有青石地伏。桥面宽8.50米，净宽7.30米，桥面长49.20米，全长57.00米。翼墙和侧墙是用条形石板砌筑，上面有单层仰天石组成的金边线。桥台两侧有燕翅墙，前墙长9.70米。桥墩两端是尖形，上游端伸出桥身外7.00米，尖端自下而上逐层缩退15—30厘米，上顶有一石雕镇水兽，兽长1.40米，高70厘米。拱碹是半圆形纵联式结构，中孔龙门上有石雕龙头，碹脸外边有拱眉石，拱眉凸出于碹脸，拱眉与侧墙平。中孔跨径8.00米，次边孔跨径7.00米，边孔跨径6.00米。', '', 16, NULL, NULL, '', 7, 1, 7, 1, '驻马店市汝南县汝宁镇', '条形青石板、青石', 50, 60, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1120, '汝东桥', '桥塊和桥面上铺砌青石板，桥面呈正圆弧形竖曲线，两侧有节间式石栏杆，下面有青石地伏。桥面宽7.30米，桥长57.00米。翼墙和侧墙是用青石板砌筑，上面有单层仰天石组成的金边线。桥台两侧有燕翅墙，前墙长8.50米。桥墩上游端是尖形，下游端是方形。拱碹是半圆形纵联式结构，无拱眉，碹脸与侧墙取平。跨径由北向南依次是5.50米、6.70米、7.80米、6.75米、5.60米。', '', 16, NULL, NULL, '', 8, 1, 8, 1, '河南省驻马店市汝南县', '青石板', 50, 61, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1121, '吴桂桥', '吴桂桥是一座5孔石板梁桥。桥面均以条形石板为梁，无栏杆，桥面宽4.50米，桥长17.00米。桥台带燕翅形，桥墩上游端是尖形，下游端是方形。跨径均为3.00米。', '', 16, NULL, NULL, '', 8, 2, 8, 1, '驻马店市确山县', '条形石板', 50, 62, '2026-04-28 23:07:54', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1122, '叶县龙泉桥', '龙泉桥是一座35孔石板梁桥。桥塊上铺砌青石板，桥面每孔5块花岗岩石板梁，共有175块石板梁。桥上无栏杆，桥面宽3.20米，桥面长60.00米，桥梁全长70.00米。下部结构全是用青石板砌筑，桥台是凹字形，桥墩两端是方形，端部高起，拦挡石板梁，上游端上面有石雕龙头。跨径均为1.30米。', '', 16, NULL, NULL, '', 8, 2, 8, 1, '平顶山市叶县龙泉乡龙泉村，跨澧河上', '青石板、花岗岩', 50, 63, '2026-04-28 23:07:54', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1123, '杭州断桥', '桥面是穹隆形，桥上无栏杆，桥面宽9.10米，桥长8.80米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长9.70米。拱碹是半圆形分段并列式结构，碹脸、拱眉与侧墙平。跨径6.10米。', '', 11, NULL, NULL, '', 8, 1, 10, 1, '杭州市西湖苏堤的北端，跨西湖上', '料石', 50, 51, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1124, '杭州拱宸桥', '拱宸桥是一座3孔薄拱薄墩轻型石拱桥。桥面中部(中孔上)高起为平面，两端是阶梯式坡道。两侧有节间式石栏杆，每侧有望柱10根，栏板9块，抱鼓石2块。地伏和仰天石均系矩形断面。桥面宽5.90米，桥塊端宽12.20米，桥梁全长92.10米。侧墙用料石砌筑，上顶有双层仰天石。桥台是凹字形，前面和两侧皆有小出台，前墙长6.50米。桥墩两端为方形，四周(拱脚周围)有出台，桥墩厚1.25米，桥墩长6.50米。拱碹均系半圆形纵联分段并列式结构，拱碹厚30厘米，碹脸外边镶有拱眉石，拱眉凸出于碹脸，也凸出于侧墙。中孔跨径15.80米，边孔跨径11.90米。', '', 11, NULL, NULL, '', 8, 1, 8, 1, '浙江省杭州市大运河上', '石材（料石）', 50, 52, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1125, '忠义桥', '忠义桥是一座单孔石拱桥。桥面是圆弧形，两侧有节间式石栏杆，桥面宽3.65米，桥长15.20米。桥台的前墙与石板砌筑的河岸为一体。拱碹是半圆形分段并列式结构，无拱眉。跨径8.00米。清《西溪 ·梵隐志》记载：\"忠义桥，溪市三桥，惟此最巨，居中虹起，石色光莹，宋孙侯所建也。兄弟恺笃，故名忠义。\"', '', 11, NULL, NULL, '', 10, 1, 10, 1, '浙江省杭州市留下镇大街，跨西溪上', '石材', 50, 53, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1126, '恩波桥', '桥塊和桥面满铺石板，中间略显隆起，两侧有节间式石栏杆，每侧有望柱24根，栏板23块，抱鼓石两块。望柱的柱头有垂莲、莲蓬、狮子等。栏板为实体板，也有雕刻，风化严重。无地伏，桥栏杆置于仰天石上。桥面宽6.00米，桥长57.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，后部有燕翅墙，前墙长7.20米。桥墩两端为尖形，桥墩厚3.20米，桥墩长9.70米。拱碹是半圆形纵联式结构，碹脸外边有拱眉，拱眉凸出于碹脸，拱眉与侧墙齐平。中孔跨径18.4米，边孔跨径15.3米。桥墩上各有一个小孔洞，其立面呈馒头形，跨径1.00米。', '', 11, NULL, NULL, '', 8, 1, 8, 1, '浙江省杭州市富阳区苋浦河上（临近富春江）', '石材（石板、料石）', 50, 54, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1127, '桂芳桥', '桥上无栏杆，桥面宽3.80米，桥长21.40米。桥台前墙与河岸连砌为一体。拱碹是半圆形纵联分段并列式结构，拱眉凸出于碹脸，又凸出于侧墙。跨径8.20米。', '', 11, NULL, NULL, '', 10, 1, 10, 1, '杭州市跨街河上', '石材', 50, 55, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1128, '日新桥', '桥面为正圆弧形，两侧有节间式石栏杆，每侧有望柱8根，栏板7块，抱鼓石2块，地伏与金边合一。桥面宽6.20米，桥长42.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台两侧有燕翅墙。桥墩两端为尖形，拱碹是并列式结构，无拱眉，碹脸与侧墙取平。中孔跨径13.20米，边孔跨径11.00米。', '', 11, NULL, NULL, '', 8, 1, 8, 1, '浙江省杭州市临安区三口镇葱坑村，在富阳区和临安区交界处', '料石', 50, 56, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1129, '白燕桥', '白燕桥是一座7孔石拱桥。桥塊和桥面上铺砌条形石板，两侧有节间式石栏杆，桥面宽7.20米，桥长74.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形。桥墩两端是方形，桥墩厚95厘米，桥墩长7.70米。拱碹是半圆形纵联分段并列式结构，碹脸外边有拱眉，拱眉凸出于碹脸，又凸出于侧墙。中孔跨径9.50米，第三、第五孔跨径8.50米，第二、第六孔跨径8.20米，第一、第七孔跨径7.50米。', '', 11, NULL, NULL, '', 10, 1, 10, 1, '杭州市萧山区', '条形石板、料石', 50, 57, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1130, '广济桥', '广济桥是一座7孔薄拱薄墩轻型石拱桥。桥面中部(中孔上)高起为平面，两端是阶梯式坡道。两侧有节间式石栏杆，无地伏，桥栏杆置于仰天石上。桥面宽6.12米，桥长78.70米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长约5.80米。桥墩两端是方形，桥墩厚1.25米，桥墩长约5.80米。拱碹均系半圆形纵联分段并列式结构，碹脸外边有拱眉，拱眉凸出于碹脸，又凸出于侧墙。中孔跨径15.60米，向两端对应的各孔跨径依次是11.80米、8.00米、5.40米。', '', 11, NULL, NULL, '', 6, 2, 8, 1, '宁波市奉化区，跨鄞江上', '石材（条形石板、方形石柱、方形石横梁）', 50, 58, '2026-04-28 23:07:54', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1131, '上江桥', '桥面中部(拱顶上)高起为平面，两端是阶梯式坡道。桥栏杆无存。桥面宽4.50米，桥长21.00米。侧墙用块石砌筑，上顶有单层仰天石。桥台的前墙与石板砌筑的河岸为一体。拱碹是半圆形纵联式结构，无拱眉，碹脸与侧墙平。跨径15.00米。', '', 11, NULL, NULL, '', 10, 1, 10, 1, '杭州市桐庐县横村跨街河上', '石材（块石、石板）', 50, 59, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1132, '长兴小乌桥', '小乌桥是一座单孔石拱桥。桥面中部(拱顶上)高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆。桥面宽3.50米，桥长33.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，也用料石砌筑。拱碹是半圆形纵联分段并列式结构，拱眉凸出于碹脸，又凸出于侧墙。跨径12.00米。', '', 11, NULL, NULL, '', 9, 1, 10, 1, '湖州市长兴县夹浦镇夹浦村，跨夹浦港上，在大乌桥下游约百米处', '料石', 50, 60, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1133, '兴隆桥（大乌桥）', '兴隆桥是一座3孔石拱桥，桥面中部(中孔拱顶上)高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆。桥面宽3.55米，桥长40.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形。桥墩两端是方形，桥墩厚1.05米，桥墩长4.00米。拱碹是半圆形纵联分段并列式结构，拱眉凸出于碹脸，又凸出于侧墙。中孔跨径12.00米，边孔跨径7.80米(总跨径27.60米)。', '', 11, NULL, NULL, '', 8, 1, 10, 1, '湖州市长兴县夹浦镇夹浦村，跨夹浦港上', '石材（料石）', 50, 61, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1134, '潮音桥', '现存桥是一座3孔薄拱薄墩轻型石拱桥。桥面为穹隆形，两侧有宇墙式石栏杆，地伏与金边合一。桥面宽5.00米，桥长54.20米。侧墙用料石砌筑，上顶有双层仰天石。桥台前墙与石板砌筑的河岸为一体。桥墩两端是方形，桥墩厚1.25米，桥墩长5.60米。拱碹是半圆形纵联分段并列式结构，中孔由8道纵联石和9段拱碹石构成，边孔由6道纵联石和7段拱碹石构成，碹脸外边有拱眉石，拱眉凸出于碹脸，拱眉与侧墙取平。三孔跨径之和是29.00米。中孔拱碹上方两边的侧墙上各有一个勾头石，两个桥墩上(拱碹之间)的侧墙上各有一根桥联柱，上顶有勾头石。', '', 11, NULL, NULL, '', 7, 1, 8, 1, '湖州市', '石材（料石、石板）', 50, 62, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1135, '潘公桥', '桥面中部(中孔上)高起为平面，两端是阶梯式坡道。两侧有板式石栏杆，无地伏，桥栏杆置于仰天石上。桥面宽6.60米，桥长57.50米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前面和两侧皆有小出台，前墙长约7.00米，端墙很长。桥墩两端是方形，拱脚四周有出台，桥墩厚70厘米，桥墩长约7.00米。拱碹是半圆形纵联分段并列式结构，中孔由8道纵联石和9段拱碹石构成，边孔由6道纵联石和7段拱碹石构成，碹脸外边有拱眉石，拱眉凸出于碹脸，拱眉与侧墙取平。中孔跨径15.50米，矢高约8.00米，边孔跨径9.30米，矢高约5.00米。各孔拱碹上方两边的侧墙上各有一个勾头石，中孔与边孔之间(桥墩上)和边孔外侧的侧墙上各有一根桥联柱，上端有勾头石。', '', 11, NULL, NULL, '', 8, 1, 7, 1, '湖州北门，跨苕雪两溪汇流处', '石材、料石', 50, 63, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1136, '湖州安澜桥', '安澜桥是一座3孔薄拱薄墩轻型石拱桥。桥面中部(中孔拱顶上)高起为平面，两端是阶梯式坡道，上下踏步各33级。两侧有节间式石栏杆，每侧有4根望柱，3段石栏板，两端是抱鼓石。无地伏，桥栏杆置于仰天石上。桥面宽4.55米，桥长99.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台为凹字形，端墙很长，前面和两侧皆有小出台，前墙长5.20米。桥墩两端是方形，桥墩厚1.05米，桥墩长4.90米。拱碹是半圆形纵联分段并列式结构，碹脸外边镶有拱眉石，拱眉凸出于碹脸，拱眉与侧墙取平。中孔跨径20.00米，边孔跨径16.60米。三孔拱碹上方两边的侧墙上各有一个勾头石，三孔之间(桥墩上)的侧墙上各有一根桥联柱，上端有勾头石，边孔外边的侧墙上各有两根桥联柱，上端有勾头石。', '', 11, NULL, NULL, '', 8, 1, 8, 1, '湖州市菱湖镇', '石材（料石）', 50, 64, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1137, '广惠桥', '桥面中部高起为平面，两端是阶梯式坡道。两侧有节间式石栏杆，每侧有望柱4根，栏板3块，抱鼓石2块。无地伏，桥栏杆置于双层仰天石上。桥面宽3.30米，桥长18.00米。侧墙用条形石板砌筑，上顶有双层仰天石组成的金边线。桥台是凹字形，前面和两侧皆有出台，前墙长3.90米，端墙的外端与条石砌筑的河岸相连。拱碹是半圆形纵联分段并列式结构，由8道纵联石和9段拱碹石构成，碹脸外边有双线拱眉石，拱眉凸出于碹脸，又凸出于侧墙。跨径10.00米。拱碹上方两边的侧墙上各有一个勾头石。桥孔两边的侧墙上各有一根桥联柱，上顶有勾头石。', '', 11, NULL, NULL, '', 8, 1, 10, 1, '湖州市南浔镇跨街河上', '石材', 50, 65, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1138, '通津桥', '通津桥原名“浔溪桥”。桥面中部(拱顶上)为平面，两端是阶梯式坡道，上下各有踏步33级。两侧有节间式石栏杆，每侧有望柱4根，栏板3块，地伏与金边合一。桥栏杆的两端与河岸上建筑物相连。桥面宽4.00米，桥长28.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台前墙与石板砌筑的河岸为一体。拱碹是半圆形纵联分段并列式结构，由6道纵联石和7段拱碹石构成，碹脸外有双线拱眉石，拱眉凸出于碹脸，拱眉与侧墙取平。跨径15.20米，矢高7.60米。', '', 11, NULL, NULL, '', 8, 1, 10, 1, '湖州市南浔镇街河上', '石材（料石、石板）', 50, 66, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1139, '湖州双林虹桥', '双林虹桥是望月桥（大虹桥）和虹桥（小虹桥）的统称。虹桥为单孔石拱桥，桥面中部高起为平面，两端各有13级踏步，两侧有节间式石栏杆（每侧6根望柱、5段石栏板、2块抱鼓石），桥面宽3.44米，桥长6.84米，侧墙砖砌，桥台凹字形，拱碹为半圆形纵联分段并列式结构，跨径9.00米。望月桥亦为单孔石拱桥，桥面宽2.35米，桥长15.63米，侧墙用料石砌筑，桥台凹字形，拱碹为半圆形纵联分段并列式结构，跨径8.50米。两桥全长22.37米。', '', 11, NULL, NULL, '', 8, 1, 8, 1, '浙江省湖州市双林镇', '石材、砖材', 50, 67, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1140, '化成桥', '化成桥是一座3孔薄拱薄墩轻型石拱桥。桥面中部为平面，两侧有节间式石栏杆，地伏与金边合一。桥面宽3.40米，桥长46.00米。侧墙用砖材砌筑，上顶有双层仰天石。桥台是凹字形，前面和两侧皆有小出台，前墙长4.00米。桥墩两端是方形，桥墩厚1.25米，桥墩长4.00米。拱碹是半圆形纵联分段并列式结构，碹脸外边有双线拱眉石，拱眉凸出于碹脸，拱眉与侧墙取平。中孔跨径13.00米，边孔跨径7.25米。', '', 11, NULL, NULL, '', 8, 1, 8, 1, '湖州双林镇', '石材、砖材', 50, 68, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1141, '万魁桥', '桥面中部高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆，地伏与金边合一。桥面宽3.20米，桥面长46.00米，桥梁全长51.00米。侧墙用砖材砌筑，上顶有双层仰天石。桥台是凹字形，前面和两侧皆有小出台，前墙长3.80米。桥墩两端是方形，桥墩厚1.25米，桥墩长3.80米。拱碹是半圆形纵联分段并列式结构，碹脸外边有拱眉石，拱眉凸出于碹脸，拱眉与侧墙取平。中孔跨径12.45米，边孔跨径7.25米。', '', 11, NULL, NULL, '', 8, 1, 8, 1, '湖州市双林镇街河上，禹王庙以北（化成桥往西122米）', '石材、砖材', 50, 69, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1142, '万元桥', '万元桥是一座3孔薄拱薄墩轻型石拱桥，实际上是三座单跨石拱桥，中间有石堤相连，桥面中部为平面，两端是阶梯式坡道，两端有阶式梯坡道与石堤连接。两侧有石栏杆，地伏与金边合一，桥面宽3.50米，桥梁全长(包括石堤)51.00米。侧墙用砖材砌筑，上顶有双层仰天石。桥台是凹字形，前面和两侧皆有小出台，前墙长4.10米。桥墩两端是方形，桥墩厚1.25米，桥墩长4.10米。拱碹是半圆形纵联分段并列式结构，碹脸外有拱眉石，拱眉凸出侧墙。中孔跨径13.60米，边孔跨径7.70米。', '', 11, NULL, NULL, '', 8, 1, 8, 1, '湖州双林镇', '石材、砖材', 50, 70, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1143, '寿昌桥', '桥面中部高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆，无地伏，桥栏杆置于仰天石上。桥面宽3.24米，桥长52.30米。侧墙用块石砌筑，上顶有单层仰天石组成的金边线。桥台是凹字形，下部前面和两侧有小出台，前墙长约3.50米。拱碹是卵形纵联分段并列式结构，无拱眉，碹脸与侧墙平。跨径17.40米。', '', 11, NULL, NULL, '', 10, 1, 10, 1, '湖州市德清县三合乡二都村', '石材（块石）', 50, 71, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1144, '长虹桥', '桥面中部(中孔上)高起为平面，两端是阶梯式坡道，各有踏步57级。两侧有节间式石栏杆，无地伏，桥栏杆置于仰天石上。桥面宽4.90米，桥梁全长72.80米。侧墙用料石砌筑，上顶有双层仰天石。桥台为凹字形，前面和两侧有出台，前墙长5.50米，端墙很长。桥墩两端是方形，拱脚四周有出台，桥墩厚1.25米，桥墩长5.50米。拱碹均为半圆形纵联分段并列式结构，碹脸外边镶有双线拱眉石，拱眉凸出于碹脸，又凸出于侧墙。中孔跨径16.20米，边孔跨径9.80米。东边孔内桥台两边和前面有纤道。各孔碹脸的上方两边侧墙上各有一个石勾头，各孔之间(桥墩上)的侧墙上各有一桥联柱，柱顶有石勾头。在边孔外边(桥台上)的侧墙上各有两个桥联柱，柱顶有石勾头。中孔两侧联柱上的对联，北面的上联是“淑气风光架岭送登彼岸”，下联是“洞天云汉横梁稳步长堤”；南面的上联是“福泽长流物阜民安国泰”，下联是“慈航普渡江平海晏河清”。边孔外侧联柱上的对联，北面的上联是“劝人为善”，下联是“愿天作福”，南面的上联是“千秋永庆”，下联是“万古长龄”。', '', 11, NULL, NULL, '', 8, 1, 7, 1, '嘉兴市王江泾，跨古运河上', '料石', 50, 72, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1145, '秀城桥', '秀城桥是一座单孔石拱桥。桥面中部(拱顶上)高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆，每侧有望柱7根，栏板刻有花草纹饰，并有铭文“重建秀城桥”阳刻楷书。南北桥堍上各有36级台阶。桥面宽3.80米，桥身长35.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长约4.20米。拱碹是半圆形纵联式结构，碹脸外边有拱眉，拱眉凸出于碹脸，又凸出于侧墙。跨径12.10米。桥身有楹联，北侧为“帝道遐昌 兴水利而济涉”、“皇口巩固乐民便以成梁”，南侧下联为“凭眺一濠，是号秀城之胜概”。', '', 11, NULL, NULL, '', 10, 1, 10, 1, '嘉兴市区跨街河上', '石材（料石）', 50, 73, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1146, '秋泾桥', '桥面中部(拱顶上)高起为平面，两端是阶梯式坡道。两侧有节间式石栏杆，无地伏，桥栏杆置于仰天石上。桥面宽4.80米，桥长60.00米。侧墙用条形石板砌筑，上顶有双层仰天石。桥台是凹字形，前墙长5.40米。拱碹是半圆形纵联分段并列式结构，碹脸外镶有拱眉石，拱眉凸出于侧墙。跨径20.00米。', '', 11, NULL, NULL, '', 8, 1, 10, 1, '嘉兴市南湖区秋泾河上', '石材（条形石板）', 50, 74, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1147, '环秀桥', '环秀桥是一座单孔石拱桥。桥面中部(拱顶上)高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆，桥面宽3.65米，桥长23.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形。拱碹是半圆形纵联分段并列式结构，有拱眉，拱眉凸出于碹脸，又凸出于侧墙，跨径8.50米。', '', 11, NULL, NULL, '', 7, 1, 7, 1, '嘉兴市嘉善县西塘镇，跨小桐圩和北翠圩汇合处', '料石', 50, 75, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1148, '当湖桥', '现存当湖桥是一座3孔薄拱薄墩石拱桥。桥面中部(中孔拱顶上)高起为平面，两端是阶梯式坡道，两侧有板式石栏杆，无地伏，桥栏杆置于仰天石上。桥面宽3.35米，桥长26.30米。侧墙用料石砌筑，上顶有双层仰天石。桥台是凹字形，前墙长约4.00米，端墙的外端与石砌河岸相连。桥墩两端是方形，桥墩厚1.05米，桥墩长4.00米。拱碹是半圆形纵联分段并列式结构，中孔的拱碹由10道纵联石和11段拱碹石构成，边孔的拱碹由6道纵联石和7段拱碹石构成，碹脸外边有拱眉石，拱眉凸出于碹脸，又凸出于侧墙。中孔跨径8.60米，边孔跨径4.70米。中孔碹脸上方两边的侧墙上各有一个勾头石，三孔之间(桥墩上)的侧墙上各有一根桥联柱，边孔外边(桥台上)的侧墙上各有一根桥联柱，上端皆有勾头石，柱面上皆有对联。东面的上联是“影接梯云万里程开腾骥足”，下联是“湖来柘水一声胪唱冠鳌峰”；西面的上联是“雄踞西关一水潆洄钟淑美”，下联是“恩迎北阙群英次第践清华”。', '', 11, NULL, NULL, '', 8, 1, 10, 1, '浙江省平湖市当湖街道西小街安吉弄北口，跨街河上', '石材（料石、仰天石、纵联石、拱碹石）', 50, 76, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1149, '仁济桥', '仁济桥是一座单孔石拱桥。桥面中部(拱顶上)高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆，每侧有望柱4根，栏板3块，抱鼓石2块。无地伏，桥栏杆置于单层仰天石上。桥面宽3.75米，桥长28.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前面和两侧有出台，端墙外有石板砌筑的河道护岸。拱碹是半圆形纵联分段并列式结构，由6道纵联石和7段拱碹石构成，碹脸外边有拱眉石，拱眉凸出于碹脸，又凸出于侧墙。跨径16.00米。碹脸上方两边的侧墙上各有一个勾头石。桥孔两边的侧墙上各有一根桥联柱，上端有勾头石。', '', 11, NULL, NULL, '', 7, 1, 10, 1, '浙江省桐乡市乌镇，跨于街河上', '石材（料石、石板）', 50, 77, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1150, '金华通济桥', '通济桥于元代元统二年(1334年)建成，为11孔石墩台木梁桥。桥上建屋五十间，两端各有一座亭，其间共有16座亭。清嘉庆十四年(1809年)重建，改建成13孔石拱桥。今存通济桥桥块和桥面上铺砌不规则石板，桥面大致为平面，两侧有节间式石栏杆，下面有青石地伏石。桥面宽7.00米，桥面长206.16米，桥梁全长254.50米。侧墙用料石砌筑，上顶有单层仰天石组成的金边线。桥台是凹字形，下部前面和两边有小出台，前墙长7.00米。桥墩两端与拱脚取齐，下部四周有小出台，桥墩厚4.50米，桥墩长7.00米。拱碹为半圆形纵联式结构，拱碹厚48厘米，碹脸外边有拱眉石，拱眉凸出于碹脸，拱眉与侧墙平。跨径由北往南依次是10.70米、11.50米、11.90米、11.80米、11.90米、12.00米、11.95米、11.68米、11.88米、11.88米、12.06米、12.06米、10.85米。', '', 11, NULL, NULL, '', 8, 1, 6, 1, '金华市跨婺江上', '不规则石板、青石、料石、仰天石', 50, 78, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1151, '通州桥', '通州桥是一座5孔等跨径石拱桥。桥面为平面，两侧有砖砌护栏，下面有矩形断面的地伏石，桥面宽4.00米，桥长84.80米。桥上建有19间砖木结构长廊，两端有门楼。侧墙用规整的石料砌筑，上顶有单层矩形断面仰天石，仰天石与侧墙平。桥台是凹字形，前墙长4.00米。桥墩的两端是尖形，两端上面有较高的锥体。拱碹为半圆形纵联式结构，无拱眉，碹脸与侧墙取平。跨径均为9.00米。', '', 11, NULL, NULL, '', 8, 1, 10, 1, '兰溪市，跨于兰江的支流梅溪上', '石料、砖、木', 50, 79, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1152, '合济桥', '合济桥是一座5孔等跨径石拱桥。桥塊和桥面上用块石铺砌，两侧有石栏杆。桥面宽6.20米，桥长96.50米。侧墙用块石砌筑，上顶有单层仰天石。桥台是燕翅形。桥墩上游端是尖形，下游端是方形，跨径16.00米。', '', 11, NULL, NULL, '', 10, 1, 10, 1, '金华市浦江县白马镇', '块石', 50, 80, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1153, '双虹桥', '现有双虹桥是一座9孔石拱桥。桥上有节间式石栏杆，柱头有石狮子，栏板为实体板。无地伏，桥栏杆置于仰天石上。桥长107.60米。侧墙用条形石板砌筑，上顶有双层仰天石组成的金边线。桥台两侧有燕翅墙，桥墩两端为尖形，桥墩宽1.60米，桥墩长8.10米。拱碹是二心圆弧形(尖形)纵联式结构，拱眉凸出于碹脸，拱眉与侧墙平。跨径均为11.00米。', '', 11, NULL, NULL, '', 8, 1, 10, 1, '嵊州市郊区乡间，跨山涧溪流上', '块石、乱石、片石', 50, 81, '2026-04-28 23:07:54', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1154, '水口桥', '水口桥是一座单孔石拱桥。桥面中部(拱顶上)高起为平面，上面建有一座木结构亭子。两端是阶梯式坡道，坡道上有砖石栏杆，上面有青石帽(扶手)，无地伏，桥栏杆砌在仰天石上。桥面宽4.70米，桥长37.80米。桥上建砖木结构亭子。侧墙用条石砌筑，上顶有双层仰天石。桥台前墙与石砌河岸为一体。拱碹是圆弧形分段并列式结构，碹脸外有拱眉石，拱眉与侧墙取平。跨径20.50米。', '', 11, NULL, NULL, '', 10, 1, 10, 1, '金华市武义县郭洞村，跨乡间排水沟上', '条石、青石、砖、木', 50, 82, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1155, '性田桥', '性田桥是一座5孔砖石混合结构拱桥。桥面大致为平面，无栏杆，桥面宽6.00米，桥长20余米。侧墙用砖材砌筑，上顶有一层较厚的仰天石，高出桥面成边牙石。桥台是凹字形，前墙长6.00米。桥墩两端与拱脚齐平，桥墩长6.00米。拱碹是半圆形纵联式结构，碹脸外边有拱眉石，拱眉凸出于碹脸，拱眉与侧墙平。跨径3.00米。', '', 11, NULL, NULL, '', 10, 1, 10, 1, '永康市', '砖、石', 50, 83, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1156, '景宁永济桥', '永济桥又名“庆安桥”。桥面中部(拱顶上)为平面，两端是阶梯式坡道，两侧有节间式石栏杆。桥面宽6.00米，桥长40.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形。拱碹是半圆形纵联分段并列式结构，拱眉凸出于碹脸，又凸出于侧墙。跨径19.00米。', '', 11, NULL, NULL, '', 8, 1, 10, 1, '丽水市景宁畲族自治县东坑镇章坑村，跨北溪上', '石材（料石）', 50, 84, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1157, '古溪桥', '古溪桥是一座单孔石拱桥。桥塊和桥面上铺砌青石板，全桥为平面。桥面宽5.60米，桥长29.30米。桥上建砖木结构廊。侧墙用块石砌筑，上顶有单层仰天石。桥台是凹字形，也用块石砌筑。拱碹是半圆形分段并列式结构，无拱眉。跨径10.50米。', '', 11, NULL, NULL, '', 8, 1, 10, 1, '龙泉市小梅镇黄南村，跨古溪上', '青石板（桥塊和桥面）、砖木（廊）、块石（侧墙、桥台）', 50, 85, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1158, '庆元坝头桥', '坝头桥是一座单孔石拱桥。桥塊和桥面上铺砌石板，全桥为平面。桥面宽4.30米，桥长29.40米。桥上建砖木结构廊。侧墙用块石砌筑，上顶有单层仰天石。桥台是凹字形。拱碹是半圆形纵联式结构，无拱眉。跨径12.00米。', '', 11, NULL, NULL, '', 8, 1, 10, 1, '丽水市庆元县江根乡坝头村', '石板、砖、木、块石', 50, 86, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1159, '庆元半山桥', '全桥是平面，铺砌条形石板，桥面宽 4.20米，桥长12.87米。桥上建砖木结构廊。侧墙用块石砌筑，上顶有单层仰天石。桥台是凹字形，用块石砌筑。拱碹是半圆形纵联式结构，无拱眉，跨径6.90米。', '', 11, NULL, NULL, '', 8, 1, 10, 1, '丽水市庆元县龙溪乡大茅坪村', '条形石板、块石、砖木', 50, 87, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1160, '步蟾桥', '步蟾桥是一座单孔石拱桥。桥塊和桥面上铺砌石板，全桥为平面。桥面宽5.20米，桥长51.60米。桥上建砖木结构廊。侧墙用块石砌筑，上顶有单层仰天石。桥台是凹字形。拱碹是半圆形纵联式结构，无拱眉。跨径17.76米。', '', 11, NULL, NULL, '', 7, 1, 7, 1, '丽水市庆元县举水乡月山村', '石板、砖木、块石', 50, 88, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1161, '庆元来凤桥', '来凤桥是一座单孔石拱桥。桥塊和桥面上铺砌石板，全桥为平面，桥面宽5.50米，桥长30.00米。桥上建砖木结构廊。侧墙用块石砌筑，上顶有单层仰天石。桥台是凹字形。拱碹是半圆形纵联式结构，无拱眉。跨径16.70米。', '', 11, NULL, NULL, '', 8, 1, 10, 1, '丽水市庆元县举水乡月山村，跨举溪上', '石板（桥塊和桥面）、砖木（廊）、块石（侧墙）', 50, 89, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1162, '垄桥', '垄桥是一座单孔石拱桥。全桥是平面，铺砌条形石板，桥面宽4.00米，桥长22.00米。桥上建砖木结构廊。侧墙用块石砌筑，上顶有单层仰天石。桥台是凹字形，用块石砌筑。拱碹是半圆形纵联式结构，无拱眉，跨径11.80米。', '', 11, NULL, NULL, '', 8, 1, 8, 1, '丽水市庆元县龙溪乡鱼川村，跨夹浦港上', '条形石板、块石、砖木', 50, 90, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1163, '木桥头桥', '桥塊和桥面上铺砌石板，全桥为平面。桥面宽3.40米，桥长26.0米。桥上建砖木结构廊。侧墙用块石砌筑，上顶有单层仰天石。桥台是凹字形。拱碹是半圆形纵联式结构，无拱眉。跨径7.50米。', '', 11, NULL, NULL, '', 10, 1, 10, 1, '丽水市庆元县左溪镇木桥头村', '石板、块石、砖木', 50, 91, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1164, '青田桥', '桥面宽3.60米，桥长10.70米。桥上建砖木结构廊。侧墙用块石砌筑，上顶有单层仰天石。桥台是凹字形。拱碹是半圆形纵联式结构，无拱眉。跨径6.80米。', '', 11, NULL, NULL, '', 8, 1, 8, 1, '丽水市庆元县江根乡青田村', '石板（桥塊和桥面）、块石（侧墙）、砖木（廊）', 50, 92, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1165, '宁波永济桥', '永济桥又名“长山桥”。无栏杆，桥面宽4.00米，桥塊外端宽8.00米，桥长50.00米。侧墙用块石砌筑，上顶有单层仰天石。桥台建在山脚下用块石砌筑的河岸上。桥墩两端是尖形。中孔跨径10.00米，边孔跨径7.20米。', '', 11, NULL, NULL, '', 8, 1, 8, 1, '宁波市北仑区长山桥村', '块石', 50, 93, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1166, '灞桥', '桥面中部(拱顶上)高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆，桥面宽4.40米，桥长30.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，端墙很长，前墙长4.70米。拱碹是半圆形纵联分段并列式结构，有拱眉，拱眉凸出于碹脸，又凸出于侧墙。跨径12.50米。', '', 11, NULL, NULL, '', 8, 1, 8, 1, '宁波市奉化区，跨东江支流上', '料石', 50, 94, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1167, '福星桥', '福星桥是一座5孔石拱桥。桥塊和桥面上铺砌条形石板，全桥为平面，两侧有节间式石栏杆，每侧有望柱26根，栏板25块，抱鼓石2块。望柱的柱头上有石狮子。无地伏，望柱安装在仰天石上，栏板的两端下面各有一块方形石块。桥面宽6.35米，桥长96.50米。侧墙用料石砌筑，上顶有单层仰天石。桥台前墙与石砌河岸为一体。桥墩两端是尖形，拱碹是半圆形纵联式结构，无拱眉，碹脸与侧墙平。中孔跨径14.90米，其余4孔跨径均为12.60米。', '', 11, NULL, NULL, '', 8, 1, 8, 1, '宁波市奉化区大堰镇常照村，跨奉化江上', '条形石板、料石', 50, 95, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1168, '金井桥', '金井桥是一座单孔石拱桥。桥塊和桥面上铺砌条形石板，呈圆弧形，无栏杆，桥面宽5.00米，桥长15.00米。侧墙用条形石板砌筑，上顶有单层仰天石。桥台是凹字形，前墙长5.30米。拱碹是半圆形纵联式结构，无拱眉。跨径10.00米。', '', 11, NULL, NULL, '', 10, 1, 10, 1, '宁波市奉化区斑竹乡，跨茶坑溪上', '条形石板', 50, 96, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1169, '居敬桥', '居敬桥是一座3孔薄拱薄墩轻型石拱桥。桥面中部高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆，每侧有望柱16根，栏板15块，抱鼓石2块，望柱是方形柱头，栏板是寻杖下镂空式，下面有地伏石。桥面净宽3.60米，桥长29.60米。侧墙用料石砌筑，上顶有单层仰天石。桥台为凹字形，前墙长5.00米。桥墩两端是方形，下部四周有出台，桥墩厚1.20米，桥墩长5.00米。拱碹是纵联分段并列式结构，碹脸外边镶有拱眉石，拱眉凸出于碹脸，拱眉凸出于侧墙。中孔跨径8.30米，边孔跨径5.40米。拱碹之间的侧墙上(桥墩上)各有一根桥联柱，上端有勾头石。边孔外边的侧墙上(桥台上)各有一根桥联柱，上端有勾头石。', '', 11, NULL, NULL, '', 7, 1, 10, 1, '宁波市奉化区西邬镇居敬村', '料石', 50, 97, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1170, '商山桥', '商山桥是一座单孔石拱桥。桥面中部为平面，两端是阶梯式坡道，两侧有节间式石栏杆，无地伏，桥栏杆置于仰天石上。桥面宽2.60米，桥长11.00米。桥台设在用块石砌筑的河岸上，拱碹是半圆形纵联式结构，无拱眉，碹脸与侧墙平。跨径7.00米。', '', 11, NULL, NULL, '', 10, 1, 10, 1, '宁波市奉化区', '石材', 50, 98, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1171, '石泉桥', '石泉桥是一座单孔石拱桥，桥面中部 (拱顶上)高起为平面，两端是阶梯式坡道。两侧有节间式石栏杆，无地伏，桥栏杆置于仰天石上。桥面宽4.50米，桥长19.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台建在山脚岩石上，形状不规则。拱碹是半圆形纵联分段并列式结构，碹脸外边有拱眉，拱眉、碹脸与侧墙平。跨径5.00米。', '', 11, NULL, NULL, '', 8, 1, 8, 1, '宁波市奉化区岩头乡', '石材（料石）', 50, 99, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1172, '望春桥', '桥面中部(拱顶上)高起为平面，两端是阶梯式坡道。两侧有节间式石栏杆，每侧有望柱8根，栏板7块，抱鼓石2块。无地伏，桥栏杆置于仰天石上。桥面宽4.00米，桥塊外端宽5.00米，桥长28.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台的前墙与石砌河岸连砌为一体，前面有出台。拱碹是半圆形纵联式结构，碹脸外边有拱眉石，拱眉凸出于碹脸，又凸出于侧墙。跨径9.00米。', '', 11, NULL, NULL, '', 8, 1, 8, 1, '宁波市海曙区望春街道，跨街河上', '料石', 50, 100, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1173, '惠明桥', '桥面为平面，桥塊上是阶梯式坡道，东西两坡各有10级台阶。两侧有节间式石栏杆，每侧有望柱8根，栏板7块，抱鼓石2块，无地伏，桥栏杆置于仰天石上。桥面宽3.70米，桥长26.00米，侧墙用料石砌筑，上顶有双层仰天石。桥台与石砌河岸为一体。桥墩两端是方形，桥墩厚1.00米，桥墩长4.00米。拱碹是半圆形纵联分段并列式结构，无拱眉，碹脸与侧墙平。跨径8.30米。两孔拱碹之间的侧墙上有桥联柱，有对联，上端有石雕龙头。北面对联是“惠泽周流交注日月双湖”,南面对联是“明山绵亘远通三郡轮蹄”。', '', 11, NULL, NULL, '', 10, 1, 10, 1, '宁波市海曙区洞桥镇洞桥村，跨日月湖上(原南塘河)', '石材（料石）', 50, 101, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1174, '启文桥', '启文桥原名“沈店桥”，是一座单孔石拱桥。桥面中部(拱顶上)高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆，桥面宽4.00米，桥全长21.50米。侧墙用块石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长4.30米，拱碹是半圆形纵联分段并列式结构，有拱眉，拱眉的外边凸出于碹脸，拱眉凸出于侧墙。跨径7.00米。', '', 11, NULL, NULL, '', 8, 1, 10, 1, '宁波市海曙区，跨南塘河上', '块石', 50, 102, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1175, '甬水桥（又名“夏家桥”）', '甬水桥是一座单孔石拱桥。桥面中部(拱顶上)高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆，无地伏，桥栏杆置于仰天石上。桥面宽2.75米，桥堍外端宽5.00米。桥长23.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长3.20米。拱碹是半圆形纵联分段并列式结构，有拱眉，拱眉凸出于碹脸，拱眉与侧墙平。跨径7.80米。', '', 11, NULL, NULL, '', 5, 1, 10, 1, '宁波城南，跨甬河上', '石材（料石）', 50, 103, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1176, '月湖桥', '月湖桥又名“湖心东桥”，是一座单孔石拱桥。桥面中部(拱顶上)高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆，无地伏，桥栏杆置于仰天石上。桥面宽4.35米，桥塊外端宽5.00米。桥长15.70米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长3.60米。拱碹是半圆形纵联分段并列式结构，有拱眉，拱眉凸出于碹脸，拱眉与侧墙平。跨径5.00米。', '', 11, NULL, NULL, '', 8, 1, 8, 1, '宁波市区月湖公园内', '料石', 50, 104, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1177, '张斌桥', '桥面中部(拱顶上)高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆，无地伏，桥栏杆置于仰天石上，桥面宽4.40米，桥长30.00米。侧墙用料石砌筑，上顶无仰天石。桥台是凹字形，端墙很长，前墙长4.70米。拱碹是半圆形纵联分段并列式结构，有拱眉，拱眉凸出于碹脸，又凸出于侧墙。跨径10.00米。', '', 11, NULL, NULL, '', 10, 1, 10, 1, '宁波市江东区', '料石', 50, 105, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1178, '碧环桥', '碧环桥是一座单孔石拱桥。桥面中部(拱顶上)高起为平面，两端是阶梯式坡道。两侧有节间式石栏杆，桥面宽2.40米，桥塊外端宽4.00米。桥长11.00米。桥台是凹字形，前墙长4.50米。拱碹是半圆形纵联分段并列式结构，无拱眉，跨径4.40米。', '', 11, NULL, NULL, '', 7, 1, 7, 1, '宁波市鄞州区五乡镇仁久村', '石材', 50, 106, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1179, '定桥', '桥面中部(中孔上)高起为平面，两端是阶梯式坡道，各有22级踏步。两侧有节间式石栏杆，每侧有8根望柱，7块石栏板，2块抱鼓石。无地伏，桥栏杆置于仰天石上。桥面宽3.05米，桥长23.90米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前面和两侧皆有小出台，前墙长约3.50米。桥墩两端为方形，四周有出台，桥墩厚1.30米，桥墩长约3.50米。拱碹是半圆形纵联分段并列式结构，中孔由8道纵联石和9段拱碹石构成，边孔由6道纵联石和7段拱碹石构成，碹脸外边镶有拱眉石，拱眉凸出于碹脸，又凸出于侧墙。中孔跨径13.00米，边孔跨径11.50米。', '', 11, NULL, NULL, '', 10, 1, 10, 1, '宁波市鄞州区姜山镇，跨无名排水沟上', '料石', 50, 107, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1180, '宁波洞桥', '桥塊和桥面上铺砌条形石板，呈圆弧形，无栏杆，桥面宽3.50米，桥塊是喇叭形，外端宽7.00米，桥梁全长30.00米。侧墙用条形石板砌筑，上顶有单层仰天石。桥台是凹字形，端墙后部有燕翅墙，前墙长7.30米。拱碹是半圆形纵联式结构，无拱眉。跨径17.50米。', '', 11, NULL, NULL, '', 7, 1, 7, 1, '宁波市鄞州区大隐镇，跨大隐溪上', '条形石板', 50, 108, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1181, '高桥', '桥面中部(拱顶上)高起为平面，两端为阶梯式坡道。无栏杆，桥面宽4.65米，桥面长28.50米，全长37.80米。侧墙用条石砌筑，上顶有双层仰天石。桥台前墙与石砌河岸连砌为一体，拱碹是半圆形纵联分段并列式结构，由8道纵联石和9段拱碹石构成，碹脸外有拱眉石，拱眉凸出于碹脸，又凸出于侧墙。跨径10.30米。', '', 11, NULL, NULL, '', 8, 1, 8, 1, '浙江省宁波市鄞州区高桥镇', '石材（条石）', 50, 109, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1182, '光溪桥', '桥面中部高起为平面，两端是阶梯式坡道。桥上两侧有石栏杆，望柱上雕有石狮子，无地伏，栏杆置于仰天石上。桥面宽4.15米，桥长35.95米。侧墙用料石砌筑，上顶有单层仰天石。北桥台前墙与石砌河岸为一体。南桥台是凹字形，前墙长4.60米。拱碹是半圆形纵联分段并列式结构，碹脸外边镶有拱眉石，拱眉凸出于碹脸，又凸出于侧墙。跨径12.00米。拱顶上面有一石匾，刻“光溪桥”。', '', 11, NULL, NULL, '', 8, 1, 8, 1, '宁波市鄞州区鄞江镇光溪村，跨光溪上', '石材（料石）', 50, 110, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1183, '皎溪桥', '皎溪桥是一座3孔石拱桥。桥面中部(中孔拱顶上)高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆。桥面宽3.30米，桥塊外端宽5.00米，桥长30.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长3.70米。桥墩两端是方形，桥墩厚1.05米，桥墩长3.70米。拱碹是半圆形纵联分段并列式结构，有拱眉，拱眉凸出于碹脸，拱眉与侧墙平。中孔跨径6.00米，边孔跨径4.50米。', '', 11, NULL, NULL, '', 8, 1, 10, 1, '宁波市鄞州区五乡镇，跨东塘大河上', '石材（料石）', 50, 111, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1184, '宁波权相墓桥', '万安桥是一座双孔石拱桥。桥面中部为平面，两端桥塊上是阶梯式坡道。桥面宽3.20米，桥长16.00米。桥上建木结构廊。侧墙用料石砌筑，上顶有双层仰天石。桥台是凹字形，前墙长3.50米。桥墩两端是方形(两端与拱脚齐平),桥墩长3.50米。拱碹是半圆形纵联式结构，无拱眉。跨径5.00米。', '', 11, NULL, NULL, '', 8, 1, 8, 1, '宁波权相墓', '石材、木材', 50, 112, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1185, '五港桥', '桥面中部(中孔上)为平面，两端是阶梯式坡道，两侧有节间式石栏杆，无地伏，桥栏杆置于仰天石上，桥面宽3.00米，全长20.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，下部前面和两边皆有30厘米出台，前墙长3.60米。桥墩两端是方形，四周皆有30厘米出台，桥墩厚1.25米，桥墩长3.60米。拱碹是半圆形纵联分段并列式结构，有拱眉，拱眉凸出于碹脸，又凸出于侧墙。中孔跨径6.00米，边孔跨径4.00米。', '', 11, NULL, NULL, '', 8, 1, 10, 1, '宁波市鄞州区西席乡', '石材（料石）', 50, 113, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1186, '斗门桥', '斗门桥是一座单孔石拱桥和一座双孔石板梁桥连接而成。石拱桥的桥面高起为平面，两端是阶梯式坡道。两侧有节间式石栏杆。桥面宽4.00米，桥长15.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长4.60米。拱碹是半圆形分段并列式结构，有拱眉，拱眉凸出于碹脸，又凸出于侧墙。跨径5.00米。石板梁桥的桥面宽也是4.00米，桥长10.00米。桥台是凹字形，前墙长4.60米。桥墩两端是方形，桥墩厚80厘米，桥墩长4.60米。跨径均为3.00米。', '', 11, NULL, NULL, '', 8, 1, 10, 1, '宁波市镇海区五乡镇夹塘村', '料石', 50, 114, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1187, '觐祖桥', '觐祖桥是一座单孔石拱桥。桥面中部(拱顶上)是平面，两端是阶梯式坡道，两侧有节间式石栏杆，无地伏，栏杆置于仰天石上。桥面宽2.80米，桥堍宽3.80米，桥长11.50米。侧墙用料石砌筑，上顶有双层仰天石。桥台是凹字形，前墙长3.10米。拱碹是半圆形纵联分段并列式结构，有拱眉，拱眉的外边凸出于碹脸，又凸出于侧墙。跨径4.50米。', '', 11, NULL, NULL, '', 10, 1, 10, 1, '宁波市镇海区田胡村', '石材（料石）', 50, 115, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1188, '吉利桥', '吉利桥是一座单孔石拱桥。桥面大致为平面，两侧有节间式石栏杆，无地伏，桥栏杆置于仰天石上。桥面净宽3.80米，桥长12.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长4.20米，端墙外端有燕翅墙。拱碹是圆弧形纵联分段并列式结构，有拱眉，拱眉的外边錾凸出的拱眉线，拱眉线凸出于侧墙。跨径4.00米。', '', 11, NULL, NULL, '', 8, 1, 8, 1, '慈溪市掌起镇叶家村', '石材（料石）', 50, 116, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1189, '七星桥', '桥面中部(中孔拱顶上)高起为平面，两端是阶梯式坡道。两侧有节间式石栏杆，无地伏，桥栏杆置于仰天石上。桥面宽3.50米，桥长25.00米。侧墙用料石砌筑，上顶有双层仰天石。桥台是凹字形，前墙长3.80米。桥墩两端是方形，桥墩厚95厘米，桥墩长3.80米。拱碹是半圆形纵联分段并列式结构，有双线拱眉。中孔跨径6.50米，边孔跨径5.20米。桥墩上的侧墙上各有一根桥联柱，上顶有勾头石。桥台上的侧墙上各有一根桥联柱，上顶有勾头石。', '', 11, NULL, NULL, '', 8, 1, 7, 1, '慈溪市横河境，跨横河上', '石材（料石）', 50, 117, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1190, '慈溪运河桥', '运河桥是一座单孔石拱桥。桥面中部(拱顶上)高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆，无地伏，桥栏杆置于仰天石上，桥面宽3.00米，桥全长12.00米。侧墙用料石砌筑，上顶有双层仰天石。桥台是凹字形，前墙长3.30米。拱碹是半圆形纵联分段并列式结构，有拱眉，拱眉的外边凸出于碹脸，拱眉与侧墙平。跨径6.00米。', '', 11, NULL, NULL, '', 10, 1, 10, 1, '慈溪市鸣鹤古镇跨运河上', '料石', 50, 118, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1191, '道士桥', '桥面为圆弧形，两端有较缓的坡道，桥上无栏杆，亦无边牙石。桥面宽5.50米，桥长23.60米。侧墙用乱石砌筑。桥台建在山脚岩石上，形状不规则。拱碹用片石砌筑，大致呈半圆形，属于纵联式结构，无拱眉，碹脸与侧墙平。跨径12.00米。', '', 11, NULL, NULL, '', 5, 1, 5, 1, '宁波市宁海县道士桥村，跨西南溪谷上', '乱石（侧墙）、片石（拱碹）', 50, 119, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1192, '登瀛桥', '登瀛桥是一座单孔石拱桥。桥面中部(拱顶上)是弧形面，两端是阶梯式坡道，两侧有节间式石栏杆。桥面宽3.40米，桥全长13.00米。侧墙用料石砌筑，上顶无仰天石。桥台是凹字形，前墙长3.40米。拱碹是半圆形纵联式结构，无拱眉，碹脸与侧墙平。跨径8.30米。', '', 11, NULL, NULL, '', 8, 1, 8, 1, '宁波市宁海县白峤村', '料石', 50, 120, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1193, '福应桥（又名“陈家桥”）', '桥面中部(拱顶上)高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆，无地伏，桥栏杆置于仰天石上。桥面宽3.10米，桥全长12.00米。侧墙用块石砌筑，上顶有单层仰天石。桥台建在山脚岩石上，不规整。拱碹是半圆形纵联式结构，无拱眉，碹脸与侧墙平。跨径6.00米。', '', 11, NULL, NULL, '', 10, 1, 10, 1, '宁波市宁海县白峤村', '石材（块石）', 50, 121, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1194, '宁海缑北桥', '缑北桥又名“深圳桥”。桥面宽5.50米，桥长80.00米。桥南北两端各有引道35.00米，全长150.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是燕翅形，前墙长5.50米。桥墩上游端是尖形，拱碹是半圆形纵联式结构，无拱眉。中孔跨径13.00米，次边孔跨径12.00米，边孔跨径11.00米。', '', 11, NULL, NULL, '', 8, 1, 8, 1, '宁波市宁海县深圳镇', '料石', 50, 122, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1195, '宁海惠德桥（俗称“四狮桥”）', '惠德桥是一座单孔石拱桥。桥面中部(拱顶上)高起为弧形面，两端是阶梯式弧形面，两侧有节间式石栏杆，无地伏，桥栏杆置于仰天石上。桥面宽4.50米，桥长11.50米。侧墙用料石砌筑。上顶有单层仰天石。桥台前墙与石砌河岸连砌为一体。拱碹是半圆形纵联分段并列式结构，无拱眉，碹脸与侧墙平。跨径6.95米。', '', 11, NULL, NULL, '', 10, 1, 10, 1, '宁波市宁海县长街镇西岙村，跨村内小溪上', '料石', 50, 123, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1196, '甲子桥', '甲子桥是一座3孔石拱桥。桥面上是平面，桥塊上是坡面，两侧有节间式石栏杆，无地伏，桥栏杆置于仰天石上。桥面宽4.30米，桥全长42.50米。侧墙用乱石砌筑，上顶有单层仰天石。桥台建在山脚岩石上，不规整。桥墩两端是方形，桥墩厚1.25米，桥墩长4.60米。拱碹是半圆形纵联式结构，无拱眉，碹脸与侧墙平。中孔跨径13.00米，边孔跨径11.50米。', '', 11, NULL, NULL, '', 8, 1, 10, 1, '宁波市宁海县，跨凫溪上', '石材', 50, 124, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1197, '阆风桥', '阆风桥是一座单孔石拱桥。桥面中部(拱顶上)是平面，两端是阶梯式坡道，两侧有节间式石栏杆。桥面宽4.50米，桥全长16.50米。侧墙用料石砌筑，上顶无仰天石。桥台是凹字形，前墙长4.50米。拱碹是半圆形纵联式结构，无拱眉，碹脸与侧墙平。跨径7.90米。', '', 11, NULL, NULL, '', 8, 1, 8, 1, '宁波市宁海县西店村，跨岩溪上', '石材（料石）', 50, 125, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1198, '书院桥', '书院桥是一座单孔石拱桥。桥面为弧形面，桥面宽3.20米，桥全长10.00米。侧墙用块石砌筑，上顶有单层仰天石。桥台建在山脚岩石上，不规整。拱碹是半圆形纵联式结构，无拱眉，碹脸与侧墙平。跨径5.00米。', '', 11, NULL, NULL, '', 10, 1, 10, 1, '宁波市宁海县桑州镇田洋卢村', '石材', 50, 126, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1199, '万年桥（又名“榧坑桥”）', '万年桥是一座单孔石拱桥。桥面中部(拱顶上)为弧形，两端是较缓的阶梯式坡道。无栏杆，桥面宽4.80米，桥长34.00米。侧墙用块石砌筑，上顶平铺一层石板，墙面自下而上有很大收分，桥体上顶(桥面)厚4.80米，底部(拱脚处)厚7.40米。无桥台，拱碹用片石砌筑，近似半圆形纵联式结构，无拱眉。跨径18.00米。', '', 11, NULL, NULL, '', 7, 1, 7, 1, '宁波市宁海县榧坑村，跨大松溪上', '块石、石板、片石', 50, 127, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1200, '宁海义门桥', '桥面中部(拱顶上)高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆，无地伏，桥栏杆置于仰天石上。桥面宽2.50米，桥全长7.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长2.50米。拱碹是半圆形纵联分段并列式结构，有拱眉，拱眉凸出于碹脸，又凸出于侧墙。跨径4.50米。', '', 11, NULL, NULL, '', 8, 1, 8, 1, '宁波市宁海县西店镇邬氏祠堂内，跨院内池塘上', '石材（料石）', 50, 128, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1201, '永迎桥', '永迎桥是一座单孔石拱桥。桥面为弧形面，无栏杆，桥面宽4.80 米，桥全长21.50米。桥台利用山脚下岩石河岸开凿而成，拱碹用乱石砌筑，属于半圆形纵联式结构，无拱眉，碹脸与侧墙平。跨径11.20米。', '', 11, NULL, NULL, '', 8, 1, 8, 1, '台州市天台县与宁波市宁海县之交界处，跨天台山深谷溪涧上', '乱石、岩石', 50, 129, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1202, '摘星桥', '摘星桥是一座单孔石拱桥。桥面为弧形面，无栏杆，桥面宽3.80 米，桥全长20.00米。桥台利用山脚下岩石河岸开凿而成，拱碹用片石砌筑，属于半圆形纵联式结构，无拱眉，碹脸与侧墙平。跨径9.00米。', '', 11, NULL, NULL, '', 10, 1, 10, 1, '宁波市宁海县摘星岭北坡，跨山涧中溪流上', '片石、岩石', 50, 130, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1203, '欧阳桥', '欧阳桥是一座3孔石拱桥。桥塊和桥面上铺砌块石面层。无栏杆，两边各有一道块石砌的边牙。桥面宽4.50米，桥梁全长5.30米。侧墙用块石砌筑，上顶有块石砌的边牙。桥台是凹字形，前墙长4.80米。桥墩两端是方形，桥墩厚1.25米，桥墩长4.80米。拱碹是半圆形纵联式结构，无拱眉。中孔跨径10.00米，边孔跨径8.50米。', '', 11, NULL, NULL, '', 8, 1, 8, 1, '宁波市象山县西周镇儒雅洋村，跨西沙岭下的缘溪上', '块石', 50, 131, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1204, '瑞安桥', '瑞安桥是一座单孔石拱桥。桥面为弧形，无栏杆。桥面宽4.50米，桥长32.00米，两端有引道，桥全长62.50米。侧墙用料石砌筑，上顶无仰天石。桥台是凹字形，前墙长4.50米。拱碹是半圆形纵联分段并列式结构，无拱眉，碹脸与侧墙平。跨径10.50米。', '', 11, NULL, NULL, '', 8, 1, 8, 1, '宁波市象山县墙头镇方家岙，跨方家岙溪上', '料石', 50, 132, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1205, '白岩桥', '桥面大致是弧形，两端是阶梯式坡道，无栏杆，桥面宽3.30米，桥长25.00米。桥台前墙与石砌河岸为一体。桥墩两端是尖形，拱碹是半圆形纵联式结构，无拱眉，碹脸与侧墙平。中孔跨径8.50米，边孔跨径7.50米。', '', 11, NULL, NULL, '', 10, 1, 10, 1, '余姚市陆埠镇，跨于山涧中', '石材', 50, 133, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1206, '余姚大方桥', '大方桥是一座单孔石拱桥。桥面中部(拱顶上)高起为平面，两侧有节间式石栏杆，中间一块栏板上刻着“大方桥”三个大字，无地伏，桥栏杆置于仰天石上。桥面宽5.00米，桥长26.30米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长5.40米，端墙外端有燕翅墙。拱碹是半圆形纵联分段并列式结构，有拱眉，拱眉的外边錾凸出的拱眉线，拱眉线凸出于侧墙。跨径13.00米。', '', 11, NULL, NULL, '', 8, 1, 8, 1, '余姚市鹿亭乡晓云村', '石材（料石）', 50, 134, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1207, '福泉桥', '福泉桥是一座单孔石拱桥。桥面中部(拱顶上)高起为平面，两端是阶梯式坡道。两侧有节间式石栏杆，无地伏，桥栏杆置于仰天石上。桥面宽2.50米，桥塊外端宽3.50米，桥长47.00米。侧墙用料石砌筑，上顶有双层仰天石。桥台是凹字形，前墙长3.80米。拱碹是半圆形纵联分段并列式结构，有双线拱眉。跨径13.00米。桥台上的侧墙上各有一根桥联柱，上顶有勾头石。', '', 11, NULL, NULL, '', 10, 1, 10, 1, '余姚市河姆渡镇河姆渡村，跨姚江支流上', '料石', 50, 135, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1208, '季卫桥', '桥塊和桥面上铺砌条形石板，两侧有板式石栏杆，无地伏，栏杆置于仰天石上。桥面宽5.00米，桥长51.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长5.30米。桥墩两端与拱脚取齐，桥墩厚1.00米，桥墩长5.30米。拱碹是半圆形纵联分段并列式结构，有拱眉，拱眉的外边凸出于碹脸，拱眉与侧墙平。中孔跨径10.22米，次边孔跨径9.00米，边孔跨径8.00米。各孔拱碹之间(桥墩上)的侧墙上各有一根桥联柱，上顶有一个石雕龙头。', '', 11, NULL, NULL, '', 8, 1, 10, 1, '余姚市跨候青江上', '条形石板、料石', 50, 136, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1209, '赤水桥', '赤水桥是一座单孔石拱桥。桥面中部(拱顶上)高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆，无地伏，桥栏杆置于仰天石上。桥面宽5.30米，桥长39.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台前墙与石砌河岸为一体。拱碹是圆弧形纵联式结构，无拱眉，碹脸与侧墙平。跨径14.50米。', '', 11, NULL, NULL, '', 10, 1, 10, 1, '余姚市柿林村，跨赤水溪上', '石材（料石）', 50, 137, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1210, '通济桥', '今存通济桥是一座3孔石拱桥。桥面中部(中孔上)高起为平面，两端是阶梯式坡道。两侧有节间式石栏杆，每侧有望柱14根，栏板13块，抱鼓石2块。无地伏，桥栏杆置于仰天石上。桥面宽5.61米，桥长43.39米。侧墙用条石砌筑，上顶有单层仰天石组成的金边线。桥台是凹字形，前面和两侧有出台，前墙长约6.20米。桥墩两端是方形，四周有出台，桥墩厚1.25米，桥墩长6.20米。拱碹是半圆形纵联分段并列式结构，中孔由8道纵联石 and 9段拱碹石构成，边孔由6道纵联石和7段拱碹石构成，碹脸外边有拱眉石，拱眉凸出于碹脸，拱眉与侧墙平。中孔跨径15.40米，边孔跨径12.50米。碹脸之间(桥墩上)的侧墙上各有一根桥联柱，上顶有勾头石，分别刻有对联，东面的上联是“千时遥吞沧海月”,下联是“万年独抵大江浪”;西面的上联是“一曲蕙兰飞彩鹚”,下联是“双城烟雨卧长虹”。', '', 11, NULL, NULL, '', 8, 1, 8, 1, '浙江省余姚市跨姚江上', '石材、条石', 50, 138, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1211, '武胜桥', '武胜桥是一座单孔石拱桥。桥面中部(拱顶上)高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆，无地伏，桥栏杆置于仰天石上。桥面宽3.50米，桥长33.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长3.80米。拱碹是半圆形纵联分段并列式结构，有双线拱眉，拱眉凸出于碹脸，拱眉与侧墙平。跨径9.00米。', '', 11, NULL, NULL, '', 8, 1, 8, 1, '余姚市武胜门外，跨护城河上', '料石', 50, 139, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1212, '镇东桥', '桥面宽4.60米，桥长7.80米。桥上建砖木结构廊。侧墙用料石砌筑，上顶无仰天石。桥台是凹字形，前墙长4.30米。拱碹是半圆形纵联式结构，无拱眉，碹脸与侧墙平。跨径8.00米。', '', 11, NULL, NULL, '', 8, 1, 8, 1, '余姚市四明山镇梨洲庙下村', '石、砖木', 50, 140, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1213, '东双桥', '桥面中部高起为平面，两端各有一段缓坡，东端与平面桥堍连接，西端有一段阶梯式坡道(长5.00米)，坡道下面是一孔石板梁桥。两侧有节间式石栏杆，每侧有6根望柱，5段石栏板，2块抱鼓石。无地伏，桥栏杆置于仰天石上。桥面宽8.40米，桥长20.00米。侧墙用料石砌筑，上顶有双层仰天石组成的金边线。桥台为凹字形，前面和两侧有10厘米出台，端墙外有燕翅墙，前墙长8.60米。拱碹是半圆形分段并列式结构，由7段拱碹石构成，碹脸外缘錾出双线拱眉，拱眉凸出于侧墙。跨径4.80米。', '', 11, NULL, NULL, '', 5, 1, 5, 1, '绍兴市城内东街，跨街河上', '石材（料石、拱碹石）', 50, 141, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1214, '绍兴府桥', '桥面中部高起为平面，两端是阶梯式坡道。两侧有节间式石栏杆，无地伏，桥栏杆置于双层仰天石上。桥面宽 3.50米，桥长14.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台前墙与石砌街河两岸相连接。拱碹是半圆形镶边纵联式结构，碹脸外边有拱眉石，拱眉与侧墙平。跨径7.60米。', '', 11, NULL, NULL, '', 5, 1, 5, 1, '绍兴市区，跨街河上', '料石', 50, 142, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1215, '光相桥', '桥面中部高起为平面，两端是阶梯式坡道。两侧有节间式石栏杆，每侧有4根望柱，3段栏板，2块抱鼓石。无地伏，桥栏杆置于仰天石上。桥面宽4.90米，桥长30.28米。侧墙上顶有单层仰天石组成的金边线，侧墙建在块石砌筑的河岸平台上。桥台与块石砌筑的河岸为一体，高程相同。拱碹是半圆形分段并列式结构，共11段拱碹石，无拱眉，碹脸与侧墙平。跨径10.00米。拱碹上方两边各有1个勾头石，桥孔两边(桥台以上)的侧墙上各有1根桥联柱，上顶有勾头石。', '', 11, NULL, NULL, '', 5, 1, 5, 1, '绍兴，跨古运河上', '石材', 50, 143, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1216, '凰仪桥', '凰仪桥是一座单孔石拱桥。跨街河上，桥面中部(拱顶上)高起为平面，两端是阶梯式坡道，东坡12阶，西坡11阶。两侧有节间式石栏杆。桥面宽3.05米，桥长10.55米。侧墙用条形石板砌筑，上顶有双层仰天石。桥台是凹字形，前墙长3.60米。拱碹是半圆形纵联分段并列式结构，碹脸外镶有拱眉石，拱眉凸出于碹脸，拱眉与侧墙平。跨径7.30米。', '', 11, NULL, NULL, '', 5, 1, 5, 1, '绍兴市鲁迅西路与红旗路交叉口', '石材（条形石板）', 50, 144, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1217, '题扇桥', '桥面为穹隆形，两侧有节间式石栏杆，每侧有4根望柱，3段石栏板，2块抱鼓石。无地伏，桥栏杆置于仰天石上。桥面宽4.30米，桥面长4.95米，桥长20.00米。侧墙上顶有双层仰天石组成的金边线，两层石板均为矩形断面，上层石板很薄，下层石板很厚(约为上层石板的4倍)。桥台的前墙与石砌河岸为一体，拱碹是半圆形分段并列式结构，共7段拱碹石，无拱眉，碹脸与侧墙平。跨径5.00米。', '', 11, NULL, NULL, '', 8, 1, 5, 1, '浙江省绍兴市城区蕺山街，跨街河上', '石材', 50, 145, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1218, '安吉桥', '安吉桥是一座单孔石拱桥。桥面中部(拱顶上)高起为平面，两端是阶梯式坡道。两侧有板式石栏杆，无地伏，桥栏杆置于仰天石上。桥面宽4.30米，桥长30.00米。侧墙用条形石板砌筑，上顶有双层仰天石组成的金边线。桥台是凹字形，前面和两侧皆有小出台。拱碹是马蹄形分段并列式结构，碹脸外边有双线拱眉石，拱眉凸出于碹脸，又凸出于侧墙。跨径8.60米。', '', 11, NULL, NULL, '', 5, 1, 5, 1, '绍兴市柯桥区安昌镇跨街河上', '石材', 50, 146, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1219, '存德桥', '桥面中部(拱顶上)高起为平面，两端是阶梯式坡道。两侧有节间式石栏杆，每侧有望柱4根，栏板3块，抱鼓石2块，无地伏，桥栏杆置于仰天石上。桥面宽3.00米，桥长10.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台前墙与石砌河岸为一体，拱碹是半圆形纵联分段并列式结构，由8道纵联石和9段拱碹石构成，碹脸外缘錾出拱眉线，拱眉与侧墙平。跨径4.70米。', '', 11, NULL, NULL, '', 8, 1, 8, 1, '绍兴市柯桥区漓渚镇，跨于街河上', '石材（料石）', 50, 147, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1220, '大木桥', '大木桥原系木桥，后改建成石桥。桥面中部(拱顶上)高起为平面，两端是阶梯式坡道。两侧有节间式石栏杆，每侧有望柱4根，栏板3块，无地伏，桥栏杆置于仰天石上，桥栏杆的两端与建筑物相连。桥面宽数据暂缺，桥面长17.50米，全长21.00米。桥台是凹字形，前面和两侧有出台，端墙两侧与河岸连砌。拱碹是半圆形纵联分段并列式结构，由8道纵联石和9段拱碹石构成，碹脸外边有拱眉石，拱眉凸出于碹脸，又凸出于侧墙。跨径4.80米。', '', 11, NULL, NULL, '', 5, 1, 5, 1, '浙江省绍兴市柯桥区鲤鱼桥东侧街河上', '石材', 50, 148, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1221, '待驾桥', '桥面中部(拱顶上)高起为平面，两端是阶梯式坡道，南北坡各有12级台阶。两侧有节间式石栏杆，每侧有望柱6根，栏板5块，抱鼓石2块，无地伏，桥栏杆置于仰天石上。桥面宽3.10米，净宽2.70米，桥长20.00米。侧墙用条石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长3.60米，端墙很长。拱碹是半圆形纵联分段并列式结构，由6道纵联石和7段拱碹石构成，碹脸外缘錾出拱眉线，拱眉凸出于侧墙。跨径6.80米。', '', 11, NULL, NULL, '', 5, 1, 5, 1, '绍兴市柯桥区华舍街道人利村，跨街河上', '石材', 50, 149, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1222, '管宁桥', '管宁桥是一座单孔石拱桥。桥面中部(拱顶上)为平面，两端是阶梯式坡道。两侧有矮石板栏杆。桥面宽2.28米，净宽1.60米，桥长14.40米。侧墙用料石砌筑，上顶有双层仰天石。桥台是凹字形，前墙长2.20米。跨径3.80米。', '', 11, NULL, NULL, '', 8, 1, 8, 1, '绍兴市柯桥区管墅村，跨街河上', '石材', 50, 150, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1223, '广溪桥', '桥面中部(拱顶上)高起为平面，两端是阶梯式坡道。两侧有节间式石栏杆，每侧有6根望柱，5段石栏板，一端有抱鼓石，另一端的端望柱与建筑物连接。无地伏，桥栏杆置于仰天石上。桥面宽4.10米，桥长21.40米。侧墙用条形石板砌筑，上顶有单层仰天石。桥台是凹字形，拱碹是半圆形纵联分段并列式结构，由8道纵联石和9段拱碹石构成，碹脸外边有拱眉石，拱眉凸出于碹脸，拱眉又凸出于侧墙。跨径6.20米。', '', 11, NULL, NULL, '', 5, 1, 5, 1, '绍兴市柯桥区广溪村', '石材', 50, 151, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1224, '绍兴荷花桥', '全桥共3孔，全长23.00米。拱桥的桥面中部(拱顶上)高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆，每侧有望柱4根，栏板3块，抱鼓石2块。桥面宽2.30米。桥台是凹字形(和石梁桥共用),前墙长约2.90米，端墙长约4.00米。拱碹是半圆形纵联分段并列式结构，由6道纵联石和7段拱碹石构成，碹脸外有拱眉石，拱眉凸出于碹脸，又凸出于侧墙。跨径3.20米。石板梁桥的桥面均为平面，无栏杆，桥面宽均为2.30米。外桥台是凹字形，前墙长约2.90米。跨径6.00米。', '', 11, NULL, NULL, '', 5, 1, 5, 1, '绍兴市柯桥区蜀埠村', '石材', 50, 152, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1225, '花浦桥', '桥面中部高起为平面，两端是阶梯式坡道。两侧有节间式石栏杆，每侧有望柱8根，栏板7块，抱鼓石2块，无地伏，桥栏杆置于双层仰天石上。桥面宽2.42米，桥长22.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前面和两侧皆有出台，前墙长3.00米。拱碹是马蹄形纵联分段并列式结构，由8道纵联石和9段拱碹石构成，碹脸外缘錾出拱眉线，拱眉与侧墙平。跨径5.00米。碹脸两侧上方各有一个勾头石。', '', 11, NULL, NULL, '', 8, 1, 8, 1, '绍兴市柯桥区斗门镇', '石材', 50, 153, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1226, '华春桥', '桥面中部高起为平面，两端是阶梯式坡道。两侧有节间式石栏杆，桥面宽3.50米，桥长9.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长3.80米。拱碹是马蹄形纵联分段并列式结构，由8道纵联石和9段拱碹石构成，碹脸外有拱眉石，拱眉凸出于侧墙。跨径3.30米。', '', 11, NULL, NULL, '', 5, 1, 5, 1, '绍兴市柯桥区', '料石', 50, 154, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1227, '接渡桥', '今存接渡桥是由一座3孔等跨径石拱桥和两端各一座单孔石梁桥对接而成。石拱桥的桥面是平面，两端桥堍是阶梯式坡道。两侧有节间式石栏杆，有望栏10根，石栏板9块，为实体板，均无抱鼓石，柱顶有石狮子，无地伏，桥栏杆置于双层仰天石上。桥面宽2.80米，桥面长42.00米，全长50.00米。侧墙用条形石板砌筑，上顶有双层仰天石组成的金边线，上层仰天石的外立面是平面，下层托石的外立面是弧形面。桥台是凹字形，端墙很长，前面和两侧下部皆有小出台。桥墩两端为方形，四周下部有出台，桥墩厚10.50米，桥墩长3.00米。拱碹均系马蹄形纵联分段并列式结构，各孔均为6道纵联石，7段拱碹石，碹脸外边有拱眉石，拱眉凸出于碹脸，拱眉与侧墙平。跨径4.20米。石梁桥的桥面均为平面，无栏杆，桥面宽2.80米。桥梁全长50.00米。跨径3.90米。', '', 11, NULL, NULL, '', 5, 1, 5, 1, '浙江省绍兴市柯桥区鸡笼江上', '石材（条形石板）', 50, 155, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1228, '柯桥', '柯桥是一座单孔石拱桥。桥上有石栏杆，桥面中部高起为平面，两端均为阶梯式坡道。桥面宽6.00米，桥长17.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台为凹字形，前墙长6.60米。拱碹为圆弧形并列式结构。跨径10.00米。', '', 11, NULL, NULL, '', 5, 1, 5, 1, '绍兴市柯桥区', '料石', 50, 156, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1229, '螺山桥', '螺山桥是一座3孔石拱桥和西端1孔石梁桥、东端6孔石梁桥对接成的一座混合结构石桥。全桥共10孔，梁总长23.00米。石拱桥的桥面呈正圆弧形，栏杆无存，地伏犹在。桥面宽2.30米，桥堍是反圆弧形，与石板梁桥相接。侧墙用料石砌筑，上顶有单层仰天石。桥台(拱桥和石梁桥合用)是凹字形，前墙长2.90米。桥墩两端是方形，拱碹是半圆形纵联分段并列式结构，碹脸外边有拱眉石，拱眉与侧墙平。中孔跨径10.00米，西边孔跨径6.65米，东边孔跨径7.30米。西端的石梁桥是1孔，无栏杆，桥面宽2.30米。外桥台是凹字形，前墙长约2.90米。东端的石梁桥是6孔，无栏杆，桥面宽2.30米。外桥台是凹字形，前墙长约2.90米。桥墩两端均为方形。', '', 11, NULL, NULL, '', 5, 1, 5, 1, '绍兴市柯桥区吴村，跨于西小江上', '石材（料石）', 50, 157, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1230, '融光桥', '融光桥原名柯桥，是一座单孔石拱桥。桥面中部高起为平面，两端是阶梯式坡道。两侧有节间式石栏杆，每侧有4根望柱，3段石栏板，两端的望柱与河岸上的石栏杆相连。无地伏，桥栏杆置于仰天石上。桥面宽6.00米，桥长17.00米。侧墙的上顶有单层仰天石组成的金边线。桥台前墙与块石砌筑的河岸为一体，桥台与河岸的高程相同。拱碹是圆弧形纵联分段并列式结构，由6道纵联石和7段拱碹石构成，无拱眉，碹脸与侧墙平。跨径10.00米。', '', 11, NULL, NULL, '', 5, 1, 5, 1, '绍兴市柯桥区，跨运河故道上', '石材', 50, 158, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1231, '阮社桥', '阮社桥原是一座纤道桥，现仅存石拱桥部分。桥面中部（拱顶上）高起为平面，两端是阶梯式坡道，无栏杆。桥面宽2.50米，桥长12.00米。侧墙用条形石板砌筑，上顶有双层仰天石。桥台是凹字形，桥台的前面和西侧有出台，前墙长3.10米。东侧前墙与石板砌筑的河岸连砌为一体。拱碹是马蹄形纵联分段并列式结构，由6道纵联石和7段拱碹石构成，碹脸外缘錾出双线拱眉线，拱眉凸出于侧墙。跨径4.00米。', '', 11, NULL, NULL, '', 5, 1, 5, 1, '绍兴市柯桥区阮社镇，跨于运河旁边的支流上', '石材（条形石板、纵联石、拱碹石）', 50, 159, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1232, '沈家桥（又名花洞桥）', '桥面中部(拱顶上)高起为平面，两端是阶梯式坡道。两侧有节间式石栏杆，无地伏，桥栏杆置于双层仰天石上。桥面宽2.20米，桥长12.00米。侧墙上顶有双层仰天石组成的金边线。桥台是凹字形，前面和两侧有出台，前墙长2.80米。拱碹是半圆形纵联分段并列式结构，由4道纵联石和5段拱碹石构成，无拱眉，碹脸与侧墙平。跨径3.95米。', '', 11, NULL, NULL, '', 7, 1, 5, 1, '绍兴市柯桥区沈家桥村', '石材', 50, 160, '2026-04-28 23:07:54', '2026-04-28 23:36:19');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1233, '绍兴太平桥', '太平桥是一座由1孔石拱桥和9孔石梁桥组成。石拱桥在东端，石梁桥的桥面由石拱桥一端向西逐孔有所降低。石拱桥的桥面中部(拱顶上)高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆。桥面宽5.60米，桥长22.00米。侧墙用料石砌筑，上顶有单层仰天石。内侧桥台是凹字形，与石梁桥的桥台为同一个。拱碹是半圆形纵联分段并列式结构，碹脸外缘錾出拱眉线，拱眉凸出于碹脸，又凸出于侧墙。跨径8.40米。东桥台两侧和前面有石板砌筑的人行道。石梁桥的桥面由东往西逐孔有所降低，无栏杆。桥面宽5.60米，桥长30.00米，石拱桥和石梁桥总长50.00米。东桥台与石拱桥共用，西桥台是凹字形，桥墩两端是方形。跨径3.00—4.00米。', '', 11, NULL, NULL, '', 8, 1, 7, 1, '绍兴市柯桥区阮社村，跨萧绍运河上', '石材', 50, 161, '2026-04-28 23:07:54', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1234, '宣桥（登仙桥）', '桥面为弧形，无栏杆，两侧各有一道边牙石。桥面宽5.00米，桥长12.00米。侧墙用乱石砌筑，上顶有一层较厚的边牙石。桥台建在天然基岩上，形状不规则。拱碹是半圆形纵联分段并列式结构，无拱眉，碹脸与侧墙平。', '', 11, NULL, NULL, '', 8, 1, 8, 1, '绍兴市柯桥区郑家闸村，跨于乡间排水沟上', '石材', 50, 162, '2026-04-28 23:07:54', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1235, '永丰桥', '今存永丰桥是一座单孔石拱桥，桥面中部(拱顶上)高起为平面，两端是阶梯式坡道。两侧有板式石栏杆，无地伏，桥栏杆置于仰天石上。桥面宽2.80米，长10.00米。侧墙用条石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长3.40米。拱碹是马蹄形并列式结构，无拱眉，碹脸与侧墙平。跨径4.50米。', '', 11, NULL, NULL, '', 5, 1, 5, 1, '浙江省绍兴市柯桥区街河上', '石材', 50, 163, '2026-04-28 23:07:54', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1236, '越联桥', '桥面中部(拱顶上)高起为平面，两侧有板式石栏杆，两端是阶梯式坡道，无栏杆。桥面宽5.20米，桥长14.50米。侧墙用乱石砌筑，上顶有单层仰天石。桥台的前墙两端有乱石砌筑的高大燕翅墙。拱碹是用料石砌筑的半圆形纵联式结构，无拱眉，碹脸与侧墙平。跨径8.80米。', '', 11, NULL, NULL, '', 5, 1, 5, 1, '浙江省绍兴市柯桥区越联村，跨街河上', '石材（乱石、料石）', 50, 164, '2026-04-28 23:07:54', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1237, '绍兴寨口桥', '118. 绍兴寨口桥 寨口桥位于绍兴市柯桥区莲增村，跨于乡间排水沟上，于清嘉庆年 间(1796—1820年)修建，光绪十二年(1886年)重修。 寨口桥是一座单孔石拱桥。桥面为圆弧形，无栏杆，亦无边牙石。 桥面宽2.60米，桥长30.00米。 无正规桥台，拱脚建在山脚下的岩石上，拱碹是圆弧形纵联式结 构，无拱眉，碹脸与侧墙平。跨径15.00米。', '', 11, NULL, NULL, '', 8, 1, 8, 1, '', NULL, 50, 165, '2026-04-28 23:07:54', '2026-04-28 23:07:54');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1238, '中南桥', '桥面中部高起为平面，两端是阶梯式坡道。两侧有板式石栏杆，无地伏，桥栏杆置于仰天石上，桥栏杆及地伏多有损坏。桥面宽3.30米，桥长22.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前面和两侧皆有小出台。拱碹是半圆形并列式结构，由4道纵联石和5段拱碹石构成，碹脸外缘錾出拱眉线，拱眉凸出于侧墙。跨径15.00米。', '', 11, NULL, NULL, '', 5, 1, 5, 1, '绍兴市柯桥区街河上', '石材（料石、仰天石、纵联石、拱碹石）', 50, 166, '2026-04-28 23:07:54', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1239, '周家桥', '今存周家桥是一座单孔石拱桥。桥面中部高起为平面，两端是阶梯式坡道。两侧有节间式石栏杆，每侧有望柱4根，栏板3块，无地伏，桥栏杆置于仰天石上，桥栏杆两端与建筑物连接。桥面宽2.00米，桥长13.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台前墙与石砌河岸为一体，拱碹是半圆形纵联分段并列式结构，由6道纵联石和7段拱碹石构成，无拱眉，碹脸与侧墙平。跨径4.75米。', '', 11, NULL, NULL, '', 5, 1, 5, 1, '绍兴市柯桥区迎驾桥村，跨街河上', '料石', 50, 167, '2026-04-28 23:07:54', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1240, '孔庙桥', '孔庙桥是一座单孔石拱桥。桥面是圆弧形，无栏杆。桥面宽 5.00米，桥长13.00米。侧墙用不规则石料砌筑，上面有单层仰天石。桥台是凹字形，前墙长5.60米。拱碹是半圆形纵联式结构，无拱眉，碹脸与侧墙平。跨径 3.60米。', '', 11, NULL, NULL, '', 5, 1, 5, 1, '绍兴市', '石料', 50, 168, '2026-04-28 23:07:54', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1241, '绍兴八字桥', '该桥实际上由通济桥（俗称“大八字桥”）和望稼桥（俗称“小八字桥”）非直线对接而成。通济桥为单孔石拱桥，桥面宽5.50米，桥长18.00米，拱碹是半圆形纵联分段并列式结构，由8道纵联石和9段拱碹石构成，跨径6.80米。望稼桥亦为单孔石拱桥，桥面宽5.50米，桥长13.00米，拱碹是圆弧形纵联分段并列式结构，由6道纵联石 and 7段拱碹石构成，跨径4.00米。两桥内桥台对接，外桥台均为凹字形。', '', 11, NULL, NULL, '', 5, 1, 5, 1, '绍兴市上虞区丰惠镇', '石材（料石、仰天石、拱碹石、石栏杆）', 50, 169, '2026-04-28 23:07:54', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1242, '绍兴泾口桥', '泾口桥由3孔石拱桥和3孔石梁桥连接而成，二桥连接处既是二桥的桥台，又是全桥的桥墩。石拱桥部分为3孔等跨径薄拱薄墩轻石拱桥，桥面宽3.40米，长20.00米，跨径均为10.00米，拱碹为马蹄形纵联分段并列式结构（6道纵联石，7段拱碹石），桥台为凹字形。石梁桥部分为3孔石板梁桥，桥面宽3.40米，长15.00米，全长27.00米，桥墩厚1.25米，长4.00米，中孔跨径6.70米，西边孔跨径6.60米，东边孔跨径5.85米。二桥以外有石堤，桥梁全长（包括石堤）60.00米。', '', 11, NULL, NULL, '', 8, 1, 5, 1, '浙江省绍兴市上虞区陶堰镇泾口村，跨浙东运河上', '石材（料石、石板、纵联石、拱碹石）', 50, 170, '2026-04-28 23:07:54', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1243, '九狮桥（又名“等慈桥”）', '桥面中部(拱顶上)为平面，两端是阶梯式坡道，无栏杆，两侧各有一道边牙石。桥面宽6.00米，桥长26.00米。侧墙用条石砌筑，上顶有双层仰天石。桥台是凹字形，前墙长6.60米。端墙的外端与石砌河岸相连。拱碹是半圆形纵联式结构，无拱眉，碹脸与侧墙平。跨径10.40米。', '', 11, NULL, NULL, '', 5, 1, 5, 1, '绍兴市上虞区丰惠镇街河上', '石材（条石）', 50, 171, '2026-04-28 23:07:54', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1244, '绍兴广济桥', '今存桥是一座3孔石拱桥。桥塊为坡道与河岸连接，桥面中部(中孔上)高起为平面，两个边孔上桥面较低，也都是平面，中部桥面与两端的桥面之间有三步台阶连接。全桥无栏杆，桥面宽4.00米，桥梁全长40.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台属于带燕翅形，前墙长5.20米。桥墩两端为尖形，桥墩长4.00米。拱碹均为半圆形纵联式结构，无拱眉，碹脸与侧墙平。中孔跨径11.30米，北边孔跨径9.50米，南边孔跨径8.90米。', '', 11, NULL, NULL, '', 5, 1, 5, 1, '绍兴上虞区西里村', '石材、料石', 50, 172, '2026-04-28 23:07:54', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1245, '虹桥（灵芝桥）', '桥面中部高起为平面，两端是阶梯式坡道。两侧有节间式石栏杆，每侧有望柱4根，石栏板3块，端望柱与建筑物连接，无地伏，桥栏杆置于双层仰天石上，桥面宽2.50米，桥长16.00米。桥台前墙与石砌河岸为一体，拱碹是纵联分段并列式结构，由6道纵联石和7段拱碹石构成，碹脸外边有双线拱眉石，拱眉凸出于碹脸，拱眉又凸出于侧墙。跨径4.50米。', '', 11, NULL, NULL, '', 5, 1, 5, 1, '浙江省绍兴市越城区灵芝村，跨于街河上', '石材', 50, 173, '2026-04-28 23:07:54', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1246, '壶觞桥', '桥面中部(拱顶上)高起为平面，两端是阶梯式坡道。桥面中部两侧有板式石栏杆，桥面宽3.00米，桥长11.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长3.60米。拱碹是马蹄形纵联分段并列式结构，由4道纵联石和5段拱碹石构成，碹脸外缘錾出拱眉线，拱眉凸出于侧墙。跨径4.50米。', '', 11, NULL, NULL, '', 5, 1, 5, 1, '绍兴市越城区壶觞村', '石材（料石）', 50, 174, '2026-04-28 23:07:54', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1247, '龙门桥', '龙门桥是一座单孔石拱桥。桥面中部(拱顶上)高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆。桥面宽4.60米，桥长18.50米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形。拱碹是半圆形纵联分段并列式结构，有拱眉，拱眉凸出于碹脸，又凸出于侧墙，跨径11.50米。', '', 11, NULL, NULL, '', 5, 1, 5, 1, '嵊州郊区乡间，跨山涧溪流上', '石板、块石、片石', 50, 175, '2026-04-28 23:07:54', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1248, '泗龙桥', '泗龙桥全长96.40米。石拱桥部分：桥面中部高起为平面，两端为阶梯式坡道，两侧有节间式石栏杆（每侧6根望柱，5块石栏板，2块抱鼓石），无地伏，桥栏杆置于单层仰天石上。桥面宽3.00米，桥长约21.00米。侧墙用料石砌筑，桥台为凹字形，前墙长3.60米。桥墩两端为方形，厚1.05米，长3.50米。拱碹为半圆形纵联分段并列式结构，碹脸外有拱眉石。中孔跨径6.20米，边孔跨径5.40米。侧墙上有勾头石和桥联柱，北面桥联柱有对联。石板梁桥部分：桥面为花岗岩石板梁，无栏杆，桥面宽3.00米，桥台为凹字形，前墙长3.60米，桥墩两端为方形，跨径3.20米。', '', 11, NULL, NULL, '', 5, 1, 5, 1, '绍兴市越城区东浦镇鲁东村', '料石、花岗岩石板', 50, 176, '2026-04-28 23:07:54', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1249, '绍兴新桥', '桥面的中部(中孔)高起为平面，两端是阶梯式坡道。桥面两侧有节间式石栏杆(坡道上无栏杆),每侧有4根望柱，3段石栏板，2块抱鼓石。无地伏，桥栏杆置于双层仰天石上。桥面宽2.50米，桥长10.50米。侧墙用料石砌筑，上顶有单层仰天石。桥台为凹字形，前面和两侧下部皆有小出台，端墙与石砌河岸连砌。中孔拱碹是马蹄形纵联分段并列式结构，边孔拱碹是半圆形纵联分段并列式结构，各孔的拱碹均为4道纵联石，5段拱碹石，碹脸外镶有拱眉石，拱眉凸出于碹脸，又凸出于侧墙。中孔跨径4.40米，边孔跨径均为2.20米。中孔拱碹两边的侧墙上(桥墩上)各有一根桥联柱，上顶有勾头石。', '', 11, NULL, NULL, '', 5, 1, 5, 1, '绍兴市越城区东浦镇', '料石、石材', 50, 177, '2026-04-28 23:07:54', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1250, '徐公桥', '今存徐公桥是一座单孔石拱桥。桥面中部(拱顶上)高起为平面，两端是阶梯式坡道。两侧有节间式石栏杆，每侧有望柱6根，栏板5块，抱鼓石2块，无地伏，桥栏杆置于仰天石上。桥面宽2.50米，桥长14.00米。侧墙是用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长3.80米。拱碹是半圆形纵联分段并列式结构，碹脸外有拱眉石，拱眉凸出于侧墙。跨径5.10米。', '', 11, NULL, NULL, '', 5, 1, 5, 1, '绍兴市越城区栖凫村，跨于街河上', '料石', 50, 178, '2026-04-28 23:07:54', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1251, '嵊州大安桥', '大安桥是一座单孔石拱桥。桥面的中部(拱顶上)高起为平面，两端各有一段坡道和一段平道与河岸相连，全桥无栏杆。桥面宽3.50米，桥长11.00米。侧墙用块石砌筑，上顶有单层较厚的仰天石。桥台用块石砌筑，大致是凹字形。拱碹是用片石砌筑的半圆形纵联式结构，无拱眉，碹脸与侧墙平。跨径6.60米。另有描述称其桥面宽3.44米，桥长18.00米，侧墙无仰天石，桥台前墙长4.00米，跨径5.80米。', '', 11, NULL, NULL, '', 10, 1, 10, 1, '浙江省嵊州市乡间溪流上', '块石、片石', 50, 179, '2026-04-28 23:07:54', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1252, '凤仙桥', '桥塊和桥面上铺砌块石面层，全桥桥面略显圆弧形，无栏杆。桥面宽3.60米，桥长10.20米。侧墙用块石砌筑，上顶平铺一层较厚的石板。桥台用块石砌筑，前墙与块石砌筑的河岸为一体。拱碹用片石砌筑，是半圆形纵联式结构，无拱眉，碹脸与侧墙平。跨径3.00米。', '', 11, NULL, NULL, '', 10, 1, 10, 1, '嵊州市，跨于乡间排水沟上', '块石、石板、片石', 50, 180, '2026-04-28 23:07:54', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1253, '福德桥', '今存福德桥是一座单孔石拱桥，跨于山涧排水沟上。桥面为圆弧形，两端各有一段坡道与山脚下河岸连通，桥上无栏杆。桥面宽5.50米，桥长11.00米。侧墙用乱石砌筑，上顶平铺两层石板。桥台前墙与乱石砌筑的河岸为一体。拱碹是半圆形纵联式结构，碹脸与侧墙平。跨径8.00米。', '', 11, NULL, NULL, '', 10, 1, 10, 1, '浙江省嵊州市双桥村', '乱石、石板', 50, 181, '2026-04-28 23:07:54', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1254, '何村桥', '桥面是穹隆形，无栏杆，也无边牙石。桥面宽4.40米，桥长37.00米。侧墙用乱石砌筑，上顶无仰天石，桥台用块石砌筑，是凹字形，前墙长4.70米。拱碹是椭圆形纵联式结构，也是用块石砌筑，无拱眉，碹脸与侧墙平。跨径12.50米。', '', 11, NULL, NULL, '', 10, 1, 10, 1, '嵊州市下王镇何村', '乱石、块石', 50, 182, '2026-04-28 23:07:54', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1255, '金兰桥', '金兰桥是一座4孔等跨径石拱桥。桥塊和桥面上铺砌青石板，全桥为平面。两侧有节间式石栏杆，桥面宽4.40米，桥长84.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台建在山脚岩石上。桥墩上游端是尖形，下游端是方形，拱碹是半圆形纵联式结构，无拱眉，碹脸与侧墙平。跨径18.50米。', '', 11, NULL, NULL, '', 10, 1, 10, 1, '嵊州市金庭乡', '青石板、料石', 50, 183, '2026-04-28 23:07:54', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1256, '龙亭桥', '桥面上铺砌不规则片石，近似圆弧形，无栏杆，又无边牙石。桥面宽4.20米，桥长11.00米。侧墙用块石砌筑，无仰天石。两个桥台的高程不相等，相差80厘米，砌筑在基岩上。拱碹用片石砌筑，是圆弧形纵联式结构，无拱眉，碹脸与侧墙平。跨径6.00米。', '', 11, NULL, NULL, '', 10, 1, 10, 1, '嵊州东林村', '片石、块石', 50, 184, '2026-04-28 23:07:54', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1257, '隆庆桥', '今存隆庆桥是一座单孔石拱桥。桥上无栏杆，两边各有一道边牙石。桥面宽3.70米，桥长12.50米。侧墙用块石砌筑，上顶无仰天石。桥台前墙与石砌河岸为一体，拱碹是半圆形纵联分段并列式结构，无拱眉，碹脸与侧墙平。跨径10.00米。', '', 11, NULL, NULL, '', 7, 1, 10, 1, '嵊州毫石村，跨乡间排水沟上', '石材', 50, 185, '2026-04-28 23:07:54', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1258, '强口桥', '桥面为圆弧形，桥上无栏杆。桥面宽 6.00米，桥长21.50米。侧墙用乱石砌筑，桥台是凹字形。拱碹是半圆形纵联式结构，用不规则石料砌筑，碹脸与侧墙平。跨径7.80米。', '', 11, NULL, NULL, '', 10, 1, 10, 1, '嵊州强口村', '乱石、不规则石料', 50, 186, '2026-04-28 23:07:54', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1259, '嵊州三连桥', '今存三连桥是一座单孔石拱桥。拱顶上无铺装，拱顶即是桥面，两端是坡道。桥面宽6.20米，桥长21.00米。侧墙用乱石砌筑。桥台是用乱石砌筑的不规则形，前墙与乱石砌筑的护坡相连。拱碹近似半圆形，是用片石砌筑的纵联式结构，无拱眉，碹脸与侧墙平。跨径14.50米。', '', 11, NULL, NULL, '', 10, 1, 10, 1, '嵊州郊区乡间，跨山涧溪流上', '乱石、片石', 50, 187, '2026-04-28 23:07:54', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1260, '善济桥', '桥面宽4.60米，桥长26.50米。侧墙用乱石砌筑，无仰天石。桥台的前墙与石砌河岸为一体。拱碹用片石砌筑，是近似半圆形纵联式结构，无拱眉。跨径11.80米。', '', 11, NULL, NULL, '', 10, 1, 10, 1, '嵊州市郊区，跨无名排水沟上', '乱石、片石', 50, 188, '2026-04-28 23:07:54', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1261, '狮岸坑桥', '桥面中部为圆弧形，两端是较缓的坡道，无铺装，全是土路面。桥上无栏杆，亦无边牙石。桥面宽4.20米，桥长21.00米。侧墙用块石砌筑，桥台用块石砌筑，建在河床中的基岩上，前墙与块石砌筑的河岸为一体。拱碹是用片石砌筑的半圆形纵联式结构，无拱眉，碹脸与侧墙平。跨径16.80米。', '', 11, NULL, NULL, '', 10, 1, 10, 1, '嵊州郊区，跨山涧溪流上', '块石、片石', 50, 189, '2026-04-28 23:07:54', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1262, '双喜桥', '桥塊和桥面是坡度较缓的圆弧形，无铺装，桥上无栏杆，亦无边牙石。桥面宽4.60米，桥长13.50米。侧墙用块石砌筑，桥台用块石砌筑，建在河床中的基岩上，前墙与块石砌筑的河岸为一体。拱碹是用片石砌筑的半圆形纵联式结构，无拱眉，碹脸与侧墙平。跨径7.80米。', '', 11, NULL, NULL, '', 10, 1, 10, 1, '嵊州郊区乡间，跨山涧溪流上', '块石、片石', 50, 190, '2026-04-28 23:07:54', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1263, '嵊州太平桥', '桥面略显圆弧形，桥上无栏杆。桥面宽2.35米，桥长9.00米。侧墙用块石砌筑，桥台建在山脚下的基岩上，前墙与石砌河岸为一体。拱碹是用片石砌筑的半圆形纵联式结构，无拱眉，碹脸与侧墙平。跨径6.60米。', '', 11, NULL, NULL, '', 10, 1, 10, 1, '嵊州市，跨山涧溪流上', '块石（侧墙）、片石（拱碹）', 50, 191, '2026-04-28 23:07:54', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1264, '梯云桥', '桥面中部高起为平面，两端是阶梯式坡道。两侧有宇墙式石栏杆，无地伏，桥栏杆置于仰天石上。桥面宽 6.60米，桥长16.50米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前面和两侧皆有出台。拱碹是半圆形纵联式结构，无拱眉，碹脸与侧墙平。跨径 9.80米。', '', 11, NULL, NULL, '', 10, 1, 10, 1, '嵊州市', '石材（料石）', 50, 192, '2026-04-28 23:07:54', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1265, '嵊州通济桥', '桥塊和桥面上铺砌块石面层，全桥的桥面为平面，无栏杆，两侧各有一道边牙石。桥面宽5.50米，桥长16.00米。侧墙用块石砌筑，上顶有一层较厚的仰天石，上面高出桥面，成为边牙石。桥台建在基岩上，均系用两层石板砌筑的条形构造，两侧有块石护岸墙。两个桥台的高程不相同，南桥台比北桥台高。拱碹是不对称圆弧形纵联分段并列式结构，龙门碹两边的纵联石和拱碹石数目不相等。一边是2道纵联石和2段拱碹石，另一边是3道纵联石和3段拱碹石，共计5道纵联石和5段拱碹石。碹脸外边有拱眉石，拱眉凸出于侧墙。跨径5.20米。', '', 11, NULL, NULL, '', 10, 1, 10, 1, '嵊州市，跨于乡间溪流上', '块石、石板', 50, 193, '2026-04-28 23:07:54', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1266, '万年桥', '万年桥是一座双孔等跨径石拱桥。桥面为平面，桥塊上是阶梯式坡道。两侧有节间式石栏杆，每侧有12根望柱(桥面上8根，桥塊上各2根),栏杆下面有地伏。桥面宽5.00米，桥长28.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台的前墙与石砌河岸为一体。桥墩两端为尖形，尖端的上面高出拱脚许多(约矢高1/3)。拱碹是半圆形纵联式结构，无拱眉，碹脸与侧墙取平，跨径均为10.00米。', '', 11, NULL, NULL, '', 8, 2, 10, 1, '余姚市大隐镇，跨大隐溪上', '石材', 50, 194, '2026-04-28 23:07:54', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1267, '洗履桥', '桥面上铺砌块石，大致为平面，无栏杆，又无边牙石。桥面宽3.60米，桥长10.20米。侧墙用块石砌筑，无仰天石。桥台是凹字形，前墙长3.60米。拱碹用片石砌筑，是半圆形纵联式结构，碹脸与侧墙平。跨径8.00米。', '', 11, NULL, NULL, '', 10, 1, 10, 1, '嵊州逵溪村', '块石、片石', 50, 195, '2026-04-28 23:07:54', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1268, '永昌桥', '桥塊上无铺装，全是土路面。桥面上也无铺装，石拱碹裸露在外面，上面是圆弧形，两端有3级石板踏步，桥上可以行人。桥面宽6.50米，桥长19.00米。无侧墙，桥台建在山脚岩石上，只有3层石板。拱碹是圆弧形纵联分段并列式结构，由2道纵联石和3段拱碹石构成，每段是5块拱碹石。跨径10.00米。', '', 11, NULL, NULL, '', 10, 1, 10, 1, '嵊州北漳镇任坞村，跨水沟上', '石材', 50, 196, '2026-04-28 23:07:54', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1269, '余庆桥', '桥面略显圆弧形，平铺不规则石板，无栏杆。桥面宽3.50米，桥长12.50米。侧墙用块石砌筑，桥台建在山脚下的基岩上，前墙与块石砌筑的河岸为一体。拱碹是半圆形纵联式结构，无拱眉，碹脸与侧墙平。跨径6.20米。', '', 11, NULL, NULL, '', 10, 1, 10, 1, '嵊州市，跨山涧溪流上', '石材（不规则石板、块石）', 50, 197, '2026-04-28 23:07:54', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1270, '玉成桥', '桥面上铺砌片石，无栏杆，两边各有一道边牙石(侧墙上顶的仰天石)。桥面宽4.70米，桥长12.15米。侧墙用块石砌筑，上顶有一层较厚的仰天石。桥台建在岩石上，是用两层石板砌筑成的长条形，前面和两边皆有出台，前墙长5.00米。拱碹是近似悬链线形纵联式结构，无拱眉，碹脸与侧墙平。跨径6.50米。', '', 11, NULL, NULL, '', 8, 1, 10, 1, '嵊州谷来镇佛头村，跨于乡村排水沟上', '片石、块石、石板', 50, 198, '2026-04-28 23:07:54', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1271, '招隐桥', '招隐桥是一座单孔石拱桥。桥面大致为平面，无栏杆，又无边牙石。桥面宽2.80米，桥长12.35米。侧墙用块石砌筑，无仰天石。桥台是凹字形，前墙长3.20米。拱碹是半圆形纵联式结构，碹脸与侧墙平。跨径4.40米。', '', 11, NULL, NULL, '', 10, 1, 10, 1, '浙江省嵊州市逵溪村', '块石', 50, 199, '2026-04-28 23:07:54', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1272, '嵊州镇东桥', '桥面中部是平面，两端是阶梯式坡道。两侧有节间式石栏杆，每侧有4根望柱，5段石栏板，2块抱鼓石。无地伏，桥栏杆置于单层仰天石上。桥面宽3.10米，桥面长5.40米，全长24.50米。侧墙用块石砌筑，上顶有单层仰天石。桥台是凹字形，前面和两边有出台，前墙长3.70米。拱碹是半圆形纵联分段并列式结构，碹脸外边有拱眉石，拱眉凸出于碹脸，拱眉与侧墙平。跨径9.60米。', '', 11, NULL, NULL, '', 8, 1, 8, 1, '嵊州市谷来镇袁家村，跨于排水沟上', '石材', 50, 200, '2026-04-28 23:07:54', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1273, '大庆桥', '大庆桥无栏杆，两侧各有一道边牙石。桥面宽6.80米，桥长24.00米。侧墙用乱石砌筑，桥台与石砌河岸为一体。拱碹是类似悬链线形纵联式结构，用乱石砌筑，无拱眉。跨径11.50米。', '', 11, NULL, NULL, '', 8, 1, 5, 1, '绍兴市新昌县真诏村，跨真诏溪上', '乱石', 50, 201, '2026-04-28 23:07:54', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1274, '皇渡桥', '桥面是圆弧形，两侧有节间式石栏杆，两端有损坏，每侧尚存望柱10根，栏板9块，抱鼓石2块。地伏和仰天石均为矩形断面。桥面宽5.00米，桥长23.90米。侧墙用料石砌筑，上面是单层仰天石(矩形断面)组成的金边线。桥台两侧有燕翅墙，雁翅墙较高(高达侧墙一半),前墙长6.20米。拱碹是半圆形纵联式结构，无拱眉，碹脸与侧墙平。跨径17.00米。', '', 11, NULL, NULL, '', 8, 1, 5, 1, '绍兴市新昌县儒岙镇', '石材（料石）', 50, 202, '2026-04-28 23:07:54', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1275, '新昌跨湖桥', '桥面中部(拱顶上)高起为平面，两端是阶梯式坡道。桥面宽4.00米，桥长20.00米。侧墙用青石板砌筑，上顶有单层仰天石。桥台是凹字形，前墙长4.00米。拱碹是半圆纵联分段并列式结构，碹脸外边有拱眉，拱眉凸出于碹脸，又凸出于侧墙。跨径6.00米。', '', 11, NULL, NULL, '', 7, 1, 7, 1, '绍兴市新昌县湖塘村，跨十里湖塘的终点处', '青石板', 50, 203, '2026-04-28 23:07:54', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1276, '乐取桥', '乐取桥是一座3孔石拱桥。桥塊和桥面上铺砌块石，桥面略显弧形，两侧有块石砌筑的桥栏杆。桥面宽4.60米，桥长34.00米。侧墙用块石砌筑，上顶有单层仰天石。桥台是燕翅形。桥墩两端是尖形。拱碹是半圆形纵联式结构，中孔南面龙门碹上刻“乐取桥”。中孔跨径9.20米，边孔跨径均为8.20米。', '', 11, NULL, NULL, '', 8, 1, 8, 1, '绍兴市新昌县儒岙镇王渡溪村，跨万年溪上', '块石', 50, 204, '2026-04-28 23:07:54', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1277, '灵鹤桥', '桥面中部(拱顶上) 高起为平面，两侧有板式石栏杆，无地伏，桥栏杆置于仰天石上。两端是阶梯式坡道，坡道上无栏杆。桥面宽5.00米，桥长28.00米。侧墙用块石砌筑，上顶有单层仰天石。南桥台前墙与石砌河岸为一体，北桥台是凹字形，前墙长5.60米。拱碹是半圆形纵联分段并列式结构，由8道纵联式和9段拱碹石构成，无拱眉，碹脸与侧墙平。跨径18.00米。', '', 11, NULL, NULL, '', 5, 1, 5, 1, '绍兴市新昌县小将村', '石材（块石）', 50, 205, '2026-04-28 23:07:54', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1278, '落马桥', '落马桥是一座单孔石拱桥。桥面略显圆弧形，无栏杆，亦无边牙石。桥面宽5.80米，桥长32.00米。侧墙和拱碹用不规则石料砌筑，桥台建在山涧基岩上，拱碹是近似半圆形镶边纵联式结构，无拱眉，碹脸与侧墙齐平。跨径10.00米。', '', 11, NULL, NULL, '', 5, 1, 5, 1, '绍兴市新昌县斑竹村（县城东40里）', '不规则石料', 50, 206, '2026-04-28 23:07:54', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1279, '如意桥（丁公桥）', '如意桥是一座单孔石拱桥。桥塊和桥面上铺砌青石板，桥面中部 (拱顶上)高起为平面，两端是阶梯式坡道，东坡有12级台阶，西坡有 9级台阶，原有石栏杆，今已无存。桥面宽3.40米，桥长20.80米。 侧墙用块石砌筑，上顶有单层仰天石。桥台建在基岩上，大致呈凹字 形。拱碹用片石砌筑，大致为半圆形，属于纵联式结构。跨径5.5米。', '', 11, NULL, NULL, '', 8, 1, 5, 1, '绍兴市新昌县拔茅镇丁公村，跨乡间排水沟上', '青石板（桥塊和桥面）、块石（侧墙）、片石（拱碹）', 50, 207, '2026-04-28 23:07:54', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1280, '新昌沙溪桥', '今存沙溪桥是一座单孔石拱桥。桥面略显圆弧形，无栏杆，又无边牙石。桥面宽4.40米，桥长26.70米。桥台用不规则石料砌筑，建在岩石上。拱碹是近似半圆形纵联式结构，用片石砌筑，碹脸与侧墙平。跨径11.50米。', '', 11, NULL, NULL, '', 5, 1, 5, 1, '绍兴市新昌县沙溪村', '石料（不规则石料、片石）', 50, 208, '2026-04-28 23:07:54', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1281, '迎仙桥', '迎仙桥是一座单孔石拱桥。桥面上铺砌乱石片，桥面大致为圆弧形，无栏杆，两侧各有一道边牙石。桥面宽4.60米，桥长29.00米。侧墙用乱石砌筑，上顶有一层较厚的边牙石。桥台建在基岩上，只有两层石板，前面和两端有小出台，前墙长5.00米。拱碹是类似悬链线形纵联式结构，用乱石砌筑，无拱眉。跨径15.60米。', '', 11, NULL, NULL, '', 8, 1, 7, 1, '绍兴市新昌县桃源乡，104国道旁边', '乱石、石板', 50, 209, '2026-04-28 23:07:54', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1282, '宝珠桥', '桥面中部(拱顶上)高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆，每侧有望柱4根，栏板3块，抱鼓石2块，无地伏，桥栏杆置于仰天石上。桥面宽3.20米，桥长17.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台建在山脚岩石上。拱碹是半圆形纵联分段并列式结构，碹脸外有拱眉石，拱眉凸出于碹脸，又凸出于侧墙。跨径9.70米。', '', 11, NULL, NULL, '', 8, 2, 10, 1, '绍兴市越城区跨街河上', '料石、石板、纵联石', 50, 210, '2026-04-28 23:07:54', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1283, '枫林桥', '枫林桥是一座3孔石拱桥。桥栏杆无存，尚存地伏。桥面宽4.00米，桥长26.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长4.60米。桥墩两端与拱脚齐平，桥墩厚65厘米，桥墩长4.60米。拱碹是半圆形纵联分段并列式结构，碹脸外边有拱眉，拱眉凸出于碹脸，又凸出于侧墙。中孔跨径11.00米，边孔跨径10.70米。', '', 11, NULL, NULL, '', 7, 1, 7, 1, '诸暨市', '料石', 50, 211, '2026-04-28 23:07:54', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1284, '金雁桥', '桥面大致为平面，无栏杆。桥面宽 5.50米，桥长18.50米。侧墙用乱石砌筑，无桥台，拱脚建在岩石上，拱碹是片石砌筑，近似半圆形结构，碹脸与侧墙平。跨径12.50米。', '', 11, NULL, NULL, '', 10, 1, 10, 1, '诸暨市，跨农村排水沟上', '乱石、片石', 50, 212, '2026-04-28 23:07:54', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1285, '媲美桥', '媲美桥是一座双孔石拱桥。桥面高起为平面，两端是阶梯式坡道，两侧有石板栏杆。桥面宽3.40米，桥长25.00米。侧墙用块石砌筑，上顶有单层仰天石。桥台是燕翅形。桥墩两端是尖形。拱碹是半圆形纵联式结构，无拱眉。跨径均为9.80米。', '', 11, NULL, NULL, '', 8, 1, 8, 1, '诸暨市马剑镇栗树坪村', '石材（块石、石板）', 50, 213, '2026-04-28 23:07:54', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1286, '石佛桥（又名永宁桥）', '石佛桥是一座3孔石拱桥。桥上无栏杆，桥面(3孔拱碹上)为平面，桥堍上是阶梯式坡道。桥面宽4.00米，桥长56.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是燕翅形，前墙长约5.20米。桥墩两段均为尖形，分水尖的上顶很高，拱碹是半圆形纵联分段并列式结构，由8道纵联石和9段拱碹石构成，碹脸外有拱眉石，拱眉凸出于碹脸，又凸出于侧墙。中孔跨径11.00米，边孔跨径10.70米。', '', 11, NULL, NULL, '', 10, 1, 10, 1, '诸暨市枫桥镇石佛村', '石材（料石、纵联石、拱碹石、仰天石、拱眉石）', 50, 214, '2026-04-28 23:07:54', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1287, '崖下桥', '桥面中部高起为平面，桥塊上是阶梯式坡道。桥上无栏杆，两侧各有一道边牙石。桥面宽4.00米，桥长 27.00米。桥台是燕翅形。桥墩两端为尖形。拱碹是半圆形纵联式结构，碹脸与侧墙平。跨径均为9.00米。', '', 11, NULL, NULL, '', 8, 1, 8, 1, '诸暨市马剑村，跨于山涧排水沟上', '石材', 50, 215, '2026-04-28 23:07:54', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1288, '永宁桥', '永宁桥是一座3孔石拱桥。两侧有板式石栏杆。桥面宽4.00米，桥长26.00米。侧墙用料石砌筑，上顶有双层仰天石。桥台燕翅形，前墙长约5.00米。桥墩两端是尖形，中孔跨径11.00米，边孔跨径10.70米。', '', 11, NULL, NULL, '', 10, 1, 10, 1, '诸暨市枫桥镇', '石材、料石', 50, 216, '2026-04-28 23:07:54', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1289, '岙高桥', '岙高桥是一座单孔石拱桥。桥塊和桥面上铺砌不规则石板，无栏杆，桥面宽3.80米，桥长15.00米。无桥台，拱脚砌筑在山脚岩石上，拱碹是类似双抛物线形纵联式结构，跨径9.60米，矢高3.50米。', '', 11, NULL, NULL, '', 10, 1, 10, 1, '台州市天台县湖窦镇，跨山间排水沟上', '石材', 50, 217, '2026-04-28 23:07:54', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1290, '天台岙杨村桥', '岙杨村桥是一座单孔石拱桥。桥塊和桥面上铺砌不规则石板，两侧有节间式石栏杆，无地伏，望柱安装在金边石上，栏板下面有空隙，桥面宽3.90米，桥长24.65米。无桥台，拱碹砌筑在山脚岩石上，是椭圆形变截面纵联式结构，无拱眉。跨径9.60米，矢高3.50米。', '', 11, NULL, NULL, '', 10, 1, 10, 1, '台州市天台县岙杨村，跨山间排水沟上', '石材（不规则石板）', 50, 218, '2026-04-28 23:07:54', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1291, '丰干桥', '桥面为正圆弧形，宽5.00米，桥长18.00米。侧墙是用乱石砌筑的不规则石墙，两端与乱石砌筑的河岸连接。桥台非正式构造，前面宽出拱脚35厘米，拱脚建在乱石砌筑的河岸底部。拱碹是不规则半圆形纵联式结构，用乱石砌筑，无拱眉，碹脸与侧墙平。跨径9.00米。1988年安装节间式石栏杆，每侧有望柱10根，栏板9块，抱鼓石2块，拆去旧边牙石，新配置地伏。', '', 11, NULL, NULL, '', 10, 1, 10, 1, '浙江省台州市天台县国清寺门前', '乱石、石材', 50, 219, '2026-04-28 23:07:54', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1292, '天台灵水桥', '桥上两侧有石板栏杆，桥面全宽 6.80米，净宽5.00米，桥长26.80米。无正规桥台，拱脚砌筑在山脚基岩上，拱碹是圆弧形纵联式结构，无拱眉。跨径19.50米。', '', 11, NULL, NULL, '', 8, 1, 10, 1, '台州市天台县，跨灵溪上', '石材', 50, 220, '2026-04-28 23:07:54', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1293, '灵镇桥', '灵镇桥是一座单孔石拱桥。桥上无栏杆，桥面净宽3.40米，桥长 12.50米。 无正规桥台，拱脚砌筑在山脚基岩上，拱碹是圆弧形纵联式结构， 拱碹厚50厘米，无拱眉。跨径8.00米。', '', 11, NULL, NULL, '', 10, 1, 10, 1, '台州市天台县灵镇村', '石材', 50, 221, '2026-04-28 23:07:54', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1294, '霞光桥', '霞光桥是一座单孔石拱桥。桥面宽4.42米，桥长17.26米。桥面上建有屋。侧墙用料石砌筑，上顶有双层仰天石。桥台是凹字形，前墙长 4.50米。拱碹是半圆形纵联式结构，无拱眉，碹脸与侧墙平。跨径 13.30米。', '', 11, NULL, NULL, '', 8, 1, 8, 1, '温州泰顺县横坑镇华洋村', '料石', 50, 222, '2026-04-28 23:07:54', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1295, '白云桥', '桥面中部(拱顶上)高起为平面，两端是阶梯式坡道。两侧有节间式石栏杆，无地伏，桥栏杆置于仰天石上。桥面宽3.30米，桥长25.30米。侧墙用料石砌筑，上顶有双层仰天石。桥台是凹字形，前墙长3.60米。拱碹是半圆形纵联分段并列式结构，有双线拱眉。跨径12.65米。桥台的侧墙上各有两根桥联柱，上顶皆有勾头石。', '', 11, NULL, NULL, '', 8, 1, 8, 1, '余姚市鹿亭乡中村(古称“白云村”)', '石材（料石）', 50, 223, '2026-04-28 23:07:54', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1296, '渡仙桥', '渡仙桥是一座3孔石板梁桥。桥面宽1.20米，桥长16.00米。桥台是凹字形，桥墩两端是方形，跨径均为4.75米。', '', 11, NULL, NULL, '', 6, 2, 10, 1, '建德市', '石材', 50, 224, '2026-04-28 23:07:54', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1297, '霁玉桥', '桥面是每孔3块石板梁，无栏杆。桥面宽96厘米，桥长28.00米。桥台是凹字形，桥墩两端是方形，桥墩厚1.50米，桥墩长1.00米。跨径3.00米。', '', 11, NULL, NULL, '', 8, 2, 8, 1, '建德市南浦村，跨于排水沟上', '石材', 50, 225, '2026-04-28 23:07:54', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1298, '国界桥', '桥面中部(中孔上)高起为平面，两端(边孔上)为坡面，桥面每孔是3块石板梁，无栏杆，桥面宽1.85米，桥面长13.20米。桥面两端各有5级踏步。桥台是凹字形，用石板垒砌，前墙长约2.50米。桥墩采用两根石柱，上顶架一根帽梁。跨径均为4.40米。在桥墩石柱侧面(桥孔内)雕刻古人像，北边孔内是吴王夫差，南边孔内是越王勾践。', '', 11, NULL, NULL, '', 8, 2, 10, 1, '嘉兴市洪合村，跨九里港上', '石材', 50, 226, '2026-04-28 23:07:54', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1299, '板堰桥', '板堰桥是一座32孔石板梁桥，桥面宽0.90米，桥长115.00米。桥台是燕翅形。桥墩上游端是尖形，下游端是方形，跨径均为2.60米。', '', 11, NULL, NULL, '', 10, 2, 10, 1, '丽水市缙云县仙都景区', '石材', 50, 227, '2026-04-28 23:07:54', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1300, '石笋桥', '石笋桥是一座45孔石板梁桥。桥面是每孔两块石板梁，无栏杆。桥面宽80厘米，桥长72.00米。桥台是用石板砌筑的凹字形构造，桥墩是两块立置的石板，上顶横放一块石板。跨径均为1.60米。', '', 11, NULL, NULL, '', 8, 2, 8, 1, '丽水市缙云县，建在水坝上', '石板', 50, 228, '2026-04-28 23:07:54', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1301, '金银渡桥', '桥面每孔4块石板梁，桥面宽2.50米，桥长24.00米。桥台是凹字形，前墙长2.50米。桥墩用条形石板砌筑，两端是方形，桥墩厚60厘米，桥墩长2.50米，上顶有两层双悬臂石板盖梁，上层盖梁长3.20米。中孔跨径5.00米(五孔跨径之和是23.00米)。', '', 11, NULL, NULL, '', 8, 2, 10, 1, '宁波市北仑区，跨小浃江上', '石板', 50, 229, '2026-04-28 23:07:54', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1302, '福寿桥', '桥面每孔3块石板梁，两侧有板式石栏杆，桥面宽2.20米，桥长11.00米。桥台是凹字形，前墙长2.20米。桥墩是两根方形石柱，上顶架一根扁方形石梁，石梁长3.00米。二柱之间砌筑石板。中孔跨径3.90米，边孔跨径3.55米(三孔跨径之和是11.00米)。', '', 11, NULL, NULL, '', 8, 2, 8, 1, '宁波市江北区跨市河上', '石材', 50, 230, '2026-04-28 23:07:54', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1303, '郭塘桥', '郭塘桥是一座3孔石板梁桥。每孔3块石板梁，桥面宽2.50米，桥全长11.00米。桥台与石砌河岸为一体。桥墩是4根方形石柱，上顶架一根方形帽梁。中孔跨径4.80米，边孔跨径4.00米。', '', 11, NULL, NULL, '', 8, 2, 8, 1, '宁波市江北区慈城镇妙山村，跨郭塘岙上', '石材', 50, 231, '2026-04-28 23:07:54', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1304, '泮池桥', '泮池桥是并排3座各为3孔的石板梁桥。三桥相距4.40米，三桥的结构与形式相同，中孔桥面略高为平面。边桥面为坡面，两侧有板式矮栏杆，中桥桥面宽2.70米，桥长7.00米。边桥桥面宽1.60米，桥长6.50米。桥台设在河岸上，桥墩两端是方形，桥墩厚70厘米，桥墩长2.00米。中孔跨径2.00米，边孔跨径1.45米。', '', 11, NULL, NULL, '', 8, 2, 10, 1, '宁波市江北区慈城镇慈溪学宫前，跨泮池上', '石材', 50, 232, '2026-04-28 23:07:54', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1305, '大涵山桥', '大涵山桥是一座3孔石板梁桥。每孔有石板梁4块，两侧有板式石栏杆。桥面宽2.00米，桥面长15.00米。桥塊上是阶梯式坡道。桥台是凹字形，前墙长2.50米。桥墩是用条形石板砌筑，上顶有一层悬臂盖梁，盖梁宽80厘米，盖梁长2.50米。中孔跨径4.60米，边孔跨径4.00米。', '', 11, NULL, NULL, '', 5, 2, 10, 1, '宁波市鄞州区东吴镇史家湾村', '石板', 50, 233, '2026-04-28 23:07:54', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1306, '德行桥', '德行桥是一座3孔石板梁桥。桥面是3块石板梁，桥塊上各是3级台阶，桥面宽1.70米，桥面长12.00米。桥台与石砌河岸为一体，桥墩两端是方形，中孔跨径4.00米，边孔跨径3.50米。', '', 11, NULL, NULL, '', 8, 2, 8, 1, '宁波市鄞州区下水村', '石材', 50, 234, '2026-04-28 23:07:54', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1307, '宁波渡桥', '鄞镇渡桥是一座3孔石板梁桥。每孔有石板梁4块，两侧有板式石栏杆。桥面宽2.10米，桥梁全长43.00米。桥堍上是坡道。桥台是凹字形，前墙长2.50米。桥墩是用条形石板砌筑，上顶有一层悬臂盖梁，盖梁宽80厘米，盖梁长2.50米。中孔跨径5.50米，边孔跨径4.90米。', '', 11, NULL, NULL, '', 8, 2, 8, 1, '鄞州区和镇海区之间，跨小浃江上', '石板', 50, 235, '2026-04-28 23:07:54', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1308, '舵撞碶桥', '桥面每孔7块石板梁，无栏杆，桥面宽4.50米，桥长14.50米。桥台前墙与石砌河岸为一体。桥墩是3根直立方形石柱，两边各有一根方形斜撑石柱，上顶架设一根方形石帽梁，中孔跨径4.20米，次边孔跨径2.50米，边孔跨径1.50米。', '', 11, NULL, NULL, '', 8, 2, 8, 1, '宁波市鄞州区唐家村', '石材', 50, 236, '2026-04-28 23:07:54', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1309, '宁波府前桥', '府前桥是一座3孔石板梁桥。桥面每孔3块石板梁，石梁厚30厘米，宽约60厘米，长5.10米，桥面宽2.00米，桥长15.50米。桥台的前墙与石砌河岸为一体，桥墩是用条形石板砌筑，石板宽70厘米，石板长2.50米，上游端是尖形，下游端是方形，上顶有一层石板盖梁，盖梁宽80厘米，长3.00米。跨径5.00米。', '', 11, NULL, NULL, '', 8, 2, 8, 1, '宁波市鄞州区东吴镇南村，跨三溪水 (俗称“门前河”)上', '石材（条形石板）', 50, 237, '2026-04-28 23:07:54', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1310, '还金桥', '还金桥是一座单孔石板梁桥。两侧有节间式石栏杆，桥面宽5.80 米，桥面长12.50米。 桥台是凹字形，前墙长5.80米。跨径2.50米。', '', 11, NULL, NULL, '', 8, 2, 8, 1, '宁波市鄞州区北渡村', '石', 50, 238, '2026-04-28 23:07:54', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1311, '浣花桥', '浣花桥是一座3孔石板梁桥。桥面每孔3块石板梁，桥面宽1.50 米，桥长18.00米。桥台前墙与石砌河岸为一体。桥墩用条形石板砌筑，两端是方形，桥墩厚50厘米，桥墩长1.50米，上顶有一层石板盖梁，盖梁长1.90 米。中孔跨径6.00米，边孔跨径5.00米。', '', 11, NULL, NULL, '', 8, 2, 8, 1, '宁波市鄞州区横街镇林村', '石板', 50, 239, '2026-04-28 23:07:54', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1312, '金鸡桥', '金鸡桥是一座6孔石板梁桥。每孔有石板梁4块，石板梁厚35厘米，宽60厘米许，长6.00米，桥面宽2.30米，桥长28.00米。桥台是凹字形，前墙长2.50米。桥墩是用条形石板砌筑，上顶有一层悬臂盖梁，盖梁宽80厘米，盖梁长2.50米。中4孔跨径均为4.50米，边孔跨径4.00米。', '', 11, NULL, NULL, '', 8, 2, 8, 1, '浙江省宁波市鄞州区塘溪镇邹溪村', '石板', 50, 240, '2026-04-28 23:07:54', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1313, '十三洞桥', '十三洞桥是一座13孔石板梁桥。桥面每孔3块石板梁，两侧有石板栏板，石板栏板在石板梁外侧，栏板两端置于桥墩上。桥面净宽1.77米，桥长53.50米。桥台是凹字形。桥墩两端是方形，上顶有一块较长的石板，两端伸出桥面许多，在栏板外边设石挡。跨径均为4.65米。', '', 11, NULL, NULL, '', 8, 2, 8, 1, '宁波市鄞州区董家村', '石材', 50, 241, '2026-04-28 23:07:54', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1314, '听泉桥', '听泉桥原名“北渡桥”。桥面宽2.00米，桥全长20.00米。桥台两侧有燕翅墙，前墙长2.60米。桥墩两端是圆形，桥墩长2.00米，上顶帽梁，帽梁长3.00米。中孔跨径4.00米，边孔跨径2.00米。', '', 11, NULL, NULL, '', 9, 2, 8, 1, '宁波市鄞州区河北渡村，跨南塘河上', '石材', 50, 242, '2026-04-28 23:07:54', '2026-04-28 23:36:27');
