INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1317, '下伞桥', '下伞桥是一座3孔石板梁桥。桥面是3块石板梁，两侧有板式石栏杆，两端是阶梯式坡道，无栏杆，桥面宽2.00米，桥全长20.00米。桥台是凹字形，前墙长2.30米。桥墩是用石板砌筑，两端是圆形，上顶有两层悬臂石盖梁，盖梁宽80厘米，盖梁长2.60米。中孔跨径4.50米，边孔跨径3.00米。', '', 11, NULL, NULL, '', 8, 2, 8, 1, '宁波市鄞州区古林镇张家谭村，建在村前的塘河上', '石材', 50, 245, '2026-04-28 23:07:54', '2026-04-28 23:36:27');
