INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1330, '黄杨桥', '黄杨桥是一座3孔石板梁桥。两侧有节间式石栏杆，桥面宽3.00米，桥面长14.00米，全长18.60米。桥台与石砌河岸为一体。桥墩两端是圆形，跨径均为3.50米。', '', 11, NULL, NULL, '', 5, 2, 5, 1, '余姚市和绍兴市分界处', '石材', 50, 258, '2026-04-28 23:07:54', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1331, '黄竹浦桥', '黄竹浦桥是一座3孔石板梁桥。桥面每孔两块石板梁，桥面宽1.70 米，桥长7.00米。 桥台与石砌河岸为一体。桥墩两端是方形，两个桥墩的厚度不一致。跨径由南向北依次是1.50米、3.00米、1.10米。', '', 11, NULL, NULL, '', 8, 2, 8, 1, '余姚市黄竹浦村', '石材', 50, 259, '2026-04-28 23:07:54', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1332, '积善桥', '积善桥是一座3孔石板梁桥。桥面每孔两块石板，中孔石板梁外侧刻“积善桥”三个大字，无栏杆，桥面宽2.50米，桥面长11.00米。桥台是凹字形。桥墩是由4根方形石柱和一根方形石横梁构成，横梁宽80厘米，横梁长3.00米。中孔跨径4.00米，边孔跨径3.00米。', '', 11, NULL, NULL, '', 10, 2, 10, 1, '余姚市郭塘浦河上', '石材', 50, 260, '2026-04-28 23:07:54', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1333, '双邑桥', '双邑桥是一座3孔石板梁桥。桥面每孔3块石板梁，两侧有节间式石栏杆，桥面宽1.70米，桥长16.50米。桥台与石砌河岸为一体。桥墩两端是圆形，桥墩厚1.10米，桥墩长2.10米，跨径均为4.75米。', '', 11, NULL, NULL, '', 5, 2, 5, 1, '余姚市和绍兴市分界处', '石材', 50, 261, '2026-04-28 23:07:55', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1334, '万安桥', '桥面是5块石板梁，石板梁的两端各有一根方形横置的石梁，横梁外侧各有5块斜撑石板，斜撑石板的下端置于桥台上。桥上两侧有节间式石栏杆，每侧有望柱4根，栏板3块，抱鼓石2块。桥面宽1.80米，桥面长11.40米。桥台与石砌河岸为一体。跨径8.50米。', '', 11, NULL, NULL, '', 8, 2, 8, 1, '余姚市梨洲街道', '石材', 50, 262, '2026-04-28 23:07:55', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1335, '报恩桥', '全桥分为三段，南段是4孔，桥面较低。中段是3孔，桥面较高，桥下可以通行小型船只。东段是5孔，桥面也较低。中间较高的桥面与两端较低的桥面有踏步相连。桥面每孔均系3块石板梁，全桥无栏杆，桥面宽2.00米，桥梁全长35.00米。桥台是凹字形，前墙长约2.50米。桥墩两端是方形，桥墩长约2.50米。', '', 11, NULL, NULL, '', 5, 2, 5, 1, '绍兴市柯桥区三角渡', '石材', 50, 263, '2026-04-28 23:07:55', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1336, '绍兴扁拖闸桥', '扁拖闸桥亦称“扁担闸桥”，实际上是两座桥，东桥称“五眼闸桥”，西桥称“三眼闸桥”，二桥之间有一道石堤。五眼闸桥是一座5孔闸桥合一的石板梁桥。桥面高起为平面，桥堍上是梯道，无栏杆。桥面宽3.90米，桥长19.15米。桥台是凹字形，前墙长3.90米。桥墩两端是方形，桥墩厚数据暂缺，桥墩长3.90米。跨径均为3.75米。', '', 11, NULL, NULL, '', 5, 2, 5, 1, '绍兴市柯桥区', '石材', 50, 264, '2026-04-28 23:07:55', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1337, '红木桥', '今存红木桥是一座3孔石板梁桥。桥面高起为平面，两端的桥塊是阶梯式坡面，在桥塊下面各有一孔方形小跨径洞。桥塊和桥面上两侧有节间式石栏杆，每侧有望柱4根，栏板3块，两端无栏端石。桥面宽5.20米，桥长11.00米。桥台设在料石砌筑的河岸上。中孔跨径6.00米，边孔跨径1.60米。', '', 11, NULL, NULL, '', 5, 2, 5, 1, '绍兴市柯桥区', '石材（石板、料石）', 50, 265, '2026-04-28 23:07:55', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1338, '虹明桥（合义桥）', '虹明桥是一段5孔石板梁桥(中孔桥面较高)、一段4孔石板梁桥和1孔引桥互相垂直对接而成，全桥平面近似“Z”字形。桥面每孔是3块石板梁，两侧有石栏杆，桥面宽1.30米，第一段桥长33.80米，第二段桥长28.0米，引桥长8.00米，桥梁全长69.80米。三桥的桥台全是凹字形，前墙长约2.00米。桥墩的两端也都是方形，桥墩厚1.10米，桥墩长约2.00米。第一段桥的跨径由东往西依次是4.80米、6.00米、8.30米、5.00米、5.20米。第二段桥跨径由北向南依次是3.00米、4.20米、4.20米、4.20米。引桥跨径4.00米。', '', 11, NULL, NULL, '', 8, 2, 5, 1, '浙江省绍兴市柯桥区徐山村', '石材', 50, 266, '2026-04-28 23:07:55', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1339, '画桥', '画桥是一座15孔石板梁桥，由5大孔和10小孔组成。桥面每孔是3块石板梁，两侧有矮石板栏杆。桥面是第一孔较低，第五孔最高，全桥桥面的总坡度是东高西低的坡面。桥面每孔是3块石板梁并排而成，桥面宽2.00米，桥梁全长62.70米。桥台是凹字形，桥墩的两端是方形。桥梁的跨径是，第5孔跨径5.70米，其余各孔跨径均为2.90米。', '', 11, NULL, NULL, '', 8, 2, 5, 1, '绍兴市柯桥区鉴湖古堤上', '石材', 50, 267, '2026-04-28 23:07:55', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1340, '奎元桥', '奎元桥是一座3孔悬臂式石板梁桥。桥面每孔3块石板梁，石梁下面，在桥台和桥墩上各有两层悬臂石板。桥面宽2.00米，桥长18.00米。桥台的前墙与石砌河岸为一体。桥墩两端是尖形，中孔跨径5.00米，边孔跨径3.50米。', '', 11, NULL, NULL, '', 5, 2, 5, 1, '绍兴市柯桥区越联村，跨街河上', '石材', 50, 268, '2026-04-28 23:07:55', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1341, '兰亭桥', '兰亭桥是一座3孔石板梁桥。桥面每孔是一块石板梁，无栏杆。桥面宽1.00米，桥长14.00米。桥西端连接方形亭台。东桥台是凹字形，前墙长1.30米。桥墩是两根方形石柱，上顶横架一根石帽梁。跨径均为3.50米。', '', 11, NULL, NULL, '', 5, 2, 5, 1, '绍兴市柯桥区', '石材', 50, 269, '2026-04-28 23:07:55', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1342, '外山桥', '外山桥是一座单孔特殊券式石梁桥。桥面高起为平面，桥塊上是阶梯式坡道。两侧有板式石栏杆。桥面宽2.75米，净宽2.00米，桥面长2.80米，桥塊长均为3.60米，桥长10.00米。侧墙是用料石砌筑，上顶有单层仰天石。桥孔主体是五边折线形纵联分段并列式框架，由4道纵联石和5段平面石板组成。桥台是凹字形，前墙长3.00米。跨径4.20米。', '', 11, NULL, NULL, '', 5, 2, 5, 1, '绍兴市柯桥区丰二村，跨街河上', '料石、石板', 50, 270, '2026-04-28 23:07:55', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1343, '王七墩庙桥', '王七墩庙桥是一座单孔特殊券式石梁桥，桥面中部高起为平面，两端是阶梯式坡道，无栏杆。桥面宽2.20米，桥长12.00米。侧墙用石板砌筑，上顶有单层仰天石。桥孔主体是由5段并排的5块石板和4根纵联石组成五边形框架。桥台是凹字形，前墙长2.50米。跨径5.20米。', '', 11, NULL, NULL, '', 5, 2, 5, 1, '绍兴市柯桥区王七墩村，跨街河上', '石材', 50, 271, '2026-04-28 23:07:55', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1344, '绍兴纤道桥', '今存纤道桥是一座115孔的石板梁桥，桥面每孔是3块石板梁，桥面宽1.50米，桥梁全长386.20米。桥台是凹字形，前墙长2.00米。桥墩的两端为方形，桥墩厚80—100厘米，桥墩长1.50—2.50米。跨径2.00米。', '', 11, NULL, NULL, '', 8, 2, 5, 1, '绍兴市柯桥区', '石板', 50, 272, '2026-04-28 23:07:55', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1345, '迎恩桥', '迎恩桥是一座单孔特殊券式石梁桥。桥面中部高起为平面，两端是阶梯式坡道，桥上无栏杆。两侧有节间式石栏杆，无地伏，桥栏杆置于仰天石上。桥面宽3.40米，桥长15.00米。侧墙用料石砌筑，上顶有单层仰天石。桥孔主体是由6道纵联石和7段并列平面石板组成七边折线形框架。桥台与石板砌筑的河岸为一体。跨径10.00米。', '', 11, NULL, NULL, '', 7, 2, 5, 1, '绍兴市柯桥区，跨郊区排水沟上', '料石、石板', 50, 273, '2026-04-28 23:07:55', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1346, '禹会桥', '禹会桥是一座3孔石板梁桥，桥面是石板梁，桥面宽3.10米，桥长23.00米。桥台是凹字形，端墙与块石砌筑的河岸连砌在一起，桥墩的两端是方形，用石板砌筑，自下而上逐层有收分。桥台和桥墩上顶各一块石板帽梁，桥墩上顶厚90厘米，桥墩长3.50米。中孔跨径6.60米，边孔跨径4.00米。', '', 11, NULL, NULL, '', 5, 2, 5, 1, '绍兴市柯桥区华张溇村，跨街河上', '石板、块石', 50, 274, '2026-04-28 23:07:55', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1347, '元宝桥 (云梯桥)', '元宝桥是一座单孔撑架式石板梁桥，上部结构是由3段石板(每段5块)和2根方形横系石杆件构成梯形门式结构。桥面高起为平面，桥堍上是阶梯式坡道，两侧有板式石栏杆。桥面宽5.00米，桥面长5.70米，桥梁全长25.00米。桥台是凹字形，用石板砌筑，其后部与石砌河岸相连。跨径7.00米。', '', 11, NULL, NULL, '', 7, 2, 7, 1, '绍兴市柯桥区华张溇村，跨张溇横江上', '石板', 50, 275, '2026-04-28 23:07:55', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1348, '朱公桥', '朱公桥是一座11孔石板梁桥。北段5孔桥面高起，在石板梁外侧有石板栏杆，桥面净宽2.10米。南段6孔桥面较低，在石板梁外侧有石板栏杆，桥面净宽2.10米。桥梁全长51.00米。桥台是凹字形，桥墩两端是方形，北5孔跨径均为3.80米，南6孔跨径均为3.00米。', '', 11, NULL, NULL, '', 7, 2, 7, 1, '绍兴市柯桥区安昌古镇', '石材', 50, 276, '2026-04-28 23:07:55', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1349, '青云桥（又名“玉带桥”）', '桥面中高起为平面，桥堍上是阶梯式坡道。桥面东侧栏杆无存，西侧有石栏杆，石栏板上镌刻“青云”二字。桥面宽4.00米，桥长20.85米。上部结构由5段并排的平面石板和4道纵联石组成，各段石板之间各有一道纵联石，其立面呈五边折线形。桥台与石板砌筑的河岸为一体。跨径4.20米。', '', 11, NULL, NULL, '', 8, 2, 8, 1, '绍兴市上虞区望头村，跨鲤鱼涌上', '石材', 50, 277, '2026-04-28 23:07:55', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1350, '探春桥（亦称“长春桥”）', '探春桥是一座3孔石板梁桥。桥面每孔是3块石板梁，两侧有板式石栏杆，桥面宽2.00米，桥长13.00米。桥台与石砌河岸为一体，桥墩是3块并排竖立的条形石板，上顶有石板盖梁，下面置于石板基础上。跨径4.00米。', '', 11, NULL, NULL, '', 5, 2, 5, 1, '绍兴市上虞区丰贞镇，跨街河上', '石材', 50, 278, '2026-04-28 23:07:55', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1351, '祥麟桥', '西桥塊上无铺装，东桥塊是用乱石砌筑的坡道。上部结构是由5段平面石板和4道纵联石组成，各段石板之间各有一道纵联石，属于纵联分段并列式结构，其立面呈五边折线形。平面石板为桥面，桥上无栏杆。桥面宽2.80米，桥长7.80米。侧墙用乱石砌筑，上顶有一层较厚的仰天石，高出桥面而成边牙石。桥台是凹字形，底部三面有出台，前墙是垂直立于桥台基础上的一排石板，桥台基础仅有两层石板。跨径5.20米，矢高2.60米。', '', 11, NULL, NULL, '', 8, 2, 5, 1, '绍兴市上虞区长溇村，跨于乡间排水沟上', '石材（石板、乱石）', 50, 279, '2026-04-28 23:07:55', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1352, '八字桥', '实际上是由广宁桥和东双桥连接而成。二桥的中心线并不重合，两条中心线折线相交，其平面呈八字形。广宁桥和东双桥均为双孔石板梁桥，结构形式相同，均为一个大孔和一个小孔，两个大孔靠近，两个大孔的桥面高起，两个小孔的桥面较低。全桥无栏杆，桥面宽均为3.20米。桥头皆有阶梯式坡道与河岸上的道路连通。桥台是凹字形，用石板砌筑。桥墩都是用两根板式石柱，上顶横置一块石墩帽。大孔跨径均为4.50米，小孔跨径均为3.00米。', '', 11, NULL, NULL, '', 5, 2, 5, 1, '绍兴市越城区', '石材（石板、板式石柱、石墩帽）', 50, 280, '2026-04-28 23:07:55', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1353, '绍兴拜王桥', '上部结构是由5段石板对接组成的五边折线形构造体，桥面是5块石板梁。石板梁的两端各是6块向内倾斜设置的石板，其下面又是各为5块向内倾斜设置的石板，5段石板之间各有一道纵联石，下段斜置石板的下端置于石板砌筑的河岸上。桥堍上是用石板铺砌的坡道，侧墙用块石砌筑，上顶有一层石板，相当于仰天石。桥面上两侧有青石地伏。桥面宽3.70米，桥面(石板梁)长3.70米，桥堍长均为13.40米，桥长30.00米。跨径4.50米。', '', 11, NULL, NULL, '', 5, 2, 5, 1, '浙江省绍兴市越城区鲁迅西路凰仪桥附近，跨街河上', '石板、块石、青石', 50, 281, '2026-04-28 23:07:55', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1354, '昌安桥', '昌安桥是一座单孔特殊券式石梁桥。桥塊上铺砌不规则石板，桥面高起为平面，桥塊上是阶梯式坡道，两侧桥栏杆无存，青石地伏尚存。桥面宽2.80米，净宽2.00米，桥长12.00米。桥孔主体是五边折线形纵联分段并列式框架，由4道纵联石和5段平面石板组成。侧墙用石板砌筑，上顶有一层仰天石。桥台是凹字形，下部前面和两侧皆有15厘米出台，前墙长3.10米。跨径4.00米，桥台底部间距是3.70米。', '', 11, NULL, NULL, '', 5, 2, 5, 1, '绍兴市越城区跨街河上', '石板、青石', 50, 282, '2026-04-28 23:07:55', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1355, '绍兴大木桥', '今存大木桥是一座3孔石板梁桥。桥塊上横铺条形石板，桥面均为石板梁，两侧有节间式石栏杆，每侧有望柱2根，栏板3块(无端望柱)。桥面宽数据暂缺，桥长数据暂缺。桥台是凹字形，其前墙是采用4块条形石板竖立设置，上顶有石板盖梁，下端置于石板基础上。桥墩全是用条形石板竖立在基石上，上顶横放一块石盖梁。跨径均为5.20米。', '', 11, NULL, NULL, '', 5, 2, 5, 1, '绍兴市越城区东浦镇跨街河上', '石板、条形石板', 50, 283, '2026-04-28 23:07:55', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1356, '广宁桥', '桥孔立面呈七边折线形，桥面中部高起为平面，两端是阶梯式坡道，南坡有16级台阶，北坡有20级台阶。两侧有节间式石栏杆，每侧有望柱6根，栏板5块，栏杆两端与河岸上的栏杆相连。桥面宽5.00米，桥长60.00米。侧墙用料石砌筑，上顶有单层仰天石。上部结构是用5段并排的平面石板和4道纵联石构成，其立面呈五边折线形。桥台是凹字形，前墙长6.00米。跨径6.10米。', '', 11, NULL, NULL, '', 7, 2, 7, 1, '绍兴市越城区跨街河上', '料石、石板', 50, 284, '2026-04-28 23:07:55', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1357, '荷湖桥', '现存荷湖桥是一座14孔石板梁桥。中间的4孔桥面较高，东端的3孔和西端的7孔桥面较低，较高的桥面两端有三级踏步。高桥面的两侧有节间式石栏杆，下面的地伏石宽出桥面。低桥面上无栏杆。桥面宽7.20米，桥长82.30米。桥台是凹字形，用石板砌筑。桥墩的下部用石板砌筑，两端为方形，上部采用4根方形石柱(桥墩两端各两根),上顶盖一块大石板。跨径由北向南依次是3.00米、3.45米、4.00米、5.00米、5.00米、5.00米、5.00米、4.50米、4.00米、4.00米、4.00米、4.00米、4.00米、4.00米。', '', 11, NULL, NULL, '', 8, 2, 8, 1, '绍兴市越城区斗门镇荷湖村', '石板、石柱', 50, 285, '2026-04-28 23:07:55', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1358, '后堡桥', '后堡桥是一座单孔石板梁桥。桥面较高，桥塊为阶梯式坡道，两侧有节间式栏杆，每侧有望柱4根，石栏板3段，地伏石宽出桥面。桥面宽2.00米，桥长12.00米。桥台是凹字形，前墙上横置一块条形石板(台帽),两端伸出石板梁。跨径5.50米。', '', 11, NULL, NULL, '', 5, 2, 5, 1, '绍兴市越城区樊江乡后堡村', '石材', 50, 286, '2026-04-28 23:07:55', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1359, '会龙桥', '会龙桥是一座单孔石板梁桥。桥上两侧有石板栏杆，桥面宽4.00 米，桥长10.00米。上建石柱桥廊。 桥台是凹字形，前墙长4.00米。跨径3.50米。', '', 11, NULL, NULL, '', 5, 2, 5, 1, '浙江省绍兴市越城区，跨街河上', '石材', 50, 287, '2026-04-28 23:07:55', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1360, '龙华桥', '桥面是每孔3块石板梁，桥面宽2.10米，桥长5.50米。桥台是凹字形，用条形石板砌筑，前墙的墙面上竖嵌一块有闸板槽的石板。跨径4.40米。', '', 11, NULL, NULL, '', 7, 2, 5, 1, '绍兴市越城区龙华寺之左', '石板、条形石板', 50, 288, '2026-04-28 23:07:55', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1361, '廿眼桥', '全桥由主桥和引桥以及石堤三部分组成。主桥为双孔石板梁桥，桥面高起为平面，桥堍上是阶梯式坡道。桥面宽1.30米，桥长12.00米。主桥的桥台是凹字形，前墙长1.30米。桥墩两端是方形，桥墩长1.30米。两孔的跨径不相等，大孔跨径5.00米，小孔跨径2.50米。引桥是15孔石板梁桥，桥面低于主桥的桥面，无栏杆，桥面宽1.30米，桥长88.70米。桥台是凹字形，桥墩两端是方形。跨径5.00米。桥梁全长100.70米，石堤长17.20米。', '', 11, NULL, NULL, '', 5, 2, 5, 1, '绍兴市越城区皋埠镇小南池村', '石材', 50, 289, '2026-04-28 23:07:55', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1362, '绍兴三接桥', '三接桥实际上是3座单孔石板梁桥，分别跨于三岔口河道的三股河道上，分别位于三岔口道路上。桥面均为3块石板梁，桥面宽均为2.00米，桥长分别是6.00米、4.50米、8.00米。桥台均为凹字形，三桥的桥墩处于三条河道交汇处中心，三座桥的桥面从中心墩向三个方向伸展，被水阻隔的三地互相连通。此桥的跨径分别是4.00米、2.50米、6.00米。', '', 11, NULL, NULL, '', 5, 2, 5, 1, '浙江省绍兴市越城区凫埠村', '石板', 50, 290, '2026-04-28 23:07:55', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1363, '赏滨桥', '桥塊上铺砌不规则石板，桥面高起为平面，桥塊上是阶梯式坡道，无栏杆，桥面宽4.30米，桥长8.50米。桥孔主体是五边折线形纵联分段并列式框架，由4道纵联石和5段平面石板组成。侧墙是用石板砌筑，上顶有单层仰天石。桥台是凹字形，下部前面和两侧皆有小出台。跨径6.60米。', '', 11, NULL, NULL, '', 5, 2, 5, 1, '绍兴市越城区东浦镇赏滨村，跨街河上', '石材', 50, 291, '2026-04-28 23:07:55', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1364, '汤公桥', '汤公桥又称“三江应宿闸”。桥面是石板梁，桥面宽9.15米，桥长108.00米。桥台是凹字形。桥墩两端是尖形，桥墩厚1.20米，桥墩长9.65米。跨径均为2.50米。原桥现存一半，20世纪50年代改建一半，新老桥合一。', '', 11, NULL, NULL, '', 7, 2, 5, 1, '绍兴市越城区三江古入海口', '石材', 50, 292, '2026-04-28 23:07:55', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1365, '望仙桥', '望仙桥是一座3孔石板梁桥，桥面宽1.90米，桥长19.00米。桥台是凹字形，桥墩两端是方形，桥墩厚80厘米，桥墩长2.00米。跨径5.20米。南宋嘉泰《会稽志》有记载。', '', 11, NULL, NULL, '', 5, 2, 5, 1, '绍兴市越城区', '石材', 50, 293, '2026-04-28 23:07:55', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1366, '蜈蚣桥', '蜈蚣桥又名“万寿福禄桥”，是由万寿桥(西桥)和福禄桥(东桥)之间的一段石堤连接而成，全桥共7孔，桥梁总长(包括石堤10.00米)49.00米。万寿桥是一座5孔石板梁桥，桥面每孔5块石板梁，有节间式石栏杆，桥面宽3.00米。福禄桥是一座双孔石板梁桥，桥面每孔5块石板梁，有节间式石栏杆，桥面宽3.00米。两座桥的桥台都是凹字形，桥墩两端都是方形，桥墩厚80厘米。桥墩长3.50米。跨径均为5.00米。', '', 11, NULL, NULL, '', 9, 2, 5, 1, '绍兴市越城区樊家埭村', '石材（石板、石堤、石墩台）、木材（民国改建桥面）', 50, 294, '2026-04-28 23:07:55', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1367, '咸宁桥', '咸宁桥是一座单孔石板梁桥，桥面是双层石板梁，上层石板梁的侧面刻“咸宁桥”。桥面宽1.00米，桥长5.00米。桥台是凹字形，前墙顶面的石板外露面皆宽出桥面。跨径数据暂缺。', '', 11, NULL, NULL, '', 5, 2, 5, 1, '绍兴市越城蕺山街，跨街河上', '石材', 50, 295, '2026-04-28 23:07:55', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1368, '谢公桥', '桥面中部高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆，无地伏，桥栏杆置于仰天石上。桥面宽3.50米，桥长28.50米。侧墙用料石砌筑，上顶有单层仰天石。桥孔主体由7段并排的石板和6道纵联石组成七边折线形框架。桥台与石板砌筑的河岸为一体。跨径8.00米。', '', 11, NULL, NULL, '', 8, 2, 8, 1, '绍兴市越城区，跨街河上', '石材（料石、石板）', 50, 296, '2026-04-28 23:07:55', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1369, '洋江桥', '洋江桥是由舆龙桥和天佑桥连接而成的一座桥。天佑桥为东桥，舆龙桥为西桥，中间有一段无名桥。舆龙桥是一座3孔石板梁桥，无名桥是4孔石板梁桥，天佑桥是一座5孔石板梁桥。桥面均系每孔4块石板梁，两侧有节间式石栏杆，下面有地伏。桥面宽均为2.20米，桥梁全长99.29米。桥台是凹字形。桥墩两端为方形，上顶有两层帽石，帽石四面出檐，桥墩厚80厘米，桥墩长2.20米。舆龙桥跨径由东向西依次是4.80米、5.40米、5.15米。天佑桥跨径由东向西依次是4.30米、5.25米、7.75米、6.04米、5.12米。', '', 11, NULL, NULL, '', 5, 2, 5, 1, '绍兴市越城区斗门镇洋江村（袍谷洋江村）', '石材', 50, 297, '2026-04-28 23:07:55', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1370, '永嘉桥', '桥面中部高起为平面，两侧有板式栏杆，两端是阶梯式坡道，无栏杆。桥面宽2.50米，桥长23.00米。侧墙用石板砌筑，上顶有单层较厚的仰天石。桥孔主体是五边纵联分段并列式框架，由5段并排的石板和4道纵联石组成。桥台是凹字形，前墙长3.00米。跨径5.50米。', '', 11, NULL, NULL, '', 7, 2, 5, 1, '绍兴市越城区大皋埠村', '石板', 50, 298, '2026-04-28 23:07:55', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1371, '访友桥', '访友桥是一座单孔撑架式石板梁桥。桥面是5块石板梁，石板梁的两端，在桥台前墙上面有5块向内倾斜设置的石板，石板梁与斜置石板之间各有一道纵联石。斜置石板的后面(桥台上)砌筑石板。全桥为平面，无栏杆。桥面宽2.90米，桥长11.00米。桥台是凹字形，用料石砌筑，前墙是5块立置的石板。跨径5.30米。', '', 11, NULL, NULL, '', 10, 2, 10, 1, '嵊州白宅墅村', '石板、料石', 50, 299, '2026-04-28 23:07:55', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1372, '果盒桥', '果盒桥是一座单孔撑架式石板梁桥。桥面是石板梁，石板梁的两端各有一排向内倾斜设置的微弯石板，石板梁与微弯石板之间各有一道纵联石，微弯石板(桥台)的下端置于岩石上。桥面为弧形面，桥堍及桥面上两侧有节间式石栏杆，每侧有望柱4根，栏板3块，抱鼓石2块。桥面宽2.20米，桥长14.30米。桥堍在山脚下河岸上，上面铺筑成缓坡路面。桥台与石砌河岸为一体。跨径7.25米。', '', 11, NULL, NULL, '', 8, 2, 8, 1, '嵊州，跨于山涧之上', '石材', 50, 300, '2026-04-28 23:07:55', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1373, '和尚桥', '桥面是石板梁，无栏杆，桥面宽2.00米，桥面长8.00米。桥台是两段相对斜置(上端向内倾斜)的石板，其下端在山脚岩石上，上端与石板梁对接处有一根纵联石。桥台后面两侧有乱石砌筑的侧墙，上顶有一层石板，如同仰天石。桥堍上铺砌石板是坡道。桥孔的立面呈梯形门式。跨径12.00米。', '', 11, NULL, NULL, '', 8, 2, 8, 1, '嵊州市，跨无名小溪上', '石板、乱石', 50, 301, '2026-04-28 23:07:55', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1374, '嵊州望仙桥 (太平桥)', '望仙桥是一座5孔石板梁桥。桥面每孔是3块石板梁，无栏杆。桥面宽2.00米，桥长35.00米。桥台与石砌河岸为一体，桥墩用石板砌筑，上游端是尖形，下游端是方形，桥墩厚1.10米，桥墩长3.00米。跨径由东向西依次是3.00米、4.20米、4.20米、4.20米、3.00米。', '', 11, NULL, NULL, '', 10, 2, 10, 1, '嵊州三界镇', '石板', 50, 302, '2026-04-28 23:07:55', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1375, '新官桥', '今存新官桥是一座7孔石板梁桥。桥面是石板梁，每孔两块石板梁，无栏杆，桥面宽1.35米，桥长42.00米。桥台与石砌河岸为一体，桥墩上游端为尖形，下游端为方形。跨径均为5.00米。', '', 11, NULL, NULL, '', 10, 2, 10, 1, '嵊州市广利乡新官桥村', '石材', 50, 303, '2026-04-28 23:07:55', '2026-04-28 23:36:27');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1376, '祠堂桥', '桥面每孔3块石板梁，石板梁的两端，各有一对斜撑石板。在桥台上斜撑石板的后面砌筑石板，上面与石板梁平，在桥墩上斜撑石板之间砌筑石板，上面与石板梁平，形成整体桥面。无栏杆。桥面宽1.70米，桥长20.00米。桥台与石砌河岸为一体。桥墩两端是尖形，跨径均为7.00米。', '', 11, NULL, NULL, '', 10, 2, 10, 1, '诸暨市青山乡草塔镇上下文村，跨乡间排水沟上', '石材', 50, 304, '2026-04-28 23:07:55', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1377, '渎溪桥', '渎溪桥是一座3孔撑架式石板梁桥。桥面每孔6块石板梁，石板梁的两端，各有一对斜撑石板，在桥台上斜板石板的后面砌筑石板，上面与石板梁平；在桥墩上斜板石板之间砌筑石板，上面与石板梁平，形成整体桥面。无栏杆，桥面宽3.00米，桥长32.00米。桥台建在山脚下岩石上，只有3层石板砌筑的“一”字形桥台，两边逐层长出约0.30米。桥墩的下部两端为尖形，跨径均为7.10米。', '', 11, NULL, NULL, '', 10, 2, 10, 1, '诸暨市渎溪村，跨乡间排水沟上', '石板', 50, 305, '2026-04-28 23:07:55', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1378, '破溪桥', '破溪桥是一座3孔撑架式石板梁桥。桥面每孔4块石板梁，石板梁的两端，各有一对斜撑石板，在桥台上斜板石板的后面砌筑石板，上面与石板梁平；在桥墩上斜板石板之间砌筑石板，上面与石板梁平，形成整体桥面。无栏杆，桥面宽2.33米，桥长34.00米。桥台建在山脚下岩石上，只有两层石板。桥墩两端为尖形，跨径均为7.50米。', '', 11, NULL, NULL, '', 10, 2, 10, 1, '诸暨市马剑高乡栗六蓬村，跨山涧上', '石板', 50, 306, '2026-04-28 23:07:55', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1379, '青潭桥', '青潭桥是一座4孔撑架式石板梁桥。桥塊在河岸上，桥塊和桥面上全桥为平面。桥面是每孔3块石板梁，石板梁的下面，在桥台前的上面有一排斜撑石板，在桥墩上面两边各有一排斜撑石板。桥墩上面两边斜撑石板之间用石板砌筑。桥上无栏杆，桥面宽1.70米，桥面长10.80米，桥长27.00米。桥台是用3层石板砌筑在山脚下岩石上，大致呈凹字形，前墙长约2.30米。桥墩是用石板砌筑，下部两端为尖形，跨径均为6.60米。', '', 11, NULL, NULL, '', 10, 2, 10, 1, '诸暨市吴子里村，跨山涧上', '石板', 50, 307, '2026-04-28 23:07:55', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1380, '上新桥', '桥面每孔是4块石板梁，中孔的石板梁为平面，石梁长4.10米，石板梁的两端各有一排斜撑石板，石板梁与斜撑石板之间各有一道纵联石。两边孔石板梁的外端稍低 (搭在河岸岩石上), 因而两边孔的石板梁为坡面，石梁长2.80米。桥面宽2.28米，桥面长13.80米，桥梁全长14.70米。边孔石板梁的外端搭在山脚岩石上，斜撑石板的下端置于山脚岩石上，跨径4.10米。', '', 11, NULL, NULL, '', 10, 2, 10, 1, '诸暨市青山乡杨焕村，跨于乡间排水沟上', '石材', 50, 308, '2026-04-28 23:07:55', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1381, '溪缘桥', '溪缘桥是一座15孔等跨径撑架式石板梁桥。桥面每孔5块石板梁，全桥为平面，无栏杆。桥面宽2.50米，桥长155.00米。上部结构是由3段并排的5块石板组成，中段石板为桥面，两端各是并排的5块斜撑石板，斜撑石板的下端置于桥墩上。在桥墩上两段斜撑石板之间砌筑石板，上面与石板梁齐平。桥台是凹字形。桥墩两端是方形。跨径均为6.25米。', '', 11, NULL, NULL, '', 10, 2, 10, 1, '诸暨市五泄区柱山乡，跨五泄江上', '石材', 50, 309, '2026-04-28 23:07:55', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1382, '岩下桥', '桥面是4块石板梁，石板梁两端各有4块斜撑石板，石板梁与斜撑石板之间各有一道纵联石。斜撑石板的下端置于山脚岩石上，斜撑石板的上面是用石板砌筑的阶梯式坡道。桥面宽1.50米，桥长14.00米。桥孔立面呈梯形门式。跨径6.50米。', '', 11, NULL, NULL, '', 8, 2, 8, 1, '诸暨市栗树坪村，跨乡间山涧溪流上', '石板', 50, 310, '2026-04-28 23:07:55', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1383, '银河桥', '银河桥是一座3孔撑架式石板梁桥。桥塊上横向铺砌石板，桥塊两侧是用不甚规则的石板砌筑的侧墙，上顶有一层矩形断面的仰天石。桥面每孔是4块石板梁，石板梁的两端各有4块并排的斜撑石板，石板梁与斜撑石板对接处各有一道纵联石。桥台上斜撑石板后面砌筑石板，上面横铺石板，两侧是用石板砌筑的侧墙。桥墩上斜撑石板之间砌筑石板，上面横铺石板。桥上两侧有节间式石栏杆，桥面宽5.50米，桥长41.60米。桥台是凹字形，端墙外有燕翅墙。桥墩的下部两端均为尖形，上部的两端是方形，跨径均为7.20米。', '', 11, NULL, NULL, '', 10, 2, 10, 1, '诸暨市', '石板', 50, 311, '2026-04-28 23:07:55', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1384, '天台西溪桥', '今存西溪桥是一座11孔石板梁桥。桥面每孔有4块石板梁，无栏杆，桥面宽1.60—1.70米，桥长44.00米。桥台是凹字形，前墙长1.80米。桥墩两端是方形，桥墩厚数据暂缺，桥墩长1.80米。跨径(桥墩中—中)3.90—4.10米。', '', 11, NULL, NULL, '', 5, 2, 10, 1, '台州市天台县湖窦镇', '石材', 50, 312, '2026-04-28 23:07:55', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1385, '白沙桥', '白沙桥是一座单孔石拱桥。桥面上为平面，铺砌石板，两侧有板式石栏杆，桥塊上是阶梯式坡道，桥面宽5.60米，桥面长15.70米。', '', 17, NULL, NULL, '', 8, 1, 8, 1, '咸宁市咸安区桂花镇白沙村，在万寿桥与刘家桥之间', '石材（块石）、砖、木', 50, 51, '2026-04-28 23:07:55', '2026-04-28 23:36:21');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1386, '金龙桥', '金龙桥是一座单孔石拱桥。桥面上铺砌石板，略显弧形，两侧有板式石栏杆，桥面宽3.00米，桥面长8.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台建在山脚基岩上，不规整。拱碹是半圆形纵联式结构，无拱眉，碹脸与侧墙平。跨径4.00米。', '', 17, NULL, NULL, '', 8, 1, 8, 1, '赤壁市中伙铺镇长山村，跨凉湖支流上', '石板、料石', 50, 52, '2026-04-28 23:07:55', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1387, '济川桥', '济川桥是一座单孔石拱桥。桥面中部是平面，两侧有节间式石栏杆，两端是阶梯式坡道，无栏杆。桥面宽4.60米，桥长16.10米，侧墙用料石砌筑，上顶无仰天石。桥台是凹字形，前墙长4.60米。拱碹是半圆形纵联式结构，无拱眉，碹脸与侧墙平。跨径5.50米。', '', 17, NULL, NULL, '', 8, 1, 8, 1, '广东省江门市蓬江区棠下镇中心村陈田围', '青石板、块石', 50, 53, '2026-04-28 23:07:55', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1388, '寅宾桥', '寅宾桥是一座单孔石拱桥。桥塊和桥面上横向铺砌条形石板，全桥为平面，两侧有节间式石栏杆，桥面宽5.80米，桥全长50.20米。侧墙用料石砌筑，上顶无仰天石。桥台是凹字形，前墙长7.00米。拱碹是半圆形纵联式结构，无拱眉，碹脸与侧墙平。跨径12.70米。', '', 17, NULL, NULL, '', 8, 1, 8, 1, '恩施土家族苗族自治州巴东县东濂口镇绿竹筏村，跨韩家河上', '条形石板、料石', 50, 54, '2026-04-28 23:07:55', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1389, '丰乐桥', '丰乐桥是一座单孔石拱桥。桥塊和桥面上铺砌石板，略显弧形面，无栏杆。桥面宽6.00米，桥全长24.30米。侧墙用料石砌筑，上顶有单层仰天石。桥台两侧有燕翅墙，前墙长7.20米。拱碹是半圆形纵联式结构，无拱眉，碹脸与侧墙平。跨径6.72米。', '', 17, NULL, NULL, '', 8, 1, 7, 1, '恩施土家族苗族自治州恩施市高桥坝村跨巴公溪上', '石材（料石、石板）', 50, 55, '2026-04-28 23:07:55', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1390, '恩施老拱桥', '老拱桥是一座单孔石拱桥。桥面为平面，桥塊上是阶梯式坡道，无栏杆。桥面宽4.30米，桥全长27.00米。侧墙用块石砌筑，上顶无仰天石。桥台前墙与石砌河岸连接。拱碹是半圆形纵联式结构，无拱眉，碹脸与侧墙平。跨径10.00米。', '', 17, NULL, NULL, '', 10, 1, 10, 1, '恩施土家族苗族自治州恩施市芭蕉乡，在龙滨桥下游，跨马鹿河上', '块石', 50, 56, '2026-04-28 23:07:55', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1391, '龙滨桥', '龙滨桥是一座单孔石拱桥。桥面上铺砌石板略显弧形面，无栏杆。桥面宽5.60米，桥全长32.20米。侧墙用料石砌筑，上顶有单层仰天石。桥台两侧有燕翅墙，前墙长6.80米。拱碹是半圆形纵联式结构，无拱眉，碹脸与侧墙平。跨径10.80米。', '', 17, NULL, NULL, '', 8, 1, 8, 1, '恩施土家族苗族自治州恩施市芭蕉乡芭蕉河村马鹿河上', '石材（石板、料石）', 50, 57, '2026-04-28 23:07:55', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1392, '九峰桥', '九峰桥是一座单孔石拱桥，桥塊和桥面上铺砌石板，全桥桥面略显弧形，两侧有板式石栏杆，桥面宽4.00米，桥长25.10米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长约4.00米。拱碹是半圆形纵联式结构，有拱眉，拱眉凸出于碹脸，拱眉与侧墙平。跨径6.00米。', '', 17, NULL, NULL, '', 8, 1, 8, 1, '恩施土家族苗族自治州鹤峰县容美镇张家村，跨深潭溪上', '石板、料石', 50, 58, '2026-04-28 23:07:55', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1393, '南村桥', '南村桥是一座单孔石拱桥。桥面上铺砌石板为平面，无栏杆，桥堍上是阶梯式坡道。桥面宽2.60米，桥长5.20米。侧墙用料石砌筑，上顶有单层仰天石。桥台建在山脚岩石上，不规整。拱碹是半圆形纵联式结构，无拱眉，碹脸与侧墙平。跨径4.00米。', '', 17, NULL, NULL, '', 8, 1, 8, 1, '恩施土家族苗族自治州鹤峰县五里乡南村让口河上', '石材（料石、石板）', 50, 59, '2026-04-28 23:07:55', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1394, '鹤峰三多桥', '三多桥又名“龚家桥”。桥是一座单孔石拱桥，桥塊和桥面上铺砌石板，全桥桥面略显弧形，两侧有板式石栏杆，桥面宽3.10米，桥长7.80米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，下部前面和两边有出台，前墙长3.10米，下部长约3.70米。拱碹是半圆形纵联式结构，有拱眉，拱眉凸出于碹脸，拱眉与侧墙平。跨径4.60米。', '', 17, NULL, NULL, '', 8, 1, 8, 1, '恩施土家族苗族自治州鹤峰县铁炉乡江口村，跨龚家溪上', '石板、料石', 50, 60, '2026-04-28 23:07:55', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1395, '四里潭桥', '四里潭桥是一座单孔石拱桥。桥塊和桥面上铺砌石板，全桥桥面略显弧形，两侧有板式石栏杆，桥面宽4.80米，桥长14.80米。侧墙用料石砌筑，上顶有单层仰天石。桥台与石砌河岸为一体。拱碹是半圆形纵联式结构，有拱眉，拱眉凸出于碹脸，拱眉与侧墙平。跨径8.80米。', '', 17, NULL, NULL, '', 8, 1, 8, 1, '恩施土家族苗族自治州鹤峰县铁炉乡唐家村，跨溇水支流上', '石板、料石', 50, 61, '2026-04-28 23:07:55', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1396, '安乐桥', '安乐桥是一座单孔石拱桥，桥面为弧形，无栏杆，桥面宽5.10米，桥长8.00米。侧墙用块石砌筑，上顶有单层仰天石。无正规桥台，拱脚落在山崖岩石上。拱碹是半圆形纵联式结构，有拱眉，拱眉凸出于碹脸，拱眉与侧墙平。跨径6.80米。', '', 17, NULL, NULL, '', 8, 2, 8, 1, '黄冈市罗田县骆驼坳镇界河村北200米', '石材', 50, 62, '2026-04-28 23:07:55', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1397, '通济桥', '通济桥是一座单孔石拱桥。桥面为平面，桥塊上是阶梯式坡道，无栏杆，桥面宽3.50米，桥长17.00米。侧墙用块石砌筑，上顶有单层仰天石。无桥台拱脚落在山崖岩石上。拱碹是半圆形纵联式结构，有拱眉，拱眉凸出于碹脸，拱眉与侧墙平。跨径7.00米。', '', 17, NULL, NULL, '', 10, 1, 10, 1, '恩施土家族苗族自治州建始县高坪镇石门河谷上', '石材（块石）', 50, 63, '2026-04-28 23:07:55', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1398, '瓦子院桥', '瓦子院桥是一座单孔石拱桥。桥面为弧形，无栏杆，桥面宽3.00 米，桥长16.00米。 侧墙用块石砌筑，上顶无仰天石。桥台即是山崖岩石。拱碹是半圆 形纵联式结构，无拱眉，碹脸与侧墙平。跨径6.00米。', '', 17, NULL, NULL, '', 8, 1, 8, 1, '恩施土家族苗族自治州建始县长梁乡瓦子院村，跨盛竹河支流上', '石材（块石）', 50, 64, '2026-04-28 23:07:55', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1399, '万寿桥', '万寿桥是一座单孔石拱桥。桥面为弧形，无栏杆，桥塊上是阶梯式坡道。桥面宽5.65米，桥长54.40米。侧墙用料石砌筑，上顶有单层仰天石。桥台建在山脚岩石上，不规整。拱碹是半圆形纵联式结构，无拱眉，碹脸与侧墙平。跨径7.80米。', '', 17, NULL, NULL, '', 8, 2, 8, 1, '孝感市孝昌县周巷镇燎原村，跨无名小河上', '石材', 50, 65, '2026-04-28 23:07:55', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1400, '一阳桥', '一阳桥是一座单孔石拱桥。桥塊和桥面上铺砌不规则石板，全桥略显弧形，两侧有板式石栏杆，桥面宽3.40米，桥全长26.00米。侧墙用料石砌筑，上顶单层仰天石。桥台是凹字形，前墙长3.40米。拱碹是半圆形纵联式结构，无拱眉，碹脸与侧墙平。跨径6.80米。', '', 17, NULL, NULL, '', 8, 1, 8, 1, '恩施土家族苗族自治州建始县官店镇雅池坝村，跨金家河上', '石材（不规则石板、料石）', 50, 66, '2026-04-28 23:07:55', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1401, '广福桥', '广福桥是一座两孔不等跨石拱桥(东孔跨径大，西孔跨径小)。桥堍和桥面上铺砌石板，因为两孔的拱顶高程不同，桥面纵断面呈反正弧形，两侧有垛口式石栏杆。桥面宽4.30米，桥梁全长47.00米。侧墙用料石砌筑，无仰天石。东桥台的前墙与石砌河岸为一体，西桥台是凹字形，前墙长约4.30米。桥墩两端是方形，东孔拱碹是圆弧形纵联式结构，有拱眉，拱眉凸出于碹脸，拱眉与侧墙平。东孔跨径16.00米。西孔的拱碹是半圆形纵联式结构，有拱眉，拱眉凸出于碹脸，拱眉与侧墙平。西孔跨径14.50米。', '', 17, NULL, NULL, '', 10, 1, 10, 1, '恩施土家族苗族自治州来凤县三胡乡石桥村，跨山间小河上', '石板（桥堍和桥面）、料石（侧墙）', 50, 67, '2026-04-28 23:07:55', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1402, '霁虹桥', '今存霁虹桥是同在一条路上的两座单孔石拱桥，二桥之间有一段石堤，二桥相距约40米。二桥的结构形式相同，桥面略显圆弧形，无栏杆。东桥长29.00米，西桥长24.00米，二桥总长(包括石堤) 85.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台均为凹字形。拱碹均系圆弧形镶边纵联式结构，碹脸外边有拱眉石，拱眉与侧墙平。东桥跨径15.00米，西桥跨径10.00米。', '', 17, NULL, NULL, '', 8, 1, 10, 1, '恩施土家族苗族自治州来凤县，跨老虎洞河上', '石料（料石）', 50, 68, '2026-04-28 23:07:55', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1403, '接龙桥', '接龙桥是一座双孔不等跨石拱桥。东孔跨径较大，西孔跨径较小，因为两孔分别跨于同一河道的两条分岔上，两孔之间有一段石堤，石堤侧面有上下桥的阶梯。桥塊和桥面上铺砌石板，全桥为平面，两侧有节间式石栏杆。桥面宽5.30米，桥梁全长80.45米。侧墙用料石砌筑，上顶有单层仰天石。大孔的外桥台与石砌河岸为一体，内侧桥台是凹字形，小孔的两个桥台是凹字形，前墙长约5.50米。拱碹均系半圆形纵联式结构，大孔的龙门上有石雕龙头，小孔的龙门上无龙头，皆有拱眉，拱眉凸出于碹脸，拱眉与侧墙平。大孔跨径15.00米，小孔跨径10.00米。', '', 17, NULL, NULL, '', 10, 1, 10, 1, '恩施土家族苗族自治州来凤县翔凤镇，跨南拦河上', '石板、料石', 50, 69, '2026-04-28 23:07:55', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1404, '步青桥', '步青桥是一座单孔石拱桥。桥面为平面，无栏杆。桥面宽3.00米，桥长10.00米。侧墙用块石砌筑，上顶有单层仰天石。桥台前墙与石砌河岸连接。拱碹是半圆形纵联式结构，无拱眉，碹脸与侧墙平。跨径8.80米。', '', 17, NULL, NULL, '', 8, 1, 10, 1, '恩施土家族苗族自治州利川市毛坝乡双泉村，跨太平河支流上', '石材（块石）', 50, 70, '2026-04-28 23:07:55', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1405, '福寿桥（又名“永兴桥”）', '福寿桥是一座单孔石拱桥。桥面为平面，桥塊上是阶梯式坡道，两侧有板式石栏杆。桥面宽4.80米，桥全长7.60米。侧墙用块石砌筑，上顶有单层仰天石。桥台前墙与石砌河岸连接。拱碹是半圆形纵联式结构，拱碹厚40厘米，无拱眉，碹脸与侧墙平。跨径6.50米。', '', 17, NULL, NULL, '', 8, 1, 8, 1, '湖北省恩施土家族苗族自治州利川市忠路镇老屋基村，跨木坝河上', '石材', 50, 71, '2026-04-28 23:07:55', '2026-04-28 23:36:20');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1406, '康济桥', '康济桥是一座双孔石拱桥，桥塊和桥面上铺砌石板为平面，两侧有铁栏杆，桥面宽5.40米，桥长30.00米。侧墙用块石砌筑，上顶有单层仰天石。桥台的前墙与石砌河岸相连。桥墩两端是方形，拱碹是半圆形纵联式结构，无拱眉，碹脸与侧墙平。跨径7.60米。', '', 17, NULL, NULL, '', 8, 1, 8, 1, '恩施土家族苗族自治州利川市汪营镇大跳墩村，跨清江河上', '石材（块石、石板）、铁（栏杆）', 50, 72, '2026-04-28 23:07:55', '2026-04-28 23:36:20');
