INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1427, '飞虹桥', '飞虹桥原名“道源桥”。桥面为平面，无栏杆。桥上建有砖木结构廊，两端有门楼。桥面宽5.16米，桥长33.65米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长5.20米。拱碹是半圆形纵联式结构，碹脸外边有拱眉石，拱眉凸出于碹脸，拱眉与侧墙平。跨径12.60米。', '', 17, NULL, NULL, '', 8, 1, 8, 1, '湖北省黄冈市黄梅县，跨于无名沟渠上', '石材（料石）、砖木（廊）', 50, 93, '2026-04-28 23:07:55', '2026-04-28 23:36:20');
