INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1445, '荆门来龙桥', '来龙桥是一座单孔石拱桥。桥面为圆弧形，有块石砌筑的宇墙式栏杆，桥面宽9.50米，桥长16.20米。侧墙用块石砌筑，上顶无仰天石，侧墙与桥栏杆为同一墙面。桥台是凹字形，前墙长约10.00米。拱碹是半圆形纵联式结构，碹脸外边有拱眉，拱眉凸出于碹脸，拱眉与侧墙平。跨径8.60米。', '', 17, NULL, NULL, '', 8, 1, 8, 1, '荆门市东宝区龙泉公园内，跨竹碧河上', '块石', 50, 111, '2026-04-28 23:07:55', '2026-04-28 23:36:21');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1446, '清水桥', '清水桥是一座单孔石拱桥。桥面为圆弧形，无栏杆，桥面宽3.00 米，桥长15.00米。 侧墙用料石砌筑，上顶有双层仰天石。桥台是凹字形，前墙长3.00 米。拱碹是半圆形纵联式结构，碹脸外边有拱眉，拱眉凸出于碹脸，拱 眉与侧墙平。跨径5.15米。', '', 17, NULL, NULL, '', 8, 1, 8, 1, '荆门市东宝区龙泉公园内，跨文明湖汉上', '石材（料石）', 50, 112, '2026-04-28 23:07:55', '2026-04-28 23:36:21');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1447, '文运福桥', '文运福桥是一座3孔石拱桥。桥面略显弧形，两侧有花墙式石栏杆，桥面宽6.80米，桥长31.50米。侧墙用料石砌筑，上顶有单层仰天石。桥台两侧有燕翅墙，前墙长8.00米。桥墩上游端是尖形，下游端是方形，拱碹是半圆形纵联式结构，碹脸外边有拱眉，拱眉凸出于碹脸，拱眉与侧墙平。中孔跨径6.20米，边孔跨径5.75米。', '', 17, NULL, NULL, '', 8, 1, 10, 1, '荆门市东宝区龙泉街，跨竹碧河上', '料石', 50, 113, '2026-04-28 23:07:55', '2026-04-28 23:36:21');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1448, '仙弈桥', '仙弈桥是一座单孔石拱桥。桥面略显弧形，无栏杆，桥面宽4.50 米，桥长18.00米。 侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长约 4.50米。拱碹是半圆形纵联式结构，无拱眉，碹脸与侧墙平。跨径 3.80米。', '', 17, NULL, NULL, '', 7, 1, 7, 1, '荆门市监利县棋盘村，跨无名小河上', '料石', 50, 114, '2026-04-28 23:07:55', '2026-04-28 23:36:21');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1449, '丽阳桥', '丽阳桥是一座3孔石拱桥。桥面为弧形，无栏杆，桥面宽68厘米，桥长16.50米。侧墙用块石砌筑，上顶有单层仰天石。桥台的前墙与河岸石墙为一体。拱碹是半圆形纵联式结构，无拱眉。中孔跨径4.23米，边孔跨径3.48米。', '', 17, NULL, NULL, '', 8, 1, 8, 1, '钟祥市丽阳村，跨丽水上', '块石', 50, 115, '2026-04-28 23:07:55', '2026-04-28 23:36:21');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1450, '利涉桥', '利涉桥是一座单孔石拱桥。桥面略显弧形，无栏杆，两侧各有一道边牙石，桥面宽6.80米，桥长22.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长约6.80米。拱碹是三心圆弧形(俗称“鸭蛋形”)纵联式结构，有3层拱眉(也可能是拱碹加强层), 碹脸与侧墙平。跨径7.24米。', '', 17, NULL, NULL, '', 8, 1, 8, 1, '湖北省钟祥市元佑路，跨龟鹤池与宫塘之间渠道上', '料石', 50, 116, '2026-04-28 23:07:55', '2026-04-28 23:36:21');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1451, '显陵桥', '显陵桥是3座并排的3孔石拱桥。结构与形式相同，桥塊和桥面上铺砌长方形石板，桥面均为圆弧形，两侧有节间式白石栏杆，每侧8根望柱，7块栏板。中桥的栏端是1只石雕蹲兽，边桥的栏端是抱鼓石。中桥的桥面宽6.40米，边桥的桥面宽4.40米，桥长均为14.60米。侧墙用料石砌筑，上顶有单层仰天石。桥台是带燕翅形，中桥前墙长7.60米，边桥前墙长5.60米。桥墩两端是尖形。拱碹是镶边纵联式结构，碹脸外缘錾出拱眉线，拱眉凸出于侧墙。中孔跨径3.50米，边孔跨径3.00米。', '', 17, NULL, NULL, '', 7, 1, 10, 1, '钟祥市城东皇陵内，皇陵前御道上，跨于陵前玉带河上', '长方形石板、白石、料石', 50, 117, '2026-04-28 23:07:55', '2026-04-28 23:36:21');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1452, '梅槐桥', '梅槐桥是一座3孔石拱桥。桥面呈正圆弧竖曲线，两侧有节间式石栏杆，倭瓜形柱头，实体栏板，栏板上雕刻人物、花鸟、云龙图案，无地伏，桥栏杆置于仰天石上。桥面宽5.40米，桥长33.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长5.40米。桥墩上游端是尖形，下游端是方形，拱碹是圆弧形纵联式结构，中孔碹脸龙门上有伸出较长的龙头，碹脸外有拱眉石，拱眉与侧墙取平。中孔跨径6.60米，边孔跨径5.50米。', '', 17, NULL, NULL, '', 8, 1, 8, 1, '湖北省荆州市荆州区太湖港河上（南通荆江大堤）', '石材（料石）', 50, 118, '2026-04-28 23:07:55', '2026-04-28 23:36:21');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1453, '万福桥', '万福桥是一座单孔石拱桥。桥面上铺砌石板，中部为平面，两端是坡道，无栏杆，桥面宽4.00米，桥长8.00米。侧墙用块石砌筑，上顶有单层仰天石。桥台建在山脚岩石上，不规整。拱碹是半圆形纵联式结构，无拱眉，碹脸与侧墙平。跨径4.60米。', '', 17, NULL, NULL, '', 8, 1, 8, 1, '随州市曾都区王家畈村，跨椒藤河上', '石材（石板、块石）', 50, 119, '2026-04-28 23:07:55', '2026-04-28 23:36:21');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1454, '神农架一心桥', '一心桥是一座单孔石拱桥。桥面中部为平面，两端是阶梯式坡道，无栏杆，桥面宽3.80米，桥长8.00米。侧墙用块石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长5.00米。拱碹是半圆形纵联式结构，有拱眉，碹脸、拱眉与侧墙平。跨径3.50米。', '', 17, NULL, NULL, '', 8, 1, 8, 1, '神农架林区宋洛乡蛇草坪村', '石、块石', 50, 120, '2026-04-28 23:07:55', '2026-04-28 23:36:21');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1455, '天津桥（又名剑河桥）', '桥面高程是海拔355.80米。桥面为穹隆形，两侧有节间式石栏杆，每侧有望柱22根，均系桃形柱头，栏板21块，均为寻杖下镂空式，两端是抱鼓石。其中，桥身上有望柱18根，栏板17块，桥塊上的八字栏杆，各有望柱2根，栏板2块，抱鼓石1块。柱头是桃形，栏板是寻杖下镂空式。下面有矩形断面的地伏石。桥面宽9.42米，桥长52.10米。侧墙用料石砌筑，上顶有单层仰天石，每隔一块仰天石，伸出一个方形装饰勾头石。桥台是带燕翅形，前墙长10.60米。桥墩上游端是尖形，下游端是方形，拱碹是半圆形镶边纵联式结构，碹脸外边有拱眉石，拱眉凸出于碹脸，又凸出于侧墙。中孔跨径9.60米，边孔跨径6.70米。', '', 17, NULL, NULL, '', 6, 1, 10, 1, '丹江口市武当山九渡涧上', '石材（料石）', 50, 121, '2026-04-28 23:07:55', '2026-04-28 23:36:21');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1456, '复真桥', '复真桥是一座单孔石拱桥。桥塊和桥面上铺砌青石板，全桥为弧形桥面，两侧有节间式石栏杆。桥面宽4.00米，桥长22.00米。侧墙用块石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长4.00米。拱碹是半圆形纵联式结构，有拱眉，拱眉凸出于碹脸，拱眉与侧墙平。跨径10.00米。', '', 17, NULL, NULL, '', 4, 1, 4, 1, '丹江口市武当山景区内，跨山涧小溪上', '青石板、块石', 50, 122, '2026-04-28 23:07:55', '2026-04-28 23:36:21');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1457, '金仙桥（又名“摘星桥”）', '金仙桥是一座单孔石拱桥。桥塊和桥面上铺砌石板，全桥为弧形桥面，两侧有节间式石栏杆。桥面宽3.90米，桥长9.70米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长3.90米。拱碹是半圆形纵联式结构，有拱眉，碹脸、拱眉与侧墙平。跨径6.40米。', '', 17, NULL, NULL, '', 8, 1, 8, 1, '丹江口市武当山下', '石板、料石', 50, 123, '2026-04-28 23:07:55', '2026-04-28 23:36:21');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1458, '天津桥（剑河桥）', '天津桥是一座3孔石拱桥。桥塊和桥面上铺砌石板，全桥为弧形桥面，两侧有节间式石栏杆。桥面宽9.42米，桥长52.10米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长9.40米，端墙外端有燕翅墙。桥墩两端是尖形，拱碹是半圆形纵联式结构，有双层拱眉，拱眉凸出于碹脸，拱眉与侧墙平。中孔跨径9.20米，边孔跨径6.70米。', '', 17, NULL, NULL, '', 7, 1, 7, 1, '丹江口市武当山景区内，跨山涧小溪上', '石板、料石', 50, 124, '2026-04-28 23:07:55', '2026-04-28 23:36:21');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1459, '正门桥', '正门桥是一座单孔石拱桥。桥塊和桥面上铺砌石板，全桥为弧形桥面，两侧有节间式石栏杆。桥面宽4.00米，桥长16.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长4.00米。拱碹是半圆形镶边纵联式结构，有拱眉，拱眉凸出于碹脸，拱眉与侧墙平。跨径6.50米。', '', 17, NULL, NULL, '', 8, 1, 8, 1, '丹江口市武当山紫霄宫正门外，跨护宫河上', '石板、料石', 50, 125, '2026-04-28 23:07:55', '2026-04-28 23:36:21');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1460, '渡春桥', '渡春桥是一座单孔石拱桥。桥面上铺砌青石板为弧形，桥塊上是阶梯式坡道，两侧有节间式石栏杆。桥面宽4.00米，桥长20.00米。侧墙用块石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长4.00米。拱碹是半圆形纵联式结构，无拱眉，碹脸与侧墙平。跨径10.00米。', '', 17, NULL, NULL, '', 8, 1, 8, 1, '十堰市郧西县原城关镇直峪河上', '青石板、块石', 50, 126, '2026-04-28 23:07:55', '2026-04-28 23:36:21');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1461, '竹山长寿桥', '长寿桥是一座单孔石拱桥。桥塊和桥面上铺砌石板，全桥为弧形桥面，两侧有节间式石栏杆。桥面宽9.00米，桥长31.00米，两端各有引道20.00米，桥全长71.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长9.00米。拱碹是半圆形纵联式结构，龙门上有石雕龙头，有拱眉，拱眉凸出于碹脸，拱眉与侧墙平。跨径8.30米。', '', 17, NULL, NULL, '', 8, 1, 8, 1, '十堰市竹山县得胜镇大桥村', '石板、料石', 50, 127, '2026-04-28 23:07:55', '2026-04-28 23:36:21');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1462, '广水马坪桥（会馆桥）', '马坪桥是一座单孔石拱桥，桥塊和桥面上铺砌青石板，桥面略显弧形，两侧有节间式石栏杆。桥面宽3.35米，桥长14.30米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长约3.35米。拱碹是半圆形纵联式结构，有拱眉，拱眉凸出于碹脸，拱眉与侧墙平。跨径4.83米。', '', 17, NULL, NULL, '', 8, 1, 8, 1, '广水市马坪镇，跨府河支流上', '青石板、料石', 50, 128, '2026-04-28 23:07:55', '2026-04-28 23:36:21');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1463, '平靖关桥', '平靖关桥是一座3孔石拱桥。桥塊和桥面上铺砌青石板，全桥为平面，两侧有节间式石栏杆。桥面宽5.00米，桥长18.50米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长约500米。桥墩两端是方形，拱碹是半圆形纵联式结构，有拱眉，拱眉凸出于碹脸，拱眉与侧墙平。中孔跨径4.10米，边孔跨径4.00米。', '', 17, NULL, NULL, '', 8, 1, 8, 1, '广水市蔡河镇平靖关村，跨三潭河上', '青石板、料石', 50, 129, '2026-04-28 23:07:55', '2026-04-28 23:36:21');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1464, '马燕坳桥', '马燕坳桥是一座单孔石拱桥。桥面上铺砌条形石板，两侧有板式石栏杆。桥面宽3.00米，桥面长15.00米。拱碹是半圆形镶边纵联式结构，无拱眉，碹脸稍后退于侧墙。跨径 7.60米。', '', 17, NULL, NULL, '', 8, 1, 8, 1, '随州市曾都区洛阳镇易家湾村，跨紫金河上', '石材', 50, 130, '2026-04-28 23:07:55', '2026-04-28 23:36:21');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1465, '平安桥', '平安桥是一座单孔石拱桥。桥塊和桥面铺砌条形石板，两侧有节间式石栏杆。桥面宽3.50米，桥面长9.00米。侧墙用块石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长350 米。拱碹是半圆形纵联式结构，无拱眉，碹脸与侧墙平，跨径6.00米。主拱碹两端各有一个小孔洞，拱碹是圆弧形纵联式结构，无拱眉，碹脸与侧墙平，跨径3.50米。', '', 17, NULL, NULL, '', 8, 1, 8, 1, '随州市曾都区淅河镇白龙港村，跨白龙港河上', '条形石板、块石', 50, 131, '2026-04-28 23:07:55', '2026-04-28 23:36:21');
