INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1487, '仙桃万寿桥', '万寿桥是一座7孔等跨径石拱桥。桥面是平面，两侧有砖栏杆，桥面宽5.00米，桥面净宽2.50米，桥长90.00米。侧墙用乱石砌筑，上顶有单层仰天石。桥台是燕翅形，前墙长6.20米。桥墩上游端是尖形，下游端是方形，拱碹是半圆形纵联式结构，中孔龙门上有石雕龙头，碹脸外边有拱眉，拱眉凸出于碹脸，拱眉与侧墙平。跨径10.00米。', '', 17, NULL, NULL, '', 8, 1, 8, 1, '湖北省仙桃市皂市镇长汀河上', '石、砖、乱石', 50, 153, '2026-04-28 23:07:55', '2026-04-28 23:36:21');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1488, '七宝桥', '七宝桥是一座单孔石拱桥。桥塊和桥面上铺砌石板，全桥为平面，无栏杆，桥面宽8.50米，桥面长27.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长8.50米，端墙很长。拱碹是半圆形纵联式结构，有拱眉，拱眉突出于碹脸，拱眉与侧墙平。跨径4.00米。', '', 17, NULL, NULL, '', 8, 1, 8, 1, '赤壁市茶庵岭镇七宝桥村，跨无名小河上', '石板、料石', 50, 154, '2026-04-28 23:07:55', '2026-04-28 23:36:21');
