INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1504, '崇阳斤丝桥', '斤丝桥是一座单孔石拱桥。桥面中部为弧形，两端是阶梯式坡道，桥面宽3.60米，桥长11.20米。侧墙用块石砌筑，上顶有单层仰天石。桥台用料石砌筑在山脚岩石上，形式不规整。拱碹是半圆形纵联式结构，无拱眉，碹脸与侧墙平。跨径6.30米。', '', 17, NULL, NULL, '', 8, 1, 8, 1, '咸宁市崇阳县桂花泉镇双港村，跨虎爪河上', '石材（块石、料石）', 50, 170, '2026-04-28 23:07:55', '2026-04-28 23:36:21');
