INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1506, '净堡桥', '净堡桥是一座单孔石拱桥。桥塊和桥面上铺砌青石板，桥面为弧形，两侧有石板栏杆，桥塊上为平面，无栏杆，桥面宽4.00米，桥长60.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长4.00米，端墙很长。拱碹是半圆形纵联式结构，有拱眉，拱眉凸出于碹脸，拱眉与侧墙平。跨径8.00米。', '', 17, NULL, NULL, '', 8, 1, 8, 1, '咸宁市嘉鱼县渡普镇烟墩静宝村', '青石板、料石', 50, 172, '2026-04-28 23:07:55', '2026-04-28 23:36:21');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1507, '温家桥', '温家桥是一座单孔石拱桥。桥面为平面，两侧有石板桥栏杆，桥面宽3.00米，桥长10.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长约3.00米。拱碹是半圆形纵联式结构，无拱眉，碹脸与侧墙平。跨径6.00米。', '', 17, NULL, NULL, '', 8, 1, 8, 1, '咸宁市嘉鱼县官桥镇温家村，跨舒桥港上', '石材（料石）', 50, 173, '2026-04-28 23:07:55', '2026-04-28 23:36:21');
