INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1517, '宋家祠桥', '宋家祠桥是一座3孔石拱桥。桥面是圆弧形，无栏杆。桥面宽5.20米，桥长24.50米。侧墙用料石砌筑，上顶有单层仰天石。桥台是带燕翅形，前墙长6.40米。桥墩上游端是尖形，下游端是方形，拱碹是圆弧形纵联式结构。跨径5.80米。', '', 17, NULL, NULL, '', 8, 1, 8, 1, '咸宁市通山县', '石材（料石）', 50, 183, '2026-04-28 23:07:55', '2026-04-28 23:36:21');
