INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1564, '孝感埠镇桥', '埠镇桥是一座3孔石拱桥。桥塊和桥面上铺砌青石板，桥面略显弧形，两侧有节间式石栏杆，桥面宽6.00米，桥长39.00米。侧墙用块石砌筑，上顶有单层仰天石。桥台两侧有燕翅墙，前墙长约7.20米。桥墩上游端是尖形，下游端是方形。拱碹是半圆形纵联式结构，有拱眉，拱眉凸出于碹脸，拱眉与侧墙平。中孔跨径6.00米，边孔跨径4.80米。', '', 17, NULL, NULL, '', 8, 1, 8, 1, '孝感市孝南区三汉镇三汊埠，跨三汊河上', '青石板（桥塊和桥面）、块石（侧墙）', 50, 230, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
