INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1586, '屈子桥', '屈子桥是一座单孔石拱桥。桥面为平面，两侧有节间式石栏杆，无地伏，桥栏杆置于仰天石上。桥面宽3.60米，桥长13.30米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长3.60米。拱碹是半圆形纵联式结构，有拱眉，碹脸、拱眉与侧墙平。跨径6.70米。', '', 17, NULL, NULL, '', 8, 1, 8, 1, '宜昌市秭归县屈原镇西陵村，跨无名小溪上', '料石', 50, 252, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1587, '升仙桥', '升仙桥是一座单孔石拱桥。桥面略显弧形，两侧有板式石栏杆，桥面宽10.50米，桥长13.60米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长约10.50米。拱碹是半圆形纵联式结构，无拱眉，碹脸与侧墙平。跨径7.56米。', '', 17, NULL, NULL, '', 8, 1, 8, 1, '钟祥市龙山，跨越山冲上', '料石', 50, 253, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1588, '石板滩桥', '石板滩桥原是一座10孔石墩台石板梁桥。桥面是石板梁，桥面宽1.00米，桥长35.00米。侧墙是用块石砌筑，上顶有单层仰天石。桥台两侧有燕翅墙。桥墩两端是尖形，桥墩厚2.50米，桥墩长3.00米。跨径均为2.80米。今存石板滩桥，是在石板梁桥上面加筑石拱，拱碹是圆弧形纵联式结构，无拱眉。桥面为平面，两侧有铁栏杆。', '', 17, NULL, NULL, '', 8, 1, 8, 1, '湖北省恩施土家族苗族自治州利川市凉雾乡双井村跨清江河上', '石材（块石、石板）、铁（栏杆）', 50, 254, '2026-04-28 23:07:55', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1589, '红安陡山湾桥', '陡山湾桥是一座4孔石板梁桥。桥面每孔3块石板梁，桥面宽1.20米，桥面长30.50米。桥台用料石砌筑，两侧有八字墙，前墙长约1.20米。桥墩是用料石砌筑，两端是方形，跨径均为6.00米。', '', 17, NULL, NULL, '', 8, 2, 8, 1, '黄冈市红安县八里湾镇中和村，跨倒河上', '料石', 50, 255, '2026-04-28 23:07:55', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1590, '红安回龙寨桥', '回龙寨桥是一座3孔石板梁桥。桥面每孔3块石板梁，桥面宽1.50米，桥梁全长26.30米。桥台两侧有燕翅墙，用料石砌筑，前墙长约2.00米。桥墩是用料石砌筑，两端是尖形，跨径均为6.50米。', '', 17, NULL, NULL, '', 8, 2, 10, 1, '黄冈市红安县太平桥乡回龙寨村，跨倒水河上', '石板梁、料石', 50, 256, '2026-04-28 23:07:55', '2026-04-28 23:36:28');
