INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1592, '罗堰畈桥', '罗堰畈桥是一座双孔石板梁桥。桥面每孔2块石板梁，桥面宽1.50米，桥面长13.50米。桥台用料石砌筑，两侧有八字墙，前墙长约2.60米。桥墩是用料石砌筑，两端是尖形，大孔跨径5.00米，小孔跨径1.10米。', '', 17, NULL, NULL, '', 8, 2, 8, 1, '黄冈市红安县七里坪镇盐店河村，跨倒河上', '料石、石板', 50, 258, '2026-04-28 23:07:55', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1593, '谢家大湾桥', '谢家大湾桥是一座6孔石板梁桥。桥面每孔3块石板梁，桥面宽1.60米，桥面长27.00米。桥台用料石砌筑，燕翅形，前墙长2.00米。桥墩是用料石砌筑，两端是尖形，桥墩厚0.90米，桥墩长2.00米。跨径均为3.60米。', '', 17, NULL, NULL, '', 8, 2, 8, 1, '黄冈市红安县八里湾镇许家田村', '料石、石板', 50, 259, '2026-04-28 23:07:55', '2026-04-28 23:36:28');
