INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1595, '姚八斗桥', '姚八斗桥是一座6孔石板梁桥。桥面每孔5块石板梁，两侧各有一道边牙石。桥面宽2.19米，净宽1.75米，桥梁全长35.00米。桥台两侧有燕翅墙，用料石砌筑，前墙长约2.20米。桥墩是用料石砌筑，上游端是尖形，下游端是方形，上顶有一层长方形石板，桥墩厚0.90米，桥墩长2.60米。跨径均为4.20米。20世纪90年代，将旧桥的桥台和桥墩加高，桥台前墙上和桥墩上各设一根石板盖梁。上面架设混凝土板梁。', '', 17, NULL, NULL, '', 7, 2, 10, 1, '湖北省黄冈市红安县太平桥乡栋津桥村，跨倒流河支流上', '石板、料石、混凝土', 50, 261, '2026-04-28 23:07:55', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1596, '红安姚家桥', '姚家桥是一座8孔石板梁桥。桥面每孔3块石板梁，桥面宽1.20米，桥面长39.00米。桥台用料石砌筑，两侧有八字墙，前墙长约1.50米。桥墩是用料石砌筑，两端是尖形，桥墩长1.60米。跨径均为3.20米。今存姚家桥，已将桥面加高、加宽。', '', 17, NULL, NULL, '', 8, 2, 10, 1, '湖北省黄冈市红安县八里湾镇许家田村，跨倒河上', '料石、石板', 50, 262, '2026-04-28 23:07:55', '2026-04-28 23:36:28');
