INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1629, '刘家寨桥', '刘家寨桥是一座5孔石板梁桥。桥面每孔4块石板梁，石板梁厚35厘米，桥面宽1.80米，桥全长17.50米。桥台是凹字形，前墙长2.00米。桥墩两端是方形，桥墩厚90厘米，桥墩长2.00米。跨径均为3.50米。', '', 17, NULL, NULL, '', 8, 2, 8, 1, '孝感市云梦县曾店镇刘寨村，跨女儿港支流上', '石材', 50, 295, '2026-04-28 23:07:55', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1630, '毛公桥', '毛公桥是一座4孔石拱与石梁混合结构桥。东边孔是石拱桥，桥面中部(拱顶上)高起为平面，两侧有石板栏杆，两端是阶梯式坡道，坡道上无栏杆。桥面宽5.00米，桥长约28.00米。侧墙用块石砌筑，上顶有单层仰天石。桥台是凹字形。拱碹是半圆形纵联式结构，无拱眉。跨径14.80米。其余3孔是石板梁桥，桥上无栏杆。桥面宽2.50米，桥长约30.00米。桥台是凹字形，桥墩上游端是尖形，下游端是方形，桥墩厚90厘米，桥墩长6.00米。跨径6.00—8.00米。', '', 18, NULL, NULL, '', 8, 1, 8, 1, '宁乡市巷子口镇谷石村(今改称直田村)跨沩水河上', '石材（块石、石板）', 50, 51, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1631, '吴杨桥（又名“芙蓉桥”）', '吴杨桥是一座单孔石拱桥。桥面铺砌花岗岩石板，略显弧形，无栏杆。桥面宽4.70米，桥长27.80米。侧墙用块石砌筑。桥台用块石砌筑，大致是凹字形。拱碹是半圆形纵联式结构，无拱眉。跨径15.50米。', '', 18, NULL, NULL, '', 8, 1, 8, 1, '湖南省长沙市长沙县金井镇涧山村，跨金井河上', '花岗岩石板、块石', 50, 52, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1632, '多安桥', '桥面上铺砌青石板，桥面稍显圆弧形，纵坡度1%。两侧有节间式石栏杆，下面有青石地伏。桥面全宽8.70米，净宽7.70米，桥长198.00米。侧墙用料石砌筑，上顶有单层仰天石组成的金边线，桥台是凹字形，前墙长8.70米。桥墩的两端是尖形，四周宽出拱脚，两端的上部是锥体，桥墩厚1.25米，桥墩长9.30米。拱碹是三心圆弧形(顶部是小圆弧形，两侧是大圆弧形)纵联式结构，碹脸外边有拱眉石，拱眉凸出于碹脸，拱眉与侧墙平。各孔跨径依次是9.50米、10.00米、10.40米、11.00米、11.00米、11.00米、11.00米、11.00米、10.40米、10.00米、9.50米。', '', 18, NULL, NULL, '', 8, 1, 8, 1, '常德市澧县城东门外，跨澧水上', '青石板、料石', 50, 53, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1633, '花瓦桥', '现存花瓦桥是一座3孔石拱桥。桥塊和桥面铺砌条形石板为平面，两侧有节间式石栏杆，每侧有16根望柱，15块栏板，2块抱鼓石。柱头是桃形，栏板是实体板。桥面宽5.30米，桥长30.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长5.30米，端墙的端部与石板砌筑的河岸连砌为一体。桥墩属于薄型，两端为方形，桥墩厚75厘米，桥墩长5.30米。拱碹是半圆形纵联分段并列式结构，碹脸外边有拱眉石，拱眉凸出于碹脸，又凸出于侧墙。中孔跨径7.50米，边孔跨径5.00米。', '', 18, NULL, NULL, '', 4, 1, 4, 1, '常德市澧县宜万乡花瓦村，跨于湘鄂两省分界河上', '条形石板、料石', 50, 54, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1634, '松竹桥', '松竹桥又名“嵩祝桥”。桥面中部(拱顶上)高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆。桥面宽8.00米，桥长37.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形。拱碹是半圆形纵联分段并列式结构，拱眉凸出于碹脸，拱眉与侧墙平。跨径 18.00米。', '', 18, NULL, NULL, '', 8, 1, 8, 1, '常德市澧县火连坡镇松竹村，跨涔水河上', '料石', 50, 55, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1635, '余市桥', '余市桥是一座9孔石拱桥。桥面上铺砌青石板，桥面为平面，两侧有节间式青石栏杆及青石地伏。桥面宽9.00米，桥长83.30米。桥上建砖木结构廊26楹。侧墙用料石砌筑，上顶有单层仰天石。桥台是燕翅形，前墙长10.20米。桥墩的上游端是尖形，下游端是方形，桥墩厚1.40米，桥墩长10.60米。拱碹是半圆形镶边纵联式结构，碹脸外边有拱眉石，拱眉凸出于碹脸，又凸出于侧墙。跨径4.70米。', '', 18, NULL, NULL, '', 8, 1, 8, 1, '湖南省常德市临澧县余市桥镇，跨澧水支流道水上', '青石板、料石、砖木', 50, 56, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1636, '桂阳七拱桥（又名“永济桥”）', '桥面为平面，铺砌花岗岩石板，两侧有节间式石栏杆，望柱与栏板同高，栏板高60厘米，厚20厘米。桥面宽10.00米，桥梁全长146.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台两侧有燕翅墙，前墙长11.20米。桥墩上游端是方形，下游端是尖形，拱碹是半圆形纵联式结构，碹脸外边有拱眉石，拱眉凸出于碹脸，又凸出于侧墙。跨径均为16.60米。', '', 18, NULL, NULL, '', 7, 1, 7, 1, '郴州市桂阳县春陵江门下渡，跨春陵江上', '花岗岩石板、料石', 50, 57, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1637, '嘉禾桐梁桥', '今存桐梁桥是一座3孔石拱桥。桥塊和桥面上铺砌青石板，无栏杆，桥面平。桥面宽5.40米，桥长35.20米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，端墙与河岸石墙连砌为一体，前墙长5.40米。桥墩两端与拱脚齐平，桥墩厚1.20米，桥墩长5.40米。拱碹是半圆形纵联分段并列式结构，碹脸外边有拱眉石，拱眉凸出于碹脸，拱眉又凸出于侧墙。跨径均为8.00米。', '', 18, NULL, NULL, '', 8, 1, 10, 1, '郴州市嘉禾县行廊镇沙坪村，跨芹溪河上', '青石板、料石', 50, 58, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1638, '汝城四拱桥', '桥塊和桥面上铺砌青石板，无栏杆，桥面平，桥面宽5.60米，桥梁全长63.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长5.60米。桥墩两端是方形，两端与拱脚取齐，桥墩厚3.00米，桥墩长5.60米。拱碹是半圆形纵联式结构，无拱眉。跨径均为10.50米。', '', 18, NULL, NULL, '', 8, 1, 8, 1, '湖南省郴州市汝城县城西，跨浙水河上', '青石板（桥塊和桥面）、料石（侧墙）', 50, 59, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1639, '万年桥', '万年桥是一座5孔等跨径石拱桥。桥塊和桥面上铺砌青石板，全桥为平面，无栏杆。桥面宽5.50米，桥长80.60米。侧墙用块石砌筑，上顶有单层仰天石。桥台是凹字形，用块石砌筑。桥墩两端是尖形，桥墩厚1.50米，桥墩长7.40米。拱碹是半圆形纵联式结构，无拱眉。跨径均为13.50米。', '', 18, NULL, NULL, '', 8, 1, 8, 1, '郴州汝城县暖水镇双联村，跨沤江上', '青石板（桥塊和桥面）、块石（侧墙、桥台）', 50, 60, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1640, '兴隆桥', '兴隆桥是一座单孔石拱桥。桥塊和桥面上铺砌花岗岩石板。无栏杆，桥面宽3.50米，桥长17.00米。侧墙用花岗岩石板砌筑，上顶有单层仰天石。桥台前墙与石砌河岸为一体。拱碹是半圆形纵联式结构，无拱眉。跨径5.00米。', '', 18, NULL, NULL, '', 8, 1, 8, 1, '郴州市汝城县小垣瑶族镇后洞村', '花岗岩石板', 50, 61, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1641, '万岁桥', '全桥用青石料砌筑，桥塊和桥面上铺砌青石板，桥面为平面，两侧有板式石栏杆。桥面宽5.10米，桥长21.50米。侧墙用青石板砌筑，上顶有单层仰天石。桥台是凹字形，前墙长5.10米。桥墩上游端是尖形，尖端的上部直达金边线。下游端是方形。拱碹是半圆形纵联式结构，无拱眉。跨径均为3.00米。', '', 18, NULL, NULL, '', 8, 1, 10, 1, '郴州北湖区石盖塘镇万寿桥村', '青石料、青石板', 50, 62, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1642, '衡山白果桥', '原有白果桥是一座9孔石拱桥。桥面上铺砌红砂岩石板，大致是平面，桥面原宽7.00米，桥长102.40米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长约7.00米。桥墩两端是方形，拱脚以下四周有出台，桥墩厚1.80米，桥墩长7.00米。拱碹是半圆形纵联式结构，碹脸外边有拱眉石，碹脸、拱眉与侧墙平。各孔跨径稍有出入，最大跨径9.20米，最小跨径8.60米。', '', 18, NULL, NULL, '', 7, 1, 10, 1, '衡阳市衡山县白果镇跨涓水上', '红砂岩石板、料石、混凝土', 50, 63, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1643, '祁东清江桥（又名“七拱桥”）', '清江桥是一座7孔石拱桥。桥塊和桥面上铺砌红砂岩石板，全桥为平面，两侧有石板栏杆。桥面宽7.00米，桥梁全长84.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形。桥墩两端是方形，桥墩厚1.20米，桥墩长7.50米。拱碹是半圆形纵联式结构，无拱眉。跨径均为7.00米。', '', 18, NULL, NULL, '', 8, 1, 10, 1, '衡阳市祁东县城连圩乡锡坪村，跨清江上', '红砂岩石板、料石', 50, 64, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1644, '祁东状元桥（又名归阳桥）', '状元桥是一座5孔等跨径石拱桥。桥塊和桥面上铺砌条形石板，桥面宽8.00米，桥长80.00米。桥上建砖木结构廊。侧墙用块石砌筑，上顶有单层仰天石。桥台是燕翅形，前墙长9.00米。桥墩两端是尖形，桥墩厚1.30米，桥墩长9.30米。拱碹是半圆形纵联式结构。跨径12.00米。', '', 18, NULL, NULL, '', 8, 1, 10, 1, '湖南省衡阳市祁东县归阳镇，跨白河入湘江之汇合口', '石材（条形石板、块石）、砖木（桥廊）', 50, 65, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1645, '衡阳青草桥', '青草桥原是一座8孔石拱桥。桥堍和桥面上铺砌青石板，两侧有节间式石栏杆。今存桥是7孔，桥面是弧形，两侧有铁栏杆。桥面宽10.00米，桥长166.35米。侧墙用料石砌筑，上顶有单层仰天石。桥台前墙与石砌河岸为一体，桥墩两端是圆形，桥墩厚2.10米，桥墩长11.60米。拱碹是圆弧形纵联式结构，无拱眉。跨径均为15.00米。', '', 18, NULL, NULL, '', 8, 1, 8, 1, '湖南省衡阳市城北，跨湘江支流蒸水河上', '青石板、料石、铁', 50, 66, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1646, '台源桥（紫霞桥）', '台源桥是一座7孔石拱桥。桥塊和桥面上铺砌红砂岩石板，全桥为平面，两侧有石板栏杆。桥面宽7.00米，桥长120.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形。桥墩两端是方形，桥墩厚1.20米，桥墩长7.50米。拱碹是半圆形纵联式结构，无拱眉。跨径14.00米。', '', 18, NULL, NULL, '', 8, 1, 8, 1, '衡阳市台源镇台源村', '红砂岩石板（桥塊和桥面）、料石（侧墙）', 50, 67, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1647, '桂花桥', '桂花桥是一座3孔石拱桥，桥面宽3.20米，桥长43.40米。桥上建砖木结构廊和亭15间。侧墙用块石砌筑，上顶有单层仰天石。桥台是凹字形，前墙及下部用石料砌筑，上部用砖材砌筑，前墙长3.20米。桥墩下部用石料砌筑，上部用砖材砌筑，两端是方形，桥墩厚1.40米，桥墩长3.80米。跨径均为10.00米。', '', 18, NULL, NULL, '', 8, 1, 8, 1, '怀化市靖州县寨牙乡芳团村', '块石、石料、砖材、木材', 50, 68, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1648, '马王桥（通济桥）', '桥面上铺砌不规则青石板，两边的边牙石上凿有流水槽，无栏杆。桥面宽5.40米，桥长31.00米。侧墙用块石砌筑，上顶有单层较厚的仰天石，上面高出桥面，成为边牙石。桥台与弧形石砌河岸为一体。拱碹是半圆形纵联分段并列式结构(拱碹石很短)，有拱眉，拱眉凸出于碹脸，拱眉与侧墙平。跨径14.00米。', '', 18, NULL, NULL, '', 8, 1, 8, 1, '怀化市靖州苗族侗族自治县城南门外', '青石板、块石', 50, 69, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1649, '通道普济桥', '普济桥是一座单孔石拱桥。桥面宽3.80米，桥全长31.40米。桥上建悬梁穿斗式木构架廊。侧墙用块石砌筑，上顶有单层仰天石。桥台是燕翅形，前墙长约5.00米。拱碹是半圆形纵联式结构，无拱眉。跨径19.80米。', '', 18, NULL, NULL, '', 8, 1, 8, 1, '湖南省怀化市通道侗族自治县坪坦乡坪坦村，跨坪坦河上', '块石、木材', 50, 70, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1650, '永定桥', '桥面宽3.55米，桥全长26.40米。桥上建穿斗式木构架廊。侧墙用块石砌筑，上顶有单层仰天石。桥台是燕翅形，前墙长约4.70米。跨径15.30米。', '', 18, NULL, NULL, '', 8, 1, 8, 1, '怀化市通道侗族自治县坪坦乡高团村', '块石、木材', 50, 71, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1651, '渡头桥', '今存渡头桥是一座3孔石拱桥。桥塊和桥面上铺砌花岗岩石板，全桥为平面，两侧有板式石栏杆，桥面宽6.00米，桥长45.00米。侧墙用花岗岩石板砌筑，上顶有单层仰天石。桥台是凹字形，前墙长6.00米。桥墩两端是方形，桥墩厚1.50米，桥墩长6.60米。拱碹是半圆形镶边纵联式结构，有拱眉，拱眉凸出于碹脸，拱眉与侧墙平。跨径8.50米。', '', 18, NULL, NULL, '', 8, 1, 10, 1, '武冈市渡头桥镇渡头村', '花岗岩石板', 50, 72, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1652, '溆浦万寿桥', '万寿桥是一座3孔石拱桥。桥面宽4.00米，桥长72.00米。桥上建砖木结构廊。侧墙用料石砌筑，上顶有单层仰天石。桥台是燕翅形，前墙长5.20米。桥墩两端是尖形，跨径均为17.50米。', '', 18, NULL, NULL, '', 8, 1, 8, 1, '怀化市溆浦县黄茅园镇万寿村及湾潭村之间，跨龙潭河上', '料石、砖、木', 50, 73, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1653, '耍溪桥', '桥面中部高起为平面，两端是坡道。无栏杆，无边牙石。桥面宽6.70米，桥长40.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长6.70米。端墙端部有八字石墙。拱碹是半圆形纵联式结构，碹脸外边有拱眉石，拱眉凸出于碹脸，又凸出于侧墙。跨径10.00米。', '', 18, NULL, NULL, '', 8, 1, 8, 1, '怀化市沅陵县盘古乡跳岩村，跨沅江支流耍溪溪口上', '料石', 50, 74, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1654, '新安桥', '新安桥是一座单孔石拱桥。桥塊和墙面上铺砌红砂岩石板。桥面宽 4.50米，桥长19.00米。桥上建木结构廊。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长4.50 米。拱碹是半圆形纵联式结构，碹脸外边有拱眉。跨径数据4.60米。', '', 18, NULL, NULL, '', 8, 1, 10, 1, '浏阳市社港镇新安村', '红砂岩石板、青石板、料石、木材', 50, 75, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1655, '沿溪桥', '沿溪桥是一座7孔石拱桥。桥塊和桥面铺砌条形石板，全桥为平面，两侧有石栏杆。桥面宽5.00米，桥长66.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是燕翅形。桥墩两端是尖形，桥墩厚1.80米，桥墩长7.20米，拱碹是半圆形纵联式结构，拱眉凸出于碹脸，拱眉与侧墙平。跨径约6.00米。', '', 18, NULL, NULL, '', 8, 1, 8, 1, '浏阳市跨大光河上', '条形石板、料石', 50, 76, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1656, '大埠桥（又名“永济桥”）', '桥塊和桥面上铺砌青石板，桥面(三孔拱碹上)是平面，两端是阶梯式坡道。桥面两端中间的石板上，雕有一个圆形云龙图案。两侧有板式石栏杆(最长的一块条石长7.00米),中间的一块栏板上刻“永济桥”三个大字。栏杆端部各有一个大狮子。桥面宽6.00米，桥长56.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长6.00米。桥墩两端是方形，桥墩厚约3.00米，桥墩长6.00米。拱碹是半圆形纵联式结构，碹脸外边有拱眉石，拱眉凸出于碹脸，又凸出于侧墙。跨径均为12.20米。', '', 18, NULL, NULL, '', 8, 1, 8, 1, '娄底市城区东部，跨山间排水沟上', '青石板、料石', 50, 77, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1657, '蓝溪桥', '今存蓝溪桥是一座3孔石拱桥。两侧有节间式石栏杆(望柱与栏板高度相同),无地伏，桥栏杆置于仰天石上。桥面宽7.80米，桥长33.40米。侧墙用料石砌筑，上顶有单层仰天石。桥台前墙与石砌河岸为一体。桥墩上游端是尖形，下游端是方形，桥墩厚1.40米，桥墩长9.00米。拱碹是半圆形分段并列式结构，碹脸外边有较窄的拱眉石，拱眉凸出于碹脸，与侧墙平，跨径均为9.50米。', '', 18, NULL, NULL, '', 8, 1, 10, 1, '涟源市蓝溪镇，跨涟水河上', '石材（料石）', 50, 78, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1658, '双峰定胜桥', '今存定胜桥是一座5孔石拱桥。桥塊和桥面上铺砌青石板，桥面平。两侧有节间式石栏杆(局部损坏)。桥面宽8.00米，桥长50.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长8.00米。桥墩两端是尖形，拱碹是半圆形纵联分段并列式结构，无拱眉。跨径均为5.60米。', '', 18, NULL, NULL, '', 8, 1, 10, 1, '湖南省娄底市双峰县永丰镇，跨湄水河支流测水河上', '青石板、料石', 50, 79, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1659, '龟灵桥', '今存龟灵桥是一座单孔石拱桥。桥面中部(桥孔上)是平面，两端是阶梯式坡道。无栏杆。桥面宽5.50米，桥长35.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长5.50米。拱碹是圆弧形纵联式结构，无拱眉，跨径15.00米。', '', 18, NULL, NULL, '', 8, 1, 8, 1, '娄底市双峰县洪山殿镇龟灵村，跨崖凉河上', '料石', 50, 80, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1660, '峡山桥', '峡山桥是一座单孔石拱桥。桥面略显圆弧形，两侧各有一道用两层石板砌筑的护栏。桥面宽3.50米，桥长6.50米。侧墙用块石砌筑，上顶有单层仰天石。桥台为凹字形，前墙长3.50米。拱碹为半圆形纵联式结构，用片石砌筑，无拱眉，碹脸与侧墙平。跨径4.00米。', '', 18, NULL, NULL, '', 8, 1, 8, 1, '娄底市双峰县峡山村', '石板、块石、片石', 50, 81, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1661, '咸新桥', '咸新桥是一座单孔石拱桥。桥面略显圆弧形，两侧各有一道用两层石板砌筑的护栏。桥面宽3.00米，桥长8.00米。侧墙用块石砌筑，上顶有单层仰天石。桥台也用块石砌筑，为凹字形，前墙长3.00米。拱碹是半圆形纵联式结构，用片石砌筑，无拱眉，碹脸与侧墙平。跨径5.00米。', '', 18, NULL, NULL, '', 8, 1, 8, 1, '娄底市双峰县', '石材（块石、石板、片石）', 50, 82, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1662, '新化油溪桥', '油溪桥原名“横溪桥”。该桥是一座单孔石拱桥，桥面上铺砌不规则石板，无栏杆。桥面宽8.00米，桥长33.00米。侧墙用不规则石板砌筑，上顶有单层仰天石，仰天石略高出桥面。桥台是凹字形，前墙长8.00米。拱碹是半圆形纵联式结构，拱碹厚70厘米，有拱眉，拱眉凸出于碹脸，拱眉与侧墙齐平。跨径28.00米。', '', 18, NULL, NULL, '', 8, 1, 8, 1, '娄底市新化县晨光乡跨油溪河上', '石材（不规则石板）', 50, 83, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1663, '大坪桥', '大坪桥是一座4孔石拱桥。桥塊和桥面上铺砌青石板，全桥为平面。桥面宽4.50米，桥长31.00米。桥上建砖木结构廊。侧墙用料石砌筑，上顶有单层仰天石，桥台是凹字形，前墙长4.50米。桥墩也用青石板砌筑，两端与拱脚齐平，桥墩长4.50米，跨径由东向西依次是8.00米、12.00米、6.00米、6.00米。', '', 18, NULL, NULL, '', 8, 1, 10, 1, '邵阳市洞口县罗溪乡，跨宝瑶河上', '青石板、料石、砖木', 50, 84, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1664, '洞口双龙桥', '桥上无栏杆。桥面宽5.40米，桥长50.00米。桥上建砖木结构廊。侧墙用料石砌筑，上顶有单层仰天石。桥台是燕翅形，前墙长约6.60米。跨径20.00米。', '', 18, NULL, NULL, '', 8, 1, 8, 1, '邵阳市洞口县双龙村与舒家村交界处', '料石、砖木', 50, 85, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1665, '邵东洪桥', '洪桥是一座6孔等跨径石拱桥。桥塊和桥面上铺砌条形石板，全桥为平面，桥面宽6.70米，桥长68.00米。桥上建砖木结构廊。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，下部三面有小出台，前墙长约7.00米，后面与石砌河岸相连。桥墩两端是方形(两端与拱脚齐平), 下部四面有小出台，桥墩厚1.50米，桥墩长8.60米。拱碹是半圆形纵联式结构，无拱眉，跨径均为7.50米。', '', 18, NULL, NULL, '', 8, 1, 10, 1, '邵阳市邵东县洪桥村', '条形石板、料石、砖木', 50, 86, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1666, '老青石桥', '老青石桥是一座单孔石拱桥。桥塊和桥面上无铺装，无栏杆。桥面宽4.50米，桥长15.00米。侧墙用块石砌筑，上顶有单层仰天石。桥台是燕翅形，前墙长5.60米。拱碹是半圆形纵联式结构，无拱眉。', '', 18, NULL, NULL, '', 8, 1, 8, 1, '邵阳市邵东县仙槎桥镇平阳村', '块石', 50, 87, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1667, '三多桥', '桥面宽4.10米，桥长18.50米。桥上建砖木结构廊。侧墙用料石砌筑，上顶有双层仰天石。桥台是燕翅形，前墙长5.30米。桥墩两端是方形，桥墩厚1.50米，桥墩长4.70米。拱碹是半圆形纵联式结构，有拱眉，碹脸、拱眉与侧墙平。跨径均为4.00米。', '', 18, NULL, NULL, '', 8, 1, 8, 1, '邵阳市邵东县堆头村', '石材（料石）、砖、木', 50, 88, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1668, '时荣桥', '时荣桥是一座3孔石拱桥。桥塊和桥面上铺砌条形石板，全桥为平面。无栏杆，桥面宽4.00米，桥梁全长100.00米。桥上建砖木结构廊。侧墙用料石砌筑，上顶有单层仰天石。桥台两侧有燕翅墙，前墙 (与桥身齐)长4.00米。桥墩两端是尖形，桥墩厚2.60米，桥墩长 7.00米。拱碹是半圆形纵联式结构，无拱眉。跨径均为20.00米。', '', 18, NULL, NULL, '', 7, 1, 10, 1, '邵阳市邵东县坪上镇竹畔村', '条形石板、砖木、料石', 50, 89, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1669, '定远桥', '定远桥是一座单孔石拱桥。桥面上铺砌青石板为平面，桥上原是阶梯式坡道，今已改平。桥面宽7.66米，桥长36.97米。桥上建砖木结构重檐轩。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长7.66米。拱碹是鸭蛋形纵联式结构，龙门碹上镌刻“定远桥”,无拱眉。跨径26.00米。清代《绥宁县志》记载：桥长一十二丈六尺，宽二丈六尺，高五丈六尺。', '', 18, NULL, NULL, '', 8, 1, 8, 1, '邵阳市绥宁县关峡苗族乡关峡村，跨兰溪上', '青石板、砖木、料石', 50, 90, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1670, '赖家坊桥', '赖家坊桥（文中又称清安桥）是一座单孔石拱桥。桥塊和桥面上铺砌青石板，桥面宽4.60 米，桥梁全长18.00米。桥上建砖木结构廊。侧墙用块石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长4.60 米。拱碹是半圆形纵联式结构，无拱眉。跨径6.00米。', '', 18, NULL, NULL, '', 8, 1, 10, 1, '邵阳市绥宁县唐家坊镇赖梅村', '青石板、砖木、块石', 50, 91, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1671, '清安桥', '清安桥是一座单孔石拱桥。桥面宽8.00米，桥梁全长30.00米。桥上建宝塔形砖木结构亭。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长8.00米。拱碹是半圆形纵联式结构，无拱眉。跨径10.50米。', '', 18, NULL, NULL, '', 8, 1, 10, 1, '邵阳市绥宁县乐铺苗族侗族乡大团村，跨乐安溪上', '料石、砖、木', 50, 92, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1672, '攀龙桥', '攀龙桥是一座双孔等跨径石拱桥。桥面平，无栏杆。桥面宽5.05米，桥梁全长20.00米。侧墙用料石砌筑，上顶有双层仰天石。桥台是凹字形，前墙长5.10米。桥墩较薄，两端与拱脚齐平，桥墩厚80厘米，桥墩长5.60米。拱碹半圆形纵联式结构，无拱眉，跨径12.60米。', '', 18, NULL, NULL, '', 8, 1, 8, 1, '武冈市旧城区，跨渠水上', '料石', 50, 93, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1673, '武冈升平桥', '升平桥又名“三元桥”,俗称“关家桥”。该桥是一座7孔等跨径石拱桥。桥面中部(中孔拱顶上)高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆。桥宽5.70米，桥长86.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长约5.70米。拱碹是半圆形纵联式结构，无拱眉。桥墩较薄，两端与拱脚齐平，桥墩厚1.20米，桥墩长5.70米。跨径均为5.50米。', '', 18, NULL, NULL, '', 8, 1, 8, 1, '武冈市荆竹镇平村跨资水上', '料石', 50, 94, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1674, '石羊桥', '石羊桥是一座7孔等跨径石拱桥。桥堍和桥面上铺砌方形青石板，全桥为平面，无栏杆。桥面宽5.55米，桥梁全长84.45米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长5.50米。桥墩两端是方形，桥墩厚3.00米，桥墩长6.20米。跨径11.10米。', '', 18, NULL, NULL, '', 8, 1, 8, 1, '武冈市头塘乡石羊村，跨资水上', '方形青石板、料石', 50, 95, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1675, '新宁上石桥', '上石桥是一座单孔拱桥。桥面中部(拱顶上)为平面，两端是阶梯式坡道。无栏杆，桥面宽3.00米，桥长18.00米。侧墙用块石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长3.00米。拱碹是半圆形。跨径8.50米。', '', 18, NULL, NULL, '', 8, 1, 8, 1, '邵阳市新宁县万塘乡双石村', '块石', 50, 96, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1676, '下石桥', '桥面中部(拱顶上)为平面，两端是阶梯式坡道。无栏杆，桥面宽3.40米，桥长18.00米。拱碹是半圆形。跨径8.50米。', '', 18, NULL, NULL, '', 8, 1, 8, 1, '邵阳市新宁县万塘乡双石村', NULL, 50, 97, '2026-04-28 23:07:55', '2026-04-28 23:07:55');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1677, '新宁遇仙桥', '遇仙桥是一座单孔石拱桥。桥面中部(拱顶上)为平面，两端是阶梯式坡道。桥面宽5.10米，桥长18.60米。侧墙用块石砌筑，上顶有单层仰天石。桥台与块石砌筑的河岸为一体，拱碹是半圆形纵联式结构，无拱眉。跨径15.00米。', '', 18, NULL, NULL, '', 8, 1, 8, 1, '邵阳市新宁县莨山镇联合村，跨深莨溪上', '块石', 50, 98, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1678, '兴龙桥', '兴龙桥是一座双孔石拱桥。桥面平，两侧有石板栏杆。桥面宽4.60米，桥长13.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长4.60米。桥墩较薄，两端是方形，桥墩厚1.30米，桥墩长4.60米。拱碹是半圆形分段并列式结构，无拱眉。跨径3.00米。', '', 18, NULL, NULL, '', 8, 1, 8, 1, '邵阳城内武陵井东，跨渠水上', '石材（料石）', 50, 99, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1679, '湘潭汉城桥', '汉城桥是一座单孔石拱桥。桥面上无铺装，拱碹的上部即桥面，两端是阶梯式坡道，无栏杆。桥面宽5.00米，桥长12.00米。侧墙用红砂岩石料砌筑，上顶有一层较厚的红砂岩石板。桥台是在山脚岩石上开凿一段平面。拱碹是圆弧形纵联式结构，用红砂岩片石砌筑，无拱眉。跨径10.70米。', '', 18, NULL, NULL, '', 8, 1, 8, 1, '湘潭市花石镇马珑村，跨花石水上', '红砂岩石料、红砂岩石板、红砂岩片石', 50, 100, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1680, '湘潭石灵桥', '石灵桥原名“湘宁桥”。桥面为平面，两侧有节间式石栏杆，桥面宽6.40米，桥长52.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是燕翅形，前墙长7.60米。桥墩上游端是尖形，下游端是方形，桥墩厚2.00米，桥墩长10.00米。跨径均为9.25米。', '', 18, NULL, NULL, '', 8, 1, 8, 1, '湘潭市响塘乡', '料石', 50, 101, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1681, '湘乡万福桥', '全桥(桥塊和桥面)大致为平面，两侧有节间式石栏杆，望柱上顶与栏杆取平，无地伏，桥栏杆置于仰天石上。桥面宽6.70米，桥长166.80米。侧墙用料石砌筑，上顶面有单层仰天石。桥台是凹字形，前墙宽出拱脚约15厘米，前墙长7.00米，端墙外有燕翅墙。桥墩两端是尖形，尖端顶面高至仰天石，桥墩以上的侧墙上伸出一个方形勾头石，桥墩上部与拱脚同宽，下部比上部周边宽出约15厘米，桥墩厚1.60米，桥墩长7.10米。拱碹是半圆形纵联式结构，碹脸外边有拱眉石，拱眉凸出于碹脸，拱眉与侧墙取平。跨径均为13.40米。桥东端有石牌坊一座，石匾上刻“楚南大观”。石牌坊前面有桥名碑，镌刻“万福桥”三个凹形大字。', '', 18, NULL, NULL, '', 8, 1, 8, 1, '湘乡市洙津渡跨涟水上', '料石', 50, 102, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1682, '凤凰桥', '凤凰桥是一座3孔石拱桥。全桥上面为平面，桥面宽6.70米，桥长31.00米。桥上建砖木结构楼阁。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，两侧有料石砌筑的弧形挡墙，前墙长6.70米。桥墩两端是尖形，尖端的上部较高，桥墩厚2.25米，桥墩长7.80米。拱碹是卵形镶边纵联式结构，孔龙门上有石雕龙头，碹脸外边有拱眉石，拱眉凸出于碹脸，又凸出于侧墙。跨径均为8.00米。', '', 18, NULL, NULL, '', 7, 1, 7, 1, '湘西土家族苗族自治州凤凰县，跨万溶江上', '料石、砖木', 50, 103, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1683, '凤凰虹桥', '桥面宽8.50米，桥长80.00米。桥上建有楼阁。侧墙用红砂条石砌筑，上顶有单层仰天石。桥台是燕翅形，前墙长约9.70米。桥墩上游端是尖形，下游端是方形，桥墩厚2.25米，桥墩长10.10米。拱碹是近似半圆形(拱顶略显尖形)纵联式结构，无拱眉。跨径16.50米。', '', 18, NULL, NULL, '', 8, 1, 8, 1, '湘西土家族苗族自治州凤凰县，跨沱江上', '红砂条石', 50, 104, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1684, '凤凰两叉河桥', '桥面上无铺装，无栏杆。桥面宽4.70米，桥长11.00米。侧墙用不规则石料砌筑，上顶有一层较厚的仰天石(边牙石)。桥台是凹字形，前墙长4.70米。拱碹用不够规整的石板砌筑，属于半圆形(有变形)纵联式结构，拱碹厚40厘米，无拱眉，碹脸与侧墙平。跨径9.00米。', '', 18, NULL, NULL, '', 10, 1, 10, 1, '湘西土家族苗族自治州凤凰县千工坪乡田冲村，跨沱江支流两叉河上', '石料（不规则石料、石板）', 50, 105, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1685, '凤凰西门江桥', '桥面中间高起是平面，两侧有板式石栏杆，两端是阶梯式坡道，两端各有36级台阶。桥面宽8.70米，桥梁全长33.00米。侧墙用石板砌筑，上顶有双层仰天石组成的金边线。桥台是凹字形，前墙长8.70米。拱碹是卵形纵联式结构，碹脸外边有拱眉石，拱眉凸出于碹脸，拱眉与侧墙平。跨径17.00米。', '', 18, NULL, NULL, '', 7, 1, 7, 1, '湘西土家族苗族自治州凤凰县得胜营(今吉信镇)跨万溶江上', '石材', 50, 106, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1686, '同仁桥', '桥面上铺砌青石板，两侧有青石板栏杆，桥塊上是阶梯式坡道，无栏杆。桥面宽6.70米，桥长29.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，用料石砌筑。拱碹是半圆形纵联分段并列式结构，拱眉凸出于碹脸，拱眉与侧墙平。跨径17.80米。', '', 18, NULL, NULL, '', 9, 1, 10, 1, '湘西土家族苗族自治州永顺县沙坝镇盐卡村', '青石板、料石', 50, 107, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1687, '安化大福桥', '大福桥是一座4孔等跨径石拱桥。桥塊和桥面上铺砌青石板，全桥是平面。两侧有节间式石栏杆，无地伏，桥栏杆置于仰天石上。桥面宽7.50米，桥长95.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长9.00米。桥墩两端是方形，拱碹是半圆形纵联式结构，无拱眉。跨径16.50米。', '', 18, NULL, NULL, '', 8, 1, 10, 1, '益阳市安化县大福镇', '青石板、料石', 50, 108, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1688, '安化联珠桥', '联珠桥是一座双孔等跨径石拱桥。桥塊和桥面上铺砌红砂岩石板，全桥为平面，两侧有石栏杆。桥面宽7.00米，桥长52.00米。侧墙用块石砌筑，上顶有单层仰天石。桥台是燕翅形，桥墩两端是尖形，拱碹是半圆形纵联式结构，无拱眉。跨径均为15.50米。', '', 18, NULL, NULL, '', 8, 1, 10, 1, '益阳市安化县东坪镇株溪村', '红砂岩石板、块石', 50, 109, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1689, '益阳枫林桥', '枫林桥是一座单孔石拱桥。桥面两侧有节间式石栏杆，中间栏板上刻“枫林胜迹，资江一桥”，桥面宽6.50米，桥长64.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形。拱碹是半圆形纵联式结构，拱眉凸出于碹脸，拱眉与侧墙平。跨径21.50米。', '', 18, NULL, NULL, '', 8, 1, 8, 1, '益阳市兰溪镇枫林村，跨兰溪河上', '料石', 50, 110, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1690, '长田桥', '今存长田桥是一座5孔石拱桥。桥面(五孔上)为平面，两端原是阶梯式坡道(今已改平)。两侧有板式石栏杆，地伏是青石矩形断面。桥面宽 5.50 米，桥长 59.00 米。侧墙用料石砌筑，上顶有双层仰天石。桥台是凹字形，下部前面和左右有出台，端墙与河岸石墙连砌为一体，前墙长 5.50 米。桥墩两端与拱脚齐平，下部四周有出台，桥墩厚 1.00 米，桥墩长 5.50 米。拱碹是半圆形纵联分段并列式结构，碹脸外边有拱眉石，拱眉凸出于碹脸，拱眉又凸出于侧墙。跨径均为 10.00 米。', '', 18, NULL, NULL, '', 8, 1, 8, 1, '永州市道县寿雁镇长田村，跨状水河上', '石材（料石、青石）', 50, 111, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1691, '皋陶桥', '桥面中部(拱碹上)为平面，两侧有石栏杆，两端是阶梯式坡道，无栏杆。桥面宽6.00米，桥长38.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长6.00米，两侧有块石铺砌的护坡。桥墩两端与拱脚齐平，桥墩厚90厘米，桥墩长6.00米。拱碹是半圆形纵联式结构，碹脸外边有拱眉石，拱眉凸出于碹脸，拱眉与侧墙平。跨径均为9.00米。', '', 18, NULL, NULL, '', 8, 1, 8, 1, '永州市道县乐福堂乡大莲塘村，跨乐福堂河上', '石材（料石、块石）', 50, 112, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1692, '十里桥', '桥面中部(五孔拱碹上)原是平面，两端是坡道(今已改平),无栏杆。桥面宽3.40米，桥长37.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形。桥墩两端与拱脚齐平，拱碹是半圆形纵联分段并列式结构，碹脸外缘錾有较窄的拱眉线，拱眉与侧墙平。中3孔跨径6.30米，两边孔跨径是4.50米。', '', 18, NULL, NULL, '', 7, 1, 7, 1, '永州市道县寿雁镇阳家铺村，跨状水河支流中坪河上', '料石', 50, 113, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1693, '杏仁桥', '杏仁桥是一座5孔石拱桥。中3孔桥面高起为平面，两个边孔拱顶上的桥面为平面，中孔上的桥面和边孔上的桥面之间是一段坡面，桥堍上又是坡面。全桥无栏杆。桥面宽5.50米，桥长53.00米。侧墙用块石砌筑，上顶有单层仰天石。桥台是凹字形，用块石砌筑。桥墩两端是方形，桥墩厚1.05米，桥墩长6.00米。拱碹是半圆形纵联式结构，无拱眉。中3孔跨径11.00米，边孔跨径8.00米。', '', 18, NULL, NULL, '', 9, 1, 10, 1, '永州市道县清塘镇幸福洞村，跨濂溪河上', '块石', 50, 114, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1694, '广利桥', '广利桥是一座3孔等跨径石拱桥。桥塊和桥面上铺砌青石板，群桥为平面，无栏杆。桥面宽4.50米，桥长36.80米。桥上建砖木结构廊。侧墙是用青石板砌筑，上顶有单层仰天石。桥台是凹字形，前墙长4.50米。桥墩两端与拱脚齐平，桥墩厚33厘米，桥墩长4.50米.拱碹是半圆形纵联式结构，无拱眉。跨径12.00米，矢高6.00米。', '', 18, NULL, NULL, '', 8, 1, 8, 1, '永州市东安县紫溪镇花桥村，跨湘江支流紫水河', '青石板、砖木', 50, 115, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1695, '东安斩龙桥', '斩龙桥是一座3孔石拱桥。桥塊和桥面上铺砌不规则形石板，全桥是平面。两侧有节间式石栏杆，桥面宽2.20米，桥长56.00米。侧墙用块石砌筑，上顶有单层仰天石。桥台前墙与石砌河岸连砌在一起。桥墩较薄，两端与拱脚齐平，桥墩厚75厘米，桥墩长2.20米。拱碹是半圆形纵联式结构，无拱眉。跨径均为12.00米。', '', 18, NULL, NULL, '', 5, 1, 10, 1, '永州市东安县卢洪市镇，跨泸江上', '石板、块石', 50, 116, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1696, '安乐桥', '安乐桥是一座单孔石拱桥。桥面中部(拱顶上)高起为平面，两侧有石板栏杆，两端是阶梯式坡道，东西两坡上各有10级台阶，坡道上无栏杆。桥面宽430米，桥长28.00米。侧墙是用料石砌筑，上顶有单层仰天石。桥台是凹字形。拱碹是半圆形纵联式结构，无拱眉。跨径12.00米。', '', 18, NULL, NULL, '', 8, 1, 8, 1, '永州市江华瑶族自治县桥头铺镇下蒋村', '料石、石板', 50, 117, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1697, '西佛桥', '西佛桥是一座7孔石拱桥。桥塊和桥面上铺砌红砂岩石板，全桥为平面，两侧有节间式石栏杆，望柱上有千姿百态的小狮子。栏板上雕刻龙、鸟、兽以及，八仙过海、文王求贤等图案。栏端各设一对大狮子。桥面宽7.00米，桥长120.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是燕翅形，前墙长约8.20米。桥墩上游端水尖形，下游端水方形，桥墩厚1.20米，桥墩长7.50米。拱碹是半圆形纵联式结构，无拱眉。跨径14米。', '', 18, NULL, NULL, '', 8, 1, 8, 1, '永州市江华瑶族自治县沱江镇，跨沱江上', '红砂岩石板、料石', 50, 118, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1698, '步瀛桥（又名“渡仙桥”）', '步瀛桥是一座3孔石拱桥。桥塊和桥面上铺砌砂岩石板，桥面(三孔拱碹上)为平面，两端各有一小段阶梯式坡面，无栏杆。桥面宽4.50米，桥长30.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是燕翅形，前墙长约5.80米。桥墩上游端是尖形，下游端是方形，端部长出拱脚约30厘米，桥墩厚1.00米，桥墩长约6.00米。拱碹是大圆弧形(不够半圆形)纵联式结构(拱碹石不够规整),无拱眉，碹脸与侧墙平，跨径均为8.50米。', '', 18, NULL, NULL, '', 5, 1, 10, 1, '永州市江永县上甘棠村', '砂岩石板、料石', 50, 119, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1699, '高成桥', '高成桥又名接龙桥。桥面略显圆弧形，桥栏杆无存，地伏尚在。桥面宽5.10米，净宽4.30米，桥长20.00米。侧墙用料石板砌筑，上顶有单层仰天石。桥台是凹字形，前墙长5.10米。拱碹是半圆形纵联式结构，无拱眉，碹脸与侧墙平。跨径11.50米。', '', 18, NULL, NULL, '', 10, 1, 10, 1, '永州市江永县', '石材、料石板', 50, 120, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1700, '永州接履桥', '今存接履桥是一座单孔石拱桥。桥面为平面，无栏杆。桥面宽8.00米，桥长13.00米。侧墙用料石砌筑，上顶有单层仰天石(代边牙石)。桥台两侧有燕翅墙，前墙长9.20米。拱碹是半圆形镶边纵联式结构，无拱眉。跨径6.00米。', '', 18, NULL, NULL, '', 8, 1, 8, 1, '永州市零陵区接履桥镇', '料石', 50, 121, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1701, '祁阳枫林铺桥', '桥面铺砌的是青石板，大致是平面，两侧有板式石栏杆，桥面净宽6.20米，桥梁全长92.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台燕翅形，前墙长7.40米。桥墩两端是尖形，桥墩厚1.30米，桥墩长7.80米。拱碹是半圆形纵联式结构，无拱眉。跨径均为13.00米。', '', 18, NULL, NULL, '', 8, 1, 10, 1, '永州市祁阳县下马渡镇枫林铺村，跨祁水河上', '青石板、料石', 50, 122, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1702, '杉树桥', '杉树桥是一座3孔石拱桥。桥塊和桥面上铺砌青石板，桥面为平面，两侧有板式石栏杆，桥面宽5.70米，桥长40.00米。侧墙用块石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长5.70米。桥墩两端是方形，桥墩宽1.30米，桥墩长6.30米。拱碹是半圆形纵联式结构，无拱眉。跨径均为8.40米。', '', 18, NULL, NULL, '', 8, 1, 8, 1, '永州市祁阳县高码头青云村，跨祁水上', '青石板、块石', 50, 123, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1703, '祁阳小陂桥', '小陂桥是一座3孔石拱桥。桥面上铺砌青石板，两侧有节间式石栏杆，桥面宽4.30米，桥梁全长27.00米。侧墙用块石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长4.30米。桥墩两端是尖形，拱碹是半圆形纵联式结构，无拱眉。跨径均为4.80米。', '', 18, NULL, NULL, '', 8, 1, 8, 1, '永州市祁阳县蓝桥乡小陂村街口，跨白河支流清江上', '青石板、块石', 50, 124, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1704, '洪城桥', '洪城桥是一座3孔等跨径石拱桥。桥塊和桥面上铺砌花岗岩石板，两侧有石栏杆。桥面宽8.00米，桥长56.00米。侧墙用块石砌筑，上顶有单层仰天石。桥台是燕翅形。桥墩两端是尖形。跨径均为16.00米。', '', 18, NULL, NULL, '', 8, 1, 8, 1, '永州市新田县高山乡程家村，跨春陵河上', '花岗岩石板（桥塊和桥面）、块石（侧墙）', 50, 125, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1705, '岳阳三眼桥', '三眼桥是一座3孔等跨径石拱桥。桥塊和桥面上铺砌花岗岩石板，全桥为平面。两侧有板式石栏杆，无地伏，桥栏杆望柱栽在侧墙上，栏板两端和望柱之间有铸铁铜子连接，栏板下面有泄水孔。桥面宽8.89米，桥长46.80米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形(前墙两端与拱脚齐平)。前墙长8.90米，端墙后部有八字墙。桥墩上游端是尖形，下游端是方形，桥墩厚数据暂缺，桥墩长数据暂缺。拱碹是半圆形纵联式结构，有拱眉，碹脸、拱眉与侧墙取平。跨径均为13.00米。', '', 18, NULL, NULL, '', 8, 1, 8, 1, '岳阳市东郊，跨南湖水面上', '花岗岩石板、料石、铸铁', 50, 126, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1706, '岳阳桥 (俗称“三眼桥”)', '岳阳桥是一座3孔厚拱厚墩石拱桥。桥塊和桥面铺砌青石板，桥面中部隆起，两侧有节间式石栏杆，无地伏，桥栏杆置于仰天石上。桥栏杆两端各有一个石狮子，狮身连同石座全高1.65米。桥面宽8.89米，桥长48.60米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长8.90米，端墙的端部有八字石墙。桥墩两端是尖形，拱碹是半圆形纵联式结构，碹脸外边有拱眉石，碹脸、拱眉与侧墙齐平。中孔跨径12.00米，边孔跨径8.00米。', '', 18, NULL, NULL, '', 8, 1, 8, 1, '岳阳市奇家岭村', '青石板、料石', 50, 127, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1707, '女子桥', '女子桥是一座3孔石拱桥。桥塊和桥面上铺砌花岗岩石板，全桥为平面，无栏杆。桥面宽5.00米，桥长35.00米。侧墙用块石砌筑，上顶有单层较厚的仰天石，高出桥面而成边牙石。桥台是凹字形，前墙长5.00米。桥墩两端是尖形，拱碹是半圆形纵联式结构，碹脸外边有拱眉石，碹脸、拱眉与侧墙齐平。跨径均为8.30米。', '', 18, NULL, NULL, '', 7, 1, 7, 1, '岳阳市汨罗县古仓乡黄道村，跨汨罗江支流蓝向河上', '花岗岩石板（桥塊和桥面）、块石（侧墙）', 50, 128, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1708, '岭北桥', '岭北桥是一座5孔等跨径砖拱桥。桥塊和桥面上铺砌青砖，无栏杆。桥面宽2.70米，桥长29.00米。侧墙用青砖砌筑，上顶有单层仰天石。桥台是燕翅形，用青石料砌筑，下部是石料砌筑的基础。桥墩用青石料砌筑，下部是石料砌筑的基础，两端是尖形，拱碹是半圆形，用青砖砌筑。跨径均为5.00米。', '', 18, NULL, NULL, '', 8, 1, 10, 1, '株洲市茶陵县马江镇玄武村，跨马伏江上', '青砖、青石料、仰天石', 50, 129, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1709, '德星桥', '德星桥是一座6孔等跨径石拱桥。桥面上铺砌花岗岩石板，两侧有节间式青石栏杆。桥面宽5.50米，桥长75.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是燕翅形，用料石砌筑。桥墩两端是尖形，桥墩厚2.20米，桥墩长8.10米。拱碹是半圆形纵联式结构，拱眉凸出于碹脸，拱眉与侧墙平。跨径10.00米。', '', 18, NULL, NULL, '', 9, 1, 10, 1, '醴陵市船湾镇星桥村', '花岗岩石板、青石、料石', 50, 130, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1710, '冠南桥（又名“清水江桥”）', '冠南桥是一座6孔等跨径石拱桥。桥面上铺砌红砂岩石板，全桥为平面，无栏杆。桥面宽5.50米，桥长68.70米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形。桥墩两端是方形，桥墩厚1.80米，桥墩长6.10米，拱碹是半圆形纵联式结构，无拱眉。跨径均为8.20米。1958年洪水冲毁中二孔拱碹，再未修复，桥面上长满藤蔓杂草。', '', 18, NULL, NULL, '', 8, 1, 10, 1, '醴陵市清水江乡文山村，跨石河上', '红砂岩石板、料石', 50, 131, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1711, '横岭桥（又名“符犯桥”）', '桥面上铺砌红砂岩石，桥孔上是平面，两侧有矮墙式红砂岩石栏杆，两端是阶梯式坡道，无栏杆。桥面宽 3.40米，桥长21.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台两侧有燕翅墙，前墙长 4.60米。桥墩上游端是尖形，尖端上部是锥形，下游端是方形，伸出桥身外约70厘米，桥墩厚2.80米，桥墩长4.80米。拱碹是半圆形纵联式结构，无拱眉。跨径均为9.50米。', '', 18, NULL, NULL, '', 8, 1, 8, 1, '醴陵市泗汾镇湛田村，跨横岭河上', '红砂岩石、料石', 50, 132, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1712, '化龙桥', '化龙桥是一座3孔等跨径石拱桥。桥塊和桥面上铺砌红砂岩石板，全桥为平面，两侧有石栏杆。桥面宽5.50米，桥长29.50米。侧墙用红砂岩石板砌筑，上顶有单层仰天石。桥台是燕翅形，桥墩两端是圆形，桥墩厚2.10米，桥墩长6.70米。拱碹是半圆形纵联式结构，无拱眉。跨径均为7.00米。', '', 18, NULL, NULL, '', 9, 1, 10, 1, '醴陵市沈潭镇庞龙村，跨大障河上', '红砂岩石板', 50, 133, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1713, '渌江桥', '今存渌江桥是一座10孔等跨径石拱桥。桥堍和桥面上铺砌红砂岩石板，全桥为平面，两侧有节间式青石栏杆和青石地伏。桥面宽8.00米，桥长186.70米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，端墙外有燕翅墙，前墙长8.00米。桥墩两端与拱脚齐平，桥墩厚2.10米，桥墩长8.00米。拱碹是圆弧形分段并列式结构，碹脸外边有拱眉石，拱眉凸出于碹脸，拱眉与侧墙平。跨径均为16.00米。', '', 18, NULL, NULL, '', 7, 1, 7, 1, '醴陵市城南，跨渌江上', '红砂岩石板、青石、料石', 50, 134, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1714, '曾家滩桥', '曾家滩桥是一座6孔等跨径石拱桥。原桥面上铺砌花岗岩石板，两侧有节间式青石栏杆。桥面宽5.65米，桥长88.60米。侧墙用料石砌筑，上顶有单层仰天石。桥台是燕翅形，用料石砌筑。桥墩两端是尖形，桥墩厚2.50米，桥墩长8.00米。拱碹是半圆形纵联式结构，拱眉凸出于碹脸，拱眉与侧墙平。跨径均为16.50米。', '', 18, NULL, NULL, '', 9, 1, 10, 1, '醴陵市清水江乡曾家滩村', '花岗岩石板、青石、料石', 50, 135, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1715, '罗正坝桥', '罗正坝桥是一座3孔石拱桥。桥塊和桥面上铺砌青石板，桥面略显弧形，两侧有石栏杆。桥面宽4.30米，桥长28.75米。侧墙用块石砌筑，上顶有单层仰天石。桥台是凹字形，用块石砌筑。桥墩两端是尖形，拱碹是半圆形纵联分段并列式结构，拱眉凸出于碹脸，拱眉与侧墙平。中孔跨径8.10米，边孔跨径6.30米。', '', 18, NULL, NULL, '', 10, 1, 10, 1, '株洲市雷打石镇扶椅山村，跨小溪罗正坝上', '青石板、块石', 50, 136, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1716, '接龙桥', '接龙桥是一座双孔等跨径石拱桥。桥塊和桥面上铺砌红砂岩石板，全桥为平面，两侧有石栏杆。桥面宽3.70米，桥长31.90米。侧墙用块石砌筑，上顶有单层仰天石。桥台是燕翅形。桥墩上游端是尖形，下游端是方形，桥墩厚2.80米，桥墩长5.60米。拱碹是半圆形纵联式结构，拱眉凸出于碹脸，拱眉与侧墙平。跨径22.50米。', '', 18, NULL, NULL, '', 8, 1, 10, 1, '株洲市炎陵县', '红砂岩石板、块石', 50, 137, '2026-04-28 23:07:55', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1717, '兰塘桥', '兰塘桥是一座单孔石拱桥。桥面高起为平面，两侧有石板栏杆，桥塊上是阶梯式坡道，坡道上无栏杆。桥面宽4.20米，桥长20.00米。侧墙用块石砌筑，上顶有单层仰天石。桥台是凹字形，用块石砌筑。拱碹是半圆形纵联式结构，无拱眉。跨径6.00米。', '', 18, NULL, NULL, '', 9, 1, 10, 1, '株洲市攸县皇图岭镇龙和村', '块石、石板', 50, 138, '2026-04-28 23:07:56', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1718, '南溟桥', '今存南溟桥是一座6孔石拱桥。桥面铺砌红砂岩石板，桥面为平面，无栏杆。桥面宽3.65米，桥长60.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台两侧有燕翅墙，前墙长4.85米。桥墩两端是尖形，尖端上部较高，拱碹是半圆形分段并列式结构，碹脸外边有拱眉石，碹脸、拱眉与侧墙齐平。跨径7.80米。', '', 18, NULL, NULL, '', 8, 1, 8, 1, '株洲市攸县黄丰桥镇南溟桥村，跨无名沟渠上', '红砂岩石板（桥面）、料石（侧墙）', 50, 139, '2026-04-28 23:07:56', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1719, '重兴桥', '重兴桥是一座单孔砖石拱桥。桥面铺筑三合土为弧形。无栏杆，桥面宽3.60米，桥长13.90米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，拱碹半圆形，用砖材砌筑，碹脸及其他部位用料石砌筑。跨径7.00米。', '', 18, NULL, NULL, '', 7, 1, 7, 1, '株洲市攸县石羊塘镇谭家垄村', '三合土、料石、砖材', 50, 140, '2026-04-28 23:07:56', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1720, '大和桥', '大和桥是一座3孔悬臂式石板梁桥。桥面每孔6块石板梁，板梁长4.50—4.70米，石板梁厚40厘米，宽40厘米。石板梁下面两端各有两层悬臂石板。桥上两侧有石板栏杆，栏板厚40厘米，高50厘米，长5.10米，栏板设在桥面外边，栏板的两端搭在桥墩(台)上。桥面净宽2.40米，桥长13.70米。桥台是凹字形，前墙长约3.20米。桥墩上游端是尖形，桥墩下游端是方形，桥墩厚90厘米，桥墩长约3.70米。中孔跨径3.70米，边孔跨径3.50米。', '', 18, NULL, NULL, '', 8, 2, 8, 1, '宁乡市沙田村跨黄涓水上', '石材', 50, 141, '2026-04-28 23:07:56', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1721, '宁乡大江桥', '大江桥是一座5孔悬臂式石板梁桥。上部结构是简支石板梁，石梁下面两端各有两层悬臂石板。两侧有石板栏杆，栏板架在桥面外边，两端搭在桥墩上。桥面净宽2.60米，桥长39.50米。桥台是凹字形，前墙长约3.20米。桥墩两端是方形，桥墩厚0.90米，桥墩长约3.20米。跨径均为6.00米。', '', 18, NULL, NULL, '', 8, 2, 8, 1, '宁乡市石江村，跨七星河上', '石材', 50, 142, '2026-04-28 23:07:56', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1722, '惠同桥', '桥面每孔7块石板梁，石板梁两端下面各有两层悬臂石板。桥上两侧有石板栏杆，桥面宽4.00米，桥长18.00米。桥上建木结构廊。桥台是凹字形，前墙长约4.00米。桥墩两端是尖形，跨径5.80米。', '', 18, NULL, NULL, '', 8, 2, 10, 1, '宁乡市沙田乡，跨涓水河上', '石材、木材', 50, 143, '2026-04-28 23:07:56', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1723, '谭俊桥', '谭俊桥又名“弹箭桥”“檀正桥”。该桥是一座4孔石板梁桥和1孔石拱桥连接而成的石桥。两侧有石板栏杆，桥面宽2.10米，石板梁桥长12.00米，石拱桥长9.00米，全长30米。石板梁桥的桥台是凹字形，桥墩两端是方形，跨径均为2.80米。石拱桥的桥台是凹字形，跨径6.50米。', '', 18, NULL, NULL, '', 8, 1, 8, 1, '湖南省邵阳市邵阳县黄塘乡檀正村', '石材', 50, 144, '2026-04-28 23:07:56', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1724, '湘乡书院桥', '书院桥是一座5孔石板梁桥。桥塊上铺墁花岗岩石板，桥面是花岗岩石板梁，每孔3块石板梁，石板梁长4.80米，两侧原有板式石栏杆，今存混凝土栏杆。桥面宽1.95米，桥长24.00米。桥台是凹字形。桥墩两端为方形，桥墩厚1.80米，桥墩长2.00米。中孔跨径4.00米，其余4孔跨径为3.20米。', '', 18, NULL, NULL, '', 8, 2, 8, 1, '湘乡市东山书院门前', '花岗岩石板、混凝土', 50, 145, '2026-04-28 23:07:56', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1725, '衡龙桥', '今存衡龙桥是一座10孔石墩台石板梁桥。每孔有4块石板梁，桥面宽3.00米，桥长70.00米。桥台是凹字形。桥墩两端是方形，自上而下逐层石板伸出，桥墩厚0.90米，桥墩长3.50米。跨径均为6.00米。', '', 18, NULL, NULL, '', 8, 2, 8, 1, '湖南省益阳市赫山区衡龙桥村，跨衡龙桥村与莲花村之间的小溪上', '石材', 50, 146, '2026-04-28 23:07:56', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1726, '社湾桥', '社湾桥是一座7孔石板梁桥。每孔只有一块石板梁，中间5孔石板梁长4.00米，两边孔石板梁长均为4.80米；桥面宽1.20米，桥面长29.60米，桥梁全长36.00米。桥台两侧有燕翅墙，前墙长2.00米。桥墩上游端是尖形，下游端是方形，桥墩厚1.00米，桥墩长2.50米。中间5孔跨径均为3.00米，两边孔跨径是3.80米。', '', 18, NULL, NULL, '', 8, 2, 8, 1, '永州市零陵区水口山镇社湾村，跨梅溪河上', '石', 50, 147, '2026-04-28 23:07:56', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1727, '波澜桥', '馆驿桥是一座单孔石拱桥。桥上两侧有石板栏杆，每侧有望柱4根， 栏板3块，北侧栏板上刻“道光戊戌年建”,南侧栏板上刻“馆驿桥”。 桥台是凹字形。拱碹是半圆形纵联式结构，有拱眉，跨径7.00米。', '', 13, NULL, NULL, '', 8, 1, 10, 1, '福建省福清市城的护城河上', '石材', 50, 51, '2026-04-28 23:07:56', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1728, '回龙桥', '回龙桥是一座单孔石拱桥。桥面中部(拱顶上)高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆，桥面宽4.80米，桥长66.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形。拱碹是半圆形纵联分段并列式结构，无拱眉。跨径13.00米。', '', 13, NULL, NULL, '', 10, 1, 10, 1, '福州市马尾区闽安镇，跨邢港(旧河道)上', '石材（料石）', 50, 52, '2026-04-28 23:07:56', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1729, '彬德桥', '彬德桥是一座3孔石桥。中孔是石拱，两边孔是石板梁，桥面中部 (中孔上)高于两端(边孔上),桥面宽4.80米，桥长33.00米。 桥台是凹字形，桥墩两端是方形。中孔拱碹是圆弧形纵联式结构， 无拱眉，跨径7.00米。边孔是石板梁，跨径5.00米。', '', 13, NULL, NULL, '', 8, 1, 8, 1, '福州市台江区帮洲街，跨白马河上', '石材', 50, 53, '2026-04-28 23:07:56', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1730, '仁德桥（又名“六柱桥”）', '桥塊和桥面上铺砌石板为平面，两侧有节间式石栏杆，桥面宽2.30米，桥长13.50米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，用方形条石横顺相间砌筑，前墙长2.30米。拱碹是半圆形纵联式结构，无拱眉。跨径4.20米。', '', 13, NULL, NULL, '', 9, 1, 10, 1, '福州市台江区八一七中路，跨茶亭河上', '石板、料石、方形条石', 50, 54, '2026-04-28 23:07:56', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1731, '三通桥', '桥面略呈弧形，桥塊上是阶梯式坡道，两侧有节间式石栏杆。桥面宽6.20米，桥长36.70米。侧墙用料石砌筑，上顶有单层仰天石。桥台是燕翅形。桥墩两端是尖形，拱碹是半圆形纵联分段并列式结构，无拱眉，中孔跨径8.00米，边孔跨径7.00米。', '', 13, NULL, NULL, '', 8, 1, 10, 1, '福建省福州市台江区三捷河上', '石材（料石）', 50, 55, '2026-04-28 23:07:56', '2026-04-28 23:36:22');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1732, '沙合桥', '沙合桥是一座单孔石拱桥。桥塊和桥面上铺砌条形石板，两侧有节间式石栏杆，桥面宽1.50米，桥长10.80米。侧墙用块石砌筑，上顶有单层仰天石。桥台是凹字形，用方形条石砌筑。拱碹是圆弧形纵联式结构，无拱眉。跨径7.20米。', '', 13, NULL, NULL, '', 5, 1, 5, 1, '福州市台江区中亭街', '条形石板（桥塊和桥面）、块石（侧墙）、方形条石（桥台）', 50, 56, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1733, '透龙桥', '桥面为弧形，桥面宽5.70米，桥长 15.70米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长4.50 米。拱碹是纵联式结构，无拱眉。跨径4.00米。', '', 13, NULL, NULL, '', 8, 1, 10, 1, '福州市台江区后洲街', '料石', 50, 57, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1734, '星安桥', '星安桥是一座3孔石拱桥。中孔上桥面较高，边孔上桥面较低，高低桥面之间有台阶相连，两侧有节间式石栏杆，东面栏板上刻“乾隆丙午新建”“嘉庆乙丑年重修”“垂裕堂张重修憔善社监督”。桥面宽3.10米，净宽2.10米，桥面长17.30米，桥全长100.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，桥墩两端是方形，桥墩厚2.50米，桥墩长3.00米。拱碹是镶边纵联式结构，碹脸由9块弧形石板组成，无拱眉。跨径18.00米。', '', 13, NULL, NULL, '', 8, 1, 8, 1, '福州市台江区双杭街，跨星安河上', '石材（料石、弧形石板）', 50, 58, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1735, '柴头溪桥', '柴头溪桥是一座单孔石拱桥。桥面大致为平面，无栏杆，桥面宽 1.75米，桥梁全长11.00米。侧墙用块石砌筑，上顶有单层较厚的仰天石，石板上面高出桥面，成为边牙石。桥台建在山脚下。拱碹是半圆形纵联式结构，无拱眉，跨径4.80米。', '', 13, NULL, NULL, '', 10, 1, 10, 1, '福州市闽侯县南通镇瓜山村，跨柴头溪上', '石材（块石、仰天石）', 50, 59, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1736, '登云桥', '登云桥是一座单孔石拱桥。桥面隆起，桥上无栏杆，桥面宽2.30 米，桥梁全长6.50米。侧墙用块石砌筑，上顶有单层较厚的仰天石，石板上面高出桥面，成为边牙石。桥台建在山脚岩石上。拱碹是半圆形纵联分段并列式结构，跨径5.50米。', '', 13, NULL, NULL, '', 7, 1, 8, 1, '南平市顺昌县曲村，跨小溪涧上', '料石、木材', 50, 60, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1737, '拱桥头桥', '拱桥头桥是一座单孔石拱桥。桥上无栏杆，桥面宽2.40米，桥梁全长13.00米。侧墙用块石砌筑，上顶有单层较厚的仰天石，石板上面高出桥面，成为边牙石。桥台建在山脚岩石上。拱碹是半圆形纵联式结构，无拱眉，跨径6.60米。', '', 13, NULL, NULL, '', 10, 1, 10, 1, '福建省福州市闽侯县武竹村，跨安前溪上', '石材（块石）', 50, 61, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1738, '鼓响桥', '鼓响桥是一座单孔石拱桥。桥面中部即拱碹，两端是阶梯式石板踏步，桥面宽3.35米，桥长11.30米。无正式桥台，拱脚建在山崖岩石上，跨径9.00米。', '', 13, NULL, NULL, '', 8, 1, 8, 1, '福建省闽侯县', '石材', 50, 62, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1739, '合龙桥（又名双溪桥）', '合龙桥是一座单孔石拱桥。桥上无栏杆，桥面宽2.74米，桥梁全长7.80米。侧墙用块石砌筑，上顶有单层较厚的仰天石，石板上面高出桥面，成为边牙石。桥台建在山脚岩石上。拱碹是半圆形纵联式结构，无拱眉，跨径6.52米。', '', 13, NULL, NULL, '', 8, 1, 10, 1, '福州市闽侯县南屿镇九都村，跨山涧无名溪上', '块石、仰天石', 50, 63, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1740, '护龙桥', '护龙桥是一座单孔石拱桥。桥面平，两侧有块石砌筑的栏杆。桥面宽2.80米，桥长6.00米。侧墙用块石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长2.80米。拱碹是半圆形纵联式结构，无拱眉。跨径3.20米。', '', 13, NULL, NULL, '', 8, 1, 8, 1, '福建省福州市闽侯县上街镇下市大街，跨街河上', '石材（块石）', 50, 64, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1741, '金鳌桥', '金鳌桥是一座单孔石拱桥。桥上两侧有块石砌筑的栏杆，桥面宽 5.00米，净宽3.30米，桥梁面长13.60米，全长17.00米。侧墙用块石砌筑，上顶有单层较厚的仰天石，石板上面高出桥面，成为边牙石。桥台建在山脚岩石上。拱碹是半圆形纵联式结构，无拱眉，跨径12.00米。', '', 13, NULL, NULL, '', 8, 1, 8, 1, '福州市闽侯县雪峰村，跨山涧上', '块石', 50, 65, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1742, '闽侯金桥', '金桥是一座单孔石拱桥。桥上无栏杆，桥面宽4.80米，桥梁全长 17.00米。侧墙用块石砌筑，上顶有单层较厚的仰天石，石板上面高出桥面，成为边牙石。桥台建在山脚岩石上。拱碹是半圆形纵联式结构，无拱眉，跨径9.40米。', '', 13, NULL, NULL, '', 8, 1, 8, 1, '福州市闽侯县碘坑村，跨山涧上', '石材（块石、石板）', 50, 66, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1743, '金沙桥', '金沙桥是一座单孔石拱桥。桥上无栏杆，桥面宽4.30米，桥梁全长8.30米。侧墙用块石砌筑，上顶有单层较厚的仰天石，石板上面高出桥面，成为边牙石。桥台建在山脚基岩上。拱碹是半圆形纵联式结构，无拱眉，跨径6.30米。', '', 13, NULL, NULL, '', 10, 1, 10, 1, '福州市闽侯县荆溪镇六垱村，跨金沙溪上', '块石', 50, 67, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1744, '凉伞桥', '凉伞桥是一座单孔石拱桥。桥面略显弧形，原有桥栏杆无存，现有混凝土柱铁管栏杆。桥面宽2.70米，桥梁全长20.00米。侧墙用块石砌筑，上顶有单层较厚的仰天石，石板上面高出桥面，成为边牙石。桥台是凹字形，拱碹是圆弧形纵联式结构，无拱眉，跨径10.00米。', '', 13, NULL, NULL, '', 8, 1, 8, 1, '福州市闽侯县上街镇新峰村，跨玉浦河上', '石材（块石、石板）、混凝土、铁管', 50, 68, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1745, '闽侯美人桥', '美人桥俗称“鲤鱼尾桥”。桥面上铺砌青石板，桥面为弧形，无栏杆，桥面宽2.50米，桥梁全长7.10米。侧墙用块石砌筑，上顶有单层较厚的仰天石，石板上面高出桥面，成为边牙石。桥台建在山脚基岩上。拱碹是半圆形纵联式结构，拱碹厚53厘米，无拱眉，跨径4.70米。', '', 13, NULL, NULL, '', 8, 1, 8, 1, '福州市闽侯县大湖乡箬洋村', '青石板、块石', 50, 69, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1746, '上拱桥', '上拱桥是一座单孔石拱桥。桥面高起为平面，桥塊上是阶梯式坡道，各有5级台阶，无栏杆，桥面宽2.30米，桥梁全长12.30米。侧墙用块石砌筑，上顶有单层较厚的仰天石，石板上面高出桥面，成为边牙石。桥台建在山脚岩石上。拱碹是半圆形纵联式结构，无拱眉，跨径6.30米。', '', 13, NULL, NULL, '', 8, 1, 10, 1, '福州市闽侯县澎湖村，跨安溪上', '石材（块石）', 50, 70, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1747, '寺院桥', '寺院桥是一座单孔石拱桥。桥面平，无栏杆。桥面宽2.70米，桥长8.50米。侧墙用块石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长2.70米。拱碹是半圆形纵联式结构，无拱眉。跨径3.50米。', '', 13, NULL, NULL, '', 10, 1, 10, 1, '福州市闽侯县小箬乡尚锦村，跨寺院溪上', '石材（块石）', 50, 71, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1748, '无里拱桥', '无里拱桥是一座单孔石拱桥。无栏杆，桥面宽2.10米，桥梁全长 12.00米。 侧墙用块石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长约 2.10米。拱碹是半圆形纵联式结构，无拱眉，跨径5.10米。', '', 13, NULL, NULL, '', 7, 1, 7, 1, '福州市闽侯县青口镇幸福村，跨山涧溪上', '块石', 50, 72, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1749, '武竹拱桥', '武竹拱桥是一座单孔石拱桥。桥塊和桥面上铺砌不规则石板，桥面呈弧形，无栏杆，桥面2.40米，桥长13.00米。侧墙用块石砌筑，无仰天石。桥台建在山脚岩石上。拱碹用片石砌筑，是半圆形纵联式结构，拱碹厚40厘米，无拱眉，跨径6.60米。', '', 13, NULL, NULL, '', 10, 1, 10, 1, '福州市闽侯县江洋农场武竹村，跨安前溪上', '石板（桥面）、块石（侧墙）、片石（拱碹）', 50, 73, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1750, '仙坂桥', '桥塊是山腰岩石，桥上两侧有块石砌筑的栏杆，桥面宽2.20米，桥梁全长22.70米。侧墙用块石砌筑，上顶有单层较厚的仰天石，石板上面高出桥面，成为边牙石。桥台建在山脚岩石上。拱碹是半圆形纵联式结构，无拱眉，跨径8.00米。', '', 13, NULL, NULL, '', 8, 1, 8, 1, '福州市闽侯县荆溪镇六垱村，跨横坂溪上', '石材（块石）', 50, 74, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1751, '御杨溪桥', '今存御杨溪桥是一座单孔石拱桥。桥塊和桥面上铺砌不规则石板，无栏杆，桥面宽2.50米，桥梁全长约20.00米。侧墙用块石砌筑，上顶有单层较厚的仰天石，石板上面高出桥面，成为边牙石。桥台建在山脚岩石上。拱碹是圆弧形纵联式结构，无拱眉，跨径8.00米。', '', 13, NULL, NULL, '', 8, 1, 8, 1, '福州市闽侯县甘蔗街道云石村，跨御杨溪上', '石板、块石', 50, 75, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1752, '怨命桥', '怨命桥是一座双孔石拱桥。桥上无栏杆，桥面宽1.90米，桥梁全长27.00米。侧墙用块石砌筑，上顶有单层较厚的仰天石，石板上面高出桥面，成为边牙石。桥台建在山崖上。北孔拱碹是半圆形纵联式结构，无拱眉，跨径4.50米。南孔拱碹是马蹄形纵联式结构，无拱眉，跨径8.80米。', '', 13, NULL, NULL, '', 10, 1, 10, 1, '福州市闽侯县箬洋村', '块石、石板', 50, 76, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1753, '龙门桥', '桥面铺砌石板为平面，无栏杆，桥面宽 4.50米，桥长17.80米。桥上建木结构廊。侧墙的下部用大卵石砌筑，上部用块石砌筑，上顶无仰天石，栏杆置于侧墙上。桥台是凹字形，用料石砌筑，前墙长4.50米。拱碹是类似抛物线形纵联式结构，无拱眉。跨径6.50米。', '', 13, NULL, NULL, '', 8, 1, 10, 1, '福州市闽清县池园村，跨小溪上', '石板、木结构、大卵石、块石、料石', 50, 77, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1754, '永泰崇福桥', '崇福桥是一座单孔石拱桥。桥面上铺砌条形石板，桥面略显弧形，两侧有板式石栏杆，桥面宽3.30米，桥长22.50米。侧墙用不规则石块砌筑，上顶有单层仰天石组成的金边线。桥台是凹字形，前墙长3.30米。拱碹是半圆形纵联式结构，无拱眉。跨径14.50米。', '', 13, NULL, NULL, '', 8, 1, 8, 1, '福州市永泰县苍霞村', '石材（条形石板、不规则石块）', 50, 78, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1755, '永泰三捷桥', '三捷桥是一座单孔石拱桥。原有桥面中部铺砌石板为平面，两端是阶梯式坡道，各有12级踏步，1992年拆除踏步，改建成斜面坡道。桥面宽3.50米，桥长26.20米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长3.50米。拱碹是半圆形纵联式结构，无拱眉。跨径4.20米。', '', 13, NULL, NULL, '', 8, 1, 10, 1, '福州市永泰县三捷村', '石板、料石', 50, 79, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1756, '西塘桥', '西塘桥是一座单孔石拱桥。桥面上铺砌石板为平面，桥面宽4.20 米，桥长29.00米。桥上建木结构廊。 侧墙用块石砌筑，无仰天石。桥台是凹字形，用料石砌筑，前墙长 4.20米，拱碹是类似抛物线形纵联式结构，无拱眉。跨径20.20米。', '', 13, NULL, NULL, '', 8, 1, 8, 1, '福州市永泰县西塘村', '石板、块石、料石、木结构', 50, 80, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1757, '珠坑桥', '珠坑桥是一座单孔石拱桥。桥面上用乱石铺砌，桥面略显弧形，无栏杆，桥面宽3.60米，桥长21.50米。侧墙用乱石块砌筑，无桥台，拱脚建在山脚岩石上，拱碹是半圆形纵联式结构，无拱眉。跨径16.50米。', '', 13, NULL, NULL, '', 8, 1, 8, 1, '福州市永泰县椿阳村', '乱石', 50, 81, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1758, '永济桥', '永济桥是一座7孔石拱桥。桥塊和桥面上铺砌条形石板，桥面为平面，桥塊为坡面，两侧有节间式石栏杆，桥面宽3.50米，桥长62.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是燕翅形，前墙长约4.50米。桥墩两端是尖形，拱碹是半圆形纵联式结构，碹脸外边有拱眉，拱眉凸出于碹脸，拱眉与侧墙平。跨径均为6.50米。', '', 13, NULL, NULL, '', 10, 1, 10, 1, '福建省龙岩市长汀县濯田镇街上村，跨田河上', '条形石板、料石', 50, 82, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1759, '上杭驷马桥', '桥面宽7.80米，桥长21.00米。侧墙用块石砌筑，上顶有单层仰天石。桥台与石砌河岸连砌为一体，拱碹是半圆形纵联式结构，无拱眉。跨径7.50米。', '', 13, NULL, NULL, '', 7, 1, 5, 1, '龙岩市上杭县城西', '块石', 50, 83, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1760, '古成德桥', '古成德桥是一座3孔石拱桥。桥塊和桥面上铺砌花岗岩石板，桥面宽6.00米，桥面长63.40米，桥塊长各5.80米，桥梁全长75.00米。侧墙用料石砌筑，上顶有单层仰天石组成的金边线。桥台是凹字形，前墙长6.00米，端墙后部有用料石砌筑的燕翅墙，桥墩两端是尖形。拱碹是半圆形纵联式结构，无拱眉，碹脸后退于侧墙。跨径9.50米。', '', 13, NULL, NULL, '', 8, 1, 8, 1, '龙岩市武平县高梧村，跨高梧溪上', '花岗岩石板、料石', 50, 84, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1761, '武平永安桥', '永安桥原名“通济桥”。桥上两侧有石栏杆。桥面宽3.70 米，桥长113.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是燕翅形，桥墩两端是尖形，桥墩厚2.10米，桥墩长5.10米。拱碹是半圆形纵联分段并列式结构，无拱眉，跨径均为10.90米。', '', 13, NULL, NULL, '', 8, 1, 10, 1, '龙岩市武平县中山镇', '石材（料石）', 50, 85, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1762, '永宁桥', '桥面宽7.00米，桥长21.00米。桥上建砖木结构廊。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形。拱碹是半圆形纵联式结构，无拱眉。跨径12.00米。', '', 13, NULL, NULL, '', 8, 1, 8, 1, '龙岩市永安区青水乡青水村', '石材、砖、木', 50, 86, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1763, '永定高陂桥', '今存高陂桥是一座单孔石拱桥。桥面略显弧形，两侧有节间式石栏杆。桥面宽7.40米，桥长60.00米。侧墙用块石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长7.40米。拱碹是三心圆弧形纵联式结构，碹脸外边有拱眉石，拱眉与侧墙平。跨径20.00米。', '', 13, NULL, NULL, '', 8, 1, 8, 1, '龙岩市永定区高陂镇和兴村，跨永定河支流上', '石材（块石）', 50, 87, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1764, '香山桥', '香山桥是一座单孔石拱桥。桥面上铺砌条形石板，无栏杆，桥面宽 5.20米，桥长24.50米。侧墙用块石砌筑，上顶有单层仰天石。拱碹是半圆形纵联式结构，无拱眉，跨径10.00米。', '', 13, NULL, NULL, '', 8, 1, 10, 1, '漳平市赤水镇香山村，跨乡村排水沟上', '条形石板、块石', 50, 88, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1765, '万安桥', '万安桥是一座双孔石拱桥。桥塊和桥面上铺砌条形石板，桥面为平面，桥塊上是坡面，两侧有砖砌花栏杆。桥面宽6.60米，桥长34.60米。桥台建在山脚岩石上，跨乡村排水沟上。桥墩两端是方形。拱碹是半圆形纵联式结构，无拱眉，跨径12.50米。', '', 13, NULL, NULL, '', 8, 2, 10, 1, '宁德市屏南县长桥镇长桥村', '石材、砖、木', 50, 89, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1766, '吴屯桥', '吴屯桥是一座双孔石拱桥。桥塊上铺砌石板踏步，桥面(拱碹上) 为平面，桥面宽4.70米，桥长37.70米。侧墙用块石砌筑，上顶有单层仰天石。桥台与石砌河岸建在一起。桥墩两端是方形，建在基岩上，拱碹是半圆形纵联式结构，有拱眉，拱眉凸出于碹脸，拱眉与侧墙平。跨径9.00米。', '', 13, NULL, NULL, '', 7, 1, 7, 1, '福建省南平市光泽县吴屯村，跨吴屯溪上', '石材（块石、石板）', 50, 90, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1767, '建瓯水西桥', '全桥(桥塊和桥面)为平面，两侧有节间式石栏杆。桥面宽4.30米，桥长104.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台两侧有燕翅墙，前墙长5.50米。桥墩上游端为鹅胸形，下游端是方形，拱碹是半圆形纵联式结构，碹脸外边有拱眉石，拱眉与侧墙取平。跨径6.00米。', '', 13, NULL, NULL, '', 7, 1, 7, 1, '福建省建瓯市水西村', '石材（料石）', 50, 91, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1768, '建阳长见桥', '拱碹上面中部即桥面，两端是土坡道。桥面宽6.00米，桥长22.20米。侧墙用块石砌筑，上顶有单层仰天石。桥台建在山崖基岩上，拱碹是半圆形纵联式结构，无拱眉。跨径5.20米。', '', 13, NULL, NULL, '', 8, 1, 8, 1, '南平市建阳区长见村', '石材', 50, 92, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1769, '太子岭桥', '太子岭桥是一座单孔石拱桥。桥面中部(拱顶上)高起为平面，两端是阶梯式坡道，两侧有石栏杆，桥面宽6.00米，桥长22.60米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，拱碹是半圆形纵联式结构，无拱眉，跨径17.60米。', '', 13, NULL, NULL, '', 8, 1, 8, 1, '南平建阳区黄坑镇长见村', '料石', 50, 93, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1770, '铜青桥', '桥面铺砌不规则石板，桥面宽6.70米，桥长55.60米。侧墙用块石砌筑，上顶有单层仰天石。桥台是“一”字形，建在山脚岩石上。桥墩用方形条石横顺相间砌筑，两端是尖形，尖端高出拱脚许多，桥墩厚1.25米，桥墩长8.70米。拱碹是半圆形纵联式结构，无拱眉。跨径均为16.00米。', '', 13, NULL, NULL, '', 8, 1, 8, 1, '邵武市新丰村，跨于铜山与青山之间山涧上', '石材（不规则石板、块石、方形条石）', 50, 94, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1771, '松溪花桥', '桥面宽3.50米，桥长36.90米。桥上有木结构廊。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，用料石砌筑，前墙长3.50米。桥墩两端是方形(端面与侧墙齐平),用料石砌筑，桥墩厚1.35米，桥墩长3.90米。拱碹是半圆形纵联式结构，无拱眉，跨径均为11.50米。', '', 13, NULL, NULL, '', 8, 1, 8, 1, '南平市松溪县花桥村，跨越杉溪上', '料石、木结构', 50, 95, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1772, '松溪溪桥', '溪桥是一座单孔石拱桥。桥面宽4.50米，桥长16.00米。桥上有木结构廊。侧墙用乱石砌筑，上顶有单层仰天石，桥台是凹字形，用乱石砌筑，端墙与侧墙为同一整体，前墙长4.50米。拱碹是半圆形纵联式结构，无拱眉，跨径10.50米。', '', 13, NULL, NULL, '', 7, 1, 7, 1, '南平市松溪县项溪村', '石材、木材', 50, 96, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1773, '巨口桥', '巨口桥是一座单孔石拱桥。桥塊和桥面上铺砌石板，桥面全桥弧形，无栏杆。桥面宽4.90米，桥长17.00米。侧墙用块石砌筑，上顶有单层较厚的仰天石，石板高出桥面。桥台是凹字形，用块石砌筑，前墙长5.00米，拱碹是类似抛物线形纵联式结构，无拱眉。跨径8.00米。', '', 13, NULL, NULL, '', 8, 1, 8, 1, '武夷山市星村镇巨口村', '石板、块石', 50, 97, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1774, '政和花桥', '花桥是一座单孔石拱桥。桥上是平面，两端有台阶，桥面全宽8.00米，净宽7.50米，桥长38.00米。桥上有木结构廊，中间部位有木结构阁。侧墙用不规则石板砌筑，上顶有单层仰天石。桥台是凹字形，前墙长8.00米，端墙和侧墙为同一墙面。拱碹是半圆形纵联式结构，无拱眉。跨径12.20米。', '', 13, NULL, NULL, '', 7, 1, 10, 1, '南平市政和县杨源乡坂头村，跨潘溪上', '石、木', 50, 98, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1775, '白玉西桥', '白玉西桥是一座单孔石拱桥。桥塊和桥面上铺砌青石板。全桥为平面。桥面宽5.50米，桥长29.00米。桥台与块石砌筑的河岸为一体。跨径12.50米。', '', 13, NULL, NULL, '', 8, 1, 10, 1, '福建省宁德市屏南县寿山乡白玉村', '青石板（桥塊和桥面）、块石（桥台与河岸）', 50, 99, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1776, '永安桥', '桥面中部(拱顶上)为平面，两端是阶梯式坡道，无栏杆。桥面宽4.00米，桥长27.50米。侧墙用不规则块石砌筑，上顶有矩形断面的仰天石。桥台是凹字形，拱碹是半圆形纵联式结构，无拱眉，碹脸与侧墙平。跨径13.50米。', '', 13, NULL, NULL, '', 10, 1, 10, 1, '宁德市柘荣县溪口乡东狮山村，跨山间排水沟上', '石材（不规则块石）', 50, 100, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1777, '赤岩虹桥', '桥面铺砌石板为平面，两侧安装石板栏杆，桥面宽5.00米，桥长27.00米。桥上建木结构廊和阁。侧墙用块石砌筑，上顶无仰天石，石板栏杆置于侧墙上。桥台是凹字形，用料石砌筑，前墙长5.00米。拱碹是半圆形纵联式结构，无拱眉。跨径14.40米。', '', 13, NULL, NULL, '', 8, 1, 8, 1, '宁德市周宁县泗桥乡赤岩村', '石板、块石、料石、木结构', 50, 101, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1778, '仙瀛桥', '仙瀛桥是一座单孔石拱桥，桥面中部(拱顶上)高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆。桥面宽4.20米，桥长54.60米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，用料石砌筑。拱碹是半圆形纵联分段并列式结构，拱眉凸出于碹脸，又凸出于侧墙。跨径22.30米。', '', 13, NULL, NULL, '', 8, 1, 8, 1, '泉州市安溪县剑斗镇圳下村', '料石', 50, 102, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1779, '德化拱桥', '拱桥是一座单孔石拱桥，桥堍和桥面上铺砌不规则石板，桥面为平面，桥堍上是阶梯式坡道，各有10级台阶，无栏杆，桥面宽3.30米，桥长31.00米。侧墙用块石砌筑，上顶有单层仰天石。桥台建在山脚岩石上。拱碹是半圆形纵联式结构，无拱眉，跨径19.50米。', '', 13, NULL, NULL, '', 8, 1, 8, 1, '泉州市德化县雷峰镇蕉溪村，跨蕉溪涧支流上', '石材（不规则石板、块石）', 50, 103, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1780, '通泗桥', '通泗桥是一座单孔石拱桥。桥面宽7.20米，桥长29.00米。桥上建砖木结构廊。侧墙用块石砌筑，上顶有单层仰天石。桥台建在山脚岩石上。拱碹是圆弧形纵联式结构，无拱眉，跨径13.20米。拱碹上面两端各有一个小孔洞，拱碹是半圆形纵联式结构，无拱眉。跨径1.30米。', '', 13, NULL, NULL, '', 8, 1, 8, 1, '三明市大田县华兴乡杞溪村', '石材（桥身、侧墙）、砖木（廊屋）', 50, 104, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1781, '大田镇东桥', '镇东桥是一座5孔石拱桥。北起第二孔上桥面高起为平面，两端是坡道，两侧有节间式石栏杆，桥面宽4.50米，桥长74.00米。侧墙用不规则石块砌筑，上顶有双层仰天石。桥台两侧有块石砌筑的八字墙，前墙长4.50米。桥墩两端是尖形，跨径由南向北依次是6.00米、14.40米、13.20米、11.50米、9.80米。', '', 13, NULL, NULL, '', 8, 1, 8, 1, '福建省三明市大田县均溪镇跨均溪上', '石块、块石、铸铁件', 50, 105, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1782, '古厝桥', '古厝桥是一座单孔石拱桥。桥面宽4.80米，桥长20.00米。桥上有木结构廊和阁。侧墙用块石砌筑，上顶有单层仰天石。桥台建在山脚岩石上，拱碹是半圆形纵联式结构，无拱眉。跨径6.50米。', '', 13, NULL, NULL, '', 8, 1, 10, 1, '福建省三明市将乐县白莲镇余家坪村，跨莲花溪上', '石材（块石）、木材', 50, 106, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1783, '高潭桥', '桥面宽4.60米，桥长24.00米。桥上建砖木结构廊。侧墙用料石砌筑，上顶有单层仰天石。桥台建在山脚岩石上。拱碹是半圆形纵联式结构，无拱眉。跨径12.50米。', '', 13, NULL, NULL, '', 10, 1, 10, 1, '三明市宁化县水茜乡安寨村', '石材（料石）、砖木', 50, 107, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1784, '宁化鹊架桥', '双虹桥是一座5孔等跨径石拱桥。桥塊和桥面铺砌石板为平面，桥上建木结构廊。桥面宽6.50米，桥长75.00米。侧墙用料石砌筑，上顶有单层仰天石，桥台是凹字形，下部有扩大基底，前墙上部长6.50米。桥墩两端是方形，下部有扩大基底，桥墩上部厚1.40米，桥墩上部长7.00米。拱碹是半圆形纵联式结构，碹脸外边有拱眉，拱眉凸出于碹脸，又凸出于侧墙。跨径均为14.25米。', '', 13, NULL, NULL, '', 8, 1, 8, 1, '宁化', '石板、料石、木材', 50, 108, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1785, '进谷桥', '桥面宽7.00米，桥长45.00米。桥上有木结构廊。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长7.00米，端墙和侧墙为同一墙面。拱碹是半圆形纵联式结构，无拱眉。跨径12.30米。', '', 13, NULL, NULL, '', 8, 1, 10, 1, '三明市沙县夏茂镇大布村，跨进谷溪上', '料石、木材', 50, 109, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1786, '石镇桥', '桥面宽6.50米，桥长16.50米。桥上建砖木结构廊。侧墙用块石砌筑，上顶有单层仰天石。桥台建在山脚岩石上。拱碹是半圆形纵联式结构，无拱眉。跨径12.30米。', '', 13, NULL, NULL, '', 8, 1, 10, 1, '三明市沙县高砂镇渔溪湾石镇村', '块石、砖、木', 50, 110, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1787, '会清桥', '桥面宽8.20米，桥长41.80米。桥上有砖木结构廊。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长9.00米。桥墩两端是方形(桥墩长等于桥身宽),桥墩长9.00米。拱碹是半圆形纵联式结构，无拱眉。中孔跨径13.20米，边孔跨径11.70米。', '', 13, NULL, NULL, '', 8, 1, 10, 1, '永安市贡川镇集风村，跨贡川溪与沙溪汇合处', '石材（料石）、砖、木', 50, 111, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1788, '聚福桥', '聚福桥是一座3孔等跨径石拱桥。桥面宽6.70米，桥长37.00米。桥上建砖木结构廊。侧墙用块石砌筑，上顶有单层仰天石。桥台是燕翅形。桥墩两端是尖形。拱碹是半圆形纵联式结构，无拱眉，跨径9.50米。', '', 13, NULL, NULL, '', 8, 1, 8, 1, '永安市大湖镇吴坊村', '石材、砖木', 50, 112, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1789, '流长桥', '流长桥是一座双孔石拱桥。桥上两侧无栏杆，桥面宽5.60米，桥长50.00米。侧墙用料石砌筑，上顶有双层仰天石。桥台建在山脚岩石上。桥墩两端是尖形，拱碹是半圆形纵联式结构。跨径14.00米。', '', 13, NULL, NULL, '', 7, 1, 10, 1, '漳州市华安县良村', '料石', 50, 113, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1790, '温水溪桥', '温水溪桥是一座7孔石拱桥。两侧有节间式石栏杆，桥面宽6.20 米，桥长102.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是燕翅形。桥墩两端是尖形，跨径均为8.00米。', '', 13, NULL, NULL, '', 10, 1, 10, 1, '漳州市华安县', '料石', 50, 114, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1791, '华安西浦桥', '西浦桥又名“流长桥”“刘塘桥”。桥面上铺砌条形石板，全桥为平面，两侧有节间式石栏杆，无地伏。桥面宽6.50米，桥长36.00米。桥塊以外有很长的坡道。侧墙用料石砌筑，上顶有双层仰天石。桥台只有3层石板，建在山岩基岩上，是凹字形，前墙长6.50米。桥墩两端是方形，桥墩厚3.00米，桥墩长6.50米。拱碹为半圆形纵联式结构，有拱眉，碹脸、拱眉与侧墙平。跨径均为14.00米。', '', 13, NULL, NULL, '', 7, 1, 10, 1, '福建省漳州市华安县良村温水溪上', '条形石板、料石', 50, 115, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1792, '古弯桥', '古弯桥是一座双孔石拱桥。桥面南高北低为坡面，无栏杆，桥面宽 3.00米，桥长26.00米。侧墙用料石砌筑，上顶有双层仰天石。桥台建在山崖基岩上。桥墩两端是尖形。拱碹是半圆形纵联式结构，无拱眉，南孔跨径6.00米，北孔跨径3.00米。', '', 13, NULL, NULL, '', 7, 1, 7, 1, '漳州市南靖县南坪村，跨古桥溪上', '料石', 50, 116, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1793, '瑞龙桥', '瑞龙桥是一座单孔石拱桥。桥面铺砌石板为平面，两侧有石栏杆，无地伏，桥栏杆置于仰天石上，桥面宽6.00米，桥长18.00米。桥上建木结构廊。侧墙用料石砌筑，上顶无仰天石，石板栏杆置于侧墙上。桥台是凹字形，用料石砌筑，前墙长6.00米。拱碹是半圆形纵联式结构，无拱眉。跨径6.00米。', '', 13, NULL, NULL, '', 8, 1, 8, 1, '南平市茂地村跨山涧上', '石板、料石、木材', 50, 117, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1794, '朝天桥', '朝天桥是一座单孔石拱桥。桥塊上是阶梯式坡道，各有11级踏步，桥面上铺砌条形石板，桥面宽4.60米，桥长9.00米。侧墙用块石砌筑，上顶有单层仰天石。桥台是燕翅形，前墙长5.50米。拱碹是半圆形纵联式结构，无拱眉。跨径7.80米。', '', 13, NULL, NULL, '', 5, 1, 10, 1, '宁德市蕉城区护城河上', '条形石板、块石', 50, 118, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1795, '宁德花桥', '桥面宽3.50米，桥长36.00米。桥上有木结构廊。侧墙用块石砌筑，上顶有单层仰天石。桥台是凹字形，用方形条石横顺相间砌筑，端墙后部有燕翅墙，前墙长3.50米。桥墩两端是尖形，用方形条石横顺相间砌筑，桥墩厚1.35米，桥墩长6.40米。拱碹是半圆形纵联式结构，无拱眉，跨径均为11.00米。', '', 13, NULL, NULL, '', 8, 1, 8, 1, '宁德县宁德市梅鹤村', '块石、方形条石、木材', 50, 119, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1796, '福州断桥', '断桥俗称“三门桥”，是一座3孔石板梁桥。桥面是4块石板梁，石板梁的侧面刻“绍兴三年岁次癸丑八月辛酉二十六日戊申，作都管干林康、林元均泊诸劝首等”，无栏杆，桥面宽2.80米，桥长30.00米，西边孔塌毁，东边孔堵塞，不再通水。现有桥长22.00米。桥台是凹字形，桥墩两端是方形，桥墩厚1.60米，桥墩长3.30米。中孔跨径6.00米，边孔跨径5.50米。', '', 13, NULL, NULL, '', 5, 2, 5, 1, '福州市仓山区城门镇林浦村', '石材', 50, 120, '2026-04-28 23:07:56', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1797, '连坂桥', '桥堍上铺砌石板，桥面是两块石板梁，石梁厚50厘米，宽70厘米，梁长7.10米。桥面宽1.40米，桥全长15.00米。桥台是凹字形，用料石砌筑，下面有木桩基础。跨径6.00米。', '', 13, NULL, NULL, '', 10, 2, 10, 1, '福州市仓山区城门镇连坂村', '石板、料石、木桩', 50, 121, '2026-04-28 23:07:56', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1798, '七星桥', '七星桥是一座3孔石板梁桥。中孔桥面高起为平面，边孔桥面为坡面，每孔有4块石板梁，桥面宽3.50米，桥长11.90米。桥台是凹字形，用方形条石横顺相间砌筑，前墙上顶有三层条石向前逐层伸出，前墙长3.50米。桥墩两端是方形，也是方形条石横顺相间砌筑，上顶有三层条石向两边逐层伸出，桥墩厚3.50米，桥墩长也是3.50米。中孔跨径5.50米，边孔跨径5.00米。', '', 13, NULL, NULL, '', 5, 2, 10, 1, '福州市仓山区郭宅村', '石材（方形条石、石板梁）', 50, 122, '2026-04-28 23:07:56', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1799, '前桥', '前桥是一座单孔石板梁桥。桥面每孔3块石板梁，桥面宽1.50米，桥面长5.90米。桥台是用条形石板砌筑，是凹字形，前墙长2.00米。跨径5.10米。', '', 13, NULL, NULL, '', 5, 2, 10, 1, '福州仓山区城门镇胪雷村', '石板', 50, 123, '2026-04-28 23:07:56', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1800, '午桥（又名“五门桥”）', '午桥是一座5孔悬臂式石板梁桥。石板梁两端下面有5层悬臂石梁，自下而上逐层加长。桥上两侧有节间式石栏杆，桥面宽3.25米，桥长34.00米。桥台是凹字形，用方形条石砌筑。桥墩用方形条石砌筑，两端为尖形，跨径均为5.50米。', '', 13, NULL, NULL, '', 5, 2, 10, 1, '福州市仓山区盖山镇阳岐村', '方形条石', 50, 124, '2026-04-28 23:07:56', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1801, '取青桥', '今存取青桥是一座3孔石板梁桥。桥面每孔有5块石板梁，桥面宽3.30米，桥面长10.00米。桥台用方形条石砌筑，横顺相间垒砌，两侧有弧形燕翅墙，前墙长3.30米。桥墩也是用方形条石砌筑，横顺相间垒砌，两端是圆弧形，桥墩厚1.00米，桥墩长4.10米。跨径2.80米。', '', 13, NULL, NULL, '', 10, 2, 10, 1, '福州市长乐区鹤上镇青桥村，跨排水沟上', '石材（方形条石、石板梁）', 50, 125, '2026-04-28 23:07:56', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1802, '太平桥', '太平桥原名“丰泰桥”,又名“观音桥”。原是一座单孔石板梁桥，桥面宽6.00米，桥面长5.50米。桥台是凹字形，用料石砌筑，前墙长6.60米，跨径4.70米。', '', 13, NULL, NULL, '', 8, 2, 8, 1, '福州市鼓楼区，跨琼河上', '石材', 50, 126, '2026-04-28 23:07:56', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1803, '下橹桥', '下橹桥是一座单孔石梁桥。桥塊上横铺4块石板，桥面是5块石板梁，无栏杆，桥面宽2.70米，桥面长4.00米。原桥台是用石板砌筑的凹字形。跨径3.20米。河道今已改成暗沟，石桥埋于地下。', '', 13, NULL, NULL, '', 8, 2, 8, 1, '福州市长乐区吴航镇和平街', '石板', 50, 127, '2026-04-28 23:07:56', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1804, '行相桥', '行相桥是一座4孔悬臂式石板梁桥。桥面每孔5根石梁，石梁厚50厘米，宽70厘米，两侧有节间式石栏杆，无地伏。望柱置于石梁上，栏板两端各有一块石垫块，桥面宽3.50米，桥长26.00米。桥台两侧有燕翅墙，前墙上顶有两侧悬臂石板，桥墩两端是尖形，上顶有两侧双悬臂石板。跨径均为5.10米。', '', 13, NULL, NULL, '', 7, 2, 10, 1, '福州市长乐区竹田村', '石材', 50, 128, '2026-04-28 23:07:56', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1805, '云庞桥', '云庞桥是一座3孔石板梁桥。桥塊上铺砌条形石板，桥面每孔两边各架设一根断面为方形的石梁。石梁厚45厘米，石梁宽50厘米，石梁长4.70米，石梁上面内侧有企口。石梁之间横铺石板而构成桥面，桥面宽2.20米，桥面长18.00米。桥台两侧有燕翅墙，用方形条石横顺相间砌筑，上顶向前有3层单向悬臂梁，悬臂梁的两侧是方形。桥墩两端是尖形，也是用方形条石横顺相间砌筑，上顶有3层双向悬臂梁，悬臂梁的两端是方形，与桥面取齐。净跨径3.70米，墩间距离4.50米。', '', 13, NULL, NULL, '', 8, 2, 10, 1, '福州市长乐区边兰村，跨潭头江上', '石板、方形条石', 50, 129, '2026-04-28 23:07:56', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1806, '安泰桥', '上部结构是由6块石板梁构成桥面，石板梁两端有一对斜撑石板，均为6块石板梁。石板梁与斜撑石板之间各有一根方形横系条石。桥面高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆，桥面宽10.00米，桥长11.00米。侧墙用块石砌筑，上顶有单层仰天石。桥台是凹字形。桥台前墙长10.60米。跨径5.30米。两面侧墙上各有一对桥联柱，上顶有勾头石。', '', 13, NULL, NULL, '', 10, 2, 10, 1, '福州市鼓楼区八一七北路', '石材', 50, 130, '2026-04-28 23:07:56', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1807, '板桥', '桥面由4块石板梁组成，石板梁厚37厘米，长5.35米。两侧设有节间式石栏杆。桥面宽3.00米，长5.35米。桥台呈凹字形，跨径为4.55米。', '', 13, NULL, NULL, '', 7, 2, 7, 1, '福州市鼓楼区光禄坊南侧，跨于罗城大濠上', '石材（原为木材）', 50, 131, '2026-04-28 23:07:56', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1808, '福枝桥', '桥面是两根石板梁，石梁厚40厘米，宽40厘米，长6.40米。石梁上面横铺石板，无栏杆。桥面宽2.63米，净宽1.68米，桥面长6.80米。桥台与石板砌筑的河岸为一体。跨径4.25米。', '', 13, NULL, NULL, '', 8, 2, 8, 1, '福州市鼓楼区朱紫坊河沿，跨安泰河上', '石板', 50, 132, '2026-04-28 23:07:56', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1809, '高陛桥', '高陛桥是一座3孔悬臂式石板梁桥。中孔桥面较高，边孔桥面较低，高低桥面之间有3级台阶。桥面每孔4条石板梁，桥堍上是阶梯式坡道，东桥堍是9级台阶，西桥堍是10级台阶。两侧有节间式石栏杆，每侧有8根望柱，西端望柱上有石狮子，其余望柱上是正六边形球体。有7块石栏板，栏板长2.30—2.60米，桥面宽3.50米，桥堍端宽4.45米，桥梁全长24.40米。桥台与石板砌筑的河岸为一体。桥墩两端是尖形，中孔跨径6.20米，边孔跨径4.50米(总跨度15.20米)。', '', 13, NULL, NULL, '', 8, 2, 8, 1, '福州市鼓楼区，跨琼东河上', '石板', 50, 133, '2026-04-28 23:07:56', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1810, '高峰桥', '桥面是7块石板梁，两侧有节间式石栏杆，每侧有望柱4根，石栏板3块，栏板上刻有仙鹤、麒麟、花草图案。桥面宽4.20米，净宽3.64米，桥面长6.80米，全长13.90米。桥台是凹字形，与石板砌筑的河岸为一体。跨径7.50米。', '', 13, NULL, NULL, '', 8, 2, 8, 1, '福州市鼓楼区，跨陆庄河上', '石材', 50, 134, '2026-04-28 23:07:56', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1811, '古迹二桥', '古迹二桥是一座单孔石板梁桥。桥面宽3.10米，桥面长6.60米，桥梁全长7.80米。桥上建木结构廊。桥台是凹字形，用条形石板砌筑，前墙长3.10米。跨径5.60米。', '', 13, NULL, NULL, '', 8, 2, 8, 1, '福州市鼓楼区，跨仓前河上', '条形石板、木结构', 50, 135, '2026-04-28 23:07:56', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1812, '虹桥', '虹桥是一座单孔石板梁桥，桥面是4块石板梁，石板厚0.37米，石板长5.35米。两侧有石板栏杆。桥面宽3.00米，桥面长5.35米。桥面两端各有3级台阶。桥台是凹字形，与石板砌筑的河岸为一体。跨径4.60米。', '', 13, NULL, NULL, '', 7, 2, 7, 1, '福州市鼓楼区光禄坊，原五代闽国罗城南门外，跨罗城护城河上', '石材', 50, 136, '2026-04-28 23:07:56', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1813, '金斗桥', '桥面是4块石板梁，石板梁宽75厘米，石板梁厚20厘米，石板梁长5.40米，两侧有石板栏杆。桥堍上是阶梯式坡道，东坡有7级台阶，西坡有8级台阶。桥面宽3.70米，桥长10.20米。桥台是凹字形。跨径4.70米。', '', 13, NULL, NULL, '', 8, 2, 10, 1, '福州市鼓楼区文儒坊西口，跨于古罗城大濠上', '石材', 50, 137, '2026-04-28 23:07:56', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1814, '陆庄桥', '桥面有3块石板梁，桥面宽2.50米，桥长8.00米。桥上有木结构廊。桥台即石砌河岸(石板梁架设在河岸上)，跨径7.00米。', '', 13, NULL, NULL, '', 8, 2, 8, 1, '福州市鼓楼区杨桥中路', '石板、木材', 50, 138, '2026-04-28 23:07:56', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1815, '武安桥', '武安桥是一座单孔石板梁桥，桥面是7块石板梁，石板梁长5.60 米，两侧有节间式石栏杆，桥面宽3.25米，桥长10.00米。桥台与石板砌筑的河岸为一体。跨径4.80米。', '', 13, NULL, NULL, '', 8, 2, 8, 1, '福州市鼓楼区安泰河东端秀冶里，跨五代罗城大濠上', '石板', 50, 139, '2026-04-28 23:07:56', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1816, '宦溪桥', '宦溪桥是一座双孔等跨径石板梁桥。桥面是3块石板梁，两侧有石板栏杆，北孔栏板上刻“时元祐六年岁五月初六日”,桥面宽2.30米，桥长11.70米。桥台是燕翅形。桥墩是船形，跨径4.70米。', '', 13, NULL, NULL, '', 5, 2, 10, 1, '福州市晋安区宦溪乡宦溪村', '石材', 50, 140, '2026-04-28 23:07:56', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1817, '福州回龙桥', '回龙桥是一座5孔悬臂式石梁桥。每孔是3根石板梁，两侧有石栏杆，桥面宽4.46米，桥梁全长65.65米。桥台是燕翅形。桥墩两端是尖形，桥墩厚1.30米，桥墩长6.00米。跨径均为6.00米。', '', 13, NULL, NULL, '', 8, 2, 10, 1, '福州市马尾区闽安镇，跨邢港(旧河道)上', '石材', 50, 141, '2026-04-28 23:07:56', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1818, '济美桥', '济美桥是一座单孔石板梁桥。桥面是4块石板梁，石板梁厚37厘米，石板梁长5.50米，两侧有节间式石栏杆，栏板上刻“济美桥”三个大字。桥面宽2.50米，桥面长5.50米。桥两端各有4级台阶。桥台与石板砌筑的河岸为一体。跨径4.70米。', '', 13, NULL, NULL, '', 8, 2, 8, 1, '福州市马尾区君竹村', '石材', 50, 142, '2026-04-28 23:07:56', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1819, '沈公桥', '沈公桥原名“回龙桥”，南宋重建时改名“飞盖桥”。现存桥梁为5孔悬臂式石板梁桥。桥面每孔7块石板梁，石梁断面1.00米见方，梁长12.80米。石梁下方的桥台和桥墩上各有一层悬臂石板，其上横置一层方形条石。桥两侧设有节间式石栏杆，无地伏。望柱共36根，置于石板梁上，断面45厘米见方，高1.40米。栏板两端各置方形石垫，下方有空隙，两面雕刻有雄狮、海兽、莲花等图案。桥面宽4.80米，桥长66.00米。桥台两侧有燕翅墙，前墙顶有两层悬臂石板，两侧有块石砌筑的护岸。桥墩下部用石板砌筑且两端呈尖形，上部用方形条石横顺相间砌筑且两端为方形。桥墩厚1.00米，桥墩中距13.80米，跨径12.80米。', '', 13, NULL, NULL, '', 8, 2, 8, 1, '福州市马尾区', '石材（石板、条石、块石）', 50, 143, '2026-04-28 23:07:56', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1820, '白马桥', '白马桥原是一座4孔石板梁桥，而后，为造地而填河，废东边孔，现存白马桥是一座3孔石板梁桥。桥面宽3.10米，桥面长71.00米，全长(两端桥塊长各12.00米)95.00米。桥台是凹字形，用方形条石横顺相间砌筑，前墙上顶有3层悬臂式石板，前墙长3.10米。桥墩两端是方形，也是用方形条石横顺相间砌筑，上顶有3层上悬臂石板，桥墩厚1.70米，桥墩长3.10米。跨径均为6.20米。', '', 13, NULL, NULL, '', 8, 2, 8, 1, '福建省福州市台江区跨白马河上', '方形条石、石板', 50, 144, '2026-04-28 23:07:56', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1821, '河口万寿桥（俗称“小万寿桥”）', '中孔桥面比边孔高出约0.40米，边孔桥面较低，每孔有5块石板梁，两侧有节间式石栏杆。每侧有望柱10根，栏板9块，无地伏。望柱安装在石板梁上，栏板两端有石垫块。桥面宽3.00米，桥梁全长35.00米。桥台是凹字形，前墙上顶有4层伸出的悬臂石板，前墙长约3.50米。桥墩两端是方形，上顶有4层向两边伸出的悬臂石板，桥墩厚约1.00米，上顶厚约2.00米。中孔跨径6.20米，边孔跨径约5.50米。', '', 13, NULL, NULL, '', 8, 2, 8, 1, '福州市台江区河口万寿路跨晋安河上', '石材', 50, 145, '2026-04-28 23:07:56', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1822, '福州万寿桥', '万寿桥是一座37孔石板梁桥，桥面每孔用两根断面为1.00米见方的石梁，间距3.00—4.00米，石梁长9.00—10.00米，石梁上面横铺0.30米和0.40米厚的石板构成桥面。桥面宽约4.50米，桥长391.00米。桥台是凹字形，用方形条石横顺相间砌筑，前墙上顶伸出两层悬臂石板，前墙长约5.00米。桥墩两端是方形，也是用方形条石横顺相间砌筑，上顶有两层双悬臂石板。中孔跨径8.00米，边孔跨径7.00米。', '', 13, NULL, NULL, '', 6, 2, 10, 1, '福州市台江区中亭街，跨南台江上', '石材（石梁、石板、方形条石）', 50, 146, '2026-04-28 23:07:56', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1823, '福清利桥 (又名“龙首桥”)', '利桥是一座10孔石板梁桥。桥面每孔是5块石板梁，无栏杆。桥面宽5.00米，桥长183.00米。桥台是凹字形，前墙长5.00米。桥墩两端是方形，桥墩厚2.00米，桥墩长5.20米。跨径均为6.20米。', '', 13, NULL, NULL, '', 7, 2, 7, 1, '福清市', '石材', 50, 147, '2026-04-28 23:07:56', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1824, '上迳桥（蹑云桥）', '上迳桥是一座14孔悬臂式石板梁桥。桥面每孔是5块石板梁，无栏杆。桥面宽3.50—3.90米，桥长100.00米。桥台是凹字形，前墙长5.00米。桥墩两端是方形，桥墩厚1.00—1.20米。最大跨径8.50米。民国二十七年(1938年),日寇飞机炸毁6孔，尚存9孔，桥长约71.00米。', '', 13, NULL, NULL, '', 5, 2, 10, 1, '福清市上迳村', '石材', 50, 148, '2026-04-28 23:07:56', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1825, '乌石桥', '乌石桥是一座双孔石板梁桥。无栏杆，桥面每孔用6块厚40厘米、宽50厘米、长6.00米的花岗岩石板梁架设，桥面中部(桥墩上)略显高起，因而桥面呈双向坡面，桥面宽3.00米，桥长16.40米。桥台是凹字形，用方形条石横顺砌筑，前墙上顶有两层逐层伸出的石板。桥墩也是用方形条石横顺砌筑，上顶有4层逐层伸出的石板。净跨径约5.00米。', '', 13, NULL, NULL, '', 7, 2, 7, 1, '福州市连江县敖江镇毗屯村，跨乌石浦上', '花岗岩石板、方形条石', 50, 149, '2026-04-28 23:07:56', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1826, '贤义桥', '贤义桥是一座3孔悬臂式石板梁桥。桥面每孔是3根石梁，石梁厚 0.70米，石梁宽0.70—0.80米。石梁两端下面各有3层悬臂石板。桥上无栏杆，桥面宽2.30米，桥长30.00米。桥台建在山脚处，为长方形，用方形条石横顺相间砌筑，前墙长 2.70米。桥墩两端是尖形，也是用方形条石横顺相间砌筑，桥墩厚 1.20米，桥墩长2.70米。跨径均为6.15米。', '', 13, NULL, NULL, '', 8, 2, 8, 1, '福州市连江县贤义村', '石材（方形条石、石梁、石板）', 50, 150, '2026-04-28 23:07:56', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1827, '罗源坦桥（又名“险桥”）', '坦桥是一座单孔石板梁桥。桥面是3根石板梁，石梁厚0.50米，宽0.60米，长8.00米，桥面宽1.80米，桥面长8.00米。桥台是凹字形，前墙长1.80米。跨径7.00米。', '', 13, NULL, NULL, '', 8, 2, 8, 1, '福建省福州市罗源县铁香炉村，跨于山涧中山崖上', '石材', 50, 151, '2026-04-28 23:07:56', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1828, '王认桥（叶令桥）', '王认桥是一座3孔石板梁桥。每孔5块石板梁，石梁厚0.35米，宽0.80米，长7.90米。中孔桥面稍高起为平面，两侧有石栏杆，边孔桥面略呈斜坡，无栏杆。桥面宽3.70米，桥长22.00米。桥台和桥墩用料石砌筑，桥台是凹字形，桥断两端是方形，桥墩厚1.00米，中孔跨径7.00米，边孔跨径6.50米。', '', 13, NULL, NULL, '', 8, 2, 8, 1, '福州市罗源县洪洋乡王认村', '石材（石板梁、料石）', 50, 152, '2026-04-28 23:07:56', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1829, '闽侯白屿桥', '白屿桥是一座7孔石板梁桥。桥面每孔3块石板梁，一侧有节间式石栏杆，桥面宽2.20米，全长80.00米。桥台是凹字形，前墙长2.50米。桥墩两端是圆形，桥墩厚75厘米，桥墩长2.50米。跨径6.50—9.20米。', '', 13, NULL, NULL, '', 8, 2, 8, 1, '福州市闽侯县南屿镇新联村，跨垱上', '石材', 50, 153, '2026-04-28 23:07:56', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1830, '坂尾桥', '坂尾桥是一座3孔石板梁桥。桥面宽3.80米，桥全长47.20米。桥台是凹字形，前墙长约4.00米。桥墩用方形条石横顺相间砌筑，两端是方形，桥墩厚1.40米，桥墩长4.00米。中孔跨径5.50米，边孔跨径5.00米。', '', 13, NULL, NULL, '', 8, 2, 8, 1, '福州市闽侯县青口镇杨厝村和扈屿村之间', '石材（方形条石）', 50, 154, '2026-04-28 23:07:56', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1831, '闽侯得胜桥', '得胜桥是一座7孔等跨径悬臂式石梁桥。桥面是4块石板梁，桥面宽2.60米，全长56.00米。桥台是凹字形，前墙长3.00米，前墙上顶有两层悬臂石板。桥墩两端是方形，桥墩厚1.20米，桥墩长3.00米，上顶有两层悬臂石板。跨径均系6.00米。', '', 13, NULL, NULL, '', 5, 2, 5, 1, '福州市闽侯县青口镇梅岭村，跨无名河上', '石材', 50, 155, '2026-04-28 23:07:56', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1832, '登瀛桥', '登瀛桥是一座3孔石板梁桥。两侧有节间式石栏杆，桥面净宽2.70米，桥长45.00米。桥台是凹字形，前墙长3.10米。桥墩两端是方形，桥墩下部厚1.00米，上顶厚1.50米。桥墩长3.10米。中孔跨径6.60米，边孔跨径6.00米。', '', 13, NULL, NULL, '', 8, 2, 8, 1, '福州市闽侯县南通镇厝村文昌阁前', '石材', 50, 156, '2026-04-28 23:07:56', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1833, '闽侯观澜桥', '观澜桥是一座双孔石板梁桥。桥面每孔是3块石板梁，石板梁厚 0.46米，宽0.60米，长约6.00米，桥面宽1.80米，桥长12.70米。 桥台是凹字形，前墙长1.80米。桥墩两端是方形，桥墩下部厚 1.00米，上顶厚1.50米。桥墩长1.80米。跨径5.40米。', '', 13, NULL, NULL, '', 8, 2, 10, 1, '福州市闽侯县鸿尾乡奎石村圣君堂旁边', '石材', 50, 157, '2026-04-28 23:07:56', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1834, '闽侯航桥', '航桥是一座双孔悬臂式石梁桥。东孔桥面是3块石板梁，西孔桥面是两根石梁，上面横铺石板，桥面宽1.70米，桥长11.80米。桥台是凹字形，用方形条石横顺相间砌筑，前墙长2.00米。桥墩两端是方形，用方形条石横顺相间砌筑，桥墩厚约0.80米，桥墩长2.00米。桥墩上顶有两层悬臂石梁，也都是方形条石，下层顺桥方向，上层横铺。跨径5.10米。', '', 13, NULL, NULL, '', 8, 2, 10, 1, '福州市闽侯县南通镇泽洋村，跨杭溪上', '石板、方形条石', 50, 158, '2026-04-28 23:07:56', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1835, '合浦桥（又名“下铺桥”）', '合浦桥是一座3孔石板梁桥。中孔上桥面高起为平面，边孔上桥面是斜坡，每孔4根石梁，石梁厚0.40米，宽0.50—0.65米，桥面宽2.5米，桥长20.00米。桥台是凹字形，用方形条石横顺相间砌筑，前墙长2.7米。桥墩两端是方形，也是用方形条石横顺相间砌筑，桥墩厚约0.80米，长约2.70米。中孔跨径约6.20米，边孔跨径约6.00米。', '', 13, NULL, NULL, '', 8, 2, 8, 1, '福州市闽侯县南屿镇合浦村', '石材（石梁、方形条石）', 50, 159, '2026-04-28 23:07:56', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1836, '乐善桥', '乐善桥是一座3孔石板梁桥，桥面宽2.10米，桥长18.00米。桥台是凹字形，前墙长2.10米。桥墩两端是方形，桥墩厚1.00米，桥墩长2.10米。中孔跨径5.30米，边孔跨径4.60米。民国八年(1919年)进行加宽，做法是在原桥桥台和桥墩外侧各竖立一根混凝土方形柱，在石桥面的外侧架设一道混凝土方形纵梁，上面安装混凝土栏杆。加宽后，桥面宽3.70米。', '', 13, NULL, NULL, '', 9, 2, 10, 1, '福州市闽侯县南通镇银安村，跨直厅溪上', '石材、混凝土', 50, 160, '2026-04-28 23:07:56', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1837, '灵光桥', '灵光桥是一座4孔石板梁桥。桥塊上横向铺砌条石，桥面每孔是4块石板梁，在桥墩上石梁之间横铺一根条石，桥面宽2.30米，桥梁全长32.00米。桥台两侧有燕翅墙，用方形条石横顺相间砌筑，前墙长2.40米。桥墩底部两端是尖形，上部两端是方形，也是用方形条石横顺相间砌筑，桥墩下部厚约1.00米，上部厚约1.60米，长2.40米。跨径均约为2.60米。', '', 13, NULL, NULL, '', 8, 2, 7, 1, '福州市闽侯县荆溪镇桐口村', '条石、石板梁、方形条石', 50, 161, '2026-04-28 23:07:56', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1838, '娘奶桥', '娘奶桥是一座3孔石板梁桥。每孔3块石板梁，石板梁厚0.45米，宽0.87米，长6.83米，桥面宽2.70米，桥长21.00米。桥台是凹字形，前墙长3.00米。桥墩两端是方形，桥墩厚约0.80米，桥墩长3.00米。中孔跨径5.60米，边孔跨径3.10米。', '', 13, NULL, NULL, '', 8, 2, 8, 1, '福州市闽侯县南屿镇尧沙村，跨浯江上', '石材', 50, 162, '2026-04-28 23:07:56', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1839, '栖云桥', '桥面每孔两块花岗岩石板梁，石梁厚40厘米，宽80厘米，长6.70米。桥面宽1.50米，桥长10.50米。桥面两端有一段阶梯式坡道。桥台是凹字形，用条石砌筑，跨径5.70米。', '', 13, NULL, NULL, '', 4, 2, 10, 1, '福州市闽侯县南屿镇窗夏村', '花岗岩、条石', 50, 163, '2026-04-28 23:07:56', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1840, '青州桥', '青州桥是一座6孔石板梁桥。桥面南端第一孔是两根石梁，上面横铺石板，第二、第三孔是两块石板梁，其他3孔都是3块石板梁。桥面宽1.50米，桥长41.00米。桥台是凹字形，前墙长2.00米。桥墩两端是方形，桥墩厚约80厘米，桥墩长2.00米。跨径6.00米。', '', 13, NULL, NULL, '', 7, 2, 7, 1, '福州市闽侯县上街镇青州村，跨桥头港上', '石材', 50, 164, '2026-04-28 23:07:56', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1841, '榕荫桥', '榕荫桥是一座3孔石梁桥。中孔桥面高起为平面，边孔桥面为坡面，每孔4根石梁，石梁厚0.50米，宽0.70米。两侧有节间式石栏杆，无地伏。望柱置于石梁上，石栏板两端各有一块方形石垫块，栏板下面有缝隙。桥面宽3.50米，净宽2.90米，桥长30.60米。桥台是凹字形，用方形条石砌筑，前墙长4.00米。桥墩上游端是尖形，下游端是方形，桥墩厚1.00米，桥墩长4.50米。中孔跨径6.30米，边孔跨径6.10米。', '', 13, NULL, NULL, '', 8, 2, 8, 1, '福州市闽侯县南通镇苏坂村，跨青龙江上', '石材（方形条石、石梁、石栏杆）', 50, 165, '2026-04-28 23:07:56', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1842, '闽侯三元桥', '三元桥是一座3孔石板梁桥。桥面每孔6块石板梁，桥面宽2.40米，桥长45.00米。桥台是凹字形，前墙长3.00米。桥墩上游端是尖形，下游端是方形。中孔跨径9.10米，边孔跨径4.70米。1994年，利用原桥台和桥墩，将桥梁加长，桥面加宽。', '', 13, NULL, NULL, '', 10, 2, 10, 1, '福州市闽侯县祥谦镇风港村，跨淘江支流蚬子浦上', '石材', 50, 166, '2026-04-28 23:07:56', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1843, '沙帽桥', '每孔3块石板梁，桥面宽2.10米，桥长12.00米。桥台是凹字形，前墙长2.50米。桥墩两端是尖形，桥墩厚0.80米，桥墩长2.80米。东孔跨径5.40米，西孔跨径5.00米。', '', 13, NULL, NULL, '', 8, 2, 8, 1, '福州市闽侯县竹歧乡榕西村，跨山尾溪上', '石材', 50, 167, '2026-04-28 23:07:56', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1844, '十四门桥', '十四门桥又称榕桥。北宋元丰二年(1079年)兴工修建，历时近七年，于元丰八年(1085年)建成一座14孔石板梁桥。清同治年间，山洪冲毁南端二孔及多孔桥面，直至民国十七年(1928年)修复，改成13孔。今存十四门桥是一座13孔石板梁桥。每孔两块石板梁，桥面宽1.74米，桥长85.50米。桥墩两端为尖形，跨径4.00—6.00米。', '', 13, NULL, NULL, '', 8, 2, 10, 1, '福州市闽侯县上街镇榕桥村，跨可溪上', '石材', 50, 168, '2026-04-28 23:07:56', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1845, '透头桥', '透头桥是一座5孔石板梁桥。桥面每孔5根石板梁，桥面宽1.50米，桥面长8.90米。桥台前墙和桥墩的构造相同，都是两根方形石柱，上顶横架一根方形石帽梁。跨径(石板梁长)均为1.70米。', '', 13, NULL, NULL, '', 8, 2, 8, 1, '福州市闽侯县荆溪镇后屿村，跨后屿浦溪上', '石材', 50, 169, '2026-04-28 23:07:56', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1846, '宏屿桥', '宏屿桥是一座单孔石板梁桥。桥塊上铺砌花岗岩石板，桥面每孔3块花岗岩石板梁，石板厚0.36米，石板宽0.67米，石板长3.90米，无栏杆。桥面宽2.20米，桥面长3.90米，两端桥塊长12.00米，桥梁全长27.95米。桥台是凹字形，用花岗岩石板砌筑，上顶有两层悬臂石板，跨径2.75米。', '', 13, NULL, NULL, '', 8, 2, 10, 1, '福州市闽侯县青口镇宏屿村', '花岗岩石板', 50, 170, '2026-04-28 23:07:56', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1847, '杨桥', '杨桥是一座单孔石板梁桥。桥面是两根石板梁，石板梁厚0.40米，宽0.80米，长7.80米。桥面宽1.67米，全长15.00米。桥台是凹字形，前墙长1.40米。跨径7.00米。', '', 13, NULL, NULL, '', 8, 2, 8, 1, '福州市闽侯县南屿镇龙泉村，跨浦口河上', '石材', 50, 171, '2026-04-28 23:07:56', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1848, '闽侯荫岩桥', '桥面每孔3块石板梁，桥面宽3.50米，桥长30.00米。桥台是凹字形，前墙长约4.00米。桥墩用方形条石横顺相间砌筑，两端是方形，桥墩厚1.00米，桥墩长4.00米。中孔跨径6.00米，边孔跨径5.20米。', '', 13, NULL, NULL, '', 8, 2, 8, 1, '福州市闽侯县荆溪镇徐家村，跨陈塘溪上', '石材', 50, 172, '2026-04-28 23:07:56', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1849, '永寿桥', '今存际上桥是一座3孔石板梁桥。中孔桥面比边孔高出约0.30米，边孔桥面较低，每孔有4—5块石板梁，石梁厚0.40米，石梁宽0.60米，石梁长6.50米。无栏杆，桥面宽2.80米，桥梁全长23.60米。桥台是凹字形，前墙上顶有4层伸出的悬臂石板，前墙长约3.00米。桥墩两端是方形，上顶有4层向两边伸出的悬臂石板，桥墩厚约1.00米，上顶厚约2.00米。净跨径约5.50米。', '', 13, NULL, NULL, '', 8, 2, 8, 1, '福建省闽侯县', '石材', 50, 173, '2026-04-28 23:07:56', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1850, '水北溪桥', '今存水北溪桥是一座62孔石板梁桥。桥面每孔是4根石板梁，桥面宽3.10米，桥长238.00米。桥台是用料石砌筑为长方形，前面竖立4根方形石柱，上顶横架一根扁方形石帽梁。桥墩是用4根方形石柱垂直设置，上顶横架一根扁方形石帽梁，墩柱两侧各有一根方形石戗柱。跨径5.50—5.70米。', '', 13, NULL, NULL, '', 8, 2, 10, 1, '福鼎市水北溪村', '石材（料石、石柱、石板）', 50, 174, '2026-04-28 23:07:56', '2026-04-28 23:36:28');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1851, '龙江桥', '龙江桥原是一座42孔石板梁桥，后因修建海口城废弃2孔，今存40孔。桥面是花岗岩石板梁，每孔5根石梁，石梁厚60—75厘米，两侧有节间式石栏杆，桥面宽4.20—5.20米，桥面长438.30米，全长480.00米。桥南端建一座七层六角石塔。桥台两侧有燕翅墙，桥墩是船形，前墙长5.50米，上游端是尖形，下游端是方形，桥墩厚1.00—1.20米，桥墩长10.00米。跨径不等，最小9.00米，最大13.00米。同期修筑石堤，堤长200余米。', '', 13, NULL, NULL, '', 5, 2, 5, 1, '福建省福清市海口镇，跨龙江下游', '花岗岩', 50, 175, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1852, '箭场桥', '箭场桥是一座3孔石板梁桥。桥面每孔9根石板梁，石梁厚0.45 米，石梁宽0.30—0.50米，石梁长6.00米，石梁侧面有通榫和通槽， 石梁互相榫槽对接，增强横向联系。桥面宽3.50米，桥长19.00米。 桥台是燕翅形，前墙长约4.00米。桥墩两端是尖形，跨径均为 5.30米。', '', 13, NULL, NULL, '', 8, 2, 10, 1, '宁德市蕉城区桥头下村', '石材', 50, 176, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1853, '忠洋桥', '桥面是5根石梁，桥面宽2.75米，桥面长8.00米。上面建有木结构瓦顶方形亭。桥台是凹字形，前墙上部有5层石板，逐层伸出。净跨径4.00米。', '', 13, NULL, NULL, '', 5, 2, 5, 1, '宁德市屏南县黛溪镇忠洋村', '石板、木、瓦', 50, 177, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1854, '岳阳桥', '岳阳桥是一座单孔石梁桥。桥面上铺墁不规则形石板，桥面弧形，无栏杆，亦无边牙石。桥面宽2.40米，桥长6.00米。主体结构属于五边折线形纵联分段并列式结构，是用5段并列的平面石板和4根方形条石构成，每段石板5块，石板厚0.30米，宽约0.50米，长1.50米。每根纵联石厚0.30米，宽0.30米，长2.40米。最下段石板置于山脚基岩上。桥孔立面呈五边折线形。跨径均为4.70米。', '', 13, NULL, NULL, '', 8, 2, 10, 1, '宁德市寿宁县南阳村', '石板、方形条石', 50, 178, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1855, '青岸桥', '今存青岸桥是一座10孔石板梁桥。桥面每孔7块石板梁，宽2.50米，桥长62.00米。桥台是用料石砌筑为长方形，前面竖立3根扁方形石柱，上顶横置一根石板帽梁。桥墩用3根扁方形石柱立于石基上，上顶横置一根石板帽梁，两侧各有1根斜戗石柱。跨径均为5.90米。如今桥中间塌毁一段。', '', 13, NULL, NULL, '', 8, 2, 5, 1, '宁德市霞浦县松城镇桥头村，跨罗汉溪上', '石材（料石、石板、石柱）', 50, 179, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1856, '通津桥', '通津桥是一座35孔石板梁桥。桥面每孔6根石梁，石梁长约3.50米。桥面宽2.88米，桥长112.50米。桥台的前墙和桥墩是用4根方形石柱构成，中间两根石柱垂直设置，两边的石柱向内倾斜设置。石柱上顶横置一根扁方形帽梁，桥墩的外侧各有一根方形戗柱。跨径3.50米。', '', 13, NULL, NULL, '', 8, 2, 8, 1, '宁德市霞浦县牙城镇杨家溪村，跨杨家溪上', '石材', 50, 180, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1857, '莆田延寿桥', '延寿桥原名“知政桥”,俗称“渡塘桥”。今存延寿桥是一座9孔石板梁桥。桥塊上是阶梯坡道，桥面为平面，每孔5根花岗岩石板梁，石梁宽0.50米，石梁厚0.40米，长8.50米，两侧有节间式石栏杆。桥面宽2.60米，桥长93.50米。桥台是凹字形，前墙长3.20米。桥墩两端是方形，桥墩厚1.00米，桥墩长3.20米。跨径7.50米。', '', 13, NULL, NULL, '', 8, 2, 8, 1, '莆田市城厢区延寿村，跨延寿溪上', '花岗岩', 50, 181, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1858, '宁海桥（又名东济桥）', '宁海桥是一座15孔石板梁桥。桥面由75根巨大石梁架设，每孔5根，石梁厚1.00米，宽1.00米，长10.00—13.00米不等。桥墩上石梁之间铺砌条石，两侧设节间式石栏杆，无地伏。望柱置于石板梁上，石栏板两端有石垫块，桥两端望柱雕有石狮。桥面宽5.80米，桥长225.70米。桥台与桥墩均用方形条石横顺相间砌筑，桥墩两端为尖形。跨径8.80—11.80米。1981年在古桥桥台和桥墩上修筑混凝土墩台，架设混凝土梁及桥面，桥面宽7.00米，两侧各设1.00米宽步道，全长214.30米。', '', 13, NULL, NULL, '', 8, 2, 8, 1, '福建省莆田市荔城区桥兜村，跨木兰溪上（入海口处）', '石梁、条石、混凝土', 50, 182, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1859, '金凤桥', '金凤桥曾名“安利桥”、“卧龙桥”。今存金凤桥是一座11孔石板梁桥。桥面宽2.30米，桥长218.00米。桥台带燕翅形，桥墩两端是尖形。跨径6.80米。', '', 13, NULL, NULL, '', 8, 2, 8, 1, '福建省莆田市仙游县鲤南镇下楼村木兰溪上', '石材', 50, 183, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1860, '仙游南门桥', '南门桥又名“南薰桥”“朱子桥”。桥面宽4.50米，桥长170.00米。桥台是燕翅形，桥墩两端是尖形，跨径均为5.80米。1929年12月5日竣工将上部结构改建为混凝土结构。', '', 13, NULL, NULL, '', 5, 2, 5, 1, '莆田市仙游县鲤南镇柳坑社区，跨兰溪中游虎啸潭上', '石、混凝土', 50, 184, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1861, '石马桥', '原有石马桥是一座19孔等跨径石梁桥，桥面宽2.00米，桥长190.00米。桥台两侧有燕翅墙，桥墩两端是尖形。跨径10.00米。', '', 13, NULL, NULL, '', 7, 2, 7, 1, '莆田市仙游县盖尾镇石马村', '石材', 50, 185, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1862, '洛阳桥（又名万安桥）', '现存洛阳桥是一座47孔石板梁桥。每孔5块石板梁，两侧有石栏杆，共有645根望柱，望柱上有104只石狮子。桥面宽5.00米，净宽4.50米，主桥长731.29米，桥梁全长1106.00米。桥台两侧有燕翅墙，桥墩的边墩两端是短尖，其余44个桥墩是长尖形(船形)，跨径8.00米。桥头有一座石亭子，7座石塔。有历代碑刻多通。', '', 13, NULL, NULL, '', 7, 2, 7, 1, '泉州市惠安县洛阳镇，跨洛阳江入海口处', '石材', 50, 186, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1863, '大德桥', '今存大德桥是一座3孔石板梁桥。桥面每孔是5块石板梁，石梁厚', '', 13, NULL, NULL, '', 8, 2, 8, 1, '泉州市惠安县涂岭乡驿坂村，跨驿坂溪上', '石材', 50, 187, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1864, '40米，石梁宽0.60米，石梁长5.90米，桥面宽3.30米，桥长', '石梁宽0.60米，石梁长5.90米，桥面宽3.30米，桥长 24.00米。 桥台是凹字形，是用方形条石横顺相间砌筑，前墙长4.10米。桥 墩的两端是方形，也是用方形条石横顺相间砌筑，桥墩下部约90厘米， 上顶厚约1.10米，桥墩长4.20米。跨径均为5.30米。', '', 13, NULL, NULL, '', 8, 2, 8, 1, '', NULL, 50, 188, '2026-04-28 23:07:56', '2026-04-28 23:07:56');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1865, '安平桥', '安平桥是一座362孔悬臂梁式石板梁桥。悬臂梁采用三层断面为方形的长条花岗岩石料，各层横顺相间设置。桥面是花岗岩石板梁，每孔有5—8块石板梁，石板梁厚0.50—1.00米，宽0.60—1.00米，石板梁长5.00—11.00米。两侧有节间式石栏杆，无地伏。望柱安装在石板梁上面的方槽中，桥墩上的望柱上顶出头，跨中的望柱上顶不出头，石栏板(单块)的两端插入望柱中。桥面宽3.00—3.40米，桥面长2255.00米，桥梁全长2491.00米。桥台两侧有燕翅墙，桥墩有方形、船形、半船形(上游端是尖形，下游端是方形)三种形式，共计361个桥墩。跨径5.00—11.00米不等。', '', 13, NULL, NULL, '', 5, 2, 5, 1, '福建省晋江市安海镇，在晋江县和南安县交界处，跨于晋江县安海镇和南安县水头镇之间的海湾上', '花岗岩', 50, 189, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1866, '晋江东洋桥', '初建桥为242孔，桥长六百六十余丈(合2198.00米)，桥宽一丈二尺(合4.00米)，桥上有两座亭子。今存东洋桥仅存东段14孔石板梁桥，桥梁不直，弯弯曲曲。桥面为4—7根石梁，石梁厚0.18—0.25米，石梁宽0.38—0.49米，桥面宽度不一致，最窄处1.90米，最宽处2.90米，桥长约66.00米。桥台与河岸砌筑在一起，桥墩两端是方形，跨径约4.80米。', '', 13, NULL, NULL, '', 8, 2, 8, 1, '晋江市安海镇东口外', '石料', 50, 190, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1867, '吟啸桥', '吟啸桥是一座14孔石板梁桥，桥面每孔是5块石板梁，无栏杆。桥面宽3.00米，桥长87.20米。(网络记载：桥长42.60米。) 桥台是凹字形，前墙长5.00米。桥墩两端是方形，桥墩厚1.00—1.20米。最大跨径6.50米，最小跨径6.00米。', '', 13, NULL, NULL, '', 5, 2, 10, 1, '晋江市', '石材', 50, 191, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1868, '泉州石笋桥', '石笋桥又名“履坦桥”“济民桥”“通济桥”。石梁平桥16孔，桥面共用94块石板梁，石板梁厚1.00米，石板梁长14.00米，两侧有石栏杆。桥面宽6.20米，桥长235.00米。桥台是“凹”字形，桥墩两端是方形，跨径均为4.75米。', '', 13, NULL, NULL, '', 5, 2, 5, 1, '泉州市鲤城区浮桥镇', '石材', 50, 192, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1869, '泉州顺济桥', '顺济桥因附近有“顺济宫”取名，又因建于石笋桥之后俗称“新桥”。《八闽通志》记载原桥长一百五十一丈。原桥是一座30孔石梁桥，桥长387.10米。桥台是凹字形，桥墩两端是方形，跨径13.00—14.80米不等。1931年利用原桥墩台改建成混凝土桥面。2010年9月受“凡比亚”台风影响倒塌。', '', 13, NULL, NULL, '', 9, 2, 10, 1, '泉州市鲤城区，跨晋江下游', '石材、混凝土', 50, 193, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1870, '五显桥', '五显桥是一座9孔石板梁桥。桥面每孔5块石板梁，桥上无栏杆，桥面宽3.00米，桥长64.00米。桥台是凹字形，前墙长4.00米。桥墩两端是方形，桥墩厚1.00米，桥墩长4.00米。跨径5.00—6.50米不等。', '', 13, NULL, NULL, '', 10, 2, 10, 1, '泉州市同安县五显镇', '石材', 50, 194, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1871, '五显第一溪桥', '桥面每孔有5块石板梁，石梁厚0.40—0.50米，宽0.60米，石梁长6.00米，桥面宽3.05米，桥长54.30米。桥台是凹字形，用方形条石横顺相间砌筑，前墙长3.60米。桥墩两端是方形，也是用方形条石横顺相间砌筑，桥墩厚约1.50米，长约3.60米。最大跨径6.60米，最小跨径4.80米。', '', 13, NULL, NULL, '', 7, 2, 10, 1, '厦门市同安县五显村，跨布塘溪和西洋溪合流后的东溪上', '石板、方形条石', 50, 195, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1872, '五显第二溪桥', '五显第二溪桥是一座8孔石板梁桥。两侧有石栏杆，上面有石板扶手，扶手下面是方形石柱，每隔一根立柱的下面有地伏。与其相邻的立柱置于石板梁上(每隔一根立柱置于石板梁上),桥面宽7.40—8.90米不等，桥长53.50米。桥台两侧有燕翅墙，用方形条石横顺相间砌筑，前墙上顶伸出3层悬臂石板，在悬臂石板上又砌筑3层石板，跨径3.20—6.20米不等。', '', 13, NULL, NULL, '', 7, 2, 7, 1, '泉州市同安县五显镇安炉村，跨五显溪上', '石材（石板、方形条石）', 50, 196, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1873, '苎溪桥', '苎溪桥是一座9孔厚墩石板梁桥。无栏杆，桥面每孔5块石板梁，石梁厚0.35—0.55米，石梁宽0.40—0.50米，石梁长5.00—7.20米，桥面宽2.60米，桥梁长73.00米。桥台是凹字形，前墙长3.00米。桥墩上游端是尖形，下游端是方形，桥墩顶厚2.50米，桥墩长5.20米。跨径6.70米。', '', 13, NULL, NULL, '', 5, 2, 5, 1, '福建省厦门市集美区后溪镇土楼村，跨苎溪上', '石材', 50, 197, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1874, '薛公桥', '薛公桥原是由4座石梁桥连接而成的一座22孔石梁桥，南第一桥是双孔，桥长25.60米；第二桥是10孔，桥长94.06米；第三桥是9孔，桥长102.78米；第四桥是单孔，桥长11.10米。全桥总长233.54米。桥台是凹字形，桥墩两端是方形，底部较厚而长，上顶较薄而短。跨径由8.20米至12.50米不等。', '', 13, NULL, NULL, '', 8, 2, 8, 1, '福建省漳州市芗城区，跨九龙江西溪上', '石材', 50, 198, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1875, '龙海江东桥', '江东桥原是一座15孔石板梁桥。桥面每孔有石梁4—5根，每根石梁长23.70米，断面是1.70米见方，重约180吨。桥面宽5.10米，桥面长335.00米。桥台是燕翅形，桥墩是船形(两端尖形),桥墩厚5.30米，桥墩长11.40米。跨径均为4.85米。尚存5个旧桥墩，两孔旧桥面。9个旧桥墩下部构造桥墩用0.35米×0.4米×5.2米的条石交错叠砌，呈舰首形，通长11.4米，宽5.3米，以及旧桥台金刚墙，残墙长100.35米。', '', 13, NULL, NULL, '', 10, 2, 10, 1, '龙海市，跨九龙江北溪上游', '条石、混凝土', 50, 199, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1876, '广南桥（龙尾桥）', '广南桥是一座99孔石板梁桥。桥面为花岗岩石板梁，桥面不直顺，总体大致平整，无栏杆，桥面宽8.90米，桥长约530.00米。桥台是凹字形。桥墩两端是方形，跨径3.00—3.60米。', '', 13, NULL, NULL, '', 7, 2, 7, 1, '漳州市诏安县桥东乡桥头村，跨东溪支流洋尾溪上', '花岗岩石板', 50, 200, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1877, '大方何家桥', '桥面宽3.00米，桥长18.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台燕翅形，前墙长4.20 米。拱碹是半圆形纵联式结构，无拱眉，跨径11.60米。', '', 24, NULL, NULL, '', 8, 1, 8, 1, '毕节市大方县柿树村，跨于蚂蚁河上', '料石', 50, 51, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1878, '大方蚂蚁河桥', '蚂蚁河桥是一座单孔石拱桥。桥面宽2.30米，桥长9.36米。侧墙用料石砌筑，上顶有单层仰天石。桥台是燕翅形，前墙长3.50米。拱碹是半圆形纵联式结构，无拱眉。', '', 24, NULL, NULL, '', 8, 1, 10, 1, '毕节市大方县柿树村，跨于蚂蚁河上', '料石', 50, 52, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1879, '织金回龙桥', '回龙桥原名“通济桥”。是一座双孔石拱桥。桥面为平面，桥塊上为坡道，原有石栏杆，今已无存。桥面宽4.50米，桥长20.00米。侧墙用块石砌筑，上顶有单层仰天石。桥台是凹字形。桥墩两端是方形，桥墩宽1.25米，长5.00米。拱碹是半圆形纵联式结构，无拱眉。跨径12.00米。', '', 24, NULL, NULL, '', 8, 1, 8, 1, '毕节市织金县城关镇清泉路东段，跨贯城河上', '石材（块石）', 50, 53, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1880, '织金奢香桥', '今存织金奢香桥是一座3孔石拱桥。桥面宽3.00米，桥长40.00米。侧墙用条形石板砌筑，上顶有单层青石仰天石。桥台是燕翅形，前墙长4.20米。桥墩的两端是尖形，拱碹为半圆形纵联式结构，碹脸外边有拱眉石，碹脸、拱眉与侧墙齐平。中孔跨径15.70米，边孔跨径10.00米。', '', 24, NULL, NULL, '', 7, 1, 7, 1, '毕节市织金县，跨贯城河(古称卜牛河)上', '条形石板、青石', 50, 54, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1881, '织金太平桥（永安桥）', '太平桥是一座双孔石桥。由一孔石拱桥(桥面较高)和一孔石梁桥 (桥面较低)相连而成。西桥是石拱桥，桥面中部(拱顶上)高起为平面，两端是阶梯式坡道，两侧有节间式石栏杆，桥面宽13.50米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形。拱碹是半圆形纵联分段并列式结构，有拱眉，拱眉凸出于碹脸，又凸出于侧墙。跨径23.00米。东桥是石梁桥，桥面是石板梁，无栏杆。桥面宽13.50米。桥梁全长28.50米。东桥的桥台也是凹字形，跨径17.00米。', '', 24, NULL, NULL, '', 8, 1, 8, 1, '贵州省毕节市织金县城关镇贯城河上', '石材（料石、石板）', 50, 55, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1882, '童生桥', '童生桥原名“永安桥”，俗称“下水关”，1962年更名“重兴桥”。桥面中部(拱顶上)高起为平面，两端是阶梯式坡道，两侧有石栏杆，桥面宽7.00米，桥长25.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形。拱碹是半圆形纵联分段并列式结构，有拱眉，跨径19.00米。', '', 24, NULL, NULL, '', 8, 1, 8, 1, '贵州省毕节市织金县城关镇贯城河上', '料石，现已改为混凝土结构', 50, 56, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1883, '兴隆桥（又名\"半边桥\"）', '兴隆桥是一座双孔等跨径石拱桥。桥面为平面，两侧有石板栏杆，桥堍是坡道，桥面宽2.50米，净宽2.10米，桥面长7.00米，全长16.00米。侧墙用块石砌筑，上顶有单层仰天石。桥台是凹字形。桥墩两端是方形，桥墩厚约1.50米，桥墩长3.00米。拱碹是半圆形纵联式结构，无拱眉，跨径4.50米。', '', 24, NULL, NULL, '', 8, 1, 10, 1, '毕节市织金县城关镇小东门', '块石、石板、混凝土', 50, 57, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1884, '月华桥', '月华桥是一座3孔石拱桥。桥面大致呈圆弧形，两侧有石栏杆，桥面宽4.70米，桥长18.50米。侧墙用块石砌筑，上顶有单层仰天石。桥台是凹字形，桥墩两端是方形，桥墩厚约1.10米，桥墩长5.10米。拱碹是半圆形纵联式结构，无拱眉。中孔跨径15.70米，边孔跨径10.00米。', '', 24, NULL, NULL, '', 8, 1, 8, 1, '贵州省毕节市织金县城内跨贯城河上', '石材（块石）', 50, 58, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1885, '仲机桥', '仲机桥是一座单孔石拱桥。桥面上铺砌条形石板，全桥为平面，无栏杆，桥面宽2.50米，桥面长4.00米，全长8.00米。侧墙用块石砌筑，上顶有单层仰天石。桥台建在山脚岩石上。拱碹是半圆形纵联式结构，无拱眉，跨径4.90米，矢高2.50米。', '', 24, NULL, NULL, '', 8, 1, 8, 1, '毕节市织金县三甲白族苗族自治乡三甲村东，跨纳弓河上', '条形石板、块石', 50, 59, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1886, '“玉峡晴虹”双桥', '“玉峡晴虹”双桥的主桥是一座单孔石拱桥。桥面为弧形，两端各有5级台阶，无栏杆。桥面宽6.00米，桥面长8.80米。侧墙是用块石砌筑。桥台建在山脚岩石上，拱碹是圆弧形纵联式结构，有拱眉，拱眉凸出于碹脸，碹脸、拱眉与侧墙平。跨径约8.00米。在桥东岩壁上刻“玉峡晴虹”，在“玉峡晴虹”上方约15米处还有一座很小的石桥，大小二桥统称双桥。', '', 24, NULL, NULL, '', 8, 1, 8, 1, '黔东南苗族侗族自治州黄平县东坡乡晒金石村', '块石', 50, 60, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1887, '安澜桥', '安澜桥是一座单孔石拱桥。桥面为平面，两侧有矮式石栏杆，两端是阶梯式坡道，北坡上有11级台阶，南坡上有12级台阶。桥面宽6.50米，桥长9.90米。侧墙是用块石砌筑，上顶有单层仰天石。桥台建在山崖上，拱碹是半圆形纵联式结构，无拱眉，跨径12.70米。该桥目前已毁无踪。', '', 24, NULL, NULL, '', 8, 1, 8, 1, '黔东南苗族侗族自治州黄平县谷陇镇岩英村西南山涧中', '块石', 50, 61, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1888, '黄平崇德桥（又名“三拱桥”）', '崇德桥原是一座双孔石拱桥。两大孔拱碹之间上面有一个小孔拱碹，如今仅外露一大孔拱碹上部和一个小孔拱碹。大孔拱顶上的桥面较高，为平面，两侧有石栏杆，两端是坡道，北坡道下面有一小孔拱碹。桥面宽7.20米，桥长34.20米。侧墙用块石砌筑，上顶有单层仰天石。桥台和桥墩被埋于河床下，大孔拱碹是半圆形纵联式结构，无拱眉。小孔拱碹是圆弧形纵联式结构，无拱眉。大孔跨径24.00米，小孔跨径7.50米。', '', 24, NULL, NULL, '', 9, 1, 10, 1, '黔东南苗族侗族自治州黄平县老城北门外，跨东门河上', '块石、石材', 50, 62, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1889, '黄平丁未桥', '丁未桥原名“石龙桥”。原有桥面状况不详(无记载)，原桥桥面宽6.80米，桥面长19.87米。侧墙用料石砌筑。桥台与石板砌筑的河岸为一体。拱碹是半圆形纵联式结构，无拱眉，跨径17.80米。', '', 24, NULL, NULL, '', 8, 1, 8, 1, '黔东南苗族侗族自治州黄平县古代滇楚驿道上', '料石、石板', 50, 63, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1890, '福众桥', '福众桥是一座5孔石拱桥。桥堍和桥面铺砌青石板(现在是沥青面)，两侧有石栏杆(改建成混凝土桥栏杆)，原桥桥面宽7.30米，桥面长67.70米。侧墙用料石砌筑，上顶有单层仰天石。桥台是燕翅形，桥墩两端是尖形，拱碹是半圆形纵联式结构，无拱眉，跨径9.20米。', '', 24, NULL, NULL, '', 8, 1, 8, 1, '黔东南苗族侗族自治州黄平县旧州镇', '青石板、料石、沥青、混凝土', 50, 64, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1891, '平播桥', '平播桥是一座单孔石拱桥。桥面为平面，无栏杆，桥面宽5.87米，桥长23.60米。侧墙用块石砌筑。桥台是在山崖上开凿出一段平面。拱碹是半圆形纵联式结构，无拱眉。跨径16.00米。', '', 24, NULL, NULL, '', 8, 1, 8, 1, '黔东南苗族侗族自治州黄平县旧州镇，跨冷水河上', '石材（块石）', 50, 65, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1892, '平龙桥', '平龙桥是一座7孔石拱桥。桥堍和桥面上铺砌石板，全桥为平面，两侧有石栏杆。桥面宽7.25米，桥长79.40米。侧墙用料石砌筑，上顶有单层仰天石。桥台是燕翅形。桥墩两端是尖形。拱碹是半圆形纵联式结构，有拱眉，碹脸、拱眉与侧墙平。跨径7.64米。', '', 24, NULL, NULL, '', 8, 1, 8, 1, '黔东南苗族侗族自治州黄平县苗里河上', '石板、料石', 50, 66, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1893, '圣果桥', '圣果桥原名“东陵桥”。桥面为平面，两端是坡面，两侧有石板栏杆。桥面宽4.32米，桥面长12.20米。侧墙用块石砌筑。桥台建在山脚岩石上。拱碹是圆弧形纵联式结构，无拱眉，跨径16.20米。', '', 24, NULL, NULL, '', 8, 1, 8, 1, '黔东南苗族侗族自治州黄平县城东飞云崖景区，跨秀水溪上', '块石、石板', 50, 67, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1894, '黄平四灵桥', '四灵桥是一座双孔石拱桥。桥面高起为平面，两端是阶梯式坡道。', '', 24, NULL, NULL, '', 8, 1, 8, 1, '黔东南苗族侗族自治州黄平县兴隆街和南街之间，重安观音阁遗址旁，跨皎沙河口', '石材', 50, 68, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1895, '瓮梅河桥（又名“乌梅桥”）', '桥面高起为平面，两侧有石板栏杆，桥塊上是阶梯式坡道，无栏杆。桥面宽6.80米，桥面长26.30米，全长35.00米。侧墙用块石砌筑，上顶有单层仰天石。桥台建在山脚岩石上。桥墩两端是方形，桥墩厚1.20米，桥墩长7.40米。拱碹是半圆形纵联式结构，无拱眉，跨径12.50米。', '', 24, NULL, NULL, '', 8, 1, 8, 1, '黔东南苗族侗族自治州黄平县城西南上塘乡乌梅河村(原名瓮梅河村)，跨乌梅河上', '石材（块石、石板）', 50, 69, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1896, '永宁桥', '永宁桥是一座单孔石拱桥。桥面略显弧形，铺砌青石板，两侧有石栏杆，桥面宽7.06米，桥长14.40米。侧墙用块石砌筑，上顶有单层仰天石。桥台是凹字形。拱碹是半圆形纵联式结构，无拱眉，跨径6.50米。', '', 24, NULL, NULL, '', 10, 1, 10, 1, '黔东南苗族侗族自治州黄平县城北门外，跨苗里河上', '青石板、块石', 50, 70, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1897, '折桂桥', '折桂桥原名“云泉桥”，又名“灵泉桥”，俗称“南门桥”。桥面略显弧形，铺砌青石板，两侧有石栏杆，桥面宽7.50米，桥长12.00米。侧墙用块石砌筑，上顶有单层仰天石。桥台是凹字形。拱碹是半圆形纵联式结构，无拱眉，跨径8.50米。', '', 24, NULL, NULL, '', 9, 1, 10, 1, '贵州省黔东南苗族侗族自治州黄平县南门外', '青石板、块石', 50, 71, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1898, '荔波双溪桥', '双溪桥又名“大七孔桥”。该桥是一座7孔等跨径石拱桥。全桥为平面，桥上无栏杆，两侧各有一道边牙石。桥面宽4.50米，桥长35.00米。侧墙不规则石料砌筑，上顶有单层仰天石。桥台是凹字形，前墙长4.80米。桥墩两端是方形，拱脚四周有小出台，桥墩厚1.25米，桥墩长4.80米。拱碹是半圆形纵联式结构，无拱眉，碹脸与侧墙平。跨径3.50米。', '', 24, NULL, NULL, '', 8, 1, 8, 1, '黔东南苗族侗族自治州荔波县王蒙乡孟塘村孟塘河上', '石料', 50, 72, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1899, '荔波桥', '荔波桥是一座7孔厚拱厚墩重型石拱桥。桥面为平面，无栏杆，无地伏。桥面宽4.00米，桥长50.50米。侧墙用条形石板砌筑，上顶有单层青石仰天石。桥台是凹字形。桥墩两端是方形，桥墩厚1.50米，桥墩长4.50米。拱碹为半圆形纵联式结构，碹脸外边有拱眉石，碹脸、拱眉与侧墙齐平。跨径4.50米。', '', 24, NULL, NULL, '', 8, 1, 10, 1, '黔东南苗族侗族自治州荔波县响水河上（黔桂驿道上）', '条形石板、青石', 50, 73, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1900, '荔波小七孔桥', '全桥为平面，桥上无栏杆，两侧各有一道边牙石。桥面宽2.20米，桥面长40.00米，全长50.00米。侧墙用不规则石料砌筑，上顶有单层仰天石。桥台是凹字形，前墙长3.00米。桥墩两端是方形，拱脚四周有小出台，桥墩厚1.25米，桥墩长3.00米。拱碹是半圆形纵联式结构，无拱眉，碹脸与侧墙平。跨径4.50米。', '', 24, NULL, NULL, '', 8, 1, 10, 1, '黔东南苗族侗族自治州荔波县王蒙乡孟塘村跨涵碧潭上', '石料', 50, 74, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1901, '镇远祝圣桥', '祝圣桥是一座5孔等跨径石拱桥。桥面全桥为平面，两侧有节间式石栏杆，地伏是矩形断面。桥面宽7.00米，桥长数据暂缺。在北起第一墩上建一座木结构三层六角翘檐亭。侧墙用条形石板砌筑，上顶有单层仰天石组成的金边线。桥台与块石砌筑的河岸相连，桥墩两端为尖形，外端高出拱脚一层石板，拱碹是三心圆弧形分段并列式结构，碹脸外边有拱眉石，拱眉与侧墙平。各孔跨径均为12.50米。', '', 24, NULL, NULL, '', 8, 1, 8, 1, '黔东南苗族侗族自治州镇远县', '石材（条形石板、块石）、木材', 50, 75, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1902, '都匀百子桥', '百子桥又名“唐家桥”。该桥是一座7孔等跨径石拱桥。桥面宽8.00米，桥长140.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是燕翅形，前墙长9.00米。桥墩上游端是尖形，下游端是方形，桥墩厚1.50米，桥墩长10.15米。拱碹是半圆形纵联式结构，拱眉凸出于碹脸，拱眉与侧墙平。跨径均为16.00米。', '', 24, NULL, NULL, '', 8, 1, 8, 1, '黔南布依族苗族自治州都匀县', '料石', 50, 76, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1903, '独山深河桥', '深河桥是一座单孔石拱桥。桥面宽5.70米，桥长37.00米。侧墙用条形石板砌筑，上顶有单层青石仰天石。桥台是燕翅形，前墙长6.90米。拱碹为半圆形纵联式结构，碹脸外边有拱眉石，拱眉凸出于碹脸，拱眉与侧墙齐平。跨径19.50米。', '', 24, NULL, NULL, '', 8, 1, 8, 1, '黔南布依族苗族自治州独山县兔场村', '条形石板、青石', 50, 77, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1904, '葛镜桥', '葛镜桥是一座3孔石拱桥。桥面略显圆弧形，两侧有节间式石栏杆，地伏是矩形断面。桥面宽8.50米，桥长51.44米。侧墙用不规则石料砌筑，上顶有单层仰天石组成的金边线。桥台前墙与河岸连砌为一体，桥墩较厚，两端是尖形，拱脚以上为攒尖，高出拱脚许多，桥墩厚2.00米，桥墩长11.00米。拱碹用片石砌筑，属于尖形纵联式结构，无拱眉，碹脸与侧墙平。中孔跨径25.62米，南边孔跨径12.30米，北边孔跨径6.26米。', '', 24, NULL, NULL, '', 7, 1, 7, 1, '黔南布依族苗族自治州福泉市麻哈江上', '石料（不规则石料、片石）', 50, 78, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1905, '吴公桥', '吴公桥亦称“吴家桥”，是一座单孔石拱桥。桥面为平面，无栏杆。桥面宽6.00米，桥面长13.00米。桥下净空约40.00米。', '', 24, NULL, NULL, '', 10, 1, 10, 1, '黔南布依族苗族自治州福泉市吴家村', '石材', 50, 79, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1906, '贵定瓮城桥', '瓮城桥是一座7孔石拱桥。桥面宽6.00米。桥长66.00米。桥上建有木结构亭。侧墙用条形石板砌筑，上顶有单层仰天石。桥台是燕翅形，前墙长7.20米。桥墩的两端是尖形，桥墩厚1.75米，桥墩长8.20米。拱碹为半圆形纵联式结构，碹脸外边有拱眉石，碹脸、拱眉与侧墙齐平。跨径均为8.50米。', '', 24, NULL, NULL, '', 7, 1, 7, 1, '黔南布依族苗族自治州贵定县', '石、木', 50, 80, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1907, '启灵桥', '桥面中部(拱顶上)为平面，两端是阶梯式坡道，两侧有板式石栏杆，无地伏，桥栏杆置于仰天石上。桥面宽4.20米，桥长21.50米。侧墙用不规则石料砌筑，上顶有单层仰天石。桥台建在山崖上。拱碹是圆弧形纵联式结构，无拱眉，碹脸与侧墙取平。跨径7.20米。', '', 24, NULL, NULL, '', 8, 1, 8, 1, '铜仁市石阡县城西，跨龙底江上', '石料', 50, 81, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1908, '瓮安岚关风雨桥', '桥面宽5.00米，桥长30.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是凹字形，前墙长5.30米。拱碹是半圆形纵联式结构，拱眉凸出于碹脸，拱眉与侧墙平。跨径21.00米。', '', 24, NULL, NULL, '', 8, 1, 10, 1, '黔南布依族苗族自治州瓮安县', '料石', 50, 82, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1909, '贵定窑上桥', '窑上桥是一座3孔石拱桥。桥面宽7.20米，桥长96.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台建在山崖上，拱碹是半圆形纵联式结构，无拱眉，跨径21.00米。', '', 24, NULL, NULL, '', 8, 1, 8, 1, '黔南布依族苗族自治州贵定县窑上村', '料石', 50, 83, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1910, '贵阳浮玉桥', '今存浮玉桥是一座7孔石拱桥。由于主河道东边有一分岔儿，主河道与东岔儿之间有一个梭形小岛，岛上建一大桥墩，上面建一座三层式楼阁。小岛西边(主河道上)是6孔，小岛东边(东岔儿上)是1孔。桥面全部为平面，两侧有节间式石栏杆。桥面宽7.00米，桥梁全长92.00米。侧墙用不规则石料砌筑，上顶有单层仰天石。桥台是凹字形，前墙长8.20米，端墙外有燕翅墙。桥墩两端均为尖形，桥墩厚1.35米，桥墩长9.00米。拱碹是半圆形纵联式结构，无拱眉，碹脸与侧墙齐平。跨径均为11.60米。', '', 24, NULL, NULL, '', 7, 1, 7, 1, '贵阳市', '石料', 50, 84, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1911, '日升桥', '日升桥是一座单孔石板梁桥。桥面由10块石板梁铺成，无栏杆，桥面宽5.20米，桥长21.00米。侧墙用块石砌筑。桥台呈凹字形，前墙为前倾式石板。拱碹采用半圆形纵联式结构，无拱眉，跨径为14.20米。', '', 24, NULL, NULL, '', 8, 2, 8, 1, '遵义市织金县城关镇跨贯城河上（当地人称“上水关”）', '石材（块石、石板）', 50, 85, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1912, '永安桥', '永安桥是一座3孔砖石拱桥。桥塊和桥面上横向铺砌青石板，桥面略显隆起。两侧有节间式石栏杆，望柱为方形莲花瓣平顶式柱头，栏板是寻杖下镂空式(寻杖下面是3个方洞),栏杆端是抱鼓石。抱鼓石以外各有一个方形石礅，上面是一只大狮子。桥长32.12米。侧墙用花岗岩石板砌筑，上顶有单层青石仰天石，其外立面的上部是平面，下部是斜面。桥台是燕翅形。桥墩上游端是尖形，下游端是方形。拱碹是半圆形，主拱圈是用砖材砌筑，碹脸是用花岗岩石料，碹脸外边有拱眉石，碹脸、拱眉与侧墙平。中孔跨径3.77米。北面桥墩以上的侧墙上各有一个龙头，南面桥墩以上的侧墙上各有一个龙尾。', '', 6, NULL, NULL, '', 7, 1, 10, 1, '沈阳市于洪区永安村', '青石板、花岗岩、砖', 50, 51, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1913, '龙门桥', '现存龙门桥是一座3孔石拱桥。桥面呈穹隆形，两侧有节间式石栏杆，桥面宽8.00米，桥长170.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台为带燕翅形，前墙长9.00米。桥墩上游端是尖形，下游端是方形，拱碹是半圆形，碹脸外边有双线拱眉石，拱眉凸出于侧墙。中孔跨径26.50米。', '', 22, NULL, NULL, '', 8, 1, 8, 1, '涪陵区', '石材（料石）', 50, 51, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1914, '开州三拱桥', '桥面为平面，原有桥栏杆，今无存。两端是阶梯式坡道，各有24级台阶，无栏杆，桥面宽6.70米，桥长31.00米。桥上建砖木结构廊。侧墙用料石砌筑，上顶有单层仰天石。南端桥台在山脚岩石上开凿而成。北端桥台是凹字形，端墙很长。桥墩两端是方形(两端与拱脚齐平),桥墩厚1.10米，桥墩长7.10米。拱碹是卵形纵联式结构，碹脸外边有拱眉，拱眉凸出于碹脸，拱眉与侧墙平。跨径8.00米。', '', 22, NULL, NULL, '', 7, 1, 7, 1, '开州区三拱桥乡三拱桥村，跨万溶江上', '石材（料石）、砖木结构（廊）', 50, 52, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1915, '开州铁锁桥', '铁锁桥是一座3孔石拱桥。桥面为穹隆形，桥上无栏杆。桥长68.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是燕翅形，桥墩两端是尖形，拱碹是圆弧形纵联式结构，无拱眉。跨径均为15.00米。', '', 22, NULL, NULL, '', 8, 1, 8, 1, '开州区铁桥镇', '料石', 50, 53, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1916, '陆安桥', '桥面中部(拱顶上)高起为平面，两端是较长的阶梯式坡道，两侧有节间式石栏杆，桥面上每侧有4根望柱，3块石栏板。坡道上的栏杆是阶梯形。桥面宽9.40米，桥长41.00米，全长55.00米。桥下净空约15.00米。侧墙用料石砌筑，上顶有双层仰天石。桥台为凹字形，前墙长约9.40米。拱碹是半圆形纵联分段并列式结构，碹脸外边有拱眉石，拱眉凸出于碹脸，又凸出于侧墙。跨径32.40米。在龙门碹上方(金边线下面)两面各有一块石匾，镌刻“陆安桥”三个凹形大字。', '', 22, NULL, NULL, '', 8, 1, 10, 1, '万州区跨苎溪河上', '料石', 50, 54, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1917, '述先桥', '述先桥是一座单孔石拱桥。桥面中部(拱顶上)高起为平面，两端为阶梯式坡道，两侧有节间式石栏杆，每侧有6根望柱，5块石栏板，两块抱鼓石。桥面宽7.33米，桥长48.25米。侧墙用料石砌筑，上顶有单层仰天石。桥台的前墙与石板砌筑的河岸为一体，拱碹是半圆形并列式结构，碹脸外边有拱眉石，拱眉凸出于碹脸，也凸出于侧墙。跨径28.00米，矢高14.00米。', '', 22, NULL, NULL, '', 10, 1, 10, 1, '云阳县盐渠乡', '石材（料石、石板）', 50, 55, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1918, '塔寺桥', '塔寺桥是一座3孔石拱桥。桥面宽8.00米，桥长39.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是燕翅形，前墙长9.00 米。桥墩上游端是尖形，下游端是方形，桥墩厚1.60米，桥墩长10.50 米。拱碹是半圆形纵联式结构，碹脸龙门上皆有龙头，碹脸外有拱眉石，拱眉凸出于侧墙。中孔跨径7.00米，边孔跨径6.00米。', '', 27, NULL, NULL, '', 8, 1, 10, 1, '陕西省宝鸡市凤翔县塔寺河上', '料石', 50, 51, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1919, '韩城毓秀桥（据水桥）', '桥面为穹隆形，两侧有节间式青石桥栏杆，每侧有99根望柱，98块栏板，抱鼓石无存。地伏是青石料，矩形断面。桥面宽4.50米，桥身长180.00米。翼墙和侧墙是用花岗岩石料砌筑，上顶有单层青石仰天石组成的金边线。桥台是燕翅形，前墙长5.50米。桥墩上游端是尖形，分水尖的上部宽度与拱脚同宽，上顶高出拱脚许多。下游端是方形，凤凰台的宽度与拱脚同宽，桥墩的下部周围皆宽出拱脚约15厘米，桥墩长7.00米。拱碹是半圆框形纵联式结构，各孔拱碹的龙门上各有一石雕龙头，碹脸外边有拱眉石，拱眉凸出于碹脸，拱眉与侧墙取平。前墙宽出(拱脚后退于前墙)约15厘米。中8孔跨径15.00米，边孔跨径13.50米。', '', 27, NULL, NULL, '', 8, 1, 8, 1, '韩城市跨据水河上', '青石、花岗岩', 50, 52, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1920, '咸阳沙河桥', '桥塊和桥面上用不规则石板铺砌，桥面大致为平面，两边各有一道边牙石(仰天石),其断面为矩形。桥上无栏杆，青石地伏犹存，为矩形断面。桥长47.30米。侧墙用料石砌筑，上顶有单层仰天石。桥台为凹字形，端墙很短，两侧有块石砌筑的河岸。桥墩上游端是尖形，下游端是方形，桥墩厚1.45米，桥墩长9.70米。拱碹采用片石砌筑，是半圆形纵联式结构，碹脸外镶有拱眉石，拱眉与侧墙取平。跨径均为2.60米。', '', 27, NULL, NULL, '', 8, 1, 8, 1, '咸阳市郊区', '不规则石板、青石、料石、块石、片石', 50, 53, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1921, '三原龙桥', '龙桥俗称“三眼桥”。桥堍和桥面为平面，两侧有节间式石栏杆，地伏为矩形断面。桥面宽11.00米。石桥两端皆有很长的引道，桥梁包括引道全长110.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是燕翅形，前墙长11.00米。桥墩两端是尖形，拱碹是半圆形纵联式结构，无拱眉。跨径均为14.00米。有诗曰“水从碧玉环中过，人在苍龙背上行”。', '', 27, NULL, NULL, '', 7, 1, 7, 1, '咸阳市三原县，跨清河河谷半坡上', '石材（料石）', 50, 54, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1922, '廖公桥', '廖公桥是一座单孔石拱桥。桥上无栏杆，桥面宽5.00米，桥长 10.00米。 侧墙用料石砌筑，上顶有单层仰天石。桥台是燕翅形，前墙长5.00 米。拱碹是半圆形纵联式结构，无拱眉，碹脸与侧墙取平。跨径 6.00米。', '', 27, NULL, NULL, '', 8, 1, 8, 1, '子长市跨清水沟小河上', '料石', 50, 55, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1923, '桥上桥', '桥上桥是一座双层石拱桥。上层桥为9孔，下层桥为7孔，上下桥的桥墩相对。上层桥桥面宽5.00米，桥长70.00米，铺砌花岗岩石板，两侧有节间式石栏杆，望柱柱头为方形，栏板为实体板，下方有矩形断面地伏石。侧墙用料石砌筑，上顶有单层仰天石。桥台为凹字形，前墙长5.00米，桥墩厚1.50米，长5.00米。拱碹均为半圆形纵联式结构，碹脸外边有拱眉石，第二至第八孔北面碹脸龙门上有龙头，南面对应位置有龙尾。下层桥为7孔，桥面宽5.00米，铺砌花岗岩石，侧墙用料石砌筑，桥台和桥墩被埋没，拱碹为半圆形纵联式结构，各孔碹脸龙门处有龙头。上下层桥跨径均为8.50米。', '', 27, NULL, NULL, '', 8, 1, 8, 1, '陕西省渭南市华州区赤水镇赤水河上', '花岗岩石板、料石', 50, 56, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1924, '榆阳桥', '榆阳桥是一座3孔砖石拱桥。桥上有矮墙式砖栏杆，无地伏，桥栏杆砌筑在单层仰天石上。桥面宽8.00米，桥长20.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是燕翅形，前墙长9.00米。桥墩上游端是尖形，下游端是方形，桥墩厚1.35米，桥墩长9.50米。拱碹为半圆形，拱顶距仰天石很高(数十厘米), 无拱眉，跨径3.00米。', '', 27, NULL, NULL, '', 10, 1, 10, 1, '榆林市南门外', '砖、料石、仰天石', 50, 57, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1925, '灞桥', '灞桥是一座67孔石墩台悬臂式木梁桥。上部结构用圆松木做纵梁，直径32—35厘米，每孔13根，纵梁接头下设方木悬臂梁。桥面宽约7.00米，全长354.00米，跨径约6.00米。桥面系由松木桥面板、焦砟石灰或石灰土垫层及花岗岩石板组成。桥台带燕翅形。桥墩主体由6根石柱和石板墩帽构成，每根石柱由4个石子（碌砖）上下对接而成，石子间采取榫卯插接，墩帽石板与石柱间穿有铸铁销子。基础为木桩基础，每根石柱下有11根基础木桩，周围有8根护墩木桩。1955年大修时将墩台用钢筋混凝土加高，改架钢筋混凝土双悬壁梁，增设人行步道及混凝土栏杆。', '', 27, NULL, NULL, '', 8, 2, 3, 1, '陕西省西安市以东，西安至洛阳公路上，跨灞水河上', '松木（纵梁、桥面板）、方木（边梁、悬臂梁）、花岗岩（桥面石板）、青石（墩帽）、石子/碌砖（墩柱）、铸铁（销子、铁锔子）、木桩（基础）', 50, 58, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1926, '北溪桥', '北溪桥是一座单孔组合式木虹桥，桥孔主体由两组木杆件穿插组合而成。第一组由3段圆木杆件(每段7根)和2根方木横系杆件构成梯形门式结构。第二组由4段圆木杆件(每段6根)和3根方木横系杆件组成五边折线形框架。第一组门式结构和五边形框架互相穿插组合成桥孔主体结构，其立面呈五边折线形。在主体结构的两边有圆木剪刀撑和圆木立柱、横梁等辅助杆件。于其上面架设圆木纵梁，上面铺木桥面板。桥面宽4.30米，桥长23.30米。桥上建砖木结构廊。桥台大致是凹字形，用块石砌筑。跨径14.70米。', '', 27, NULL, NULL, '', 9, 6, 10, 1, '丽水市景宁畲族自治县东坑镇汤北村', '圆木、方木、块石、砖木', 50, 59, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1927, '大赤坑桥', '桥孔主体是由两组木杆件组合而成，第一组由3段圆木杆件(每段11根)和两根方木横系杆件构成梯形门式结构。第二组由5段圆木杆件(每段10根)和4根方木横系杆件组成五边折线形框架。第一组门式结构和第二组五边形框架互相穿插组合成桥孔主体结构，其立面呈五边折线形。在主体结构的后背上附设圆木剪刀撑。在主体结构的两边有圆木立柱、横梁等辅助杆件。于其上面架设圆木纵梁，纵梁上面铺木板而成桥面。桥面宽5.00米，桥长36.35米。桥上建木结构廊。借助山崖壁为桥台。跨径30.00米。', '', 27, NULL, NULL, '', 8, 6, 10, 1, '丽水市景宁畲族自治县大赤坑村，跨赤坑溪上', '木材（圆木、方木）', 50, 60, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1928, '景宁大地桥（庆安桥）', '大地桥是一座单孔组合式木虹桥，桥孔主体是由两组木杆件穿插组合而成。第一组由3段圆木杆件(每段9根)和2根方木横系杆件构成梯形门式结构。第二组由5段圆木杆件(每段8根) and 4根方木横系杆件组成五边折线形框架。第一组门式结构和第二组五边形框架互相穿插组合成桥孔主体结构，其立面呈五边折线形。在主体结构的后背上附设圆木剪刀撑。在主体结构的两边有圆木立柱、横梁等辅助杆件。于其上面架设圆木纵梁，纵梁上面铺木板而成桥面。桥面宽4.80米，桥长41.80米。桥上建木结构廊。桥台在山崖壁上开凿，跨径31.10米。', '', 27, NULL, NULL, '', 8, 6, 10, 1, '丽水市景宁畲族自治县沙湾镇大地桥村，跨山涧溪上', '木材（圆木、方木、木板）', 50, 61, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1929, '东坑下桥', '桥孔主体由两组木杆件穿插组合而成。第一组由3段圆木杆件(每段9根)和2根方木横系杆件构成梯形门式结构。第二组由5段圆木杆件(每段8根)和4根方木横系杆件组成五边折线形框架。第一组门式结构和第二组五边形框架互相穿插组合成桥孔主体结构，其立面呈五边折线形。在主体结构的后背上附设圆木剪刀撑。在主体结构的两边有圆木立柱、横梁等辅助杆件。于其上面架设圆木纵梁，纵梁上面铺木桥面板。桥面宽4.40米，桥长28.30米。桥上建木结构廊。桥台在山脚石壁开凿出平台。跨径18.70米。', '', 27, NULL, NULL, '', 8, 6, 8, 1, '丽水市景宁畲族自治县东坑镇东坑村，跨赤坑溪上', '木材（圆木、方木）、石材', 50, 62, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1930, '接龙桥', '接龙桥是一座单孔组合式木虹桥，桥孔主体是由两组木杆件组合而成。第一组由3段圆木杆件(每段11根)和两根方木横系杆件构成梯形门式结构。第二组由5段圆木杆件(每段10根)和4根方木横系杆件组成五边折线形框架。第一组门式结构和第二组五边形框架互相穿插组合成桥孔主体结构，其立面呈五边折线形。在主体结构的后背上附设圆木剪刀撑，在纵梁上面铺木板而成桥面。桥面宽4.80米，桥长38.50米。桥上建砖木结构廊。桥台是凹字形，用料石砌筑。跨径30.70米。', '', 27, NULL, NULL, '', 8, 6, 10, 1, '丽水市景宁畲族自治县东坑镇章坑村', '木材（圆木、方木、木板）、砖、料石', 50, 63, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1931, '岭脚桥', '岭脚桥是一座单孔组合式木虹桥，桥孔主体是由两组木杆件组合而成。第一组由3段圆木杆件(每段9根)和2根方木横系杆件构成梯形门式结构。第二组由4段圆木杆件(每段8根)和4根方木横系杆件组成五边折线形框架。第一组门式结构和第二组五边形框架互相穿插组合成桥孔主体结构，其立面呈五边折线形。在主体结构的后背上附设圆木剪刀撑。在主体结构的两边有圆木立柱、横梁等辅助杆件。于其上面架设圆木纵梁，纵梁上面铺木板而成桥面。桥面宽4.60米，桥长38.60米。桥台是凹字形，用块石砌筑，前墙长约5.00米。跨径27.30米。', '', 27, NULL, NULL, '', 8, 6, 10, 1, '丽水市景宁畲族自治县家地乡芎岱村', '木材（圆木、方木、木板）、块石', 50, 64, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1932, '梅崇桥', '梅崇桥是一座单孔组合式木梁虹桥。桥孔主体由两组木杆件组合而成。第一组由3段圆木杆件(每段9根)和两根方木横系杆件构成梯形门式结构。第二组由5段圆木杆件(每段8根)和4根方木横系杆件组成五边折线形框架。第一组门式结构和第二组五边折线形框架互相穿插组合成桥孔主体结构。在主体结构的背面附设圆木剪刀撑。在主体结构的两边附设圆木立柱、横梁等辅助杆件。于其上面架设圆木纵梁，纵梁上面横顺铺木桥面板。桥面宽5.00米，桥长39.00米。桥上有砖木结构廊。桥台建在山脚下岩石上，用块石砌筑，形式不规则。纵梁的外端搭在山崖壁上。跨径33.40米。', '', 27, NULL, NULL, '', 8, 2, 10, 1, '丽水市景宁畲族自治县英川镇梅崇村，跨英川港上', '木材（圆木杆件、方木横系杆件、圆木纵梁、木桥面板）、砖、块石', 50, 65, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1933, '杨岐桥', '桥孔主体由两组木杆件组合而成。第一组由3段圆木杆件(每段9根)和2根方木横系杆件构成梯形门式结构；第二组由5段圆木杆件(每段8根)和4根方木横系杆件组成五边折线形框架。两组框架互相穿插组合，立面呈五边折线形。主体结构后背附设圆木剪刀撑，两边有圆木立柱、横梁等辅助杆件。上面架设圆木纵梁并铺设木板。桥面宽4.60米，桥长35.00米。桥台为凹字形，用块石砌筑，前墙长5.00米。跨径26.30米。', '', 27, NULL, NULL, '', 9, 6, 10, 1, '丽水市景宁畲族自治县杨岐乡杨岐村，跨梅岐坑溪上', '木材（圆木、方木、木板）、块石', 50, 66, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1934, '永平桥（又名“畲桥”）', '永平桥是一座单孔组合式木虹桥。桥孔主体是由两组木杆件组合而成。第一组是3段圆木杆件(每段8根)和2根方木横系杆件构成梯形门式结构。第二组是5段圆木杆件(每段8根)和4根方木横系杆件组成五边折线形框架。第一组门式结构和第二组五边形框架互相穿插组合成桥孔主体结构，其立面呈五边折线形。在主体结构的背面附设两对圆木剪刀撑。在主体结构的两边有圆木立柱、横梁等辅助杆件。于其上面架设圆木纵梁，上面铺木桥面板。桥面宽5.00米，桥长37.40米。桥上建木结构廊。桥台是凹字形，用块石砌筑，前墙长约5.00米。跨径29.20米。', '', 27, NULL, NULL, '', 8, 6, 8, 1, '丽水市景宁畲族自治县东坑镇平桥村', '木材（圆木、方木）、块石', 50, 67, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1935, '永镇桥', '永镇桥是一座单孔组合式木虹桥。主体是由两组木杆件组合而成。第一组由3段圆木杆件(每段8根)和2根方木横系杆件构成梯形门式结构。第二组由4段圆木杆件(每段7根)和3根方木横系杆件组成五边折线形框架。第一组门式结构和第二组五边形框架互相穿插组合成桥孔主体结构，其立面呈五边折线形。在主体结构的后背上附设圆木剪刀撑。在主体结构的两边有圆木立柱、横梁等辅助杆件。于其上面架设圆木纵梁，纵梁上面铺木板而成桥面。桥面宽4.00米，桥长42.00米。桥台是凹字形，用块石砌筑，前墙长约5.00米。跨径24.00米。', '', 27, NULL, NULL, '', 8, 6, 10, 1, '丽水市景宁畲族自治县金钟乡徐山村', '木材（圆木、方木、木板）、块石', 50, 68, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1936, '顺德桥', '顺德桥是一座单孔组合式木虹桥。桥孔主体是由两组木杆件组合而成。第一组是3段圆木杆件(每段9根)和2根方木横系杆件构成梯形门式结构。第二组是5段圆木杆件(每段8根)和4根方木横系杆件组成五边折线形框架。第一组门式结构和第二组五边形框架，互相穿插组合成桥孔主体结构，其立面呈五边折线形。在主体结构的背面附加两对圆木斜撑。在主体结构的两边设有立柱、横梁等附属杆件。上面架设圆木纵梁，纵梁上面铺木桥面板。桥面宽4.50米，桥长35.00米。桥上建砖木结构廊。桥台是凹字形，用块石砌筑。跨径27.50米。', '', 27, NULL, NULL, '', 8, 6, 10, 1, '龙泉市屏南镇垟顺村，跨垟顺溪上', '圆木、方木、砖、块石', 50, 69, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1937, '怀仁桥', '该桥的桥面基本上是平面。桥孔的立面是五边折线形，其构造是由两组木杆组合而成。第一组是3段并排各为9根的圆木和两根方木横系杆件构成梯形门式结构，也就是撑架式结构。第二组是由5段并排各为8根的圆木和4根方木横系杆件组成五边折线形框架。五边形框架与门式结构互相穿插起来，形成五边折线形组合体。在组合体的背面附设两对圆木剪刀撑。在组合体的两边设置圆木立柱和横梁。于其上面架设圆木纵梁，纵梁上铺木桥面板。桥面宽4.40米，桥全长35.60米。桥上有木结构廊。桥台用块石砌筑，平面是凹字形，前墙长约5.00米。跨径29.54米。', '', 27, NULL, NULL, '', 8, 6, 10, 1, '丽水市青田县岭根乡林坑村，跨山间排水沟上', '圆木、方木、块石', 50, 70, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1938, '安溪桥', '安溪桥是一座单孔组合式木虹桥。桥孔主体是由两组木杆件组合而成，第一组是3段圆木杆件，每段9根，3段圆木杆件之间各有一根方木横系杆件，组成梯形门式结构。第二组杆件是5段圆木杆件，每段8根，5段圆木杆件之间各有1根方木横系杆件，组成五边折线形框架。第一、二两组杆件互相穿插组合成五边折线形组合体。于其上面架设圆木纵梁，纵梁上面铺木板。桥面宽5.00米，桥长41.50米，桥上建砖木结构廊。桥台用块石砌筑，大致是凹字形。跨径32.00米。', '', 27, NULL, NULL, '', 8, 6, 10, 1, '丽水市庆元县安南乡安溪村', '木材（圆木杆件、方木横系杆件、纵梁、木板）、块石（桥台）、砖木（廊）', 50, 71, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1939, '查洋桥', '查洋桥又名“半路亭桥”“云岩桥”。该桥是一座单孔组合式木虹桥。桥孔主体由两组木杆件互相穿插组合而成。第一组是3段圆木杆件和2根方木横系杆件构成梯形门式结构。第二组是5段圆木杆件和4根方木横系杆件组成五边折线形框架。第一组门式结构和第二组五边形框架互相穿插组合成五边折线形桥孔主体结构。上面架设圆木纵梁，纵梁上面铺木桥面板。桥面宽4.90米，桥长28.65米。桥上建砖木结构廊。桥台是在山涧石壁上开凿出的平台。跨径21.25米。', '', 27, NULL, NULL, '', 8, 4, 10, 1, '丽水市庆元县黄田镇陈边村', '木材、砖', 50, 72, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1940, '庆元阜梁桥', '新建的阜梁桥是一座3孔石墩台组合式木虹桥。桥孔主体是由两组木杆件组合而成，第一组是3段圆木木杆件，每段9根，中段水平设置，两端是一对圆木斜撑，3段圆木杆件之间各有一根方木横系杆件，组成梯形门式结构。第二组杆件是5段圆木杆件，每段8根，中段杆件水平设置(架在第一组水平杆件的上面),于其两端各有一对圆木斜撑，下面又是一对圆木斜撑，五段圆木杆件之间各有一根方木横系杆件，组成五边折线形框架。第一、二两组杆件互相穿插组合成五边折线形组合体。于其上面架设圆木纵梁，纵梁上面铺木板，桥面宽5.00米，桥长76.80米。桥上建砖木结构廊。桥台是用料石砌筑，其平面为凹字形。桥墩两端是方形，桥墩厚1.00米，桥墩长6.00米。跨径22.00米(总跨径66.00米)。', '', 27, NULL, NULL, '', 8, 2, 7, 1, '浙江省丽水市庆元县竹口镇竹口溪上（2011年重建于旧桥下游150米处）', '木材（圆木、方木、木板）、料石（桥台）、砖木（廊屋）', 50, 73, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1941, '后坑桥（普渡桥）', '后坑桥是一座单孔组合式木虹桥。桥孔主体是由两组木杆件组合而成，第一组是3段木杆件，每段14根圆木，中段水平设置，两端的两段圆木杆件相对倾斜设置，实际上属于斜撑，三段杆件组成梯形门式结构。第二组杆件是5段圆木杆件，每段13根圆木，中段杆件水平设置，架在第一组水平杆件的上面。上下两层圆木杆件之间，于其两端各置一根圆木横梁，第二组杆件组成的组合体是五边折线形。两组杆件互相穿插组合成五边折线形组合体。该组合体的上面架设圆木纵梁，纵梁上面铺木板而成桥面。桥面宽5.45米，桥长36.20米。桥上建木结构廊。桥台是凹字形，用块石砌筑，前墙长约6.00米。跨径28.50米。', '', 27, NULL, NULL, '', 8, 6, 8, 1, '丽水市庆元县竹口镇枫堂村', '圆木、木板、块石', 50, 74, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1942, '后山桥', '桥孔主体是由两组木杆件组合而成。第一组是3段圆木杆件，每段9根，3段圆木杆件之间有一根方木横系杆件，构成梯形门式结构。第二组是5段圆木杆件，每段8根，5段圆木杆件之间各有一根方木横系杆件，组成五边折线形框架。第一、二两组杆件互相穿插组合成桥孔主体结构，其立面呈五边折线形，于其上面架设圆木纵梁，纵梁上面铺木桥面板。桥面宽5.00米，桥长41.50米。桥上建砖木结构廊。桥台建在山脚下，用块石砌筑，大致为凹字形。跨径32.00米。', '', 27, NULL, NULL, '', 8, 2, 10, 1, '南平市政和县岭腰乡后山村', '木材（圆木、方木）', 50, 75, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1943, '黄水长桥', '桥孔主体由两组木杆件组合而成。第一组是3段圆木杆件和2根方木横系杆件构成梯形门式结构。第二组是5段圆木杆件和4根方木横系杆件组成五边折线形框架。第一组门式结构和第二组五边形框架互相穿插组合成桥孔主体结构。在主体结构的背面设置圆木剪刀撑、立柱和横梁等附属杆件。于其上面架设圆木纵梁，纵梁上面铺木桥面板。桥面宽4.90米，桥长54.30米。桥上建砖木结构廊。桥台是用料石砌筑，大致是凹字形。跨径27.00米。', '', 27, NULL, NULL, '', 8, 6, 8, 1, '丽水市庆元县合湖乡黄水村', '木材（圆木、方木）、砖、料石', 50, 76, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1944, '庆元回龙桥', '回龙桥是一座单孔组合式木虹桥，桥孔主体由两组木杆件互相穿插组合而成。第一组是3段圆木杆件和2根方木横系杆件构成梯形门式结构。第二组是5段圆木杆件和4根方木横系杆件组成五边折线形框架。第一组门式结构和第二组五边形框架互相穿插，组合成五边折线形桥孔主体结构。上面架设圆木纵梁，纵梁上面铺木桥面板。桥面宽4.60米，桥长21.00米。桥上建砖木结构廊。桥台与块石砌筑的河岸为一体。跨径16.30米。', '', 27, NULL, NULL, '', 8, 6, 8, 1, '丽水市庆元县荷地镇石木下村', '圆木、方木、木桥面板、砖、块石', 50, 77, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1945, '兰溪桥', '兰溪桥是一座单孔组合式木虹桥，桥孔主体由两组圆木杆件组合而成。第一组是3段圆木杆件，每段9根，3段之间各有一根方木横系杆件，构成梯形门式结构。第二组是5段圆木杆件，每段8根圆木，5段之间各有一根横系杆件，组成五边折线形框架。两组杆件互相穿插组合成五边折线形结构。于其两边附以圆木剪刀撑、立柱、横梁等辅助杆件，上面架设圆木纵梁，纵梁上面铺木桥面板。桥面宽5.00米，桥长48.12米。桥上建砖木结构廊。桥台是用料石砌筑，其平面是凹字形。跨径36.80米。', '', 27, NULL, NULL, '', 8, 6, 8, 1, '宁德市古田县鹤塘镇溪边村', '圆木、方木、木桥面板', 50, 78, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1946, '庆元蒙淤桥', '桥孔主体由两组木杆件组合而成。第一组由3段圆木杆件(每段9根，中段水平设置)和2根方木横系木杆件构成梯形门式结构。第二组由5段圆木杆件(每段8根，中段杆件水平设置)和4根方木横系木杆件组成五边折线形框架。第一组门式结构和第二组五边形框架互相穿插组合成桥孔主体结构。在主体结构的背面附设圆木剪刀撑。在主体结构的两边设圆木立柱、横梁等辅助杆件。于其上面架设圆木纵梁，纵梁上面铺木板而成桥面。桥面宽4.50米，桥长35.00米。桥上建木结构廊。桥台式凹字形，用块石砌筑，前墙长约5.00米。跨径28.20米。', '', 27, NULL, NULL, '', 8, 6, 10, 1, '丽水市庆元县五大堡乡濛淤村', '圆木、方木、木板、块石', 50, 79, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1947, '濛洲桥', '3孔结构与形式完全相同。桥孔主体由两组木杆件组合而成，桥孔立面为五边折线形。桥面宽5.40米，桥梁全长114.67米。桥上建砖木结构廊和亭。桥台是用块石砌筑，是凹字形。桥墩用料石砌筑，两端是方形。中孔跨径27.30米，边孔跨径26.75米。', '', 27, NULL, NULL, '', 7, 6, 10, 1, '丽水市庆元县五大堡乡濛圩村，跨松源溪上', '木材、砖、块石、料石', 50, 80, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1948, '咏归桥', '咏归桥是一座单孔组合式木虹桥。桥孔主体是由两组木杆件组合而成。第一组是3段圆木杆件(每段9根)和2根方木横系杆件构成，呈梯形门式结构。第二组是5段圆木杆件(每段8根)和4根方木横系杆件组成五边折线形框架。第一组门式结构和第二组五边形框架互相穿插组合成桥孔主体结构，其立面呈五边折线形。在主体结构的背面附设圆木剪刀撑。在主体结构的两边有圆木立柱、圆木横梁等辅助杆件。于其上面架设圆木纵梁，纵梁上面铺木板。桥面宽5.50米，桥长38.76米。桥上建砖木结构廊。桥台用块石砌筑，其平面呈凹字形。跨径21.70米。', '', 27, NULL, NULL, '', 6, 6, 6, 1, '丽水市庆元县松源镇，在水上公园内，跨松源溪和竹坑溪汇合口上', '木材（圆木、方木、木板）、砖木（廊）、块石（桥台）', 50, 81, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1949, '庆元竹坪桥（又名“蜈蚣桥”）', '竹坪桥是一座组合式木虹桥。桥孔主体由两组木杆件组合而成。第一组是3段圆木杆件和2根方木横系杆件构成梯形门式结构。第二组是5段圆木杆件和4根方木横系杆件组成五边折线形框架。第一组门式结构和第二组五边形框架互相穿插，组合成五边折线形桥孔主体结构。上面架设圆木纵梁，纵梁上面铺木桥面板。桥面宽4.48米，桥长36.69米。桥上建砖木结构廊。桥台用块石砌筑，大致为凹字形。跨径18.20米。', '', 27, NULL, NULL, '', 8, 6, 10, 1, '丽水市庆元县左溪镇', '圆木、方木、块石、砖', 50, 82, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1950, '双埕桥', '双埕桥是一座单孔组合式木虹桥。桥孔主体是由两组木杆件组合而成。第一组由3段圆木杆件(每段12根)和2根方木横系杆件构成梯形门式结构。第二组由5段圆木杆件(每段11根)和4根方木横系杆件组成五边折线形框架。第一组门式结构和第二组五边形框架互相穿插组合成桥孔主体结构。在主体结构的背面附设圆木剪刀撑。在主体结构的两边附设圆木立柱、横梁等辅助杆件。于其上面架设圆木纵梁，纵梁上面铺木板而成桥面。桥面宽5.00米，桥长41.00米。桥上建砖木结构廊。桥台是凹字形，用料石砌筑，前墙长5.00米。跨径31.00米。', '', 27, NULL, NULL, '', 10, 6, 10, 1, '浙江省温州市泰顺县仕阳村', '圆木、方木、木板、砖、料石', 50, 83, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1951, '泗溪下桥', '主体是由两组木杆件组成。第一组由3段圆木(每段9根)和2根方木横系杆件构成梯形门式结构。第二组由5段圆木(每段8根)和4根方木横系杆件组成五边折线形框架。门式结构和五边形框架互相穿插起来，形成五边折线形组合体。于其背面附设两对圆木剪刀撑。于其两边附设圆木立柱和横梁等辅助杆件。上面架设圆木纵梁，纵梁上面铺木板而成桥面。桥面宽5.20米，全长50.00米。桥上有木结构廊。桥台是凹字形，前墙长约5.50米。跨径31.00米。', '', 27, NULL, NULL, '', 8, 6, 10, 1, '温州市泰顺县', '木材（圆木、方木、木板）', 50, 84, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1952, '同乐桥（仙洞虹桥）', '同乐桥是一座单孔组合式木虹桥。桥孔主体是由两组木杆件组合而成。第一组由3段圆木杆件(每段12根)和2根方木横系杆件构成梯形门式结构。第二组由5段圆木杆件(每段11根)和4根方木横系杆件组成五边折线形框架。第一组门式结构和第二组五边形框架互相穿插组合成桥孔主体结构。在主体结构的背面附设圆木剪刀撑。在主体结构的两边附设圆木立柱、横梁等辅助杆件。于其上面架设圆木纵梁，纵梁上面铺木板而成桥面。桥面宽5.20米。桥长34.40米。桥上建木结构廊。桥台建在山脚岩石上。跨径23.00米。', '', 27, NULL, NULL, '', 7, 6, 7, 1, '温州市泰顺县岭北乡北村', '木材（圆木、方木）', 50, 85, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1953, '文兴桥', '桥孔主体由两组木杆件组合而成。第一组由3段圆木杆件(每段7根)和2根方木横系杆件构成梯形门式结构。第二组由4段圆木杆件(每段6根)和3根方木横系杆件组成五边折线形框架。第一组门式结构和五边形框架互相穿插组合成桥孔主体结构，其立面呈五边折线形。在主体结构的两边有圆木剪刀撑和圆木立柱、横梁等辅助杆件。于其上面架设圆木纵梁，上面铺木桥面板。桥面宽5.00米，桥长40.20米。桥上建砖木结构廊。桥台用块石砌筑，大致呈凹字形。跨径29.60米。', '', 27, NULL, NULL, '', 8, 6, 10, 1, '温州市泰顺县筱村镇坑边村，跨玉溪上', '木材（圆木、方木）、砖、块石', 50, 86, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1954, '仙居桥', '桥面中部高起，两端的桥面是坡面，桥面系是双层圆木纵梁，纵梁上面横顺铺双层木桥面板。桥面宽 4.89米，桥长42.80米。桥上建有木结构廊。桥梁主体是由两组木杆件组成，第一组是由3段圆木(每段10根) 和2根方木横系杆件构成梯形门式结构。第二组是由5段圆木(每段9 根)和4根方木横系杆件组成五边折线形框架。门式结构与五边折线形框架互相穿插起来，形成五边折线形组合体。于其背面设置两对圆木剪刀撑。于其两边设置圆木立柱和横梁。上面是桥面系。桥台建在山脚基岩上，其平面是凹字形，前墙长约5.00米。跨径 35.10米。', '', 27, NULL, NULL, '', 8, 6, 8, 1, '温州市泰顺县仙稔乡仙居村', '木材（圆木、方木、木桥面板）', 50, 87, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1955, '薛宅桥（锦溪桥）', '薛宅桥是一座单孔组合式木虹桥。桥孔主体是由两组木杆件组合而成。第一组由3段圆木杆件(每段11根)和2根方木横系杆件构成梯形门式结构。第二组由5段圆木杆件(每段10根)和4根方木横系杆件组成五边折线形框架。第一组门式结构和第二组五边形框架互相穿插组合成桥孔主体结构。在主体结构的背面附设圆木剪刀撑。在主体结构的两边附设圆木立柱、横梁等辅助杆件。于其上面架设圆木纵梁，纵梁上面铺木板而成桥面。桥面宽5.20米，桥身长51.00米。桥台与石砌河岸为一体。跨径29.00米。', '', 27, NULL, NULL, '', 8, 6, 10, 1, '温州市泰顺县三魁镇薛宅村营岗店街头', '木材（圆木杆件、方木横系杆件、圆木剪刀撑、圆木立柱、横梁、圆木纵梁、木板）、石材（桥台）', 50, 88, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1956, '营岗店桥', '主体由两组木杆件组成。第一组是3段并排的9根圆木和2根方木构成梯形门式结构，中段圆木水平设置，两端各有1根方木横系杆件，下面是一对(各9根)相对内倾的圆木斜撑，斜撑的下端置于石砌基座上。第二组是5段并排的8根圆木和4根方木组成五边折线形框架。中段圆木水平设置，两端各有1根方木横系杆件，下面是一对(每排各为8根圆木)相对内倾的圆木斜撑，斜撑的下端各有一根方木横系杆件，再下面，又是一对(每排各为8根圆木)相对内倾斜的圆木斜撑，这对斜撑的下端置于石砌基座上。两组木杆件互相穿插组合而成其立面呈五边折线形的组合体，该组合体实际上属于框架。在其背上附设两对剪刀撑，在框架的外边设置圆木立柱和圆木横梁，上面架设圆木纵梁，纵梁上面横顺铺双层木桥面板。桥面宽5.00米，全长33.00米。桥上建砖木结构廊。桥台建在山脚下岩石上，用块石砌筑，形式不规则。纵梁的外端搭在山崖壁上。跨径28.20米。', '', 27, NULL, NULL, '', 8, 6, 10, 1, '温州市泰顺县', '木材（圆木、方木）、块石（桥台、基座）、砖木（廊）', 50, 89, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1957, '多亭桥（又名“店坂桥”“状元桥”）', '多亭桥是一座单孔组合式木虹桥。桥孔主体由两组圆木杆件组合而成。第一组是21根圆木杆件，分为3段，每段7根，中段杆件水平设置，两边的两段杆件向内相对倾斜设置，3段圆木杆件对接处各横置1根方木横系杆件，2段斜置杆件的下端置于用石板砌筑的台基上，构成梯形门式结构。第二组是30根圆木杆件，分为5段，每段6根。五段杆件之间各有1根方木横系杆件，组成五边折线形框架，两组杆件组成立面呈五边折线形结构，于其两边附以圆木剪刀撑、立柱、横梁等辅助杆件，上面架设圆木纵梁，纵梁上面铺木板而成桥面。桥面宽4.70米，桥长32.30米。桥上建砖木结构廊。桥台在山脚岩石上开凿而成。跨径20.30米。', '', 27, NULL, NULL, '', 8, 4, 10, 1, '福州市晋安区日溪乡梓山村', '圆木、方木、石板、木板、砖', 50, 90, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1958, '蕉溪桥', '蕉溪桥是一座单孔组合式木梁桥。主体由两组圆木杆件组合而成。第一组杆件是27根圆木，分为3段，每段9根，中段杆件水平设置，两边的两段杆件向内相对倾斜设置。3段圆木杆件对接处各横置1根方木为横系杆件，两段斜置杆件的下端置于用石板砌筑的台基上，构成梯形门式结构。第二组圆木杆件是40根，分为5段，每段8根。中段杆件水平设置，架在第一组水平杆件的上面，上下两排圆木杆件之间，于其两端各置1根圆木横梁。两边的4段圆木杆件，两两向内相对倾斜设置。5段圆木杆件对接处各横置1根方木为横系杆件，下部的两段斜置杆件，其下端置于用石板砌筑的台基上。两组杆件互相穿插组合成五边折线形组合体，其立面呈五边折线形。五边折线形组合体的上面铺木板而成桥面。桥面宽4.33米，桥长27.30米。桥上建砖木结构廊。桥台是凹字形，建在山崖上。跨径19.20米。', '', 27, NULL, NULL, '', 9, 2, 10, 1, '福州市闽侯县蕉溪村，跨蕉溪上', '圆木、方木、石板、木板、砖木', 50, 91, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1959, '坑坪桥', '坑坪桥是一座单孔组合式木梁桥。桥孔主体是由两组木杆件组合而成。第一组是由3段圆木杆件(每段9根)和2根方木横系杆件构成梯形门式结构。第一组（原文如此，应为第二组）是由5段圆木杆件(每段8根)和4根方木横系杆件组成五边折线形框架。第一组门式结构和第二组五边形框架互相穿插组合成桥孔主体，其立面呈五边折线形。在此主体结构的背后附有两对剪刀撑和立柱、横梁等附属杆件。上面架设圆木纵梁，纵梁上面铺双层木桥面板。桥面宽6.38米，桥长32.10米。桥上有木结构廊。桥台是用块石砌筑，形状不规则。跨径22.70米。', '', 27, NULL, NULL, '', 8, 2, 8, 1, '福州市闽侯县廷坪乡坑坪村，跨村东山涧溪上', '圆木、方木、块石', 50, 92, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1960, '闽侯三溪桥', '桥孔主体是由两组圆木杆件组合而成。第一组是3段圆木杆件(每段9根，共27根)和2根方木横系杆件构成梯形门式结构。第二组是5段圆木杆件和4根方木横系杆件组成五边折线形框架。第一组门式结构和第二组五边形框架互相穿插组合成桥孔主体结构，其立面呈五边折线形。在主体结构的背面附设圆木剪刀撑。在主体结构的两边有圆木立柱、横梁等辅助杆件。于其上面架设圆木纵梁，纵梁上面铺双层木桥面板。桥面宽6.38米，桥长26.10米。桥上有木结构廊。桥台在山脚岩壁上开凿出平台，纵梁的两端搭在山崖上。跨径21.10米。', '', 27, NULL, NULL, '', 8, 2, 10, 1, '福州市闽侯县大湖乡六锦村和坂头村之间，跨山涧溪上', '圆木、方木', 50, 93, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1961, '泰山桥', '泰山桥是一座单孔组合式木虹桥。主体由两组圆木杆件组合而成。第一组圆木杆件是27根，分为3段，每段9根。中段杆件水平设置，两边的两段杆件向内相对倾斜设置，3段圆木杆件对接处各横置1根方木为横系杆件。两段斜置杆件的下端置于用石板砌筑的台基上，构成梯形门式结构。第二组圆木杆件是32根，分为4段，每段8根。4段杆件分上下两部分，上部的两段圆木杆件，相对向内倾斜设置，两段倾斜设置的杆件顶端间有1根圆木横梁；下部的两段圆木杆件也是相对向内倾斜设置。上下两对杆件之间各有1根方木横系杆件，其立面是四边折线形。上述两组杆件组成的组合体立面呈五边折线形，五边折线形组合体的上面架设圆木纵梁，纵梁上面铺木板而成桥面。桥面宽4.30米，桥长27.90米。桥上建木结构廊。桥台建在山脚岩石上。跨径21.60米。', '', 27, NULL, NULL, '', 10, 6, 10, 1, '福州市闽侯县廷坪乡后溪村，跨后溪上', '圆木、方木、石板、木板', 50, 94, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1962, '塘里桥', '塘里桥是一座单孔组合式木虹桥。主体由两组圆木杆件组合而成。第一组圆木杆件是27根，分为3段，每段9根。中段杆件水平设置，两边的两段杆件向内相对倾斜设置，3段圆木杆件对接处各横置1根方木为横系杆件。两段斜置杆件的下端置于用石板砌筑的台基上，构成梯形门式结构。第二组圆木杆件是32根，分为4段，每段8根。4段杆件分上下两部分，上部的两段圆木杆件，相对向内倾斜设置，两段倾斜设置的杆件顶端间有1根圆木横梁；下部的两段圆木杆件也是相对向内倾斜设置。上下两对杆件之间各有1根方木横系杆件，其立面是四边折线形。上述两组杆件组成的组合体立面呈五边折线形，五边折线形组合体的上面架设圆木纵梁，纵梁上面铺木板而成桥面。桥面宽4.40米，桥长28.80米。桥上建木结构廊。桥台是在山脚岩石上开凿成平台。跨径24.80米。', '', 27, NULL, NULL, '', 10, 6, 10, 1, '福州市闽侯县廷坪乡塘里村，跨山涧溪上', '圆木、方木、石板、木板', 50, 95, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1963, '远济桥', '远济桥又名“石陌桥”。桥孔主体由两组木杆件组合而成。第一组杆件是由3段圆木杆件(每段9根)和2根方木横系杆件构成梯形门式结构，两段斜置杆件的下端置于用石板砌筑的台基上。第二组杆件是由5段圆木杆件(每段8根)和4根方木横系杆件组成五边折线形构造体。最下两段斜置杆件的下端置于用石板砌筑的台基上。第一组门式结构和第二组五边形构造体互相穿插组合而成桥孔主体结构，其立面呈五边折线形。于其两边附以圆木剪刀撑和立柱、横梁等辅助杆件，以及纵梁桥面系。桥面宽4.40米，桥长28.80米。桥上建木结构廊。桥台是在山脚岩石上开凿成平台。跨径24.80米。', '', 27, NULL, NULL, '', 8, 2, 8, 1, '福州市闽侯县白沙镇联坑村，跨南山涧上', '木材（圆木、方木）、石板（台基）', 50, 96, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1964, '合龙桥（又名八都桥）', '合龙桥是一座双孔石墩台组合式木虹桥。上部结构是由两组圆木杆件穿插组合而成，第一组杆件是3段并排的圆木，构成梯形门式结构。第二组杆件是4段并排的圆木，组成四边折线形框架，两组杆件穿插组合而成五边折线形桥梁上部主体。上面架设圆木纵梁，纵梁上面铺木桥面板。桥面宽4.35米，桥长53.00米。桥上建木结构廊。桥台是凹字形，用方形条石横顺相间砌筑，端墙后部有燕翅墙，前墙长4.80米。桥墩两端是尖形。跨径是12.50米、14.70米。', '', 27, NULL, NULL, '', 8, 6, 8, 1, '福州市闽清县省璜镇省璜村，跨梅溪河上', '圆木、木、方形条石', 50, 97, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1965, '德胜桥', '德胜桥是一座单孔组合式木虹桥。桥孔主体是由两组木杆件组合而成，第一组是3段圆木杆件，每段8根，3段之间各有1根方木横系杆件，构成梯形门式结构。第二组是5段圆木杆件，每段8根，5段之间各有1根横系杆件，组成五边折线形框架。第一组门式结构和第二组五边形框架互相穿插组合成五边折线形结构。于其两边附以圆木剪刀撑、立柱、横梁等辅助杆件，上面架设圆木纵梁，纵梁上面铺木桥面板，桥面宽4.50米，桥面长36.00米，全长40.00米。桥上建木结构廊。桥台建在山脚岩石上。跨径23.00米。', '', 27, NULL, NULL, '', 8, 6, 8, 1, '南平市建瓯市迪口镇郑魏村', '木材（圆木、方木）', 50, 98, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1966, '后建桥', '后建桥是一座单孔组合式木虹桥。桥孔主体是由两组木杆件组合而成，第一组是3段圆木杆件，每段8根，3段之间各有1根方木横系杆件，构成梯形门式结构。第二组是5段圆木杆件，每段8根，5段之间各有1根横系杆件，组成五边折线形框架。第一组门式结构和第二组五边形框架互相穿插组合成五边折线形结构。于其两边附以圆木剪刀撑、立柱、横梁等辅助杆件，上面架设圆木纵梁，纵梁上面铺木桥面板，桥面宽4.00米，桥长33.00米。桥上建木结构廊。桥台建在山脚岩石上。跨径22.40米。', '', 27, NULL, NULL, '', 8, 6, 8, 1, '南平市建瓯市迪口镇可建村', '木材（圆木、方木）', 50, 99, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1967, '建瓯接龙桥', '接龙桥是一座单孔组合式木虹桥。桥孔主体是由两组木杆件组合而成，第一组是3段并排的圆木，每段9根圆木，3段之间各有一根横系梁，构成梯形门式结构。第二组是5段并排的圆木，每段8根圆木，5段杆件之间各有1根横系梁，组成五边折线形框架。两组杆件互相穿插组合成五边折线形桥梁主体，在主体的背面各加设一对圆木剪刀撑。在主体的两端各立两排圆木立柱，上顶架圆木横梁，主体和横梁上面架设圆木纵梁，上面铺双层木桥面板。桥面宽4.10米，桥长46.00米。桥上建砖廊。桥台建在山脚岩石上。跨径31.50米。', '', 27, NULL, NULL, '', 9, 6, 10, 1, '福建省南平市建瓯市迪口镇龙北溪村，跨迪溪上', '圆木、木桥面板、砖', 50, 100, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1968, '仙恩桥', '桥孔主体是由两组木杆件组合而成，第一组是3段圆木杆件，每段8根，3段之间各有一根方木横系杆件，构成梯形门式结构。第二组是5段圆木杆件，每段7根，5段之间各有1根横系杆件，组成五边折线形框架。第一组门式结构和第二组五边形框架互相穿插组合成五边折线形结构。于其两边附以圆木剪刀撑、立柱、横梁等辅助杆件，上面架设圆木纵梁，纵梁上面铺木桥面板。桥面宽4.30米，桥面长44.00米，梁全长50.00米。桥上建砖木结构廊。桥台建在山脚岩石上。跨径24.50米。', '', 27, NULL, NULL, '', 8, 6, 8, 1, '南平市建瓯市迪口镇郑魏村', '木材（圆木、方木）、砖', 50, 101, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1969, '顺昌岚下桥', '岚下桥原名“石环桥”，原是一座单孔组合式木虹桥。桥孔主体结构是由两组木杆件组合而成。第一组是3段圆木杆件，每段8根，3段原木杆件之间各有1根方木横系杆件，构成梯形门式结构。第二组是5段圆木杆件，每段9根，5段杆件之间各有1根方木横系杆件，组成五边折线形框架。第一、二两组杆件互相穿插组合成桥孔主体，其立面呈五边折线形，在主体构造的背面各加设一对圆木剪刀撑。在主体的两端各立两排圆木立柱，上顶架圆木横梁，主体和横梁上面架设圆木纵梁，上面铺双层木桥面板。桥面宽4.25米，桥长55.00米。桥上建砖木结构廊。桥台是用石板砌筑的不规则形。原桥(北孔)跨径25.80米。南端是一孔简支木梁桥，桥面宽4.25米。桥梁全长51.60米。桥上建砖木结构廊。', '', 27, NULL, NULL, '', 8, 2, 8, 1, '福建省南平市顺昌县岚下乡岚下村跨街河上', '圆木、方木、木桥面板、石板、砖', 50, 102, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1970, '顺昌兴隆桥', '兴隆桥原是一座单孔组合式木虹结构桥。桥孔主体有两组木杆件穿插组合而成。第一组是3段圆木杆件和两根方木横系杆件构成梯形门式结构。第二组是5段圆木杆件和4根方木横系杆件组成五边折线形框架。第一组门式结构和第二组五边形框架互相穿插组合成桥孔主体，在它的两边附加圆木剪刀撑和立柱、横梁等辅助杆件，于其上面架设圆木纵梁，纵梁上面铺木桥面板。桥面宽5.50米。东桥台是用块石砌筑，为凹字形。跨径20.00米。西孔跨滨河路，上部结构是简支木梁桥，桥面宽5.50米，桥梁全长45.30米。桥上建砖木结构廊。西桥台用块石砌筑，也是凹字形。跨径5.00米。', '', 27, NULL, NULL, '', 8, 2, 10, 1, '福建省南平市顺昌县建西镇谢屯村', '圆木、方木、块石、砖', 50, 103, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1971, '武夷山余庆桥（又名“福星桥”，俗称“南门花桥”）', '余庆桥是一座3孔等跨径组合式木虹桥，各孔结构与形式完全相同。桥孔主体由两组木杆件组合而成。第一组是3段圆木杆件，每段11根，3段之间各有1根方木横系杆件，构成梯形门式结构。第二组是4段圆木杆件，每段10根，4段之间各有1根横系杆件，组成四边折线形框架。第一组门式结构和第二组四边形框架互相穿插组合成五边折线形桥孔主体结构。主体结构的背面附以圆木剪刀撑，在主体结构的两边设有圆木立柱、横梁等辅助杆件。主体结构上面架设圆木纵梁，纵梁上面铺木桥面板，桥面宽6.70米，桥梁全长79.00米。桥上建砖木结构廊。桥台用块石砌筑，其平面图形为凹字形。桥墩用料石砌筑，两端是圆形。跨径23.75米。', '', 27, NULL, NULL, '', 8, 6, 8, 1, '福建省武夷山市武夷山景区，跨崇阳溪上', '圆木、方木、木桥面板、砖、块石、料石', 50, 104, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1972, '赤溪桥', '桥孔主体是由两组木杆件组合而成。第一组是3段圆木杆件，每段9根，3段之间各有1根方木横系杆件，构成梯形门式结构。第二组是5段圆木杆件，每段8根圆木，5段之间各有1根横系杆件，组成五边折线形框架。两组杆件互相穿插组合成五边折线形结构。于其两边附以圆木剪刀撑、立柱、横梁等辅助杆件，上面架设圆木纵梁，纵梁上面铺木桥面板，桥面宽4.80米，桥长33.50米。桥台在山脚岩壁上开凿出平台。跨径24.00米。', '', 27, NULL, NULL, '', 8, 6, 8, 1, '南平市政和县澄源乡赤溪村', '圆木、方木', 50, 105, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1973, '洋后桥（又名“洋后厝桥”）', '桥孔主体由两组圆木杆件组合而成。第一组由3段圆木杆件(每段9根，中段杆件水平设置)和2根方木为横系杆件构成梯形门式结构。第二组由5段圆木杆件(每段8根，中段杆件水平设置)和4根方木为横系杆件组成五边折线形框架。第一组门式结构和第二组五边形框架互相穿插组合成桥孔主体结构，其立面呈五边折线形。在主体结构的背面附设圆木剪刀撑。在主体结构的两边附设圆木立柱、横梁等辅助杆件。于其上面架设圆木纵梁，纵梁上面铺木板而成桥面。桥面宽4.86米，桥长39.20米。桥上建砖木结构廊。桥台是凹字形，用方形条石横顺相间砌筑，前墙长4.80米。跨径27.00米。', '', 27, NULL, NULL, '', 8, 2, 10, 1, '福建省南平市政和县外屯村洋后自然村，跨七星溪上', '圆木、方木、木板、砖、方形条石', 50, 106, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1974, '福安棠溪桥', '棠溪桥又名“登烛桥”“井桥”。桥孔主体由两组圆木杆件组合而成。第一组是3段并排的圆木，每段9根圆木，3段之间各有1根横系梁，构成梯形门式结构。第二组是5段并排的圆木，每段8根圆木，5段杆件之间各有1根横系梁，组成五边折线形框架。两组杆件互相穿插组合成五边折线形桥梁主体，在主体的背面各加设一对圆木剪刀撑。在主体的两端各立两排圆木立柱，上顶架圆木横梁，主体和横梁上面架设圆木纵梁，上面铺双层木桥面板。桥面宽4.80米，桥长43.20米。桥上建砖木结构廊。桥台用块石砌筑，形式不规则。跨径36.00米。', '', 27, NULL, NULL, '', 8, 2, 10, 1, '福安市潭头镇棠溪村，跨乡间排水沟上', '圆木、木、砖、块石', 50, 107, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1975, '玉亭桥', '玉亭桥是一座单孔组合式木虹桥。桥孔主体由两组圆木杆件组合而成。第一组是3段圆木杆件，每段9根，3段之间各有1根方木横系杆件，构成梯形门式结构。第二组是5段圆木杆件，每段8根圆木，5段之间各有1根横系杆件，组成五边折线形框架。两组杆件互相穿插组合成五边折线形结构。于其两边附以圆木剪刀撑、立柱、横梁等辅助杆件，上面架设圆木纵梁，纵梁上面铺木桥面板，桥面宽7.30米，桥长31.00米。桥上建木结构廊。桥台建在山脚岩石上。跨径24.30米。', '', 27, NULL, NULL, '', 8, 4, 8, 1, '福安市穆云乡玉林村', '圆木、方木、木桥面板', 50, 108, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1976, '福鼎老人桥', '老人桥是一座单孔组合式木梁桥。桥孔主体是用两组圆木杆件组合而成。第一组是由3段圆木杆件(每段9根)和2根方木横系杆件构成梯形门式结构。第二组是由5段圆木杆件(每段8根)和4根方木横系杆件组成五边折线形框架。第一组门式结构和第二组五边形框架互相穿插组合成桥孔主体结构，其立面呈五边折线形。在主体结构的背面附设圆木剪刀撑。在主体结构的两边附设圆木立柱、横梁等辅助杆件。于其上面架设圆木纵梁，纵梁上面铺木桥面板。桥面宽4.80米，桥长30.40米。桥上建木结构廊。没有桥台，主体结构杆件的下端置于山脚岩石上，纵梁也是搭在山脚岩石上。跨径25.20米。', '', 27, NULL, NULL, '', 8, 2, 8, 1, '福鼎管阳镇西阳村，跨山涧沟上', '木材（圆木、方木）', 50, 109, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1977, '双虹桥', '桥孔主体是由两组木杆件组合而成。第一组是3段圆木杆件，每段9根，3段之间各有1根方木横系杆件，构成梯形门式结构。第二组是5段圆木杆件，每段8根圆木，5段之间各有1根横系杆件，组成五边折线形框架。两组杆件互相穿插组合成五边折线形结构。于其两边附以圆木剪刀撑、立柱、横梁等辅助杆件，上面架设圆木纵梁，纵梁上面铺木桥面板，桥面宽4.60米，桥长35.00米。桥上建木结构廊。桥台用块石砌筑，是凹字形。跨径27.00米。', '', 27, NULL, NULL, '', 10, 6, 10, 1, '宁德市古田县卓洋乡卓洋村', '圆木、方木、块石', 50, 110, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1978, '田地桥', '田地桥是一座单孔组合式木虹桥。桥孔主体是由两组木杆件组合而成。第一组是3段圆木杆件，每段9根，3段之间各有1根方木横系杆件，构成梯形门式结构。第二组是5段圆木杆件，每段8根圆木，5段之间各有1根横系杆件，组成五边折线形框架。两组杆件互相穿插组合成五边折线形结构。于其两边附以圆木剪刀撑、立柱、横梁等辅助杆件，上面架设圆木纵梁，纵梁上面铺木桥面板，桥面宽5.85米，桥长40.75米。桥上建砖木结构廊。桥台是用块石砌筑，形状不规则。跨径32.80米。', '', 27, NULL, NULL, '', 8, 6, 10, 1, '宁德市古田县鹤塘镇田地村，跨霍口溪上', '木材（圆木、方木）、砖、块石', 50, 111, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1979, '亭下桥', '亭下桥是一座单孔组合式木虹桥。桥孔主体是由两组木杆件组合而成。第一组是3段圆木杆件，每段9根，3段之间各有1根方木横系杆件，构成梯形门式结构。第二组是5段圆木杆件，每段8根圆木，5段之间各有1根横系杆件，组成五边折线形框架。两组杆件互相穿插组合成五边折线形结构。于其两边附以圆木剪刀撑、立柱、横梁等辅助杆件，上面架设圆木纵梁，纵梁上面铺木桥面板，桥面宽4.00米，桥长29.20米。桥上建木结构廊。桥台建在山脚岩石上。跨径27.60米。', '', 27, NULL, NULL, '', 8, 6, 10, 1, '宁德市古田县杉洋镇亭下村', '木材（圆木、方木、木桥面板）', 50, 112, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1980, '徐州桥（又名“洙州桥”）', '徐州桥是一座单孔组合式木虹桥。桥孔主体是由两组木杆件组合而成。第一组是3段圆木杆件，每段9根，3段之间各有1根方木横系杆件，构成梯形门式结构。第二组是5段圆木杆件，每段8根圆木，5段之间各有1根横系杆件，组成五边折线形框架。两组杆件互相穿插组合成五边折线形结构。于其两边附以圆木剪刀撑、立柱、横梁等辅助杆件，上面架设圆木纵梁，纵梁上面铺木桥面板。桥面宽5.00米，桥长34.80米。桥上建木结构廊。桥台建在山脚岩石上。跨径30.00米。', '', 27, NULL, NULL, '', 8, 6, 7, 1, '宁德市古田县鹤塘镇前圪村，跨徐州河上', '木材（圆木、方木）', 50, 113, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1981, '百祥桥', '百祥桥是一座单孔组合式木梁桥，桥孔主体由两组圆木杆件组合而成。第一组是3段并排的圆木，每段9根圆木，3段之间各有1根横系梁，构成梯形门式结构。第二组是5段圆木杆件，每段8根圆木，5段之间各有1根横系杆件，组成五边折线形框架。两组杆件互相穿插组合成五边折线形桥梁主体。主体上面架设圆木纵梁，上面铺双层木桥面板。桥面宽4.50米，桥长38.00米。桥上建砖木结构廊。桥台是利用山崖石壁开凿而成。跨径35.00米。', '', 27, NULL, NULL, '', 10, 2, 10, 1, '宁德市屏南县棠口乡下坑尾村与寿山乡白洋村交界处，跨白洋溪上', '圆木、木桥面板、砖、石', 50, 114, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1982, '广利桥', '广利桥是一座单孔组合式木梁桥。桥孔主体由两组圆木杆件组合而成。第一组是3段并排的圆木，每段9根圆木，3段之间各有1根横系梁，构成梯形门式结构。第二组是5段并排的圆木，每段8根圆木，5段之间各有1根横系梁，组成五边折线形框架。两组杆件互相穿插组合成五边折线形组合体。主体上面，架设圆木纵梁，上面铺双层木桥面板。桥面宽4.30米，桥长28.30米。桥上建砖木结构廊。桥台是凹字形，用块石砌筑，前墙长约4.40米。跨径18.20米。', '', 27, NULL, NULL, '', 8, 2, 8, 1, '宁德市屏南县岭下乡岭下村', '圆木、木桥面板、砖木、块石', 50, 115, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1983, '惠风桥', '惠风桥是一座单孔组合式木虹桥，桥孔主体由两组圆木杆件组合而成。第一组是3段圆木杆件(每段9根)和2根方木横系杆件构成梯形门式结构。第二组是5段圆木杆件(每段8根)和4根方木横系杆件组成五边折线形框架。第一组门式结构和第二组五边形框架互相穿插组合成桥孔主体结构，其立面呈五边折线形。在主体的背面加设一对圆木剪刀撑。在主体的两端各立两排圆木立柱，上顶架圆木横梁。主体结构的上面架设圆木纵梁，上面铺双层木桥面板。桥面宽4.50米，桥长32.20米。桥上建木结构廊。桥台建在山脚岩石上。跨径23.50米。', '', 27, NULL, NULL, '', 8, 6, 8, 1, '宁德市屏南县黛溪镇泮地村', '圆木、方木', 50, 116, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1984, '锦溪桥', '锦溪桥是一座组合式木虹桥。桥孔主体由两组圆木杆件组合而成。第一组是3段圆木杆件(每段9根)和2根方木横系杆件构成梯形门式结构。第二组是5段圆木杆件(每段8根)和4根方木横系杆件组成五边折线形框架。第一组门式结构和第二组五边形框架互相穿插组合成桥孔主体结构，其立面呈五边折线形。在主体的背面加设一对圆木剪刀撑。在主体的两端各立两排圆木立柱，上顶架圆木横梁。主体结构的上面架设圆木纵梁。纵梁上面横顺铺木板而成桥面。桥面宽4.30米，桥长37.80米。桥上建砖木结构廊。桥台建在山脚岩石上。跨径21.50米。', '', 27, NULL, NULL, '', 8, 6, 8, 1, '宁德市屏南县溪里村', '圆木、方木、木板、砖木', 50, 117, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1985, '龙井桥', '桥孔主体由两组圆木杆件组合而成。第一组是3段并排的圆木，每段9根圆木，3段之间各有1根横系梁，构成梯形门式结构。第二组是5段并排的圆木，每段8根圆木，5段之间各有1根横系梁，组成五边折线形框架。两组杆件互相穿插组合成五边折线形框架。门式结构和五边折线形框架互相穿插组合成桥孔主体结构，其立面呈五边折线形。在主体结构的背面附设圆木剪刀撑，在主体结构的两边附设圆木立柱、横梁等辅助杆件。于其上面架设圆木纵梁，纵梁上面铺双层木桥面板。桥面宽4.90米，桥长27.50米。桥上建砖木结构廊。桥台是利用山崖石壁开凿而成。跨径22.20米。', '', 27, NULL, NULL, '', 8, 2, 8, 1, '福建省宁德市屏南县寿山乡白玉村', '圆木、砖木、石材', 50, 118, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1986, '屏南千乘桥（又名“祥峰桥”）', '桥长62.70米，桥面宽4.90米。两孔木结构完全相同，桥孔主体结构由两组木杆件穿插组合而成：第一组由3段圆木杆件（每段8根）和2根方木横系杆件构成梯形门式结构；第二组由4段圆木杆件（每段7根）和3根方木横系杆件组成四边折线形框架。两组互相穿插组合成五边折线形桥孔主体结构。背面附设圆木剪刀撑，两边附设圆木立柱、横梁等辅助杆件。上面架设圆木纵梁，铺木桥面板。桥上建砖木结构廊。桥台为凹字形，用方形条石横顺相间砌筑，前墙长7.60米。桥墩两端为尖形。南孔跨径27.70米，北孔跨径26.70米。', '', 27, NULL, NULL, '', 8, 6, 8, 1, '宁德市屏南县海棠口村（棠口），跨塘口溪上', '木材（圆木、方木、木桥面板）、砖木（廊）、方形条石（桥台）', 50, 119, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1987, '清宴桥', '清宴桥是一座单孔组合式木虹桥，桥孔主体由两组圆木杆件组合而成。第一组是3段圆木杆件(每段9根)和2根方木横系杆件构成梯形门式结构。第二组是5段圆木杆件(每段8根)和4根方木横系杆件组成五边折线形框架。第一组门式结构和第二组五边形框架互相穿插组合成桥孔主体结构，其立面呈五边折线形。在主体的背面加设一对圆木剪刀撑。在主体的两端各立两排圆木立柱，上顶架圆木横梁。主体结构的上面架设圆木纵梁。纵梁上面横顺铺木板而成桥面。桥面宽4.50米，桥长26.40米。桥上建木结构廊。桥台建在山脚岩石上。跨径21.80米。', '', 27, NULL, NULL, '', 8, 6, 8, 1, '宁德市屏南县熙岭乡前塘村', '木材（圆木、方木、木板）', 50, 120, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1988, '屏南万安桥', '万安桥原名“公济桥”，又称“长桥”。桥梁全长98.20米，桥面宽4.70米，是一座6孔石墩台组合式木虹桥。桥堍上铺砌条形石板，桥面为平面。桥上建有砖木结构廊。其上部结构由两组圆木杆件穿插组合而成：第一组是3段并排的圆木杆件，每段9根，各段间横置方木，构成梯形门式结构；第二组是5段并排的圆木杆件，每段8根，各段间有方木横系杆件，组成五边折线形框架。两组杆件互相穿插组合成桥梁主体。桥台为凹字形，桥墩两端为方形，均用花岗岩方形条石横顺相间砌筑。桥墩厚2.82米，长4.70米。跨径由东向西依次为15.30米、14.75米、14.75米、13.40米、12.60米、12.60米。', '', 27, NULL, NULL, '', 8, 6, 8, 1, '福建省宁德市屏南县长桥村跨长桥溪上', '花岗岩方形条石（桥台、桥墩）、条形石板（桥堍）、圆木、方木、砖木（廊）', 50, 121, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1989, '樟口桥', '樟口桥是一座单孔组合式木虹桥。桥孔主体由两组圆木杆件组合而成。第一组是3段圆木杆件(每段9根)和2根方木横系杆件构成梯形门式结构。第二组是5段圆木杆件(每段8根)和4根方木横系杆件组成五边折线形框架。第一组门式结构和第二组五边形框架互相穿插，组合成桥孔主体结构，其立面呈五边折线形。在主体的背面加设一对圆木剪刀撑。在主体的两端各立两排圆木立柱，上顶架圆木横梁。主体结构的上面架设圆木纵梁，上面铺双层木桥面板。桥面宽3.80米，桥长26.00米。桥上建木结构廊。桥台建在山脚岩石上。跨径18.50米。', '', 27, NULL, NULL, '', 8, 6, 10, 1, '宁德市屏南县樟源村', '圆木、方木', 50, 122, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1990, '长濑溪桥', '主体是由两组木杆件组合而成。第一组是3段并排的圆木杆件，每段11根圆木，各段杆件之间有1根横方木，构成梯形门式结构。第二组是5段并排的木杆件，每段10根圆木，各段杆件之间有1根横方木，组成五边折线形框架。两组杆件互相穿插组合成五边折线形框架。上面平置木纵梁，纵梁上面铺木桥面板。桥面宽5.40米，桥长39.20米。桥上建木结构廊。桥台建在山脚岩石上。跨径32.00米。', '', 27, NULL, NULL, '', 10, 6, 10, 1, '宁德市寿宁县长濑溪村', '木材（圆木、横方木、木纵梁、木桥面板）', 50, 123, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1991, '大宝桥', '大宝桥是一座单孔组合式木虹桥。桥孔主体是由两组木杆件组合而成。第一组是3段圆木杆件，每段9根，各段杆件之间各有1根方木横系杆件，构成梯形门式结构。第二组是5段圆木杆件，每段8根，5段杆件之间各有一根横方木横系杆件，组成五边折线形框架。第一组门式结构和第二组五边形框架互相穿插组合成五边折线形结构。于其两边附以圆木剪刀撑、立柱、横梁等辅助杆件，上面架设圆木纵梁，纵梁上面铺木桥面板。桥面宽4.60米，桥长44.30米。桥上建木结构廊。桥台建在山脚下，用块石砌筑。跨径33.10米。', '', 27, NULL, NULL, '', 8, 6, 8, 1, '宁德市寿宁县坑底乡小东村', '木材（圆木、方木）、块石', 50, 124, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1992, '寿宁登云桥', '桥孔主体由两组木杆件组合而成。第一组由3段圆木杆件(每段9根)和2根方木横系杆件构成梯形门式结构。第二组由5段圆木杆件(每段8根)和4根方木横系杆件组成五边折线形框架。第一组门式结构和第二组五边折线形框架互相穿插组合成桥孔主体结构。在主体结构的背面附设圆木剪刀撑，在主体结构的两边附设圆木立柱、横梁等辅助杆件。于其上面架设圆木纵梁，纵梁上面铺双层木桥面板。桥面宽4.20米，桥长33.80米。桥上建砖木结构廊。桥台是凹字形，用块石砌筑，前墙长约4.80米。跨径30.80米。', '', 27, NULL, NULL, '', 8, 2, 8, 1, '宁德市寿宁县杨梅桥村', '木材（圆木、方木）、块石、砖', 50, 125, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1993, '飞云桥', '飞云桥又名“后墩桥”“步云桥”。桥梁主体由两组圆木杆件组合而成。第一组圆木是由3段圆木(每段9根)和2根方木横系杆件(3段圆木杆件之间)构成梯形门式结构。第二组杆件是由4段圆木(每段8根)和3根方木横系杆件(4段圆木杆件之间)组成五边折线形构造体。第一组门式结构和第二组四边形框架互相穿插组合而成五边折线形构造体。构造体的背面附设两对圆木剪刀撑，在五边折线形构造体的两边设置立柱和横梁等辅助杆件。上面架设圆木纵梁，纵梁上面铺木桥面板。桥面宽5.30米，桥长29.20米。桥上建木结构廊。木结构的外侧挂木制遮雨板。桥台建在用块石砌筑的河岸上。跨径18.80米。', '', 27, NULL, NULL, '', 8, 2, 10, 1, '宁德市寿宁县鳌阳镇后墩村，跨山涧排水沟上', '圆木、方木、木桥面板、块石', 50, 126, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1994, '福寿桥', '福寿桥是一座单孔组合式木虹桥。桥孔主体结构由两组木杆件组合而成。第一组由3段圆木杆件(每段9根，中段水平设置)和2根方木横系杆件构成梯形门式结构。第二组由5段圆木杆件(每段8根，中段水平设置)和4根方木横系杆件组成五边折线形框架。第一组门式结构和第二组五边形框架互相穿插组合而成桥孔主体结构，其立面呈五边折线形。在主体结构的背面附设圆木剪刀撑。在主体结构的两边附设圆木立柱、横梁等附属构件。于其上面架设圆木纵梁，纵梁上面铺木桥面板。桥面宽4.90米，桥长40.70米。桥上建砖木结构廊。桥台建在山脚下，用块石砌筑。跨径32.8米。', '', 27, NULL, NULL, '', 8, 6, 10, 1, '宁德市寿宁县犀溪乡犀溪村', '木材（圆木、方木）、砖、块石', 50, 127, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1995, '里仁桥（又名“尤溪下桥”）', '里仁桥是一座单孔组合式木虹桥。主体是由两组木杆件组合而成。第一组是3段并排的圆木杆件，每段11根圆木，各段杆件之间各有1根横方木，构成梯形门式结构。第二组是4段并排的木杆件，每段10根圆木。4段杆件分上下两部分，上部的两段杆件向内相对倾斜设置；其顶端之间有1根横向的圆木，该横木置于第一组水平杆件的上面，下部的两端杆件也是向内相对倾斜设置。上下4段杆件之间各有1根方木横系杆件，组成四边折线形框架。两组杆件互相穿插组合成五边折线形框架。上面平置木纵梁，纵梁上面铺木桥面板。桥面宽5.60米，桥长26.40米。桥上建木结构廊。桥台建在山脚岩石上。跨径21.00米。', '', 27, NULL, NULL, '', 8, 6, 10, 1, '宁德市寿宁县芹洋乡尤溪村', '木材', 50, 128, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1996, '鸾峰桥（下党桥）', '鸾峰桥是一座单孔组合式木梁桥。主体由两组圆木杆件组合而成，第一组是3段并排的圆木，每段9根圆木，3段之间各有1根横系梁，构成梯形门式结构。第二组是5段并排的圆木，每段8根圆木，5段之间各有1根横系梁，组成五边折线形框架。两组杆件互相穿插组合成主体结构，其立面呈五边折线形。组合体的上面，架设圆木纵梁，上面铺双层木桥面板。桥面宽4.90米，桥长47.60米。桥上建砖木结构廊。桥台是凹字形，前墙长约5.00米。跨径37.60米。', '', 27, NULL, NULL, '', 8, 2, 10, 1, '宁德市寿宁县下党乡下党村', '圆木、木桥面板、砖木结构', 50, 129, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1997, '寿宁普济桥', '桥孔主体由两组木构件穿插组合而成五边折线形结构。第一组杆件是3段，每段由9根圆木杆件和2根方木横系杆件构成梯形门式结构。第二组杆件是5段，每段由8根圆木杆件和4根方木横系杆件构成五边折线形构造体。第一组梯形门式结构和第二组五边折线形构造体互相穿插组合起来，构成桥孔的主体结构，其立面呈五边折线形。五边折线形主体结构的两边附以圆木剪刀撑和立柱，以及纵梁等桥面系。桥面宽5.00米，桥长25.00米。桥上建砖木结构廊。木结构两旁挂遮雨板。桥台用块石砌筑，大致是凹字形。跨径16.4米。', '', 27, NULL, NULL, '', 10, 6, 10, 1, '宁德市寿宁县南阳镇溪南村', '木材（圆木、方木）、砖、块石', 50, 130, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1998, '寿宁升平桥', '升平桥是一座单孔组合式木梁桥。主体由两组圆木杆件组合而成。第一组圆木杆件是36根，分为3段，每段12根，中段杆件水平设置。两边的2段杆件向内相对倾斜设置，3段圆木杆件对接处各横置1根方木为横系杆件，两段斜置杆件的下端置于用石板砌筑的台基上，构成梯形门式结构。第二组圆木杆件是44根，分为4段，每段11根。4段杆件分上下两部分，上部的2段圆木杆件，相对向内倾斜设置，2段倾斜设置的杆件顶端间有1根圆木横梁；下部的2段圆木杆件也是相对向内倾斜设置。上下两对杆件之间各有1根方木横系杆件，其立面是四边折线形。上述两组杆件组成的组合体立面呈五边折线形，五边折线形组合体的上面架设圆木纵梁，纵梁上面铺木板而成桥面。桥面宽5.60米，桥长25.50米。桥上建木结构廊。桥台是与块石砌筑河岸为一体。跨径23.40米。', '', 27, NULL, NULL, '', 8, 2, 8, 1, '福建省宁德市寿宁县鳌阳镇蟾溪东坝上', '圆木、方木、木板、石板、块石', 50, 131, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (1999, '仙宫桥（又名\"玉带桥\"）', '仙宫桥是一座单孔石台组合式木梁桥。主体由两组圆木杆件组合而成。第一组圆木杆件是33根，分为3段，每段11根，中段杆件水平设置，两边的两段杆件向内相对倾斜设置，3段圆木杆件对接处各横置1根方木横系杆件。两段斜置杆件的下端置于用石板砌筑的台基上，构成梯形门式结构。第二组圆木杆件是40根，分为4段，每段10根，4段杆件分上下两部分。上部的两段圆木杆件，相对向内倾斜设置，两段倾斜设置的杆件顶端间有1根圆木横梁；下部的两段圆木杆件也是相对向内倾斜设置。上下两对杆件之间各有1根方木横系杆件，其立面是四边折线形。上述两组杆件组成的组合体立面呈五边折线形，五边折线形组合体的上面架设圆木纵梁，纵梁上面铺木板而成桥面。桥面宽5.10米，桥长27.00米。桥上建木结构廊。桥台是凹字形，用料石砌筑，前墙长5.10米。跨径24.50米。', '', 27, NULL, NULL, '', 8, 2, 8, 1, '福建省宁德市寿宁县鳌阳镇跨蟾溪上', '圆木、方木、木板、料石、石板', 50, 132, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2000, '小东上桥', '桥孔主体结构由两组木杆件组合而成，第一组是3段圆木杆件(每段9根)和2根方木横系杆件构成梯形门式结构。第二组是5段圆木杆(每段8根)和4根方木横系杆件组成五边折线形框架。第一组门式结构和第二组五边形框架互相穿插组合成桥孔主体，其立面呈五边折线形。在主体结构的背后附有圆木剪刀撑。在主体结构的两边有立柱、横梁等辅助杆件。于其上面架设圆木纵梁，纵梁上面铺木桥面板。桥面宽4.60米，桥长21.40米。桥上建木结构廊。桥台是凹字形，用块石砌筑，前墙长4.60米。跨径16.40米。', '', 27, NULL, NULL, '', 8, 6, 10, 1, '宁德市寿宁县小东村，跨小溪上', '木材（圆木、方木）、块石', 50, 133, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2001, '寿宁杨溪头桥', '横系杆件构成梯形门式结构。第二组由5根圆木杆件(每段9根，中段 水平设置)和4根方木横系杆件组成五边折线形框架。 第一组门式结构和第二组五边形框架互相穿插组合成桥孔主体结构。在主体结构的背面附设圆木剪刀撑。 在主体结构的两边附设圆木立柱、横梁等辅助杆件。于其上面架设圆木纵梁，纵梁上面铺木桥面板。桥面宽5.00米，桥长40.00米。桥上建木结构廊。 桥台建在山脚岩石上。跨径33.40米。', '', 27, NULL, NULL, '', 8, 6, 8, 1, '寿宁杨溪头', '圆木、方木', 50, 134, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2002, '柘荣东源桥', '东源桥又名“水浒桥”。桥孔主体由两组木杆件组合而成。第一组杆件是3段并排的圆木杆件，每段9根圆木，构成梯形门式结构。第二组杆件是五段并排的圆木杆件，每段8根圆木，组成五边折线形框架。第一组门式结构和第二组五边形框架互相穿插组合成桥孔主体结构，其立面呈五边折线形。主体结构的背后附以圆木剪刀撑，在主体结构的两边有立柱、横梁等附属杆件。上面架设圆木纵梁，纵梁上面铺木桥面板。桥面宽6.90米，桥长43.90米。桥上建木结构廊。桥台建在山脚岩石上，用乱石砌筑，形式不规则。跨径25.00米。', '', 27, NULL, NULL, '', 8, 2, 8, 1, '福建省宁德市柘荣县东源乡东源村金砂溪上', '木材（圆木、木杆件、木桥面板）、乱石', 50, 135, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2003, '登龙桥', '登龙桥是一座单孔组合式木梁桥。桥孔主体是由两组木杆件组合而成。第一组由3段圆木杆件和2根方木横系杆件构成梯形门式结构。第二组由5段圆木杆件和4根方木横系杆件组成五边折线形框架。第一组门式结构和第二组五边形框架互相穿插组合成桥孔主体结构。在主体结构的背面附设圆木剪刀撑。在主体结构的两边有圆木立柱、横梁等辅助杆件。于其上面架设圆木纵梁，纵梁上面铺木桥面板。桥面宽4.90米，桥长38.00米。桥上建砖木结构廊。桥台是凹字形。跨径23.50米。', '', 27, NULL, NULL, '', 8, 2, 8, 1, '宁德市周宁县七步镇八蒲村', '木材（圆木杆件、方木横系杆件、圆木纵梁、木桥面板）、砖木（廊）', 50, 136, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2004, '后垄桥', '后垄桥是一座单孔组合式木虹桥。桥孔主体由两组圆木杆件组合而成。第一组是3段圆木杆件，每段9根，3段之间各有1根方木横系杆件，构成梯形门式结构。第二组是5段圆木杆件，每段8根圆木，5段之间各有1根横系杆件，组成五边折线形框架。两组杆件互相穿插组合成五边折线形结构。于其两边附以圆木剪刀撑、立柱、横梁等辅助杆件，上面架设圆木纵梁，纵梁上面铺木桥面板，桥面宽4.80米，桥长36.50米。桥上建木结构廊。桥台建在山脚岩石上。跨径30.20米。', '', 27, NULL, NULL, '', 10, 6, 10, 1, '宁德市周宁县礼门乡后垄村', '圆木、方木、木桥面板', 50, 137, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2005, '德化长寿桥', '长寿桥又名“山茶桥”，是一座单孔组合式木虹桥。桥孔主体由两组木杆件组合而成。第一组是3段圆木杆件，每段9根，中段杆件水平设置，其两端是两排相对内倾的圆木斜撑，3段圆木杆件之间各有1根方木横系杆件，斜撑的下端置于石板砌筑的台基上，构成梯形门式结构。第二组杆件是5段圆木杆件，每段8根，5段圆木杆件之间各有1根方木横系杆件，组成五边折线形框架。第一、二两组杆件互相穿插组合成五边折线形构造体。于其两边附以圆木剪刀撑、立柱、横梁等辅助杆件，上面架设圆木纵梁，纵梁上铺木桥面板。桥面宽4.00米，桥长35.80米。桥上建有砖木结构廊。桥台用块石砌筑，大致是凹字形。跨径25.80米。', '', 27, NULL, NULL, '', 8, 3, 8, 1, '福建省泉州市德化县上涌乡曾坂村，跨山茶水上', '木材（圆木、方木）、石材（石板、块石）、砖', 50, 138, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2006, '霁虹桥', '霁虹桥又名“兰津桥”，是一座单孔铁索桥。主体结构是由18根铁链组成，底索16根，两根合并为一股，边索各1根。在底索上铺双层木桥面板，在边索上立挂木栏杆柱。桥面宽3.80米，桥梁全长113.40米。跨径57.30米。另有资料记载，桥面宽4.00米，桥全长115.00米。跨径56.20米。', '', 27, NULL, NULL, '', 10, 3, 10, 1, '大理白族自治州永平县岩洞乡与保山市平坡乡之间，跨澜沧江上', '铁链、木材', 50, 139, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2007, '泸定桥', '泸定桥是一座单跨铁索桥，全桥主体由13根铁链构成，其中，底索9根，边索各2根，在底索上铺双层木桥面板，在边索内侧安装铁栏杆。桥面宽3.00米，桥长103米。', '', 27, NULL, NULL, '', 8, 3, 8, 1, '甘孜藏族自治州泸定县，跨大渡河上', '铁链、木桥面板', 50, 140, '2026-04-28 23:07:56', '2026-04-28 23:36:29');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2008, '宁安桥', '桥面宽4.50米，桥长25.00米。侧墙用料石砌筑，上顶有单层仰天石。桥台是燕翅形，前墙长5.50米。拱碹是半圆形纵联式结构，无拱眉，碹脸与侧墙取平。跨径 8.00米。', '', 8, NULL, NULL, '', 10, 1, 10, 1, '宁安市', '料石', 50, 51, '2026-04-28 23:07:56', '2026-04-28 23:36:23');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2009, '朝阳门鸾桥', '桥梁最初为双孔石板梁桥，后改建为单孔石台木梁石面桥。桥台带燕翅形，前墙长12.80米，跨径4.15米。桥面全宽11.60米，净宽10.50米，桥面长5.00米，桥梁全长16.40米。两侧设有城砖宇墙式栏杆，厚50厘米，高1.20米。1953年加宽工程中，在桥面两侧添建木结构人行步道，使桥面全宽达到15.20米。上部结构为密排方形木纵梁，纵梁上铺城砖垫层及花岗岩石板。桥基和海墁是在梅花桩基础上铺砌单层花岗岩石板。', '', 1, NULL, NULL, '', 7, 2, 7, 1, '北京市朝阳门外，跨内城东护城河上（朝外关厢路）', '花岗岩石板、城砖、青石、木纵梁、石灰土、梅花桩', 50, 51, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2010, '德胜门鸾桥', '桥面全宽12.80米，净宽11.70米，桥面长5.00米，南北桥堍长6.50米，桥梁全长18.00米。桥台带燕翅形，前墙长14.00米，上游(西侧)燕翅墙长6.50米，下游(东侧)燕翅墙长约9.00米，跨径4.10米。1955年大修时，保留原木纵梁（共28根，含黄松木和黄花松）并进行防腐处理，加铺松木桥面板、焦渣石灰垫层及沥青面层，两侧安装木栏杆。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '北京市德胜门箭楼北面，跨内城北护城河上（德胜门外德胜门清河路）', '花岗岩石板（桥堍、桥面、桥台）、城砖（栏杆、护栏）、青石（墙帽、迎面石、护角石、地伏）、木材（黄松木、黄花松纵梁）、沥青（后期桥面）', 50, 52, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2011, '东直门鸾桥', '桥面全宽9.60米，净宽8.50米，桥面长5.00米，东西桥堍长6.50米，桥梁全长18.00米。桥台两侧有雁翅墙，前墙长11.00米，四角燕翅墙长8.20米，跨径4.15米。两侧有城砖宇墙式栏杆，厚约0.49米，高1.05米，每侧长22.10米。桥台前墙北段有闸板槽。燕翅石墙以外有城砖驳岸，上游（北侧）长9.00米，下游（南侧）长12.00米。', '', 1, NULL, NULL, '', 7, 2, 7, 1, '北京市东直门箭台东面，跨护城河上（东直门外关厢路）', '花岗岩石板（桥面）、城砖（栏杆、驳岸）、青石（墙帽、栏端石、护角石、地伏）、木梁（桥身）、条石（桥脚）', 50, 53, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2012, '阜成门鸾桥', '桥堍和桥面上铺墁花岗岩石板，上部结构是密排方木纵梁。两侧有砖砌宇墙式桥栏杆，下面有青石地伏。栏杆每侧长21.10米，桥身段栏杆长6.10米，八字栏杆长均为7.50米。桥面全宽9.90米，净宽8.80米，桥面长5.10米，东西桥堍长6.50米，桥梁全长18.10米。桥台带燕翅形，前墙近北端处有闸板槽（距北端约1.65米），前墙长11.30米，四角燕翅墙长7.70米。跨径4.15米。燕翅墙以外皆有城砖砌筑的驳岸。桥面以东有石板道，绕过瓮城北面与闸门内的石板道相连。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '北京市阜成门外大街，跨内城西护城河上', '花岗岩石板（桥堍和桥面）、方形松木（纵梁）、砖（宇墙式栏杆）、青石（地伏）、条石（桥脚）、城砖（垫层及驳岸）', 50, 54, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2013, '广安门鸾桥', '桥面全宽12.00米，净宽10.90米，桥面长5.00米，东西桥堍长5.80米，桥梁全长16.60米。两侧有城砖砌宇墙式桥栏杆，下有青石地伏。每侧栏杆长19.00米，桥身段栏杆长7.20米，八字栏杆均为5.90米。桥台带燕翅形，前墙长13.80米，上游(北)燕翅墙长7.80米，下游燕翅墙长6.95米。跨径4.00米。桥下和桥区有石板海墁。1955年拆除砖栏杆，在桥面两侧修建木结构人行步道并安装木栏杆。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '北京市广安门外，跨外城西护城河上，广安门外关厢路', '花岗岩石板（桥堍、桥面、桥台）、黄松木（纵梁）、城砖（栏杆、驳岸、桥面铺层）、青石（地伏）', 50, 55, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2014, '广渠门鸾桥', '广渠门鸾桥是一座闸桥合一的单孔石台木梁石面桥，水闸位于南侧。桥堍和桥面上铺砌花岗岩石板，上部结构为密排方形木纵梁。桥两侧设有城砖宇墙式栏杆，下有青石地伏，上有青石墙帽，两端设迎面石，折角处设护角石。栏杆厚0.49米，高0.90米，每侧长17.60米。桥面全宽9.30米，净宽8.00米，桥面长约5.10米，东西桥堍各长5.50米，桥梁全长16.10米。桥台呈燕翅形，前墙长12.80米，燕翅墙长约6.00米，跨径4.15米。桥下及桥区设有石板海墁，海墁北边有二级跌水，燕翅墙外连有城砖驳岸。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '北京市广渠门外，跨外城东护城河上', '花岗岩石板、方形木纵梁、城砖、青石', 50, 56, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2015, '西便门鸾桥', '西便门鸾桥是一座闸桥合一的石台木梁石面桥，水闸在东面，闸台上有铰关石架。桥堍和桥面上铺砌花岗岩石板，上部结构是密排方形木纵梁。两侧有城砖宇墙式桥栏杆，下面有青石地伏。每侧栏杆长18.00米，其中桥身段栏杆长7.80米。桥面全宽6.10米，净宽4.80米，桥面长(纵梁长)5.10米。南北桥堍长6.50米，桥梁全长18.10米。桥面南端有花岗岩石板道，直通便门内。桥(闸)台的两侧有燕翅墙，前墙全长9.70米。跨径4.15米。桥下和桥区有石板海墁，海墁西边有跌水。1952年加宽后，桥面全宽为9.50米，车行道宽7.50米。', '', 1, NULL, NULL, '', 7, 2, 10, 1, '北京市西便门外，跨外城的西北护城河上', '石台、木梁、花岗岩石板、城砖、青石、圆木、沥青', 50, 57, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2016, '西直门鸾桥', '桥面全宽9.60米，净宽8.50米，桥面长5.00米，东西桥堍长6.50米，桥梁全长18.00米。桥台两侧有雁翅墙，前墙长11.00米，跨径4.10米。1950年加宽工程中，拆除城砖桥栏杆，在桥面两侧现场浇筑混凝土T形梁，上面铺装步道，外侧安装混凝土分段式桥栏杆，旧石板桥面上满铺沥青面层。1954年因西直门外大街改扩建被拆除，在原位新建临时性木桥。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '北京市西直门外关厢路，跨内城西护城河上', '花岗岩石板（桥堍和桥面）、城砖（栏杆）、青石（墙帽、迎面石、地伏）、木方形纵梁、混凝土、沥青', 50, 58, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2017, '永定门鸾桥', '桥面全宽8.15米，净宽7.00米，桥面长5.00米，南北桥堍长6.50米，桥梁全长18.00米。桥(闸)台是燕翅形，前墙长10.90米(闸台长2.05米)，上游燕翅墙长约7.90米，下游燕翅墙长约8.50米。跨径4.05米。桥下和桥区有石板海墁，海墁下游边是一道跌水。四角燕翅墙以外均有很长的石砌驳岸，石砌驳岸以外还有一段城砖驳岸。桥南有一段石板道，桥北的石板道直通城门洞。水闸在桥面西侧，闸台上无绞关石架。两侧有城砖砌宇墙式桥栏杆，下面有青石地伏，每侧栏杆长21.00米。', '', 1, NULL, NULL, '', 7, 2, 10, 1, '北京市永定门箭楼南面，跨外城南护城河上，永定门外永外关厢路', '花岗岩石板（桥堍和桥面）、木纵梁（上部结构）、条石（桥脚）、城砖（宇墙式桥栏杆）、青石（地伏）', 50, 59, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2018, '右安门鸾桥', '该桥为单孔石台木梁桥。桥堍和桥面上铺墁花岗岩石板，两侧有板式青石栏杆，下有青石地伏。每侧栏杆长14.20米，桥身上栏杆长5.60米。纵梁为密排方形木梁。桥面全宽8.10米，净宽7.40米，桥面长约4.85米，桥梁全长约14.00米。桥台带燕翅形，用花岗岩石板砌筑，前墙长9.50米，跨径约为4.15米。四角燕翅墙以外有城砖砌筑的驳岸。1954年加宽工程中，西侧加宽2.50米，东侧加宽1.50米，在燕翅墙上搭设叠合圆木梁，铺设木桥面板及沥青面层。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '北京市右安门外，跨于外城南护城河上（右安门草桥路）', '花岗岩石板（桥堍、桥面、桥台）、青石（栏杆、地伏）、方形木梁（纵梁）、城砖（驳岸）', 50, 60, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2019, '左安门鸾桥', '该桥为闸桥合一结构，水闸位于桥面西侧。桥堍和桥面上铺砌花岗岩石板，上部结构为密排方形木纵梁。两侧设有城砖宇墙式桥栏杆，配有青石墙帽、青石迎面石、护角石及青石地伏。栏杆厚0.50米，高1.10米，每侧长20.50米，桥身段长10.20米。桥面全宽8.15米，净宽6.85米，桥面长5.15米，南北桥堍长4.90米，桥梁全长15.00米。桥台呈燕翅形，闸台上有绞关石架，前墙全长11.20米，跨径4.15米。桥下及桥区铺有石板海墁，海墁东边有跌水。桥面以北有宽4.50米的花岗岩石板路直通城门洞。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '北京市左安门外，跨外城南护城河上（左安门分钟寺路）', '石台、木梁、花岗岩石板、城砖、青石', 50, 61, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2020, '分水亭桥', '分水亭桥是一座单孔石台木梁桥。上部结构是圆木纵梁，纵梁上铺双层木桥面板(下层横铺，上层顺铺),木板上铺墁城砖面层。两侧有节间式木栏杆。桥面宽3.70米，桥长10.27米。桥台为凹字形，前墙上面有两层石板悬臂梁。木纵梁净跨径7.97米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '临汾市洪洞县广胜寺前，跨霍泉河上', '圆木（纵梁）、木（桥面板）、城砖（面层）、石（桥台）', 50, 62, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2021, '万安桥（又名“万安亭桥”）', '万安桥是一座3孔石墩台木梁桥。中孔桥面较高为平面，边孔桥面为坡面，两侧有木栏杆，桥面净宽2.60米，桥长29.00米。桥台是凹字形，前墙长3.00米。桥墩两端是方形，桥墩厚90厘米，桥墩长3.00米。中跨径4.20米，边孔跨径2.80米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '青浦县金泽镇', '石（墩台）、木（梁、栏杆）', 50, 63, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2022, '迎祥桥', '迎祥桥是一座5孔石墩台木梁砖面桥。桥面呈圆弧形，上部结构是圆木纵梁，梁上横铺木桥面板，木板上面铺砌砖面层。无栏杆，桥堍上是瓮砖礓礤坡道。桥面宽2.41米，桥面长30.75米，全长34.25米。桥台是凹字形，用料石砌筑，前墙是两根方形石柱，上顶有石盖梁，盖梁长约3.30米。桥墩也是两根方形石柱，上顶有石盖梁，盖梁长3.30米。中孔跨径6.40米，次边孔跨径5.00米，边孔跨径4.30米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '青浦县金泽镇南栅村，跨市河下游段', '石材（墩台、桥台料石、方形石柱、盖梁）、木材（纵梁、桥面板）、砖（面层、瓮砖）', 50, 64, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2023, '余庆桥', '余庆桥是一座3孔石墩台木梁砖面桥。上部结构是圆木纵梁，每孔5根梁，木梁直径30厘米，梁上横铺5厘米厚木桥面板，木板上平铺两层青砖，上面又铺砌梵砖面层。中孔桥面高起，边孔桥面较低，中孔桥面两端有坡道与边孔桥面相连。无栏杆，桥面宽2.61米，中部桥面长4.83米，西坡道桥面长5.36米，东坡道桥面长4.43米。西桥塊长2.10米，东桥塊长6.90米，桥梁全长34.25米。桥台是凹字形，用料石砌筑，前墙是两根方形石柱，上顶有石盖梁，盖梁长约3.10米。桥墩也是两根方形石柱，上顶有石盖梁，盖梁长约3.10米。中孔净跨径(中—中)5.36米，边孔跨径4.83米。', '', 1, NULL, NULL, '', 10, 2, 10, 1, '青浦县溪塘镇四农村跨市河上', '石、圆木、木板、青砖、梵砖、料石', 50, 65, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2024, '太湖龙门桥', '龙门桥是一座单孔石台悬臂式木梁桥。上部结构是圆木纵梁，上面铺双层木桥面板，桥上建有木结构廊。桥面宽3.70米，桥长20.00米。桥上建砖木结构亭。桥台是用石板砌筑，凹字形。跨径14.50米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '安庆市太湖县', '石板、圆木、木、砖', 50, 66, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2025, '回龙桥', '回龙桥原名“清绕桥”,又名“龙春桥”,明代称“回龙桥”。桥梁全长80.00米。中孔是石拱桥，桥面中部(拱顶上)高起为平面，两端是阶梯式坡道，两侧有石栏杆，桥面宽4.40米，桥长20.00米。西边孔是悬臂式木梁结构，悬臂梁上架设圆木纵梁，纵梁上铺木桥面板，桥面宽4.40米，桥长30.00米。东边孔是三层圆木叠合纵梁结构，纵梁上铺木桥面板，桥面宽4.40米，桥长30.00米。中孔上建砖木结构亭，两边孔上各建一座砖木结构阁，统称“文昌阁”。桥台是用块石砌筑，属于不规则形。桥墩两端是方形。中孔跨径16.50米，边孔跨径4.10米。', '', 1, NULL, NULL, '', 8, 2, 10, 1, '邵阳市城步苗族自治县长安营乡大寨村，跨中流河上', '木材（圆木、木板）、石材、砖', 50, 67, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2026, '高阳桥', '高阳桥是一座3孔石墩台简支木梁桥。上部结构是圆木纵梁，纵梁上面铺木桥面板，桥面宽4.00米，桥长15.00米。桥上建砖木结构廊。桥台是凹字形，用料石砌筑，前墙长4.00米。桥墩也是用料石砌筑，两端是方形。跨径5.20米。', '', 1, NULL, NULL, '', 10, 2, 10, 1, '黄山市歙县许村', '圆木、木桥面板、砖木、料石', 50, 68, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2027, '休宁拱北桥', '拱北桥是一座5孔石墩台简支木梁桥。上部结构是双层圆木纵梁，纵梁上面铺木桥面板。桥面宽5.00米，桥长70.70米。桥上建有木结构廊。桥台是凹字形，桥墩两端为方形，桥墩厚2.50米。最大两孔跨径13.00米，其余3孔跨径9.50米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '黄山市休宁县北市塘乡岭下村', '石、木', 50, 69, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2028, '咸丰土溪河桥', '桥塊上是阶梯式坡道，桥梁上部结构是两根圆木叠合式纵梁，上面铺木桥面板而成桥面。桥面宽 3.40米，桥面长19.00米，桥全长31.00米。桥上建砖木结构廊。桥台两侧有燕翅墙，用料石砌筑，前墙长约3.50米。跨径18.30米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '恩施土家族苗族自治州咸丰县活龙坪乡水坝村', '料石（桥台、燕翅墙）、圆木（纵梁）、木（桥面板）、砖木（廊）', 50, 70, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2029, '九道水凉桥', '九道水凉桥是一座单孔石墩台简支木梁桥。桥塊上是阶梯式坡道，上部结构采用双层圆木叠合式纵梁，上面铺木桥面板而成桥面。桥面宽 4.00米，桥全长14.00米。桥上建砖木结构廊。桥台两侧与石砌河岸为一体。跨径11.00米。', '', 1, NULL, NULL, '', 8, 2, 10, 1, '恩施土家族苗族自治州咸丰县芭蕉乡石板溪村', '石材、木材、砖', 50, 71, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2030, '咸丰太阳河桥', '咸丰太阳河桥（文中亦称斩龙桥）是一座4孔石墩台简支木梁桥。纵梁采用两根圆木叠合梁，上面铺木桥面板而成桥面。桥面宽4.00米，桥全长44.80米。桥上建砖木结构廊。桥台两侧有燕翅墙，用料石砌筑，前墙长约4.00米。桥墩两端是尖形。跨径6.80米。', '', 1, NULL, NULL, '', 8, 2, 10, 1, '太阳河上', '料石、圆木、木桥面板、砖', 50, 72, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2031, '驼背经桥', '驼背经桥是一座7孔石墩台简支木梁桥。每孔9根圆木纵梁，上面铺木桥面板而成桥面。桥面宽5.40米，桥全长55.00米。桥台是凹字形，用料石砌筑，前墙长约6.00米。桥墩两端是方形，跨径6.50米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '咸宁市通山县杨芳林乡太平庄村跨杨芳河上', '料石、圆木、木桥面板', 50, 73, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2032, '通山小源桥', '小源桥是一座3孔石墩台简支木梁桥。上部结构是圆木纵梁，纵梁上面铺木桥面板，桥面为平面，桥面宽4.20米，桥全长20.00米。桥上建砖木结构廊。桥台与石砌河岸为一体。桥墩两端是尖形，跨径4.75米。', '', 1, NULL, NULL, '', 7, 2, 7, 1, '湖北省咸宁市通山县闯王镇小源口村', '石、木、砖', 50, 74, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2033, '杨芳桥', '杨芳桥是一座3孔石墩台简支木梁桥。每孔9根双层圆木纵梁，上面铺双层木桥面板。桥面宽5.80米，桥全长30.00米。桥台与石砌河岸为一体。桥墩两端是方形，跨径7.80米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '咸宁市通山县杨芳林乡田铺村', '石、木', 50, 75, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2034, '三合桥', '桥面宽2.50米，桥长60.00米。桥上建砖木结构榭亭。桥台是燕翅形，前墙长约3.50米。桥墩上游端是尖形，下游端是方形。跨径均为8.50米。', '', 1, NULL, NULL, '', 8, 2, 10, 1, '湖南省郴州市北湖区华塘镇三合村，跨三条河流交汇处的西河上', '石（墩台）、木（梁）、砖木（榭亭）', 50, 76, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2035, '洪江倒湾桥', '倒湾桥是一座3孔石墩台简支木梁桥。桥塊上是阶梯式坡道，上部结构是双层圆木叠合纵梁，桥面宽4.00米，桥面长20.00米，全长27.00米。桥上建砖木结构廊和亭。桥台是燕翅形，用青石板砌筑。桥墩两端是尖形，也是用青石板砌筑。跨径6.00米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '洪江市大龙田村，跨双岔溪上', '青石板、圆木、砖木结构', 50, 77, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2036, '株竹桥', '株竹桥是一座6孔石墩台简支木梁桥。每孔8根圆木纵梁，上面铺木桥面板。两侧有木栏杆，栏杆内侧有木凳，桥面宽6.60米，桥长32.00米。桥台是燕翅形，用青石板砌筑。桥墩两端是尖形，也是用青石板砌筑。跨径5.00米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '洪江市雪峰镇株竹村，湘黔古驿道上', '圆木、木、青石板', 50, 78, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2037, '观月桥', '观月桥是一座双孔石墩台简支木梁桥。上部结构是双层圆木叠合式纵梁，上面横铺木桥面板。桥面宽5.38米，全长24.10米。桥上建木构架廊。桥台是燕翅形，前墙长约6.00米。跨径均为11.00米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '怀化市通道侗族自治县陇城镇路塘村村口', '石（墩台）、木（梁、面板、构架廊）', 50, 79, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2038, '回福桥', '回福桥是一座双孔石墩台简支木梁桥。上部结构是双层圆木叠合式纵梁，梁上横铺木桥面板。桥面宽3.86米，桥全长42.50米。桥上建木结构廊。桥台是凹字形，前墙长约4.00米。桥墩两端是方形。跨径均为11.00米。', '', 1, NULL, NULL, '', 8, 2, 10, 1, '怀化市通道侗族自治县坪坦乡高楼村郊外', '石、木', 50, 80, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2039, '普修桥', '普修桥是一座5孔石墩台悬臂式木梁桥。上部结构是圆木纵梁，纵梁下面两端各有3层原木悬臂梁，悬臂梁之间有方木横系杆件。纵梁上面铺双层木桥面板，木板上铺墁砖面层。桥面宽7.00米，桥长45.00米。桥上有木结构通廊，每个桥墩上有一座砖木结构塔。桥台是凹字形，端墙外有燕翅墙，桥墩两端为尖形。中孔跨径20.00米，次边孔跨径19.00米，边孔跨径18.00米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '怀化市通道侗族自治县皇都乡', '石（墩台）、圆木（纵梁）、原木（悬臂梁）、方木（横系杆件）、木（桥面板）、砖（面层）', 50, 81, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2040, '通道文星桥', '文星桥是一座单孔简支木梁桥。桥堍上是阶梯式坡道，上部结构是双层圆木叠合纵梁，上面横铺木桥面板。桥面宽3.50米，桥面长9.00米，全长22.40米。桥上建穿斗式木构架廊。桥台是凹字形，前墙长3.50米。跨径8.00米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '怀化市通道侗族自治县坪坦乡阳烂村', '木材', 50, 82, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2041, '永福桥', '桥面宽3.80米，桥长19.32米。桥上建木构架廊。桥台是燕翅形，前墙长约5.00米。跨径16.20米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '怀化市通道侗族自治县坪坦乡高上村', '石、木', 50, 83, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2042, '中步二桥', '中步二桥是一座单孔石墩台简支木梁桥。上部结构是双层圆木叠合式纵梁，上面横铺木桥面板。桥面宽5.35米，全长14.2米。桥上建木构架廊。桥台是燕翅形，前墙长约6.50米。跨径12.50米。', '', 1, NULL, NULL, '', 8, 2, 10, 1, '怀化市通道侗族自治县陇城镇中步村', '石材（墩台）、木材（纵梁、桥面板、构架廊）', 50, 84, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2043, '中步头桥', '中步头桥是一座单孔石墩台简支木梁桥。上部结构是双层圆木叠合式纵梁，上面横铺木桥面板。桥面宽3.52米，全长28.00米。桥上建木构架廊。桥台是燕翅形，前墙长约5.50米。跨径11.00米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '怀化市通道侗族自治县陇城镇中步村东', '石、木', 50, 85, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2044, '溆浦壶圆桥', '由两座桥对接而成，二桥分别跨于岚水江和卜鳌江上，二桥之间是二江夹角形成的三角洲，两桥相距约20.00米。由于二桥的中心线不是直线，故二桥的平面图形呈八字形。二桥的结构与形式完全相同，上部结构均系圆木纵梁，梁上横铺木桥面板。桥面宽5.20米，桥长均为13.00米，二桥总长45.00米。两座桥上均建有木结构廊，二桥之间的三角洲上建塔式亭。桥台均为凹字形。桥墩两端是方形。二桥跨径均为5.50米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '湖南省溆浦县岚水江和卜鳌江汇合处', '石（墩台）、圆木（纵梁）、木（桥面板、廊）', 50, 86, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2045, '涟源新车桥', '新车桥是一座3孔石墩台悬臂式木梁桥。上部结构是圆木纵梁，纵梁两端下面各有两层圆木悬臂梁。纵梁上面横铺木桥面板，桥面宽5.60米，桥长35.00米。桥上建砖木结构廊和亭，门垛上有桥联，上联是“春秋浩气光青史”，下联是“日夜温泉下大江”。桥台是燕翅形。桥墩两端是尖形。跨径均为10.00米。', '', 1, NULL, NULL, '', 8, 2, 10, 1, '涟源市石马山镇群英村，跨温江河上', '石（墩台）、圆木（纵梁、悬臂梁）、木（桥面板）、砖木（廊和亭）', 50, 87, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2046, '新化龙潭桥', '原为两孔石拱桥，取名“杨洪岩桥”。清乾隆二十二年(1757年)重修，嘉庆十八年(1813年)重修。道光二十八年(1848年)夏秋之交该桥毁于洪水，光绪十二年(1886年)重修并在桥上建长亭。上部结构是上层叠合式圆木纵梁，横铺厚木板为桥面。桥面宽数据暂缺，桥长50.00米。桥上建砖木结构廊。跨径8.50米。', '', 1, NULL, NULL, '', 8, 1, 8, 1, '新化', '圆木、厚木板、砖、木', 50, 88, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2047, '永镇桥', '上部结构每孔是4根圆木纵梁和两根方形(边梁)纵梁，纵梁两端下面有3层圆木悬臂梁，悬臂梁之间有方木横系梁。纵梁上面铺木桥面板，桥面宽3.00米，桥梁全长40.00米。桥台是凹字形。桥墩两端是圆形，桥墩厚1.80米，桥墩长约4.00米。跨径13.50米。', '', 1, NULL, NULL, '', 8, 2, 10, 1, '邵阳市城步苗族自治县长安营乡岩寨村，跨长坪水上', '石、木', 50, 89, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2048, '大溪亭子桥', '桥面是6根圆木纵梁，纵梁下面各有一根圆木辅梁，辅梁的两端各有一根横梁，对应纵梁的下面各有一对(共6对)圆木斜撑，斜撑的下端在桥台的中部。桥面宽4.00米，桥全长15.00米。桥上有木结构廊。桥台与石砌河岸为一体。跨径11.00米。', '', 1, NULL, NULL, '', 9, 2, 10, 1, '邵阳市洞口县渣坪乡', '石、木', 50, 90, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2049, '洞口红军桥', '红军桥是一座8孔石墩台悬臂式木梁桥。上部结构是，在桥台上有两层圆木单悬臂梁。在桥墩上有两层圆木双悬臂梁，上面圆木纵梁，纵梁上铺木桥面板。桥面宽6.50米，桥长95.00米。桥上建砖木结构廊和亭。桥台两侧有燕翅墙，前墙长约7.00米。桥墩两端是尖形。跨径均为11.50米。', '', 1, NULL, NULL, '', 10, 2, 10, 1, '邵阳市洞口县花园镇黄金村', '石（墩台）、圆木（梁）、木（桥面板）、砖木（廊和亭）', 50, 91, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2050, '洞口红桥（红珠桥）', '红桥是一座3孔石墩台简支木梁桥。每孔有10道双层叠合式圆木纵梁，纵梁上面铺木桥面板。桥面宽5.25米，桥面长20.00米，全长25.70米。桥上有木结构廊。桥台和桥墩全是料石砌筑，桥台是凹字形，前墙长5.60米。桥墩两端是方形。跨径6.50米。', '', 1, NULL, NULL, '', 8, 2, 10, 1, '邵阳市洞口县江口镇', '料石、圆木、木', 50, 92, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2051, '洞口洛阳桥', '洛阳桥是一座单孔石台简支木梁桥。桥塊上是阶梯式坡道，上部结构是双层叠合式圆木纵梁，纵梁上面铺木桥面板。桥面宽4.00米，桥面长12.00米，全长18.00米。桥上建木结构廊。无正式桥台，木纵梁两端搭在河岸上。跨径10.50米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '湖南省邵阳市洞口县石江镇', '石、木', 50, 93, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2052, '青龙桥', '桥塊上是阶梯式坡道，上部结构是密排圆木纵梁，纵梁上面铺木桥面板，两侧有木栏杆，桥面宽5.00米，净宽4.50米，桥面长9.90米。桥上建木结构廊。无正式桥台，木纵梁两端搭在河岸上。跨径8.80米。', '', 1, NULL, NULL, '', 10, 2, 10, 1, '邵阳市洞口县岩山乡', '石、木', 50, 94, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2053, '洞口水东桥（遇仙桥）', '水东桥是一座9孔石墩台简支木梁桥。上部结构是圆木纵梁，木梁上铺木桥面板。桥面宽5.00米，桥长86.00米。桥上建砖木结构廊，廊中部建亭。桥台和桥墩全用料石砌筑，桥台是燕翅形，前墙长6.00米。桥墩两端是尖形。跨径6.50米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '邵阳市洞口县水东乡，跨黄泥江上', '料石（桥台和桥墩）、圆木（纵梁）、木（桥面板）、砖木（廊）', 50, 95, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2054, '涡潭桥', '涡潭桥是一座3孔石墩台悬臂式木梁桥。每孔有12根圆木纵梁，纵梁下面，在桥台上有两层圆木单悬臂梁，在桥墩上有两层圆木双悬臂梁。纵梁上面铺木桥面板。桥面宽5.8米，桥全长38米。桥上建木结构廊。桥台两侧有燕翅墙，前墙长约6.00米。桥墩两端是尖形。跨径均为 10.00米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '邵阳市洞口县杨林乡山下村溪坑上', '石（墩台）、圆木（纵梁、悬臂梁）、木（桥面板、廊）', 50, 96, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2055, '宁湖桥', '宁湖桥是一座4孔石墩台简支木梁桥。每孔16根圆木纵梁，纵梁上面铺木桥面板。桥面宽6.40米，桥长27.00米。桥上建木结构廊。桥台是燕翅形，前墙长7.20米。桥墩上游端是尖形，下游端是方形。跨径5.00米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '邵阳市隆回县西洋江镇湖桥村，跨西洋江支流上', '石（墩台）、木（纵梁、桥面板、廊）', 50, 97, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2056, '仙磴桥', '仙磴桥是一座3孔石墩台简支木梁桥，上部结构是双层圆木叠合式纵梁，纵梁上面铺木桥面板，桥面宽4.80米，桥长49.00米。桥上建砖木结构廊。桥台是凹字形，建在山脚岩石上，用料石砌筑，前墙长约5.50米。桥墩上游端是尖形，下游端是方形。跨径6.20米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '邵阳市隆回县六都寨镇，跨辰河上', '石、木、砖', 50, 98, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2057, '罗家桥', '罗家桥是一座4孔石墩台简支木梁桥。桥塊上是阶梯式坡道，上部结构是双层叠合式圆木纵梁，纵梁上面铺木桥面板。桥面宽5.00米，桥梁全长40.00米。桥上建木结构廊。桥台建在山崖岩石上。桥墩两端是尖形，桥墩长7.00米。跨径8.50米。', '', 1, NULL, NULL, '', 8, 2, 10, 1, '邵东市评上镇罗桥村', '石（墩台）、木（纵梁、桥面板、廊）', 50, 99, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2058, '杨家桥', '杨家桥是一座4孔石墩台简支木梁桥。桥塊上是阶梯式坡道，上部结构是密排圆木纵梁，纵梁上面铺木桥面板。桥面宽3.50米，桥全长40.00米。桥上有砖木结构廊。桥台是燕翅形，前墙长4.00米。桥墩两端是尖形。各孔跨径6.50米。', '', 1, NULL, NULL, '', 8, 2, 10, 1, '邵东市坪上镇杨桥村，跨古河道上', '石（墩台）、圆木（纵梁）、木（桥面板）、砖木（廊）', 50, 100, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2059, '绥宁鹅公岭桥', '鹅公岭桥是一座双孔石墩台简支木梁桥。桥面宽4.00米，桥长12.00米。桥上建砖木结构廊。桥台是凹字形，前墙长4.00米。桥墩两端是方形，桥墩厚1.45米，桥墩长4.00米。跨径均为5.50米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '邵阳市绥宁县鹅公岭侗族苗族乡鹅公岭村', '石（墩台）、木（梁）、砖木（廊）', 50, 101, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2060, '杨家桥（又名“人文桥”）', '桥面宽4.00米，桥长20.00米。桥上有砖木结构廊和亭。桥台两侧有燕翅墙，前墙长约5.00米，桥墩端部是尖形。跨径均为7.00米。', '', 1, NULL, NULL, '', 8, 2, 7, 1, '邵阳市绥宁县黄土矿乡通乐村，跨黄土矿河上', '石（墩台）、木（梁）、砖木（廊和亭）', 50, 102, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2061, '关凤桥', '关凤桥是一座双孔石墩台悬臂式木梁桥。桥长25.00米，面宽4.35米。上部结构是双层圆木叠合式纵梁，纵梁上面有木板，纵梁下面有3层圆木悬臂梁。桥面平，建有砖木结构廊。桥台形式不规则，用块石砌筑，桥台上顶有3层圆木单悬臂梁。桥墩两端是圆形，上顶有3层圆木双悬臂梁。跨径均为11.00米。', '', 1, NULL, NULL, '', 8, 2, 10, 1, '武冈市大田村，跨龙江上', '石（桥台、桥墩）、木（纵梁、悬臂梁、廊）、砖（廊）', 50, 103, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2062, '化龙桥', '化龙桥原名“义济桥”,又名“化士桥”。桥梁全长27.95米，桥面宽7.80米。上部结构为密排圆木纵梁，纵梁上铺木桥面板，桥上建有木结构廊。下部结构中，桥台和桥墩全用料石砌筑，桥台呈凹字形，前墙长约8.00米，桥墩端部为尖形，跨径为6.00米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '武冈市城内，跨渠水上', '料石（桥台、桥墩）、圆木（纵梁）、木材（桥面板、廊）', 50, 104, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2063, '木瓜桥', '全长44米，面宽4.7米，四墩五拱，墩上叠木，拱间架木。逐层往上出跳，木上以石板加重压固，构成12排木架长廊。上部结构是以圆木为纵梁，纵梁上面有木板，纵梁下面有方形悬臂梁，桥面平，建有长廊。桥台两侧有八字墙，前墙长约5.00米。桥墩两端是圆形。桥台上顶有3层方木单悬臂梁，桥墩上顶有3层方木双悬臂梁。跨径均为7.60米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '邵阳市武冈市木瓜村，跨资水上', '石墩台、圆木、木板、方形悬臂梁、石板', 50, 105, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2064, '新宁回龙桥', '回龙桥始建于清雍正五年(1727年)，全长78.00米，桥面宽3.80米。该桥为石墩台悬臂式木梁桥，上部结构是在3层圆木悬臂梁上面架设圆木纵梁，纵梁上面铺木桥面板。桥上建有砖木结构廊。桥台为凹字形，用料石砌筑，前墙长4.00米。桥墩两端为方形，用料石砌筑。跨径均为9.80米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '湖南省邵阳市新宁县金石镇柳山村，跨扶夷江支流上', '料石（桥台、桥墩）、圆木（纵梁、悬臂梁）、砖木（桥廊）', 50, 106, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2065, '新宁江口桥', '江口桥是一座8孔石墩台悬臂式木梁桥。上部结构是每孔8根圆木纵梁，纵梁两端下面有3层各8根方木悬臂梁，各层悬臂梁之间横向疏铺方木垫梁。纵梁上面横铺木桥面板。桥长102.00米。桥上建砖木结构廊和亭。桥台是燕翅形。桥墩上游端是尖形，下游端是方形。跨径均为10.00米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '邵阳市新宁县金石镇下马石村，跨新寨水和金溪水合流后的扶夷水上', '石（墩台）、圆木（纵梁）、方木（悬臂梁、垫梁）、木（桥面板）、砖木（廊和亭）', 50, 107, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2066, '狮象桥', '狮象桥是一座双孔石墩台木梁桥。桥塊上是阶梯式坡道，上部结构是双层圆木叠合梁，上面铺木板。桥面宽5.00米，桥面长18.00米，全长20.00米。桥上有砖木结构廊。桥台和桥墩全是料石砌筑，桥台是凹字形，用料石砌筑，前墙长5.00米。桥墩两端是方形。跨径8.60米。', '', 1, NULL, NULL, '', 10, 2, 10, 1, '邵阳市新宁县白马田乡跨田垄溪上', '料石、圆木、木板、砖木', 50, 108, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2067, '新宁太平桥', '太平桥是一座3孔石墩台简支木梁桥。桥塊上是阶梯式坡道，上部结构是双层叠合式圆木纵梁，纵梁上面铺木桥面板。桥面宽3.50米，桥面长27.00米，全长34.00米。桥上建木结构廊。桥台是燕翅形，前墙长4.50米。桥墩两端是尖形。跨径9.00米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '邵阳市新宁县城西南金石镇李家塘村，跨金溪水', '石（墩台）、木（纵梁、桥面板、廊）', 50, 109, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2068, '新邵青龙桥', '青龙桥是一座单孔石台简支木梁桥。桥塊上是阶梯式坡道，上部结构是双层叠合式圆木纵梁，纵梁上面铺木桥面板。桥面宽8.00米，桥长20.00米。桥上建木结构廊。东桥台是凹字形，用方块石料砌筑，前墙长8.00米。西桥台与石砌河岸为一体。跨径7.20米。', '', 1, NULL, NULL, '', 10, 2, 10, 1, '邵阳市新邵县潭溪镇泌水村', '石料、圆木、木', 50, 110, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2069, '思贤桥', '思贤桥是一座3孔石墩台简支木梁桥。上部结构是双层圆木叠合纵梁，桥面宽4.00米，桥长43.30米。桥上建木结构廊。桥台是燕翅形，前墙长约5.00米。桥墩两端是尖形，跨径均为9.00米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '益阳市安化县江南七一村，跨资水支流思贤溪上', '石材（墩台）、木材（纵梁、廊）', 50, 111, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2070, '永锡桥', '永锡桥是一座6孔石墩台简支木梁桥。桥面宽4.20米，桥长83.00米。桥上建砖木结构廊。桥台是燕翅形，前墙长约5.20米。桥墩两端是尖形，跨径均为12.00米。桥碑有诗赞曰：\"熊山一水赴龙山，奔出千岩弯复弯。画鹚昔曾横野渡，彩虹今忽炫尘寰。天余缺憾人能补，神着先鞭石不顽。好是津梁通两岸，行人到此尽欢颜。\"', '', 1, NULL, NULL, '', 8, 2, 8, 1, '益阳市安化县洞市镇锡潭村，跨麻溪上', '石、木、砖', 50, 112, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2071, '望嶷亭桥', '望嶷亭桥是一座单孔石台木梁桥。桥塊上是阶梯式坡道，上部结构是圆木纵梁，梁上横铺木桥面板，桥面宽4.40米，桥面长7.00米。桥上建木结构亭。桥台是凹字形，前墙长4.40米。跨径6.60米。', '', 1, NULL, NULL, '', 9, 2, 10, 1, '永州市蓝山县所城镇黄泥铺村南端', '石材（桥台）、圆木（纵梁）、木材（桥面板、木结构亭）', 50, 113, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2072, '熟溪桥', '全桥总长140米。上部结构是圆木纵梁，纵梁两端下面各有3层圆木悬臂梁，悬臂梁之间有疏铺方木横梁。纵梁上面横铺木桥面板。桥面宽5.00米，桥梁全长140.00米。桥上有砖木结构廊。桥台是凹字形，用料石砌筑，前墙长5.00米。桥墩两端是方形，桥墩厚3.00米，桥墩长7.00米。中7孔跨径10.70—12.00米，两边孔跨径3.95米。', '', 1, NULL, NULL, '', 7, 2, 7, 1, '金华市武义县壶山镇来远门外', '石（墩台、桥台料石）、木（纵梁、悬臂梁、横梁、桥面板）、砖木（桥屋/廊）', 50, 114, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2073, '西津桥', '西津桥是一座16孔石墩台悬臂式木梁桥。上部结构是圆木纵梁，纵梁两端下面各有3层圆木悬臂梁，悬臂梁之间有疏置方木横梁。纵梁上面横铺木桥面板，桥面净宽4.05米，桥梁全长184.53米。桥上有砖木结构廊。桥台是凹字形，前墙长约4.50米。桥墩两端是方形，桥墩厚3.00米，桥墩长5.50米。最大跨径12.00米，最小跨径7.15米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '永康市城西南，跨永康江上', '石墩、圆木、方木、砖木', 50, 115, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2074, '公起桥', '公起桥是一座单孔石台撑架式木梁桥。桥面宽3.30米，桥长22.80米。桥上建木结构廊。山脚下岩壁为桥台。跨径12.70米。', '', 1, NULL, NULL, '', 8, 2, 10, 1, '丽水市莲都区河边村，跨大龄台溪上', '木、石', 50, 116, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2075, '钟山桥', '钟山桥是一座单孔石台简支木梁桥。桥面宽4.50米，桥长30.20米。桥台是凹字形，前墙长4.50米。跨径20.00米。', '', 1, NULL, NULL, '', 8, 2, 10, 1, '丽水市莲都区峰源乡夏庄村', '石、木', 50, 117, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2076, '白鹤桥', '白鹤桥是一座单孔撑架式木梁桥。上部结构是9根圆木纵梁，纵梁下面中间各有一根圆木辅梁，辅梁两端有一对圆木斜撑，纵梁上面铺双层木桥面板，桥面宽4.80米，桥长32.30米。桥上建砖木结构廊。桥台建在山脚岩石上，用块石砌筑。跨径23.90米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '丽水市景宁畲族自治县东坑镇白鹤村，跨北溪上', '圆木、木、砖、块石', 50, 118, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2077, '茶堂桥', '茶堂桥是一座单孔撑架式木梁桥。上部结构是9道圆木纵梁，纵梁下面中部各挂1根圆木辅梁，辅梁的两端有一根方木横系梁。横系梁的外侧有9对圆木斜撑，斜撑的下端置于用石板砌筑的桥台前墙中部。纵梁上面铺木桥面板。桥面宽4.88米，桥长61.50米。桥上建木结构廊。桥台是凹字形，前墙长约5.50米。跨径26.70米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '丽水市景宁畲族自治县英川镇木耳口村，跨黄谢圩港上', '木材（圆木、方木、木桥面板）、石板', 50, 119, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2078, '长滩桥', '长滩桥是一座单孔石台撑架式木梁桥。桥面宽4.60米，桥长 25.80米。 桥台是凹字形，用块石砌筑，前墙长约5.00米。跨径17.80米。', '', 1, NULL, NULL, '', 8, 2, 10, 1, '丽水市景宁畲族自治县英川镇西坑村', '块石、木材', 50, 120, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2079, '景宁大济胡桥', '桥面宽17.20米，桥长17.40米。桥上建砖木结构廊。桥台与河岸为一体，用块石砌筑。跨径10.00米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '丽水市景宁畲族自治县大济乡西岸底村', '块石、木、砖', 50, 121, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2080, '景宁大均桥（泉坑桥）', '大均桥是一座3孔石墩台简支木梁桥。上部结构是圆木纵梁，上面铺木桥面板，桥面宽6.20米，桥面长23.00米，全长31.00米。桥上建砖木结构廊。桥台是凹字形，用条形石板砌筑。桥墩也是用条形石板砌筑，两端是方形，桥墩厚1.00米，桥墩长6.20米。跨径5.50米。', '', 1, NULL, NULL, '', 8, 2, 10, 1, '丽水市景宁畲族自治县大均乡大均村', '圆木、木桥面板、条形石板、砖木', 50, 122, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2081, '东坑上桥', '东坑上桥是一座撑架式木梁桥。上部结构是圆木纵梁，纵梁下面有 4根圆木横梁，横梁下面有6根圆木辅梁，辅梁两端各有一对圆木斜撑。 纵梁上面铺木桥面板。 桥面宽4.40米，桥长28.30米。桥上建木结构廊。 桥台在山崖壁上凿成平台。跨径18.70米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '丽水市景宁畲族自治县东坑村，跨赤坑溪上', '木材（圆木纵梁、横梁、辅梁、斜撑，木桥面板，木结构廊）', 50, 123, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2082, '景宁广济桥', '广济桥又名“芎岱桥”。广济桥是一座单孔撑架式木梁桥。上部结构是13道双层圆木叠合纵梁，纵梁下面中部各有一根圆木辅梁，辅梁两端有一对圆木斜撑。纵梁上面铺双层木桥面板。桥面宽6.00米，桥长42.00米。桥台建在山脚岩石上。跨径14.50米。', '', 1, NULL, NULL, '', 8, 2, 10, 1, '丽水市景宁畲族自治县家地乡家地村，跨山建排水沟上', '木材（圆木、木桥面板）、岩石（桥台）', 50, 124, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
