INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2094, '龙泉永和桥', '永和桥是一座4孔石墩台悬臂式木梁桥。上部结构是每孔9根圆松木纵梁，纵梁两端下面各有7层圆木悬臂梁，悬臂梁间皆有横向疏铺的方木垫梁。纵梁上面横顺铺双层硬木桥面板。桥面宽7.50米，净宽6.40米，桥长125.70米。桥上建砖木结构廊42间，中间有阁，桥两端各有27级台阶。桥台是凹字形，两侧有块石砌筑的斜坡护岸。桥墩上游端是尖形，下游端方形，桥墩厚1.80米，桥墩长9.80米。跨径由东向西依次是14.30米、18.40米、17.10米、16.90米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '龙泉市安仁镇，跨安仁西溪上', '石墩台、圆松木纵梁、圆木悬臂梁、方木垫梁、硬木桥面板、砖木结构廊、块石', 50, 136, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
