INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2115, '如龙桥', '如龙桥是一座单孔撑架式木梁桥。上部结构是圆木纵梁，纵梁下面中部各挂一根圆木辅梁，辅梁两端有一对圆木斜撑。纵梁上横顺铺木桥面板。桥面宽5.08米，桥长28.20米。桥上建有木结构廊。桥台建在山脚基岩上。跨径19.50米。', '', 1, NULL, NULL, '', 7, 2, 10, 1, '丽水市庆元县举水乡月山村', '圆木、木桥面板', 50, 157, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
