INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2117, '上坑阙下桥', '上部结构是8根圆木纵梁，纵梁下面中部有2根圆木横梁，横梁下面有4根辅梁，辅梁两端各有一对圆木斜撑。纵梁上面铺木桥面板。桥面宽4.10米，桥长23.75米。桥上建砖木结构廊。桥台是在山涧石壁上开凿出的平台。跨径9.80米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '丽水市庆元县竹口镇上坑村，跨山涧上', '圆木、木、砖木', 50, 159, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
