INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2122, '庆元文昌桥', '文昌桥是一座单孔撑架式木梁桥。上部结构是7根圆木纵梁，纵梁下面中部有2根圆木横梁，横梁下面有4根圆木辅梁，辅梁两端各有一对圆木斜撑。纵梁上面铺木桥面板。桥面宽3.80米，桥长13.70米。桥上建砖木结构廊。桥台用块石砌筑。跨径13.00米。', '', 1, NULL, NULL, '', 10, 2, 10, 1, '丽水市庆元县安南乡吾际下村', '圆木、木桥面板、砖木结构、块石', 50, 164, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
