INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2125, '余地桥', '余地桥是一座单孔简支木梁桥。上部结构是圆木纵梁，纵梁上面铺木桥面板，桥面宽3.75米，桥长16.45米。桥上建砖木结构廊。桥台用块石砌筑。跨径5.60米。', '', 1, NULL, NULL, '', 8, 2, 10, 1, '丽水市庆元县安南乡余地村', '圆木、木、砖、块石', 50, 167, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2126, '广济桥', '广济桥是一座4孔石墩台木梁桥。上部结构是密排圆木纵梁，上面铺双层木桥面板，桥面宽6.60米，桥长51.68米。桥上建砖木结构廊。桥台是凹字形，桥墩是6根方形石柱，边柱上顶向内倾斜，上顶有石板帽梁，帽梁宽0.90米，帽梁长7.80米。跨径10.00米。', '', 1, NULL, NULL, '', 6, 2, 6, 1, '浙江省宁波市奉化区南渡村，跨奉化区江下游', '石、木、砖', 50, 168, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2127, '卧渡桥', '卧渡桥是一座单孔撑架式木梁桥。上部结构是3层圆木(两顺一横)架设而成，纵梁下面两端各有5对圆木斜撑。桥面宽6.40米，桥长24.00米。桥上建砖木结构廊。在山脚岩石上开凿桥台。跨径20.00米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '宁波市奉化区山区峡谷中，跨水龙溪和马陆溪汇流后下游河道上', '圆木、砖木', 50, 169, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2128, '百梁桥', '现存百梁桥是一座7孔石墩台简支木梁桥。中孔为16根圆木纵梁，其余6孔均为14根圆木纵梁，全桥共计100根梁，故称“百梁桥”。梁上铺双层木桥面板。桥面宽8.00米，桥长77.40米。桥上建有木结构长廊，两端有门楼。桥台与石板砌筑的河岸为一体。桥墩两端是尖形。中孔跨径7.00米，边孔跨径6.50米。', '', 1, NULL, NULL, '', 7, 2, 5, 1, '宁波市鄞州区洞桥镇蕙江村，跨鄞江上', '石墩台、圆木纵梁、木桥面板、木结构长廊、石板', 50, 170, '2026-04-28 23:07:56', '2026-04-28 23:36:24');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2129, '洞桥', '洞桥是一座双孔石墩台简支木梁桥。上部结构是圆木纵梁上面铺双层木桥面板，桥面宽8.10米，桥长26.76米。桥上建砖木结构廊。桥台是凹字形，前墙长8.50米。桥墩两端是方形。跨径均为6.60米。', '', 1, NULL, NULL, '', 10, 2, 10, 1, '宁波市鄞州区', '石（墩台）、木（纵梁、桥面板）、砖木（廊）', 50, 171, '2026-04-28 23:07:56', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2130, '宁波鄞江桥', '鄞江桥是一座6孔石墩台悬臂式木梁桥。上部结构是圆木纵梁，纵梁两端下面各有3层圆木悬臂梁，悬臂梁之间疏置圆木横梁。纵梁上横向疏铺方形枕木，上面铺木桥面板。桥面宽5.00米，桥梁全长79.80米。桥上有砖木结构廊。桥台是凹字形，前墙长约5.00米。桥墩两端是方形，自下而上有收分(上顶较薄，下部较厚)。中4孔跨径9.00米，两边孔跨径6.00米。', '', 1, NULL, NULL, '', 8, 2, 10, 1, '宁波市鄞州区鄞江桥镇', '石（墩台）、圆木（纵梁、悬臂梁、横梁）、木（桥面板）、砖木（廊）', 50, 172, '2026-04-28 23:07:56', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2131, '尚源桥', '尚源桥是一座单孔简支木梁桥。上部结构是圆木做纵梁，上面横铺木板而成桥面。桥面宽7.10米，桥长12.30米。桥上建砖木结构廊。桥台与块石砌筑的河岸为一体。跨径6.90米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '宁波市宁海县山区峡谷中，跨凫溪上', '圆木（纵梁）、木板（桥面）、砖木（廊）、块石（桥台）', 50, 173, '2026-04-28 23:07:56', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2132, '镇东桥', '原建上部结构是圆木纵梁，上面铺双层木桥面板。桥面宽5.40米，净宽4.24米，桥面长21.00米，全长23.50米。桥上建砖木结构廊。桥台是燕翅形，桥墩两端是方形，桥墩厚0.80米，桥墩长5.70米，桥孔净跨11.26米。20世纪80年代加固时，在桥台前墙中部各加设两对圆木斜撑，斜撑的上端顶在纵梁下面，成为类似撑架式木梁桥。', '', 1, NULL, NULL, '', 8, 2, 10, 1, '宁波市宁海县西店镇璜溪口村，跨紫溪入海处', '石（墩台）、圆木（纵梁、斜撑）、木（桥面板）、砖木（廊）', 50, 174, '2026-04-28 23:07:56', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2133, '余姚板桥', '板桥是一座双孔石墩台简支木梁桥。每孔桥面有10根圆木纵梁，上面铺双层木桥面板。桥面宽4.50米，桥长28.00米。桥上建砖木结构廊。桥台与石砌河岸为一体。桥墩是5根方形石柱，上顶横置一根方形石帽梁，帽梁长5.00米。跨径11.00米。', '', 1, NULL, NULL, '', 10, 2, 10, 1, '余姚市李家塔村', '石、木、砖', 50, 175, '2026-04-28 23:07:56', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2134, '梅树坂桥', '梅树坂桥是一座单孔撑架式木梁桥。上部结构是6根纵梁，纵梁上面铺单层木桥面板。两根边纵梁的下面中间各有一道辅梁，辅梁的两端各有一对圆木斜撑。4根中纵梁的下面中间各有一道横梁，横梁的两边各有4对圆木斜撑。桥面宽3.20米，桥长19.00米。桥上建砖木结构廊。桥台与料石砌筑的河岸为一体。跨径14.00米。', '', 1, NULL, NULL, '', 5, 2, 5, 1, '绍兴市新昌县上三坑村，跨街河上', '木、砖、料石', 50, 176, '2026-04-28 23:07:56', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2135, '新昌普济桥', '普济桥是一座单孔双层撑架式木梁桥。纵梁采用双层圆木叠梁，纵梁之间设有横木系杆，每根纵梁的下面挂一根辅梁，辅梁的两端各有一对圆木斜撑，斜撑的下端置于块石砌筑的桥台下部。辅梁的中间有一根横梁，横梁的两侧各有一对圆木斜撑，斜撑的下端置于桥台的中部。纵梁上面横顺铺木桥面板。桥面宽5.00米，桥长25.00米。桥上建有木结构廊。桥台与块石砌筑的河岸为一体。跨径16.4米。', '', 1, NULL, NULL, '', 5, 2, 5, 1, '绍兴市新昌县上三坑村，跨街河上', '圆木、木材、块石', 50, 177, '2026-04-28 23:07:56', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2136, '泰顺北涧桥', '北涧桥是一座单孔撑架式木梁桥。上部结构是用圆木做纵梁，上面横顺铺双层木桥面板，纵梁下面中间各设一根圆木辅梁，辅梁的两端各有一根圆木横梁，对应每根纵梁的下面各有一对圆木斜撑。斜撑的下端置于石板砌筑的桥台中部，纵梁的外端搭在桥台的上面。桥面宽5.40米，桥长51.90米。桥上建砖木结构廊。桥台建在基岩上，桥台前墙的中部有一道横槽，平放一根方形木垫梁，斜撑的下端置于横木垫上。跨径29.00米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '温州市泰顺县泗溪镇下桥村，跨山涧排水沟上', '圆木、木桥面板、石板、砖木', 50, 178, '2026-04-28 23:07:56', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2137, '泰顺三条桥', '现存三条桥是一座单孔石台撑架式木梁桥。上部结构是双层圆木叠合纵梁，纵梁的外端搭在桥台上，纵梁下面中间各有一根圆木辅梁，辅梁的两端有一对圆木斜撑。纵梁上面横顺铺双层木桥面板。桥面宽4.00米，桥长26.63米。上部结构的两侧挂有木遮雨板，桥上建砖木结构廊。桥台建在基岩上，跨径21.26米。', '', 1, NULL, NULL, '', 8, 2, 5, 1, '温州市泰顺县垟溪乡和洲岭乡交界处，跨横溪上', '木、砖、石', 50, 179, '2026-04-28 23:07:56', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2138, '泰顺泗溪东桥', '上部结构是用17道圆木做纵梁，在纵梁中段挂2根圆木横梁，横梁下面挂圆木辅梁，共8根较长的辅梁，9根较短的辅梁。短辅梁的两端各有一对圆木斜撑，斜撑的下端置于石砌桥台的下部。长辅梁的两端各有一对圆木斜撑，斜撑的下端置于石砌桥台的中部。纵梁的外端搭在桥台的上面。纵梁上横顺铺双层木桥面板。桥面宽4.86米，桥长41.70米。木结构两边挂遮雨木板，桥上建砖木结构廊。桥台建在山脚基岩上，是用块石砌筑，形式不规则。跨径25.70米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '温州市泰顺县泗溪镇下桥村，跨东溪上', '圆木、木板、砖、块石', 50, 180, '2026-04-28 23:07:56', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2139, '泰顺文重桥', '文重桥是一座双孔石墩台悬臂式木梁桥。上部结构是圆木纵梁，纵梁两端下面各有3层圆木悬臂梁，悬臂梁之间疏铺方木横梁。纵梁上面横顺铺双层木桥面板。无栏杆。桥面宽4.70米，桥长26.20米。桥台是凹字形，前墙长约5.00米。桥墩两端是方形，桥墩厚2.50米，桥墩长5.00米。跨径11.20米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '温州市泰顺县筱村镇东洋村', '石（墩台）、圆木（纵梁、悬臂梁）、方木（横梁）、木（桥面板）', 50, 181, '2026-04-28 23:07:56', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2140, '永庆桥', '永庆桥是一座双孔石墩台悬臂式木梁桥。上部结构是圆木纵梁，纵梁下面两端有3层圆木悬臂梁，悬臂梁之间有方木横系杆件。纵梁上面铺木桥面板，桥面宽5.00米，桥长36.00米。桥上建砖木结构廊。桥台与块石砌筑的河岸为一体。桥墩用青石板砌筑，两端是方形，桥墩厚1.30米，桥墩长5.50米。跨径均为9.50米。', '', 1, NULL, NULL, '', 8, 2, 10, 1, '温州市泰顺县三魁镇战洲下溪坪村', '圆木、方木、木桥面板、砖、块石、青石板', 50, 182, '2026-04-28 23:07:56', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2141, '毓文桥', '毓文桥是一座单孔撑架式木梁桥。桥面宽4.00米，桥长23.00米。桥上建砖木结构廊。桥台是凹字形，用块石砌筑。跨径7.60米。', '', 1, NULL, NULL, '', 8, 2, 10, 1, '温州市泰顺县洲岭乡洲边村', '砖木结构、块石', 50, 183, '2026-04-28 23:07:56', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2142, '二桥亭桥', '二桥亭桥是一座单孔石台木梁桥。桥面是12根圆木纵梁，上面疏架方形横木，横木上铺木桥面板，两侧有石栏杆，桥面宽3.20米，桥长9.80米。桥上建砖木结构亭。桥台是凹字形。跨径4.10米。', '', 1, NULL, NULL, '', 10, 2, 10, 1, '福州市鼓楼区仓前街与通湖路之间，在金斗桥南', '石、木、砖', 50, 184, '2026-04-28 23:07:56', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2143, '蕉溪桥', '蕉溪桥是一座单孔撑架式木梁桥。上部结构是13根圆木纵梁，纵梁中部下面各有一根辅梁。辅梁两端各有一根圆木横梁，横梁外侧各有 13根圆木斜撑，斜撑的下端置于桥台的中部。纵梁上面铺双层木桥面板。桥面宽4.33米，桥长27.30米。桥上建砖木结构廊。桥台是用方形条石砌筑，大致为凹字形，前墙长约4.50米。跨径 9.20米。', '', 1, NULL, NULL, '', 9, 2, 10, 1, '福州市闽侯县廷坪乡蕉溪村，跨蕉溪上', '圆木（纵梁、辅梁、横梁、斜撑）、木（桥面板）、砖木（廊）、方形条石（桥台）', 50, 185, '2026-04-28 23:07:56', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2144, '岭下桥', '岭下桥是一座单孔石台撑架式木梁桥。桥堍上铺砌块石，桥面是5根圆木纵梁，纵梁的两端置于河岸上。纵梁下面中间挂一道横梁，横梁两侧各有5对圆木斜撑，斜撑的下端置于河岸中部。桥面宽4.60米，桥长9.60米。桥上有木结构廊。桥台与用乱石砌筑的河岸为一体。跨径6.80米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '福州市闽侯县六锦村，跨山涧排水沟上', '块石、圆木、乱石', 50, 186, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2145, '龙津桥', '龙津桥是一座单孔撑架式木梁桥。上部结构圆木纵梁，纵梁下面中部有4根圆木横梁，横梁下面有6根圆木辅梁，辅梁两端各有一对圆木斜撑。纵梁上面铺木桥面板。桥面宽4.30米，桥长33.00米。桥上建砖木结构廊。桥台用块石砌筑，形状不规则。跨径20.20米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '福州市闽侯县延坪乡流源村，跨东源溪上', '木材（圆木斜撑、辅梁、纵梁、桥面板、木廊）、石材（山崖岩石桥台）', 50, 187, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2146, '泰山桥', '泰山桥是一座单孔撑架式木梁桥。桥面是8根圆木纵梁，纵梁中部下面各有一根圆木辅梁，辅梁的两端各有一根圆木横梁，横梁的外侧各有8根圆木斜撑，斜撑的下端置于山脚岩石上。纵梁上面铺双层木桥面板，桥面宽4.30米，桥长27.90米。桥上建砖模具结构廊。桥台是在山脚岩石上开凿成平台。跨径21.60米。', '', 1, NULL, NULL, '', 9, 2, 10, 1, '福州市闽侯县廷坪乡后溪村，跨后溪上', '圆木、木桥面板、砖', 50, 188, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2147, '温汤桥', '上部结构是9根圆木纵梁，纵梁下面中部挂有4根辅梁(相间),辅梁两端各有一根圆木斜撑。在辅梁两端以外各有一根较粗的圆木横梁，横梁之间有辅梁，横梁外侧有一对圆木斜撑。纵梁上面铺木桥面板。桥面宽4.00米，桥长11.40米。桥上建木结构廊。桥台建在山脚岩石上。跨径11.60米。', '', 1, NULL, NULL, '', 8, 2, 10, 1, '福州市闽侯县桔林乡温汤村', '木材', 50, 189, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2148, '武灵桥', '武灵桥是一座单孔简支木梁桥。上部结构是双层圆木纵梁，纵梁上面铺木桥面板，桥面宽3.60米，桥长13.20米。桥上建砖木结构廊。桥台是在山脚岩石上开凿而成。跨径9.30米。', '', 1, NULL, NULL, '', 10, 2, 10, 1, '福建省福州市闽侯县廷坪乡溪坪村，跨后垄溪上', '圆木、木、砖', 50, 190, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2149, '溪隆桥', '溪隆桥是一座单孔石台简支木梁桥。桥面是圆木纵梁，纵梁上面铺木桥面板。桥面宽3.16米，桥长9.15米。桥上建砖木结构廊。桥台建在山脚岩石上。跨径6.70米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '福州市闽侯县下洋村，跨溪隆尾溪上', '石（桥台）、木（纵梁、桥面板、廊）、砖（廊）', 50, 191, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2150, '洋头桥（玄帝桥）', '洋头桥是一座单孔石台简支木梁桥。桥塊上铺砌块石，桥面是圆木纵梁，纵梁上面铺木桥面板。桥面宽3.50米，桥长20.00米。桥上建砖木结构廊。桥台建在山脚岩石上。跨径12.70米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '福州市闽侯县洋头村，跨三溪口上', '块石、圆木、木、砖木', 50, 192, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2151, '友泉溪桥', '友泉溪桥是一座单孔石台简支木梁桥。桥塊上铺砌块石，桥面是圆木纵梁，桥上有木结构廊。桥面宽3.16米，桥长9.17米。桥台是凹字形，用乱石砌筑。跨径5.00米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '福州市闽侯县洋里村，跨友泉溪上', '块石（桥塊）、圆木（纵梁）、乱石（桥台）、木材（廊）', 50, 193, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2152, '闽侯远济桥', '远济桥又名“石陌桥”。桥面是9道圆木纵梁，纵梁下面挂9根辅梁，纵梁上面铺双层木桥面板。桥上建木结构廊，桥面宽5.10米，桥长23.00米。桥台是凹字形，用料石砌筑，前墙长5.10米。跨径14.50米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '福州市闽侯县白沙镇联坑村，跨大目溪上', '木材（圆木、木桥面板、木结构廊）、料石', 50, 194, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2153, '左白桥', '桥面是圆木纵梁，纵梁上面铺木桥面板。桥面宽3.90米，桥长16.58米。桥上建砖木结构廊。桥台建在山脚岩石上。跨径10.70米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '福州市闽侯县东墘村，跨东墘溪上', '石、木、砖', 50, 195, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2154, '合龙桥', '合龙桥是一座双孔撑架式木梁桥。上部结构是圆木纵梁，纵梁下面中部有2根圆木横梁，横梁下面有4根圆木辅梁，辅梁两端各有一对圆木斜撑。纵梁上面铺木桥面板。桥面宽4.50米，桥长39.70米。桥上建砖木结构廊。桥台是燕翅形，用料石砌筑。桥墩也用料石砌筑，两端是尖形。跨径分别是12.50米、14.70米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '福州市闽清县省璜镇省璜村，跨梅溪支流上', '圆木、木、砖木、料石', 50, 196, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2155, '长汀当坑桥（永隆桥）', '上部结构是在桥台上有4层圆木单悬臂梁，上面架设5层圆木叠合纵梁，纵梁上面横顺铺木桥面板，桥面宽4.00米，桥长27.00米。桥上建木结构廊。桥台是凹字形，用方形条石横顺相间砌筑，前墙长4.00米。跨径18.70米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '龙岩市长汀县策武乡当坑村', '圆木、木材、方形条石', 50, 197, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2156, '文川桥', '文川桥是一座双孔石墩台悬臂式木梁桥。桥面结构系用圆木为纵梁，上面横铺木桥面板，桥台上有两层圆木单悬臂梁，桥墩上有两层圆木双悬臂梁，承托圆木纵梁，桥面宽5.00米，桥长47.00米。桥上建木结构廊。桥台两侧有燕翅墙，用料石砌筑，前墙长5.00米。桥墩两端是尖形，用料石砌筑，桥墩厚1.80米，桥墩长7.20米。跨径22.00米。', '', 1, NULL, NULL, '', 5, 2, 5, 1, '龙岩市连城县城南', '圆木、木材、料石', 50, 198, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2157, '永隆桥', '永隆桥是一座5孔石墩台悬臂式木梁桥。上部结构是圆木纵梁，纵梁两端下面有3层圆木悬臂梁，悬臂梁之间有方木横系杆件。纵梁上面铺木桥面板。桥面宽6.00米，桥长85.00米。桥上建砖木结构廊。桥台是燕翅形，用料石砌筑，前墙长6.80米。桥墩上游端是尖形，下游端是方形。跨径8.20米。', '', 1, NULL, NULL, '', 7, 2, 7, 1, '龙岩市连城县吕溪镇莒壁洲村，跨莒溪上', '石（墩台、料石）、木（圆木纵梁、悬臂梁、方木横系杆件、木桥面板）、砖木（廊）', 50, 199, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2158, '玉沙桥', '玉沙桥是一座双孔石墩台悬臂式木梁桥。上部结构是，在桥台上有 一层圆木单悬臂梁，桥墩上有一层圆木双悬臂梁，上面架设双层圆木叠 合纵梁，纵梁上面横铺木桥面板，桥面宽5.00米，桥长29.00米。桥上 建木结构廊。 桥台是凹字形，用块石砌筑，前墙长5.00米。桥墩两端是方形， 桥墩厚1.65米，桥墩长5.00米。跨径均为12.00米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '龙岩市连城县马屋村，跨花溪上', '石、木', 50, 200, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2159, '云龙桥', '上部结构是在桥台上有3层圆木单悬臂梁，在桥墩上有3层圆木双悬臂梁，上面架设3层复合型圆木纵梁，纵梁上面横顺铺木桥面板。桥面宽5.00米，桥长81.00米。桥上建木结构廊。桥台是带燕翅形，建在山脚下，用料石砌筑，前墙长6.00米。桥墩上游端是尖形，下游端是方形。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '龙岩市连城县下罗村，跨青岩河上', '圆木、木材、料石', 50, 201, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2160, '南平安口桥', '安口桥是一座单孔撑架式木梁桥。上部结构是8根圆木纵梁，纵梁下面中部挂两根圆木横梁，横梁下面有4根圆木辅梁，辅梁两端各有1对圆木斜撑。纵梁上面铺木桥面板，桥面宽4.00米，桥长16.00米。桥台用块石砌筑。跨径12.00米。', '', 1, NULL, NULL, '', 10, 2, 10, 1, '南平市建阳区永吉镇安口村', '圆木、块石', 50, 202, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2161, '南平八字桥', '桥面系用3段圆木为纵梁，纵梁上横顺铺双层木桥面板。纵梁下面有两层辅梁，上层辅梁较长，两端各有两对圆木斜撑，下层辅梁较短，两端各有一对圆木斜撑。桥台是凹字形，用块石砌筑，桥面宽6.00米，桥长34.80米。桥上建砖木结构廊。跨径19.30米。', '', 1, NULL, NULL, '', 9, 2, 10, 1, '南平市延平区山峡阳镇梅照村', '木材（圆木纵梁、木桥面板、圆木斜撑）、块石（桥台）、砖木（廊）', 50, 203, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2162, '金造桥', '金造桥是一座单孔撑架式木梁桥。上部结构是10道圆木纵梁，上面铺单层木桥面板，上面铺墁砖面。纵梁下面中间各有一道辅梁，辅梁的两端各有一对圆木斜撑，斜撑分上下两层，各为5对。桥面宽4.78米，桥长39.50米。桥上建砖木结构廊。桥台用石板砌筑。跨径31.40米。', '', 1, NULL, NULL, '', 8, 2, 10, 1, '宁德市屏南县棠口乡涤头村', '圆木、木板、石板', 50, 204, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2163, '落托桥', '桥面宽4.70米，桥长22.30米。桥上建砖木结构廊。桥台是凹字形，用块石砌筑，前墙长约5.00米。跨径15.30米。', '', 1, NULL, NULL, '', 9, 2, 10, 1, '南平市延平区茫荡镇头村', '木、砖、块石', 50, 205, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2164, '月圆桥', '月圆桥是一座单孔简支木梁桥。上部结构是11根双层圆木叠合纵梁，纵梁上面横顺铺木板而成桥面。桥面宽5.00米，桥长40.00米。桥上建木结构廊。桥台建在山脚岩石上。跨径12.50米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '南平市延平区峡阳镇洋安村', '木材（圆木、木板）', 50, 206, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2165, '承安桥', '承安桥是一座4孔石墩台复合型悬臂式木梁桥。上部结构是在桥台上3层圆木单悬臂梁，在桥墩上3层圆木双悬臂梁，上面架设3层复合型圆木纵梁，纵梁上面横顺铺木桥面板。桥面宽4.50米，桥长55.00米。桥上建木结构廊。桥台是燕翅形，前墙长5.50米。桥墩上游端是尖形，下游端是方形。跨径6.80米。', '', 1, NULL, NULL, '', 7, 2, 7, 1, '南平市光泽县鸾凤乡油溪村，跨油溪上', '石（墩台）、圆木（悬臂梁、纵梁）、木（桥面板、廊）', 50, 207, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2166, '建瓯步月桥', '步月桥是一座3孔石墩台复合型悬臂式木梁桥。上部结构是在桥墩上有3层圆木双悬臂梁，上面架设3层复合型圆木纵梁，纵梁上横顺铺木桥面板，桥面宽6.05米，桥梁全长127.50米。桥台是两侧有燕翅墙，用方形条石横顺相间砌筑，前墙长6.00米。桥墩两端是尖形，也是用方形条石横顺相间砌筑，桥墩厚2.00米，桥墩长8.25米。跨径14.00米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '建瓯市玉溪村，跨玉溪河上', '圆木、木桥面板、方形条石', 50, 208, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2167, '承龙桥', '承龙桥是一座单孔撑架式木梁桥。共有8根圆木纵梁，纵梁的下面中间部位各挂一根圆木辅梁，辅梁的两端各挂1根圆木横梁，横梁的外侧各设8对圆木斜撑，斜撑的下端置于桥台的中部。纵梁上面横顺铺木板而成桥面。桥面宽4.20米，桥长59.00米。桥上建木结构廊。桥台是凹字形，用块石砌筑，前墙长约4.50米。跨径18.00米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '建瓯市迪口镇小桔村', '圆木、木板、块石', 50, 209, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2168, '丰乐桥', '丰乐桥又称“黄桥”，是一座单孔简支木梁桥。桥面是圆木纵梁，木梁直径约40厘米，梁长7.50米，上面铺单层木板，桥面宽5.60米，桥面长18.00米。桥上建木结构廊。东北端有9级台阶，西南端有21级台阶。桥台是凹字形，用块石砌筑，前墙长5.60米。跨径6.50米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '南平市浦城县临江镇水西村跨乡间小溪上', '圆木（纵梁）、木板（桥面）、块石（桥台）', 50, 210, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2169, '镇安桥（又名“临江桥”）', '镇安桥是一座3孔石墩台悬臂式木梁桥。上部结构是，在桥台上有4层圆木单悬臂梁，在桥墩上有4层圆木双悬臂梁，上面架设3层复合型圆木纵梁，纵梁上面横顺铺木桥面板。桥面宽3.60米，桥长79.50米。桥上建木结构廊。桥台是凹字形，用石板砌筑，前墙长4.50米。桥墩两端是方形，用石板砌筑，桥墩厚1.50米，桥墩长3.50米。跨径15.50米。', '', 1, NULL, NULL, '', 7, 2, 7, 1, '南平市浦城县水东村与水西村之间，跨南浦溪支流临江溪上', '石板、圆木、木', 50, 211, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2170, '顺昌广济桥', '广济桥是一座单孔简支木梁桥。上部结构是15根双层圆木叠合纵梁，各道纵梁之间有圆木横系杆件。纵梁两端下面(在桥台上)各有6层(3顺3横)方木垫。纵梁上面铺木桥面板。桥面宽6.25米，净宽5.50米，桥长24.00米。桥上建砖木结构廊。桥台是用料石砌筑，大致为凹字形。跨径9.00米。', '', 1, NULL, NULL, '', 7, 2, 10, 1, '南平市顺昌县古春村', '圆木、方木、木材、砖、料石', 50, 212, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2171, '岚下桥', '岚下桥是一座单孔撑架式木梁桥，桥面宽4.25米，桥梁全长51.60 米。桥上建木结构廊。桥台是凹字形，用块石砌筑，前墙长约4.50米。跨径15.80米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '南平市顺昌县岚下乡岚下村', '木、块石', 50, 213, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2172, '兴隆桥', '兴隆桥是一座单孔撑架式木梁桥。桥面系是用3段圆木为纵梁，纵梁上横顺铺双层木桥面板，桥面宽5.00米，桥梁全长45.30米。桥上建木结构廊。桥台是用块石砌筑，其平面是凹字形，前墙长约5.00米。跨径20.00米。', '', 1, NULL, NULL, '', 8, 2, 10, 1, '南平市顺昌县谢屯村', '圆木、木桥面板、块石', 50, 214, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2173, '松溪五福桥', '五福桥俗称“八岭桥”。上部结构是在桥台上有3层圆木单悬臂梁，在桥墩上有3层圆木双悬臂梁，上面架设3层复合型圆木纵梁，纵梁上面横顺铺木桥面板。桥面宽5.20米，桥长108.00米。桥上建木结构廊。桥台是燕翅形，前墙长6.00米。桥墩上游端是尖形，下游端是方形。跨径均为11.00米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '福建省南平市松溪县渭田镇渭田村，跨渭田溪上', '石（墩台）、圆木（悬臂梁、纵梁）、木（桥面板、廊）', 50, 215, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2174, '中峰桥', '桥面是用3层圆木为纵梁，每层10根圆杉木纵梁，纵梁之间有12根杉木横梁，纵梁上面，横顺铺木桥面板。桥面宽4.50米，桥长11.00米。桥上建木结构廊。桥台用石板砌筑，燕翅形，前墙长5.50米，跨径8.50米。', '', 1, NULL, NULL, '', 7, 2, 7, 1, '南平市松溪县五里牌村，跨山涧小溪上', '圆杉木、石板', 50, 216, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2175, '交龙桥', '共有11根圆木纵梁，纵梁的下面中间部位各挂一根圆木辅梁。辅梁的两端各挂1根圆木横梁，横梁的外侧各设11对圆木斜撑，斜撑的下端置于桥台的中部。纵梁上面横顺铺木板而成桥面。桥面宽5.00米，桥长27.80米。桥上建木结构廊。桥台是凹字形，用块石砌筑，前墙长约5.00米。跨径14.50米。', '', 1, NULL, NULL, '', 8, 2, 10, 1, '南平市政和县澄源乡大梨溪村', '圆木、木板、块石', 50, 217, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2176, '龙滩桥', '龙滩桥是一座单孔撑架式木梁桥。共有11根圆木纵梁，纵梁的下面中间部位各挂一根圆木辅梁。辅梁的两端各挂1根圆木横梁，横梁的外侧各设11对圆木斜撑，斜撑的下端置于桥台的中部。纵梁上面横顺铺木板而成桥面。桥面宽5.00米，桥长31.00米。桥上建木结构廊。桥台建在山脚岩石上。跨径23.00米。', '', 1, NULL, NULL, '', 10, 2, 10, 1, '南平市政和县杨源乡龙滩村', '木材（圆木、木板）', 50, 218, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2177, '落岭桥', '落岭桥是一座单孔撑架式木梁桥。上部结构是圆木纵梁，纵梁下面中部挂两根圆木横梁。横梁下面挂4根辅梁，辅梁两端各有一对圆木斜撑。纵梁上面铺木桥面板，桥面宽4.30米，桥长40.50米。桥上建木结构廊。桥台建在山脚岩石上。跨径28.00米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '南平市政和县杨源乡上庄村', '木材（圆木、木桥面板）', 50, 219, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2178, '下坂桥', '下坂桥是一座单孔撑架式木梁桥。共有9根圆木纵梁，纵梁的下面中间部位各挂一根圆木辅梁。辅梁的两端各挂1根圆木横梁，横梁的外侧各设9对圆木斜撑，斜撑的下端置于桥台的中部。纵梁上面横顺铺木板而成桥面。桥面宽4.50米，桥长26.00米。桥上建木结构廊。桥台建在山脚岩石上。跨径21.00米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '南平市政和县杨源乡下坂村', '圆木、木板、木结构、岩石', 50, 220, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2179, '虎神桥', '虎神桥是一座单孔撑架式木梁桥。上部结构是圆木纵梁，纵梁下面中部有2根圆木横梁，横梁下面有圆木辅梁，辅梁两端各有一对圆木斜撑。纵梁上面铺木桥面板。桥面宽4.50米，桥长19.50米。桥上建砖木结构廊。桥台与块石砌筑的河岸为一体。跨径16.00米。', '', 1, NULL, NULL, '', 8, 2, 10, 1, '福安市潭头镇棠溪村', '圆木、木桥面板、砖木、块石', 50, 221, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2180, '积谷桥', '积谷桥是一座单孔石台撑架式木梁桥。共有11根圆木纵梁，纵梁的下面中间部位各挂一根圆木辅梁，辅梁的两端各挂1根圆木横梁。横梁的外侧各设11对圆木斜撑，斜撑的下端置于桥台的中部。纵梁上面横顺铺木板而成桥面，桥面宽5.00米，桥长20.00米。桥上建木结构廊。桥台是凹字形，用块石砌筑，前墙长约5.00米。跨径14.00米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '福安市康厝乡石尖村', '圆木、木板、块石', 50, 222, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2181, '乐善桥', '乐善桥是一座单孔撑架式木梁桥。上部结构是圆木纵梁，纵梁下面中部有两根圆木横梁，横梁下面有圆木辅梁，辅梁两端各有一对圆木斜撑。纵梁上面铺木桥面板。桥面宽5.00米，桥长25.00米。桥台用料石砌筑，两侧与块石砌筑的河岸相连。跨径18.50米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '福安市潭头镇棠溪村', '圆木、木桥面板、料石、块石', 50, 223, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2182, '福安乐喜桥', '乐喜桥又名“乐仙桥”。该桥为单孔撑架式木梁桥，上部结构采用圆木纵梁，纵梁下方中部设有两根圆木横梁，横梁下方设有圆木辅梁，辅梁两端各有一对圆木斜撑。纵梁上方铺设木桥面板。桥面宽4.65米，桥长25.00米。桥上建有砖木结构的廊屋。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '福安市潭头镇棠溪村', '圆木、木材、砖木', 50, 224, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2183, '奈何桥', '奈何桥是一座双孔悬臂式木梁桥。上部结构是双层6根圆木叠合纵梁，纵梁上面铺双层木桥面板。桥面宽5.10米，桥长29.50米。桥上建砖木结构廊。桥台是用块石砌筑，为凹字形。桥墩两端是方形，桥墩厚约1.80米，桥墩长5.50米。跨径均为13.60米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '福安市晓阳镇奈何村，跨凤过溪上', '圆木、木桥面板、砖、木、块石', 50, 225, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2184, '洋坑桥', '洋坑桥是一座单孔撑架式木梁桥。上部结构是圆木纵梁，下面是10对圆木斜撑，承托10根辅梁。辅梁上面架设圆木纵梁，纵梁上面横铺单层木桥面板。桥面宽4.80米，桥长24.00米。桥上建木结构廊。桥台建在山脚基岩上，形式不规则。跨径17.40米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '福安市范坑乡上坪村，跨洋坑溪上', '圆木、木材', 50, 226, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2185, '柘头桥', '共有9根圆木纵梁，纵梁的下面中间部位各挂1根圆木辅梁，辅梁的两端各挂1根圆木横梁，横梁的外侧各设9对圆木斜撑，斜撑的下端置于桥台的中部。纵梁上面横顺铺木板而成桥面。桥面宽4.40米，桥面长17.50米。桥上建木结构廊。桥台是凹字形，用块石砌筑，前墙长约4.50米。跨径16.00米。', '', 1, NULL, NULL, '', 10, 2, 10, 1, '福安市潭头镇柘头村，跨排水沟上', '圆木、木板、块石', 50, 227, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2186, '古田沉字桥', '沉字桥是一座5孔等跨径石墩台悬臂式木梁桥。桥面的结构是在桥台上有3层圆木单悬臂梁，在桥墩上有3层圆木双悬臂梁，上面架设圆木纵梁，梁上横顺铺木桥面板构成桥面系。桥面宽4.50米，桥长56.90米。桥上建木结构廊。桥台是燕翅形，前墙长约5.70米。桥墩两端是尖形，用石板砌筑，桥墩厚1.75米，桥墩长6.70米，跨径均为9.00米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '福建省宁德市古田县鹤塘镇西洋村，跨西洋溪上', '石材（墩台、桥墩）、圆木（悬臂梁、纵梁）、木材（桥面板、廊）', 50, 228, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2187, '吉口桥', '吉口桥是一座单孔石台悬臂式木梁桥。上部结构是圆木纵梁，纵梁下面两端各有3层圆木悬臂梁，悬臂梁之间有方木横系杆件。纵梁上面铺木桥面板，桥面宽5.20米，桥长24.00米。桥上建砖木结构廊。桥台建在山脚岩石上。跨径18.60米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '宁德市古田县吉巷乡吉巷村', '圆木、方木、木材、砖、石材', 50, 229, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2188, '沈字桥', '上部结构是双层圆木纵梁，纵梁下面两端各有3层圆木悬臂梁，悬臂梁之间有方木横系杆件。纵梁上面铺木桥面板，桥面宽5.20米，桥长54.00米。桥上建砖木结构廊。桥台建在山脚岩石上。中3孔跨径8.50米，边孔跨径6.50米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '宁德市古田县鹤塘镇西洋村', '石（墩台）、圆木（纵梁、悬臂梁）、方木（横系杆件）、木（桥面板）、砖木（廊）', 50, 230, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2189, '树荫桥', '共有8根圆木纵梁，纵梁的下面中间部位各挂一根圆木辅梁，辅梁的两端各挂1根圆木横梁，横梁的外侧各设8对圆木斜撑，斜撑的下端置于桥台的中部。纵梁上面横顺铺木板而成桥面。桥面宽4.20米，桥长29.90米。桥上建木结构廊。桥台是凹字形，用块石砌筑，前墙长约4.50米。跨径16.10米。', '', 1, NULL, NULL, '', 7, 2, 7, 1, '宁德市古田县卓洋乡树兜村', '圆木（纵梁、辅梁、横梁、斜撑）、木板（桥面）、块石（桥台）', 50, 231, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2190, '古田下地水尾桥', '上部结构是圆木纵梁，纵梁下面两端各有两层圆木悬臂梁，悬臂梁之间有方木横系杆件。纵梁上面铺木桥面板。桥面宽3.70米，桥长27.30米。桥上建砖木结构廊。桥台建在山脚岩石上。跨径9.50米。', '', 1, NULL, NULL, '', 8, 2, 10, 1, '宁德市古田县卓洋乡下地村', '石、圆木、方木、砖木', 50, 232, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
