INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2193, '广福桥', '广福桥是一座单孔撑架式木梁桥。上部结构是10根圆木纵梁，纵梁下面中部有4根横梁，横梁下面有4根较长辅梁，有4根较短辅梁，辅梁两端各有一对圆木斜撑。纵梁上面铺双层木桥面板。桥面宽5.00米，桥长32.00米。桥上建砖木结构廊。桥台是凹字形，用块石砌筑，前墙长约5.00米。跨径10.50米。', '', 1, NULL, NULL, '', 8, 2, 6, 1, '宁德市屏南县岭下乡岭下村', '圆木、木桥面板、砖木、块石', 50, 235, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
