INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2196, '聚宝桥', '聚宝桥是一座单孔撑架式木梁桥。上部结构是11根圆木纵梁，在纵梁下面中部挂两根圆木横梁，横梁下面有6根辅梁，辅梁两端各有一对圆木斜撑。纵梁上面铺木桥面板。桥面宽6.00米，桥长28.00米。桥上建砖木结构廊。桥台用块石砌筑。跨径14.10米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '宁德市屏南县甘棠乡際下村', '圆木、木、砖、块石', 50, 238, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2197, '上仓桥', '上部结构圆木纵梁，纵梁下面中部有3根圆木横梁，横梁下面有5根圆木辅梁，辅梁两端各有一对圆木斜撑。纵梁上面铺木桥面板。桥面宽4.00米，桥长27.00米。桥上建砖木结构廊。桥台利用块石砌筑的河岸。跨径16.00米。', '', 1, NULL, NULL, '', 9, 2, 10, 1, '宁德市屏南县寿山乡上仓村', '圆木、木、砖、块石', 50, 239, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2198, '什锦桥', '什锦桥是一座单孔撑架式木梁桥。共有9根圆木纵梁，纵梁的下面中间部位各挂一根圆木辅梁，辅梁的两端各挂1根圆木横梁，横梁的外侧各设9对圆木斜撑，斜撑的下端置于桥台的中部。纵梁上面横顺铺木板而成桥面。桥面宽4.20米，桥长12.00米。桥上建木结构廊。桥台建在山脚岩石上。跨径6.00米。', '', 1, NULL, NULL, '', 10, 2, 10, 1, '宁德市屏南县什锦桥村', '木材（圆木、木板）', 50, 240, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2199, '屏南双龙桥', '桥长66米，两墩三孔。上部结构是圆木纵梁，纵梁的下面中间部位每隔1根纵梁挂1根圆木辅梁。辅梁的两端各挂1根圆木横梁，横梁的外侧各设一对圆木斜撑，斜撑的下端置于桥台的中部。纵梁上面横顺铺双层木桥面板。桥面宽4.50米，桥长66.00米。桥上建木结构廊。桥台在山脚岩壁上开凿出平台，桥墩两端是方形。跨径19.90米。', '', 1, NULL, NULL, '', 8, 2, 10, 1, '福建省宁德市屏南县白水洋景区（原在鸳鸯溪下游，重建于白水洋上/鸳鸯溪上游）', '木材（圆木纵梁、圆木辅梁、圆木横梁、圆木斜撑、双层木桥面板、木结构廊）', 50, 241, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2200, '万安桥', '万安桥是一座6孔撑架式木梁桥。上部结构是圆木纵梁，纵梁下面中部有2根圆木横梁，横梁下面有4根圆木辅梁，辅梁两端各有一对圆木斜撑。纵梁上面铺木桥面板。桥面宽4.70米，桥长98.20米。桥上建砖木结构廊。桥东南端有10级台阶，西北端有36级台阶。桥台用料石砌筑，是燕翅形。桥墩用料石砌筑，两端是尖形，桥墩厚2.00米，桥墩长6.90米。中4孔跨径15.20米，边孔跨径10.6米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '宁德市屏南县长桥镇长桥村跨龙江溪上', '圆木、木桥面板、砖木结构、料石', 50, 242, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2201, '屏南溪里桥', '溪里桥是一座单孔撑架式木梁桥。共有9根圆木纵梁，纵梁的下面中间部位各挂1根圆木辅梁。辅梁的两端各挂1根圆木横梁，横梁的外侧各设9对圆木斜撑，斜撑的下端置于桥台的中部。纵梁上面横顺铺木板而成桥面。桥面宽4.30米，桥长37.80米。桥上建木结构廊。桥台建在山脚岩石上。跨径20.00米。', '', 1, NULL, NULL, '', 10, 2, 10, 1, '宁德市屏南县溪里乡溪里村', '木材（圆木、木板）', 50, 243, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
