INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2209, '奖禄上桥', '奖禄上桥是一座单孔撑架式木梁桥。上部结构是密排圆木纵梁，纵梁下面中部挂2根圆木横梁，横梁下面挂3根辅梁，辅梁两端各有1根圆木斜撑。纵梁上面铺木桥面板，桥面宽4.10米，桥长31.00米。桥上建砖木结构廊。桥台建在山脚岩石上。拱跨12.00米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '宁德市寿宁县斜滩镇奖禄村', '圆木、木、砖木', 50, 251, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
