INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2211, '奶殿桥', '奶殿桥是一座单孔撑架式木梁桥。上部结构是密排11根圆木纵梁，每隔1根(共5根)纵梁下面中部各挂1根圆木辅梁，辅梁两端有1根圆木横梁，横梁外侧有一对圆木斜撑。纵梁上面铺木桥面板，桥面宽5.00米，桥长34.00米。桥上建砖木结构廊。桥台用块石砌筑，两侧与块石砌筑的河岸相连。跨径16.60米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '寿宁县平溪乡柯洋村', '圆木、木、砖、块石', 50, 253, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2212, '寿宁升平桥', '升平桥是一座单孔撑架式木梁桥。上部结构是11道圆木纵梁，纵梁中部下面各有1根圆木辅梁，辅梁两端各有一对圆木斜撑，斜撑的下端置于石砌桥台中部。纵梁上面横顺铺双层木桥面板。桥面宽5.60米，长25.50米。桥台与石板砌筑的河岸为一体。跨径23.40米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '宁德市寿宁县鳌阳镇跨街河上', '木材（圆木、木桥面板）、石材（石砌桥台、石板）', 50, 254, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2213, '升仙桥', '升仙桥是一座双孔木梁桥。南孔跨滨河路，是简支木梁桥，桥面宽 3.50米，南桥台用块石砌筑，是凹字形。跨径3.50米。北孔跨河道，是悬臂式木梁桥。上部结构是圆木纵梁，纵梁两端下面各有4层圆木悬臂梁，各层悬臂梁之间有方木横系杆件。纵梁上面铺木桥面板，桥面宽4.50米，桥梁全长19.00米。北桥台建在天然基石上。跨径12.50米。全桥上面建砖木结构廊。', '', 1, NULL, NULL, '', 8, 2, 10, 1, '宁德市寿宁县犀溪乡仙峰村', '圆木、方木、木桥面板、块石、砖木', 50, 255, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2214, '寿春桥 (又名“翁坑桥”)', '寿春桥是一座单孔撑架式木梁桥。上部结构是圆木纵梁，纵梁下面中部各挂1根圆木辅梁，辅梁两端各有一对圆木斜撑。纵梁上面铺木桥面板，桥面宽4.20米，桥长19.60米。桥上建砖木结构廊。桥台建在山脚岩石上。跨径12.40米。', '', 1, NULL, NULL, '', 8, 2, 10, 1, '宁德市寿宁县犀溪乡翁坑村', '圆木、砖木', 50, 256, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2215, '外洋垱桥', '外洋垱桥是一座单孔撑架式木梁桥。上部结构是圆木纵梁，纵梁下面中部各挂1根圆木辅梁，辅梁两端各有一对圆木斜撑。纵梁上面铺木桥面板，桥面3.80米，桥长19.00米。桥台用块石砌筑，大致是凹字形。跨径14.70米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '宁德市寿宁县南阳镇外洋垱村', '木、块石', 50, 257, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
