INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2220, '杨梅州桥', '杨梅州桥是一座单孔撑架式木梁桥。共有9道双层圆木纵梁，纵梁的下面中间部位各挂1根圆木辅梁。辅梁的两端各挂1根圆木横梁，横梁的外侧各有9根圆木斜撑，斜撑的下端置于桥台的下部。纵梁上面横顺铺木板而成桥面。桥面宽4.20米，桥长42.50米。桥上建砖木结构廊。桥台是凹字形，前墙长约4.50米。跨径35.70米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '宁德市寿宁县坑底乡杨梅州', '木材（圆木、木板）、砖木', 50, 262, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
