INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2223, '临清桥', '临清桥是一座单孔撑架式木梁桥。上部结构下面是6对圆木斜撑，承托6根辅梁。辅梁上面架设圆木纵梁，纵梁上面横铺单层木桥面板。桥面宽3.65米，桥长18.80米。桥上建木结构廊。桥台两侧有八字墙，前墙长约6.00米。跨径11.30米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '宁德市霞浦县盖竹村', '木材', 50, 265, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
