INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2228, '三仙桥', '三仙桥是一座单孔撑架式木梁桥。上部结构是圆木纵梁，纵梁的下面中间部位挂2根圆木横梁，横梁下面有6根辅梁，辅梁两端各有一对圆木斜撑。纵梁上面铺木桥面板。桥面宽5.40米，桥长18.40米。桥上建砖木结构廊。桥台与料石砌筑的河岸为一体。跨径15.00米。', '', 1, NULL, NULL, '', 9, 2, 10, 1, '宁德市周宁县纯池镇禾溪村', '圆木、木材、砖木、料石', 50, 270, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2229, '竹龄桥', '共有13根圆木纵梁，纵梁的下面中间部位各挂1根圆木辅梁。辅梁的两端各挂1根圆木横梁，横梁的外侧各设13对圆木斜撑，斜撑的下端置于桥台的中部。纵梁上面横顺铺木板而成桥面。桥面宽4.50米，桥长34.60米。桥上建木结构廊。桥台是凹字形，用块石砌筑，前墙长约5.50米。跨径24.70米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '宁德市周宁县泗桥乡竹村', '圆木、木板、块石', 50, 271, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2230, '安溪瑞云桥', '瑞云桥是一座单孔简支木梁桥。上部结构是圆木纵梁，纵梁上面铺木桥面板。桥面宽5.10米，桥长14.70米。桥上建砖木结构廊。桥台利用块石砌筑的河岸。跨径8.70米。', '', 1, NULL, NULL, '', 7, 2, 7, 1, '泉州市安溪县蓝田乡进德村，跨进德溪上', '圆木（纵梁）、木（桥面板）、砖木（廊）、块石（桥台）', 50, 272, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2231, '德化长寿桥', '长寿桥是一座单孔撑架式木梁桥。共有7根圆木纵梁，纵梁的下面中间部位各挂1根圆木辅梁。辅梁的两端各挂1根圆木横梁，横梁的外侧各设7对圆木斜撑，斜撑的下端置于桥台的中部。纵梁上面横顺铺木板而成桥面。桥面宽3.50米，桥长26.40米。桥上建木结构廊。桥台建在山脚岩石上。跨径20.50米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '泉州市德化县上涌乡增坂村', '木材（圆木、木板）、岩石（桥台）', 50, 273, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2232, '德化登龙桥', '德化登龙桥是一座3孔等跨径石墩台木梁桥。上部结构是15根圆杉木纵梁，纵梁下面两端各有6层圆木悬臂梁，各层悬臂梁之间各有6根圆木横垫梁。纵梁上面铺双层木桥面板，桥面宽3.85米，桥梁全长50.40米。桥上建砖木结构廊。桥台是凹字形。桥墩两端是方形。中孔跨径13.50米。边孔跨径11.00米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '泉州市德化县浔中镇蒲坂村', '石（墩台）、圆杉木（梁）、木（桥面板）、砖木（廊）', 50, 274, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2233, '德化广济桥', '广济桥是一座单孔石台复合型简支木梁桥。上部结构是用3层圆木为纵梁，纵梁上面横顺铺木桥面板，桥面宽5.50米，桥长24.00米。桥上建木结构廊。桥台是凹字形，用料石砌筑，前墙长5.50米。跨径12.50米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '泉州市德化县双翰村，跨山涧上', '圆木（纵梁）、木桥面板、料石（桥台）', 50, 275, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2234, '德化宴林口桥', '宴林口桥是一座双孔石墩台简支木梁桥。上部结构是圆木纵梁，纵梁上面铺木桥面板。桥面宽3.40米，桥长27.30米。桥上建砖木结构廊。桥台建在山脚岩石上。桥墩两端是尖形。跨径均为7.50米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '泉州市德化县盖德乡林地村', '石（墩台）、圆木（纵梁）、木（桥面板）、砖木（廊）', 50, 276, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2235, '永春东关桥（通仙桥）', '东关桥是一座5孔石墩台悬臂式木梁桥。上部结构是双层圆木叠合纵梁，纵梁之间有横系杆，梁上横顺铺双层木桥面板。桥面宽5.00米，桥长85.00米。桥上建砖木结构廊。桥台是用料石砌筑，桥墩上游端是尖形，下游端是方形，桥墩顶端厚2.50米，跨径均为12.00米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '泉州市永春县东关镇东美村，跨湖洋溪上', '料石（桥台、桥墩）、圆木（纵梁）、木（桥面板）、砖木（廊）', 50, 277, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2236, '宜生桥', '宜生桥是一座5孔石墩台悬臂式木梁桥。上部结构是，桥台上是3层圆木单悬臂梁，桥墩上是3层圆木双悬臂梁，上面架设单层圆木纵梁，纵梁上面横顺铺木桥面板。桥面宽4.60米，桥长58.00米。桥上建木结构廊。桥台带燕翅形，建在山脚下，用方形条石横顺相间砌筑，前墙长4.60米。桥墩也是用方形条石横顺相间砌筑，上游端是尖形，下游端是方形。跨径均为13.50米。', '', 1, NULL, NULL, '', 8, 2, 8, 1, '三明市宁化县滑石村', '圆木、方形条石', 50, 278, '2026-04-28 23:07:57', '2026-04-28 23:36:25');
INSERT INTO `bridge` (`id`, `name`, `description`, `level`, `province_id`, `lng`, `lat`, `image`, `age`, `typeid`, `period_id`, `status`, `area`, `material`, `hotScore`, `hot_score`, `create_time`, `update_time`) VALUES (2237, '沙县百花桥', '百花桥是一座单孔撑架式木梁桥。上部结构是圆木纵梁，纵梁上面铺木桥面板。桥面宽2.80米，桥长7.50米。桥上建砖木结构廊。桥台建在山脚岩石上。跨径4.00米。', '', 1, NULL, NULL, '', 10, 2, 10, 1, '福建省三明市沙县夏茂镇洋元村', '圆木、木材、砖', 50, 279, '2026-04-28 23:07:57', '2026-04-28 23:36:26');
